@extra("draw.io: a bezel is its own tagged shape, over a face drawn without it")
def check_drawio_covers(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/index.html", wait_until="load")
    r = page.evaluate("""async () => {
      const F = await import('/site/rack/face.js');
      const D = await import('/vendor/drawio.js');
      const svgOf = cell => {
        const b64 = cell.getAttribute('style').split('image=data:image/svg+xml,')[1].split(';')[0];
        return new TextDecoder().decode(Uint8Array.from(atob(b64), c => c.charCodeAt(0)));
      };
      const cellsOf = async (ref, cfg) => {
        const f = await F.configuredFace({ref, cfg, view: 'front'});
        const xml = D.deviceCells('dev', f.text, f.vb, f.ports, 0, 0, 400, 80).join('');
        return {xml, doc: new DOMParser().parseFromString(`<root>${xml}</root>`, 'application/xml')};
      };
      const {xml, doc} = await cellsOf('r740xd', 'sff24-rc5-1b2a3a');
      const face = doc.querySelector('mxCell[id="dev-face"]');
      const cover = doc.querySelector('object[portrayal-cover="bezel"]');
      const coverSvg = cover ? svgOf(cover.querySelector('mxCell')) : '';
      const plain = await cellsOf('as7726-32x', 'ac-f2b');
      // The rear has plates classed `bezel` inside parts that do not come off
      // (riser shrouds, trims): none of them is a cover.
      const rearF = await F.configuredFace({ref: 'r740xd', cfg: 'sff24-rc5-1b2a3a', view: 'rear'});
      const rearXml = D.deviceCells('dev', rearF.text, rearF.vb, rearF.ports, 0, 0, 400, 80).join('');
      return {
        parses: !doc.querySelector('parsererror'),
        faceHasBezel: svgOf(face).includes('data-class="bezel"'),
        faceHasDrive: svgOf(face).includes('id="drive-0"'),
        cover: !!cover,
        tags: cover?.getAttribute('tags') || '',
        parent: cover?.querySelector('mxCell')?.getAttribute('parent') || '',
        coverHasBezel: coverSvg.includes('id="bezel"'),
        coverHasDrive: coverSvg.includes('id="drive-0"'),
        coverBelowPorts: cover ? xml.indexOf('portrayal-cover=') < xml.indexOf('portrayal-path=') : false,
        plainCovers: plain.doc.querySelectorAll('object[portrayal-cover]').length,
        rearCovers: (rearXml.match(/portrayal-cover=/g) || []).length,
      };
    }""")
    expect = {"parses": True, "faceHasBezel": False, "faceHasDrive": True, "cover": True,
              "parent": "dev", "coverHasBezel": True, "coverHasDrive": False,
              "coverBelowPorts": True, "plainCovers": 0, "rearCovers": 0}
    for k, want in expect.items():
        if r.get(k) != want:
            bad.append(f"draw.io covers: {k} is {r.get(k)!r}, expected {want!r}")
    # ONE tag: draw.io hides a cell only when every tag on it is hidden.
    if r.get("tags") != "bezel":
        bad.append(f"draw.io covers: tags are {r.get('tags')!r}, expected 'bezel'")
    return bad


@extra("draw.io: a group may name its own faces, a device its own id, a rack its numbering - defaults unchanged")
def check_drawio_group_faces(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/index.html", wait_until="load")
    r = page.evaluate("""async () => {
      const D = await import('/vendor/drawio.js');
      const F = await import('/site/rack/face.js');
      const f = await F.configuredFace({ref: 'tm-280', cfg: 'base', view: 'front'});
      const b = await F.configuredFace({ref: 'tm-280', cfg: 'base', view: 'rear'});
      const face = x => ({svg: x.text, vb: x.vb, ports: x.ports});
      const mk = (extra = {}, m = {}) => [{label: 'P', ...extra, racks: [{label: 'R', units: 4,
        mounted: [{name: 'TM', u: 2, ru: 1, faces: {front: face(f), rear: face(b)}, ...m}]}]}];
      const a = D.rackDiagram(mk(), {faces: ['front', 'rear']});
      return {
        same: a === D.rackDiagram(mk({faces: ['front', 'rear']}), {faces: ['front']}),
        rearOnly: (x => !x.includes('value="R · front"') && x.includes('value="R · rear"'))(
          D.rackDiagram(mk({faces: ['rear']}), {faces: ['front', 'rear']})),
        nameIds: a.includes('id="TM-g0r0-front"'),
        ownIds: (x => x.includes('id="i7-g0r0-front"') && !x.includes('id="TM-g0r0-front"'))(
          D.rackDiagram(mk({}, {id: 'i7'}))),
        ascend: a.includes('numDisp=ascend;'),
        descend: D.rackDiagram([{label: 'P', racks: [{label: 'R', units: 4, numDisp: 'descend', mounted: []}]}])
          .includes('numDisp=descend;'),
      };
    }""")
    for k in ("same", "rearOnly", "nameIds", "ownIds", "ascend", "descend"):
        if not r.get(k):
            bad.append(f"rackDiagram: {k} is {r.get(k)!r}")
    return bad


# One draw.io page, read: its cabinets by cell id, what each one holds (the
# values of the cells whose parent it is), every id, and the edges.
def drawio_page(text):
    root = ET.fromstring(text)
    pages = root.findall("diagram")
    page = pages[0] if pages else None
    cells = list(page.iter("mxCell")) if page is not None else []
    geo = lambda c: c.find("mxGeometry")
    cabinets = {c.get("id"): {"value": c.get("value"), "x": float(geo(c).get("x")),
                              "holds": [k.get("value") for k in cells if k.get("parent") == c.get("id")]}
                for c in cells if re.fullmatch(r"g0r\d+-front", c.get("id") or "")}
    return {"names": [d.get("name") for d in pages], "cabinets": cabinets,
            "ids": [e.get("id") for e in (page.iter() if page is not None else []) if e.get("id")],
            "edges": [o for o in (page.iter("object") if page is not None else [])
                      if o.find("mxCell") is not None and o.find("mxCell").get("edge") == "1"]}


@extra("rack.html: Export - draw.io is one page with a front and a rear cabinet, only what shows from each side, and a seated card's ports")
def check_rack_export_drawio(page, base):
    from collections import Counter
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)
    dl = export_file(page, "drawio")
    if dl.suggested_filename != "Export-test.drawio":
        bad.append(f"draw.io: named {dl.suggested_filename!r}")
    text = pathlib.Path(dl.path()).read_text(encoding="utf-8")
    try:
        d = drawio_page(text)
    except ET.ParseError as e:
        return bad + [f"draw.io: not well-formed XML ({e})"]
    # ONE page, named for the rack: the rear is beside the front, not on a second tab.
    if d["names"] != ["Export test"]:
        return bad + [f"draw.io: pages {d['names']}, expected the one page 'Export test'"]
    cab = d["cabinets"]
    if {k: v["value"] for k, v in cab.items()} != {"g0r0-front": "Export test · front", "g0r1-front": "Export test · rear"}:
        return bad + [f"draw.io: cabinets {[(k, v['value']) for k, v in cab.items()]}, expected a front and a rear"]
    front, rear = cab["g0r0-front"], cab["g0r1-front"]
    # Side by side: the vendor's cabinet is 180 wide, and racks stand 190 apart.
    if (front["x"], rear["x"]) != (0.0, 370.0):
        bad.append(f"draw.io: the cabinets are at x {front['x']} and {rear['x']}, expected 0 and 370")
    dup = [i for i, c in Counter(d["ids"]).items() if c > 1]
    if dup:
        bad.append(f"draw.io: duplicate cell ids {dup[:5]}")
    if front["holds"].count("demarc") != 1:
        bad.append("draw.io front cabinet: expected one demarc (U20's, from behind); U14's is behind leaf-1")
    if "leaf-1" not in front["holds"] or "core-1" not in front["holds"]:
        bad.append(f"draw.io front cabinet: holds {front['holds']}")
    if "leaf-1" in rear["holds"]:
        bad.append("draw.io rear cabinet: leaf-1 is drawn, but demarc is mounted in front of it there")
    if rear["holds"].count("demarc") != 2 or "core-1" not in rear["holds"]:
        bad.append("draw.io rear cabinet: expected both demarcs and core-1's rear")
    # A rear cabinet entry has an id of its own, so its cells never collide with the front's.
    if "i1-g0r0-front" not in d["ids"] or "i1-rear-g0r1-front" not in d["ids"] or "i3-rear-g0r1-front" not in d["ids"]:
        bad.append("draw.io: core-1 is not in both cabinets under ids of its own, or the rear demarc is missing")
    card = [o for o in ET.fromstring(text).iter("object") if o.get("portrayal-path") == "slot-2/module/p0"]
    if [o.get("id") for o in card] != ["i1-g0r0-front-slot-2--module--p0"]:
        bad.append(f"draw.io front cabinet: the seated card's port cell is {[o.get('id') for o in card]}")
    if "numDisp=descend;" not in text:
        bad.append("draw.io: a bottom-up rack is not numbered from the bottom")
    if "Front cabinet: demarc is behind leaf-1 and is not drawn there." not in text:
        bad.append("draw.io: the notes comment does not list the device hidden behind leaf-1")
    if not text.startswith('<mxfile host="portrayal"><!--') or text.count("<!--") != 1:
        bad.append(f"draw.io: the notes are not one comment inside <mxfile>: {text[:80]!r}")
    # A rack with no cables: no edge, and no word about cables.
    if d["edges"] or "cable" in text.partition("-->")[0].lower():
        bad.append(f"draw.io: a rack with no cables has {len(d['edges'])} edges or a cable note")
    if "@rear" in text.partition("-->")[0]:
        bad.append("draw.io: an id made for the rear cabinet is in the notes a person reads")

    # draw.io reads a label as HTML (html=1): a name with & and < must reach it
    # HTML-escaped, or the tag-like part is dropped from what it shows.
    got = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js');
      const r = window.__rack.doc().racks[0];
      const rack = {...r, name: 'R&D <core>', items: r.items.filter(i => i.id === 'i2').map(i => ({...i, label: 'a<b>&c'}))};
      const out = await X.drawioFile(rack, () => ({ru: 1}));
      const doc = new DOMParser().parseFromString(out.data, 'application/xml');
      const shown = v => { const d = document.createElement('div'); d.innerHTML = v; return d.textContent; };
      const values = [...doc.querySelectorAll('[value]')].map(e => e.getAttribute('value')).filter(Boolean);
      const blank = await X.drawioFile({...rack, name: ''}, () => ({ru: 1}));
      return {name: out.name, error: doc.querySelector('parsererror')?.textContent || '',
              page: doc.querySelector('diagram')?.getAttribute('name'), values, shown: values.map(shown),
              blank: [...blank.data.matchAll(/id="g0r\\d-front" value="([^"]*)"/g)].map(m => m[1]),
              blankPage: blank.data.match(/<diagram name="([^"]*)"/)?.[1]};
    }""")
    if got["error"]:
        bad.append(f"draw.io labels: not well-formed XML ({got['error'][:120]})")
    if got["name"] != "R-D-core.drawio":
        bad.append(f"draw.io labels: named {got['name']!r}")
    for want in ("R&D <core> · front", "R&D <core> · rear", "a<b>&c", "▲ a<b>&c"):
        if want not in got["shown"]:
            bad.append(f"draw.io labels: draw.io would not show {want!r}; it shows {sorted(set(got['shown']))}")
    for want in ("R&amp;D &lt;core&gt; · front", "R&amp;D &lt;core&gt; · rear"):
        if want not in got["values"]:
            bad.append(f"draw.io labels: a cabinet's value is not HTML-escaped ({want!r}): {sorted(set(got['values']))}")
    # The page's name is an attribute, not a label: it is the rack's name as typed.
    if got["page"] != "R&D <core>":
        bad.append(f"draw.io labels: the page is named {got['page']!r}")
    # A rack with no name still gets a front and a rear cabinet, and a page with a name.
    if got["blank"] != ["front", "rear"] or got["blankPage"] != "Rack":
        bad.append(f"draw.io labels: a nameless rack's cabinets read {got['blank']} on page {got['blankPage']!r}")
    return bad


@extra("rack.html: Export - 2D offers a switch to 3D; GLB and USDZ name every device and carry the notes")
def check_rack_export_3d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)
    page.click('#mode [data-mode="2d"]')
    page.click("#exportMenu > summary")
    page.wait_for_selector('#exportItems [data-export="to-3d"]', timeout=READY_MS)
    if page.query_selector('#exportItems [data-export="glb"]'):
        bad.append("3D export: 2D offers GLB, which only a 3D scene can make")
    page.click('#exportItems [data-export="to-3d"]')
    settle_scene(page, "3D export: the scene")
    dl = export_file(page, "glb", timeout=READY_3D_MS)
    glb = pathlib.Path(dl.path()).read_bytes()
    if dl.suggested_filename != "Export-test.glb" or glb[:4] != b"glTF":
        bad.append(f"GLB: {dl.suggested_filename!r} is not a GLB")
    missing = [i for i in ("i1", "i2", "i3", "i4") if f'"device-{i}"'.encode() not in glb]
    if missing:
        bad.append(f"GLB: no node for device(s) {missing}")
    if b"Optic labels and colors are not in the 3D model yet: leaf-1." not in glb:
        bad.append("GLB: the notes are not in the scene's extras")
    status = page.inner_text("#exportStatus")
    if status != "Downloaded, with 1 note in the file.":
        bad.append(f"GLB: the status reads {status!r}")
    dl = export_file(page, "usdz", timeout=READY_3D_MS)
    usdz = pathlib.Path(dl.path()).read_bytes()
    if dl.suggested_filename != "Export-test.usdz" or usdz[:2] != b"PK":
        bad.append(f"USDZ: {dl.suggested_filename!r} is not a USDZ")
    else:
        with zipfile.ZipFile(io.BytesIO(usdz)) as z:
            if not any(n.lower().endswith((".usdc", ".usda", ".usd")) for n in z.namelist()):
                bad.append(f"USDZ: no USD entry in the archive: {z.namelist()}")
    # A USDZ has nowhere to put the notes, so the status must not say they are in it.
    status = page.inner_text("#exportStatus")
    if status != "Downloaded. USDZ carries no notes; the GLB does.":
        bad.append(f"USDZ: the status reads {status!r}")
    # The exporters pause the render loop (their texture encoding crawls behind
    # a frame of the rack otherwise); the view must be drawing again after.
    if not page.evaluate("() => window.__rack.scene().running()"):
        bad.append("3D export: the render loop was left paused after an export")
    page.click('#mode [data-mode="2d"]')
    return bad


# THE TOOL PAGES FIT A PHONE. At 360px explorer.html scrolled sideways by 6px,
# annotate.html by 287px and components.html by 2645px. Not the tool bar: the
# shell's 23rem side panel (and the Annotator's second one) would not shrink
# below its nowrap tree rows, and a component card would not shrink below its
# monospace title or its true-scale drawing. The Explorer fit at 375px, which
# is why nobody saw it.
NARROW_PAGES = ["explorer.html", "components.html", "annotate.html", "drawio.html",
                "exporter.html", "drawings.html"]


@extra("the tool-bar pages fit a 360px viewport: no sideways scroll, the bar holds its links, menus open on screen")
def check_narrow_tool_pages(page, base):
    bad = []
    page.set_viewport_size({"width": 360, "height": 740})
    for name in NARROW_PAGES:
        page.goto(f"{base}/{name}", wait_until="load")
        page.wait_for_timeout(1500)
        r = page.evaluate(r"""() => {
          const w = document.documentElement.scrollWidth;
          // Name the widest culprits, so a failure says where to look.
          const wide = [...document.querySelectorAll('body *')]
            .filter(e => e.getBoundingClientRect().right > 360.5)
            .slice(0, 4)
            .map(e => e.tagName.toLowerCase() + (e.id ? '#' + e.id : '')
                      + (e.className && typeof e.className === 'string'
                         ? '.' + e.className.trim().split(/\s+/).join('.') : '')
                      + ' right=' + Math.round(e.getBoundingClientRect().right));
          // The bar's links wrap onto a second row on a phone; a bar of fixed
          // height let that row hang over the page's heading.
          const bar = document.querySelector('.site-bar');
          const bottom = bar ? bar.getBoundingClientRect().bottom : 0;
          const spill = bar ? [...bar.querySelectorAll('a, summary')]
            .filter(e => !e.closest('.navmenu-items'))
            .filter(e => e.getBoundingClientRect().bottom > bottom + 0.5)
            .map(e => e.textContent.trim()) : [];
          return {w, wide, spill};
        }""")
        if r["w"] > 360:
            bad.append(f"{name}: scrollWidth {r['w']} at a 360px viewport; past the edge: "
                       + ", ".join(r["wide"]))
        if r["spill"]:
            bad.append(f"{name}: at 360px the tool bar's links hang below the bar, over the page: "
                       + ", ".join(r["spill"]))
        # Each menu in the bar opens on screen. Export starts a row of its own
        # on a phone, and a panel hung from its right edge opened off the left.
        for i in range(page.locator(".site-bar .navmenu > summary").count()):
            summary = page.locator(".site-bar .navmenu > summary").nth(i)
            label = summary.inner_text().strip()
            summary.click()
            box = page.evaluate("""i => {
              const m = document.querySelectorAll('.site-bar .navmenu')[i];
              const r = m.querySelector('.navmenu-items').getBoundingClientRect();
              m.open = false;
              return [Math.round(r.left), Math.round(r.right)];
            }""", i)
            if box[0] < 0 or box[1] > 360:
                bad.append(f"{name}: at 360px the {label} menu opens off screen, "
                           f"from x={box[0]} to x={box[1]}")
    return bad


@extra("rack.html: a 42U four-post rack on first open, frame edits redraw and survive a reload")
def check_rack_page(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    counts = lambda: page.evaluate("""() => ['front', 'rear'].map(f =>
      document.querySelectorAll(`svg[data-pane="${f}"] rect.rk-u`).length)""")
    if counts() != [42, 42]:
        bad.append(f"rack page: U targets {counts()}, expected [42, 42]")
    page.click("#frameBtn")
    page.fill("#fHeight", "24")
    page.dispatch_event("#fHeight", "change")
    # The side panel is redrawn after each change: wait for it, then the next control.
    page.wait_for_function("""() => document.querySelectorAll('svg[data-pane="front"] rect.rk-u').length === 24""",
                           timeout=READY_MS)
    page.select_option("#fHoles", "tapped")
    page.wait_for_function("""() => document.querySelector('svg[data-pane="front"] circle[data-rail-hole]')""",
                           timeout=READY_MS)
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    if counts() != [24, 24]:
        bad.append(f"rack page: after reload U targets {counts()}, expected [24, 24]")
    if not page.query_selector('svg[data-pane="rear"] circle[data-rail-hole]'):
        bad.append("rack page: tapped holes did not survive the reload")
    if page.get_attribute('.site-bar a[href="rack.html"]', "aria-current") != "page":
        bad.append("rack page: the nav does not mark Rack Builder as the current page")
    # The two panes' headings are single-line ("Front" / "Rear"); the frame
    # summary that used to wrap the front heading onto two lines - starting
    # its SVG lower than the rear one's - now lives in the top bar instead.
    front_top = page.eval_on_selector('svg[data-pane="front"]', "s => s.getBoundingClientRect().top")
    rear_top = page.eval_on_selector('svg[data-pane="rear"]', "s => s.getBoundingClientRect().top")
    if abs(front_top - rear_top) > 1:
        bad.append(f"rack page: the two panes' SVGs start at different top edges ({front_top} vs {rear_top})")
    return bad


def pick(page, face, u, query, ref, cfg=None, dispatch=False):
    sel = f'svg[data-pane="{face}"] rect.rk-u[data-u="{u}"]'
    # A `through` panel can visually cover a free U's own hit rectangle (round
    # 3 §2's half-depth case) without blocking a real click - onPaneClick
    # routes a click there itself - but a real, position-based Playwright
    # click still refuses to act on an element another one visually covers,
    # so callers that know the U is covered dispatch straight to the rect,
    # the same target the app's own click handler reads ev.target from (this
    # mirrors check_rack_inspect's identical workaround for a mounted panel).
    if dispatch:
        page.dispatch_event(sel, "click")
    else:
        page.click(sel)
    page.fill("#catQuery", query)
    page.select_option("#catDevice", ref)
    if cfg:
        page.select_option("#catCfg", cfg)
    page.click("#catPlace")


# THE EXPORT FIXTURE: a 24U four-post rack holding the cases every export
# has to get right - a seated card (core-1's slot-2), an optic with a label
# (leaf-1's port-1), a U shared front and rear (U14), and two devices with
# the same label (demarc).
EXPORT_FIXTURE = {
    "format": "portrayal-rack", "version": 1, "id": "doc-export-fixture",
    "racks": [{
        "id": "r1", "name": "Export test",
        "frame": {"kind": "four-post", "heightRU": 24, "numbering": "bottom-up",
                  "holes": {"style": "square", "thread": None},
                  "railDepth": 740, "usableDepth": 1000, "ref": None},
        "items": [
            {"id": "i1", "ref": "asr-9006", "cfg": "base", "label": "core-1", "ru": 2, "face": "front",
             "turned": False, "swaps": {"slot-2": "cisco/a9k-16x100ge-tr@1"}, "fields": {}},
            {"id": "i2", "ref": "as7726-32x", "cfg": "ac-f2b", "label": "leaf-1", "ru": 14, "face": "front",
             "turned": False, "swaps": {"port-1": "generic/qsfp-lc@2"},
             "fields": {"port-1-occupant": {"label": "LR4"}}},
            {"id": "i3", "ref": "tm-280", "cfg": "base", "label": "demarc", "ru": 14, "face": "rear",
             "turned": False, "swaps": {}, "fields": {}},
            {"id": "i4", "ref": "tm-280", "cfg": "base", "label": "demarc", "ru": 20, "face": "rear",
             "turned": False, "swaps": {}, "fields": {}},
        ],
        "zeroU": [], "cables": []}]}


def open_fixture(page, base, fixture=EXPORT_FIXTURE):
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    rack = fixture["racks"][0]
    # The reload reopens the library's last rack - in a check that opens a
    # fixture twice, the SAME fixture under the same name, drawn with the same
    # devices. Its first draw can land before the file is read and stored
    # (under load, the file's way into the library is the slow part), and then
    # every wait below is met by the rack that was there before. So the panes
    # are watched from here on, and the wait is for a draw made while the
    # opened document - a fresh id, as an opened file always gets - is the
    # page's: once it is, no draw of the old one can land (it is superseded).
    page.evaluate("""() => {
      const was = window.__rack.doc().id;
      window.__openedDrawn = false;
      new MutationObserver((_, o) => {
        if (window.__rack.doc().id !== was) { window.__openedDrawn = true; o.disconnect(); }
      }).observe(document.getElementById('paneFront'), {childList: true});
    }""")
    page.set_input_files("#openFile", files=[{"name": "fixture.rack.json", "mimeType": "application/json",
                                              "buffer": json.dumps(fixture).encode()}])
    page.wait_for_function("(n) => window.__rack.doc().racks[0].name === n", arg=rack["name"], timeout=READY_MS)
    page.wait_for_function("() => window.__openedDrawn", timeout=READY_MS)
    page.wait_for_function(
        """(n) => document.querySelectorAll('svg[data-pane="front"] [data-item-id][data-panel]').length >= n""",
        arg=len(rack["items"]), timeout=READY_MS)


def export_file(page, kind, timeout=READY_MS):
    page.click("#exportMenu > summary")
    with page.expect_download(timeout=timeout) as dl:
        page.click(f'#exportItems [data-export="{kind}"]')
    return dl.value


def export_kit(page, target):
    """An import kit as the Export menu downloads it: the download, and what
    kit_rows and readme_lists read - {"names": entries in order, "zip": {entry: text}}."""
    dl = export_file(page, f"{target}-import")
    with zipfile.ZipFile(dl.path()) as z:
        names = z.namelist()
        return dl, {"names": names, "zip": {n: z.read(n).decode("utf-8") for n in names}}


DEVICES_FILE = {"netbox": "2-devices.csv", "nautobot": "1-devices.csv"}


@extra("rack.html: Export - one import kit per target in the menu, with every device and part's type under types/ and a README")
def check_rack_export_dcim_types(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)
    page.click("#exportMenu > summary")
    wait_sel(page, "menu: the import kits", '#exportItems [data-export="nautobot-import"]')
    kinds = page.evaluate("() => [...document.querySelectorAll('#exportItems [data-export]')].map(b => [b.dataset.export, b.textContent])")
    page.click("#exportMenu > summary")
    dcim = [k for k in kinds if "netbox" in k[0] or "nautobot" in k[0] or "dcim" in k[0]]
    if dcim != [["dcim-settings", "DCIM import settings"], ["netbox-import", "NetBox import (.zip)"],
                ["nautobot-import", "Nautobot import (.zip)"]]:
        bad.append(f"menu: the DCIM entries are {dcim}")
    want = {"types/device-types/Cisco/ASR-9006-AC-V2.yaml", "types/device-types/Edgecore/7726-32X-O-AC-F.yaml",
            "types/device-types/BATM-Telco Systems/TM-280.yaml", "types/module-types/Cisco/A9K-16X100GE-TR.yaml",
            "types/module-types/Cisco/A9K-3KW-AC.yaml", "types/module-types/Cisco/ASR-9006-FAN.yaml",
            "types/module-types/Cisco/A9K Slot Cover.yaml"}
    for target, T in (("netbox", "NetBox"), ("nautobot", "Nautobot")):
        dl, kit = export_kit(page, target)
        status = export_status(page)
        if dl.suggested_filename != f"Export-test-{target}-import.zip":
            bad.append(f"{T} kit: named {dl.suggested_filename!r}")
        types = [n for n in kit["names"] if n.startswith("types/")]
        if set(types) != want or len(types) != len(want):
            bad.append(f"{T} kit: types differ - missing {sorted(want - set(types))}, extra {sorted(set(types) - want)}, {len(types)} entries")
        if len(kit["names"]) != len(set(kit["names"])) or kit["names"][-1] != "README.txt" or "NOTES.txt" in kit["names"]:
            bad.append(f"{T} kit: entries {kit['names']}")
        left, notes = readme_lists(kit["zip"]["README.txt"])
        if not any("ASR-9006-AC-V2 is a best guess" in n for n in notes):
            bad.append(f"{T} kit: the README does not flag the ASR-9006's guessed type")
        if not any("generic/qsfp-lc@2" in n and f"no {T} module type" in n for n in notes):
            bad.append(f"{T} kit: the README does not list the optic with no module type")
        if "model: 7726-32X-O-AC-F" not in kit["zip"].get("types/device-types/Edgecore/7726-32X-O-AC-F.yaml", ""):
            bad.append(f"{T} kit: the Edgecore YAML is not the exported file")
        # The status counts the README's own lines: the blank-settings warning, what is left out, the notes.
        if status != notes_status(readme_count(kit["zip"]["README.txt"])):
            bad.append(f"{T} kit: the README carries {readme_count(kit['zip']['README.txt'])} notes, but the status reads {status!r}")
    return bad


def read_csv(dl):
    # read_bytes: read_text would turn the file's CRLF into LF and the Notes split would never match
    text = pathlib.Path(dl.path()).read_bytes().decode("utf-8")
    data = text.partition("\r\n\r\nNotes\r\n")[0]
    reader = csv.DictReader(io.StringIO(data, newline=""))
    return reader.fieldnames, list(reader), text


# The kit's comment on the later of two devices that share a unit front and rear (kit 0.22.0), and a device's
# unit as Nautobot's devices file gives it: its position, or, for one written with none, the unit its comment names.
NAUTOBOT_PAIR = "In U{u} on the rear, opposite {by}; no position, since Nautobot refuses two devices in one unit, front and rear, while either type is full depth."


def nautobot_u(row):
    m = re.search(r"\bIn U([\d.]+) on the (?:front|rear), opposite ", row.get("comments") or "")
    return row.get("position") or (m.group(1) if m else "")


def device_rows(page, target="nautobot"):
    """The device import's rows for one target, as exported from the page. Nautobot's
    file is the default because it holds every device with a type: NetBox's leaves
    out a device NetBox would refuse (two full-depth devices sharing a U)."""
    return list(csv.DictReader(io.StringIO(export_kit(page, target)[1]["zip"][DEVICES_FILE[target]], newline="")))


@extra("rack.html: Export - the kits' devices files name each device's type, position and face as NetBox and Nautobot read them")
def check_rack_export_device_csv(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)
    _, kit = export_kit(page, "netbox")
    rows = kit_rows(kit, "2-devices.csv")
    if list(rows[0].keys()) != ["name", "role", "manufacturer", "device_type", "status", "site", "rack", "position", "face", "comments"]:
        bad.append(f"NetBox devices: columns {list(rows[0].keys())}")
    by = {r["name"]: r for r in rows}
    want = {"core-1": ("Cisco", "ASR-9006-AC-V2", "2", "front"), "leaf-1": ("Edgecore", "7726-32X-O-AC-F", "14", "front"),
            "demarc-i4": ("BATM/Telco Systems", "TM-280", "20", "rear")}
    for name, (man, dt, pos, face) in want.items():
        r = by.get(name)
        if not r or (r["manufacturer"], r["device_type"], r["position"], r["face"]) != (man, dt, pos, face):
            bad.append(f"NetBox devices: {name} is {r and (r['manufacturer'], r['device_type'], r['position'], r['face'])}")
    # demarc-i3 shares U14 with leaf-1 and both types are full depth: NetBox would refuse the whole file for it.
    left = readme_lists(kit["zip"]["README.txt"])[0]
    if set(by) != set(want) or not any(l.startswith("demarc-i3 is not in the devices file: it shares U14 with leaf-1 on the front") for l in left):
        bad.append(f"NetBox devices: rows {sorted(by)}; the README lists {left}")
    if not all(r["status"] == "planned" and r["rack"] == "Export test" for r in rows):
        bad.append("NetBox devices: status or rack column wrong")
    if "best guess" not in by.get("core-1", {}).get("comments", ""):
        bad.append("NetBox devices: core-1's guessed type is not said in comments")

    rows = device_rows(page, "nautobot")
    leaf = next((r for r in rows if r["name"] == "leaf-1"), {})
    if (leaf.get("device_type__model"), leaf.get("status__name")) != ("7726-32X-O-AC-F", "Planned"):
        bad.append(f"Nautobot devices: leaf-1 is {leaf}")
    # NAUTOBOT REFUSES THE PAIR AT U14 TOO, front and rear, while either type is full depth (kit 0.22.0: a fix;
    # earlier kits wrote both with a position, and the import failed). Its file keeps all four devices; the later
    # of the pair, demarc-i3, is written with no position and no face, and its comment says where it is and why.
    odd = next((r for r in rows if r["name"] == "demarc-i3"), {})
    if sorted(r["name"] for r in rows) != ["core-1", "demarc-i3", "demarc-i4", "leaf-1"] \
            or (odd.get("position"), odd.get("face")) != ("", "") or NAUTOBOT_PAIR.format(u=14, by="leaf-1") not in odd.get("comments", "") \
            or any("refuses" in r["comments"] or not r["position"] or not r["face"] for r in rows if r["name"] != "demarc-i3"):
        bad.append(f"Nautobot devices: rows {[(r['name'], r['position'], r['face'], r['comments']) for r in rows]}")

    # A DCIM CSV is imported as is: a label that opens like a formula stays verbatim (only the BOM guards it).
    eq = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js');
      const r = window.__rack.doc().racks[0];
      const rack = {...r, items: r.items.filter(i => i.id === 'i2').map(i => ({...i, label: '=leaf'}))};
      return (await X.dcimKit(rack, () => ({manufacturer: 'Edgecore'}), 'netbox')).files['2-devices.csv'];
    }""")
    if not eq.split("\r\n")[1].startswith("=leaf,"):
        bad.append(f"NetBox devices: a label starting with '=' is not verbatim: {eq[:200]!r}")

    # Positions follow the frame's numbering.
    page.click("#frameBtn")
    page.select_option("#fNumbering", "top-down")
    page.wait_for_function("() => window.__rack.doc().racks[0].frame.numbering === 'top-down'", timeout=READY_MS)
    got = {r["name"]: r["position"] for r in device_rows(page, "netbox")}
    if got != {"core-1": "14", "leaf-1": "11", "demarc-i4": "5"}:
        bad.append(f"NetBox devices: top-down positions {got}")
    got = {r["name"]: r["position"] for r in device_rows(page, "nautobot")}
    # (demarc-i3 has no position in Nautobot's file; its comment names its unit as the frame counts it)
    said = {r["name"]: r["comments"] for r in device_rows(page, "nautobot")}
    if got != {"core-1": "14", "leaf-1": "11", "demarc-i3": "", "demarc-i4": "5"} or NAUTOBOT_PAIR.format(u=11, by="leaf-1") not in said.get("demarc-i3", ""):
        bad.append(f"Nautobot devices: top-down positions {got}; demarc-i3 says {said.get('demarc-i3')!r}")
    return bad


@extra("rack.html: Export - a device type from another vendor's file is said so in the notes, the devices file and the kit's README")
def check_rack_export_other_vendor(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)
    # A chassisOf stub whose manufacturer has no files, so the match falls
    # back to the Cisco folder: a file from another vendor.
    got = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js');
      const r = window.__rack.doc().racks[0];
      const rack = {...r, items: r.items.filter(i => i.id === 'i1')};
      const stub = () => ({manufacturer: 'Nobody Inc'});
      const ctx = await X.dcimContext(rack, stub, 'netbox');
      const kit = await X.dcimKit(rack, stub, 'netbox');
      return {note: ctx.notes.find(n => n.includes('core-1')) || '', flag: ctx.types.get('i1')?.otherVendor,
              csv: kit.files['2-devices.csv'], readme: kit.files['README.txt']};
    }""")
    if got["flag"] is not True:
        bad.append(f"other vendor: otherVendor is {got['flag']!r}, expected true")
    if "another vendor's" not in got["note"]:
        bad.append(f"other vendor: dcimContext note is {got['note']!r}")
    rows = list(csv.DictReader(io.StringIO(got["csv"], newline="")))
    comments = rows[0]["comments"] if rows else ""
    if "another vendor's (Cisco) file" not in comments:
        bad.append(f"other vendor: the CSV comment is {comments!r}")
    if "another vendor's (Cisco) file" not in flat_readme(got["readme"]):
        bad.append(f"other vendor: the kit's README is {got['readme']!r}")
    return bad


@extra("rack.html: a cable manager on a switch - drawn over it, clicked through to it, moved with it, and outside the rails in 3D")
def check_rack_face_managers(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    built = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Managers'});
      ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 20, label: 'leaf-1'}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, label: 'mgr-1', on: 'i1', unit: 1}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 30, face: 'rear', label: 'mgr-rear'}));
      return r;
    }""")
    page.evaluate("r => window.__rack.replaceRack(r)", built)
    page.wait_for_selector('#paneFront svg [data-item-id="i2"][data-panel="mounted"]', timeout=READY_MS)
    page.wait_for_selector('#paneRear svg [data-item-id="i3"][data-panel="mounted"]', timeout=READY_MS)
    if not page.query_selector('#paneRear svg [data-manager-mark="i3"]'):
        bad.append("2D: no gutter mark for the rear manager in the rear pane")
    if page.query_selector('#paneFront svg [data-item-id="i3"][data-panel="mounted"]'):
        bad.append("2D: the rear manager is drawn mounted in the front pane")
    order = page.evaluate("""() => {
      const s = document.querySelector('#paneFront svg');
      const h = s.querySelector('[data-item-id="i1"][data-panel="mounted"]'), m = s.querySelector('[data-item-id="i2"][data-panel="mounted"]');
      return !!(h.compareDocumentPosition(m) & Node.DOCUMENT_POSITION_FOLLOWING);
    }""")
    if not order:
        bad.append("2D: the manager is not drawn after its host")
    if not page.query_selector('#paneFront svg [data-manager-mark="i2"]'):
        bad.append("2D: no gutter mark for the manager")
    if page.query_selector('#paneRear svg [data-item-id="i2"]'):
        bad.append("2D: the manager shows on the rear, behind the switch")
    # A point over the manager whose top element belongs to the host: a gap.
    gap = page.evaluate("""() => {
      const m = document.querySelector('#paneFront svg [data-item-id="i2"][data-panel="mounted"]').getBoundingClientRect();
      for (let fx = 0.05; fx < 1; fx += 0.03) for (let fy = 0.2; fy < 0.9; fy += 0.2) {
        const x = m.left + m.width * fx, y = m.top + m.height * fy;
        if (document.elementFromPoint(x, y)?.closest('[data-item-id]')?.dataset.itemId === 'i1') return [x, y];
      }
      return null;
    }""")
    if not gap:
        bad.append("2D: no point over the manager reaches the switch behind it")
    else:
        page.mouse.click(*gap)
        if page.inner_text("#side h3") != "leaf-1":
            bad.append(f"2D: a click between the rings selected {page.inner_text('#side h3')!r}, not leaf-1")
    ring = page.query_selector('#paneFront svg [data-item-id="i2"] [data-kind="ring"]')
    if not ring:
        bad.append("2D: the manager has no ring to click")
    else:
        ring.click()
        if page.inner_text("#side h3") != "mgr-1":
            bad.append(f"2D: a click on a ring selected {page.inner_text('#side h3')!r}, not mgr-1")
    page.click('#paneFront svg [data-manager-mark="i2"]')
    if page.inner_text("#side h3") != "mgr-1":
        bad.append("2D: the gutter mark does not select the manager")
    page.click("#mSelectHost")
    if not page.query_selector("#mgrRows"):
        bad.append("inspector: the host shows no Cable managers section")
    page.click("#iMove")
    page.click('#paneFront svg [data-u="24"][data-face="front"]')
    items = page.evaluate("() => window.__rack.doc().racks[0].items.filter(i => i.id !== 'i3').map(i => [i.id, i.ru, i.on ?? null])")
    if items != [["i1", 24, None], ["i2", 24, "i1"]]:
        bad.append(f"move: the manager did not follow its host: {items}")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the managers' scene")
    got = page.evaluate("""async () => {
      const s = window.__rack.scene(); await s.complete?.();
      const g = s.three.scene.getObjectByName('device-i2'), h = s.three.scene.getObjectByName('device-i1');
      const face = s.metrics().faceZ;
      const box = g.children.find(c => c.isMesh && Array.isArray(c.material));
      const a = await s.guideAnchor({id: 'i2'}, 'guide-1');
      const rr = s.three.scene.getObjectByName('device-i3');
      const railDepth = window.__rack.doc().racks[0].frame.railDepth;
      return {mgrZ: g.position.z, hostZ: h.position.z, face, hidden: box.material.every(m => !m.visible), anchor: !!a,
              rearZ: rr?.position.z, rearRotY: rr?.rotation.y, rearPlane: face - railDepth};
    }""")
    if got["rearZ"] is None or not (got["rearZ"] < got["rearPlane"]):
        bad.append(f"3D: the rear manager is not behind the rear rails ({got})")
    if got["rearRotY"] is None or abs(got["rearRotY"] - 3.141592653589793) > 1e-6:
        bad.append(f"3D: the rear manager is not turned around ({got})")
    if not (got["mgrZ"] > got["face"] > got["hostZ"]):
        bad.append(f"3D: the manager is not in front of the rails ({got})")
    if not got["hidden"]:
        bad.append("3D: the manager's sheet body is drawn as a solid box")
    if not got["anchor"]:
        bad.append("3D: guideAnchor finds no guide-1 on the manager")
    # The rail labels of the host and its manager are at one height: they sit side by side.
    tags = page.evaluate("""() => {
      const sc = window.__rack.scene().three.scene, y = sc.getObjectByName('device-i1').position.y;
      return sc.children.filter(c => c.isSprite && c.position.z === 46 && Math.abs(c.position.y - y) < 1)
        .map(c => [c.position.x - c.scale.x / 2, c.position.x + c.scale.x / 2]);
    }""")
    if len(tags) < 2:
        bad.append(f"3D: the host and its manager do not both have a rail label at their height: {tags}")
    elif any(a[0] < b[1] and b[0] < a[1] for i, a in enumerate(tags) for b in tags[i + 1:]):
        bad.append(f"3D: the host's and the manager's rail labels overlap: {tags}")
    dl = export_file(page, "glb", timeout=READY_3D_MS)
    glb = pathlib.Path(dl.path()).read_bytes()
    if glb[:4] != b"glTF" or b'"device-i2"' not in glb:
        bad.append(f"GLB: {dl.suggested_filename!r} is not a GLB with the manager's node")
    return bad


@extra("rack.html: cables route through their manager's rings and up the lanes, in 2D and 3D, edited and reset, with a routed length")
def check_rack_cable_routes(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    # The cables must land: optics at both ends' ports, a splice cassette in the
    # panel, and fiber between them (cat6 into these ports leaves ends loose).
    built = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Routes'});
      const optic = {'port-1': 'generic/qsfp-lc@2', 'port-32': 'generic/qsfp-lc@2'};
      ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 20, label: 'leaf-1', swaps: optic}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, label: 'mgr-1', on: 'i1', unit: 1}));
      // c2's panel end is bay 4, on its own (right) side: since kit 0.12.0 a
      // cable whose ends stand on opposite sides takes the shorter gutter.
      ({rack: r} = M.withItem(r, {ref: 'fhd-1ufce', cfg: cat['fhd-1ufce'].default, ru: 30, label: 'pp-1',
        swaps: {'bay-1': 'fs/fhd-splice-12-lc@3', 'bay-4': 'fs/fhd-splice-12-lc@3'}}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i3', path: 'bay-1/module/lc1', view: 'front'}, media: 'os2'}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-32', view: 'front'}, b: {item: 'i3', path: 'bay-4/module/lc2', view: 'front'}, media: 'os2'}));
      return r;
    }""")
    page.evaluate("r => window.__rack.replaceRack(r)", built)
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id]').length === 2", timeout=READY_MS)
    page.wait_for_function("() => window.__rack.doc().racks[0].cables.length === 2 && window.__rack.doc().racks[0].cables.every(c => c.length && c.length.source === 'routed')", timeout=READY_MS)
    srcs = page.evaluate("() => window.__rack.doc().racks[0].cables.map(c => [c.id, c.length?.source])")
    if any(x[1] != "routed" for x in srcs):
        bad.append(f"length: not every cable has a routed length: {srcs}")
    # The automatic routes: lanes exactly left-front and right-front; c1 through guide-1, c2 through guide-5.
    routes = page.evaluate("() => window.__rack.routes?.() ?? null")
    if routes is None:
        return bad + ["probe: window.__rack.routes() is missing"]
    rmap = dict(routes)
    lanes = sorted({w["lane"] for _, ws in routes for w in ws if "lane" in w})
    if lanes != ["left-front", "right-front"]:
        bad.append(f"routes: lanes are {lanes}, not left-front and right-front: {routes}")
    via = lambda cid: [w["via"] for w in rmap.get(cid, []) if w.get("item") == "i2"]
    if "guide-1" not in via("c1") or "guide-5" not in via("c2"):
        bad.append(f"routes: c1 goes through {via('c1')} and c2 through {via('c2')}, not guide-1 / guide-5: {routes}")
    # 2D: each lane run is vertical, reaches into its gutter, and the path passes the ring end.
    geo = page.evaluate("""() => {
      const s = document.querySelector('#paneFront svg');
      const out = {};
      for (const id of ['c1', 'c2']) {
        const g = s.querySelector(`[data-cables] [data-cable-id="${id}"]`);
        const paths = [...g.querySelectorAll('path')].filter(p => !p.dataset.leader);
        const pts = [];
        for (const p of paths) { const L = p.getTotalLength(); for (let t = 0; t <= L; t += 0.5) { const q = p.getPointAtLength(t); pts.push([q.x, q.y]); } }
        const xs = pts.map(q => q[0]);
        const left = id === 'c1';
        const ext = left ? Math.min(...xs) : Math.max(...xs);
        const run = pts.filter(q => Math.abs(q[0] - ext) < 0.6).map(q => q[1]);
        out[id] = {ext, span: Math.max(...run) - Math.min(...run)};
      }
      // THE RING WHERE THE KIT LAYS THE CABLE (kit 0.14.0): across, the
      // centre of guide-1's drawing; in height, its sill, the kit's entry and
      // exit (rack mm: the pane's y runs down from the top of the rack)
      const g1 = s.querySelector('[data-cables] [data-cable-id="c1"]');
      const end = s.querySelector('[data-item-id="i2"] [id="guide-1-end"]') || s.querySelector('#guide-1-end');
      const eb = end.getBoundingClientRect(), cx = eb.left + eb.width / 2;
      const kp = window.__rack.paths().c1.points.filter(q => q.item === 'i2' && q.via === 'guide-1' && (q.at === 'entry' || q.at === 'exit'));
      const H = window.__rack.doc().racks[0].frame.heightRU * 44.45, sillY = H - kp.reduce((a, q) => a + q.y, 0) / (kp.length || NaN);
      const inv = s.getScreenCTM().inverse();
      const cxPane = new DOMPoint(cx, 0).matrixTransform(inv).x;
      let best = Infinity;
      for (const p of g1.querySelectorAll('path')) {
        if (p.dataset.leader) continue;
        const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
        for (let t = 0; t <= L; t += 0.25) {
          const q = new DOMPoint(p.getPointAtLength(t).x, p.getPointAtLength(t).y).matrixTransform(m);
          best = Math.min(best, Math.hypot(q.x - cxPane, q.y - sillY));
        }
      }
      out.ringGap = best;
      return out;
    }""")
    if not (geo["c1"]["ext"] < -26) or not (geo["c2"]["ext"] > 450.85 + 26):
        bad.append(f"2D: the cables do not run out to their gutters (c1 {geo['c1']['ext']}, c2 {geo['c2']['ext']})")
    for cid in ("c1", "c2"):
        if geo[cid]["span"] < 20:
            bad.append(f"2D: {cid}'s lane run is not vertical (the vertical span at its extreme x is {geo[cid]['span']})")
    if not (geo["ringGap"] <= 1.5):
        bad.append(f"2D: c1's path passes {geo['ringGap']} units from guide-1 at the kit's sill height, over 1.5")
    # Editing. Select c1 from the list, open its form, type a label, add a waypoint after row 0.
    page.click('#cableList [data-cable-row="c1"]')
    page.click("#cableEdit")
    routed_text = page.inner_text("#cRouted")
    # (kit 0.22.0: a routed length holds what the cord must at least be, `need`, where it held `measured`)
    if not re.match(r"^\d+(\.\d+)? m \(routed: the route needs [\d.]+ m\)", routed_text):
        bad.append(f"form: the routed length reads {routed_text!r}, not 'N m (routed: the route needs X m)'")
    page.fill("#cLabel", "uplink-A")
    page.focus("#routeRow-0")
    page.keyboard.press("Enter")
    page.click("#routeAdd")
    # While picking, the rear pane's left-gutter targets are named for the right (mirrored).
    # (once the redraw that draws them is done: the routes now read each plug's reach first)
    page.wait_for_function("() => document.querySelector('#paneRear svg [data-pick-lane]')", timeout=READY_MS)
    rear = page.evaluate("""() => {
      const s = document.querySelector('#paneRear svg');
      const xOf = n => { const r = s.querySelector(`[data-pick-lane="${n}"]`); return r ? r.getBBox().x : null; };
      return {right: xOf('right-rear'), left: xOf('left-rear')};
    }""")
    if rear["right"] is None or rear["left"] is None or not (rear["right"] < rear["left"]):
        bad.append(f"rear pick: the left gutter's target is not named right-rear: {rear}")
    page.click('#paneFront svg [data-pick-lane="right-front"][data-pick-ru="25"]')
    page.keyboard.press("Escape")
    got = page.evaluate("() => { const c = window.__rack.doc().racks[0].cables.find(c => c.id === 'c1'); return {route: c.route, edited: c.routeEdited === true}; }")
    stored = got["route"]
    if len(stored) < 2 or stored[1] != {"lane": "right-front", "ru": 25} or not got["edited"]:
        bad.append(f"edit: the waypoint is not at index 1 of the stored route (edited {got['edited']}): {stored}")
    label = page.input_value("#cLabel")
    if label != "uplink-A":
        bad.append(f"edit: the typed label did not survive the pick: {label!r}")
    page.click("#cSave")
    saved = page.evaluate("() => window.__rack.doc().racks[0].cables.find(c => c.id === 'c1').label")
    if saved != "uplink-A":
        bad.append(f"edit: the label saved as {saved!r}")
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    again = page.evaluate("() => window.__rack.doc().racks[0].cables.find(c => c.id === 'c1').route")
    if again != stored:
        bad.append(f"reload: the edited route came back as {again}, not {stored}")
    page.click('#cableList [data-cable-row="c1"]', timeout=READY_MS)
    page.click("#cableEdit")
    page.click("#routeReset")
    if page.evaluate("() => window.__rack.doc().racks[0].cables.some(c => 'routeEdited' in c)"):
        bad.append("reset: a cable still has a routeEdited key")
    # CANCEL TAKES BACK THE EDIT (S-0042): the reset above and one more pick were made since
    # this form opened; Cancel puts the route back as the form found it, and adds no Undo step.
    page.click("#routeAdd")
    page.wait_for_function("() => document.querySelector('#paneFront svg [data-pick-lane]')", timeout=READY_MS)
    page.click('#paneFront svg [data-pick-lane="right-front"][data-pick-ru="30"]')
    page.keyboard.press("Escape")
    mid = page.evaluate("() => window.__rack.doc().racks[0].cables.find(c => c.id === 'c1').routeEdited === true")
    steps = page.evaluate("() => window.__rack.history().undoSummary")
    if not mid:
        bad.append("cancel: the pick did not edit the route")
    page.click("#cCancel")
    back = page.evaluate("() => { const c = window.__rack.doc().racks[0].cables.find(c => c.id === 'c1'); return {route: c.route, edited: c.routeEdited === true}; }")
    if back["route"] != stored or not back["edited"]:
        bad.append(f"cancel: the route is {back}, not the one the form opened with ({stored})")
    if page.evaluate("() => window.__rack.history().undoSummary") == steps:
        bad.append(f"cancel: the last Undo step is still {steps!r}: the pick was not taken back")
    if not page.evaluate("() => window.__rack.history().canRedo"):
        bad.append("cancel: Redo is empty: the edits were not undone as steps")
    # (the 3D part below reads the automatic route)
    page.click("#cableEdit")
    page.click("#routeReset")
    page.click("#cSave")
    # 3D: a lone cable's tube passes through its ring's opening and up its lane, outside the switch.
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, cables: r.cables.filter(c => c.id === 'c1')}); }""")
    page.click('#mode [data-mode="3d"]')
    # THE SCENE THAT STAYS (settle_scene). The cable list was just cut to c1,
    # and its routes settle after the 3D switch has started a build: the page
    # then disposes that scene and builds another.
    settle_scene(page, "3D: the lone cable's scene", tubes=True)
    res = page.evaluate("""async () => {
      const R = await import('/vendor/rack/route.js');
      const s = window.__rack.scene();
      // THROUGH THE RING AS THE KIT PASSES IT (portrayal-site#166): the
      // tube's polyline runs through the kit's entry and exit of guide-1, on
      // its sill, and is straight between them
      const faceZ = s.metrics().faceZ;
      const kp = window.__rack.paths().c1.points.filter(q => q.item === 'i2' && q.via === 'guide-1');
      const tubes = s.rackCables.tubes;
      const pts = tubes.flatMap(t => t.points);
      const segDist = (p, a, b) => {
        const ab = b.clone().sub(a), t = Math.max(0, Math.min(1, p.clone().sub(a).dot(ab) / (ab.lengthSq() || 1)));
        return a.clone().add(ab.multiplyScalar(t)).distanceTo(p);
      };
      const on = q => { const T = pts[0].clone().set(q.x, q.y, faceZ + q.z); let d = Infinity;
        for (let i = 0; i + 1 < pts.length; i++) d = Math.min(d, segDist(T, pts[i], pts[i + 1])); return d; };
      const io = kp.filter(q => q.at === 'entry' || q.at === 'exit');
      const ring = io.length === 2 ? Math.max(...io.map(on)) : Infinity;
      let lane = Infinity;
      const lx = R.laneX('left');
      for (const p of pts) lane = Math.min(lane, Math.abs(p.x - lx));
      const inside = [];
      for (const {ref, box} of s.deviceBoxes()) for (const p of pts) if (box.containsPoint(p)) inside.push(ref);
      const through = {kit: kp.map(q => q.at), entryExit: io.length,
                       apart: io.length === 2 ? Math.hypot(io[0].x - io[1].x, io[0].y - io[1].y, io[0].z - io[1].z) : null};
      return {ring, lane, laneX: lx, tubes: tubes.length, npts: pts.length, inside, through};
    }""")
    if res["npts"] == 0:
        bad.append(f"3D: the lone cable has no tube points ({res})")
    else:
        if not (res["ring"] < 0.05):
            bad.append(f"3D: the tube misses the kit's entry or exit of guide-1 by {res['ring']} mm: {res['through']}")
        if not (res["lane"] < 3):
            bad.append(f"3D: the tube never reaches the lane at x = {res['laneX']} (closest {res['lane']} mm)")
        if res["inside"]:
            bad.append(f"3D: tube points lie inside a device box: {res['inside']}")
        t = res["through"]
        if t["entryExit"] != 2 or "approach" not in t["kit"] or abs((t["apart"] or 0) - 6.8) > 0.05:
            bad.append(f"3D: the kit does not pass guide-1 from an approach point, entering and leaving 6.8 mm apart: {t}")
    return bad


@extra("rack.html: on the mirrored rear pane a cable passes its ring with no hook, and so does a cross-face cable drawn from its far end (Portrayal #930)")
def check_rack_ring_rear_pane(page, base):
    """The two call sites the ring marks hang on: cable-view.js turns the
    kit's marks to the rear pane's mirrored axes (paneMarks), and cables.js
    reverses them for a cross-face cable whose 'to' end lands on the pane
    (reverseMarks). Unturned or unreversed, the ring is entered by its far
    face and the stroke goes past the ring and back along x: a hook."""
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    # A REAR-facing switch with the manager on it, a rear-facing panel above
    # (c1, c2: both ends on the rear pane, automatic routes through guide-1
    # and guide-5), and a front-facing panel whose cable c3 runs from the
    # front to the switch: on the rear pane only its 'to' end lands.
    built = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Rear rings'});
      const optic = {'port-1': 'generic/qsfp-lc@2', 'port-2': 'generic/qsfp-lc@2', 'port-32': 'generic/qsfp-lc@2'};
      // c2's panel end is bay 4, on its own side (kit 0.12.0: ends on opposite
      // sides take the shorter gutter)
      const splice = {'bay-1': 'fs/fhd-splice-12-lc@3', 'bay-4': 'fs/fhd-splice-12-lc@3'};
      ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 20, face: 'rear', label: 'leaf-r', swaps: optic}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, face: 'rear', label: 'mgr-r', on: 'i1', unit: 1}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-1ufce', cfg: cat['fhd-1ufce'].default, ru: 30, face: 'rear', label: 'pp-r', swaps: splice}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-1ufce', cfg: cat['fhd-1ufce'].default, ru: 34, label: 'pp-f', swaps: splice}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i3', path: 'bay-1/module/lc1', view: 'front'}, media: 'os2'}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-32', view: 'front'}, b: {item: 'i3', path: 'bay-4/module/lc2', view: 'front'}, media: 'os2'}));
      ({rack: r} = K.withCable(r, {a: {item: 'i4', path: 'bay-1/module/lc1', view: 'front'}, b: {item: 'i1', path: 'port-2', view: 'front'}, media: 'os2'}));
      return r;
    }""")
    page.evaluate("r => window.__rack.replaceRack(r)", built)
    page.wait_for_function("() => document.querySelectorAll('#paneRear svg [data-cables] [data-cable-id]').length === 3", timeout=READY_MS)
    page.wait_for_function("() => (window.__rack.rings()?.marks || []).length === 3", timeout=READY_MS)
    routes = dict(page.evaluate("() => window.__rack.routes()"))
    rings_of = lambda cid: [w["via"] for w in routes.get(cid, []) if w.get("item") == "i2"]
    want = {"c1": "guide-1", "c2": "guide-5"}
    for cid, via in want.items():
        if via not in rings_of(cid):
            bad.append(f"routes: {cid} does not go through {via}: {routes.get(cid)}")
    if not rings_of("c3"):
        return bad + [f"routes: the cross-face cable c3 goes through no ring on the manager: {routes.get('c3')}"]
    want["c3"] = rings_of("c3")[0]
    # The furthest each stroke goes back along x against its own travel,
    # within 20 mm (along x) and 30 mm (along y) of the ring's end rect centre.
    got = page.evaluate("""want => {
      const s = document.querySelector('#paneRear svg'), inv = s.getScreenCTM().inverse(), out = {};
      for (const [id, via] of Object.entries(want)) {
        const g = s.querySelector(`[data-cables] [data-cable-id="${id}"]`);
        const end = s.querySelector(`[data-item-id="i2"] [id="${via}-end"]`);
        if (!g || !end) { out[id] = {missing: !g ? 'cable' : 'ring'}; continue; }
        const eb = end.getBoundingClientRect();
        const c = new DOMPoint(eb.left + eb.width / 2, eb.top + eb.height / 2).matrixTransform(inv);
        // Each path on its own (a cable is drawn as more than one, the
        // strands at its ends among them), in the order it is drawn.
        let back = 0, near = 0;
        for (const p of g.querySelectorAll('path')) {
          if (p.dataset.leader) continue;
          const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength(), pts = [];
          for (let t = 0; t <= L; t += 0.1) {
            const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m);
            if (Math.abs(w.x - c.x) <= 20 && Math.abs(w.y - c.y) <= 30) pts.push(w.x);
          }
          if (pts.length < 2) continue;
          near += pts.length;
          const dir = Math.sign(pts[pts.length - 1] - pts[0]) || 1;
          let best = -Infinity;
          for (const x of pts) { best = Math.max(best, dir * x); back = Math.max(back, best - dir * x); }
        }
        out[id] = near ? {back, near} : {near};
      }
      return out;
    }""", want)
    for cid, r in got.items():
        if "back" not in r:
            bad.append(f"rear pane: {cid} could not be measured at {want[cid]} ({r})")
        elif r["back"] > 0.05:
            bad.append(f"rear pane: {cid} hooks back {r['back']:.2f} mm along x at {want[cid]}")
    return bad


# CABLE BUNDLES (portrayal-site#142). Three Cat6A cables from one copper
# switch through one ring of its lacer, up the left-front lane to a second
# switch: the kit works their trunk out as mgr-1 ring 1 > left-front U20-U30,
# and sizes it from the cable types' Cat6A diameter, well above the drawing's
# two-stroke floor, so the band and tube widths test the real figure. `face`
# puts the whole set on the front or the rear face.
def bundle_fixture(page, face="front", ports=("port-1", "port-2", "port-3")):
    return page.evaluate("""async ([face, ports]) => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Bundles'});
      ({rack: r} = M.withItem(r, {ref: 'ws-c4948e', cfg: cat['ws-c4948e'].default, ru: 20, face, label: 'sw-1'}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, face, label: 'mgr-1', on: 'i1', unit: 1}));
      ({rack: r} = M.withItem(r, {ref: 'ws-c4948e', cfg: cat['ws-c4948e'].default, ru: 30, face, label: 'sw-2'}));
      for (const p of ports)
        ({rack: r} = K.withCable(r, {a: {item: 'i1', path: p, view: 'front'}, b: {item: 'i3', path: p, view: 'front'}, media: 'cat6a'}));
      return r;
    }""", [face, list(ports)])


def open_bundle_rack(page, base, face="front", ports=("port-1", "port-2", "port-3")):
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.evaluate("r => window.__rack.replaceRack(r)", bundle_fixture(page, face, ports))
    # (the routes of THIS rack: the page opens on the last rack, which in a check that calls this twice is the last
    # call's, three routed cables as well, and those would answer for it)
    page.wait_for_function("() => (window.__rack.routes() || []).length === 3 && window.__rack.routes().every(([, ws]) => ws.length)"
                           " && window.__rack.routesCurrent().current", timeout=READY_MS)


# The envelope of a bundle on a pane, measured: its stroke width, the x of its
# vertical run on the lane, how far the furthest member's stroke is from the
# envelope's end at the ring (`ringGap`: the envelope is about the members'
# pack there, at the height the kit rests them, not at the middle of the ring's
# drawing), and how far it hooks back along x near that ring; whether it shows;
# the straps drawn; and, per member, its stroke's x at a height (U29) above any
# peel point.
BAND_GEO = """([pane, id]) => {
  const s = document.querySelector(`#${pane} svg`);
  const g = s.querySelector(`[data-cables] [data-bundle-id="${id}"]`);
  if (!g) return null;
  const band = g.querySelector('[data-bundle-trunk]');
  const inv = s.getScreenCTM().inverse();
  const pts = [];
  for (const p of g.querySelectorAll('[data-bundle-trunk]')) {
    const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
    for (let t = 0; t <= L; t += 0.25) { const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m); pts.push([w.x, w.y]); }
  }
  const xs = pts.map(q => q[0]);
  // the gutter the trunk runs up: the band's x furthest out from the rack's middle
  const laneX = xs.reduce((a, x) => (Math.abs(x - 225.425) > Math.abs(a - 225.425) ? x : a), xs[0]);
  const run = pts.filter(q => Math.abs(q[0] - laneX) < 0.6).map(q => q[1]);
  const end = s.querySelector('[data-item-id="i2"] [id="guide-1-end"]');
  let ringGap = null, back = null;
  if (end) {
    const eb = end.getBoundingClientRect(), c = new DOMPoint(eb.left + eb.width / 2, eb.top + eb.height / 2).matrixTransform(inv);
    // the envelope's end at the ring, and how far each member's stroke passes from it
    const endPt = pts.reduce((a, q) => (Math.hypot(q[0] - c.x, q[1] - c.y) < Math.hypot(a[0] - c.x, a[1] - c.y) ? q : a), pts[0]);
    const gaps = [];
    for (const id of (g.dataset.members || '').split(' ').filter(Boolean)) {
      let best = Infinity;
      for (const p of s.querySelectorAll(`[data-cables] [data-cable-id="${id}"] path`)) {
        const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
        for (let t = 0; t <= L; t += 0.25) { const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m); best = Math.min(best, Math.hypot(w.x - endPt[0], w.y - endPt[1])); }
      }
      gaps.push(best);
    }
    ringGap = gaps.length ? Math.max(...gaps) : null;
    const near = pts.filter(q => Math.abs(q[0] - c.x) <= 20 && Math.abs(q[1] - c.y) <= 30).map(q => q[0]);
    if (near.length > 1) {
      const dir = Math.sign(near.at(-1) - near[0]) || 1;
      let best = -Infinity; back = 0;
      for (const x of near) { best = Math.max(best, dir * x); back = Math.max(back, best - dir * x); }
    }
  }
  // the y of U29's middle on this pane: the rack is 42U, U1 at the bottom
  const y28 = 42 * 44.45 - 28.5 * 44.45;
  const memberX = {};
  for (const c of ['c1', 'c2', 'c3']) {
    const cg = s.querySelector(`[data-cables] [data-cable-id="${c}"]`);
    if (!cg) continue;
    let best = null;
    for (const p of cg.querySelectorAll('path')) {
      const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
      for (let t = 0; t <= L; t += 0.5) {
        const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m);
        if (Math.abs(w.y - y28) < 1 && (best == null || Math.abs(w.x - laneX) < Math.abs(best - laneX))) best = w.x;
      }
    }
    memberX[c] = best;
  }
  // the radius of the first arc in the trunk's own paths
  const arc = /A([\\d.]+)[ ,]/.exec([...g.querySelectorAll('[data-bundle-trunk]')].map(p => p.getAttribute('d') || '').join(' '));
  return {width: +band.getAttribute('stroke-width'), laneX, arcR: arc ? +arc[1] : null, span: run.length ? Math.max(...run) - Math.min(...run) : 0,
          ringGap, back, straps: s.querySelectorAll(`[data-strap="${id}"]`).length, memberX,
          shown: getComputedStyle(g.querySelector('[data-envelope]')).visibility === 'visible',
          strapXs: [...s.querySelectorAll(`[data-strap="${id}"] > line:not([data-strap-least])[data-strap-part="core"]`)].map(l => (+l.getAttribute('x1') + +l.getAttribute('x2')) / 2)};
}"""


def bundle_run_problems(geo, bend_mm, what):
    """The band's straight run, from the lane and the bend radius: the 10U trunk
    is 10 x 44.45 mm, and a turn of up to 90 degrees at each end takes at most
    one radius R off it (R tan(theta/2) <= R), less 1 mm for rounding. The
    trunk's arcs are the bundle's bend radius."""
    bad = []
    if not bend_mm or not geo["arcR"] or abs(geo["arcR"] - bend_mm) > 0.05:
        bad.append(f"2D: {what} turns on arcs of radius {geo['arcR']}, not the bundle's bend radius {bend_mm} mm")
        return bad
    least = 10 * 44.45 - 2 * bend_mm - 1
    if not (geo["laneX"] < -26) or geo["span"] < least:
        bad.append(f"2D: {what} does not run up the gutter for the 10U trunk (x {geo['laneX']}, span {geo['span']}, at least {least:.1f} for a lane less two {bend_mm} mm arcs)")
    return bad


@extra("rack.html: a bundle made from the cable list is drawn on the front pane as one band its size wide, with its straps, and a peeled cable leaves it (portrayal-site#142)")
def check_rack_bundle_2d_front(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_bundle_rack(page, base, "front")
    # Through the page's own controls: select c1, Bundle..., tick c2 and c3, name it.
    page.click('#cableList [data-cable-row="c1"]')
    page.click("#cableBundle")
    page.check("#bPick-c2")
    page.check("#bPick-c3")
    page.fill("#bLabel", "uplinks")
    page.click("#bCreate")
    page.wait_for_selector("#bundlePanel", timeout=READY_MS)
    doc = page.evaluate("() => window.__rack.doc().racks[0].bundles")
    if not doc or [m["cable"] for m in doc[0]["members"]] != ["c1", "c2", "c3"] or doc[0].get("label") != "uplinks":
        return bad + [f"create: the bundle was not stored as uplinks of c1-c3: {doc}"]
    page.wait_for_function("() => document.querySelector('#paneFront [data-bundle-id=\"b1\"] [data-bundle-trunk]')", timeout=READY_MS)
    facts = page.evaluate("() => window.__rack.bundles()")
    f = facts[0] if facts else None
    if not f or not f["checked"] or not f["diameter"]:
        return bad + [f"facts: the bundle was not checked for size: {facts}"]
    if f["diameter"] <= 6:
        return bad + [f"facts: three Cat6A come to {f['diameter']} mm, not above the 6 mm drawing floor - are the cable types loaded?"]
    geo = page.evaluate(BAND_GEO, ["paneFront", "b1"])
    if not geo:
        return bad + ["2D: no band for b1 on the front pane"]
    # The band is the bundle's diameter wide.
    if abs(geo["width"] - f["diameter"]) > 0.05:
        bad.append(f"2D: the band is {geo['width']} wide, not the bundle's {f['diameter']} mm")
    bad += bundle_run_problems(geo, f.get("bend_mm"), "the band")
    # At the ring the envelope is about the pack: every member's centre line within its half width less half a stroke.
    if geo["ringGap"] is None or geo["ringGap"] > geo["width"] / 2 - 1.5 + 0.5:
        bad.append(f"2D: at guide-1 a member's stroke is {geo['ringGap']} from the envelope's line, outside its half width {geo['width'] / 2}")
    # The bundle is selected (its panel is open), so its envelope shows.
    if not geo["shown"]:
        bad.append("2D: the selected bundle's envelope is not shown")
    if geo["straps"] != f["count"] or geo["straps"] < 2:
        bad.append(f"2D: {geo['straps']} straps drawn, the kit counts {f['count']}")
    # Combed inside the band: every member's run at U29 within the band's half width (plus a stroke).
    for c, x in geo["memberX"].items():
        if x is None or abs(x - geo["laneX"]) > geo["width"] / 2 + 1.5:
            bad.append(f"2D: {c} at U29 is at x {x}, outside the band at {geo['laneX']} (half width {geo['width'] / 2})")
    # The spacing, through the panel: 6 in gives more straps, drawn.
    page.fill("#bEvery", "6")
    page.press("#bEvery", "Enter")
    # (more SPACING straps: the count of every kind need not rise, since a breakout strap is left out where a
    # spacing strap already serves, kit 0.22.0)
    page.wait_for_function("n => (window.__rack.bundles() || [])[0]?.kinds.spacing > n", arg=f["kinds"]["spacing"], timeout=READY_MS)
    page.wait_for_function("() => document.querySelectorAll('#paneFront [data-strap=\"b1\"]').length === window.__rack.bundles()[0].count",
                           timeout=READY_MS)
    # Peel c3 at left-front U27 on: it leaves the band there for its b end, the nearer (sw-2 at U30).
    opts = page.eval_on_selector_all("#bPeelAt-c3 option", "os => os.map(o => [o.value, o.textContent])")
    at = next((v for v, t in opts if t == "from left-front U27"), None)
    if at is None:
        return bad + [f"peel: no 'from left-front U27' choice for c3: {opts}"]
    page.select_option("#bPeelAt-c3", at)
    page.click("#bPeel-c3")
    page.wait_for_function("() => window.__rack.doc().racks[0].bundles[0].members[2].b?.ru === 27", timeout=READY_MS)
    page.wait_for_function("() => (window.__rack.routes() || []).find(([id]) => id === 'c3')?.[1].every(w => !w.lane || w.ru <= 27)",
                           timeout=READY_MS)
    page.click("#bDone")
    page.wait_for_function("() => document.querySelector('#paneFront [data-bundle-id=\"b1\"]')", timeout=READY_MS)
    geo2 = page.evaluate(BAND_GEO, ["paneFront", "b1"])
    x3 = (geo2 or {}).get("memberX", {}).get("c3")
    if geo2 is None or (x3 is not None and abs(x3 - geo2["laneX"]) <= geo2["width"] / 2 + 1.5):
        bad.append(f"peel: c3 still rides the band at U29 after leaving at U27 ({geo2 and geo2['memberX']})")
    # THE LIST: the bundle's header, its summary with size and straps, members marked, c3's peel point.
    head = page.inner_text('#cableList [data-bundle-item="b1"]')
    # (the strap summary is "N straps every 6 in" when every strap is a spacing strap, and "N straps (a every 6 in, b where a
    # cable leaves)" when some are not: the kit counts a strap at the peel (0.28.0, straps on the routed path))
    if "uplinks" not in head or "about" not in head or not re.search(r"\d+ straps? (every 6 in|\(\d+ every 6 in)", head):
        bad.append(f"list: the bundle's header does not give its name, size and straps: {head!r}")
    order = page.eval_on_selector_all("#cableList ul > li", "ls => ls.map(l => l.dataset.bundleItem ? 'B' : l.dataset.cableItem)")
    if order[:4] != ["B", "c1", "c2", "c3"]:
        bad.append(f"list: the members do not follow their bundle's header: {order}")
    c3 = page.inner_text('#cableList [data-cable-item="c3"] [data-bundle-of]')
    if "In uplinks" not in c3 or "left-front U27 for its b end" not in c3:
        bad.append(f"list: c3's row does not say it leaves uplinks at left-front U27 for its b end: {c3!r}")
    # WHICH END A PEELED CABLE HEADS FOR is the kit's choice, the nearer port
    # (the page sends no end): c3 above left near the top for its b end, and
    # c2 leaving near the bottom, at U22, heads for its a end (sw-1 at U20).
    page.click('#cableList [data-bundle-row="b1"]')
    page.wait_for_selector("#bPeelAt-c2", timeout=READY_MS)
    opts = page.eval_on_selector_all("#bPeelAt-c2 option", "os => os.map(o => [o.value, o.textContent])")
    at = next((v for v, t in opts if t == "from left-front U22"), None)
    if at is None:
        return bad + [f"peel: no 'from left-front U22' choice for c2: {opts}"]
    page.select_option("#bPeelAt-c2", at)
    page.click("#bPeel-c2")
    page.wait_for_function("() => { const m = window.__rack.doc().racks[0].bundles[0].members[1]; return !!m.a || !!m.b; }", timeout=READY_MS)
    m2 = page.evaluate("() => window.__rack.doc().racks[0].bundles[0].members[1]")
    if (m2.get("a") or {}).get("ru") != 22 or m2.get("b") is not None:
        bad.append(f"peel: c2, leaving at U22, was not sent to its a end, the nearer: {m2}")
    page.click("#bDone")
    page.wait_for_selector('#cableList [data-cable-item="c2"] [data-bundle-of]', timeout=READY_MS)
    c2 = page.inner_text('#cableList [data-cable-item="c2"] [data-bundle-of]')
    if "left-front U22 for its a end" not in c2:
        bad.append(f"list: c2's row does not say it leaves uplinks at left-front U22 for its a end: {c2!r}")
    # Dissolving: no band, no header, the cables kept.
    page.click('#cableList [data-bundle-row="b1"]')
    page.click("#bRemove")
    page.wait_for_function("() => !document.querySelector('#paneFront [data-bundle-id]') && !document.querySelector('#cableList [data-bundle-item]')",
                           timeout=READY_MS)
    if page.evaluate("() => window.__rack.doc().racks[0].cables.length") != 3:
        bad.append("remove: dissolving the bundle removed cables")
    return bad


@extra("rack.html: a bundle on the mirrored rear pane is drawn there, through its ring with no hook, and not on the front (portrayal-site#142)")
def check_rack_bundle_2d_rear(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_bundle_rack(page, base, "rear")
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3']})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneRear [data-bundle-id=\"b1\"] [data-bundle-trunk]')", timeout=READY_MS)
    if page.evaluate("() => !!document.querySelector('#paneFront [data-bundle-id]')"):
        bad.append("2D: a rear bundle is drawn on the front pane")
    # NOTHING OF A BUNDLE ON A PANE NONE OF ITS CABLES RUN ON: no strap and no stretch of its envelope.
    # (The kit's rest height for a ring is the rack's, the same on either pane, and once placed a
    # rear lacer's ring on the front pane: bars floating over the front of the rack, and in the sheet.)
    stray = page.evaluate("""() => { const s = document.querySelector('#paneFront svg');
      return {strokes: s.querySelectorAll('[data-cables] [data-cable][data-cable-id]').length,
              straps: s.querySelectorAll('[data-strap]').length, stretches: s.querySelectorAll('[data-bundle-trunk]').length,
              rear: document.querySelectorAll('#paneRear svg [data-cables] [data-cable][data-cable-id]').length}; }""")
    if stray["rear"] != 3 or stray["strokes"]:
        bad.append(f"2D fixture: the cables are not all on the rear pane alone ({stray}), so a pane with no member stroke was not measured")
    if stray["straps"] or stray["stretches"]:
        bad.append(f"2D: the front pane, where no member runs, has {stray['straps']} straps and {stray['stretches']} envelope stretches")
    sheet = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      return (await X.sheetSvg(window.__rack.doc().racks[0], (await C.loadCatalog('/assets/dist/')).chassisOf)).data;
    }""")
    in_sheet = len(re.findall(r'data-strap="b1"', sheet))
    kit = page.evaluate("() => window.__rack.bundles()[0].count")
    if in_sheet != kit:
        bad.append(f"sheet: {in_sheet} straps drawn on the two faces, the kit counts {kit}")
    # THE SAME, WHERE IT BITES: cords from the middle of the switch ride two of the rear lacer's rings
    # together, a stretch from ring to ring. A ring's rest height alone once placed that stretch on the
    # front pane too (a lane node is never placed on the other face, so the cords above showed nothing).
    open_bundle_rack(page, base, "rear", ports=("port-25", "port-26", "port-27"))
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3']})")
    if res.get("error"):
        return bad + [f"create (two rings): refused: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneRear [data-bundle-id=\"b1\"] [data-bundle-trunk]') && window.__rack.routesCurrent().current", timeout=READY_MS)
    two = page.evaluate("""() => { const f = document.querySelector('#paneFront svg'), r = document.querySelector('#paneRear svg');
      const flat = [...r.querySelectorAll('[data-bundle-trunk]')].filter(p => { const [x0, y0, x1, y1] = p.getAttribute('d').match(/-?[\\d.]+(?:e-?\\d+)?/g).map(Number);
        return Math.abs(y1 - y0) < 0.5 && Math.abs(x1 - x0) > 20; }).length;
      return {flat, strokes: f.querySelectorAll('[data-cables] [data-cable][data-cable-id]').length,
              straps: f.querySelectorAll('[data-strap]').length, stretches: f.querySelectorAll('[data-bundle-trunk]').length}; }""")
    if not two["flat"] or two["strokes"]:
        bad.append(f"2D fixture (two rings): the rear pane has {two['flat']} ring-to-ring stretches and the front {two['strokes']} cable strokes, so the case was not measured")
    if two["straps"] or two["stretches"]:
        bad.append(f"2D (two rings): the front pane, where no member runs, has {two['straps']} straps and {two['stretches']} envelope stretches")
    f = page.evaluate("() => window.__rack.bundles()[0]")
    geo = page.evaluate(BAND_GEO, ["paneRear", "b1"])
    # The kit routes it up right-rear, which the mirrored rear pane draws on its left.
    bad += bundle_run_problems(geo, f.get("bend_mm"), "the rear band")
    if geo["ringGap"] is None or geo["ringGap"] > geo["width"] / 2 - 1.5 + 0.5:
        bad.append(f"2D: at guide-1 on the rear pane a member's stroke is {geo['ringGap']} from the envelope's line, outside its half width {geo['width'] / 2}")
    # Nothing is hovered or selected: the envelope is drawn, and hidden.
    if geo["shown"]:
        bad.append("2D: the rear bundle's envelope shows with nothing hovered or selected")
    if geo["back"] is None or geo["back"] > 0.05:
        bad.append(f"2D: the rear band hooks back {geo['back']} mm along x at guide-1 (pane flip lost?)")
    if geo["straps"] != f["count"]:
        bad.append(f"2D: {geo['straps']} straps on the rear pane, the kit counts {f['count']}")
    if f["diameter"] <= 6 or abs(geo["width"] - f["diameter"]) > 0.05:
        bad.append(f"2D: the rear band is {geo['width']} wide, not the bundle's {f['diameter']} mm (above the 6 mm floor)")
    return bad


# THE RACK BUILDER'S EARS ARE ON (Portrayal #909): a device modelled between
# its ear folds is drawn with a silver L-bracket over each rail, in 2D and 3D,
# and a blanking panel - whose ears are its own face, 482.6 mm wide - gets no
# second pair over the ones it draws. Both keep their screw heads, two per
# ear per U on the rail holes: 8 for the 2U switch and 8 for the 2U blank.
@extra("rack.html: rack ears are on - silver generic ears on a switch, none over a blank's built-in ears, in 2D and 3D (Portrayal #909)")
def check_rack_ears_default(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    rack = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Ears'});
      ({rack: r} = M.withItem(r, {ref: 's9600-72xc', cfg: cat['s9600-72xc'].default, ru: 20, face: 'front', label: 'agg-1'}));
      ({rack: r} = M.withItem(r, {ref: 'fhu-bps-2u', cfg: cat['fhu-bps-2u'].default, ru: 24, face: 'front', label: 'blank-1'}));
      return r;
    }""")
    # ONE FETCH PER FACE FILE: the pane draws the switch's front and the ear
    # plan reads that same file for its declared width (face.js earPlanFor).
    fronts = []
    count = lambda r: fronts.append(r.url) if re.search(r"/assets/dist/[^/]+\.front\.svg$", r.url) else None
    page.on("request", count)
    page.evaluate("r => window.__rack.replaceRack(r)", rack)
    page.wait_for_function("() => document.querySelector('#paneFront [data-item-id=\"i2\"][data-panel=\"mounted\"]')"
                           " && document.querySelector('#paneFront [data-item-id=\"i1\"][data-panel=\"mounted\"]')", timeout=READY_MS)
    page.wait_for_function("() => document.querySelector('#paneFront [data-ears-for=\"i1\"]')", timeout=READY_MS)
    page.wait_for_timeout(300)
    page.remove_listener("request", count)
    names = sorted(u.rsplit("/", 1)[1] for u in fronts)
    if len(names) != 2 or len(set(names)) != 2 or not any(n.startswith("s9600-72xc.") for n in names):
        bad.append(f"2D: the two devices' fronts were not each fetched once: {names}")
    got = page.evaluate("""() => {
      const p = document.querySelector('#paneFront');
      const e1 = p.querySelector('[data-ears-for="i1"]'), e2 = p.querySelector('[data-ears-for="i2"]');
      return {switch: !!e1, color: e1?.getAttribute('data-ear-color') ?? null,
              fills: e1 ? [...new Set([...e1.querySelectorAll('rect')].map(r => r.getAttribute('fill')))] : [],
              screws: e1 ? e1.querySelectorAll('circle').length : 0,
              blank: e2 ? e2.querySelectorAll('rect').length : null,
              blankScrews: e2 ? e2.querySelectorAll('circle').length : 0};
    }""")
    if not got["switch"]:
        bad.append(f"2D: the S9600-72XC has no rack ears in the Rack Builder: {got}")
    elif got["fills"] != ["#c8cacc"]:
        bad.append(f"2D: the S9600-72XC's ears are {got['fills']}, not silver #c8cacc")
    if got["screws"] != 8:
        bad.append(f"2D: the 2U S9600-72XC's ears carry {got['screws']} screws, expected 8 (2 per ear per U)")
    if got["blank"]:
        bad.append("2D: the FHU-BPS-2U blank, whose ears are built into its face, got a second pair drawn over them")
    if got["blankScrews"] != 8:
        bad.append(f"2D: the 2U FHU-BPS-2U blank is held by {got['blankScrews']} screws, expected 8 (2 per ear per U)")
    if webgl_trouble(page):
        print("[check_rack_ears_default] no WebGL here - checked the 2D half only")
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the ears' scene")
    g3 = page.evaluate("""async () => {
      const s = window.__rack.scene(), d = Date.now() + 60000;
      let w = s.three.scene;
      while (!(w.getObjectByName('device-i1') && w.getObjectByName('device-i2')) && Date.now() < d) {
        await new Promise(r => setTimeout(r, 200)); w = s.three.scene;
      }
      const e1 = w.getObjectByName('ears-i1'), e2 = w.getObjectByName('ears-i2');
      const mats = [], kinds = o => { const k = {box: 0, screw: 0};
        o?.traverse(m => { if (m.isMesh) k[m.geometry?.type === 'BoxGeometry' ? 'box' : 'screw']++; }); return k; };
      e1?.traverse(o => { if (o.isMesh && o.geometry?.type === 'BoxGeometry') mats.push(o.material.color.getHexString()); });
      const k1 = kinds(e1), k2 = kinds(e2);
      return {devices: !!(w.getObjectByName('device-i1') && w.getObjectByName('device-i2')),
              switch: k1.box, screws: k1.screw, colors: [...new Set(mats)], blank: k2.box, blankScrews: k2.screw};
    }""")
    if not g3["devices"]:
        return bad + [f"3D: the two devices never stood up: {g3}"]
    if not g3["switch"] or g3["colors"] != ["c8cacc"]:
        bad.append(f"3D: the S9600-72XC's ears are missing or not silver: {g3}")
    if g3["screws"] != 8:
        bad.append(f"3D: the 2U S9600-72XC's ears carry {g3['screws']} screws, expected 8")
    if g3["blank"]:
        bad.append("3D: the FHU-BPS-2U blank got generic ears over its built-in ones")
    if g3["blankScrews"] != 8:
        bad.append(f"3D: the 2U FHU-BPS-2U blank is held by {g3['blankScrews']} screws, expected 8")
    return bad


# HOVER DIMS THE REST (#169). Three Cat6A cables bundled as `uplinks` (b1)
# and a fourth on its own (c4). In 2D and then 3D, the pointer goes over c4 on
# the stage, over c2's row in the cable list and over the bundle's header row:
# each time exactly the lit set stays at full strength (c4; c2; b1's trunk,
# straps and members) and everything else is dimmed - classes and computed
# opacity on the panes, material opacity and depth writing in the scene. Moving
# off restores every element and material to what it was before the hover,
# exactly. An export taken mid-hover is undimmed: the sheet SVG carries no hover
# class, and the GLB's cable materials are opaque and its jacket at its own
# 0.45, while the scene stays dimmed for the pointer still over the row.
HOVER_2D_STATE = """() => {
  const out = {};
  for (const svg of document.querySelectorAll('#paneFront > svg, #paneRear > svg')) {
    const pane = svg.dataset.pane;
    out[pane + ':pane'] = svg.classList.contains('cable-hover');
    for (const n of svg.querySelectorAll('[data-cable-id], [data-bundle-id], [data-strap]')) {
      const id = n.dataset.cableId ?? n.dataset.bundleId ?? ('strap:' + n.dataset.strap);
      const kind = n.matches('[data-cable-tag]') ? 'tag' : n.matches('[data-strap]') ? 'strap' : n.matches('[data-bundle-id]') ? 'band' : 'cable';
      const k = `${pane}:${kind}:${id}`;
      const op = +getComputedStyle(n).opacity;
      const env = kind === 'band' ? n.querySelector('[data-envelope]') : null;
      (out[k] ||= []).push([n.classList.contains('hot'), Math.round(op * 100) / 100,
                            ...(kind === 'band' ? [!!env && getComputedStyle(env).visibility === 'visible'] : [])]);
    }
  }
  return out;
}"""
HOVER_3D_STATE = """() => {
  const w = window.__rack.scene().three.scene, out = {};
  for (const [name, prefix] of [['patch-cables', 'cable-'], ['cable-bundles', 'bundle-']]) {
    for (const g of w.getObjectByName(name)?.children ?? []) {
      const id = g.name.slice(prefix.length), mats = new Set(), env = [];
      // a bundle's envelope is shown or hidden, never dimmed: its tubes are read apart from the rest
      // ...and its straps too: they dim only when another bundle is the one lit
      const straps = new Set();
      g.traverse(o => { if (!o.isMesh) return; if (o.userData.envelope) { env.push(o.visible); return; }
        for (const m of [].concat(o.material)) (o.userData.strap ? straps : mats).add(m); });
      const read = set => [...set].map(m => [m.transparent, Math.round(m.opacity * 1000) / 1000, m.depthWrite]);
      if (prefix === 'cable-' || mats.size) out[prefix + id] = read(mats);
      if (prefix === 'bundle-') { out['envelope-' + id] = env; out['straps-' + id] = read(straps); }
    }
  }
  // each cable's plugs (#179): a device's meshes tagged with the port a cable ends at
  const port = e => e.item + '|' + String(e.path).split('-occupant')[0];
  for (const c of window.__rack.doc().racks[0].cables ?? []) {
    const keys = new Set([port(c.a), port(c.b)]), mats = new Set();
    for (const d of w.children) {
      if (!d.name.startsWith('device-')) continue;
      d.traverse(o => { if (o.isMesh && o.userData.portrayalPath && keys.has(d.name.slice(7) + '|' + String(o.userData.portrayalPath).split('-occupant')[0]))
        for (const m of [].concat(o.material)) mats.add(m); });
    }
    out['plugs-' + c.id] = [...mats].map(m => [m.transparent, Math.round(m.opacity * 1000) / 1000, m.depthWrite]);
  }
  return out;
}"""


def hover_fixture(page, base):
    open_bundle_rack(page, base, "front")
    r = page.evaluate("""async () => {
      const K = await import('/vendor/rack/cable-rules.js');
      let r = window.__rack.doc().racks[0];
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-24', view: 'front'}, b: {item: 'i3', path: 'port-24', view: 'front'}, media: 'cat6a'}));
      return r;
    }""")
    page.evaluate("r => window.__rack.replaceRack(r)", r)
    # A bundle command reads the routes of the rack as it is (rack-page.js
    # routesNow, kit 0.17.0): wait for the render after the replace to have
    # read them. Sent sooner it is refused, never worked out from the routes
    # of the rack before (check_rack_routes_follow_edits holds that).
    page.wait_for_function(ROUTES_CURRENT, timeout=READY_MS)
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'uplinks'})")
    page.wait_for_function("() => document.querySelector('#paneFront [data-bundle-id=\"b1\"] [data-bundle-trunk]')"
                           " && document.querySelector('#paneFront [data-cable-id=\"c4\"]')"
                           " && document.querySelector('#cableList [data-bundle-row=\"b1\"]')", timeout=READY_MS)
    page.wait_for_timeout(400)
    # THE TIE STRAPS OF SINGLE CABLES (kit 0.22.0) go with the cables they tie, as a bundle's straps go with its
    # members: each is lit while one of its cables is. Read from the page for this rack (route-context.js tieStraps).
    for k in [k for k in HOVER_MEMBERS if k.startswith("tie:")]:
        del HOVER_MEMBERS[k]
    for m in page.evaluate("() => window.__rack.tieStraps()"):
        HOVER_MEMBERS[f"tie:{m['item']}|{m['via']}|{m['tie']}"] = set(m["cables"])
    return res


HOVER_MEMBERS = {"b1": {"c1", "c2", "c3"}}


def hover_2d_dims(st, lit_cables, lit_bundles, members=HOVER_MEMBERS):
    """What is wrong with a 2D state for a hover lighting these. A bundle's
    envelope shows while the bundle is lit or a cable that rides it is; with
    neither, its group is dimmed and the envelope hidden."""
    bad = []
    if not st.get("front:pane"):
        bad.append("the front pane is not in hover (no .cable-hover)")
    for k, vals in st.items():
        if k.endswith(":pane"):
            continue
        _, kind, id_ = k.split(":", 2)
        if kind == "band":
            rides = bool(members.get(id_, set()) & set(lit_cables))
            for hot, op, shown in vals:
                if hot != (id_ in lit_bundles):
                    bad.append(f"{k} is hot={hot} with bundles {sorted(lit_bundles)} lit")
                if shown != (id_ in lit_bundles or rides):
                    bad.append(f"{k}'s envelope is {'shown' if shown else 'hidden'}; expected it shown only while the bundle or a member is lit")
                if (id_ in lit_bundles or rides) and op != 1:
                    bad.append(f"{k} should be at full strength, is opacity={op}")
                if not (id_ in lit_bundles or rides) and op > 0.2:
                    bad.append(f"{k} should be dimmed, is opacity={op}")
            continue
        # a strap goes with its bundle: lit while its bundle, or a cable that rides it, is lit
        lit = (id_[6:] in lit_bundles or bool(members.get(id_[6:], set()) & set(lit_cables))) if kind == "strap" else (id_ in lit_cables)
        for hot, op in vals:
            if lit and (not hot or op != 1):
                bad.append(f"{k} should stay lit, is hot={hot} opacity={op}")
            if not lit and (hot or op > 0.2):
                bad.append(f"{k} should be dimmed, is hot={hot} opacity={op}")
    return bad


def hover_3d_dims(st, base3, lit, members=HOVER_MEMBERS):
    bad = []
    for k, mats in st.items():
        if k.startswith("envelope-"):
            b = k[len("envelope-"):]
            want = f"bundle-{b}" in lit or any(f"cable-{c}" in lit for c in members.get(b, ()))
            if not mats or any(v != want for v in mats):
                bad.append(f"3D {k} is {mats}; expected {'shown' if want else 'hidden'} (shown only while the bundle or a member is lit)")
            continue
        if k.startswith("straps-"):
            b = k[len("straps-"):]
            # a strap goes with its bundle: lit while its bundle, or a cable that rides it, is lit
            dimmed = bool(lit) and f"bundle-{b}" not in lit and not any(f"cable-{c}" in lit for c in members.get(b, ()))
            for (tr, op, dw), (tr0, op0, dw0) in zip(mats, base3.get(k, [])):
                if not dimmed and (tr, op, dw) != (tr0, op0, dw0):
                    bad.append(f"3D {k} should be at full strength (its bundle or a member is lit), its material is {(tr, op, dw)}, was {(tr0, op0, dw0)}")
                if dimmed and (not tr or dw or op > op0 * 0.2 + 1e-6):
                    bad.append(f"3D {k} should be dimmed (another cable or bundle is lit), its material is {(tr, op, dw)}")
            continue
        lit_now = k in lit or (k.startswith("plugs-") and "cable-" + k[len("plugs-"):] in lit)
        for (tr, op, dw), (tr0, op0, dw0) in zip(mats, base3.get(k, [])):
            if lit_now:
                if (tr, op, dw) != (tr0, op0, dw0):
                    bad.append(f"3D {k} should stay lit, its material is {(tr, op, dw)}, was {(tr0, op0, dw0)}")
            elif not tr or dw or op > op0 * 0.2 + 1e-6:
                bad.append(f"3D {k} should be dimmed, its material is {(tr, op, dw)} (own opacity {op0})")
    return bad


def park_mouse(page):
    page.mouse.move(2, 2)       # the page header: over no pane, no scene, no list
    page.wait_for_timeout(350)  # a frame for the hover, the 120 ms fade


@extra("rack.html: hovering a cable or a bundle (stage, cable row, bundle row), or keyboard focus on a row, dims every other one in 2D and 3D, restores exactly on leave, and never reaches an export (#169)")
def check_rack_hover_dims(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    res = hover_fixture(page, base)
    if res and res.get("error"):
        return bad + [f"fixture: the bundle was not made: {res['error']}"]
    park_mouse(page)
    base2 = page.evaluate(HOVER_2D_STATE)
    if not any(k.startswith("front:band:b1") for k in base2) or "front:cable:c4" not in base2:
        return bad + [f"fixture: no band for b1 or no stroke for c4 on the front pane: {sorted(base2)}"]
    if any(shown for _, _, shown in base2["front:band:b1"]):
        bad.append("2D: b1's envelope shows with nothing hovered or selected")

    # 2D, the stage: a point on c4's own stroke, over no other cable.
    pt = page.evaluate("""() => {
      const svg = document.querySelector('#paneFront > svg');
      const g = svg.querySelector('[data-cables] [data-cable][data-cable-id="c4"]');
      const others = [...svg.querySelectorAll('[data-cables] [data-cable]:not([data-cable-id="c4"]) path, [data-cables] [data-bundle-id] path')];
      for (const p of g.querySelectorAll('path')) {
        const L = p.getTotalLength();
        for (let f = 0.5; f < 0.95; f += 0.05) {
          const q = p.getPointAtLength(L * f), m = p.getScreenCTM(), s = new DOMPoint(q.x, q.y).matrixTransform(m);
          if (others.some(o => o.isPointInStroke(new DOMPoint(s.x, s.y).matrixTransform(o.getScreenCTM().inverse())))) continue;
          if (document.elementFromPoint(s.x, s.y)?.closest('#paneFront')) return [s.x, s.y];
        }
      }
      return null;
    }""")
    if not pt:
        bad.append("2D: found no point on c4's stroke clear of the others to hover")
    else:
        page.mouse.move(pt[0], pt[1])
        page.wait_for_timeout(350)
        bad += [f"2D stage hover on c4: {m}" for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c4"}, set())]
        if page.evaluate("() => window.__rack.doc() && document.querySelector('#paneFront .rk-selected, #paneFront [data-cable-id].on')"):
            bad.append("2D stage hover on c4 selected something")
        park_mouse(page)
        if page.evaluate(HOVER_2D_STATE) != base2:
            bad.append("2D: leaving c4 did not restore every cable, tag, band and strap exactly")

    # 2D, a cable row, then the bundle's header row.
    page.hover('#cableList [data-cable-row="c2"]')
    page.wait_for_timeout(350)
    bad += [f"2D list hover on c2: {m}" for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c2"}, set())]
    park_mouse(page)
    if page.evaluate(HOVER_2D_STATE) != base2:
        bad.append("2D: leaving c2's row did not restore everything exactly")

    # THE KEYBOARD, with the pointer parked: the arrow keys onto a row and it
    # is lit as under the pointer. The list is a tree (#190): one Tab stop,
    # and Down and Up between its rows, which run b1's header, c1, c2, c3,
    # then the unbundled group and c4.
    at = "() => { const a = document.activeElement; return a?.dataset?.cableRow ?? a?.dataset?.bundleRow ?? a?.dataset?.cableItem ?? a?.dataset?.bundleItem ?? null; }"
    page.focus('#cableList [data-bundle-row="b1"]')
    page.keyboard.press("ArrowDown")
    page.wait_for_timeout(350)
    if page.evaluate(at) != "c1":
        bad.append(f"2D keyboard: Down from b1's header did not reach c1's row ({page.evaluate(at)!r}), so focus was not measured")
    else:
        bad += [f"2D keyboard focus on c1: {m}" for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c1"}, set())]
        page.keyboard.press("ArrowDown")
        page.wait_for_timeout(350)
        bad += [f"2D keyboard focus on {page.evaluate(at)}, after c1: {m}"
                for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c2"}, set())]
        page.keyboard.press("ArrowUp")
        page.keyboard.press("ArrowUp")
        page.wait_for_timeout(350)
        if page.evaluate(at) != "b1":
            bad.append(f"2D keyboard: Up twice from c2 did not reach b1's header ({page.evaluate(at)!r})")
        bad += [f"2D keyboard focus on {page.evaluate(at)}, the bundle's header: {m}"
                for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c1", "c2", "c3"}, {"b1"})]
        # The pointer over another row outranks the focused one, and gives it back on leaving.
        page.hover('#cableList [data-cable-row="c4"]')
        page.wait_for_timeout(350)
        bad += [f"2D pointer on c4 with focus on b1: {m}" for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c4"}, set())]
        park_mouse(page)
        bad += [f"2D pointer gone, focus still on b1: {m}"
                for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c1", "c2", "c3"}, {"b1"})]
        # The pointer over an empty part of the stage does not end it either: focus is still on the row.
        empty = page.evaluate("""async () => {
          const H = await import('/site/rack/hover.js');
          const svg = document.querySelector('#paneFront > svg'), r = svg.getBoundingClientRect();
          for (let fy = 0.1; fy < 0.95; fy += 0.07) for (let fx = 0.3; fx < 0.75; fx += 0.07) {
            const x = r.left + r.width * fx, y = r.top + r.height * fy, el = document.elementFromPoint(x, y);
            if (el?.closest('#paneFront') && !H.hoverAt2d(svg, {clientX: x, clientY: y, target: el})) return [x, y];
          }
          return null; }""")
        if not empty:
            bad.append("2D: found no empty point on the front pane to move the pointer over")
        else:
            page.mouse.move(empty[0], empty[1])
            page.wait_for_timeout(350)
            bad += [f"2D pointer over empty stage, focus still on b1: {m}"
                    for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c1", "c2", "c3"}, {"b1"})]
            park_mouse(page)
            bad += [f"2D pointer off the stage, focus still on b1: {m}"
                    for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c1", "c2", "c3"}, {"b1"})]
        if page.evaluate("() => !!document.querySelector('#cableList [aria-pressed=\"true\"]')"):
            bad.append("2D keyboard: focus pressed a row in the list (focus must not select)")
        # Focus moved off the rows (to the control before the list) ends it.
        page.keyboard.press("Shift+Tab")
        page.wait_for_timeout(350)
        if page.evaluate(at) is not None or page.evaluate(HOVER_2D_STATE) != base2:
            bad.append(f"2D keyboard: focus leaving the rows (now on {page.evaluate(at)!r}) did not restore everything exactly")
    # A row clicked with the mouse keeps focus, with no ring: it is not held
    # lit once the pointer has gone. (The click selects c4; a second puts it back.)
    page.click('#cableList [data-cable-row="c4"]')
    park_mouse(page)
    held = page.evaluate("() => [document.activeElement?.dataset?.cableRow ?? null, !!document.querySelector('#paneFront > svg.cable-hover')]")
    if held != ["c4", False]:
        bad.append(f"2D mouse: after a click on c4's row and the pointer gone, [focused row, panes in hover] is {held}, expected ['c4', False]")
    page.click('#cableList [data-cable-row="c4"]')
    page.wait_for_function("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')", timeout=READY_MS)
    page.evaluate("() => document.activeElement?.blur()")
    park_mouse(page)
    if page.evaluate(HOVER_2D_STATE) != base2:
        bad.append("2D mouse: selecting c4 and putting it back did not leave everything as it was")

    page.hover('#cableList [data-bundle-row="b1"]')
    page.wait_for_timeout(350)
    bad += [f"2D bundle row hover on b1: {m}" for m in hover_2d_dims(page.evaluate(HOVER_2D_STATE), {"c1", "c2", "c3"}, {"b1"})]
    # An export taken now is the rack, not the hover.
    sheet = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      return (await X.sheetSvg(window.__rack.doc().racks[0], of, {date: new Date(2026, 0, 2)})).data;
    }""")
    if "cable-hover" in sheet or re.search(r'class="[^"]*\bhot\b', sheet):
        bad.append("2D: the sheet SVG exported mid-hover carries the hover's classes")
    if 'data-bundle-id="b1"' not in sheet or 'data-cable-id="c4"' not in sheet:
        bad.append("2D: the sheet SVG exported mid-hover has no b1 band or no c4: nothing was measured")
    park_mouse(page)
    if page.evaluate(HOVER_2D_STATE) != base2:
        bad.append("2D: leaving the bundle row did not restore everything exactly")
    if page.evaluate("() => window.__rack.doc().racks[0] && document.querySelector('#cableList [aria-pressed=\"true\"]')"):
        bad.append("2D: a hover pressed a row in the list (hover must not select)")

    if webgl_trouble(page):
        print("[check_rack_hover_dims] no WebGL here - checked the 2D half only")
        return bad
    page.click('#mode [data-mode="3d"]')
    page.wait_for_function("""() => { const s = window.__rack.scene(); const w = s?.three.scene;
      return w && w.getObjectByName('cable-c4') && w.getObjectByName('bundle-b1'); }""", timeout=READY_3D_MS)
    settle_scene(page, "3D: the hover rack's scene", tubes=True)
    park_mouse(page)
    base3 = page.evaluate(HOVER_3D_STATE)
    if not base3.get("straps-b1") or not base3.get("cable-c4") or not base3.get("envelope-b1"):
        return bad + [f"3D: no tubes for c4, or no straps or no envelope for b1: {sorted(base3)}"]
    if not all(base3.get(f"plugs-{c}") for c in ("c1", "c4")):
        bad.append(f"3D: found no plug meshes for c1 or c4 (a plug is a device mesh tagged with its port): {sorted(k for k in base3 if k.startswith('plugs-'))}")
    if any(base3["envelope-b1"]):
        bad.append("3D: b1's envelope shows with nothing hovered or selected")

    # 3D, the stage: a point on c4's tube that a ray reaches first.
    pt = page.evaluate("""() => {
      const s = window.__rack.scene(), {THREE, scene: w, camera, renderer} = s.three;
      const g = w.getObjectByName('cable-c4'), mesh = g.children.find(o => o.isMesh);
      const r = renderer.domElement.getBoundingClientRect(), pos = mesh.geometry.attributes.position, v = new THREE.Vector3();
      const targets = [w.getObjectByName('patch-cables'), w.getObjectByName('cable-bundles')].filter(Boolean);
      const ray = new THREE.Raycaster();
      for (let k = Math.floor(pos.count / 2); k < pos.count; k += 37) {
        v.fromBufferAttribute(pos, k).applyMatrix4(mesh.matrixWorld).project(camera);
        if (Math.abs(v.x) > 0.95 || Math.abs(v.y) > 0.95) continue;
        ray.setFromCamera(new THREE.Vector2(v.x, v.y), camera);
        const hit = ray.intersectObjects(targets, true)[0];
        let o = hit?.object; while (o && o.parent && o.parent.name !== 'patch-cables') o = o.parent;
        if (o?.name !== 'cable-c4') continue;
        const x = r.left + (v.x + 1) / 2 * r.width, y = r.top + (1 - v.y) / 2 * r.height;
        if (document.elementFromPoint(x, y) === renderer.domElement) return [x, y];
      }
      return null;
    }""")
    if not pt:
        bad.append("3D: found no point on c4's tube in front of the others to hover")
    else:
        page.mouse.move(pt[0], pt[1])
        page.wait_for_timeout(350)
        bad += [f"3D stage hover on c4: {m}" for m in hover_3d_dims(page.evaluate(HOVER_3D_STATE), base3, {"cable-c4"})]
        park_mouse(page)
        if page.evaluate(HOVER_3D_STATE) != base3:
            bad.append("3D: leaving c4's tube did not restore every material exactly")

    page.hover('#cableList [data-cable-row="c2"]')
    page.wait_for_timeout(350)
    bad += [f"3D list hover on c2: {m}" for m in hover_3d_dims(page.evaluate(HOVER_3D_STATE), base3, {"cable-c2"})]
    park_mouse(page)
    if page.evaluate(HOVER_3D_STATE) != base3:
        bad.append("3D: leaving c2's row did not restore every material exactly")
    # The keyboard in 3D: Down from the bundle's header onto c1's row, then focus gone.
    page.focus('#cableList [data-bundle-row="b1"]')
    page.keyboard.press("ArrowDown")
    page.wait_for_timeout(350)
    if page.evaluate("() => document.activeElement?.dataset?.cableRow ?? document.activeElement?.dataset?.cableItem ?? null") != "c1":
        bad.append("3D keyboard: Down from b1's header did not reach c1's row, so focus was not measured")
    else:
        bad += [f"3D keyboard focus on c1: {m}" for m in hover_3d_dims(page.evaluate(HOVER_3D_STATE), base3, {"cable-c1"})]
    page.evaluate("() => document.activeElement?.blur()")
    page.wait_for_timeout(350)
    if page.evaluate(HOVER_3D_STATE) != base3:
        bad.append("3D keyboard: focus leaving c1's row did not restore every material exactly")

    page.hover('#cableList [data-bundle-row="b1"]')
    page.wait_for_timeout(350)
    lit_b = {"cable-c1", "cable-c2", "cable-c3", "bundle-b1"}
    bad += [f"3D bundle row hover on b1: {m}" for m in hover_3d_dims(page.evaluate(HOVER_3D_STATE), base3, lit_b)]
    # A GLB taken now: its materials as the rack has them, and the scene dimmed again after.
    glb = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      const out = await X.modelFile(window.__rack.scene(), window.__rack.doc().racks[0], 'glb', of);
      const buf = out.data instanceof ArrayBuffer ? out.data : await new Response(out.data).arrayBuffer();
      const dv = new DataView(buf), len = dv.getUint32(12, true);
      const j = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 20, len)));
      const mats = n => {
        const node = j.nodes.findIndex(x => x.name === n), seen = [];
        const walk = i => { const x = j.nodes[i]; if (x.mesh != null) for (const p of j.meshes[x.mesh].primitives) seen.push(j.materials[p.material]);
                            for (const c of x.children ?? []) walk(c); };
        if (node >= 0) walk(node);
        return seen.map(m => [m.alphaMode ?? 'OPAQUE', m.pbrMetallicRoughness?.baseColorFactor?.[3] ?? 1]);
      };
      return {c4: mats('cable-c4'), c1: mats('cable-c1'), b1: mats('bundle-b1-trunk'), strap: mats('bundle-b1-strap-0')};
    }""")
    if not glb["c4"] or not glb["strap"]:
        bad.append(f"GLB mid-hover: no c4 or b1 strap to read: {glb}")
    if any(a != "OPAQUE" or op != 1 for a, op in glb["c4"] + glb["c1"] + glb["strap"]):
        bad.append(f"GLB mid-hover: a cable's or a strap's material is dimmed in the file: c4 {glb['c4']}, c1 {glb['c1']}, strap {glb['strap']}")
    # The envelope is the page's, shown for the hover: the file is the rack, and carries none.
    if glb["b1"]:
        bad.append(f"GLB mid-hover: the bundle's envelope is in the file: {glb['b1']}")
    bad += [f"3D after the GLB, still over b1's row: {m}" for m in hover_3d_dims(page.evaluate(HOVER_3D_STATE), base3, lit_b)]
    park_mouse(page)
    if page.evaluate(HOVER_3D_STATE) != base3:
        bad.append("3D: leaving the bundle row did not restore every material exactly")
    return bad


# A CORD'S SPARE IS SAID (site/rack/spare.js). The page draws the path a cable
# takes and nothing more, so on the reference rack c4, a 0.5 m cord, and c12, a
# 1 m cord, look alike: their paths are 130 mm apart and their cords half a
# metre. The cable list says each cord and its spare, and in one line what the
# drawing shows; no row is marked for having much spare. A cable under the
# pointer says the same two figures beside it, in 2D and in 3D. A length
# entered in feet says both in feet. An entered cord under what its route
# needs (the kit's `need`: rack file version 4, kit 0.22.0) says so as a
# warning (0.2 m on c4's route); one that meets the need has spare and no
# warning, however little (0.5 m on c16's route, which needs about 0.4 m; a
# 3 ft cord on c12's). Until 0.22.0 the need held the 0.2 m of end play, so
# 0.5 m on c16's route warned "without dressing room".
#
# THE EXPECTED SPARE is worked here by another road than spare.js takes, which
# asks the kit's spareOf: each path's points added up (window.__rack.paths),
# what is inside the port at each end (END_ALLOWANCE_BY_MEDIA) and the maker's
# short tolerance, taken from the cord's length. THE KIT'S OWN (spareOf, by
# the page's route context) is read beside it, and the two must agree: this is
# where a page that still took the dressing as `endAllowance` less the table
# would say 0.2 m less spare for every cord. No figure is written down here,
# so a plug drawn deeper moves both.
SPARE_WANT_JS = """async () => {
  const R = await import('/vendor/rack/route.js');
  const rack = window.__rack.doc().racks[0], paths = window.__rack.paths() || {};
  const PER = {m: 1, ft: 0.3048}, r2 = x => Math.round(x * 100) / 100, out = {};
  for (const c of rack.cables) {
    const p = paths[c.id], l = c.length;
    if (!p || !l || !PER[l.unit ?? 'm']) { out[c.id] = null; continue; }
    let mm = 0;
    for (let k = 1; k < p.points.length; k++)
      mm += Math.hypot(p.points[k].x - p.points[k - 1].x, p.points[k].y - p.points[k - 1].y, p.points[k].z - p.points[k - 1].z);
    const unit = l.unit ?? 'm', cord = l.value * PER[unit];
    const need = mm / 1000 + 2 * R.END_ALLOWANCE_BY_MEDIA[c.media] + R.shortTolerance(c, cord);
    const spare = cord - need;
    const kit = R.spareOf(rack, c, window.__rack.routeContext());
    // one rounding rule, the kit's: each figure to the nearest hundredth, as the schedule's cell says it
    const up = x => Math.round(x * 100) / 100, short = spare < -1e-9;
    const shown = up(Math.abs(spare) / PER[unit]);
    // a length that is not the page's own measurement, under what the cord must at least be
    const under = l.source !== 'routed' && cord < need - 1e-9;
    const text = `${l.value} ${unit} cord, ${shown} ${unit} ${short ? 'short' : 'spare'}`;
    const asks = under ? `the route needs ${up(need / PER[unit])} ${unit}` : null;
    out[c.id] = {value: l.value, unit, source: l.source, stock: p.value, measured: p.measured, need, path_mm: Math.round(mm), spare,
      kit: kit && {spare: kit.spare_m, need: kit.need_m, stock: kit.stock_m, end_play: kit.end_play_m}, end_play: R.END_PLAY_M,
      text, asks, short: asks ? [`${text}; ${asks}.`] : []};
  }
  return out;
}"""
SPARE_LIST_JS = """() => ({
  help: [...document.querySelectorAll('#cableList [data-spare-help]')].map(p => p.textContent),
  toasts: [...document.querySelectorAll('.rk-side .rk-notice')].map(p => p.textContent),
  rows: Object.fromEntries([...document.querySelectorAll('#cableList li[data-cable-item]')].map(li => [li.dataset.cableItem, {
    meta: li.querySelector('.rk-cable-meta')?.textContent ?? '',
    marks: li.querySelectorAll('[data-spare-note], [data-spare-large], .rk-spare-note').length + (li.dataset.spareLarge != null ? 1 : 0),
    short: [...li.querySelectorAll('[data-spare-short]')].map(n => n.textContent),
    shortWarns: [...li.querySelectorAll('[data-spare-short]')].every(n => n.classList.contains('rk-warn'))}])),
  titles: Object.fromEntries([...document.querySelectorAll('#paneFront svg [data-cables] [data-cable][data-cable-id]')]
    .map(g => [g.dataset.cableId, g.querySelector('title')?.textContent ?? '']))})"""
SPARE_TIP_JS = """() => { const t = document.getElementById('cableTip');
  if (!t || t.hidden) return null;
  const r = t.getBoundingClientRect();
  return {id: t.dataset.cableTip ?? null, text: t.textContent, meta: t.querySelector('[data-tip-meta]')?.textContent ?? '',
          short: t.querySelector('[data-tip-short]')?.textContent ?? null,
          shown: r.width > 0 && r.height > 0 && r.right <= innerWidth && r.bottom <= innerHeight && getComputedStyle(t).display !== 'none'}; }"""
# A point of the window where the page's own hover finds this cable: on its 2D stroke...
SPARE_PT_2D_JS = """async id => {
  const H = await import('/site/rack/hover.js');
  const svg = document.querySelector('#paneFront > svg');
  const g = svg.querySelector(`[data-cables] [data-cable][data-cable-id="${id}"]`);
  if (!g) return null;
  g.scrollIntoView({block: 'center'});
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
  for (const p of g.querySelectorAll('path')) {
    const L = p.getTotalLength();
    for (let f = 0.05; f < 0.96; f += 0.03) {
      const q = p.getPointAtLength(L * f), s = new DOMPoint(q.x, q.y).matrixTransform(p.getScreenCTM());
      const at = document.elementFromPoint(s.x, s.y);
      if (!at?.closest('#paneFront')) continue;
      if (H.hoverAt2d(svg, {clientX: s.x, clientY: s.y, target: at})?.id === id) return [s.x, s.y];
    }
  }
  return null;
}"""
# ...and on its 3D tube, where a ray reaches it before any other.
SPARE_PT_3D_JS = """async id => {
  const H = await import('/site/rack/hover.js');
  const s = window.__rack.scene(), {THREE, scene: w, camera, renderer} = s.three;
  const g = w.getObjectByName('cable-' + id), r = renderer.domElement.getBoundingClientRect(), v = new THREE.Vector3();
  if (!g) return null;
  let edge = null;
  const meshes = []; g.traverse(o => { if (o.isMesh) meshes.push(o); });
  for (const mesh of meshes) {
    const pos = mesh.geometry.attributes.position;
    for (let k = 0; k < pos.count; k += 7) {
      v.fromBufferAttribute(pos, k).applyMatrix4(mesh.matrixWorld).project(camera);
      if (Math.abs(v.x) > 0.95 || Math.abs(v.y) > 0.95) continue;
      const x = r.left + (v.x + 1) / 2 * r.width, y = r.top + (1 - v.y) / 2 * r.height;
      if (document.elementFromPoint(x, y) !== renderer.domElement) continue;
      // WELL INSIDE THE TUBE, NOT ON ITS EDGE: a vertex on the tube's silhouette is under the pointer in one frame
      // and beside it in the next (the camera eases by a fraction of a pixel long after an orbit), so the ray must
      // find this cable a pixel to each side too. The first such point is taken; with none, the first that hits.
      const on = (dx, dy) => { const t = H.hoverAt3d(s, {clientX: x + dx, clientY: y + dy}); return t?.kind === 'cable' && t.id === id; };
      if (!on(0, 0)) continue;
      if (on(1, 0) && on(-1, 0) && on(0, 1) && on(0, -1)) return [x, y];
      edge ??= [x, y];
    }
  }
  return edge;
}"""


# THE CAMERA AT REST. A settled scene is not a still camera: after an orbit the controls ease it for as many FRAMES
# as it takes (damping), which is many seconds where a frame takes a tenth of a second or more, and a point found on a
# cable while it eases is a few pixels from that cable by the time the pointer reaches it (the label shows the
# cable beside it, or none). Where it comes to rest also depends on how many frames the easing ran, so a cable that
# shows well in one run lies behind its neighbours in the next. The check turns the easing off before it orbits
# (the label under test is the page's, not the controls'), so the view stops where the pointer lets go, and waits
# until three frames in a row moved the camera under 0.05 mm each or `ms` pass. True when it is still.
CAMERA_REST_JS = """async ms => {
  const s = window.__rack.scene();
  if (!s?.three) return true;
  const {camera, renderer, controls} = s.three, sleep = t => new Promise(r => setTimeout(r, t));
  controls.enableDamping = false;
  const deadline = Date.now() + ms, last = camera.position.clone();
  let frame = renderer.info.render.frame, calm = 0;
  while (Date.now() < deadline) {
    await sleep(100);
    const f = renderer.info.render.frame;
    if (f === frame) continue;
    calm = camera.position.distanceTo(last) / (f - frame) < 0.05 ? calm + 1 : 0;
    last.copy(camera.position); frame = f;
    if (calm >= 3) return true;
  }
  return false;
}"""


def spare_hover(page, bad, where, find_js, cid, want, drag=None):
    """Put the pointer on `cid` and read the label beside it against `want`. With
    `drag`, a button held and let go hides it until the pointer next moves."""
    # THE POINT IS FOUND ON THE SCENE AS IT STANDS, and in 3D the camera eases on for a moment after an orbit (the
    # c4 step before c12's drags one): a point found while it still moves may not be under the cable once the
    # pointer gets there. The label is the pointer's, on a move, so the point is found again, up to three times,
    # until the pointer put on it shows the label. A cable whose label never shows still fails below.
    pt = None
    for attempt in range(3):
        if find_js is SPARE_PT_3D_JS:
            page.evaluate(CAMERA_REST_JS, 30000)
        pt = page.evaluate(find_js, cid)
        if not pt:
            break
        page.mouse.move(pt[0] - 3, pt[1] - 3)
        page.mouse.move(pt[0], pt[1])
        try:
            wait_fn(page, f"{where}: {cid}'s hover label", "id => document.getElementById('cableTip')?.dataset.cableTip === id", arg=cid, timeout=10000 if attempt == 2 else 2500)
            break
        except RuntimeError:
            park_mouse(page)
            page.wait_for_timeout(600)
    if not pt:
        bad.append(f"{where}: found no point where the page's hover finds {cid}, so its label was not read")
        return
    tip = page.evaluate(SPARE_TIP_JS)
    if not tip or tip["id"] != cid:
        # (what the page's own hover finds at that point, and what is under it, so a red says why the label did not come)
        seen = page.evaluate("""async ([x, y]) => {
          const H = await import('/site/rack/hover.js'), s = window.__rack.scene?.();
          const el = document.elementFromPoint(x, y);
          return {hover: s ? H.hoverAt3d(s, {clientX: x, clientY: y}) : 'no scene', under: el ? el.tagName + '#' + el.id : null,
                  tip: document.getElementById('cableTip')?.dataset.cableTip ?? null};
        }""", pt) if find_js is SPARE_PT_3D_JS else None
        bad.append(f"{where}: the pointer on {cid} shows no label for it: {tip}" + (f" (at {pt}: {seen})" if seen else ""))
    else:
        if want["text"] not in tip["meta"]:
            bad.append(f"{where}: {cid}'s hover label says {tip['meta']!r}, expected it to carry {want['text']!r}")
        if not tip["shown"]:
            bad.append(f"{where}: {cid}'s hover label is not laid out inside the window: {tip}")
        asks = want["asks"] and want["asks"][0].upper() + want["asks"][1:] + "."
        if tip["short"] != asks:
            bad.append(f"{where}: {cid}'s hover label says {tip['short']!r} of what the route asks for, expected {asks!r}")
        if drag is not None:
            # `drag` is how far the pointer goes with the button down: an orbit in
            # 3D; on a pane 0, a press and release in place, which moves nothing.
            page.mouse.down()
            if drag > 1:
                page.mouse.move(pt[0] + drag, pt[1] + drag / 4, steps=4)
            page.wait_for_timeout(300)
            held = page.evaluate(SPARE_TIP_JS)
            page.mouse.up()
            page.wait_for_timeout(300)
            let_go = page.evaluate(SPARE_TIP_JS)
            if held or let_go:
                bad.append(f"{where}: the hover label stays through a drag (button down: {held}, let go: {let_go})")
            # ...and it comes back with the next free move over a cable.
            if drag > 1:
                settle_scene(page, f"{where}: the scene after the orbit", tubes=True)
                page.evaluate(CAMERA_REST_JS, 30000)
            # (found again up to three times, as the first point is: where two cables lie close in 3D (c4 and c8 in ring 4
            # since the ring is chosen by room, kit 0.27.0) a point found while the camera still eases may be under the
            # other one by the time the pointer gets there)
            back = None
            for attempt in range(3):
                back = page.evaluate(find_js, cid)
                if not back:
                    break
                page.mouse.move(back[0] - 3, back[1] - 3)
                page.mouse.move(back[0], back[1])
                try:
                    wait_fn(page, f"{where}: {cid}'s label back", "id => { const t = document.getElementById('cableTip'); return t && !t.hidden && t.dataset.cableTip === id; }",
                            arg=cid, timeout=10000 if attempt == 2 else 2500)
                    break
                except RuntimeError:
                    if attempt == 2:
                        bad.append(f"{where}: the hover label does not come back on {cid} with the next move after a drag: {page.evaluate(SPARE_TIP_JS)}")
                    else:
                        park_mouse(page)
                        page.wait_for_timeout(600)
            if not back:
                bad.append(f"{where}: found no point on {cid} after the drag, so the label's return was not read")
    park_mouse(page)
    if page.evaluate(SPARE_TIP_JS):
        bad.append(f"{where}: the hover label stays after the pointer has left {cid}")


# A drawing's own <title>s name its parts by drawing id ("port-24--jack"). The
# page imports the drawings whole, so a hover on a jack under a cable showed
# one as a browser tooltip (#186). None reaches the stage: the page's own
# labels (a cable's, its tag's, an item's) are the page's, a child of the
# group it made, never of the drawing's parts.
PART_TITLES = """() => [...document.querySelectorAll('#panes svg [data-item-id], #panes svg [data-zerou-id]')]
  .flatMap(g => [...g.querySelectorAll('title')].filter(t => t.parentElement !== g).map(t => t.textContent))"""


@extra("rack.html: no drawing's native <title> (a raw part path such as port-24--jack) reaches the stage in Front / Rear or Left / Right, so a hover over a port under a cable shows none (#186)")
def check_rack_no_part_titles(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_side_fixture(page, base)
    if not page.evaluate("() => document.querySelectorAll('#panes svg [data-item-id]').length"):
        return bad + ["fixture: no item is drawn on the panes"]
    got = page.evaluate(PART_TITLES)
    if got:
        bad.append(f"Front / Rear: {len(got)} part titles on the stage, e.g. {got[:3]}")
    to_sides(page)
    got = page.evaluate(PART_TITLES)
    if got:
        bad.append(f"Left / Right: {len(got)} part titles on the stage, e.g. {got[:3]}")
    return bad


@extra("rack.html: each routed cable says its cord and its spare in the list with no row marked for it, an entered cord under what its route needs warns, and the hover label carries the figures in 2D and 3D, in the cable's own unit")
def check_rack_cable_spare(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    page.add_init_script(STAND_IN_MODEL_CONTEXT)     # the agent's tools, to read inspect's text
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    load_rack_3d_ready(page, base, rack)
    wait_fn(page, "spare: the reference rack's routes", ROUTES_CURRENT)
    wait_fn(page, "spare: every row says a spare",
            "() => document.querySelectorAll('#cableList .rk-cable-meta[data-spare]').length === 16")
    park_mouse(page)
    want = page.evaluate(SPARE_WANT_JS)
    if len(want) != 16 or any(w is None for w in want.values()):
        return bad + [f"spare: not every one of the 16 cords has a path and a length to work from: {want}"]
    # THE TWO CORDS OF THE REPORT: c4 a 0.5 m cord, c12 a 1 m cord, both the kit's stock size.
    for cid, cord in (("c4", 0.5), ("c12", 1)):
        w = want[cid]
        if (w["value"], w["unit"], w["source"], w["stock"]) != (cord, "m", "routed", cord):
            bad.append(f"{cid}: not a routed {cord} m cord: {w}")
    if not (want["c4"]["spare"] > 0 and want["c12"]["spare"] > want["c4"]["spare"]):
        bad.append(f"the 1 m cord on the longer path should have the larger spare: c4 {want['c4']['spare']}, c12 {want['c12']['spare']}")
    if any(w["asks"] for w in want.values()):
        bad.append(f"fixture: a routed cord is under the size its route asks for: {[c for c, w in want.items() if w['asks']]}")
    # THE SPARE IS THE KIT'S: for every cord, the figure worked here from the path is the kit's spareOf, its need
    # the kit's need, and a routed cord has its end play in the spare (to the 10 mm stock break), not taken off it.
    for cid, w in want.items():
        k = w["kit"]
        if not k or abs(k["spare"] - w["spare"]) > 1e-9 or abs(k["need"] - w["need"]) > 1e-9 or k["stock"] != w["value"]:
            bad.append(f"{cid}: the kit's spareOf is {k}, the path gives spare {w['spare']} and need {w['need']} for a {w['value']} m cord")
        if w["spare"] < 2 * w["end_play"] - 0.01 - 1e-9:
            bad.append(f"{cid}: a routed cord with {w['spare']:.4f} m spare has less than its end play ({2 * w['end_play']} m, less the 10 mm break)")
        if abs(w["measured"] - (w["need"] + 2 * w["end_play"])) > 1e-9:
            bad.append(f"{cid}: the kit's measured ({w['measured']}) is not its need ({w['need']}) and the end play at both ends")

    def read_list(where, ids=None):
        got = page.evaluate(SPARE_LIST_JS)
        for cid, w in sorted(want.items(), key=lambda kv: int(kv[0][1:])):
            if ids is not None and cid not in ids:
                continue
            row = got["rows"].get(cid)
            if not row:
                bad.append(f"{where}: no row for {cid}")
                continue
            if not row["meta"].endswith(w["text"]):
                bad.append(f"{where}: {cid} ({w['path_mm']} mm path, {w['measured']} m measured) says {row['meta']!r}, expected it to end {w['text']!r}")
            # NO ROW IS MARKED FOR ITS SPARE: 14 of these 16 cords are more spare than path, and none is a fault.
            if row["marks"]:
                bad.append(f"{where}: {cid}'s row carries a spare mark ({row['marks']})")
            # ...and only an entered cord under the size its route asks for warns.
            if row["short"] != w["short"] or not row["shortWarns"]:
                bad.append(f"{where}: {cid} ({w['value']} {w['unit']} {w['source']}, the kit's size {w['stock']} m) warns {row['short']}, expected {w['short']}")
        if len(got["help"]) != 1 or "path" not in got["help"][0] or not got["help"][0].endswith("is not drawn."):
            bad.append(f"{where}: the list's one line on what the drawing shows is {got['help']}")
        if any("not drawn" in t for t in got["toasts"]):
            bad.append(f"{where}: the spare is said in a notice, not only in the list: {got['toasts']}")
        return got
    got = read_list("2D list")
    for cid in ("c4", "c12"):
        if want[cid]["text"] not in got["titles"].get(cid, ""):
            bad.append(f"2D: {cid}'s title on the pane is {got['titles'].get(cid)!r}, without {want[cid]['text']!r}")
    for cid in ("c4", "c12"):
        spare_hover(page, bad, "2D hover", SPARE_PT_2D_JS, cid, want[cid])
    # Over a row of the list, the row says it: no second label.
    page.hover('#cableList [data-cable-row="c4"]')
    page.wait_for_timeout(350)
    if page.evaluate(SPARE_TIP_JS):
        bad.append("2D: the pointer on c4's row in the list shows the stage's hover label too")
    park_mouse(page)

    # THE AGENT'S TEXT: inspect says the same words of each cord.
    for cid in ("c4", "c12"):
        said = page.evaluate("""async id => { const t = window.__tools?.inspect; if (!t) return null;
          const out = await t.execute({id}); return (out?.content ?? []).map(c => c.text ?? '').join('\\n'); }""", cid)
        if not said or f"; {want[cid]['text']} (" not in said:
            bad.append(f"agent: inspect {cid} does not say {want[cid]['text']!r}: {said!r}")

    # FEET. c12 is given a length of 3 ft in its form: the cord and the spare are both said in feet.
    page.click('#cableList [data-cable-row="c12"]')
    wait_sel(page, "spare: Edit", "#cableEdit")
    page.click("#cableEdit")
    wait_sel(page, "spare: c12's form", "#cableForm")
    page.fill("#cLength", "3")
    page.select_option("#cUnit", "ft")
    page.click("#cSave")
    wait_fn(page, "spare: c12 saved as 3 ft", "() => window.__rack.doc().racks[0].cables.find(c => c.id === 'c12').length?.unit === 'ft'")
    wait_fn(page, "spare: the routes after the edit", ROUTES_CURRENT)
    wait_fn(page, "spare: c12's row in feet", "() => /ft cord/.test(document.querySelector('#cableList li[data-cable-item=\"c12\"] .rk-cable-meta')?.textContent ?? '')")
    was = want["c12"]
    want = page.evaluate(SPARE_WANT_JS)
    ft = want["c12"]
    if (ft["value"], ft["unit"]) != (3, "ft") or not ft["text"].startswith("3 ft cord, ") or not ft["text"].endswith(" ft spare"):
        bad.append(f"feet: c12 should read as a 3 ft cord with its spare in feet, is {ft}")
    if ft["text"] == was["text"] or abs(ft["spare"] - (was["spare"] - (1 - 3 * 0.3048))) > 1e-6:
        bad.append(f"feet: a 3 ft cord on the same path should have 0.0856 m less spare than the 1 m cord: {was['spare']} then {ft['spare']}")
    # 3 ft (0.914 m) is under the 1 m the kit would pick and over what the route needs: no warning.
    if not (ft["measured"] < 0.9 and ft["stock"] == 1 and ft["asks"] is None and ft["text"].endswith(" ft spare")):
        bad.append(f"feet: a 3 ft cord on a route needing under 0.9 m should have spare and no warning: {ft}")
    page.click('#cableList [data-cable-row="c12"]')     # let it go: a selected cable dims the rest
    wait_fn(page, "spare: nothing selected", "() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
    def give(cid, metres, seen):
        page.click(f'#cableList [data-cable-row="{cid}"]')
        wait_sel(page, f"spare: Edit {cid}", "#cableEdit")
        page.click("#cableEdit")
        wait_sel(page, f"spare: {cid}'s form", "#cableForm")
        page.fill("#cLength", str(metres))
        page.select_option("#cUnit", "m")
        page.click("#cSave")
        wait_fn(page, f"spare: {cid} saved as {metres} m", "([id, v]) => window.__rack.doc().racks[0].cables.find(c => c.id === id).length?.value === v", arg=[cid, metres])
        wait_fn(page, f"spare: the routes after {cid}'s edit", ROUTES_CURRENT)
        wait_fn(page, f"spare: {cid}'s row says {seen!r}", "([id, t]) => (document.querySelector(`#cableList li[data-cable-item=\"${id}\"] .rk-cable-meta`)?.textContent ?? '').includes(t)", arg=[cid, seen])
        page.click(f'#cableList [data-cable-row="{cid}"]')
        wait_fn(page, "spare: nothing selected again", "() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
    # A CORD THAT MEETS THE NEED WITH LESS THAN THE END PLAY TO SPARE. c16 is given 0.5 m: its route needs about
    # 0.4 m, so it reaches, with under 0.2 m of spare. It has that spare and no warning (the kit's need is met).
    give("c16", 0.5, " m spare")
    # A CORD THAT DOES NOT REACH. c4 is given 0.2 m: less than its path and plugs use.
    give("c4", 0.2, "short")
    want = page.evaluate(SPARE_WANT_JS)
    ft, tight, short = want["c12"], want["c16"], want["c4"]
    if not (0 < tight["spare"] < 2 * tight["end_play"] and tight["measured"] > 0.5 > tight["need"] and tight["text"].startswith("0.5 m cord, ")
            and tight["text"].endswith(" m spare") and tight["asks"] is None and tight["short"] == []):
        bad.append(f"tight: c16 at 0.5 m should meet its need with less than the end play to spare, and not warn: {tight}")
    if not (short["spare"] < 0 and short["text"].startswith("0.2 m cord, ") and short["text"].endswith(" m short")
            and (short["asks"] or "").startswith("the route needs 0.")):
        bad.append(f"short: c4 at 0.2 m should read short of what its route needs: {short}")
    if ft["asks"] is not None:
        bad.append(f"feet: c12 at 3 ft warns after the other edits: {ft}")
    park_mouse(page)
    read_list("2D list, c12 in feet, c16 tight and c4 short")
    spare_hover(page, bad, "2D hover, c12 in feet", SPARE_PT_2D_JS, "c12", ft)
    spare_hover(page, bad, "2D hover, c16 tight", SPARE_PT_2D_JS, "c16", tight)
    spare_hover(page, bad, "2D hover, c4 short", SPARE_PT_2D_JS, "c4", short, drag=0)
    # the press and release in place was a click on whatever lies under the cable: let it go
    page.keyboard.press("Escape")
    wait_sel(page, "spare: the list after the press", '#cableList [data-cable-row="c4"]')
    wait_fn(page, "spare: the routes after the press", ROUTES_CURRENT)
    park_mouse(page)
    # A CORD UNDER THE NEED BY LESS THAN A DISPLAYED STEP. c12's route needs about 0.4232 m; a cord cut to the
    # centimetre under that is short, and says so. Its figures are rounded as the kit rounds every figure (one rule
    # for the page and the schedule), so the need it names is the kit's to the nearest centimetre.
    near = math.floor(want["c12"]["need"] * 100) / 100
    give("c12", near, "short")
    want = page.evaluate(SPARE_WANT_JS)
    hair = want["c12"]
    m = re.fullmatch(r"the route needs ([\d.]+) m", hair["asks"] or "")
    if not (near < hair["need"] < near + 0.01) or not m or float(m.group(1)) != round(hair["need"] * 100) / 100 or not hair["text"].endswith(" m short"):
        bad.append(f"rounding: c12 at {near} m on a route needing {hair['need']} m should be short and name the kit's need to the centimetre: {hair}")
    read_list(f"2D list, c12 at {near} m")
    spare_hover(page, bad, f"2D hover, c12 at {near} m", SPARE_PT_2D_JS, "c12", hair)
    # The agent's text for each: its need on the length (the kit's, 0.22.0), then the cord, then what the route asks for.
    for cid in ("c4", "c16", "c12"):
        said = page.evaluate("""async id => { const out = await window.__tools.inspect.execute({id});
          return (out?.content ?? []).map(c => c.text ?? '').join('\\n'); }""", cid)
        w = want[cid]
        tail = f"{w['text']}; {w['asks']} (" if w["asks"] else f"{w['text']} ("
        if not re.search(r"length [\d.]+ (m|ft) \(entered\), needs [\d.]+ m; routed [\d.]+ m, stock size [\d.]+ m; "
                         + re.escape(tail), said or "") or "dressing" in (said or "") or "against the routed length" in (said or ""):
            bad.append(f"agent: inspect {cid} does not say its length with its need, then {tail!r}: {said!r}")

    if webgl_trouble(page):
        print("[check_rack_cable_spare] no WebGL here - checked the 2D half only")
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the spare rack's scene", tubes=True)
    wait_fn(page, "spare: the routes in 3D", ROUTES_CURRENT)
    park_mouse(page)
    read_list("3D list")
    for cid in ("c4", "c12"):
        spare_hover(page, bad, "3D hover", SPARE_PT_3D_JS, cid, want[cid], drag=40 if cid == "c4" else None)
    return bad


# THE EARS MEET THE BODY (#168). A generic ear's flange runs from the face's
# own edge out over the rail, as the kit's plan and the 3D flange do. It ran
# from the opening's edge, so every device narrower than the 450.85 mm opening
# showed rail between body and ear (9.75 mm each side on the XCU10, 115 mm on a
# half-width TM-340). And a face is centred on the opening by its DECLARED box:
# the CMH-6DR1U's drawing is wider than its face (#865, viewBox from -43), and
# centring the drawing put its built-in ears 43 mm off the rails. Measured in
# pane millimetres off the drawn DOM, against each face's declared box read
# from the compiled file; the FHD-CMP5DR (built-in ears, a rack-face part) and
# the full-width blank are in the sample to hold their centring.
@extra("rack.html: generic rack ears meet the device body in 2D, and every face is centred by its declared box (#168)")
def check_rack_ears_meet_face(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    sample = [("xcu", 37), ("fhd-cmp5dr", 41), ("s9600-72xc", 20), ("tm-340", 10), ("fhu-bps-2u", 24), ("cmh-6dr1u", 30)]
    rack = page.evaluate("""async sample => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Ears meet'});
      for (const [ref, ru] of sample)
        ({rack: r} = M.withItem(r, {ref, cfg: cat[ref].default, ru, face: 'front', label: ref}));
      return r;
    }""", sample)
    page.evaluate("r => window.__rack.replaceRack(r)", rack)
    page.wait_for_function("n => document.querySelectorAll('#paneFront [data-item-id][data-panel=\"mounted\"]').length === n",
                           arg=len(sample), timeout=READY_MS)
    page.wait_for_timeout(300)
    got = page.evaluate(r"""async () => {
      const {OPENING} = await import('/vendor/rack/rails.js');
      const C = await import('/vendor/rack/catalog.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      const pane = document.querySelector('#paneFront');
      const out = [];
      for (const g of pane.querySelectorAll('[data-item-id][data-panel="mounted"]')) {
        const ref = g.dataset.deviceRef, cfg = cat[ref].default;
        let r = await fetch(`/assets/dist/${ref}.${cfg}.front.svg`);
        if (!r.ok) r = await fetch(`/assets/dist/${ref}.front.svg`);
        const root = new DOMParser().parseFromString(await r.text(), 'image/svg+xml').documentElement;
        const vb = root.getAttribute('viewBox').trim().split(/[\s,]+/).map(Number);
        const fw = parseFloat(root.getAttribute('data-face-w'));
        const declared = fw > 0;
        const faceW = declared ? fw : vb[2], ox = declared ? 0 : vb[0];
        const m = g.transform.baseVal.consolidate().matrix;
        const left = m.e + ox, right = left + faceW;
        const ears = pane.querySelector(`[data-ears-for="${g.dataset.itemId}"]`);
        const rects = ears ? [...ears.querySelectorAll('rect')].map(e => [+e.getAttribute('x'), +e.getAttribute('width')]) : [];
        out.push({ref, faceW, left, right, centre: (OPENING - faceW) / 2, kind: ears?.dataset.ears ?? null,
                  earL: rects[0] ? rects[0][0] + rects[0][1] : null, earR: rects[1] ? rects[1][0] : null});
      }
      return out;
    }""")
    seen = {d["ref"] for d in got}
    for ref, _ in sample:
        if ref not in seen:
            bad.append(f"{ref}: never drawn on the front pane")
    generic = 0
    for d in got:
        if abs(d["left"] - d["centre"]) > 0.05:
            bad.append(f"{d['ref']}: its {d['faceW']} mm face starts at x={d['left']:.2f}, not centred at {d['centre']:.2f}")
        if d["kind"] == "generic":
            generic += 1
            gl, gr = d["left"] - d["earL"], d["earR"] - d["right"]
            if abs(gl) > 0.05 or abs(gr) > 0.05:
                bad.append(f"{d['ref']}: its generic ears stop {gl:.2f} mm (left) and {gr:.2f} mm (right) short of its "
                           f"{d['faceW']} mm face; they must meet it")
    for ref in ("xcu", "s9600-72xc", "tm-340"):
        if not any(d["ref"] == ref and d["kind"] == "generic" for d in got):
            bad.append(f"{ref}: no generic ears drawn, so nothing was measured for it")
    if generic < 3:
        bad.append(f"only {generic} generic ear pairs measured, expected 3")
    return bad


# THE BUNDLES IN THE EXPORTS (Portrayal #923, kit 0.9.0): the cable schedule
# names each member's bundle in its `bundle` column and carries the kit's line
# for the bundle in its notes, measured with the page's routes, cable types and
# bend radii (so a bend radius, never "bend not checked", for Cat6A); the BOM
# buys the straps the page draws, in one hook-and-loop line.
@extra("rack.html: a bundle is in the exports - the schedule's bundle column and the kit's bundle note, and the BOM's strap line (Portrayal #923)")
def check_rack_bundle_exports(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_bundle_rack(page, base, "front")
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'uplinks'})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => (window.__rack.bundles() || [])[0]?.count > 0", timeout=READY_MS)
    f = page.evaluate("() => window.__rack.bundles()[0]")
    got = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      const r = window.__rack.doc().racks[0];
      const s = await X.cableScheduleCsv(r, of), b = await X.bomCsv(r, of);
      return {sched: s.data, notes: s.notes, bom: b.data};
    }""")
    lines = got["sched"].split("\r\n")
    cols = lines[0].split(",")
    if "bundle" not in cols or cols.index("bundle") != cols.index("route") + 1:
        bad.append(f"schedule: no bundle column straight after route: {cols}")
    else:
        k = cols.index("bundle")
        named = [l.split(",")[k] for l in lines[1:4]]
        if named != ["uplinks"] * 3:
            bad.append(f"schedule: the members' bundle column reads {named}, not uplinks")
    head = next((n for n in got["notes"] if n.startswith("uplinks (b1): 3 cables")), None)
    if not head:
        bad.append(f"schedule: no kit note for the bundle: {got['notes']}")
    else:
        # by kind since kit 0.22.0: every strap the page draws, and how many of them are the spacing straps
        k = f["kinds"]
        said = f"{f['count']} straps every 12 in" if k["spacing"] == f["count"] else \
            f"{f['count']} straps ({k['spacing']} every 12 in, {k['breakout']} where a cable leaves" if k["breakout"] and not k["anchor"] else f"{f['count']} straps ("
        if said not in head or sum(k.values()) != f["count"]:
            bad.append(f"schedule: the bundle note does not count the {f['count']} straps the page draws ({k}): {head!r}")
        if "bend radius" not in head or "bend not checked" in head:
            bad.append(f"schedule: the bundle note has no measured bend radius: {head!r}")
    strap = [l for l in got["bom"].split("\r\n") if "Hook-and-loop cable strap" in l]
    # the bundle's straps, and one more for each tray tie slot a single cable is tied at (kit 0.22.0): the kit's total
    total = page.evaluate("""async () => { const B = await import('/vendor/rack/bundles.js'), RC = await import('/site/rack/route-context.js');
      const rack = window.__rack.doc().racks[0]; return B.strapTotals(rack, RC.withCableTypes({route: window.__rack.routeContext()}, await RC.cableTypes())); }""")
    if len(strap) != 1 or not strap[0].split(",")[1:2] == [str(total["total"])] or total["spacing"] + total["breakout"] != f["count"] - f["kinds"]["anchor"] or total["total"] < f["count"]:
        bad.append(f"BOM: the strap line is {strap}, not one line of the kit's {total['total']} ({total}; the bundle has {f['count']})")
    return bad


@extra("rack.html: in 3D a bundle is a tube of its diameter along its trunk, with a strap band at each of the kit's straps (portrayal-site#142)")
def check_rack_bundle_3d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_bundle_rack(page, base, "front")
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3']})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => (window.__rack.bundles() || [])[0]?.count > 0", timeout=READY_MS)
    f = page.evaluate("() => window.__rack.bundles()[0]")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the bundle's scene", tubes=True)
    got = page.evaluate("""async () => {
      const s = window.__rack.scene(); const d = Date.now() + 30000;
      while (!s.rackCables?.bundles && Date.now() < d) await new Promise(r => setTimeout(r, 200));
      const world = s.three.scene, trunk = world.getObjectByName('bundle-b1-trunk');
      if (!trunk) return null;
      const straps = []; world.traverse(o => { if (/^bundle-b1-strap-/.test(o.name)) straps.push(o); });
      // each strap's distance from the tube's centre line (its path's points)
      const path = trunk.geometry.parameters.path, line = path.getSpacedPoints(400);
      const off = straps.map(o => Math.min(...line.map(p => p.distanceTo(o.position))));
      // the members' tubes stay inside the bundle where they ride the lane (U22-U28)
      const lo = 21.5 * 44.45, hi = 27.5 * 44.45, inside = [];
      // and each member's offset across the lane at U25 (x, z), to show they are spread, not stacked
      const spread = [];
      for (const t of s.rackCables.tubes) {
        const main = t.mesh?.children?.[0]?.geometry?.parameters?.path;
        let at = null;
        for (const p of main ? main.getSpacedPoints(800) : []) if (p.y > lo && p.y < hi && Math.abs(p.x + 271) < 30) {
          inside.push(Math.min(...line.map(q => q.distanceTo(p))));
          if (!at || Math.abs(p.y - 24.5 * 44.45) < Math.abs(at.y - 24.5 * 44.45)) at = p;
        }
        if (at) spread.push([at.x, at.z]);
      }
      return {radius: trunk.geometry.parameters.radius, straps: straps.length, off: Math.max(0, ...off), spread,
              memberOff: inside.length ? Math.max(...inside) : null, n: inside.length,
              ys: [Math.min(...line.map(p => p.y)), Math.max(...line.map(p => p.y))]};
    }""")
    if not got:
        return bad + ["3D: no bundle-b1-trunk tube in the scene"]
    want_r = f["diameter"] / 2
    if want_r <= 3:
        return bad + [f"3D: the bundle is {f['diameter']} mm, not above the 6 mm drawing floor"]
    if abs(got["radius"] - want_r) > 0.01:
        bad.append(f"3D: the tube's radius is {got['radius']}, not half the bundle's {f['diameter']} mm")
    if got["ys"][1] - got["ys"][0] < 400:
        bad.append(f"3D: the tube does not run the 10U trunk (y {got['ys']})")
    if got["straps"] != f["count"]:
        bad.append(f"3D: {got['straps']} strap bands, the kit counts {f['count']}")
    if got["off"] > 3:
        bad.append(f"3D: a strap band sits {got['off']:.1f} mm off the tube's centre line")
    # A member's centre line is within the radius less half a 3 mm tube, so the whole tube is inside.
    if got["memberOff"] is None or got["memberOff"] > want_r - 1.5 + 0.5:
        bad.append(f"3D: a member's tube reaches {got['memberOff']} mm from the bundle's centre on the lane ({got['n']} points; radius {want_r})")
    # ...and spread across it: three members at three places, at least a millimetre apart.
    pts = got["spread"]
    close = [(i, j) for i in range(len(pts)) for j in range(i + 1, len(pts))
             if ((pts[i][0] - pts[j][0]) ** 2 + (pts[i][1] - pts[j][1]) ** 2) ** 0.5 < 1]
    if len(pts) != 3 or close:
        bad.append(f"3D: the members are not spread inside the bundle at U25: {pts}")
    return bad


# ── the rack's drawing: what is in front of a cable, a bundle's pack, its
# straps, and a half-unit body ───────────────────────────────────────────────
def png_pixels(data):
    """A PNG screenshot's pixels, with nothing but zlib: (width, height, at(x, y) -> (r, g, b))."""
    import struct
    import zlib
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("not a PNG")
    pos, idat, w = 8, b"", None
    while pos < len(data):
        n, kind = struct.unpack(">I4s", data[pos:pos + 8])
        body = data[pos + 8:pos + 8 + n]
        if kind == b"IHDR":
            w, h, depth, ctype, _, _, lace = struct.unpack(">IIBBBBB", body)
            if depth != 8 or ctype not in (2, 6) or lace:
                raise ValueError(f"PNG of depth {depth}, colour type {ctype}, interlace {lace}")
        elif kind == b"IDAT":
            idat += body
        pos += 12 + n
    bpp = 4 if ctype == 6 else 3
    raw, stride, rows, prev = zlib.decompress(idat), w * bpp, [], bytearray(w * bpp)
    for y in range(h):
        f, line = raw[y * (stride + 1)], bytearray(raw[y * (stride + 1) + 1:(y + 1) * (stride + 1)])
        for i in range(stride):
            a = line[i - bpp] if i >= bpp else 0
            b, c = prev[i], (prev[i - bpp] if i >= bpp else 0)
            if f == 1:
                line[i] = (line[i] + a) & 255
            elif f == 2:
                line[i] = (line[i] + b) & 255
            elif f == 3:
                line[i] = (line[i] + ((a + b) >> 1)) & 255
            elif f == 4:
                pa, pb, pc = abs(b - c), abs(a - c), abs(a + b - 2 * c)
                line[i] = (line[i] + (a if pa <= pb and pa <= pc else b if pb <= pc else c)) & 255
        rows.append(line)
        prev = line
    return w, h, lambda x, y: tuple(rows[int(y)][int(x) * bpp:int(x) * bpp + 3])


def rgb_of(color):
    """'#rrggbb' or 'rgb(r, g, b)' as a tuple."""
    m = re.fullmatch(r"#([0-9a-fA-F]{6})", color.strip())
    if m:
        return tuple(int(m.group(1)[i:i + 2], 16) for i in (0, 2, 4))
    return tuple(int(float(v)) for v in re.findall(r"[\d.]+", color)[:3])


def contrast_ratio(a, b):
    """WCAG contrast of two sRGB colours, 1 to 21."""
    def lum(c):
        ch = [v / 255 for v in c]
        ch = [v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4 for v in ch]
        return 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2]
    hi, lo = max(lum(a), lum(b)), min(lum(a), lum(b))
    return (hi + 0.05) / (lo + 0.05)


# A switch with a lacer on it (rings), a second switch ten units up and a
# vertical manager beside the left front upright (a duct with covers); four
# cords between the switches, which the kit routes through the lacer's rings
# and up the duct.
FRONT_FIXTURE = """async () => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.newRack({name: 'In front'});
  ({rack: r} = M.withItem(r, {ref: 'ws-c4948e', cfg: cat['ws-c4948e'].default, ru: 20, face: 'front', label: 'sw-1'}));
  ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, face: 'front', label: 'mgr-1', on: 'i1', unit: 1}));
  ({rack: r} = M.withItem(r, {ref: 'ws-c4948e', cfg: cat['ws-c4948e'].default, ru: 30, face: 'front', label: 'sw-2'}));
  r = {...r, zeroU: [{id: 'z1', ref: 'cmv-sfd42u9w', cfg: 'base', label: 'duct-1', at: 'left-front', offsetMm: 0}]};
  for (const p of ['port-1', 'port-2', 'port-3', 'port-24'])
    ({rack: r} = K.withCable(r, {a: {item: 'i1', path: p, view: 'front'}, b: {item: 'i3', path: p, view: 'front'}, media: 'cat6a'}));
  return r;
}"""


def open_front_fixture(page, base, fixture=FRONT_FIXTURE, cables=4):
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.evaluate("r => window.__rack.replaceRack(r)", page.evaluate(fixture))
    page.wait_for_function("n => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id]').length >= n"
                           " && window.__rack.routesCurrent().current", arg=cables, timeout=READY_MS)
    page.wait_for_timeout(400)


# Where c1's drawn stroke crosses a ring leg and a cover, in page pixels, with
# the paints that meet there; and the pane's layers in document order.
IN_FRONT_JS = """() => {
  const svg = document.querySelector('#paneFront svg');
  const kids = [...svg.children], at = sel => kids.findIndex(k => k.matches(sel));
  const layer = svg.querySelector(':scope > [data-in-front]');
  const inside = layer ? [layer, ...layer.querySelectorAll('*')] : [];
  const carried = inside.flatMap(n => [...n.attributes].map(a => a.name))
    .filter(a => a === 'id' || a === 'tabindex' || (a.startsWith('data-') && !/^data-(in-front|front|front-of)$/.test(a)));
  const own = inside.slice(1).filter(n => n.hasAttribute('pointer-events')).length;
  const stroke = svg.querySelector('[data-cables] [data-cable-id="c1"] path:last-of-type');
  const pts = [];
  for (const p of svg.querySelectorAll('[data-cables] [data-cable-id="c1"] path')) {
    const m = p.getScreenCTM(), L = p.getTotalLength();
    for (let t = 0; t <= L; t += 0.25) { const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m); pts.push([w.x, w.y]); }
  }
  const within = (r, pad) => pts.filter(q => q[0] > r.left + pad && q[0] < r.right - pad && q[1] > r.top + pad && q[1] < r.bottom - pad);
  const mid = list => list[Math.floor(list.length / 2)] ?? null;
  const ring = svg.querySelector('[data-item-id="i2"][data-panel="mounted"] [id="guide-1-end"]');
  const plate = svg.querySelector('[data-zerou-id="z1"] [data-group="cover"] [id$="--plate"]');
  const rr = ring.getBoundingClientRect(), pr = plate.getBoundingClientRect();
  // on the cover: well inside its plate, on the part of it the page shows
  const seen = q => { const e = document.elementFromPoint(q[0], q[1]); return !!e && svg.contains(e); };
  const onCover = within(pr, 6).filter(seen);
  return {order: {cables: at('[data-cables]'), front: at('[data-in-front]'), tags: at('[data-cable-tags]'),
                  last: Math.max(...kids.map((k, i) => (k.matches('[data-item-id], [data-zerou-id], .rk-ears') ? i : -1)))},
          rings: layer ? layer.querySelectorAll(':scope > [data-front="ring"][data-front-of="i2"]').length : 0,
          covers: layer ? layer.querySelectorAll(':scope > [data-front="cover"][data-front-of="z1"]').length : 0,
          coverOpacity: layer ? [...layer.querySelectorAll(':scope > [data-front="cover"]')].map(g => +getComputedStyle(g).opacity) : [],
          ringOpacity: layer ? [...layer.querySelectorAll(':scope > [data-front="ring"]')].map(g => +getComputedStyle(g).opacity) : [],
          layerPointer: layer?.getAttribute('pointer-events') ?? null, carried, own,
          ringIds: svg.querySelectorAll('[id="guide-1-end"]').length, coverIds: svg.querySelectorAll('[id="cover-1"]').length,
          ids: svg.querySelectorAll('[id]').length,
          cable: stroke.getAttribute('stroke'), ringFill: ring.getAttribute('fill'), plateFill: plate.getAttribute('fill'),
          onRing: mid(within(rr, 1.5)), onCover: mid(onCover),
          ringFree: [rr.left + rr.width / 2, rr.top + 4], coverFree: [pr.left + pr.width * 0.8, pr.top + pr.height * 0.6],
          top: [document.elementFromPoint(rr.left + rr.width / 2, rr.top + 4)?.id ?? null,
                document.elementFromPoint(pr.left + pr.width * 0.8, pr.top + pr.height * 0.6)?.closest('[data-zerou-id]')?.dataset.zerouId ?? null]};
}"""


@extra("rack.html: in 2D a lacer's ring legs and a vertical manager's cover paint above the cables, as the 3D scene stands them (the cover see-through), as copies with no id that take no pointer; clicks still reach the parts underneath, and the sheet keeps the same order")
def check_rack_cables_behind(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_front_fixture(page, base)
    for _ in range(3):
        page.click("#zoomIn")
        page.wait_for_timeout(150)
    page.evaluate("() => document.querySelector('#paneFront svg [data-u=\"22\"]').scrollIntoView({block: 'center', inline: 'center'})")
    page.wait_for_timeout(500)
    g = page.evaluate(IN_FRONT_JS)
    o = g["order"]
    if not (o["last"] < o["cables"] < o["front"] < o["tags"]):
        bad.append(f"order: the pane's layers are not faces, cables, in-front, tags: {o}")
    if (g["rings"], g["covers"]) != (5, 2):
        bad.append(f"in front: {g['rings']} ring legs and {g['covers']} covers copied, expected the lacer's 5 and the duct's 2")
    if g["carried"] or g["own"] or g["layerPointer"] != "none":
        bad.append(f"in front: a copy carries {sorted(set(g['carried']))}, {g['own']} pointer-events of its own; the layer's is {g['layerPointer']!r}")
    if (g["ringIds"], g["coverIds"]) != (1, 1):
        bad.append(f"ids: guide-1-end is in the pane {g['ringIds']} times and cover-1 {g['coverIds']} times, expected once each")
    if any(abs(v - 1) > 1e-6 for v in g["ringOpacity"]) or any(not 0.25 <= v <= 0.45 for v in g["coverOpacity"]):
        bad.append(f"paint: ring legs at {g['ringOpacity']} and covers at {g['coverOpacity']}, expected opaque legs and covers about a third opaque")
    # The composited page: on a ring leg the cable is hidden; under the cover it shows through.
    if not g["onRing"] or not g["onCover"]:
        return bad + [f"pixels: c1's stroke was not found crossing a ring leg ({g['onRing']}) and the cover ({g['onCover']})"]
    _, _, px = png_pixels(page.screenshot())
    cable, ring, plate = rgb_of(g["cable"]), rgb_of(g["ringFill"]), rgb_of(g["plateFill"])
    far = lambda a, b: max(abs(x - y) for x, y in zip(a, b))
    got_ring, got_cover = px(*g["onRing"]), px(*g["onCover"])
    if far(got_ring, ring) > 12:
        bad.append(f"pixels: where c1 crosses a ring leg the page shows {got_ring}, not the leg's {ring} (the cable is {cable})")
    blend = tuple(round(0.34 * p + 0.66 * c) for p, c in zip(plate, cable))
    if far(got_cover, blend) > 30 or far(got_cover, cable) < 25 or far(got_cover, plate) < 25:
        bad.append(f"pixels: where c1 runs behind the cover the page shows {got_cover}; expected near {blend}, between the cable's {cable} and the plate's {plate}")
    # The originals still take the pointer: a click on a ring leg selects its manager, one on the cover the duct.
    if g["top"] != ["guide-1-end", "z1"]:
        bad.append(f"pointer: the element under a ring leg and under the cover is {g['top']}, expected the original guide-1-end and z1's")
    page.mouse.click(*g["ringFree"])
    page.wait_for_function("() => document.querySelector('#paneFront [data-item-id=\"i2\"].rk-selected')", timeout=READY_MS)
    if page.locator("#paneFront svg .rk-sel-ring").count() != 1:
        bad.append("selection: no selection ring after a click on a ring leg")
    page.wait_for_timeout(300)
    cov = page.evaluate(IN_FRONT_JS)["coverFree"]
    page.mouse.click(*cov)
    page.wait_for_function("() => document.querySelector('#paneFront [data-zerou-id=\"z1\"].rk-selected')", timeout=READY_MS)
    # The sheet: the same layers in the same order, and still one of each id.
    sheet = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      return (await X.sheetSvg(window.__rack.doc().racks[0], (await C.loadCatalog('/assets/dist/')).chassisOf, {faces: ['front']})).data;
    }""")
    ns = "{http://www.w3.org/2000/svg}"
    pane = ET.fromstring(sheet.encode("utf-8")).find(f"{ns}svg")
    kids = list(pane)
    idx = lambda key: next((i for i, k in enumerate(kids) if k.get(key) is not None), -1)
    faces = max((i for i, k in enumerate(kids) if k.get("data-item-id") or k.get("data-zerou-id")), default=-1)
    if not (faces < idx("data-cables") < idx("data-in-front") < idx("data-cable-tags")):
        bad.append(f"sheet: its layers are faces {faces}, cables {idx('data-cables')}, in-front {idx('data-in-front')}, tags {idx('data-cable-tags')}")
    else:
        front = kids[idx("data-in-front")]
        kinds = [k.get("data-front") for k in front]
        if (kinds.count("ring"), kinds.count("cover")) != (5, 2):
            bad.append(f"sheet: its in-front layer holds {kinds}")
        if any(n.get("id") for n in front.iter()):
            bad.append("sheet: a copy in its in-front layer carries an id")
        if [k.get("opacity") for k in front if k.get("data-front") == "cover"] != ["0.34"] * 2:
            bad.append(f"sheet: its covers are not see-through: {[k.get('opacity') for k in front]}")
    for name in ("guide-1-end", "cover-1"):
        if sum(1 for n in pane.iter() if n.get("id") == name) != 1:
            bad.append(f"sheet: {name} is in the file {sum(1 for n in pane.iter() if n.get('id') == name)} times")
    return bad


# Three cords from the middle of a switch through two of its lacer's rings and
# up the left lane to a second switch, and one from its left end through the
# last ring only: a bundle of the four rides a stretch along the lacer, a
# corner and a lane.
PACK_FIXTURE = FRONT_FIXTURE.replace("['port-1', 'port-2', 'port-3', 'port-24']", "['port-25', 'port-26', 'port-27', 'port-1']").replace("'In front'", "'Pack'")
# Five switches, U31 to U35, each with a cord to a sixth at U40, bundled up the
# left lane: the members join one unit after another, so the trunk grows
# upward and each cord peels off the pack toward its own switch.
PEEL_FIXTURE = """async () => {
  const M = await import('/vendor/rack/model.js'), K = await import('/vendor/rack/cable-rules.js');
  let r = M.newRack({name: 'Peels'});
  ({rack: r} = M.withItem(r, {ref: 'ds1000', cfg: 'f2b', ru: 40, face: 'front', label: 'mgmt'}));
  for (let u = 35; u >= 31; u--) ({rack: r} = M.withItem(r, {ref: 'ds1000', cfg: 'f2b', ru: u, face: 'front', label: `sw-${u}`}));
  for (let k = 2; k <= 6; k++)
    ({rack: r} = K.withCable(r, {a: {item: `i${k}`, path: 'mgmt', view: 'front'}, b: {item: 'i1', path: `port-${k - 1}`, view: 'front'}, media: 'cat6'}));
  return {...r, bundles: [{id: 'b1', number: 1, label: 'MGMT', members: r.cables.map(c => ({cable: c.id})),
                          route: [{lane: 'left-front', ru: 31}, {lane: 'left-front', ru: 40}]}]};
}"""

# The pack on the front pane, in pane mm: each envelope stretch (its line, its
# width, how many ride it, the kit's diameter for that many of this rack's
# cables, and how far the furthest member's stroke passes from five points
# along it), whether the envelope shows, each member's stroke as points, and
# the straps.
PACK_2D_JS = """async () => {
  const B = await import('/vendor/rack/bundles.js');
  const svg = document.querySelector('#paneFront svg'), inv = svg.getScreenCTM().inverse();
  const g = svg.querySelector('[data-cables] [data-bundle-id="b1"]');
  if (!g) return null;
  const ids = (g.dataset.members || '').split(' ').filter(Boolean);
  const line = {};
  for (const id of ids) {
    const pts = [];
    // the cable's own run, not the short strands into a duplex pair
    const p = [...svg.querySelectorAll(`[data-cables] [data-cable][data-cable-id="${id}"] path`)].sort((a, b) => b.getTotalLength() - a.getTotalLength())[0];
    if (p) { const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
      for (let t = 0; t <= L; t += 0.2) { const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m); pts.push([w.x, w.y]); } }
    line[id] = pts;
  }
  const d = window.__rack.doc().racks[0], dOf = window.__rack.routeContext().diameterOf;
  const one = dOf ? dOf(d.cables[0]) : null;
  const stretches = [...g.querySelectorAll('[data-bundle-trunk]')].map(p => {
    const [x0, y0, x1, y1] = p.getAttribute('d').match(/-?[\\d.]+(?:e-?\\d+)?/g).map(Number), n = +p.dataset.riders;
    const reach = [0.1, 0.3, 0.5, 0.7, 0.9].map(f => { const c = [x0 + (x1 - x0) * f, y0 + (y1 - y0) * f];
      // the riders are the n members nearest this point; the furthest of them is the pack's reach
      return ids.map(id => Math.min(...line[id].map(q => Math.hypot(q[0] - c[0], q[1] - c[1])))).sort((a, b) => a - b)[n - 1]; });
    return {x0, y0, x1, y1, width: +p.getAttribute('stroke-width'), riders: n, kit: one ? Math.max(6, Math.round(B.bundleDiameter(Array(n).fill(one)) * 10) / 10) : null, reach: Math.max(...reach)};
  });
  const env = g.querySelector('[data-envelope]');
  return {stretches, shown: getComputedStyle(env).visibility === 'visible', members: ids, line,
          straps: [...svg.querySelectorAll('[data-strap="b1"]')].map(g => { const l = g.querySelector('line[data-strap-part="core"]:not([data-strap-least])');
            // its members' own strokes where they cross the bar's line: how wide the pack is drawn there, and where its middle is
            const [x1, y1, x2, y2] = ['x1', 'y1', 'x2', 'y2'].map(k => +l.getAttribute(k)), len = Math.hypot(x2 - x1, y2 - y1);
            const n = [(x2 - x1) / len, (y2 - y1) / len], d = [-n[1], n[0]], c = [(x1 + x2) / 2, (y1 + y2) / 2], across = [];
            for (const id of ids) {
              let best = null;
              for (const q of line[id]) { const along = Math.abs((q[0] - c[0]) * d[0] + (q[1] - c[1]) * d[1]), a = (q[0] - c[0]) * n[0] + (q[1] - c[1]) * n[1];
                if (Math.abs(a) < 30 && (best == null || along < best.along)) best = {along, a}; }
              if (best && best.along <= 0.5) across.push(best.a);
            }
            return {pack: +g.dataset.pack, len, riders: across.length, drawn: across.length ? Math.max(...across) - Math.min(...across) + 3 : null,
                    off: across.length ? (Math.max(...across) + Math.min(...across)) / 2 : null}; }),
          opacity: Object.fromEntries([...svg.querySelectorAll('[data-cables] [data-cable][data-cable-id]')].map(n => [n.dataset.cableId, +getComputedStyle(n).opacity]))};
}"""
# The pack in the scene: the envelope's pieces (radius, shown, a centre line
# as points), each member's tube as points, the ring openings the kit places,
# and the straps.
PACK_3D_JS = """async () => {
  const S = await import('/vendor/rack/solids.js');
  const s = window.__rack.scene(), w = s.three.scene, fz = s.metrics().faceZ, g = w.getObjectByName('bundle-b1');
  if (!g) return null;
  const r1 = v => Math.round(v * 100) / 100;
  const env = g.children.filter(o => o.userData.envelope).map(o => ({radius: o.geometry.parameters.radius, shown: o.visible, riders: o.userData.envelope.riders,
    line: o.geometry.parameters.path.getSpacedPoints(Math.max(20, Math.ceil(o.geometry.parameters.path.getLength() / 2))).map(p => [r1(p.x), r1(p.y), r1(p.z - fz)])}));
  const tubes = {};
  for (const t of s.rackCables.tubes) {
    const path = t.mesh?.children?.[0]?.geometry?.parameters?.path;
    if (path) tubes[t.link.id] = path.getSpacedPoints(Math.ceil(path.getLength() / 2)).map(p => [r1(p.x), r1(p.y), r1(p.z - fz)]);
  }
  let rings = [];
  try { rings = S.traysOf(window.__rack.doc().racks[0], window.__rack.routeContext()).flatMap(t => t.rings.map(o => ({item: t.item, via: o.via, run: o.run, box: o.box}))); } catch { rings = []; }
  return {env, tubes, rings, members: g.userData.members,
          straps: g.children.filter(o => o.userData.strap).map(o => ({radius: o.geometry.parameters.radiusTop, pack: o.userData.strap.diameter}))};
}"""


def segments_cross(p, q, r, s):
    """Do segments pq and rs cross at a point inside both?"""
    def side(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    d1, d2, d3, d4 = side(r, s, p), side(r, s, q), side(p, q, r), side(p, q, s)
    return d1 * d2 < 0 and d3 * d4 < 0


@extra("rack.html: a bundle is its members - packed inside its diameter along the whole trunk in 2D and 3D, standing on a ring's sill, as thick on each stretch as the cables that ride it, the first to leave on the side it leaves toward; its envelope shows only on hover or selection, and its straps are round the pack")
def check_rack_bundle_pack(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_front_fixture(page, base, PACK_FIXTURE)
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3', 'c4'], label: 'pack'})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneFront [data-bundle-id=\"b1\"] [data-bundle-trunk]') && window.__rack.routesCurrent().current",
                           timeout=READY_MS)
    page.wait_for_timeout(400)
    park_mouse(page)
    g = page.evaluate(PACK_2D_JS)
    if not g or not g["stretches"]:
        return bad + ["2D: no envelope stretches for b1 on the front pane"]
    # ── nothing of the bundle on the rear pane, where none of its cables run (its lacer stretch, ring to
    # ring, was once placed there by the kit's rest height alone: bars over the rear, and in the sheet) ──
    stray = page.evaluate("""() => { const s = document.querySelector('#paneRear svg');
      return {strokes: s.querySelectorAll('[data-cables] [data-cable][data-cable-id]').length,
              straps: s.querySelectorAll('[data-strap]').length, stretches: s.querySelectorAll('[data-bundle-trunk]').length}; }""")
    if stray["strokes"] or stray["straps"] or stray["stretches"]:
        bad.append(f"2D: the rear pane, where no member runs, has {stray['straps']} straps and {stray['stretches']} envelope stretches ({stray['strokes']} cable strokes)")
    # ── 2D: hidden by default; members and trunk coincide on every stretch ──
    if g["shown"]:
        bad.append("2D: the envelope shows with nothing hovered or selected")
    flat = [s for s in g["stretches"] if abs(s["y1"] - s["y0"]) < 0.5 and abs(s["x1"] - s["x0"]) > 20]
    up = [s for s in g["stretches"] if abs(s["x1"] - s["x0"]) < 0.5 and abs(s["y1"] - s["y0"]) > 20]
    if not flat or not up:
        bad.append(f"2D fixture: the bundle has no stretch along the lacer ({len(flat)}) or none up the lane ({len(up)}), so the pack was not measured there")
    for s in g["stretches"]:
        where = f"the stretch ({s['x0']:.0f}, {s['y0']:.0f}) to ({s['x1']:.0f}, {s['y1']:.0f}) with {s['riders']} riding"
        if s["kit"] is None or abs(s["width"] - s["kit"]) > 0.05:
            bad.append(f"2D: {where} is {s['width']} wide, not the kit's {s['kit']} for that many")
        # every rider's centre line within the half width less half a 3 mm stroke: its whole stroke is inside
        if s["reach"] > s["width"] / 2 - 1.5 + 0.3:
            bad.append(f"2D: on {where} a member's stroke is {s['reach']:.2f} mm from its line, outside the half width {s['width'] / 2:.2f}")
    # along the lacer the members are apart, not on one line: the pack has height there
    if flat:
        s = max(flat, key=lambda s: s["riders"])
        xm = (s["x0"] + s["x1"]) / 2
        ys = sorted(min(q, key=lambda q: abs(q[0] - xm))[1] for q in (g["line"][c] for c in g["members"])
                    if q and min(abs(p[0] - xm) for p in q) < 1)
        ys = ys[-s["riders"]:]      # the riders are the lowest strokes there (y is down)
        if len(ys) < 2 or ys[-1] - ys[0] < 1.5:
            bad.append(f"2D: along the lacer the members' strokes are at heights {ys}: one line, not a pack")
    # (#190: across the members as they are drawn there, measured here off their own strokes where they
    # cross the bar, which side by side are never wider than the pack's diameter; and 2 mm each side)
    if not g["straps"] or any(st["riders"] < 2 or abs(st["len"] - (st["drawn"] + 2)) > 1.2 or abs(st["off"]) > 1.2 or st["drawn"] > st["pack"] + 0.5 for st in g["straps"]):
        bad.append(f"2D: a strap is not a bar across its pack (its members' strokes there, no wider than its diameter, and 1 mm each side on the page since S-0040, to 1.2 mm): {g['straps']}")
    # hover and selection show it; a member hovered alone still dims the others
    page.hover('#cableList [data-bundle-row="b1"]')
    page.wait_for_timeout(350)
    if not page.evaluate(PACK_2D_JS)["shown"]:
        bad.append("2D: the envelope does not show while the bundle's row is hovered")
    page.hover('#cableList [data-cable-row="c2"]')
    page.wait_for_timeout(350)
    h = page.evaluate(PACK_2D_JS)
    if not h["shown"]:
        bad.append("2D: the envelope does not show while a member's row is hovered")
    if h["opacity"].get("c2") != 1 or any(v > 0.2 for k, v in h["opacity"].items() if k != "c2"):
        bad.append(f"2D: a member hovered alone does not dim the others: {h['opacity']}")
    park_mouse(page)
    if page.evaluate(PACK_2D_JS)["shown"]:
        bad.append("2D: the envelope still shows after the pointer left")
    page.click('#cableList [data-cable-row="c1"]')
    page.wait_for_function("() => document.querySelector('#paneFront [data-cable-id=\"c1\"].on')", timeout=READY_MS)
    park_mouse(page)
    if not page.evaluate(PACK_2D_JS)["shown"]:
        bad.append("2D: the envelope does not show while a member is selected")
    page.click('#cableList [data-cable-row="c1"]')
    page.wait_for_function("() => !document.querySelector('#paneFront [data-cable-id].on')", timeout=READY_MS)
    page.click('#cableList [data-bundle-row="b1"]')
    page.wait_for_selector("#bundlePanel", timeout=READY_MS)
    park_mouse(page)
    if not page.evaluate(PACK_2D_JS)["shown"]:
        bad.append("2D: the envelope does not show while the bundle is selected")
    # ── 3D, with the bundle still selected ──
    if webgl_trouble(page):
        print("[check_rack_bundle_pack] no WebGL here - the 3D half was not checked")
    else:
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, "3D: the pack's scene", tubes=True)
        park_mouse(page)
        t = page.evaluate(PACK_3D_JS)
        if not t or not t["env"]:
            return bad + ["3D: no envelope tube for b1 in the scene"]
        if not all(e["shown"] for e in t["env"]):
            bad.append("3D: the envelope does not show while the bundle is selected")
        page.click("#bDone")      # the panel closed: nothing selected
        page.wait_for_function("() => !document.querySelector('#bundlePanel')", timeout=READY_MS)
        park_mouse(page)
        if any(e["shown"] for e in page.evaluate(PACK_3D_JS)["env"]):
            bad.append("3D: the envelope shows with nothing hovered or selected")
        page.hover('#cableList [data-cable-row="c2"]')
        page.wait_for_timeout(350)
        if not all(e["shown"] for e in page.evaluate(PACK_3D_JS)["env"]):
            bad.append("3D: the envelope does not show while a member's row is hovered")
        park_mouse(page)
        page.hover('#cableList [data-bundle-row="b1"]')
        page.wait_for_timeout(350)
        if not all(e["shown"] for e in page.evaluate(PACK_3D_JS)["env"]):
            bad.append("3D: the envelope does not show while the bundle's row is hovered")
        park_mouse(page)
        # Along the lacer, between its last two rings: every member inside the envelope there, the
        # envelope standing on the ring's sill, and the members apart.
        rings = sorted((r for r in t["rings"] if r["item"] == "i2" and r["via"] in ("guide-1", "guide-2")), key=lambda r: r["box"]["x0"])
        if len(rings) != 2:
            bad.append(f"3D fixture: the kit places {len(rings)} of the lacer's guide-1 and guide-2 openings, expected both")
        else:
            x_lo, x_hi, sill = rings[0]["box"]["x1"] + 2, rings[1]["box"]["x0"] - 2, rings[0]["box"]["y0"]
            dist = lambda a, b: sum((u - v) ** 2 for u, v in zip(a, b)) ** 0.5
            centre = [(p, e["radius"]) for e in t["env"] for p in e["line"] if x_lo <= p[0] <= x_hi]
            # (near the sill: the same cords pass over this stretch again ten units up, at the second switch)
            riding = {c: [p for p in pts if x_lo <= p[0] <= x_hi and abs(p[1] - sill) < 40] for c, pts in t["tubes"].items() if c in ("c1", "c2", "c3")}
            if not centre or any(not v for v in riding.values()):
                bad.append(f"3D: no envelope ({len(centre)} points) or a member with no tube between the two rings: {{c: len(v) for c, v in riding.items()}}")
            else:
                worst = max((min(dist(p, c) - (r - 1.5) for c, r in centre), cid) for cid, pts in riding.items() for p in pts)
                # (a millimetre, a third of a tube's width: the trunk and each member round their corners on their own arcs)
                if worst[0] > 1.0:
                    bad.append(f"3D: between the rings {worst[1]}'s tube is {worst[0]:.2f} mm outside the envelope")
                # at the rings themselves the envelope's underside is on the sill
                at_ring = [c[1] - r for c, r in centre if c[0] - x_lo < 6 or x_hi - c[0] < 6]
                if not at_ring or abs(min(at_ring) - sill) > 0.75:
                    bad.append(f"3D: the envelope's underside at the rings is at y {min(at_ring) if at_ring else None}, the sill is at {sill}")
                mid = (x_lo + x_hi) / 2
                spots = [min(pts, key=lambda p: abs(p[0] - mid)) for pts in riding.values()]
                close = [(a, b) for i, a in enumerate(spots) for b in spots[i + 1:] if dist(a[1:], b[1:]) < 1]
                if close:
                    bad.append(f"3D: midway along the lacer two members share one line: {close}")
        if not t["straps"] or any(abs(st["radius"] - (st["pack"] / 2 + 1.5)) > 0.01 for st in t["straps"]):
            bad.append(f"3D: a strap is not a band round its pack (its radius and 1.5 mm): {t['straps']}")
    # ── the trunk thins as cables peel off, and no peel crosses the cables that ride on ──
    open_front_fixture(page, base, PEEL_FIXTURE, cables=5)
    page.wait_for_function("() => document.querySelector('#paneFront [data-bundle-id=\"b1\"] [data-bundle-trunk]')", timeout=READY_MS)
    g = page.evaluate(PACK_2D_JS)
    met = page.evaluate("() => window.__rack.bundles()[0]")
    if not g or not g["stretches"]:
        return bad + ["peel: no envelope stretches on the front pane"]
    by_y = sorted(g["stretches"], key=lambda s: -max(s["y0"], s["y1"]))     # lowest on the rack first
    riders = [s["riders"] for s in by_y]
    if riders != sorted(riders) or riders[0] != 2 or riders[-1] != 5:
        bad.append(f"peel: going up, the stretches hold {riders} cables; expected 2 at the bottom growing to all 5")
    for s in (by_y[0], by_y[-1]):
        if s["kit"] is None or abs(s["width"] - s["kit"]) > 0.05:
            bad.append(f"peel: the stretch with {s['riders']} riding is {s['width']} wide, not the kit's {s['kit']} for the members left")
    if abs(by_y[-1]["width"] - met["diameter"]) > 0.05 or not by_y[0]["width"] < by_y[-1]["width"] - 3:
        bad.append(f"peel: the trunk is {by_y[0]['width']} wide at its thin end and {by_y[-1]['width']} at its thick end; the kit's size is {met['diameter']}")
    for s in g["stretches"]:
        if s["reach"] > s["width"] / 2 - 1.5 + 0.3:
            bad.append(f"peel: with {s['riders']} riding a member's stroke is {s['reach']:.2f} mm from the stretch's line, outside the half width {s['width'] / 2:.2f}")
    # Each member's trunk line is its run in the gutter (x left of the rail);
    # its peel is where it leaves the gutter for its own switch, below the top
    # stretch's end, where all five turn in to the top switch together.
    top = min(min(s["y0"], s["y1"]) for s in g["stretches"])
    crossings = []
    for a in g["members"]:
        peel = [q for q in g["line"][a] if q[1] > top + 15]
        for b in g["members"]:
            if a == b:
                continue
            trunk = [q for q in g["line"][b] if q[0] < -26 and q[1] > top + 15]
            hit = any(segments_cross(peel[i], peel[i + 5], trunk[j], trunk[j + 5])
                      for i in range(0, len(peel) - 5, 5) for j in range(0, len(trunk) - 5, 5))
            if hit:
                crossings.append((a, b))
    if crossings:
        bad.append(f"peel: a member's line crosses another's trunk line below the top: {crossings}")
    if not all(len(g["line"][c]) > 50 for c in g["members"]):
        bad.append("peel: a member has no stroke on the front pane, so its crossings were not measured")
    return bad


# A strap on the front pane: where its middle is on the page, its core's
# computed colour, the stage's, and its opacity through every ancestor.
STRAP_2D_JS = """() => {
  const svg = document.querySelector('#paneFront svg'), g = svg.querySelector('[data-strap="b1"]');
  if (!g) return null;
  const core = g.querySelector('line[data-strap-part="core"]:not([data-strap-least])'), m = core.getScreenCTM();
  const p = new DOMPoint((+core.getAttribute('x1') + +core.getAttribute('x2')) / 2, (+core.getAttribute('y1') + +core.getAttribute('y2')) / 2).matrixTransform(m);
  let opacity = 1;
  for (let n = g; n && n !== svg.parentNode; n = n.parentNode) opacity *= +getComputedStyle(n).opacity;
  const rimTrue = g.querySelector('line[data-strap-part="rim"]:not([data-strap-least])');
  return {at: [p.x, p.y], coreW: +core.getAttribute('stroke-width'), rimW: +rimTrue.getAttribute('stroke-width'), core: getComputedStyle(core).stroke, rim: getComputedStyle(g.querySelector('[data-strap-part="rim"]')).stroke,
          stage: getComputedStyle(document.getElementById('panes')).backgroundColor, opacity: Math.round(opacity * 100) / 100,
          parts: [...g.children].map(l => [l.dataset.strapPart, l.hasAttribute('data-strap-least'), l.getAttribute('vector-effect')]),
          scale: Math.hypot(m.a, m.b), n: svg.querySelectorAll('[data-strap="b1"]').length,
          others: Object.fromEntries([...svg.querySelectorAll('[data-cables] [data-cable][data-cable-id]')].map(n => [n.dataset.cableId, +getComputedStyle(n).opacity]))};
}"""
STRAP_3D_JS = """() => {
  const g = window.__rack.scene().three.scene.getObjectByName('bundle-b1'), s = g?.children.find(o => o.userData.strap);
  return s ? {color: '#' + s.material.color.getHexString(), transparent: s.material.transparent, opacity: s.material.opacity} : null;
}"""


def strap_extent(px, w, h, at, core):
    """How many pixels of the strap's own colour run through `at`, across and down the page."""
    near = lambda c: max(abs(a - b) for a, b in zip(c, core)) <= 40
    x0, y0 = int(at[0]), int(at[1])
    if not (0 <= x0 < w and 0 <= y0 < h) or not near(px(x0, y0)):
        return (0, 0)
    def run(dx, dy):
        n, x, y = 0, x0 + dx, y0 + dy
        while 0 <= x < w and 0 <= y < h and near(px(x, y)):
            n, x, y = n + 1, x + dx, y + dy
        return n
    return (1 + run(-1, 0) + run(1, 0), 1 + run(0, -1) + run(0, 1))


@extra("rack.html: a bundle's straps can be seen - in 2D a quiet band, a muted light grey on a dark stage and a muted dark grey on a light one, each with a hairline rim in a muted tone and no white outline (4.5 to under 8 to 1 against the stage), never under 4 px on screen at Fit on a 42U rack, lit with their bundle (a member selected or hovered) and dimmed with it (another cable), in the stage's strap colour in 3D, and black on a sheet whatever the stage")
def check_rack_straps_seen(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_front_fixture(page, base, PACK_FIXTURE)
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'pack'})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneFront [data-strap=\"b1\"]') && window.__rack.routesCurrent().current", timeout=READY_MS)
    page.click("#zoomFit")
    page.wait_for_timeout(400)
    park_mouse(page)
    ratios = {}
    for stage, tone, want in (("#101214", "dark", ("#8a9199", "#2a2f35")), ("#ffffff", "light", ("#5b6169", "#c9cdd2"))):
        page.click(f'#stagebg .sw[data-c="{stage}"]')
        page.wait_for_timeout(300)
        page.evaluate("() => document.querySelector('#paneFront [data-strap=\"b1\"]').scrollIntoView({block: 'center', inline: 'center'})")
        page.wait_for_timeout(200)
        s = page.evaluate(STRAP_2D_JS)
        if not s:
            return bad + [f"{tone}: no strap for b1 on the front pane"]
        core, rim, ground = rgb_of(s["core"]), rgb_of(s["rim"]), rgb_of(s["stage"])
        if (core, rim) != (rgb_of(want[0]), rgb_of(want[1])) or ground != rgb_of(stage):
            bad.append(f"{tone}: the strap is {core} with a {rim} rim on a {ground} stage, expected {want} on {stage}")
        ratios[tone] = contrast_ratio(core, ground)
        # S-0040: a quiet band, not a block: seen (4.5 to 1 or more) but not bright (under 8 to 1), and no white or high-contrast outline
        if not 4.5 <= ratios[tone] < 8:
            bad.append(f"{tone}: the strap's contrast with the stage is {ratios[tone]:.1f} to 1, expected from 4.5 to under 8")
        if min(rim) > 235 or contrast_ratio(rim, core) > 5 or contrast_ratio(rim, ground) > 5:
            bad.append(f"{tone}: the strap's rim {rim} is a white or high-contrast outline against its core {core} and the {ground} stage")
        if s["rimW"] > s["coreW"] + 1.5 or s["coreW"] * s["scale"] > 7:
            bad.append(f"{tone}: the strap is {s['coreW']:.1f} units wide with a rim {s['rimW']:.1f} wide, expected a hairline rim and a narrow band")
        if [p[:2] for p in s["parts"]] != [["rim", False], ["rim", True], ["core", False], ["core", True]] or any(p[1] and p[2] != "non-scaling-stroke" for p in s["parts"]):
            bad.append(f"{tone}: a strap is not a rim and a core at its true size and again at its least: {s['parts']}")
        # on the composited page, at Fit: the strap's own colour, at least 6 px along the run and across it
        w, h, px = png_pixels(page.screenshot())
        ext = strap_extent(px, w, h, s["at"], core)
        if s["scale"] * 10 >= 6:
            bad.append(f"{tone} fixture: at Fit a 10 mm strap is {s['scale'] * 10:.1f} px, so the least size was not what was measured")
        if min(ext) < 4:
            bad.append(f"{tone}: at Fit the strap is {ext[0]} x {ext[1]} px of its own colour on the page, under 4 (a 10 mm bar is {s['scale'] * 10:.1f} px here)")
        if s["opacity"] != 1:
            bad.append(f"{tone}: the strap is at opacity {s['opacity']} with nothing selected")
    print(f"[check_rack_straps_seen] strap against the stage: dark {ratios.get('dark', 0):.1f} to 1, light {ratios.get('light', 0):.1f} to 1; at least 4 px at Fit")
    page.click('#stagebg .sw[data-c="#101214"]')
    # A STRAP GOES WITH ITS BUNDLE. A cable that rides it selected, then hovered: the strap stays at
    # full strength. A cable that does not (c4): the strap dims with its bundle's cables.
    for cable, rides in (("c1", True), ("c4", False)):
        page.click(f'#cableList [data-cable-row="{cable}"]')
        page.wait_for_function("c => document.querySelector(`#paneFront [data-cable-id=\"${c}\"].on`)", arg=cable, timeout=READY_MS)
        park_mouse(page)
        page.wait_for_timeout(300)
        s = page.evaluate(STRAP_2D_JS)
        if (s["opacity"] == 1) != rides or (not rides and s["opacity"] > 0.25):
            bad.append(f"selected: with {cable} selected the strap is at {s['opacity']}; expected {'full strength' if rides else 'dimmed with its bundle'}")
        page.click(f'#cableList [data-cable-row="{cable}"]')
        page.wait_for_function("() => !document.querySelector('#paneFront [data-cable-id].on')", timeout=READY_MS)
        page.hover(f'#cableList [data-cable-row="{cable}"]')
        page.wait_for_timeout(350)
        s = page.evaluate(STRAP_2D_JS)
        if (s["opacity"] == 1) != rides or (not rides and s["opacity"] > 0.25):
            bad.append(f"hover: with {cable} hovered the strap is at {s['opacity']}; expected {'full strength' if rides else 'dimmed with its bundle'}")
        park_mouse(page)
    if page.evaluate(STRAP_2D_JS)["opacity"] != 1:
        bad.append("after: with nothing selected or hovered the strap is not back at full strength")
    # ...and it does dim when a bundle is lit that is not its own.
    dim = page.evaluate("""async () => {
      const H = await import('/site/rack/hover.js'), svgs = [...document.querySelectorAll('#paneFront > svg, #paneRear > svg')];
      H.paintHover2d(svgs, {cables: new Set(), bundles: new Set(['another'])});
      await new Promise(r => setTimeout(r, 300));
      const op = +getComputedStyle(document.querySelector('#paneFront [data-strap="b1"]')).opacity;
      H.paintHover2d(svgs, null);
      return op;
    }""")
    if dim > 0.2:
        bad.append(f"hover: with another bundle lit the strap is at {dim}, expected dimmed")
    # A sheet is paper: a black strap with a white rim, whatever the stage (dark here).
    sheet = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      return (await X.sheetSvg(window.__rack.doc().racks[0], (await C.loadCatalog('/assets/dist/')).chassisOf, {faces: ['front']})).data;
    }""")
    ns = "{http://www.w3.org/2000/svg}"
    bars = [g for g in ET.fromstring(sheet.encode("utf-8")).iter(f"{ns}g") if g.get("data-strap") == "b1"]
    paint = sorted({(l.get("data-strap-part"), l.get("stroke")) for g in bars for l in g})
    if not bars or paint != [("core", "#1b1d20"), ("rim", "#ffffff")]:
        bad.append(f"sheet: {len(bars)} straps, painted {paint}; expected a black core and a white rim")
    if webgl_trouble(page):
        print("[check_rack_straps_seen] no WebGL here - the 3D half was not checked")
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the straps' scene", tubes=True)
    park_mouse(page)
    s3 = page.evaluate(STRAP_3D_JS)
    if not s3 or s3["color"] != "#d5d9de":
        bad.append(f"3D: on the black stage a strap is {s3}, expected #d5d9de")
    page.hover('#cableList [data-cable-row="c1"]')
    page.wait_for_timeout(350)
    s3 = page.evaluate(STRAP_3D_JS)
    if not s3 or s3["transparent"] or s3["opacity"] != 1:
        bad.append(f"3D: with a cable that rides its bundle hovered a strap is dimmed: {s3}")
    page.hover('#cableList [data-cable-row="c4"]')
    page.wait_for_timeout(350)
    s3 = page.evaluate(STRAP_3D_JS)
    if not s3 or not s3["transparent"] or s3["opacity"] > 0.2:
        bad.append(f"3D: with an unrelated cable hovered a strap is not dimmed with its bundle: {s3}")
    park_mouse(page)
    s3 = page.evaluate(STRAP_3D_JS)
    if not s3 or s3["transparent"] or s3["opacity"] != 1:
        bad.append(f"3D: with nothing hovered a strap is not back at full strength: {s3}")
    page.click('#stagebg .sw[data-c="#ffffff"]')
    page.wait_for_timeout(300)
    s3 = page.evaluate(STRAP_3D_JS)
    if not s3 or s3["color"] != "#1b1d20":
        bad.append(f"3D: on the white stage a strap is {s3}, expected #1b1d20")
    page.click('#stagebg .sw[data-c="#101214"]')
    return bad


# A half-unit panel (the Fibrain XCU10: catalogue ru 0.5, 22.2 mm) at U20 and
# another at U23 with a fibre between them, a 1U switch at U21 and a 2U switch
# at U18.
HALF_U_FIXTURE = """async () => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.newRack({name: 'Half U'});
  ({rack: r} = M.withItem(r, {ref: 'xcu', cfg: 'xcu10-21ic', ru: 20, face: 'front', label: 'xcu-a'}));
  ({rack: r} = M.withItem(r, {ref: 'ws-c4948e', cfg: cat['ws-c4948e'].default, ru: 21, face: 'front', label: 'sw-1u'}));
  ({rack: r} = M.withItem(r, {ref: 'dcs500', cfg: 'ac-f2b', ru: 18, face: 'front', label: 'sw-2u'}));
  ({rack: r} = M.withItem(r, {ref: 'xcu', cfg: 'xcu10-21ic', ru: 23, face: 'front', label: 'xcu-b'}));
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'drawer/module/slot-1/module/lc01', view: 'front'},
                               b: {item: 'i4', path: 'drawer/module/slot-1/module/lc01', view: 'front'}, media: 'os2'}));
  return r;
}"""
# Each item on the front pane, in pane mm: its face group's translate, its
# face's declared height (read from the compiled file), its ears' flange and
# screw heads, and where the cable leaves the XCU; with the kit's port height.
HALF_U_2D_JS = """async () => {
  const {RU} = await import('/vendor/rack/rails.js'), C = await import('/vendor/rack/catalog.js'), F = await import('/site/faces.js').catch(() => null);
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  const rack = window.__rack.doc().racks[0], svg = document.querySelector('#paneFront svg'), H = rack.frame.heightRU * RU;
  const out = {RU, H, items: {}};
  for (const it of rack.items) {
    const g = svg.querySelector(`[data-item-id="${it.id}"][data-panel="mounted"]`);
    const [tx, ty] = /translate\\(([-\\d.e]+) ([-\\d.e]+)\\)/.exec(g.getAttribute('transform')).slice(1).map(Number);
    const face = g.querySelector('[data-class="chassis"]');
    const h = +face.getAttribute('height'), y0 = +face.getAttribute('y') || 0;
    const ears = svg.querySelector(`.rk-ears[data-ears-for="${it.id}"]`);
    out.items[it.id] = {ref: it.ref, ru: it.ru, catRu: cat[it.ref].ru, ty, h, y0,
      flanges: [...(ears?.querySelectorAll('rect') ?? [])].map(r => [+r.getAttribute('y'), +r.getAttribute('height')]),
      screws: [...(ears?.querySelectorAll('circle') ?? [])].map(c => +c.getAttribute('cy'))};
  }
  // where the cable's strands start: at its plugs' own cable points (the two of a duplex pair, each end)
  const ends = [...svg.querySelectorAll('[data-cables] [data-cable-id="c1"] path')].map(p => {
    const q = p.getPointAtLength(0), w = new DOMPoint(q.x, q.y).matrixTransform(svg.getScreenCTM().inverse().multiply(p.getScreenCTM())); return [w.x, w.y]; });
  const pts = window.__rack.paths().c1.points;
  out.cable = {ends, a: pts.find(q => q.at === 'a').y, b: pts.find(q => q.at === 'b').y};
  return out;
}"""
HALF_U_3D_JS = """async () => {
  const s = window.__rack.scene(), w = s.three.scene, THREE = s.three.THREE, out = {};
  for (const id of ['i1', 'i2', 'i3']) {
    const g = w.getObjectByName(`device-${id}`), e = w.getObjectByName(`ears-${id}`);
    const body = g.children.find(o => o.isMesh && o.geometry.type === 'BoxGeometry');
    const flanges = [], heads = [];
    e?.traverse(o => { if (!o.isMesh) return;
      if (o.geometry.type === 'BoxGeometry' && o.geometry.parameters.width === 24) flanges.push([o.position.y, o.geometry.parameters.height]);
      if (o.geometry.type === 'CylinderGeometry') heads.push(o.position.y); });
    out[id] = {y: g.position.y, h: body.geometry.parameters.height, flanges, heads};
  }
  const port = await s.portAnchor({id: 'i1'}, 'drawer/module/slot-1/module/lc01', {view: 'front'});
  out.port = port ? port.position.y : null;
  return out;
}"""


@extra("rack.html: a body under one unit (the half-unit XCU10) sits in the lower half of its unit in 2D and 3D - its face, its port and cable, and an ear as tall as itself with one screw at the hole that half holds - and a 1U and a 2U device are exactly where they were")
def check_rack_half_unit(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_front_fixture(page, base, HALF_U_FIXTURE, cables=1)
    g = page.evaluate(HALF_U_2D_JS)
    RU, H = g["RU"], g["H"]
    x, one, two = g["items"]["i1"], g["items"]["i2"], g["items"]["i3"]
    if x["catRu"] != 0.5 or abs(x["h"] - 22.2) > 1e-9 or one["catRu"] != 1 or two["catRu"] != 2:
        return bad + [f"fixture: the catalogue gives the XCU ru {x['catRu']} and height {x['h']}, the switches ru {one['catRu']} and {two['catRu']}"]
    bottom = lambda it: H - (it["ru"] - 1) * RU          # pane y of the bottom of the item's lowest unit
    # ── 2D: the XCU's face is in the lower half of U20, centred in that half ──
    top = x["ty"] + x["y0"]
    if not (bottom(x) - RU / 2 - 1e-6 <= top and top + x["h"] <= bottom(x) + 1e-6):
        bad.append(f"2D: the XCU's face runs y {top:.3f} to {top + x['h']:.3f}; the lower half of U20 is {bottom(x) - RU / 2:.3f} to {bottom(x):.3f}")
    if abs((top + x["h"] / 2) - (bottom(x) - RU / 4)) > 1e-6:
        bad.append(f"2D: the XCU's face is not centred in the lower half of its unit (centre {top + x['h'] / 2:.4f}, the half's {bottom(x) - RU / 4:.4f})")
    # its ear: as tall as the half unit it fills (the kit's itemBox lo to hi; it was as tall as the body,
    # 22.2 of the half's 22.225 mm), with one screw a side at the one hole that half holds (the kit's holesIn)
    half_top = bottom(x) - RU / 2
    if len(x["flanges"]) != 2 or any(abs(y - half_top) > 1e-6 or abs(h - RU / 2) > 1e-6 for y, h in x["flanges"]):
        bad.append(f"2D: the XCU's ear flanges are {x['flanges']}, expected two from y {half_top:.3f}, {RU / 2} tall (the lower half of U20)")
    if len(x["screws"]) != 2 or any(abs(cy - (bottom(x) - 6.35)) > 1e-6 for cy in x["screws"]):
        bad.append(f"2D: the XCU's screws are at {x['screws']}, expected one a side at {bottom(x) - 6.35:.3f} (6.35 mm above the unit's bottom)")
    # its port: the cable leaves it inside the body, and the kit's height for the port is in the lower half too
    # (its strands start at its plugs; those in the lower half of the pane's span of them are the XCU at U20's)
    ys = [q[1] for q in g["cable"]["ends"]]
    at_x = [q for q in g["cable"]["ends"] if q[1] > (min(ys) + max(ys)) / 2 and bottom(x) - RU <= q[1] <= bottom(x)]
    end = at_x[0] if at_x else [0, -1]
    if not at_x or any(not top <= q[1] <= top + x["h"] for q in at_x):
        bad.append(f"2D: the cable leaves the XCU at y {[round(q[1], 2) for q in at_x]}, not inside its face ({top:.2f} to {top + x['h']:.2f})")
    ya = g["cable"]["a"]
    if not 19 * RU <= ya <= 19.5 * RU or abs((H - ya) - end[1]) > 3:
        bad.append(f"2D: the kit's height for the XCU's port is {ya:.2f} mm, the pane draws the cable from {H - end[1]:.2f}; the lower half of U20 is {19 * RU:.2f} to {19.5 * RU:.2f}")
    # ── 2D: the 1U and the 2U device are exactly where the centred formula has always put them ──
    for it, u in ((one, 1), (two, 2)):
        was = (H - (it["ru"] - 1 + u) * RU) + (u * RU - it["h"]) / 2 - it["y0"]
        # (to 1e-9 mm: the place is the kit's itemBox now, the same sum in another order, and differs in the last bit)
        if abs(it["ty"] - was) > 1e-9:
            bad.append(f"2D: the {u}U {it['ref']} is at y {it['ty']!r}, it was at {was!r}")
        t0, t1 = H - (it["ru"] - 1 + u) * RU, H - (it["ru"] - 1) * RU
        if len(it["flanges"]) != 2 or any(abs(y - t0) > 1e-9 or abs(h - (t1 - t0)) > 1e-9 for y, h in it["flanges"]):
            bad.append(f"2D: the {u}U {it['ref']}'s ear flanges are {it['flanges']}, they were two from {t0}, {t1 - t0} tall")
        want = sorted([H - (it["ru"] - 1 + k) * RU - dy for k in range(u) for dy in (6.35, 38.10)] * 2)
        if len(it["screws"]) != len(want) or any(abs(a - b) > 1e-9 for a, b in zip(sorted(it["screws"]), want)):
            bad.append(f"2D: the {u}U {it['ref']}'s screws are at {sorted(it['screws'])}, they were at {want}")
    if webgl_trouble(page):
        print("[check_rack_half_unit] no WebGL here - the 3D half was not checked")
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the half-unit scene", tubes=True)
    t = page.evaluate(HALF_U_3D_JS)
    x3, base_y = t["i1"], 19 * RU
    lo, hi = x3["y"] - x3["h"] / 2, x3["y"] + x3["h"] / 2
    if not (base_y - 1e-6 <= lo and hi <= base_y + RU / 2 + 1e-6) or abs(x3["y"] - (base_y + RU / 4)) > 1e-6:
        bad.append(f"3D: the XCU's body runs y {lo:.3f} to {hi:.3f}; the lower half of U20 is {base_y:.3f} to {base_y + RU / 2:.3f}, centred at {base_y + RU / 4:.4f}")
    # the two views agree: the body's place above the unit's bottom is the same
    if abs((lo - base_y) - (bottom(x) - (top + x["h"]))) > 1e-6:
        bad.append(f"2D and 3D: the XCU's body is {bottom(x) - (top + x['h']):.4f} mm above its unit's bottom in 2D and {lo - base_y:.4f} in 3D")
    # (over the half it fills, 2 mm clear, as a whole unit's is 4.5 mm clear of its span; it was as tall as the body)
    if len(x3["flanges"]) != 2 or any(abs(y - (base_y + RU / 4)) > 1e-6 or abs(h - (RU / 2 - 2)) > 1e-6 for y, h in x3["flanges"]):
        bad.append(f"3D: the XCU's ear flanges are {x3['flanges']} (centre y, height), expected two at {base_y + RU / 4:.3f}, {RU / 2 - 2} tall")
    if len(x3["heads"]) != 2 or any(abs(y - (base_y + 6.35)) > 1e-6 for y in x3["heads"]):
        bad.append(f"3D: the XCU's screw heads are at {x3['heads']}, expected one a side at {base_y + 6.35:.3f}")
    if t["port"] is None or not lo <= t["port"] <= hi or abs(t["port"] - ya) > 1.0:
        bad.append(f"3D: the XCU's port is at y {t['port']}, the kit's height for it is {ya:.2f} and its body runs {lo:.2f} to {hi:.2f}")
    for key, it, u in (("i2", one, 1), ("i3", two, 2)):
        d = t[key]
        # CENTRED IN ITS SPAN, as the kit's itemBox and its solids have it (rack file version 4, decision 2): it
        # stood on the bottom of its lowest unit, (u x RU - h) / 2 lower. The 2D face and the 3D body now agree.
        mid = (it["ru"] - 1) * RU + u * RU / 2
        if abs(d["y"] - mid) > 1e-9:
            bad.append(f"3D: the {u}U {it['ref']} is at y {d['y']!r}, the middle of its span is {mid!r}")
        top2d = H - (it["ty"] + it["y0"] + it["h"] / 2)      # the 2D face's middle, mm above the bottom of the rails
        if abs(d["y"] - top2d) > 1e-6:
            bad.append(f"2D and 3D: the {u}U {it['ref']}'s body is centred at {top2d:.4f} in 2D and {d['y']:.4f} in 3D")
        if len(d["flanges"]) != 2 or any(abs(y - mid) > 1e-9 or abs(h - (u * RU - 4.5)) > 1e-9 for y, h in d["flanges"]):
            bad.append(f"3D: the {u}U {it['ref']}'s ear flanges are {d['flanges']}, they were two at {mid}, {u * RU - 4.5} tall")
        want = sorted([(it["ru"] - 1) * RU + k * RU + dy for k in range(u) for dy in (6.35, 38.10)] * 2)
        if len(d["heads"]) != len(want) or any(abs(a - b) > 1e-9 for a, b in zip(sorted(d["heads"]), want)):
            bad.append(f"3D: the {u}U {it['ref']}'s screw heads are at {sorted(d['heads'])}, they were at {want}")
    return bad


# What is pinned, as the page shows it: per cable its opacity on the front
# pane and whether it is .on, the pressed rows, whether b1's envelope shows,
# and in the scene each cable's material and b1's envelope.
PIN_STATE_JS = """() => {
  const svg = document.querySelector('#paneFront > svg'), out = {two: {}, three: null};
  if (svg && !document.getElementById('panes').hidden) {
    for (const n of svg.querySelectorAll('[data-cables] [data-cable][data-cable-id]'))
      out.two[n.dataset.cableId] = [n.classList.contains('on'), Math.round(+getComputedStyle(n).opacity * 100) / 100];
    const env = svg.querySelector('[data-bundle-id="b1"] [data-envelope]');
    out.envelope2 = !!env && getComputedStyle(env).visibility === 'visible';
    out.hovering = svg.classList.contains('cable-hover');
    const strap = svg.querySelector('[data-strap="b1"]');
    if (strap) { let op = 1; for (let n = strap; n && n !== svg.parentNode; n = n.parentNode) op *= +getComputedStyle(n).opacity; out.strap2 = Math.round(op * 100) / 100; }
  }
  out.pressed = [...document.querySelectorAll('#cableList [aria-pressed="true"]')].map(b => b.dataset.cableRow ?? b.dataset.bundleRow);
  out.panel = !!document.getElementById('bundlePanel');
  out.pin = document.getElementById('bPin')?.getAttribute('aria-pressed') ?? null;
  const w = window.__rack.scene()?.three?.scene, g = w?.getObjectByName('patch-cables');
  if (g && !document.getElementById('stage3d').hidden) {
    out.three = {};
    for (const c of g.children) { const m = c.children.find(o => o.isMesh).material; out.three[c.name.slice(6)] = [m.transparent, Math.round(m.opacity * 1000) / 1000]; }
    out.envelope3 = (w.getObjectByName('bundle-b1')?.children ?? []).filter(o => o.userData.envelope).map(o => o.visible);
    const band = (w.getObjectByName('bundle-b1')?.children ?? []).find(o => o.userData.strap);
    out.strap3 = band ? [band.material.transparent, Math.round(band.material.opacity * 1000) / 1000] : null;
  }
  return out;
}"""


def pin_wrong(st, lit, envelope, where):
    """What is wrong with a state for these cables pinned (none: nothing pinned)."""
    bad = []
    for c, (on, op) in (st.get("two") or {}).items():
        if lit and c in lit and (not on or op != 1):
            bad.append(f"{where}: 2D {c} should be lit, is on={on} opacity={op}")
        if lit and c not in lit and (on or op > 0.25):
            bad.append(f"{where}: 2D {c} should be dimmed, is on={on} opacity={op}")
        if not lit and (on or op != 1):
            bad.append(f"{where}: 2D {c} should be as drawn, is on={on} opacity={op}")
    if st.get("two") and st.get("envelope2") != envelope:
        bad.append(f"{where}: 2D b1's envelope is {'shown' if st.get('envelope2') else 'hidden'}")
    for c, (tr, op) in (st.get("three") or {}).items():
        if (not lit or c in lit) and (tr or op != 1):
            bad.append(f"{where}: 3D {c} should be at full strength, its material is transparent={tr} opacity={op}")
        if lit and c not in lit and (not tr or op > 0.2):
            bad.append(f"{where}: 3D {c} should be dimmed, its material is transparent={tr} opacity={op}")
    if st.get("three") is not None and (not st.get("envelope3") or any(v != envelope for v in st["envelope3"])):
        bad.append(f"{where}: 3D b1's envelope is {st.get('envelope3')}, expected {'shown' if envelope else 'hidden'}")
    # b1's straps go with b1: lit while it or a cable that rides it is pinned (or nothing is), dimmed with it otherwise
    rides = not lit or bool(set(lit) & {"c1", "c2", "c3"})
    if st.get("two") and "strap2" in st and ((st["strap2"] == 1) != rides or (not rides and st["strap2"] > 0.25)):
        bad.append(f"{where}: 2D b1's strap is at opacity {st['strap2']}, expected {'full strength' if rides else 'dimmed with its bundle'}")
    if st.get("three") is not None and st.get("strap3") and (st["strap3"] == [False, 1]) != rides:
        bad.append(f"{where}: 3D b1's strap is {st['strap3']}, expected {'full strength' if rides else 'dimmed with its bundle'}")
    return bad


@extra("rack.html: a click on a cable's or a bundle's row pins its highlight - the rest stay dimmed in 2D and 3D through a switch of view, an orbit drag, a hover over another cable and a click on a control - and a click on empty stage or page, Escape or the row again puts it down")
def check_rack_pinned_highlight(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    res = hover_fixture(page, base)
    if res and res.get("error"):
        return bad + [f"fixture: the bundle was not made: {res['error']}"]
    state = lambda: page.evaluate(PIN_STATE_JS)

    def put_down(js):
        # (a pin that is not put down is a finding, not a timeout: it is said, then put down with Escape so the rest is still tried)
        try:
            page.wait_for_function(js, timeout=5000)
        except Exception:
            st = state()
            bad.append(f"not put down: still pinned (pressed rows {st['pressed']}, bundle panel {'open' if st['panel'] else 'closed'}) after the step before \"{steps[-1] if steps else 'the first check'}\"")
            page.keyboard.press("Escape")
            page.wait_for_timeout(400)
    steps = []
    see = lambda lit, env, where: (steps.append(where), bad.extend(pin_wrong(state(), lit, env, where)))
    park_mouse(page)
    see(None, False, "nothing pinned")
    # ── a cable, in 2D ──
    page.click('#cableList [data-cable-row="c4"]')
    page.wait_for_function("() => document.querySelector('#paneFront [data-cable-id=\"c4\"].on')", timeout=READY_MS)
    park_mouse(page)
    see({"c4"}, False, "c4's row clicked")
    if state()["pressed"] != ["c4"] or state().get("hovering"):
        bad.append(f"c4's row clicked: the pressed rows are {state()['pressed']} and the pane is {'in' if state().get('hovering') else 'not in'} hover; expected c4 pressed and no hover")
    # a hover over another cable previews it, and the pin returns when the pointer leaves
    page.hover('#cableList [data-cable-row="c1"]')
    page.wait_for_timeout(350)
    h = state()["two"]
    if h["c1"][1] != 1 or h["c4"][1] > 0.25:
        bad.append(f"2D: hovering c1 while c4 is pinned shows c1 at {h['c1'][1]} and c4 at {h['c4'][1]}; expected c1 lit and c4 dimmed for the while")
    park_mouse(page)
    see({"c4"}, False, "2D, the pointer gone from c1")
    # THE HOVER LABEL BESIDE THE POINTER (#cableTip) and the pin live together: over another cable's
    # stroke the label says that cable, as ever, and the pin holds; over the pinned cable's own
    # stroke there is no label (it is selected, and its pressed row says it all).
    on_stroke = """async id => {
      const H = await import('/site/rack/hover.js'), svg = document.querySelector('#paneFront > svg');
      for (const p of svg.querySelectorAll(`[data-cables] [data-cable][data-cable-id="${id}"] path`)) {
        const L = p.getTotalLength(), m = p.getScreenCTM();
        for (let f = 0.1; f < 0.95; f += 0.03) {
          const q = p.getPointAtLength(L * f), s = new DOMPoint(q.x, q.y).matrixTransform(m), el = document.elementFromPoint(s.x, s.y);
          if (!el?.closest('#paneFront')) continue;
          const t = H.hoverAt2d(svg, {clientX: s.x, clientY: s.y, target: el});
          if (t?.kind === 'cable' && t.id === id) return [s.x, s.y];
        }
      }
      return null; }"""
    tip = "() => { const t = document.getElementById('cableTip'); return t && !t.hidden ? t.dataset.cableTip : null; }"
    at1, at4 = page.evaluate(on_stroke, "c1"), page.evaluate(on_stroke, "c4")
    if not at1 or not at4:
        bad.append(f"label: found no point on c1's stroke ({at1}) or on c4's ({at4}) to hover")
    else:
        page.mouse.move(at1[0], at1[1])
        page.wait_for_timeout(400)
        if page.evaluate(tip) != "c1":
            bad.append(f"label: over c1's stroke with c4 pinned the hover label names {page.evaluate(tip)!r}, expected c1")
        page.mouse.move(at4[0], at4[1])
        page.wait_for_timeout(400)
        if page.evaluate(tip) is not None:
            bad.append(f"label: over the pinned cable's own stroke the hover label shows ({page.evaluate(tip)!r})")
        park_mouse(page)
        see({"c4"}, False, "2D, after the pointer was over c1's stroke and c4's")
    # a click on a control does not put it down: the zoom, then the stage's swatch
    page.click("#zoomIn")
    page.click("#zoomFit")
    page.click('#stagebg .sw[data-c="#101214"]')
    page.wait_for_timeout(300)
    park_mouse(page)
    see({"c4"}, False, "2D, after clicks on the zoom and a stage swatch")
    if webgl_trouble(page):
        print("[check_rack_pinned_highlight] no WebGL here - the 3D half was not checked")
    else:
        # ── the mode switch does not put it down, and the scene shows it ──
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, "3D: the pinned rack's scene", tubes=True)
        park_mouse(page)
        see({"c4"}, False, "3D, after the switch")
        if state()["pressed"] != ["c4"]:
            bad.append(f"3D: after the switch the pressed rows are {state()['pressed']}")
        # an orbit drag is not a click
        spot = page.evaluate("""async () => {
          const H = await import('/site/rack/hover.js'), s = window.__rack.scene(), r = s.three.renderer.domElement.getBoundingClientRect();
          for (const [fx, fy] of [[0.04, 0.05], [0.96, 0.05], [0.04, 0.95], [0.5, 0.03]]) {
            const x = r.left + r.width * fx, y = r.top + r.height * fy;
            if (document.elementFromPoint(x, y) === s.three.renderer.domElement && !H.hoverAt3d(s, {clientX: x, clientY: y})) return [x, y];
          }
          return null; }""")
        if not spot:
            return bad + ["3D: found no empty point on the scene to drag from and click"]
        cam0 = page.evaluate("() => window.__rack.scene().three.camera.position.toArray()")
        page.mouse.move(spot[0], spot[1])
        page.mouse.down()
        for k in range(1, 9):
            page.mouse.move(spot[0] + 15 * k, spot[1] + 6 * k)
        page.mouse.up()
        page.wait_for_timeout(400)
        cam1 = page.evaluate("() => window.__rack.scene().three.camera.position.toArray()")
        if max(abs(a - b) for a, b in zip(cam0, cam1)) < 1:
            bad.append("3D: the drag did not orbit the scene, so an orbit was not what was tried")
        park_mouse(page)
        see({"c4"}, False, "3D, after an orbit drag")
        page.hover('#cableList [data-cable-row="c1"]')
        page.wait_for_timeout(350)
        h = state()["three"]
        if h["c1"] != [False, 1] or not h["c4"][0]:
            bad.append(f"3D: hovering c1 while c4 is pinned shows c1 {h['c1']} and c4 {h['c4']}; expected c1 lit and c4 dimmed for the while")
        park_mouse(page)
        see({"c4"}, False, "3D, the pointer gone from c1")
        # a click on empty stage puts it down
        spot = page.evaluate("""async () => {
          const H = await import('/site/rack/hover.js'), s = window.__rack.scene(), r = s.three.renderer.domElement.getBoundingClientRect();
          for (const [fx, fy] of [[0.04, 0.05], [0.96, 0.05], [0.04, 0.95], [0.5, 0.03]]) {
            const x = r.left + r.width * fx, y = r.top + r.height * fy;
            if (document.elementFromPoint(x, y) === s.three.renderer.domElement && !H.hoverAt3d(s, {clientX: x, clientY: y})) return [x, y];
          }
          return null; }""")
        page.mouse.click(spot[0], spot[1])
        put_down("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
        park_mouse(page)
        see(None, False, "3D, after a click on empty stage")
        # ── a bundle, in 3D: its members, its envelope; an orbit keeps it; Escape puts it down ──
        page.click('#cableList [data-bundle-row="b1"]')
        page.wait_for_selector("#bundlePanel", timeout=READY_MS)
        park_mouse(page)
        see({"c1", "c2", "c3"}, True, "3D, b1's row clicked")
        page.mouse.move(spot[0], spot[1])
        page.mouse.down()
        for k in range(1, 9):
            page.mouse.move(spot[0] + 12 * k, spot[1] + 9 * k)
        page.mouse.up()
        page.wait_for_timeout(400)
        park_mouse(page)
        see({"c1", "c2", "c3"}, True, "3D, b1 pinned, after an orbit drag")
        page.click('#mode [data-mode="2d"]')
        page.wait_for_function("() => document.querySelector('#paneFront [data-bundle-id=\"b1\"]') && !document.getElementById('panes').hidden", timeout=READY_MS)
        park_mouse(page)
        page.wait_for_timeout(300)
        see({"c1", "c2", "c3"}, True, "2D, b1 pinned, after the switch back")
        page.keyboard.press("Escape")
        put_down("() => !document.getElementById('bundlePanel')")
        park_mouse(page)
        see(None, False, "2D, after Escape")
    # ── a bundle, in 2D; a click on the page's background puts it down ──
    if state()["two"].get("c4", [True])[0] or state()["pressed"]:
        page.keyboard.press("Escape")
        put_down("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
    page.click('#cableList [data-bundle-row="b1"]')
    page.wait_for_selector("#bundlePanel", timeout=READY_MS)
    park_mouse(page)
    page.wait_for_timeout(300)
    see({"c1", "c2", "c3"}, True, "2D, b1's row clicked")
    # THE PANEL'S OWN PIN: its row is behind the panel, so the panel says it is pinned and can put it down and take it up
    if state()["pin"] != "true":
        bad.append(f"panel: the bundle panel's pin control reads aria-pressed={state()['pin']!r} while its bundle is pinned")
    else:
        page.click("#bPin")
        page.wait_for_function("() => document.getElementById('bPin')?.getAttribute('aria-pressed') === 'false'", timeout=READY_MS)
        park_mouse(page)
        page.wait_for_timeout(300)
        see(None, False, "2D, unpinned by the panel's control")
        if not state()["panel"]:
            bad.append("panel: unpinning closed the bundle panel")
        page.click("#bPin")
        page.wait_for_function("() => document.getElementById('bPin')?.getAttribute('aria-pressed') === 'true'", timeout=READY_MS)
        park_mouse(page)
        page.wait_for_timeout(300)
        see({"c1", "c2", "c3"}, True, "2D, pinned again by the panel's control")
    # A BUNDLE COMMAND WHILE IT IS PINNED: the pin stays, and follows the bundle's members
    # (its SPACING straps: the count of every kind need not rise with them, kit 0.22.0)
    n0 = page.evaluate("() => window.__rack.bundles()[0].kinds.spacing")
    page.fill("#bEvery", "6")
    page.press("#bEvery", "Enter")
    page.wait_for_function("n => (window.__rack.bundles() || [])[0]?.kinds.spacing > n && document.querySelectorAll('#paneFront [data-strap=\"b1\"]').length === window.__rack.bundles()[0].count",
                           arg=n0, timeout=READY_MS)
    park_mouse(page)
    page.wait_for_timeout(300)
    see({"c1", "c2", "c3"}, True, "2D, b1 pinned, after its strap spacing changed")
    page.click("#bAdd")
    page.wait_for_function("() => window.__rack.doc().racks[0].bundles[0].members.length === 4 && window.__rack.routesCurrent().current"
                           " && document.querySelector('#paneFront [data-bundle-id=\"b1\"]')?.dataset.members.split(' ').length === 4", timeout=READY_MS)
    park_mouse(page)
    page.wait_for_timeout(300)
    see({"c1", "c2", "c3", "c4"}, True, "2D, b1 pinned, after c4 was added to it")
    page.click("#bPeel-c4")
    page.wait_for_function("() => window.__rack.doc().racks[0].bundles[0].members.length === 3 && window.__rack.routesCurrent().current"
                           " && document.querySelector('#paneFront [data-bundle-id=\"b1\"]')?.dataset.members.split(' ').length === 3", timeout=READY_MS)
    park_mouse(page)
    page.wait_for_timeout(300)
    see({"c1", "c2", "c3"}, True, "2D, b1 pinned, after c4 was peeled out of it")
    if not state()["panel"] or state()["pin"] != "true":
        bad.append(f"panel: after the bundle's commands the panel is {'open' if state()['panel'] else 'closed'} with its pin {state()['pin']!r}")
    page.click("#headFront")
    put_down("() => !document.getElementById('bundlePanel')")
    park_mouse(page)
    see(None, False, "2D, after a click on the page's background")
    # ── the keyboard: Enter on a row pins, Enter again puts it down; a click on empty stage too ──
    page.focus('#cableList [data-cable-row="c1"]')
    page.keyboard.press("Enter")
    page.wait_for_function("() => document.querySelector('#paneFront [data-cable-id=\"c1\"].on')", timeout=READY_MS)
    ring = page.evaluate("() => { const a = document.activeElement; return [a?.dataset?.cableRow ?? null, a?.getAttribute('aria-pressed'), getComputedStyle(a).outlineStyle]; }")
    if ring[:2] != ["c1", "true"] or ring[2] == "none":
        bad.append(f"keyboard: after Enter on c1's row the focused row is {ring[0]!r}, aria-pressed {ring[1]!r}, outline {ring[2]!r}; expected c1, pressed, ringed")
    park_mouse(page)
    see({"c1"}, True, "keyboard, Enter on c1's row")
    # Escape puts it down altogether: focus is still on the row, and must not light it again as a hover
    page.keyboard.press("Escape")
    put_down("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
    page.wait_for_timeout(400)
    if page.evaluate("() => document.activeElement?.dataset?.cableRow ?? null") != "c1":
        bad.append("keyboard: Escape moved focus off c1's row, so focus on the row was not what was tried")
    see(None, False, "keyboard, Escape with focus still on c1's row")
    if state().get("hovering"):
        bad.append("keyboard: after Escape the pane is still in hover, from the focus left on the row")
    page.keyboard.press("Enter")
    page.wait_for_function("() => document.querySelector('#paneFront [data-cable-id=\"c1\"].on')", timeout=READY_MS)
    page.evaluate("() => document.activeElement?.blur()")
    park_mouse(page)
    see({"c1"}, True, "keyboard, Enter on c1's row again")
    page.focus('#cableList [data-cable-row="c1"]')
    page.keyboard.press("Space")
    put_down("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
    page.evaluate("() => document.activeElement?.blur()")
    park_mouse(page)
    see(None, False, "keyboard, Space on the pinned row")
    page.click('#cableList [data-cable-row="c4"]')
    page.wait_for_function("() => document.querySelector('#paneFront [data-cable-id=\"c4\"].on')", timeout=READY_MS)
    gutter = page.evaluate("""() => {
      const svg = document.querySelector('#paneFront > svg'), r = svg.getBoundingClientRect();
      for (const [fx, fy] of [[0.5, 0.004], [0.02, 0.004], [0.98, 0.004]]) {
        const x = r.left + r.width * fx, y = r.top + r.height * fy;
        if (document.elementFromPoint(x, y) === svg) return [x, y];
      }
      return null; }""")
    if not gutter:
        bad.append("2D: found no empty point of the front pane (its own background) to click")
    else:
        # a press held and moved is not a click...
        page.mouse.move(gutter[0], gutter[1])
        page.mouse.down()
        page.mouse.move(gutter[0] + 40, gutter[1] + 1, steps=4)
        page.mouse.up()
        page.wait_for_timeout(300)
        see({"c4"}, False, "2D, after a drag on empty stage")
        # ...and a click there is
        page.mouse.click(gutter[0], gutter[1])
        put_down("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
        park_mouse(page)
        see(None, False, "2D, after a click on empty stage")
    # the pin is the page's: nothing of it in the document that is saved
    doc = json.dumps(page.evaluate("() => window.__rack.doc()"))
    if "pinned" in doc or '"sel"' in doc:
        bad.append("saved: the rack document carries the pin")
    return bad


# WHAT A DOWNLOAD HOLDS OF A BUNDLE, pinned: a change to it should fail here
# and be made on purpose. The GLB as its JSON chunk's nodes and each strap's
# colour, with a digest of the whole file.
BUNDLE_GLB_JS = """async () => {
  const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
  const out = await X.modelFile(window.__rack.scene(), window.__rack.doc().racks[0], 'glb', (await C.loadCatalog('/assets/dist/')).chassisOf);
  const buf = out.data instanceof ArrayBuffer ? out.data : await new Response(out.data).arrayBuffer();
  const dv = new DataView(buf), len = dv.getUint32(12, true);
  const j = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 20, len)));
  const hash = [...new Uint8Array(await crypto.subtle.digest('SHA-256', buf))].map(b => b.toString(16).padStart(2, '0')).join('');
  const names = j.nodes.map(n => n.name || '');
  const sha = async b => [...new Uint8Array(await crypto.subtle.digest('SHA-256', b))].map(x => x.toString(16).padStart(2, '0')).join('');
  // every material and every image in the file: what a stage could have coloured
  const paint = await sha(new TextEncoder().encode(JSON.stringify([j.materials, (j.images || []).map(i => [i.mimeType, j.bufferViews[i.bufferView]?.byteLength])])));
  const imgs = await Promise.all((j.images || []).map(i => { const v = j.bufferViews[i.bufferView]; return sha(new Uint8Array(buf, 20 + len + 8 + (v.byteOffset || 0), v.byteLength)); }));
  const colour = n => { const m = j.materials[j.meshes[n.mesh].primitives[0].material], c = m.pbrMetallicRoughness?.baseColorFactor ?? [1, 1, 1, 1];
    // glTF colours are linear: back to sRGB bytes
    return c.slice(0, 3).map(v => Math.round(255 * (v <= 0.0031308 ? 12.92 * v : 1.055 * Math.pow(v, 1 / 2.4) - 0.055))); };
  return {hash, bytes: buf.byteLength, paint, images: imgs.sort().join(' '), nodes: names.length, cables: names.filter(n => /^cable-c\\d+$/.test(n)).sort(),
          straps: j.nodes.filter(n => /^bundle-b1-strap-\\d+$/.test(n.name || '')).map(colour),
          trunks: names.filter(n => /-trunk$/.test(n)).length, bundle: names.includes('bundle-b1')};
}"""


@extra("rack.html: what a download holds of a bundle - the sheet and the GLB carry its members and the kit's count of straps in fixed ink, never its envelope; the sheet carries the in-front layer; and the GLB is the same file from a dark stage and a light one")
def check_rack_bundle_downloads(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_front_fixture(page, base, PACK_FIXTURE)
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'pack'})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneFront [data-strap=\"b1\"]') && window.__rack.routesCurrent().current", timeout=READY_MS)
    kit = page.evaluate("() => window.__rack.bundles()[0].count")
    if kit < 2:
        return bad + [f"fixture: the kit counts {kit} straps, so a count was not what was measured"]
    # ── the sheet, both faces, from the dark stage with the bundle hovered (so its envelope shows on the page) ──
    page.click('#stagebg .sw[data-c="#101214"]')
    page.hover('#cableList [data-bundle-row="b1"]')
    page.wait_for_timeout(350)
    sheet = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      return (await X.sheetSvg(window.__rack.doc().racks[0], (await C.loadCatalog('/assets/dist/')).chassisOf)).data;
    }""")
    park_mouse(page)
    ns = "{http://www.w3.org/2000/svg}"
    panes = {s.get("data-pane"): s for s in ET.fromstring(sheet.encode("utf-8")).findall(f"{ns}svg")}
    if sorted(panes) != ["front", "rear"]:
        return bad + [f"sheet: its panes are {sorted(panes)}"]
    def held(pane):
        nodes = list(pane.iter())
        return {"cables": sorted({n.get("data-cable-id") for n in nodes if n.get("data-cable") and n.get("data-cable-id")}),
                "straps": [n for n in nodes if n.get("data-strap") == "b1"],
                "envelope": sum(1 for n in nodes if n.get("data-envelope") is not None or n.get("data-bundle-trunk") is not None),
                "front": [k.get("data-front") for g in pane if g.get("data-in-front") is not None for k in g],
                "bundle": sum(1 for n in nodes if n.get("data-bundle-id") == "b1")}
    f, r = held(panes["front"]), held(panes["rear"])
    if f["cables"] != ["c1", "c2", "c3", "c4"] or r["cables"]:
        bad.append(f"sheet: the front face draws cables {f['cables']} and the rear {r['cables']}; expected all four on the front alone")
    if len(f["straps"]) != kit or r["straps"]:
        bad.append(f"sheet: {len(f['straps'])} straps on the front face and {len(r['straps'])} on the rear; the kit counts {kit}, all on the front")
    ink = sorted({(l.get("data-strap-part"), l.get("stroke")) for g in f["straps"] for l in g})
    if ink != [("core", "#1b1d20"), ("rim", "#ffffff")] or any(len(list(g)) != 4 for g in f["straps"]):
        bad.append(f"sheet: a strap is not four lines in fixed ink (a black core, a white rim): {ink}, {[len(list(g)) for g in f['straps']]} lines")
    if f["envelope"] or r["envelope"]:
        bad.append(f"sheet: it carries the bundle's envelope ({f['envelope']} nodes on the front, {r['envelope']} on the rear)")
    if (f["front"].count("ring"), f["front"].count("cover")) != (5, 2) or r["front"]:
        bad.append(f"sheet: the front face's in-front layer holds {f['front']} and the rear's {r['front']}; expected 5 ring legs and 2 covers on the front")
    if webgl_trouble(page):
        print("[check_rack_bundle_downloads] no WebGL here - the GLB was not checked")
        return bad
    # ── the GLB, from the dark stage and from the light one ──
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the downloads' scene", tubes=True)
    page.evaluate("() => window.__rack.scene().settled?.()")
    dark = page.evaluate(BUNDLE_GLB_JS)
    # the file is written in the file's ink; straight after, on the dark stage still, the scene's strap is the stage's own again
    after = page.evaluate(STRAP_3D_JS)
    if not after or after["color"] != "#d5d9de":
        bad.append(f"GLB: straight after the export the scene's strap is {after}, expected the dark stage's #d5d9de again")
    page.click('#stagebg .sw[data-c="#ffffff"]')
    page.wait_for_timeout(400)
    light = page.evaluate(BUNDLE_GLB_JS)
    again = page.evaluate(BUNDLE_GLB_JS)
    page.click('#stagebg .sw[data-c="#101214"]')
    for name, g in (("dark", dark), ("light", light)):
        if g["cables"] != ["cable-c1", "cable-c2", "cable-c3", "cable-c4"] or not g["bundle"]:
            bad.append(f"GLB ({name} stage): its cables are {g['cables']} and bundle-b1 is {'there' if g['bundle'] else 'missing'}")
        if len(g["straps"]) != kit or any(c != [27, 29, 32] for c in g["straps"]):
            bad.append(f"GLB ({name} stage): {len(g['straps'])} straps coloured {g['straps']}; the kit counts {kit}, each #1b1d20")
        if g["trunks"]:
            bad.append(f"GLB ({name} stage): it carries {g['trunks']} envelope tubes")
    # THE SAME FILE FROM EITHER STAGE. Two GLBs of one scene are not the same bytes (the exporter's own
    # stamp differs from one export to the next: `again` is a second export from the light stage), so
    # what is compared is everything a stage could have coloured, and the size: every material, every
    # image's bytes, the node count and the file's length.
    same = lambda a, b: (a["bytes"], a["paint"], a["images"], a["nodes"]) == (b["bytes"], b["paint"], b["images"], b["nodes"])
    if not same(light, again):
        bad.append("GLB: two exports of one scene from one stage differ in their materials, images, nodes or length, so the stages could not be compared")
    elif not same(dark, light):
        bad.append(f"GLB: the file from the dark stage is not the file from the light stage (length {dark['bytes']} and {light['bytes']}, "
                   f"materials {'the same' if dark['paint'] == light['paint'] else 'differ'}, images {'the same' if dark['images'] == light['images'] else 'differ'})")
    if dark["hash"] == light["hash"]:
        print("[check_rack_bundle_downloads] the GLBs from the two stages are the same bytes")
    if (dark["cables"], dark["straps"], dark["trunks"]) != (light["cables"], light["straps"], light["trunks"]):
        bad.append("GLB: its bundle content differs between the dark stage and the light one")
    return bad


# ── THE SIDE PAIR (portrayal-site#187) ────────────────────────────────────
# One switch beside 2D/3D turns the two panes from the rack's faces (Front,
# Rear) to its sides (Left, Right): site/rack/side-elevation.js. The fixture
# has what a side view has to get right: a device on the front rails, one on
# the rear rails, one turned, a lacer bolted over a device, a vertical manager
# beside the left front upright, two patches between ports of the front face
# (through the lacer and up a lane) and one cable from the front to the rear.
SIDE_FIXTURE = """async () => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.newRack({name: 'Sides'});
  const sw = {ref: 'ws-c4948e', cfg: cat['ws-c4948e'].default};
  ({rack: r} = M.withItem(r, {...sw, ru: 20, face: 'front', label: 'sw-front'}));
  ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, face: 'front', label: 'mgr-1', on: 'i1', unit: 1}));
  ({rack: r} = M.withItem(r, {...sw, ru: 30, face: 'front', label: 'sw-top'}));
  ({rack: r} = M.withItem(r, {...sw, ru: 26, face: 'rear', label: 'sw-rear'}));
  ({rack: r} = M.withItem(r, {ref: 'dcs500', cfg: 'ac-f2b', ru: 10, face: 'front', turned: true, label: 'sw-turned'}));
  r = {...r, zeroU: [{id: 'z1', ref: 'cmv-sfd42u9w', cfg: 'base', label: 'duct-1', at: 'left-front', offsetMm: 0}]};
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i3', path: 'port-1', view: 'front'}, media: 'cat6a'}));
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-2', view: 'front'}, b: {item: 'i4', path: 'port-2', view: 'front'}, media: 'cat6'}));
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-3', view: 'front'}, b: {item: 'i3', path: 'port-3', view: 'front'}, media: 'cat6a'}));
  return r;
}"""
SIDE_DRAWN = """() => { const s = [...document.querySelectorAll('#panes > section > div > svg')];
  return s.length === 2 && s[0].dataset.pane === 'left' && s[1].dataset.pane === 'right' && !document.getElementById('panes').hidden; }"""
FACES_DRAWN = """() => { const s = [...document.querySelectorAll('#panes > section > div > svg')];
  return s.length === 2 && s[0].dataset.pane === 'front' && s[1].dataset.pane === 'rear' && !document.getElementById('panes').hidden; }"""


def open_side_fixture(page, base, cables=3):
    """The side fixture, drawn in Front / Rear with its routes read."""
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.evaluate("r => window.__rack.replaceRack(r)", page.evaluate(SIDE_FIXTURE))
    page.wait_for_function("n => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id][data-cable]').length >= 1"
                           " && Object.keys(window.__rack.paths() || {}).length === n && window.__rack.routesCurrent().current",
                           arg=cables, timeout=READY_MS)
    page.wait_for_timeout(400)


def to_sides(page, cables=3):
    page.click('#view2d [data-view="sides"]')
    page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
    if cables:
        page.wait_for_function("n => [...document.querySelectorAll('#panes svg[data-side]')].every(s => s.querySelectorAll('[data-cables] [data-cable-id][data-cable]').length === n)",
                               arg=cables, timeout=READY_MS)
    page.wait_for_timeout(300)


def to_faces(page):
    page.click('#view2d [data-view="faces"]')
    page.wait_for_function(FACES_DRAWN, timeout=READY_MS)
    page.wait_for_timeout(300)


# What the page shows of the pair: the switch, the headings, each pane's own
# kind, the buttons round it, and what is stored.
SIDE_SWITCH_JS = """() => ({
  view: window.__rack.view(),
  pressed: Object.fromEntries([...document.querySelectorAll('#view2d [data-view]')].map(b => [b.dataset.view, [b.getAttribute('aria-pressed'), b.classList.contains('on')]])),
  group: [document.getElementById('view2d').getAttribute('role'), document.getElementById('view2d').getAttribute('aria-label'),
          [...document.querySelectorAll('#view2d [data-view]')].map(b => [b.tagName, b.textContent.trim()])],
  heads: [document.getElementById('headFront').textContent, document.getElementById('headRear').textContent],
  labelled: [...document.querySelectorAll('#panes > section')].map(s => s.getAttribute('aria-labelledby')),
  panes: [...document.querySelectorAll('#panes > section > div > svg')].map(s => s.dataset.pane),
  shown: !document.getElementById('panes').hidden,
  switchInert: document.getElementById('view2d').inert, switchSeen: getComputedStyle(document.getElementById('view2d')).visibility,
  stored: localStorage.getItem('portrayal.rack.view'), url: location.href,
  cable: [document.getElementById('cableBtn').disabled, document.getElementById('cableBtn').title, document.getElementById('cableBtn').getAttribute('aria-pressed')],
  note: document.getElementById('sidesNote')?.textContent ?? null,
})"""


@extra("rack.html: one switch beside 2D/3D turns both panes from Front / Rear to Left / Right and back, with headings and pressed states that follow, is remembered across a reload in this browser, and is in neither the rack file nor the URL (#187)")
def check_rack_side_switch(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_side_fixture(page, base)
    st = lambda: page.evaluate(SIDE_SWITCH_JS)

    def expect(s, view, where):
        heads, panes = (["Left", "Right"], ["left", "right"]) if view == "sides" else (["Front", "Rear"], ["front", "rear"])
        other = "faces" if view == "sides" else "sides"
        if s["view"] != view or s["panes"] != panes:
            bad.append(f"{where}: the panes are {s['panes']} and the page's view is {s['view']!r}; expected {panes}, {view!r}")
        if s["heads"] != heads:
            bad.append(f"{where}: the headings read {s['heads']}, expected {heads}")
        if s["pressed"].get(view) != ["true", True] or s["pressed"].get(other) != ["false", False]:
            bad.append(f"{where}: the switch's buttons are {s['pressed']}; expected {view} pressed and {other} not")
    s0 = st()
    expect(s0, "faces", "at first")
    if s0["group"][0] != "group" or not s0["group"][1] or s0["group"][2] != [["BUTTON", "Front / Rear"], ["BUTTON", "Left / Right"]]:
        bad.append(f"the switch is {s0['group']}; expected a labelled group of two buttons, Front / Rear and Left / Right")
    if s0["labelled"] != ["headFront", "headRear"]:
        bad.append(f"the panes are labelled by {s0['labelled']}, expected their headings")
    if s0["stored"] not in (None, "faces") or s0["note"]:
        bad.append(f"at first: stored view {s0['stored']!r}, side note {s0['note']!r}; expected neither")
    # beside the 2D/3D switch: its neighbour in the bar
    beside = page.evaluate("() => document.getElementById('view2d').nextElementSibling?.id")
    if beside != "mode":
        bad.append(f"the switch's next neighbour in the bar is #{beside}, expected #mode")
    # THE SWITCH ANSWERS AT ONCE: the headings and the busy mark in the very task of the click, the panes when drawn;
    # and it reads nothing again: the routes it draws from are the ones the page already held for this rack
    at_click = page.evaluate("""() => { window.__ctx0 = window.__rack.routeContext(); document.querySelector('#view2d [data-view="sides"]').click();
      return [document.getElementById('panes').getAttribute('aria-busy'), document.getElementById('headFront').textContent, document.getElementById('headRear').textContent,
              getComputedStyle(document.getElementById('panes')).cursor]; }""")
    if at_click != ["true", "Left", "Right", "progress"]:
        bad.append(f"at the click on Left / Right the panes' busy mark, headings and cursor are {at_click}; expected busy, Left, Right, the progress cursor")
    page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
    page.wait_for_function("() => !document.getElementById('panes').hasAttribute('aria-busy')", timeout=READY_MS)
    kept = page.evaluate("() => [window.__rack.routeContext() === window.__ctx0, window.__rack.routesCurrent().current, document.querySelectorAll('#panes svg[data-side] [data-cables] [data-cable][data-cable-id]').length]")
    if kept != [True, True, 6]:
        bad.append(f"after the switch: the same route context {kept[0]}, current {kept[1]}, {kept[2]} cables drawn on the side panes; expected the routes kept and all 3 cables on each pane")
    to_faces(page)
    to_sides(page)
    s1 = st()
    expect(s1, "sides", "after Left / Right")
    if s1["stored"] != "sides":
        bad.append(f"after Left / Right: this browser stores {s1['stored']!r}, expected 'sides'")
    if "sides" in s1["url"].split("rack.html")[1] or "view" in s1["url"].split("rack.html")[1]:
        bad.append(f"after Left / Right: the URL is {s1['url']}; the view is not kept there")
    doc = page.evaluate("() => window.__rack.doc()")
    keys = set(doc) | set(doc["racks"][0]) | set(doc["racks"][0]["frame"])
    if keys & {"view", "view2d", "pair", "sides"} or '"sides"' in json.dumps(doc):
        bad.append(f"after Left / Right: the rack document carries the view ({sorted(keys)})")
    # the two panes are both side panes, one of each, never one face and one side
    kinds = page.evaluate("() => [...document.querySelectorAll('#panes svg[data-pane]')].map(s => [s.dataset.pane, s.dataset.side ?? null, s.querySelectorAll('[data-side-post]').length, s.querySelectorAll('rect.rk-u').length])")
    if kinds != [["left", "true", 2, 0], ["right", "true", 2, 0]]:
        bad.append(f"after Left / Right: the panes are {kinds}; expected a left and a right side pane, each with its two posts and no U target")
    # remembered across a reload
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    try:
        page.wait_for_function(SIDE_DRAWN, timeout=20000)
    except Exception:
        pass
    expect(st(), "sides", "after a reload")
    # 3D keeps the switch's place, out of use, and comes back to the pair it left
    if webgl_trouble(page):
        print("[check_rack_side_switch] no WebGL here - the 3D half was not checked")
    else:
        page.click('#mode [data-mode="3d"]')
        page.wait_for_function("() => document.getElementById('panes').hidden", timeout=READY_MS)
        s3 = st()
        if not s3["switchInert"] or s3["switchSeen"] != "hidden":
            bad.append(f"3D: the Front / Rear | Left / Right switch is inert={s3['switchInert']} visibility={s3['switchSeen']}; expected out of use, keeping its place")
        page.click('#mode [data-mode="2d"]')
        page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
        expect(st(), "sides", "back from 3D")
    to_faces(page)
    s2 = st()
    expect(s2, "faces", "after Front / Rear")
    if s2["stored"] != "faces" or s2["note"] or s2["cable"][0]:
        bad.append(f"after Front / Rear: stored {s2['stored']!r}, side note {s2['note']!r}, Cable disabled={s2['cable'][0]}; expected 'faces', no note, Cable in use")
    us = page.evaluate("() => ['front', 'rear'].map(f => document.querySelectorAll(`svg[data-pane=\"${f}\"] rect.rk-u`).length)")
    if us != [42, 42]:
        bad.append(f"after Front / Rear: U targets {us}, expected [42, 42]")
    return bad


# Each body a side pane draws, measured off the page: the box of its drawing
# on the pane (its backing rect, through its own transform), which of its
# drawings is shown, the posts, the U numbers, and the kit's solids.
SIDE_BODIES_JS = """async () => {
  const {RU} = await import('/vendor/rack/rails.js');
  const rack = window.__rack.doc().racks[0], H = rack.frame.heightRU * RU, out = {RU, H, frame: rack.frame, panes: {}, kit: {}};
  for (const s of window.__rack.solids()) {
    const b = out.kit[s.item] ??= {n: 0, z0: Infinity, z1: -Infinity, y0: Infinity, y1: -Infinity};
    b.n++; b.z0 = Math.min(b.z0, s.box.z0); b.z1 = Math.max(b.z1, s.box.z1); b.y0 = Math.min(b.y0, s.box.y0); b.y1 = Math.max(b.y1, s.box.y1);
  }
  for (const svg of document.querySelectorAll('#panes svg[data-side]')) {
    const inv = svg.getScreenCTM().inverse();
    const boxOf = el => { const b = el.getBBox(), m = inv.multiply(el.getScreenCTM());
      const c = [[b.x, b.y], [b.x + b.width, b.y + b.height], [b.x, b.y + b.height], [b.x + b.width, b.y]].map(([x, y]) => new DOMPoint(x, y).matrixTransform(m));
      return {x0: Math.min(...c.map(p => p.x)), x1: Math.max(...c.map(p => p.x)), y0: Math.min(...c.map(p => p.y)), y1: Math.max(...c.map(p => p.y))}; };
    const p = out.panes[svg.dataset.pane] = {bodies: {}, order: [], vb: svg.getAttribute('viewBox').split(' ').map(Number)};
    for (const g of svg.querySelectorAll('[data-item-id], [data-zerou-id]')) {
      const id = g.dataset.itemId ?? g.dataset.zerouId, hit = g.querySelector('[data-side-hit]');
      // where the drawing's own x = 0 edge lands: the front of a right drawing, the rear of a left one
      const m = inv.multiply(hit.getScreenCTM()), b0 = hit.getBBox(), o = new DOMPoint(b0.x, b0.y).matrixTransform(m);
      p.bodies[id] = {...boxOf(hit), view: g.dataset.sideView, turn: g.dataset.sideTurn === 'true', origin: o.x,
                      marks: g.querySelectorAll('rect, path, circle, line').length, near: !!g.closest('[data-side-near]')};
      p.order.push(id);
    }
    p.posts = [...svg.querySelectorAll('[data-side-post]')].map(r => [r.dataset.sidePost, +r.getAttribute('x'), +r.getAttribute('x') + +r.getAttribute('width')]);
    p.nums = [...svg.querySelectorAll('[data-side-num="front"]')].map(t => [t.textContent, Math.round((+t.dataset.mid + 4) * 1000) / 1000]);
    // how big the pane's own words are on screen, in CSS px, and whether a U number still sits in its unit
    const scale = svg.getBoundingClientRect().width / svg.viewBox.baseVal.width;
    p.scale = scale;
    p.px = Object.fromEntries(['num', 'word', 'part'].map(k => [k, [...svg.querySelectorAll(`[data-side-label="${k}"]`)].map(t => Math.round(+t.getAttribute('font-size') * scale * 10) / 10)]));
    p.numFits = [...svg.querySelectorAll('[data-side-label="num"]')].every(t => { const b = t.getBBox(), mid = +t.dataset.mid; return b.y >= mid - RU / 2 - 0.5 && b.y + b.height <= mid + RU / 2 + 0.5; });
    p.wordsIn = [...svg.querySelectorAll('[data-side-label="word"]')].every(t => { const b = t.getBBox(), v = svg.viewBox.baseVal; return b.x >= v.x - 0.5 && b.x + b.width <= v.x + v.width + 0.5 && b.y >= v.y - 0.5; });
    // the line round each body, as painted: its colour and its width on screen
    p.edges = Object.fromEntries([...svg.querySelectorAll('[data-item-id], [data-zerou-id]')].map(g => { const e = g.querySelector('[data-side-edge]'), cs = e && getComputedStyle(e);
      return [g.dataset.itemId ?? g.dataset.zerouId, e ? [cs.stroke, cs.vectorEffect, parseFloat(cs.strokeWidth)] : null]; }));
    p.stage = getComputedStyle(svg).getPropertyValue('--pt-ink-muted').trim();
    // a part beside the near side: its drawing's own opacity, and the marks that say it is a part in front
    p.near = [...svg.querySelectorAll('[data-side-near] > [data-zerou-id]')].map(g => { const m = svg.querySelector(`[data-side-near-mark="${g.dataset.zerouId}"]`);
      return {id: g.dataset.zerouId, opacity: +getComputedStyle(g).opacity, hatch: !!m?.querySelector('rect[fill^="url(#rk-side-hatch"]') && !!svg.querySelector('pattern[id^="rk-side-hatch"] line'),
              dashed: [...(m?.querySelectorAll('rect') ?? [])].some(r => r.getAttribute('stroke-dasharray')), label: m?.querySelector('text')?.textContent ?? null, events: m ? getComputedStyle(m).pointerEvents : null}; });
    p.plugs = Object.fromEntries([...svg.querySelectorAll('[data-cables] [data-cable][data-cable-id]')].map(g => [g.dataset.cableId,
      Object.fromEntries([...g.querySelectorAll('[data-side-plug]')].map(r => [r.dataset.sidePlug, r.dataset.span.split(' ').map(Number)]))]));
    // a plug is told from a strap: in its cable's own colour, with a nose line; where the part's name is, against the bodies and the cables
    p.plugPaint = [...svg.querySelectorAll('[data-cables] [data-cable][data-cable-id]')].map(g => [g.querySelector('path:last-of-type').getAttribute('stroke'),
      ...[...g.querySelectorAll('[data-side-plug]')].map(b => [b.querySelector('rect').getAttribute('fill'), b.querySelectorAll('line').length])]);
    const inPane = el => { const b = el.getBBox(), m = inv.multiply(el.getScreenCTM()), c = [[b.x, b.y], [b.x + b.width, b.y + b.height]].map(([x, y]) => new DOMPoint(x, y).matrixTransform(m));
      return {x0: Math.min(c[0].x, c[1].x), x1: Math.max(c[0].x, c[1].x), y0: Math.min(c[0].y, c[1].y), y1: Math.max(c[0].y, c[1].y)}; };
    const over = (a, b) => a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1;
    p.nameOver = [...svg.querySelectorAll('[data-side-label="part"]')].map(t => { const n = inPane(t), v = svg.viewBox.baseVal;
      return {inside: n.x0 >= v.x && n.x1 <= v.x + v.width && n.y1 <= v.y + v.height,
              bodies: [...svg.querySelectorAll('[data-item-id] [data-side-hit]')].filter(h => over(n, inPane(h))).length,
              cables: [...svg.querySelectorAll('[data-cables] [data-cable] path')].filter(c => over(n, inPane(c))).length}; });
    // a part beside the far side is fainter than a body; the U numbers are painted over every part, each with a rim
    p.far = [...svg.querySelectorAll(':scope > [data-zerou-id]')].map(g => [g.dataset.zerouId, +getComputedStyle(g).opacity]);
    p.bodyOpacity = [...svg.querySelectorAll(':scope > [data-item-id]')].map(g => +getComputedStyle(g).opacity);
    const kids = [...svg.children], numsAt = kids.findIndex(n => n.dataset.sideNums), last = sel => kids.reduce((m, n, i) => (n.matches(sel) ? i : m), -1);
    p.numsOver = numsAt > last('[data-side-near]') && numsAt > last('[data-zerou-id], [data-item-id]') && numsAt > last('[data-side-posts]');
    p.numRim = [...new Set([...svg.querySelectorAll('[data-side-num]')].map(t => `${t.getAttribute('stroke')} ${t.getAttribute('paint-order')}`))];
    p.hatch = (l => (l ? [+l.getAttribute('stroke-width'), +l.closest('pattern').getAttribute('width')] : null))(svg.querySelector('pattern[id^="rk-side-hatch"] line'));
    p.extent = (() => { const r = svg.querySelector('[data-side-extent]'); return r ? [+r.getAttribute('x'), +r.getAttribute('x') + +r.getAttribute('width')] : null; })();
    p.words = Object.fromEntries([...svg.querySelectorAll('[data-side-word]')].map(t => [t.dataset.sideWord, +t.getAttribute('x')]));
    p.layers = [...svg.children].map(n => n.dataset.sidePosts ? 'posts' : n.dataset.cables ? 'cables' : n.dataset.sideNear ? 'near' : n.dataset.itemId ? `item:${n.dataset.itemId}` : n.dataset.zerouId ? `part:${n.dataset.zerouId}` : null).filter(Boolean);
  }
  // the front pane's own U rows, for the one U scale: drawn while hidden is not possible, so from the rule itself
  return out;
}"""


@extra("rack.html: in Left / Right each body's own side drawing sits at the depth and height the kit's solidsOf gives - a device on the front rails, one on the rear rails, a turned one, a lacer and a vertical manager - the two panes are mirror placements, the posts stand at the rail planes with the U numbers on the front pane's scale, and nearer bodies are painted over farther ones (#187)")
def check_rack_side_placement(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_side_fixture(page, base)
    # the front pane's U rows, read before the switch: the side panes keep its scale and its top
    rows = page.evaluate("""() => { const svg = document.querySelector('#paneFront svg[data-pane="front"]');
      return {vb: svg.getAttribute('viewBox').split(' ').map(Number),
              nums: [...svg.querySelectorAll('[data-rail-num="left"]')].map(t => [t.textContent, Math.round(+t.getAttribute('y') * 1000) / 1000])}; }""")
    to_sides(page)
    d = page.evaluate(SIDE_BODIES_JS)
    H, RU, rd, deep = d["H"], d["RU"], d["frame"]["railDepth"], d["frame"]["usableDepth"]
    L, R = d["panes"].get("left"), d["panes"].get("right")
    if not L or not R:
        return bad + [f"the side panes are {list(d['panes'])}, expected left and right"]
    eps = 0.05
    # what each body is, and which of its own drawings each pane shows: its own side on that side when it looks out of the front
    want = {"i1": ("a device on the front rails", "left", "right"), "i3": ("a device on the front rails", "left", "right"),
            "i4": ("a device on the rear rails", "right", "left"), "i5": ("a turned device", "right", "left"),
            "i2": ("a lacer on the front rails", "left", "right"), "z1": ("a vertical manager at the left front upright", "left", "right")}
    exact = {"i1", "i3", "i4", "i5"}
    for bid, (what, lview, rview) in want.items():
        kit, l, r = d["kit"].get(bid), L["bodies"].get(bid), R["bodies"].get(bid)
        if not kit or not l or not r:
            bad.append(f"{bid} ({what}): kit box {bool(kit)}, drawn in the left pane {bool(l)}, in the right pane {bool(r)}")
            continue
        if (l["view"], r["view"]) != (lview, rview):
            bad.append(f"{bid} ({what}): the left pane shows its {l['view']} drawing and the right pane its {r['view']}; expected {lview} and {rview}")
        if l["marks"] < 2 or r["marks"] < 2:
            bad.append(f"{bid} ({what}): its drawing has {l['marks']} and {r['marks']} marks: it is a box, not its side drawing")
        # depth: the right pane's x is the depth back from the front rail plane (-z); the left pane's is z
        rz, lz = (-r["x1"], -r["x0"]), (l["x0"], l["x1"])
        if abs(rz[0] - lz[0]) > eps or abs(rz[1] - lz[1]) > eps:
            bad.append(f"{bid} ({what}): the two panes are not mirror placements: depth {lz} from the left, {rz} from the right")
        if abs(l["y0"] - r["y0"]) > eps or abs(l["y1"] - r["y1"]) > eps:
            bad.append(f"{bid} ({what}): at different heights in the two panes: {l['y0']}..{l['y1']} and {r['y0']}..{r['y1']}")
        # height: the pane's y runs down from the rack's top
        y = (H - l["y1"], H - l["y0"])
        if bid in exact:
            if abs(lz[0] - kit["z0"]) > eps or abs(lz[1] - kit["z1"]) > eps:
                bad.append(f"{bid} ({what}): drawn at depth {lz[0]:.2f}..{lz[1]:.2f}, the kit's solid is at {kit['z0']:.2f}..{kit['z1']:.2f}")
            # as tall as the kit's solid, centred in the units it takes (the front pane's rule): within the gap that leaves of the kit's bottom
            units = 2 if bid == "i5" else 1
            slack = (units * RU - (kit["y1"] - kit["y0"])) / 2 + eps
            if abs((y[1] - y[0]) - (kit["y1"] - kit["y0"])) > eps or abs(y[0] - kit["y0"]) > slack or y[0] < kit["y0"] - eps:
                bad.append(f"{bid} ({what}): drawn at height {y[0]:.2f}..{y[1]:.2f}, the kit's solid is at {kit['y0']:.2f}..{kit['y1']:.2f}")
        else:
            # a sheet part's solids are its plates: they lie inside its drawing (a plate's thickness aside), which shares their outer face and their height
            if kit["z0"] < lz[0] - 3 or kit["z1"] > lz[1] + 3 or kit["y0"] < y[0] - 3 or kit["y1"] > y[1] + 3:
                bad.append(f"{bid} ({what}): the kit's plates {kit['z0']:.2f}..{kit['z1']:.2f} deep, {kit['y0']:.2f}..{kit['y1']:.2f} high are outside its drawing {lz[0]:.2f}..{lz[1]:.2f}, {y[0]:.2f}..{y[1]:.2f}")
            face = (lz[1], kit["z1"]) if bid == "i2" else (lz[0], kit["z0"])
            if abs(face[0] - face[1]) > eps or abs(y[0] - kit["y0"]) > 0.5 or abs(y[1] - kit["y1"]) > 0.5:
                bad.append(f"{bid} ({what}): its drawing ends at depth {face[0]:.2f} and spans {y[0]:.2f}..{y[1]:.2f}; the kit's plates end at {face[1]:.2f} and span {kit['y0']:.2f}..{kit['y1']:.2f}")
        # its own front is where its front is: a right drawing starts at its front, a left drawing ends there
        for pane, b in (("left", l), ("right", r)):
            if abs(b["origin"] - b["x0"]) > eps:
                bad.append(f"{bid} ({what}): in the {pane} pane its drawing is turned or mirrored (its own x = 0 is at {b['origin']:.2f}, its box starts at {b['x0']:.2f})")
    # the rack's rules in numbers: front on the rail plane, the rear device against the rear rails, the turned one's body behind the front rails
    k = d["kit"]
    if k.get("i1") and (abs(k["i1"]["z1"]) > eps or abs(k["i4"]["z0"] + rd) > eps or abs(k["i5"]["z1"]) > eps):
        bad.append(f"the kit's solids are not where the fixture expects: i1 {k['i1']}, i4 {k['i4']}, i5 {k['i5']}")
    # the posts: 34 mm behind each rail plane, the same in both panes mirrored; the rack's depth from the front rail back
    if sorted(R["posts"]) != [["front", 0, 34], ["rear", rd - 34, rd]] or sorted(L["posts"]) != [["front", -34, 0], ["rear", -rd, -rd + 34]]:
        bad.append(f"the posts are at {R['posts']} (right) and {L['posts']} (left); expected the front pair behind the front rail plane and the rear pair {rd} mm back")
    if R["extent"] != [0, deep] or L["extent"] != [-deep, 0]:
        bad.append(f"the rack's depth is drawn {R['extent']} and {L['extent']}, expected {deep} mm back from the front rail plane")
    if not (R["words"].get("front") == 0 and R["words"].get("rear") == rd and L["words"].get("front") == 0 and L["words"].get("rear") == -rd):
        bad.append(f"FRONT and REAR are at {R['words']} and {L['words']}")
    # the front of the rack is at the right pane's left and the left pane's right
    if not (R["vb"][0] < 0 < rd < R["vb"][0] + R["vb"][2] and L["vb"][0] < -rd < 0 < L["vb"][0] + L["vb"][2]) or abs(L["vb"][2] - R["vb"][2]) > eps or abs(L["vb"][0] + R["vb"][0] + R["vb"][2]) > eps:
        bad.append(f"the panes' boxes are {L['vb']} and {R['vb']}; expected mirrored boxes of one width holding the rack from its rear posts to in front of its front rails")
    # FITTED TO THE RACK AS IT STANDS, not to its usable depth: what the pane shows is the posts, the bodies and the cables, and a margin
    held = [b for b in R["bodies"].values()]
    lo, hi = min([b["x0"] for b in held] + [0]), max([b["x1"] for b in held] + [rd])
    if R["vb"][2] >= deep or R["vb"][0] < lo - 130 or R["vb"][0] + R["vb"][2] > hi + 130:
        bad.append(f"the right pane's box runs {R['vb'][0]:.0f}..{R['vb'][0] + R['vb'][2]:.0f} mm; what stands in it runs {lo:.0f}..{hi:.0f}, and the usable depth is {deep}: expected the rack as it stands and a margin")
    for name, p in (("left", L), ("right", R)):
        # THE PANE'S OWN WORDS ARE READABLE AT FIT: never under their least size on screen, the U numbers still inside their units, the words inside the pane
        if p["scale"] >= 1:
            bad.append(f"{name} pane: drawn at {p['scale']:.2f} px a mm at Fit, so the least sizes were not tried")
        if not p["px"]["num"] or min(p["px"]["num"]) < 8.9 or len(p["px"]["word"]) != 2 or min(p["px"]["word"]) < 10.9 or not p["numFits"] or not p["wordsIn"]:
            bad.append(f"{name} pane: on screen the U numbers are {min(p['px']['num'] or [0])} px and FRONT / REAR {p['px']['word']} px (least 9 and 11); numbers inside their units {p['numFits']}, words inside the pane {p['wordsIn']}")
        # A LINE ROUND EVERY BODY in the stage's ink, a pixel wide whatever the zoom
        for bid, e in p["edges"].items():
            if not e or e[0] in ("none", "") or e[1] != "non-scaling-stroke" or e[2] != 1:
                bad.append(f"{name} pane: {bid} has no outline in the stage's ink ({e})")
        # A PLUG AT EACH CABLED PORT, from the port's face out by the kit's reach
        for c, ends in p["plugs"].items():
            if set(ends) != {"a", "b"} or any(not (4 < abs(v[1] - v[0]) < 90) for v in ends.values()):
                bad.append(f"{name} pane: {c}'s plugs are {ends}; expected a block at each end, as long as its plug reaches")
    # the front device's plugs start on the front rail plane and stand out in front; the rear device's start on the rear rail plane and stand out behind
    pa, pb = R["plugs"].get("c2", {}).get("a"), R["plugs"].get("c2", {}).get("b")
    if not pa or not pb or abs(pa[1]) > eps or pa[0] > -4 or abs(pb[0] - rd) > eps or pb[1] < rd + 4:
        bad.append(f"c2's plugs in the right pane are {pa} and {pb}; expected one out of the front rail plane at 0 and one out of the rear rail plane at {rd}")
    # THE PART BESIDE THE NEAR SIDE reads as a part in front: see-through, with a dashed outline, a hatch and its name, none of which takes the pointer
    nl = L["near"]
    if len(nl) != 1 or nl[0]["id"] != "z1" or not (0.1 <= nl[0]["opacity"] <= 0.4) or not nl[0]["hatch"] or not nl[0]["dashed"] or "duct-1" not in (nl[0]["label"] or "") or nl[0]["events"] != "none":
        bad.append(f"left pane: the manager beside the near side is {nl}; expected z1 see-through, hatched, outlined, named, its marks taking no pointer")
    # THE PART BESIDE THE FAR SIDE is behind everything and fainter than a body, so the two managers of a rack do not read as one solid column
    if R["far"] != [["z1", 0.3]] or L["far"] or any(o != 1 for o in R["bodyOpacity"] + L["bodyOpacity"]):
        bad.append(f"the right pane's far part is {R['far']} (the left pane's {L['far']}) and the bodies are at {sorted(set(R['bodyOpacity'] + L['bodyOpacity']))}; expected z1 at 0.3 from the right, none from the left, every body at 1")
    # THE U NUMBERS are over every part, with a rim of the post's metal: a near part's fingers do not run through them
    for name, p in (("left", L), ("right", R)):
        if not p["numsOver"] or p["numRim"] != ["#B9BFC6 stroke"]:
            bad.append(f"{name} pane: the U numbers are {'over' if p['numsOver'] else 'under'} the parts and posts, with rim {p['numRim']}; expected over them, rimmed in the post's metal")
    # its name is under the rack, inside the pane, over no body and no cable at Fit; the hatch is thin and wide apart
    if L["nameOver"] != [{"inside": True, "bodies": 0, "cables": 0}]:
        bad.append(f"left pane: the near part's name is {L['nameOver']}; expected inside the pane and over no body or cable")
    if not L["hatch"] or L["hatch"][0] > 1 or L["hatch"][1] < 24:
        bad.append(f"left pane: the near part's hatch is {L['hatch']} (line width, pitch); expected a thin line at a wide pitch")
    # a plug is its cable's colour with a nose line, never a strap's neutral
    for name, p in (("left", L), ("right", R)):
        for row in p["plugPaint"]:
            if len(row) != 3 or any(b != [row[0], 1] for b in row[1:]) or row[0].lower() in ("#1b1d20", "#ffffff", "#d5d9de", "#0b0c0d"):
                bad.append(f"{name} pane: a cable drawn {row[0]} has plugs {row[1:]}; expected two, each in the cable's colour with one nose line")
    if R["near"] or not L["px"]["part"] or min(L["px"]["part"]) < 10.9:
        bad.append(f"the right pane marks {R['near']} as beside its near side (expected none), and the left pane's part name is {L['px']['part']} px")
    # one U scale and one top for all four panes: the numbers on the front post at the front pane's own heights
    for name, p in (("left", L), ("right", R)):
        if p["nums"] != rows["nums"] or len(p["nums"]) != 42:
            bad.append(f"{name} pane: the U numbers on its front post are not at the front pane's heights ({p['nums'][:2]} against {rows['nums'][:2]}, {len(p['nums'])} of them)")
    # nearer over farther: from the left the manager beside the left upright is in front of everything, from the right behind it
    lo, ro = L["layers"], R["layers"]
    if not (lo.index("near") > lo.index("cables") > lo.index("posts") > max(i for i, n in enumerate(lo) if n.startswith("item:")) and L["bodies"]["z1"]["near"]):
        bad.append(f"left pane: painted in the order {lo}; expected the devices, the posts, the cables, then the manager beside the near side")
    if not (ro[0] == "part:z1" and not R["bodies"]["z1"]["near"]):
        bad.append(f"right pane: painted in the order {ro}; expected the manager beside the far side first")
    # the lacer is wider than a device, so nearer from either side: after the device it is bolted over
    for name, p in (("left", L), ("right", R)):
        if p["order"].index("i2") < p["order"].index("i1"):
            bad.append(f"{name} pane: the lacer is painted before the device it is bolted over")
    return bad


# A side pane's cables, off the page: each one's drawn points (in pane mm),
# whether it is lit, the envelope, and the label beside the pointer.
SIDE_CABLES_JS = """() => {
  const out = {panes: {}, pressed: [...document.querySelectorAll('#cableList [aria-pressed="true"]')].map(b => b.dataset.cableRow ?? b.dataset.bundleRow),
               tip: (t => (t && !t.hidden ? t.textContent : null))(document.getElementById('cableTip')), tips: document.querySelectorAll('#sideTip, .rk-side-tip').length, paths: {}};
  const P = window.__rack.paths() || {};
  for (const [id, p] of Object.entries(P)) out.paths[id] = p ? p.points.map(q => [q.x, q.y, q.z]) : null;
  for (const svg of document.querySelectorAll('#panes > section > div > svg')) {
    const p = out.panes[svg.dataset.pane] = {cables: {}, hover: svg.classList.contains('cable-hover'), focus: svg.classList.contains('cable-focus')};
    for (const g of svg.querySelectorAll(':scope > [data-cables] [data-cable][data-cable-id]')) {
      const path = g.querySelector('path:last-of-type');
      const pts = (path.getAttribute('d').match(/-?[\\d.]+ -?[\\d.]+/g) || []).map(s => s.split(' ').map(Number));
      p.cables[g.dataset.cableId] = {pts, on: g.classList.contains('on'), hot: g.classList.contains('hot'), opacity: Math.round(+getComputedStyle(g).opacity * 100) / 100,
                                     stroke: path.getAttribute('stroke'), events: getComputedStyle(g).pointerEvents};
    }
  }
  return out;
}"""
# A point of a cable's stroke on a pane, in page pixels, that no other cable's stroke is under.
SIDE_POINT_JS = """([pane, id]) => {
  const svg = document.querySelector(`#panes svg[data-pane="${pane}"]`), mine = svg.querySelector(`[data-cable-id="${id}"] path:last-of-type`);
  const others = [...svg.querySelectorAll('[data-cables] [data-cable][data-cable-id] path')].filter(p => p.closest('[data-cable-id]').dataset.cableId !== id);
  const L = mine.getTotalLength(), m = mine.getScreenCTM();
  for (let k = 1; k < 200; k++) {
    const q = mine.getPointAtLength(L * k / 200), s = new DOMPoint(q.x, q.y).matrixTransform(m);
    if (others.some(o => o.isPointInStroke(new DOMPoint(s.x, s.y).matrixTransform(o.getScreenCTM().inverse())))) continue;
    const r = svg.getBoundingClientRect();
    if (s.x > r.left + 2 && s.x < r.right - 2 && s.y > r.top + 2 && s.y < r.bottom - 2) return [s.x, s.y];
  }
  return null;
}"""


def side_lit_wrong(st, lit, where):
    bad = []
    for pane, p in st["panes"].items():
        for c, v in p["cables"].items():
            if lit and c in lit and v["opacity"] != 1:
                bad.append(f"{where}: {pane} pane, {c} should be lit, is at opacity {v['opacity']}")
            if lit and c not in lit and v["opacity"] > 0.25:
                bad.append(f"{where}: {pane} pane, {c} should be dimmed, is at opacity {v['opacity']}")
            if not lit and v["opacity"] != 1:
                bad.append(f"{where}: {pane} pane, {c} should be as drawn, is at opacity {v['opacity']}")
    return bad


@extra("rack.html: in Left / Right a cable is the kit's own points dropped onto depth and height - a patch between two front ports stays in front of the front rail plane, a run up a lane is a vertical on it, a front-to-rear cable is drawn through the rack - in its own colour, mirrored in the two panes; hovering one dims the rest and names it, and a pinned cable stays pinned through Front / Rear, Left / Right and 3D (#187)")
def check_rack_side_cables(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_side_fixture(page, base)
    colours = page.evaluate("""() => Object.fromEntries([...document.querySelectorAll('#paneFront svg [data-cables] [data-cable][data-cable-id]')].map(g =>
      [g.dataset.cableId, g.querySelector('path:last-of-type').getAttribute('stroke')]))""")
    to_sides(page)
    park_mouse(page)
    st = page.evaluate(SIDE_CABLES_JS)
    L, R = st["panes"].get("left"), st["panes"].get("right")
    if not L or not R or set(L["cables"]) != {"c1", "c2", "c3"} or set(R["cables"]) != {"c1", "c2", "c3"}:
        return bad + [f"the side panes draw {({k: sorted(v['cables']) for k, v in st['panes'].items()})}, expected c1, c2 and c3 on each"]
    H, rd = 42 * 44.45, 740
    for c in ("c1", "c2", "c3"):
        kit = st["paths"][c]
        l, r = L["cables"][c]["pts"], R["cables"][c]["pts"]
        # mirror images: the left pane's x is the right pane's, negated
        if len(l) != len(r) or any(abs(a[0] + b[0]) > 0.01 or abs(a[1] - b[1]) > 0.01 for a, b in zip(l, r)):
            bad.append(f"{c}: its strokes in the two panes are not mirror images ({l[:3]} against {r[:3]})")
        # the kit's points, every one, in order: (depth back from the front rail, height down from the top), runs across the rack seen end on
        want = []
        for x, y, z in kit:
            q = [round(-z, 3), round(H - y, 3)]
            if not want or abs(want[-1][0] - q[0]) > 1e-6 or abs(want[-1][1] - q[1]) > 1e-6:
                want.append(q)
        if len(want) != len(r) or any(abs(a[0] - b[0]) > 0.01 or abs(a[1] - b[1]) > 0.01 for a, b in zip(want, r)):
            bad.append(f"{c}: the right pane draws {len(r)} points {r[:4]}...; the kit's path gives {len(want)}, {want[:4]}...")
        if R["cables"][c]["stroke"] != colours.get(c) or L["cables"][c]["stroke"] != colours.get(c):
            bad.append(f"{c}: drawn {R['cables'][c]['stroke']} from the side, {colours.get(c)} on the front pane")
        if R["cables"][c]["events"] != "none":
            bad.append(f"{c}: its stroke takes the pointer ({R['cables'][c]['events']}); a click under it is the device's")
    # c1 and c3: two ports of the front face. Never behind the front rail plane, and its run up the lane is a vertical on that plane
    for c in ("c1", "c3"):
        xs = [p[0] for p in R["cables"][c]["pts"]]
        if max(xs) > 0.01 or min(xs) > -10:
            bad.append(f"{c} (front port to front port): its depth runs {min(xs):.1f}..{max(xs):.1f} mm back from the front rail plane; expected in front of it and out to its plug")
        pts = R["cables"][c]["pts"]
        vert = [abs(b[1] - a[1]) for a, b in zip(pts, pts[1:]) if abs(a[0]) < 0.01 and abs(b[0]) < 0.01]
        if not vert or max(vert) < 300:
            bad.append(f"{c}: no vertical run on the front rail plane (its lane) is drawn; the longest is {max(vert) if vert else 0:.0f} mm")
    # c2: from a front port to the device on the rear rails. Drawn through the rack, from in front of the front plane to behind the rear one
    xs = [p[0] for p in R["cables"]["c2"]["pts"]]
    if min(xs) > -10 or max(xs) < rd:
        bad.append(f"c2 (front to rear): its depth runs {min(xs):.1f}..{max(xs):.1f}; expected from in front of the front rail plane to the rear rail plane at {rd} and its plug beyond")
    through = [(a, b) for a, b in zip(R["cables"]["c2"]["pts"], R["cables"]["c2"]["pts"][1:]) if a[0] <= 0.01 and b[0] >= rd - 0.01]
    if len(through) != 1 or abs(through[0][0][1] - through[0][1][1]) > 0.01:
        bad.append(f"c2 (front to rear): {len(through)} of its legs run from the front rail plane to the rear one; expected one, level")
    # ── a bundle from the side: its straps and envelope with its members, and none where no member is drawn ──
    res = page.evaluate("() => window.__rack.bundleCommand({op: 'bundle.create', cables: ['c1', 'c3'], label: 'pair'})")
    if res and res.get("error"):
        bad.append(f"the bundle was not made: {res['error']}")
    else:
        # (the bundle's own straps; `ties` are the tie straps of single cables, kit 0.22.0, which go with the cables they tie)
        BUN = """() => [...document.querySelectorAll('#panes svg[data-side]')].map(s => ({straps: [...s.querySelectorAll('[data-strap]:not([data-tie])')].map(g => [g.dataset.strap, g.dataset.members,
          Math.round(+getComputedStyle(g).opacity * 100) / 100]),
          ties: [...s.querySelectorAll('[data-strap][data-tie]')].map(g => [g.dataset.strap, g.dataset.members, Math.round(+getComputedStyle(g).opacity * 100) / 100]), stretches: s.querySelectorAll('[data-bundle-trunk]').length,
          env: [...s.querySelectorAll('[data-envelope]')].map(e => getComputedStyle(e).visibility), drawn: s.querySelectorAll('[data-cables] [data-cable][data-cable-id]').length}))"""
        page.wait_for_function("() => document.querySelectorAll('#panes svg[data-side] [data-strap]').length >= 2 && window.__rack.routesCurrent().current", timeout=READY_MS)
        park_mouse(page)
        b0 = page.evaluate(BUN)
        for pane, v in zip(("left", "right"), b0):
            if not v["straps"] or not v["stretches"] or any(m[1] != "c1 c3" for m in v["straps"]) or any(e != "hidden" for e in v["env"]):
                bad.append(f"the bundle, {pane} pane: straps {v['straps']}, {v['stretches']} stretches, envelope {v['env']}; expected straps naming c1 and c3, stretches, and the envelope hidden until hovered or selected")
        # c2 pinned: the straps of a bundle it does not ride dim with the rest; a member pinned keeps them lit and shows the envelope
        page.click('#cableList [data-cable-row="c2"]')
        page.wait_for_function("() => document.querySelector('#paneRear [data-cable-id=\"c2\"].on')", timeout=READY_MS)
        park_mouse(page)
        b1 = page.evaluate(BUN)
        if any(m[2] > 0.25 for v in b1 for m in v["straps"]):
            bad.append(f"c2 pinned: the other bundle's straps are at {[m[2] for v in b1 for m in v['straps']]}; expected dimmed with the rest")
        # ...and a tie strap is lit exactly while a cable it ties is: c2's own stays lit with it
        if any((m[2] == 1) != ("c2" in m[1].split()) or (m[2] != 1 and m[2] > 0.25) for v in b1 for m in v["ties"]):
            bad.append(f"c2 pinned: the tie straps are at {[m for v in b1 for m in v['ties']]}; expected lit where they tie c2 and dimmed elsewhere")
        page.click('#cableList [data-cable-row="c1"]')
        page.wait_for_function("() => document.querySelector('#paneRear [data-cable-id=\"c1\"].on')", timeout=READY_MS)
        park_mouse(page)
        b2 = page.evaluate(BUN)
        if any(m[2] != 1 for v in b2 for m in v["straps"]) or any(e != "visible" for v in b2 for e in v["env"]):
            bad.append(f"c1 pinned: its bundle's straps are at {[m[2] for v in b2 for m in v['straps']]} and its envelope {[v['env'] for v in b2]}; expected lit and shown")
        if any((m[2] == 1) != ("c1" in m[1].split()) or (m[2] != 1 and m[2] > 0.25) for v in b2 for m in v["ties"]):
            bad.append(f"c1 pinned: the tie straps are at {[m for v in b2 for m in v['ties']]}; expected lit where they tie c1 and dimmed elsewhere")
        page.keyboard.press("Escape")
        page.wait_for_function("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')", timeout=READY_MS)
        # a member's end made loose (its port's device gone from under it): the cables not drawn take the bundle's drawing with them
        page.evaluate("() => window.__rack.failCableFacts(false)")
        page.evaluate("""() => { const r = structuredClone(window.__rack.doc().racks[0]);
          for (const c of r.cables) if (c.id !== 'c2') c.b = {...c.b, path: c.b.path + '-none'};
          window.__rack.replaceRack(r); }""")
        page.wait_for_function("() => window.__rack.routesCurrent().current && [...document.querySelectorAll('#panes svg[data-side]')].every(s => s.querySelectorAll('[data-cables] [data-cable][data-cable-id]').length === 1)", timeout=READY_MS)
        b3 = page.evaluate(BUN)
        # A CABLE WITH A LOOSE END IS NOT DRAWN FROM THE SIDE AT ALL: no stroke, no plug, no lead, no tag (the cable list says why it is not connected)
        loose = page.evaluate("""() => [...document.querySelectorAll('#panes svg[data-side]')].map(s => [s.querySelectorAll('[data-cable-id="c1"], [data-cable-id="c3"]').length,
          s.querySelectorAll('[data-loose-lead], [data-open-plug], [data-cable-tag]').length, s.querySelectorAll('[data-side-plug]').length])""")
        if loose != [[0, 0, 2], [0, 0, 2]]:
            bad.append(f"c1 and c3 with a loose end: the side panes hold {loose} (their drawings; leads, open plugs and tags; plugs in all); expected nothing of them, and c2's two plugs")
        why = page.evaluate("() => { const side = document.getElementById('side').innerText; return Object.values(window.__rack.cableFacts().reasons).filter(Boolean).map(r => [r, side.includes(r)]); }")
        if len(why) != 2 or not all(shown for _, shown in why):
            bad.append(f"c1 and c3 with a loose end: the page's reasons, and whether the side panel says each, are {why}; expected two, both said")
        if any(v["straps"] or v["stretches"] for v in b3):
            bad.append(f"c1 and c3 not drawn (a loose end each): their bundle still has {[(len(v['straps']), v['stretches']) for v in b3]} straps and stretches on the side panes")
        page.evaluate("() => window.__rack.undo()")
        page.wait_for_function("() => window.__rack.routesCurrent().current && [...document.querySelectorAll('#panes svg[data-side]')].every(s => s.querySelectorAll('[data-cables] [data-cable][data-cable-id]').length === 3)", timeout=READY_MS)
        page.wait_for_timeout(400)
    # ── hover: a point of c2's own stroke, in the right pane ──
    spot = page.evaluate(SIDE_POINT_JS, ["right", "c2"])
    if not spot:
        return bad + ["found no point of c2's stroke in the right pane that is clear of the other cables"]
    page.mouse.move(spot[0] - 30, spot[1] - 30)
    page.mouse.move(spot[0], spot[1], steps=3)
    page.wait_for_timeout(450)
    h = page.evaluate(SIDE_CABLES_JS)
    bad += side_lit_wrong(h, {"c2"}, "hovering c2 in the right pane")
    if not h["panes"]["left"]["hover"]:
        bad.append("hovering c2 in the right pane: the left pane is not dimmed with it")
    if not h["tip"] or "sw-front" not in h["tip"] or "sw-rear" not in h["tip"]:
        bad.append(f"hovering c2: the label beside the pointer reads {h['tip']!r}; expected it to name c2's two ends")
    if h["tips"]:
        bad.append("the side pair has a hover label of its own again; the page has one (#cableTip)")
    # a switch of pair by keyboard leaves the pointer where it is: the label goes with the pane it was over
    page.focus('#view2d [data-view="faces"]')
    page.keyboard.press("Enter")
    page.wait_for_function(FACES_DRAWN, timeout=READY_MS)
    if page.evaluate(SIDE_CABLES_JS)["tip"]:
        bad.append("a switch of pair by keyboard left the hover label up over the new panes")
    page.focus('#view2d [data-view="sides"]')
    page.keyboard.press("Enter")
    page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
    page.wait_for_function("() => [...document.querySelectorAll('#panes svg[data-side]')].every(s => s.querySelectorAll('[data-cables] [data-cable][data-cable-id]').length === 3)", timeout=READY_MS)
    page.wait_for_timeout(300)
    # a button going down on the stroke hides it at once (the click that pins does not carry it along)
    spot = page.evaluate(SIDE_POINT_JS, ["right", "c2"])
    page.mouse.move(spot[0] - 30, spot[1] - 30)
    page.mouse.move(spot[0], spot[1], steps=3)
    page.wait_for_timeout(450)
    if not page.evaluate(SIDE_CABLES_JS)["tip"]:
        bad.append("hovering c2 again after the switch back: no label")
    page.mouse.down()
    held = page.evaluate(SIDE_CABLES_JS)["tip"]
    page.mouse.move(spot[0] + 60, spot[1] + 60, steps=3)   # a press that moves away is no click: nothing is pinned by it
    page.mouse.up()
    if held:
        bad.append(f"a button down on c2's stroke left the hover label up ({held!r})")
    park_mouse(page)
    h = page.evaluate(SIDE_CABLES_JS)
    bad += side_lit_wrong(h, None, "the pointer gone")
    if h["tip"]:
        bad.append(f"the pointer gone: the label still reads {h['tip']!r}")
    # ── a click on the stroke pins it; it survives every switch of view ──
    page.mouse.click(spot[0], spot[1])
    page.wait_for_function("() => document.querySelector('#paneRear [data-cable-id=\"c2\"].on')", timeout=READY_MS)
    park_mouse(page)
    p = page.evaluate(SIDE_CABLES_JS)
    bad += side_lit_wrong(p, {"c2"}, "c2 clicked in the right pane")
    if p["pressed"] != ["c2"]:
        bad.append(f"c2 clicked in the right pane: the pressed rows are {p['pressed']}")
    # the same click again leaves it pinned
    spot = page.evaluate(SIDE_POINT_JS, ["right", "c2"])
    page.mouse.click(spot[0], spot[1])
    page.wait_for_timeout(400)
    park_mouse(page)
    if page.evaluate(SIDE_CABLES_JS)["pressed"] != ["c2"]:
        bad.append("c2 clicked again: it was put down; a click on the pinned cable keeps it")
    to_faces(page)
    park_mouse(page)
    f = page.evaluate(SIDE_CABLES_JS)
    bad += side_lit_wrong(f, {"c2"}, "c2 pinned, in Front / Rear")
    if f["pressed"] != ["c2"]:
        bad.append(f"c2 pinned, in Front / Rear: the pressed rows are {f['pressed']}")
    to_sides(page)
    park_mouse(page)
    bad += side_lit_wrong(page.evaluate(SIDE_CABLES_JS), {"c2"}, "c2 pinned, back in Left / Right")
    if webgl_trouble(page):
        print("[check_rack_side_cables] no WebGL here - the 3D half was not checked")
    else:
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, "3D: the side fixture's scene", tubes=True)
        park_mouse(page)
        three = page.evaluate("""() => { const g = window.__rack.scene()?.three?.scene?.getObjectByName('patch-cables'), out = {};
          for (const c of g?.children ?? []) { const m = c.children.find(o => o.isMesh).material; out[c.name.slice(6)] = [m.transparent, Math.round(m.opacity * 1000) / 1000]; }
          return out; }""")
        if three.get("c2") != [False, 1] or not all(v[0] and v[1] < 0.2 for k, v in three.items() if k != "c2") or len(three) != 3:
            bad.append(f"c2 pinned, in 3D: the tubes' materials are {three}; expected c2 at full strength and the others dimmed")
        page.click('#mode [data-mode="2d"]')
        page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
        page.wait_for_function("() => document.querySelector('#paneRear [data-cable-id=\"c2\"].on')", timeout=READY_MS)
        park_mouse(page)
        b = page.evaluate(SIDE_CABLES_JS)
        bad += side_lit_wrong(b, {"c2"}, "c2 pinned, back from 3D in Left / Right")
        if b["pressed"] != ["c2"]:
            bad.append(f"c2 pinned, back from 3D: the pressed rows are {b['pressed']}")
    # a click on empty pane puts it down, as everywhere
    empty = page.evaluate("""() => { const svg = document.querySelector('#paneRear > svg'), r = svg.getBoundingClientRect();
      for (const [fx, fy] of [[0.5, 0.004], [0.3, 0.004], [0.7, 0.004]]) { const x = r.left + r.width * fx, y = r.top + r.height * fy;
        if (document.elementFromPoint(x, y) === svg) return [x, y]; } return null; }""")
    if not empty:
        bad.append("found no empty point of the right pane to click")
    else:
        page.mouse.click(empty[0], empty[1])
        try:
            page.wait_for_function("() => !document.querySelector('#cableList [aria-pressed=\"true\"]')", timeout=5000)
        except Exception:
            bad.append("a click on empty pane did not put the pinned cable down")
        park_mouse(page)
        bad += side_lit_wrong(page.evaluate(SIDE_CABLES_JS), None, "after a click on empty pane")
    return bad


@extra("rack.html: Left / Right is for looking - a click selects a device, a part or a cable and rings it; nothing can be dragged, moved with the arrow keys, placed or cabled there; Cable is off and says why, a new cable in hand is dropped on the way in, and the panel says what the pair is for (#187)")
def check_rack_side_view_only(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_side_fixture(page, base)
    # Cable mode on, with an end picked, in Front / Rear
    page.click("#cableBtn")
    page.wait_for_selector("#cableHelp", timeout=READY_MS)
    if page.get_attribute("#cableBtn", "aria-pressed") != "true":
        bad.append("Front / Rear: the Cable button did not turn on")
    to_sides(page)
    s = page.evaluate(SIDE_SWITCH_JS)
    if s["cable"][0] is not True or s["cable"][2] != "false" or "Front / Rear" not in s["cable"][1]:
        bad.append(f"Left / Right: the Cable button is disabled={s['cable'][0]}, pressed={s['cable'][2]}, title {s['cable'][1]!r}; expected off, not pressed, saying cables are added in Front / Rear")
    if page.query_selector("#cableHelp") or page.evaluate("() => document.getElementById('panes').classList.contains('rk-cabling')"):
        bad.append("Left / Right: Cable mode is still on")
    if not s["note"] or "Front / Rear" not in s["note"]:
        bad.append(f"Left / Right: the panel's note reads {s['note']!r}; expected it to say the pair is for looking and where to edit")
    targets = page.evaluate("() => [document.querySelectorAll('#panes rect.rk-u').length, document.querySelectorAll('#panes [data-u]').length, document.querySelectorAll('#panes [data-pick]').length]")
    if targets != [0, 0, 0]:
        bad.append(f"Left / Right: the panes hold {targets} U targets, U rows and pick targets; expected none")
    before = page.evaluate("() => JSON.stringify(window.__rack.doc().racks[0])")
    hist = page.evaluate("() => window.__rack.history().undoSummary")
    # a click on a device selects it, and rings it
    box = page.evaluate("""() => { const r = document.querySelector('#paneRear svg [data-item-id="i5"] [data-side-hit]').getBoundingClientRect();
      return [r.left + r.width * 0.7, r.top + r.height / 2, r.height]; }""")
    page.mouse.click(box[0], box[1])
    try:
        page.wait_for_function("() => document.querySelectorAll('#panes .rk-sel-ring').length === 2 && document.querySelector('#paneRear [data-item-id=\"i5\"].rk-selected')", timeout=8000)
    except Exception:
        bad.append("a click on the turned device did not select and ring it in both panes")
    if not page.query_selector("#side #iRemove"):
        bad.append("a click on the turned device did not open its panel")
    # the arrow keys do not move it (in Front / Rear they move a selected device a unit at a time)
    page.keyboard.press("ArrowUp")
    page.keyboard.press("ArrowDown")
    page.keyboard.press("ArrowDown")
    page.wait_for_timeout(400)
    if page.evaluate("() => JSON.stringify(window.__rack.doc().racks[0])") != before:
        bad.append("the arrow keys moved a device selected in Left / Right")
    if not page.query_selector('#paneRear [data-item-id="i5"].rk-selected'):
        bad.append("after the arrow keys the device is no longer the selection, so they were not tried on it")
    # a press and a move on it does not start a drag, and does not move it
    page.mouse.move(box[0], box[1])
    page.mouse.down()
    page.mouse.move(box[0], box[1] - box[2] * 3, steps=8)
    drag_ui = page.evaluate("() => !!document.getElementById('dragStatus') || !!document.querySelector('.rk-dragging, .rk-drag-ghost, [data-drag-ghost]')")
    page.mouse.up()
    page.wait_for_timeout(400)
    if drag_ui:
        bad.append("a press and a move on a device started a drag")
    after = page.evaluate("() => JSON.stringify(window.__rack.doc().racks[0])")
    if after != before or page.evaluate("() => window.__rack.history().undoSummary") != hist:
        bad.append("after a click, the arrow keys and a drag on a device in Left / Right the rack changed")
    # (the press and release above ended on empty pane: the device is selected again for its panel)
    page.mouse.click(box[0], box[1])
    page.wait_for_selector("#side #iMove", timeout=READY_MS)
    # Move, from its panel, says where moving is done
    if page.query_selector("#iMove"):
        page.click("#iMove")
        page.wait_for_selector("#moveHelp", timeout=READY_MS)
        if "Front / Rear" not in page.inner_text("#moveHelp"):
            bad.append(f"Move, in Left / Right, reads {page.inner_text('#moveHelp')!r}")
        page.keyboard.press("Escape")
        page.wait_for_timeout(300)
    # the part beside the rack, in the pane it is nearest in
    zb = page.evaluate("""() => { const r = document.querySelector('#paneFront svg [data-zerou-id="z1"] [data-side-hit]').getBoundingClientRect();
      return [r.left + r.width * 0.8, r.top + r.height * 0.9]; }""")
    page.mouse.click(zb[0], zb[1])
    try:
        page.wait_for_function("() => document.querySelector('#paneFront [data-zerou-id=\"z1\"].rk-selected')", timeout=8000)
    except Exception:
        bad.append("a click on the vertical manager did not select it")
    # a click on empty pane puts a selected part down, and places nothing
    empty = page.evaluate("""() => { const svg = document.querySelector('#paneRear > svg'), r = svg.getBoundingClientRect();
      for (const [fx, fy] of [[0.5, 0.004], [0.3, 0.004]]) { const x = r.left + r.width * fx, y = r.top + r.height * fy;
        if (document.elementFromPoint(x, y) === svg) return [x, y]; } return null; }""")
    if empty:
        page.mouse.click(empty[0], empty[1])
        try:
            page.wait_for_function("() => !document.querySelector('#panes .rk-selected') && !document.querySelector('#panes .rk-sel-ring')", timeout=8000)
        except Exception:
            bad.append("a click on empty pane did not put the selected part down")
    # a click inside the rack's depth where nothing stands opens no picker
    hole = page.evaluate("""() => { const svg = document.querySelector('#paneRear > svg'), m = svg.getScreenCTM(), p = new DOMPoint(400, 42 * 44.45 - 2.5 * 44.45).matrixTransform(m);
      return document.elementFromPoint(p.x, p.y) === svg ? [p.x, p.y] : null; }""")
    if not hole:
        bad.append("found no empty unit inside the rack's depth to click")
    else:
        page.mouse.click(hole[0], hole[1])
        page.wait_for_timeout(400)
        if page.query_selector("#catQuery") or page.query_selector("#catPlace"):
            bad.append("a click on an empty unit in Left / Right opened the picker")
    if page.evaluate("() => JSON.stringify(window.__rack.doc().racks[0])") != before:
        bad.append("the rack changed in Left / Right")
    # the Cable button takes no click
    page.evaluate("() => document.getElementById('cableBtn').click()")
    page.wait_for_timeout(300)
    if page.query_selector("#cableHelp"):
        bad.append("Left / Right: a click on the Cable button turned Cable mode on")
    # back in Front / Rear everything is in use again: the Cable button, and a drag that moves
    to_faces(page)
    if page.is_disabled("#cableBtn") or page.get_attribute("#cableBtn", "title"):
        bad.append("back in Front / Rear the Cable button is still off")
    return bad


@extra("rack.html: every file is the same whether the panes show Front / Rear or Left / Right - the sheet, the draw.io file, the bill of materials, the cable schedule and the rack file byte for byte, and the GLB's materials, images, nodes and bundle content - and none holds a side view (#187)")
def check_rack_side_exports_same(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_side_fixture(page, base)
    res = page.evaluate("() => window.__rack.bundleCommand({op: 'bundle.create', cables: ['c1', 'c3'], label: 'pair'})")
    if res and res.get("error"):
        return bad + [f"the bundle was not made: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneFront [data-strap=\"b1\"]') && window.__rack.routesCurrent().current", timeout=READY_MS)
    page.wait_for_timeout(400)
    KINDS = ("sheet-svg", "front-svg", "rear-svg", "drawio", "bom", "cables", "json")
    grab = lambda kind: pathlib.Path(export_file(page, kind).path()).read_bytes()
    gl = not webgl_trouble(page)
    if not gl:
        print("[check_rack_side_exports_same] no WebGL here - the GLB was not compared")

    def model():
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, "3D: the side fixture's scene, for its GLB", tubes=True)
        g = page.evaluate(BUNDLE_GLB_JS)
        page.click('#mode [data-mode="2d"]')
        page.wait_for_function("() => !document.getElementById('panes').hidden && document.querySelectorAll('#panes > section > div > svg').length === 2", timeout=READY_MS)
        page.wait_for_timeout(400)
        return g
    faces = {k: grab(k) for k in KINDS}
    glb_f = model() if gl else None
    to_sides(page)
    menu = page.evaluate("() => { document.querySelector('#exportMenu > summary').click(); const v = [...document.querySelectorAll('#exportItems [data-export]')].map(b => [b.dataset.export, b.textContent]); document.querySelector('#exportMenu > summary').click(); return v; }")
    if any("left" in k or "right" in k or "side" in k.lower() or "Left" in t or "Right" in t for k, t in menu):
        bad.append(f"Left / Right: the Export menu offers a side view: {menu}")
    sides = {k: grab(k) for k in KINDS}
    glb_s = model() if gl else None
    least = {"sheet-svg": 2000, "front-svg": 2000, "rear-svg": 2000, "drawio": 2000, "bom": 100, "cables": 200, "json": 500}
    for k in KINDS:
        if len(faces[k]) < least[k]:
            bad.append(f"{k}: the file is {len(faces[k])} bytes: nothing was compared")
        if faces[k] != sides[k]:
            bad.append(f"{k}: the file exported from Left / Right ({len(sides[k])} bytes) is not the one exported from Front / Rear ({len(faces[k])} bytes)")
        if b'data-pane="left"' in sides[k] or b'data-side' in sides[k] or b'"sides"' in sides[k]:
            bad.append(f"{k}: the file holds a side pane or the pair")
    # the schedule and the bill of materials did carry the cables and the bundle's straps
    if b"c1" not in faces["cables"] or faces["cables"].count(b"\n") < 4 or faces["bom"].count(b"\n") < 4:
        bad.append(f"the cable schedule ({faces['cables'].count(bytes([10]))} lines) or the bill of materials ({faces['bom'].count(bytes([10]))} lines) is too short to have been compared")
    if gl:
        same = ("paint", "images", "nodes", "cables", "straps", "trunks", "bundle", "bytes")
        diff = [k for k in same if glb_f[k] != glb_s[k]]
        if diff:
            bad.append(f"GLB: from Left / Right it differs from Front / Rear in {diff} ({[(glb_f[k], glb_s[k]) for k in diff if k not in ('paint', 'images')]})")
        if len(glb_f["cables"]) != 3 or not glb_f["straps"] or not glb_f["bundle"] or glb_f["nodes"] < 20:
            bad.append(f"GLB: it holds cables {glb_f['cables']}, {len(glb_f['straps'])} straps, {glb_f['nodes']} nodes: too little to have been compared")
    if page.evaluate("() => window.__rack.view()") != "sides" or not page.evaluate(SIDE_DRAWN):
        bad.append("after the exports the panes no longer show Left / Right")
    return bad


# FRESH AFTER AN EDIT (#187). A switch of pair draws from the faces and routes
# the page already holds, and only when both were read for the rack as it is
# (rack-page.js redraw `kept`: S.routes.rack and S.factsRack are this very rack
# object). The cases that tell are a switch pressed inside an edit's redraw.
# They are not left to timing, which a fast machine wins: the redraw is HELD at
# a named point (the page's probe hook, probeHeld) while the switch is pressed
# and drawn. Held while the routes are read, a rule without the routes' rack
# test draws the rack before the edit and leaves it so. Held after the routes
# are set and before the facts are stored, a rule without the facts' rack test
# draws this rack's routes with the facts of the rack before. Each case ends
# with the same document loaded afresh: the two must be drawn and said the same.
SIDE_FRESH_JS = """() => ({
  current: window.__rack.routesCurrent().current,
  pair: [...document.querySelectorAll('#panes > section > div > svg')].map(s => s.dataset.pane),
  cables: [...document.querySelectorAll('#panes > section > div > svg')].map(s => [...s.querySelectorAll(':scope > [data-cables] [data-cable][data-cable-id]')]
    .map(g => [g.dataset.cableId, [...g.querySelectorAll('path')].map(p => p.getAttribute('d')).join('|')]).sort()),
  bodies: [...document.querySelectorAll('#panes > section > div > svg')].map(s => [...s.querySelectorAll(':scope > [data-item-id], [data-side-near] > [data-zerou-id], :scope > [data-zerou-id]')]
    .map(g => [g.dataset.itemId ?? g.dataset.zerouId, g.getAttribute('transform')]).sort()),
  list: [...document.querySelectorAll('#cableList li')].map(li => li.innerText.replace(/\\s+/g, ' ').trim()),
  notice: [...document.querySelectorAll('#side .rk-notice, #side .rk-warn')].map(n => n.textContent).filter(t => /not known|not checked/i.test(t)),
  seats: JSON.stringify(window.__rack.cableFacts()),
})"""
SIDE_SETTLED = """() => window.__rack.routesCurrent().current && !document.getElementById('panes').hasAttribute('aria-busy')
  && document.querySelectorAll('#panes > section > div > svg').length === 2 && !document.getElementById('panes').hidden"""


@extra("rack.html: a switch of pair pressed while an edit is still being redrawn shows the rack as it now is - after a move, a turn and a cable removed and added, with the edit's redraw held while its routes are read, held after they are set and before its facts are stored, and once settled, the drawings, the cable list, the facts and the routes are those of the same document loaded afresh - and a new cable's picked ends dropped by the switch leave nothing behind (#187)")
def check_rack_side_fresh_after_edit(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_side_fixture(page, base)
    fixture = page.evaluate("() => structuredClone(window.__rack.doc().racks[0])")

    def settle(where):
        try:
            page.wait_for_function(SIDE_SETTLED, timeout=9000)
        except Exception:
            bad.append(f"{where}: the page did not settle: the routes it holds are not this rack's")
        page.wait_for_timeout(500)
        park_mouse(page)
    edits = [
        ("a move", ["() => window.__rack.apply({op: 'move', id: 'i3', ru: 33})"]),
        ("a turn", ["() => window.__rack.apply({op: 'patch', id: 'i5', turned: false})"]),
        ("a cable removed and added", ["() => window.__rack.apply({op: 'cable.remove', id: 'c3'})",
                                       "() => window.__rack.apply({op: 'cable.add', a: {item: 'i1', path: 'port-5', view: 'front'}, b: {item: 'i3', path: 'port-5', view: 'front'}, media: 'cat6a'})"]),
    ]
    # WHERE THE SWITCH LANDS IS HELD, NOT TIMED (rack-page.js probeHeld): the edit's redraw is held open at a named point, the
    # switch is pressed and drawn, and only then is the held redraw let go.
    #   'routes': the routes are being read. The page holds the routes and the facts of the rack before the edit.
    #   'drawn':  the routes are set for the rack as it is, and its facts are not stored yet: routes current, facts stale.
    #   None:     no hold; the switch is pressed once the edit has settled.
    for k, (what, cmds) in enumerate(edits):
        for n, hold in enumerate(("routes", "drawn", None)):
            # from one pair to the other, turn about: the edit is made in `start`, and the switch is to `to`
            start, to = (("faces", "sides") if (k + n) % 2 == 0 else ("sides", "faces"))
            when = {"routes": "while its routes are being read", "drawn": "after its routes are set and before its facts are stored", None: "once it has settled"}[hold]
            where = f"{what}, the switch to {'Left / Right' if to == 'sides' else 'Front / Rear'} {when}"
            if page.evaluate("() => window.__rack.view()") != start:
                page.click(f'#view2d [data-view="{start}"]')
            page.evaluate("r => window.__rack.replaceRack(r)", fixture)
            page.wait_for_function(SIDE_DRAWN if start == "sides" else FACES_DRAWN, timeout=READY_MS)
            settle(f"{where} (before)")
            for cmd in cmds[:-1]:
                r = page.evaluate(cmd)
                if r and r.get("error"):
                    bad.append(f"{where}: refused: {r['error']}")
                settle(f"{where} (first step)")
            if hold is None:
                r = page.evaluate(cmds[-1])
                settle(f"{where} (the edit)")
                page.click(f'#view2d [data-view="{to}"]')
                page.wait_for_function(SIDE_DRAWN if to == "sides" else FACES_DRAWN, timeout=READY_MS)
            else:
                # the edit, with its redraw held at the point; the page's state there is read, to know the window is the one named
                r = page.evaluate("""async ([cmd, hold]) => { window.__rack.holdRedraw(hold); const r = (0, eval)(`(${cmd})`)();
                  const reached = await Promise.race([window.__rack.heldRedraw().then(() => true), new Promise(done => setTimeout(() => done(false), 15000))]);
                  return {error: r?.error ?? null, reached, current: window.__rack.routesCurrent().current}; }""", [cmds[-1], hold])
                if not r.get("reached"):
                    page.evaluate("() => window.__rack.releaseRedraw()")
                    bad.append(f"{where}: the edit's redraw was never held there, so the case was not tried")
                    continue
                # while the routes are read the page's routes are the old rack's; once they are set they are this rack's
                if r["current"] != (hold == "drawn"):
                    bad.append(f"{where}: held there, the page's routes are {'this' if r['current'] else 'not this'} rack's; the hold is not at the point it names")
                page.click(f'#view2d [data-view="{to}"]')
                # the switch's own redraw runs past the held one and draws the pair asked for
                try:
                    page.wait_for_function(SIDE_DRAWN if to == "sides" else FACES_DRAWN, timeout=20000)
                    page.wait_for_function("() => !document.getElementById('panes').hasAttribute('aria-busy')", timeout=20000)
                except Exception:
                    bad.append(f"{where}: with the edit's redraw held, the switch did not draw the pair asked for")
                page.evaluate("() => window.__rack.releaseRedraw()")
            if r and r.get("error"):
                bad.append(f"{where}: refused: {r['error']}")
            settle(where)
            got = page.evaluate(SIDE_FRESH_JS)
            # the same document, loaded afresh, in the same pair
            page.evaluate("() => window.__rack.loadDoc(structuredClone(window.__rack.doc()))")
            page.wait_for_function("n => Object.keys(window.__rack.paths() || {}).length === n", arg=3, timeout=READY_MS)
            settle(f"{where} (loaded afresh)")
            want = page.evaluate(SIDE_FRESH_JS)
            if not want["current"] or want["pair"] != (["left", "right"] if to == "sides" else ["front", "rear"]) or sum(len(c) for c in want["cables"]) < 3:
                bad.append(f"{where}: the fresh load to compare with is not settled or shows {want['pair']} with {[len(c) for c in want['cables']]} cables")
                continue
            for key, said in (("current", "the routes are current"), ("pair", "the pair shown"), ("bodies", "where the bodies are drawn"), ("cables", "the cables as drawn"),
                              ("list", "the cable list"), ("notice", "a not-known notice"), ("seats", "the facts of the cabled ends")):
                if got[key] != want[key]:
                    n_diff = (sum(1 for a, b in zip(sum(got[key], []), sum(want[key], [])) if a != b) if key in ("cables", "bodies") else None)
                    bad.append(f"{where}: {said} differ from the same document loaded afresh"
                               + (f" ({n_diff} drawings)" if n_diff is not None else f" ({str(got[key])[:120]} against {str(want[key])[:120]})"))
    # without the probe's hold set, nothing of it is in a redraw's way: the page holds none now
    if page.evaluate("() => window.__rack.heldRedraw() instanceof Promise && (window.__rack.releaseRedraw(), true)") is not True:
        bad.append("the probe's hold could not be cleared")
    # ── A NEW CABLE IN HAND, dropped by the switch: the plugs seated for its two picked ends go with it ──
    page.click('#view2d [data-view="faces"]')
    page.evaluate("r => window.__rack.replaceRack(r)", fixture)
    page.wait_for_function(FACES_DRAWN, timeout=READY_MS)
    settle("the new-cable case (before)")
    seats0 = page.evaluate("() => JSON.stringify(window.__rack.cableFacts())")
    page.click("#cableBtn")
    for item, port in (("i1", "port-7"), ("i3", "port-7")):
        box = page.evaluate("""([item, port]) => { const r = document.querySelector(`#paneFront svg [data-item-id="${item}"][data-panel="mounted"] [data-path="${port}"]`).getBoundingClientRect();
          return [r.left + r.width / 2, r.top + r.height / 2]; }""", [item, port])
        page.mouse.click(box[0], box[1])
        page.wait_for_timeout(500)
    try:
        page.wait_for_selector("#cableForm", timeout=8000)
    except Exception:
        return bad + ["the new-cable case: picking two ports did not open the new cable's form"]
    settle("the new-cable case (the form open)")
    with_form = page.evaluate("() => JSON.stringify(window.__rack.cableFacts())")
    if with_form == seats0:
        bad.append("the new-cable case: with the form open the page's facts hold nothing for its two ends, so there was nothing to leave behind")
    page.click('#view2d [data-view="sides"]')
    page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
    settle("the new-cable case (in Left / Right)")
    in_sides = page.evaluate("() => [JSON.stringify(window.__rack.cableFacts()), !!document.getElementById('cableForm'), window.__rack.doc().racks[0].cables.length]")
    page.click('#view2d [data-view="faces"]')
    page.wait_for_function(FACES_DRAWN, timeout=READY_MS)
    settle("the new-cable case (back in Front / Rear)")
    back = page.evaluate("() => JSON.stringify(window.__rack.cableFacts())")
    if in_sides[1] or in_sides[2] != 3:
        bad.append(f"the new-cable case: in Left / Right the form is {'open' if in_sides[1] else 'closed'} and the rack has {in_sides[2]} cables; expected the form gone and nothing added")
    if in_sides[0] != seats0 or back != seats0:
        bad.append("the new-cable case: after the switch the page still holds facts for the dropped cable's two ends")
    return bad


# A RACK OF A SIZE (portrayal-site#192): `devices` two-unit fabric switches stacked from the top of a 42U four-post
# rack, a lacer panel on each, a vertical manager either side, and `per_pair` cables from each switch to the one below
# it, port k to port 24 + k, each port holding the cable's own plug. 13 devices and 24 a pair is 288 cables and 576
# seated ends: the shape and size of the rack the issue was measured on. Built here, so no rack file is committed.
def speed_fixture(devices, per_pair=24, name=None):
    if not (2 <= devices <= 20 and 1 <= per_pair <= 24):
        raise ValueError("speed_fixture: 2 to 20 devices, 1 to 24 cables a pair")
    items, cables = [], []
    for k in range(devices):
        used = ([*range(per_pair)] if k < devices - 1 else []) + ([*range(24, 24 + per_pair)] if k else [])
        items.append({"id": f"i{k + 1}", "ref": "s9725-64e", "cfg": "ac", "label": f"FAB-{k + 1}", "ru": 41 - 2 * k, "face": "front", "turned": False,
                      "swaps": {f"port-{n}": "generic/qsfp-dd-cable@1" for n in used}, "fields": {}})
    for k in range(devices):
        items.append({"id": f"i{devices + k + 1}", "ref": "fhd-cmp5dr", "cfg": "base", "label": f"CM-{k + 1}", "ru": 42 - 2 * k, "face": "front",
                      "turned": False, "swaps": {}, "fields": {}, "on": f"i{k + 1}", "unit": 2})
    for k in range(devices - 1):
        for n in range(per_pair):
            cables.append({"id": f"c{len(cables) + 1}", "a": {"item": f"i{k + 1}", "path": f"port-{n}", "view": "front"},
                           "b": {"item": f"i{k + 2}", "path": f"port-{24 + n}", "view": "front"}, "media": "aoc", "purpose": "fabric",
                           "label": f"FAB-{k + 1} {n} > FAB-{k + 2} {24 + n}", "route": []})
    return {"format": "portrayal-rack", "version": 4, "id": f"doc-speed-{devices}-{per_pair}", "racks": [{
        "id": "r1", "name": name or f"Speed {len(cables)}",
        "frame": {"kind": "four-post", "heightRU": 42, "numbering": "bottom-up", "holes": {"style": "square", "thread": None},
                  "railDepth": 740, "usableDepth": 1000, "ref": None},
        "items": items,
        "zeroU": [{"id": "z1", "ref": "cmv-sfd42u9w", "cfg": "base", "label": "CMV left", "at": "left-front", "offsetMm": 0},
                  {"id": "z2", "ref": "cmv-sfd42u9w", "cfg": "base", "label": "CMV right", "at": "right-front", "offsetMm": 0}],
        "cables": cables}]}


# ONE READING OF A RACK, AND NEVER A STALE ONE (portrayal-site#192, site/rack/reading.js). The routes are read once for
# a rack object and handed to the panes, the list, the exports and every assistant tool, and what a tool reads of the
# kit is answered once for the rack object. What that risks is staleness: something shown, said or downloaded that was
# true of the rack before an edit. So each kind of edit is made on a page that has already answered everything for the
# rack before it, and what the page then shows, says and downloads is compared with THE SAME DOCUMENT OPENED IN A
# BROWSER THAT HAS NEVER SEEN IT (another context, a fresh page): nothing there can be left over from anything.
#
# The page's state, as plain data: both panes' drawings whole, the list's rows, every route warning (a folded kind is
# opened first), what the page read of the routes, and the rack.
READING_STATE_JS = """async () => {
  const R = window.__rack, plain = v => JSON.parse(JSON.stringify(v ?? null));
  for (const d of document.querySelectorAll('#side details[data-route-more]:not([open])')) d.querySelector('summary').click();
  await new Promise(r => setTimeout(r, 30));
  // (less the zoom, which is the window's, and the outline an assistant's edit wears for three seconds; and every
  // number to a millionth: the cable layer is measured off the laid-out pane, and two pages lay the same pane out
  // to within the last digits of a float, 310.60001226425175 against 310.6000122642518 on CI's runner)
  const pane = id => { const svg = document.querySelector(`#${id} > svg`); if (!svg) return null;
    const c = svg.cloneNode(true); c.removeAttribute('style');
    for (const n of c.querySelectorAll('.rk-agent-touched')) { n.classList.remove('rk-agent-touched'); if (!n.getAttribute('class')) n.removeAttribute('class'); }
    return c.outerHTML.replace(/-?\\d+\\.\\d{7,}/g, m => String(Math.round(Number(m) * 1e6) / 1e6)); };
  return {"the front pane's drawing": pane('paneFront'), "the rear pane's drawing": pane('paneRear'),
    "the cable list's rows": [...document.querySelectorAll('#side [data-cable-item]')].map(li => li.textContent),
    'the route warnings': [...document.querySelectorAll('#side [data-route-warning]')].map(p => p.textContent),
    'the routes': plain(R.routes()), 'the paths': plain(R.paths()), 'the fill': plain(R.fill()), 'the ring marks and findings': plain(R.rings()),
    'the bodies crossed': plain(R.bodies()), 'the tight bends': plain(R.bends()), 'the bundles': plain(R.bundles()),
    'the tie straps': plain(R.tieStraps()), "the cabled ends' facts": plain(R.cableFacts()), 'the rack': plain(R.doc().racks[0])};
}"""
# A redraw has finished since `n` were, none is running or queued, and the routes the page holds are this rack's.
READING_SETTLED = """n => window.__rack.drawn() > n && window.__rack.idle()
  && (!window.__rack.doc().racks[0].cables.length || window.__rack.routesCurrent().current)"""
# describe_rack asked the moment an edit lands, before its redraw has read anything, against the kit asked afresh of
# that very rack object with a context nobody else holds: [what the tool said, the kit's lines it should end with].
# (A small window, so the tool's own cut to fit plays no part: its text is the kit's first line, its own lines of the
# session, then the rest of the kit's.)
READING_AT_ONCE_JS = """async () => {
  const rack = window.__rack.doc().racks[0];
  const said = window.__tools.describe_rack.execute({limit: 4});
  const Q = await import('/vendor/rack/queries.js'), RC = await import('/site/rack/route-context.js'), C = await import('/vendor/rack/catalog.js');
  const {chassisOf} = await C.loadCatalog('assets/dist/'), types = await RC.cableTypes();
  const rf = rack.cables.length ? await RC.routeFacts(rack, chassisOf) : null;
  const kit = Q.describe(rack, {chassisOf, ...(rf ? {route: rf.ctx} : {}), ...(types ? {diameterOf: types.diameterOf, bendOf: types.bendOf} : {})}, {offset: 0, limit: 4});
  return {said: (await said).content[0].text, kit};
}"""
READING_TOOL_JS = """async ([n, a]) => { const before = window.__rack.reads(), res = await window.__tools[n].execute(a), after = window.__rack.reads();
  return {text: (res?.content ?? []).map(c => c.text).join('\\n'), isError: !!res?.isError,
          reads: after.routeFacts - before.routeFacts, lays: after.lays - before.lays}; }"""


def reading_tools(rack):
    """The tool calls whose answers are compared: everything an assistant can read of this rack."""
    cables = [c["id"] for c in rack.get("cables") or []]
    # (windows small enough to fit whole: the default one is cut to the room the undo line leaves, and a rack opened afresh has none)
    calls = [("describe_rack", {"limit": 4}), ("describe_rack", {"section": "items"}), ("describe_rack", {"section": "bundles"})]
    calls += [("describe_rack", {"section": "cables", "offset": k, "limit": 8}) for k in range(0, len(cables), 8)]
    calls += [("inspect", {"id": c}) for c in dict.fromkeys(cables[:2] + cables[-2:])]
    calls += [("inspect", {"id": b["id"]}) for b in rack.get("bundles") or []]
    calls += [("inspect", {"id": "i1"}), ("list_free_ports", {"id": "i1"}), ("check_fit", {"ref": "as7326-56x", "face": "front"})]
    if len(cables) >= 2:
        calls.append(("edit_rack", {"dry_run": True, "commands": [{"op": "bundle.create", "cables": cables[-2:]}]}))
    return calls


# The undo line is the one thing a tool says that is the session's, not the rack's: a rack opened afresh has nothing to undo.
def reading_text(name, text):
    lines = text.split("\n")
    return "\n".join(l for k, l in enumerate(lines) if not (name == "describe_rack" and k == 1 and (l.startswith("Undo would take back") or l == "Nothing to undo.")))


@extra("rack.html: one reading of a rack, never a stale one - after each kind of edit (a cable's end, media and label, a cable removed and added, a device moved, renamed and an optic taken out by an assistant, the frame, a route by hand and reset, a bundle, undo, redo, the DCIM settings, the rack's name, another document with the same ids) every tool's text, both drawings, the list, the warnings, the routes and a download are those of the same document opened in a browser that has never seen it; a tool call on a rack that has not changed reads no route again, and asked twice lays no cable (#192)")
def check_rack_reading_fresh_after_edit(page, base):
    return reading_fresh_after_edit(page, base, False)


def reading_fresh_after_edit(page, base, check_kept):
    """The staleness run. With `check_kept` the page is opened with ?checkKept=1 (the kit lays every path it reads again
    from nothing and compares it with the one it kept, route-context.js kept): the cold lays go through the same plug
    reaches, so the counts of cables laid cannot hold in that pass and are not asked; a throw of the kit's is a failure
    wherever it is raised, so the console is read too (the kit swallows some into console.warn)."""
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    if check_kept:
        page.on("console", lambda m: bad.append(f"console {m.type}: {m.text[:300]}") if "checkKept" in m.text else None)
    page.add_init_script(STAND_IN_MODEL_CONTEXT)
    page.set_viewport_size({"width": 1600, "height": 1000})
    fixture = json.loads(CABLE_LAY_FIXTURE.read_text())
    fixture.pop("_note", None)
    page.goto(f"{base}/rack.html?probe=1" + ("&checkKept=1" if check_kept else ""), wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.click('#view2d [data-view="faces"]')
    # the browser that has never seen the rack: its own context, so not even this one's library
    other = page.context.browser.new_context(viewport={"width": 1600, "height": 1000}, accept_downloads=True)
    fresh = other.new_page()
    fresh.on("pageerror", lambda e: bad.append(f"uncaught, in the fresh browser: {e}"))
    if check_kept:
        fresh.on("console", lambda m: bad.append(f"console {m.type}, in the fresh browser: {m.text[:300]}") if "checkKept" in m.text else None)
    fresh.add_init_script(STAND_IN_MODEL_CONTEXT)

    def settle(pg, drawn, where):
        try:
            pg.wait_for_function(READING_SETTLED, arg=drawn, timeout=READY_MS)
        except Exception:
            bad.append(f"{where}: the page did not settle on the routes of the rack as it is")
        pg.wait_for_timeout(150)

    def answers(pg, rack):
        out = []
        for name, a in reading_tools(rack):
            r = pg.evaluate(READING_TOOL_JS, [name, a])
            out.append((name, a, r))
        return out

    def schedule(pg):
        dl = export_file(pg, "cables")
        return pathlib.Path(dl.path()).read_text()

    def compare(where, drawn_before):
        settle(page, drawn_before, where)
        rack = page.evaluate("() => window.__rack.doc().racks[0]")
        got_state, got_tools, got_csv = page.evaluate(READING_STATE_JS), answers(page, rack), schedule(page)
        # ...and a redraw that changes nothing reads nothing again and draws the same
        n, reads = page.evaluate("() => [window.__rack.drawn(), window.__rack.reads()]")
        page.evaluate("() => { window.__rack.redraw(); }")
        settle(page, n, f"{where} (drawn again)")
        again_state, reads_after = page.evaluate(READING_STATE_JS), page.evaluate("() => window.__rack.reads()")
        if rack["cables"] and (reads_after["routeFacts"] != reads["routeFacts"] or (reads_after["lays"] != reads["lays"] and not check_kept)):
            bad.append(f"{where}: a redraw of a rack that had not changed read the routes {reads_after['routeFacts'] - reads['routeFacts']} times and laid {reads_after['lays'] - reads['lays']:g} cables; expected neither")
        for key in got_state:
            if again_state[key] != got_state[key]:
                bad.append(f"{where}: {key} changed when the page was drawn again with no edit")
        # each tool again: no route is read, and no cable is laid for an answer already given
        # (a dry run is not a reading: the kit runs the command, which lays what the command needs laid)
        for name, a, first in got_tools:
            r = page.evaluate(READING_TOOL_JS, [name, a])
            if r["text"] != first["text"]:
                bad.append(f"{where}: {name} {json.dumps(a)} answered differently the second time")
            if r["reads"] or (r["lays"] and name != "edit_rack" and not check_kept):
                bad.append(f"{where}: {name} {json.dumps(a)}, asked a second time of a rack that had not changed, read the routes {r['reads']} times and laid {r['lays']:g} cables; expected neither")
        for name, a, first in got_tools:
            if first["reads"]:
                bad.append(f"{where}: {name} {json.dumps(a)} read the routes again ({first['reads']} times) on a rack the page had already read")
        # THE SAME DOCUMENT, in the browser that has never seen it
        doc = page.evaluate("() => window.__rack.doc()")
        open_fixture(fresh, base, doc)
        settle(fresh, 0, f"{where} (opened afresh)")
        want_state, want_tools, want_csv = fresh.evaluate(READING_STATE_JS), answers(fresh, rack), schedule(fresh)
        if len(want_state["the paths"] or {}) != len(rack["cables"]) and rack["cables"]:
            bad.append(f"{where}: the fresh browser to compare with read {len(want_state['the paths'] or {})} paths for {len(rack['cables'])} cables")
        for key in got_state:
            if got_state[key] != want_state[key]:
                a, b = json.dumps(got_state[key]), json.dumps(want_state[key])
                k = next((i for i in range(min(len(a), len(b))) if a[i] != b[i]), min(len(a), len(b)))
                bad.append(f"{where}: {key} is not that of the same document opened afresh: ...{a[max(0, k - 60):k + 90]} against ...{b[max(0, k - 60):k + 90]}")
        for (name, a, g), (_, _, w) in zip(got_tools, want_tools):
            if reading_text(name, g["text"]) != reading_text(name, w["text"]) or g["isError"] != w["isError"]:
                bad.append(f"{where}: {name} {json.dumps(a)} does not say what it says of the same document opened afresh: {g['text'][:160]!r} against {w['text'][:160]!r}")
        if got_csv != want_csv:
            bad.append(f"{where}: the cable schedule is not the one downloaded from the same document opened afresh")
        return rack

    drawn = page.evaluate("() => window.__rack.drawn()")
    page.evaluate("r => window.__rack.replaceRack(r)", fixture)
    rack = compare("the rack as loaded", drawn)
    if page.evaluate("() => window.__rack.checkKept()") != check_kept:
        bad.append(f"the route context the page read has the kit's checkKept {'off' if check_kept else 'on'}; expected it {'on' if check_kept else 'off'}")
    if len(rack["cables"]) != 16:
        return bad + [f"the fixture has {len(rack['cables'])} cables; expected the cable-lay rack's 16"]
    apply = lambda cmd: f"() => window.__rack.apply({json.dumps(cmd)})"
    agent = lambda cmds: f"() => window.__tools.edit_rack.execute({json.dumps({'commands': cmds})}).then(r => (r.isError ? {{error: r.content[0].text}} : {{}}))"
    edits = [
        ("a cable's end moved", apply({"op": "cable.update", "id": "c16", "b": {"item": "i2", "path": "bay-1/module/lc1", "view": "front"}})),
        ("a cable's media changed", apply({"op": "cable.update", "id": "c2", "media": "cat6a"})),
        ("a cable's label changed", apply({"op": "cable.update", "id": "c3", "label": "uplink three"})),
        ("a cable removed", apply({"op": "cable.remove", "id": "c15"})),
        ("a cable added", apply({"op": "cable.add", "a": {"item": "i3", "path": "port-55", "view": "front"}, "b": {"item": "i2", "path": "bay-1/module/lc2", "view": "front"}, "media": "om4"})),
        ("a device moved", apply({"op": "move", "id": "i3", "ru": 37})),
        ("a device renamed", apply({"op": "patch", "id": "i1", "label": "LEAF-A2"})),
        ("an optic taken out by an assistant", agent([{"op": "fit", "id": "i1", "path": "port-56", "ref": None}])),
        ("the frame grown", apply({"op": "frame", "heightRU": 44})),
        ("a route edited by hand", """() => { const ways = new Map(window.__rack.routes()).get('c4') ?? [];
            return window.__rack.apply({op: 'cable.route', id: 'c4', route: [...ways, {lane: 'left-front', ru: 30}], summary: 'Waypoint added.'}); }"""),
        ("the route reset", apply({"op": "cable.route.reset", "id": "c4", "summary": "Route reset to automatic."})),
        ("a bundle made", "() => window.__rack.bundleCommand({op: 'bundle.create', cables: ['c5', 'c6', 'c7'], label: 'trunk'})"),
        ("undo", "() => { window.__rack.undo(); return {}; }"),
        ("redo", "() => { window.__rack.redo(); return {}; }"),
        # not a step: the rack is a new object that shares the reading of the one before (reading.js sameReading)
        ("the DCIM settings", apply({"op": "dcim", "site": "DC-1", "role": "leaf"})),
        ("the rack renamed", apply({"op": "rename", "name": "Cable lay, renamed"})),
        # another document, its ids the same as the last one's: nothing of the last is its
        ("another document with the same ids", """() => { const d = structuredClone(window.__rack.doc());
            d.id = 'doc-reading-other'; d.racks[0].name = 'Another';
            d.racks[0].cables = d.racks[0].cables.filter(c => !['c1', 'c9'].includes(c.id)).map(c => (c.id === 'c10' ? {...c, media: 'os2'} : c));
            d.racks[0].bundles = [];
            window.__rack.loadDoc(d); return {}; }"""),
    ]
    for what, js in edits:
        # before the edit the page has answered everything for the rack as it was (compare did): each answer is there to go stale
        drawn = page.evaluate("() => window.__rack.drawn()")
        r = page.evaluate(js)
        if r and r.get("error"):
            bad.append(f"{what}: refused: {r['error']}")
            continue
        # ASKED AT ONCE, before the edit's redraw has read a route: the answer is this rack's, as the kit gives it afresh.
        # (Not compared with the answer once the redraw is done: the redraw writes the routed lengths, and a new cable's spare with them.)
        at_once = page.evaluate(READING_AT_ONCE_JS)
        first, rest = at_once["kit"].split("\n", 1) if "\n" in at_once["kit"] else (at_once["kit"], "")
        if not (at_once["said"].startswith(first + "\n") and at_once["said"].endswith("\n" + rest)):
            bad.append(f"after {what}: describe_rack asked the moment the edit landed does not say what the kit says of the rack as it then was: {at_once['said'][:300]!r} against {at_once['kit'][:300]!r}")
        rack = compare(f"after {what}", drawn if what != "the DCIM settings" else drawn - 1)
    other.close()
    return bad


@extra("rack.html: what the kit keeps is what it would lay afresh - the staleness run again with the kit's own check on (?probe=1&checkKept=1, kit ctx.checkKept: every path the kit reads is laid again from copies of the rack, the cable and the context and compared with the one it kept, and a difference throws), through every kind of edit; no page error, no console message of the check, no settle timeout, and every tool, drawing and download still that of the same document opened afresh (#192)")
def check_rack_kept_paths_hold(page, base):
    return reading_fresh_after_edit(page, base, True)


# A LARGE RACK'S BUDGETS (portrayal-site#192). The rack the issue was measured on took 39 s to draw, 27 s to draw again
# with nothing changed, and half a minute for each call an assistant made, because everything read every route again.
# What holds that off is counted here, on a rack of 288 cables built in the check (speed_fixture), in two ways:
#
#   - BY COUNT, which no machine's load moves: how many times the routes were read (route-context.js routeFacts) and
#     how many cables the kit read the inputs of (its asks for a plug's reach, halved; kit 0.25.0 asks when it reads a
#     cable's inputs, `layInputs`, and not for a path it has kept, so this is no longer "cables laid"), for the first
#     draw, a redraw with nothing changed, an edit, and each thing an assistant reads, the first time and again;
#   - BY TIME, as a ratio to another time taken in the same run on the same machine, never in seconds: against the same
#     rack's own first draw, and against the first draw of a rack of 12 cables.
#
# Measured on kit 0.25.0 (this rack, an 80-core machine with other work running): a draw and the first describe_rack
# 4.67 per cable, an edit's redraw 4.65, an inspect of a cable 0.01, everything else none; a first draw about 9 s, a
# redraw with nothing changed about 2.5 s (the page's own drawing: the kit reads nothing), an edit's redraw about 5 s.
# Each bound has about twice the room the page needs today (a count that was none is allowed a tenth, so a kit that
# reads a few inputs again is not a failure; every cable again would be 4.67), so a slow or busy runner does not trip
# one; a change that reads the routes again where it did not, or has the kit read every cable for a question already
# answered, goes past it by far. The bounds are ceilings: when the kit keeps more, the counts fall, and nothing here minds.
SPEED_BUDGETS = {
    # (reads of the routes, kit cable-input reads per cable) at most
    "first draw": (1, 10), "a redraw with nothing changed": (0, 0), "a redraw after one cable's end is moved": (1, 10),
    # (the first question of a rack whose cables had no length until the page measured them is asked of the rack as it
    # is, a new object; the kit reads each cable's inputs once for it. After that, and after an edit, it reads none)
    "describe_rack, first asked": (0, 10), "describe_rack, asked again": (0, 0), "describe_rack after the edit": (0, 0.1),
    "describe_rack's next page, first asked": (0, 0.1),
    "inspect of a cable, first asked": (0, 0.05), "inspect of a cable, asked again": (0, 0),
    "the cable schedule, first downloaded": (0, 0.1), "the cable schedule, downloaded again": (0, 0),
}
# a time, as a multiple of another time of the same run, at most (measured: 0.27, 0.02, 0.005, 0.004, 0.00, 0.00, 0.59, 11.6)
SPEED_RATIOS = [
    ("a redraw with nothing changed", "first draw", 0.55),
    ("describe_rack, first asked", "first draw", 0.1),
    ("describe_rack's next page, first asked", "first draw", 0.1),
    ("describe_rack after the edit", "first draw", 0.1),
    ("describe_rack, asked again", "the small rack's first draw", 1.0),
    ("inspect of a cable, asked again", "the small rack's first draw", 1.0),
    ("a redraw after one cable's end is moved", "first draw", 1.2),
    ("first draw", "the small rack's first draw", 30),
]
SPEED_TIMED_JS = """async ([src, arg, needDraw]) => {
  const R = window.__rack, sleep = t => new Promise(r => setTimeout(r, t));
  const before = R.reads(), drawn = R.drawn(), t0 = performance.now();
  const out = await (0, eval)(`(${src})`)(arg);
  for (;;) {
    await new Promise(r => queueMicrotask(r));
    if ((!needDraw || R.drawn() > drawn) && R.idle()) { await sleep(0); if (R.idle()) break; }
    await sleep(5);
  }
  const after = R.reads();
  return {ms: performance.now() - t0, out: out ?? null, reads: after.routeFacts - before.routeFacts, lays: after.lays - before.lays};
}"""
# How long any one step of the large rack gets: it reads 288 routes, and a 2-CPU runner draws them in minutes.
SPEED_MS = 600000


def speed_open(page, base, doc):
    """A fresh page and the document through Open .json: the first draw's {ms, reads, lays}, from the file being chosen."""
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.wait_for_function("() => window.__rack.idle()", timeout=SPEED_MS)
    if page.evaluate("() => window.__rack.view()") != "faces":
        page.click('#view2d [data-view="faces"]')
    was = page.evaluate("() => ({id: window.__rack.doc().id, drawn: window.__rack.drawn(), reads: window.__rack.reads()})")
    t0 = time.time()
    page.set_input_files("#openFile", files=[{"name": "speed.rack.json", "mimeType": "application/json", "buffer": json.dumps(doc).encode()}])
    page.wait_for_function("was => window.__rack.doc().id !== was.id && window.__rack.drawn() > was.drawn && window.__rack.idle() && window.__rack.routesCurrent().current",
                           arg=was, timeout=SPEED_MS, polling=20)
    ms = (time.time() - t0) * 1000
    got = page.evaluate("was => { const r = window.__rack.reads(); return {reads: r.routeFacts - was.reads.routeFacts, lays: r.lays - was.reads.lays}; }", was)
    return {"ms": ms, **got}


@extra("rack.html: a large rack keeps its budgets - on a rack of 288 cables built in the check, the routes are read once for the first draw and once for an edit and by nothing else (a redraw with nothing changed, describe_rack and its next page, the inspect of a cable, the cable schedule, each asked twice), the kit reads the inputs of each cable at most 10 times for a draw and for the first describe_rack of a rack just measured, a tenth of a time for its next page, one after an edit and a first schedule, and none for anything asked again; and by the clock of the same run a redraw with nothing changed takes under 0.55 of the first draw, a describe_rack under a tenth of it, an answer asked again less than a 12-cable rack's first draw, an edit's redraw no more than 1.2 first draws, and the first draw no more than 30 times the 12-cable rack's (#192)")
def check_rack_speed_budgets(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.add_init_script(STAND_IN_MODEL_CONTEXT)
    page.set_default_timeout(SPEED_MS)
    page.set_viewport_size({"width": 1600, "height": 1000})
    small, big = speed_fixture(3, 6), speed_fixture(13, 24)
    n = len(big["racks"][0]["cables"])
    took_ms, cost = {}, {}
    # the small rack, three times over: its middle time is the yardstick
    took_ms["the small rack's first draw"] = sorted(speed_open(page, base, small)["ms"] for _ in range(3))[1]
    first = speed_open(page, base, big)
    took_ms["first draw"], cost["first draw"] = first["ms"], first
    if page.evaluate("() => Object.keys(window.__rack.paths() ?? {}).length") != n:
        return bad + [f"the large rack did not read a path for each of its {n} cables, so nothing was measured"]

    def timed(what, src, arg=None, need_draw=False):
        r = page.evaluate(SPEED_TIMED_JS, [src, arg, need_draw])
        took_ms[what], cost[what] = r["ms"], r
        return r

    tool = "async ([n, a]) => { const r = await window.__tools[n].execute(a); return {error: !!r?.isError, text: r?.content?.[0]?.text ?? ''}; }"
    timed("a redraw with nothing changed", "() => { window.__rack.redraw(); }", need_draw=True)
    for turn in ("first asked", "asked again"):
        r = timed(f"describe_rack, {turn}", tool, ["describe_rack", {}])
        if r["out"]["error"] or f"{n} cables" not in r["out"]["text"]:
            bad.append(f"describe_rack, {turn}, did not describe the rack: {r['out']['text'][:160]!r}")
    timed("describe_rack's next page, first asked", tool, ["describe_rack", {"section": "cables", "offset": 40, "limit": 40}])
    for turn in ("first asked", "asked again"):
        r = timed(f"inspect of a cable, {turn}", tool, ["inspect", {"id": f"c{n // 2}"}])
        if r["out"]["error"] or "routed" not in r["out"]["text"]:
            bad.append(f"inspect of a cable, {turn}, did not give its routed length: {r['out']['text'][:160]!r}")
    for turn in ("first downloaded", "downloaded again"):
        r = timed(f"the cable schedule, {turn}", tool, ["export_rack", {"kind": "cable schedule"}])
        if r["out"]["error"]:
            bad.append(f"the cable schedule, {turn}: {r['out']['text'][:160]!r}")
    r = timed("a redraw after one cable's end is moved",
              "() => window.__rack.apply({op: 'cable.update', id: 'c1', a: {item: 'i1', path: 'port-30', view: 'front'}})", need_draw=True)
    if (r["out"] or {}).get("error"):
        bad.append(f"the edit was refused, so its redraw was not measured: {r['out']['error']}")
    # ...and a call made after the edit reads nothing again either: the redraw's reading is the rack's
    # ...and a call made after the edit: the redraw's reading is the rack's, and the kit is asked of the rack it decided
    timed("describe_rack after the edit", tool, ["describe_rack", {}])
    for what, (reads, per_cable) in SPEED_BUDGETS.items():
        got = cost[what]
        if got["reads"] > reads:
            bad.append(f"{what}: the routes were read {got['reads']} times; at most {reads}")
        if got["lays"] > per_cable * n:
            bad.append(f"{what}: the kit read the inputs of {got['lays']:g} cables, {got['lays'] / n:.2f} for each of the rack's {n}; at most {per_cable:g} each")
    for what, of, most in SPEED_RATIOS:
        if took_ms[what] > most * took_ms[of]:
            bad.append(f"{what} took {took_ms[what] / 1000:.2f} s, {took_ms[what] / took_ms[of]:.2f} times {of} ({took_ms[of] / 1000:.2f} s); at most {most:g} times")
    print("          " + "; ".join(f"{k} {v / 1000:.2f} s" for k, v in took_ms.items()), flush=True)
    print("          " + "; ".join(f"{k} {c['reads']} reads, {c['lays'] / n:.2f} per cable" for k, c in cost.items()), flush=True)
    return bad


# THE WARNINGS, ONE SECTION THAT OPENS (portrayal-site#192, cable-panel.js warningsSection). Every route warning stood
# above the cable list, a sentence each, and a rack with dozens of tight bends had its bundles and cables pushed out of
# sight. They are one row above the tree now, "Warnings (N)", closed until the reader opens it.
WARNINGS_JS = """() => {
  const sec = document.querySelector('#cableList [data-warnings]'), head = document.getElementById('warningsToggle');
  const first = document.querySelector('#cableList [role="tree"] > li'), side = document.getElementById('side');
  const box = el => { const r = el.getBoundingClientRect(); return {top: r.top, bottom: r.bottom, h: r.height}; };
  return {
    there: !!sec, n: sec ? +sec.dataset.count : 0, line: head?.textContent ?? null, open: head?.getAttribute('aria-expanded') === 'true',
    colour: head ? getComputedStyle(head).color : null, ink: getComputedStyle(document.querySelector('#cableList h3')).color,
    head: head ? box(head) : null, section: sec ? box(sec) : null,
    firstRow: first ? {...box(first), id: first.id, inView: box(first).top >= side.getBoundingClientRect().top && box(first).top < Math.min(innerHeight, side.getBoundingClientRect().bottom)} : null,
    kinds: [...document.querySelectorAll('#cableList [data-warning-kind]')].map(k => ({kind: k.dataset.warningKind, count: +k.dataset.count,
      title: k.querySelector('.rk-warnings-row, .rk-warnings-title').textContent, folds: !!k.querySelector('.rk-warnings-row'),
      open: !k.querySelector('.rk-warnings-list').hidden, rows: k.querySelectorAll('[data-warning-row]').length,
      picks: [...k.querySelectorAll('[data-warning-pick]')].map(b => b.dataset.warningPick),
      texts: [...k.querySelectorAll('[data-route-warning], [data-warning-text]')].map(p => p.textContent)})),
    laidOut: [...document.querySelectorAll('#cableList [data-warnings] p')].filter(p => p.getClientRects().length).length,
    outside: [...document.querySelectorAll('#cableList [data-route-warning]')].filter(p => !p.closest('[data-warnings]')).length,
    bends: (window.__rack.bends() ?? []).map(f => [f.cable, f.text]),
    rowWarnings: [...document.querySelectorAll('#cableList [role="tree"] :is([data-loose], [data-warning], [data-spare-short])')].map(x => x.textContent),
    pinned: [...document.querySelectorAll('#cableList [data-cable-row][aria-pressed="true"]')].map(b => b.dataset.cableRow),
    stored: localStorage.getItem('portrayal.rack.tree'),
  };
}"""


def warnings_fixture():
    """The cable-lay rack with warnings of three kinds: an AOC between its leaves (tight bends), seven fibre cords
    said to be copper (mismatches), and two cords into cages whose optics are taken out (loose ends)."""
    lay = json.loads(CABLE_LAY_FIXTURE.read_text())
    lay.pop("_note", None)
    rack = aoc_between_the_leaves(lay)
    for c in rack["cables"]:
        if c["id"] in ("c2", "c3", "c4", "c5", "c6", "c7", "c8"):
            c["media"] = "cat6a"
    leaf_b = next(i for i in rack["items"] if i["id"] == "i3")
    leaf_b["swaps"] = {k: v for k, v in leaf_b["swaps"].items() if k not in ("port-55", "port-56")}
    return {"format": "portrayal-rack", "version": 4, "id": "doc-warnings", "racks": [{**rack, "name": "Warnings"}]}


@extra("rack.html: the warnings are one section that opens, above the cable tree - with warnings of three kinds it is one row, \"Warnings (N)\" in the warning colour, closed, N the findings (a cable with several tight corners is one), no warning is laid out and the tree's first bundle row is in view without scrolling; opened, each kind has its title and count and a kind of more than five opens on its own, every sentence is the kit's or the row's own, once; a finding pins its cable; what is open survives a redraw and a reload and does not open by itself; N follows an edit that clears a warning; a rack with none has no section (#192)")
def check_rack_warnings_section(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1280, "height": 720})

    def settled(n):
        page.wait_for_function(READING_SETTLED, arg=n, timeout=READY_MS)
        page.wait_for_timeout(150)

    open_fixture(page, base, warnings_fixture())
    settled(0)
    # a bundle, so the tree has a bundle row to keep in view
    n = page.evaluate("() => window.__rack.drawn()")
    r = page.evaluate("() => window.__rack.bundleCommand({op: 'bundle.create', cables: ['c10', 'c11'], label: 'pair'})")
    if r.get("error"):
        bad.append(f"the bundle was refused: {r['error']}")
    settled(n)
    st = page.evaluate(WARNINGS_JS)
    if not st["there"]:
        return bad + ["a rack with tight bends, loose ends and mismatches has no Warnings section"]
    bent = list(dict.fromkeys(c for c, _ in st["bends"]))
    by = {k["kind"]: k for k in st["kinds"]}
    if not {"bends", "loose", "mismatch"} <= set(by):
        return bad + [f"the fixture gives warnings of {sorted(by)}; the check needs tight bends, loose ends and mismatches"]
    want_n = sum(k["rows"] for k in st["kinds"])
    if st["n"] != want_n or st["line"] != f"Warnings ({want_n})":
        bad.append(f"the row reads {st['line']!r} for {st['n']}; expected 'Warnings ({want_n})', the findings of every kind")
    if by["bends"]["count"] != len(bent):
        bad.append(f"tight bends count {by['bends']['count']} for {len(st['bends'])} corners on {len(bent)} cables; expected one finding a cable")
    if by["mismatch"]["count"] <= 5:
        bad.append(f"the fixture gives {by['mismatch']['count']} mismatches; the check needs a kind of more than five")
    if st["open"] or st["laidOut"]:
        bad.append(f"the section starts {'open' if st['open'] else 'closed'} with {st['laidOut']} sentences laid out; expected closed and none")
    if st["outside"]:
        bad.append(f"{st['outside']} route warnings still stand outside the section, above the tree")
    if st["colour"] == st["ink"]:
        bad.append(f"the row is not in the warning colour: {st['colour']}")
    if st["section"]["h"] > 40:
        bad.append(f"closed, the section is {st['section']['h']:.0f} px tall; expected one line")
    if not st["firstRow"] or not st["firstRow"]["id"].startswith("bundleItem-") or not st["firstRow"]["inView"]:
        bad.append(f"the tree's first bundle row is not in view without scrolling at 1280 by 720: {st['firstRow']}")
    if not st["rowWarnings"]:
        bad.append("the cables' own rows no longer say their loose ends and mismatches")
    # opened with the keyboard: the kinds, their counts, and every sentence once
    page.focus("#warningsToggle")
    page.keyboard.press("Enter")
    st = page.evaluate(WARNINGS_JS)
    by = {k["kind"]: k for k in st["kinds"]}
    if not st["open"]:
        bad.append("Enter on the row did not open the section")
    for kind, title in (("bends", "Tight bends"), ("loose", "Loose ends"), ("mismatch", "Media mismatches")):
        k = by[kind]
        if k["title"] != f"{title} ({k['count']})" or k["rows"] != k["count"]:
            bad.append(f"the kind {kind} reads {k['title']!r} over {k['rows']} findings; expected '{title} ({k['count']})'")
        if k["folds"] != (k["count"] > 5) or k["open"] != (k["count"] <= 5):
            bad.append(f"the kind {kind}, of {k['count']}, {'is' if k['folds'] else 'is not'} a row that opens and is {'open' if k['open'] else 'closed'}; a kind of more than five opens on its own, and starts closed")
    if by["bends"]["texts"] != [t for _, t in st["bends"]]:
        bad.append("the tight bends listed are not the kit's sentences, each once and in its order")
    own = sorted(by["loose"]["texts"] + by["mismatch"]["texts"])
    if own != sorted(st["rowWarnings"]):
        bad.append(f"the loose ends and mismatches listed are not the sentences the cables' own rows say: {own} against {sorted(st['rowWarnings'])}")
    page.click("#warningKind-mismatch")
    if not next(k for k in page.evaluate(WARNINGS_JS)["kinds"] if k["kind"] == "mismatch")["open"]:
        bad.append("a click on Media mismatches did not open it")
    # a finding pins its cable, as its row in the tree does
    pick = by["mismatch"]["picks"][0]
    n = page.evaluate("() => window.__rack.drawn()")
    page.click(f'[data-warning-kind="mismatch"] [data-warning-pick="{pick}"]')
    settled(n)
    st = page.evaluate(WARNINGS_JS)
    if st["pinned"] != [pick.split(" ")[1]]:
        bad.append(f"a click on the finding {pick} pinned {st['pinned']}")
    if not st["open"]:
        bad.append("the section closed when the panel was drawn again for the pin")
    # ...and what is open is the reader's, kept with the tree's rows: it survives a reload
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    settled(0)
    st = page.evaluate(WARNINGS_JS)
    kinds = {k["kind"]: k for k in st["kinds"]}
    if not st["there"] or not st["open"] or not kinds.get("mismatch", {}).get("open"):
        bad.append(f"after a reload the section is {'open' if st.get('open') else 'closed or gone'} and Media mismatches {'open' if kinds.get('mismatch', {}).get('open') else 'closed'}; expected both as the reader left them")
    # N FOLLOWS THE RACK: a mismatch put right is one finding fewer, and nothing opens or closes for it
    before = st["n"]
    n = page.evaluate("() => window.__rack.drawn()")
    page.evaluate("() => window.__rack.apply({op: 'cable.update', id: 'c2', media: 'om4'})")
    settled(n)
    st = page.evaluate(WARNINGS_JS)
    left = next((k["count"] for k in st["kinds"] if k["kind"] == "mismatch"), 0)
    if left != by["mismatch"]["count"] - 1 or st["line"] != f"Warnings ({st['n']})" or st["n"] != sum(k["rows"] for k in st["kinds"]):
        bad.append(f"after a mismatch was put right the row reads {st['line']!r} with {left} mismatches (it read Warnings ({before}) with {by['mismatch']['count']})")
    # closed by the reader, a new warning does not open it
    page.click("#warningsToggle")
    n = page.evaluate("() => window.__rack.drawn()")
    page.evaluate("() => window.__rack.apply({op: 'cable.update', id: 'c2', media: 'cat6a'})")
    settled(n)
    st = page.evaluate(WARNINGS_JS)
    if st["open"] or st["laidOut"]:
        bad.append("a warning that appeared opened the section the reader had closed")
    if next((k["count"] for k in st["kinds"] if k["kind"] == "mismatch"), 0) != by["mismatch"]["count"]:
        bad.append("the count did not follow the warning that appeared")
    # a rack with nothing to warn of has no section
    n = page.evaluate("() => window.__rack.drawn()")
    lay = json.loads(CABLE_LAY_FIXTURE.read_text())
    lay.pop("_note", None)
    page.evaluate("r => window.__rack.replaceRack(r)", lay)
    settled(n)
    st = page.evaluate(WARNINGS_JS)
    if st["there"] or st["outside"]:
        bad.append(f"the cable-lay rack, which has no warning, shows a Warnings section ({st['line']!r})")
    return bad


# THE FS MANAGERS' PATHWAYS, AS A ROUTE READS THEM (portrayal-site#130,
# Portrayal #868). Each CMH / USCMH placed alone: every guide and pass the
# catalogue indexes on its front and rear is a guide routeFacts finds on that
# face, and every ring among them has the opening its component declares. Then
# a cable through the CMH-4DRB1U's guide-1 is fill-checked there: before #868
# its rings were found only by data-group="guides", with no opening, and fill
# skipped them.
@extra("rack.html: every FS horizontal manager's indexed rings, ducts and passes are route guides, rings with their openings, and a cable through a CMH-4DRB1U ring is fill-checked (#130)")
def check_rack_fs_manager_guides(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    got = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js');
      const K = await import('/vendor/rack/cable-rules.js'), R = await import('/site/rack/route-context.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices, chassisOf = ref => cat[ref];
      const out = {managers: {}};
      for (const ref of Object.keys(cat).filter(n => /^(us)?cmh-/.test(n)).sort()) {
        let r = M.newRack({name: ref});
        ({rack: r} = M.withItem(r, {ref, cfg: cat[ref].default, ru: 10}));
        const rf = await R.routeFacts(r, chassisOf);
        const want = [];
        for (const key of ['guides', 'passes'])
          for (const [view, ids] of Object.entries(cat[ref][key] || {}))
            // the route context reads the front and rear faces, as the kit reads guides; the side views' passes
            // (the CMH-4DRB1U's end holes, exported since Portrayal #1066) are pathways the kit lists, not guides it draws
            if (!['top', 'left', 'right'].includes(view)) for (const id of ids) want.push(`${view}|${id}`);
        out.managers[ref] = {complete: rf.complete, want: want.sort(),
          got: rf.ctx.guidesOf('i1').map(g => ({key: `${g.face}|${g.via}`, kind: g.kind, aperture: g.aperture}))};
      }
      let r = M.newRack({name: 'Ring fill'});
      ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 20, label: 'leaf-1', swaps: {'port-1': 'generic/qsfp-lc@2'}}));
      ({rack: r} = M.withItem(r, {ref: 'cmh-4drb1u', cfg: cat['cmh-4drb1u'].default, ru: 21, label: 'mgr-1'}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-1ufce', cfg: cat['fhd-1ufce'].default, ru: 30, label: 'pp-1', swaps: {'bay-1': 'fs/fhd-splice-12-lc@3'}}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i3', path: 'bay-1/module/lc1', view: 'front'}, media: 'os2'}));
      r = {...r, cables: r.cables.map(c => ({...c, route: [{item: 'i2', via: 'guide-1'}, {lane: 'left-front', ru: 25}], routeEdited: true}))};
      const rf = await R.routeFacts(r, chassisOf);
      out.fill = rf.fill;
      out.rings = rf.ringFindings;
      return out;
    }""")
    ms = got["managers"]
    if len(ms) < 23:
        bad.append(f"catalogue: {len(ms)} FS horizontal managers, expected the 23 on main")
    rings = 0
    for ref, m in ms.items():
        keys = sorted(g["key"] for g in m["got"])
        missing = [k for k in m["want"] if k not in keys]
        if not m["complete"] or missing:
            bad.append(f"{ref}: the route context does not find {missing} (indexed {m['want']}; faces read: {m['complete']})")
        blind = [g["key"] for g in m["got"] if g["kind"] == "ring" and not g["aperture"]]
        rings += sum(1 for g in m["got"] if g["kind"] == "ring")
        if blind:
            bad.append(f"{ref}: rings with no opening, so never fill-checked: {blind}")
    if rings < 20:
        bad.append(f"only {rings} rings across the FS managers - the check measured too little")
    four = [g for g in ms.get("cmh-4drb1u", {}).get("got", []) if g["kind"] == "ring"]
    if sorted((g["key"], json.dumps(g["aperture"], sort_keys=True)) for g in four) != \
            [(f"front|guide-{i}", '{"h": 74.8, "w": 37.2}') for i in range(1, 5)]:
        bad.append(f"cmh-4drb1u: its rings are not guide-1..4 at 37.2 x 74.8 mm: {four}")
    if got["rings"]:
        bad.append(f"the test route does not pass guide-1 cleanly: {got['rings']}")
    f = [x for x in got["fill"] if x["item"] == "i2" and x["via"] == "guide-1"]
    want_pct = round(math.pi * 1.5 ** 2 / (0.4 * 37.2 * 74.8) * 100)
    if len(f) != 1 or f[0]["cables"] != ["c1"] or f[0]["percent"] != want_pct:
        bad.append(f"fill: the cable through the CMH-4DRB1U's guide-1 is not fill-checked against its 37.2 x 74.8 mm"
                   f" opening ({want_pct}%): {got['fill']}")
    return bad


@extra("rack.html: a cable through a horizontal manager's pass-throughs (duct > pass-through-1 > right-rear U34 > pass-through-2 > duct on a CMH-SFD1U) is drawn in the Rear view as well as the Front view (S-0037)")
def check_rack_pass_through_rear(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    built = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Pass'});
      ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 20, label: 'leaf-1', swaps: {'port-1': 'generic/qsfp-lc@2'}}));
      ({rack: r} = M.withItem(r, {ref: 'cmh-sfd1u', cfg: cat['cmh-sfd1u'].default, ru: 30, label: 'mgr-1'}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-1ufce', cfg: cat['fhd-1ufce'].default, ru: 38, label: 'pp-1', swaps: {'bay-1': 'fs/fhd-splice-12-lc@3'}}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i3', path: 'bay-1/module/lc1', view: 'front'}, media: 'os2'}));
      const route = [{item: 'i2', via: 'duct'}, {item: 'i2', via: 'pass-through-1'}, {lane: 'right-rear', ru: 34},
                     {item: 'i2', via: 'pass-through-2'}, {item: 'i2', via: 'duct'}];
      return {...r, cables: r.cables.map(c => ({...c, route, routeEdited: true}))};
    }""")
    page.evaluate("r => window.__rack.replaceRack(r)", built)
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id]').length >= 1", timeout=READY_MS)
    # The route is the one written: the kit did not drop a stop.
    routes = dict(page.evaluate("() => window.__rack.routes()"))
    if [w.get("via") or w.get("lane") for w in routes.get("c1", [])] != ["duct", "pass-through-1", "right-rear", "pass-through-2", "duct"]:
        return [f"routes: c1 is not duct > pass-through-1 > right-rear > pass-through-2 > duct: {routes.get('c1')}"]
    # A cable is drawn in a pane as a g of paths with length; both panes, both views of the rack.
    probe = """pane => {
      const s = document.querySelector(`#pane${pane} svg`);
      const g = s && s.querySelector('[data-cables] [data-cable-id="c1"]');
      if (!g) return {drawn: false};
      const len = [...g.querySelectorAll('path')].reduce((a, p) => a + (p.dataset.leader ? 0 : p.getTotalLength()), 0);
      const b = g.getBBox();
      return {drawn: true, len, w: b.width, h: b.height};
    }"""
    for pane in ("Front", "Rear"):
        got = page.evaluate(probe, pane)
        if not got["drawn"] or not got["len"] > 20:
            bad.append(f"{pane} view: the cable through the pass-throughs is not drawn ({got})")
    # On the rear pane it runs from the manager's pass-throughs (U30) up to the
    # lane at U34, whose hairpin the cable's bend radius eases a little short.
    rear = page.evaluate("""() => {
      const s = document.querySelector('#paneRear svg'), inv = s.getScreenCTM().inverse();
      const g = s.querySelector('[data-cables] [data-cable-id="c1"]');
      if (!g) return null;
      const m = inv.multiply(g.getScreenCTM());
      const b = g.getBBox(), top = new DOMPoint(0, b.y).matrixTransform(m).y, bottom = new DOMPoint(0, b.y + b.height).matrixTransform(m).y;
      const u = n => { const r = s.querySelector(`[data-u="${n}"]`); const q = r && r.getBBox(); return q && q.y + q.height / 2; };
      return {top, bottom, u30: u(30), u34: u(34)};
    }""")
    if rear and rear["u30"] is not None and rear["u34"] is not None:
        if rear["top"] > rear["u34"] + 60 or rear["bottom"] < rear["u30"] - 20:
            bad.append(f"Rear view: the cable is not drawn from U30 up to the lane at U34 ({rear})")
    return bad


# SPARE IN A FINGER DUCT AND A VERTICAL MANAGER IN A ROUTE (kit 0.35.0,
# Portrayal #1065; site/rack/spare-loops.js). Two switches at U30 and U26, a
# CMH-BS-SFDS1U at U28, a CMH-6DR1U ring manager at U24, a CMV-SFD42U9W
# beside the right front upright from U1, and two cords between the switches:
# c1 through the horizontal duct, c2 down the right front lane, which runs
# through the vertical's duct. The agent's edit_rack stores and is refused.
SPARE_DUCTS_RACK_JS = """async () => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.withFrame(M.newRack({name: 'Spare in ducts'}), {heightRU: 45});
  const optic = {'port-1': 'generic/qsfp-lc@2', 'port-2': 'generic/qsfp-lc@2'};
  ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 30, label: 'leaf-1', swaps: optic}));
  ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 26, label: 'leaf-2', swaps: optic}));
  ({rack: r} = M.withItem(r, {ref: 'cmh-bs-sfds1u', cfg: cat['cmh-bs-sfds1u'].default, ru: 28, label: 'hm-1'}));
  ({rack: r} = M.withItem(r, {ref: 'cmh-6dr1u', cfg: cat['cmh-6dr1u'].default, ru: 24, label: 'rings-1'}));
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i2', path: 'port-1', view: 'front'}, media: 'os2'}));
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-2', view: 'front'}, b: {item: 'i2', path: 'port-2', view: 'front'}, media: 'os2'}));
  return r;
}"""


def open_spare_ducts(page, base):
    """The spare-ducts rack, open in Front / Rear, with the agent's tools and the vertical placed; [] or what failed."""
    page.add_init_script(STAND_IN_MODEL_CONTEXT)
    page.set_viewport_size({"width": 1600, "height": 1000})
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.evaluate("r => window.__rack.replaceRack(r)", page.evaluate(SPARE_DUCTS_RACK_JS))
    wait_fn(page, "spare ducts: agent tools registered", "() => window.__tools && window.__tools.edit_rack && window.__tools.inspect")
    res = agent_call(page, "edit_rack", {"commands": [
        {"op": "zerou.place", "ref": "cmv-sfd42u9w", "at": "right-front", "ru": 1, "label": "VCM"},
        {"op": "cable.route", "id": "c1", "route": [{"item": "i3", "via": "duct"}]},
        {"op": "cable.route", "id": "c2", "route": [{"lane": "right-front", "ru": 30}, {"lane": "right-front", "ru": 26}]}]})
    if res.get("isError"):
        return [f"setup: {res['content'][0]['text']}"]
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id]').length === 2", timeout=READY_MS)
    return []


# A loop on a pane, as plain data: its cable, its centre in the pane's user space and its box.
SPARE_LOOPS_JS = """sel => [...document.querySelectorAll(`${sel} [data-spare-loops] [data-spare-loop]`)].map(g => {
  const s = g.ownerSVGElement, m = s.getScreenCTM().inverse().multiply(g.getScreenCTM()), b = g.getBBox();
  const c = new DOMPoint(b.x + b.width / 2, b.y + b.height / 2).matrixTransform(m);
  return {loop: g.dataset.spareLoop, members: g.dataset.members, run: g.dataset.spareRun, x: c.x, y: c.y, w: b.width, h: b.height,
          title: g.querySelector('title')?.textContent ?? ''};
})"""
# A part's box on a pane, in its user space.
PART_BOX_JS = """([pane, sel]) => { const s = document.querySelector(`#pane${pane} svg`), e = s && s.querySelector(sel);
  if (!e) return null;
  const m = s.getScreenCTM().inverse().multiply(e.getScreenCTM()), b = e.getBBox();
  const p = new DOMPoint(b.x, b.y).matrixTransform(m), q = new DOMPoint(b.x + b.width, b.y + b.height).matrixTransform(m);
  return {x0: Math.min(p.x, q.x), x1: Math.max(p.x, q.x), y0: Math.min(p.y, q.y), y1: Math.max(p.y, q.y)}; }"""


@extra("rack.html: an agent stores a cord's spare in a horizontal manager's finger duct its route uses; the loop is drawn in the duct in Front, in Left / Right and in 3D, the agent's text says it, and spare in a ring is refused with where it can go (kit 0.35.0, Portrayal #1065)")
def check_rack_spare_duct_loop(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    failed = open_spare_ducts(page, base)
    if failed:
        return bad + failed
    # A ring holds no spare: refused, with where the spare can go.
    ring = agent_call(page, "edit_rack", {"commands": [{"op": "cable.slack", "id": "c1", "at": {"item": "i4", "via": "guide-1"}}]})
    said = ring["content"][0]["text"]
    if not ring.get("isError") or "holds no spare" not in said or "can go in" not in said or "hm-1 duct" not in said:
        bad.append(f"a ring: spare in rings-1 guide-1 is not refused with where the spare can go: {said!r}")
    ok = agent_call(page, "edit_rack", {"commands": [{"op": "cable.slack", "id": "c1", "at": {"item": "i3", "via": "duct"}}]})
    if ok.get("isError"):
        return bad + [f"the duct: storing c1's spare in hm-1 duct was refused: {ok['content'][0]['text']}"]
    page.wait_for_function("() => (window.__rack.spareLoops() || []).length === 1", timeout=READY_MS)
    loop = page.evaluate("() => window.__rack.spareLoops()[0]")
    if (loop["cable"], loop["item"], loop["via"], loop["kind"], loop["run"]) != ("c1", "i3", "duct", "duct", "x"):
        bad.append(f"the loop: not c1's in i3 duct, a duct running across the rack: {loop}")
    # Front: one loop, inside the manager's drawing.
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-spare-loops] [data-spare-loop]').length === 1", timeout=READY_MS)
    front = page.evaluate(SPARE_LOOPS_JS, "#paneFront svg")
    mgr = page.evaluate(PART_BOX_JS, ["Front", '[data-item-id="i3"][data-panel]'])
    f = front[0]
    if not mgr or not (mgr["x0"] <= f["x"] <= mgr["x1"] and mgr["y0"] - 2 <= f["y"] <= mgr["y1"] + 2):
        bad.append(f"Front: the loop at ({f['x']:.1f}, {f['y']:.1f}) is not in hm-1's drawing {mgr}")
    if not (f["w"] > f["h"]):
        bad.append(f"Front: the loop does not lie along the duct across the rack ({f['w']:.1f} wide, {f['h']:.1f} high)")
    # THE LOOP GROWS WITH ITS SPARE (S-0042): long radius 22 mm x clamp(0.5 + 0.5 m, 0.6, 1.5); the box is two turns 5 mm apart.
    scale = min(1.5, max(0.6, 0.5 + 0.5 * loop["metres"]))
    if abs(f["w"] - (2 * 22 * scale + 5)) > 1.5:
        bad.append(f"Front: a loop of {loop['metres']:.2f} m is {f['w']:.1f} wide, not {2 * 22 * scale + 5:.1f}")
    if "c1:" not in f["title"] or "hm-1 duct" not in f["title"]:
        bad.append(f"Front: the loop's title does not name the cable and the duct: {f['title']!r}")
    if page.evaluate(SPARE_LOOPS_JS, "#paneRear svg"):
        bad.append("Rear: a loop in a front duct is drawn on the rear pane")
    # The agent's text.
    txt = agent_call(page, "inspect", {"id": "c1"})["content"][0]["text"]
    # c1 is fibre and hm-1 states its count for cat6, which kit 0.39.0 does not count a fibre cord against
    for want in ("as a loop in i3 duct (a duct whose stated capacity is for cat6 cables, which os2 is not counted against)", "the stored loop is drawn", "Spare can go in: i3 duct"):
        if want not in txt:
            bad.append(f"inspect c1: no {want!r} in {txt!r}")
    if "listed, not drawn" in txt:
        bad.append(f"inspect c1: still says the spare is listed, not drawn: {txt!r}")
    item = agent_call(page, "inspect", {"id": "i3"})["content"][0]["text"]
    if "Pathways: duct duct (holds spare)" not in item:
        bad.append(f"inspect i3: its pathways are not said with which hold spare: {item!r}")
    # Left / Right: a loop on each side pane, at the duct's height.
    page.click('#view2d [data-view="sides"]')
    page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
    page.wait_for_function("() => [...document.querySelectorAll('#panes svg[data-side]')].every(s => s.querySelectorAll('[data-spare-loops] [data-spare-loop]').length === 1)", timeout=READY_MS)
    for side in ("left", "right"):
        got = page.evaluate(SPARE_LOOPS_JS, f'#panes svg[data-side][data-pane="{side}"]')
        if len(got) != 1 or got[0]["members"] != "c1":
            bad.append(f"{side.title()}: not one loop of c1: {got}")
    # 3D: one loop, named for its place, with its cable.
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "spare duct 3D", tubes=True)
    s3 = page.evaluate("""() => { const s = window.__rack.scene(), L = s?.rackCables?.loops;
      return L ? L.loops.map(g => ({name: g.name, members: g.userData.members, spare: g.userData.spare, meshes: g.children.length})) : null; }""")
    if not s3 or len(s3) != 1 or s3[0]["members"] != ["c1"] or s3[0]["meshes"] != 2:
        bad.append(f"3D: not one loop of c1, of two turns: {s3}")
    return bad


@extra("rack.html: an agent stores a cord's spare in the duct of a vertical manager beside the rack that its lane runs through; the loop is drawn up the duct beside the rack in Front, in Left / Right and in 3D, with the finding that the part states no capacity (kit 0.35.0, Portrayal #1065)")
def check_rack_spare_vertical_loop(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    failed = open_spare_ducts(page, base)
    if failed:
        return bad + failed
    ok = agent_call(page, "edit_rack", {"commands": [{"op": "cable.slack", "id": "c2", "at": {"item": "z1", "via": "duct"}}]})
    if ok.get("isError"):
        return bad + [f"the vertical: storing c2's spare in VCM duct was refused: {ok['content'][0]['text']}"]
    page.wait_for_function("() => (window.__rack.spareLoops() || []).length === 1", timeout=READY_MS)
    loop = page.evaluate("() => window.__rack.spareLoops()[0]")
    if (loop["cable"], loop["item"], loop["run"]) != ("c2", "z1", "y"):
        bad.append(f"the loop: not c2's in z1, running up the rack: {loop}")
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-spare-loops] [data-spare-loop]').length === 1", timeout=READY_MS)
    f = page.evaluate(SPARE_LOOPS_JS, "#paneFront svg")[0]
    part = page.evaluate(PART_BOX_JS, ["Front", '[data-zerou-id="z1"]'])
    u28 = page.evaluate("""() => { const r = document.querySelector('#paneFront svg [data-u="28"]'); const q = r && r.getBBox(); return q && q.y + q.height / 2; }""")
    if not part or not (part["x0"] <= f["x"] <= part["x1"]):
        bad.append(f"Front: the loop at x {f['x']:.1f} is not beside the rack in the vertical's drawing {part}")
    if u28 is not None and abs(f["y"] - u28) > 23:
        bad.append(f"Front: the loop at y {f['y']:.1f} is not at U28, the middle of c2's run from U30 to U26 ({u28:.1f})")
    if not (f["h"] > f["w"]):
        bad.append(f"Front: the loop does not lie up the duct ({f['w']:.1f} wide, {f['h']:.1f} high)")
    # The loop goes with its cable: another cable selected, it dims; its own, it stays lit.
    loop_opacity = "() => Number(getComputedStyle(document.querySelector('#paneFront svg [data-spare-loop]')).opacity)"
    page.click('#cableList [data-cable-row="c1"]')
    page.wait_for_timeout(400)
    other = page.evaluate(loop_opacity)
    page.click('#cableList [data-cable-row="c2"]')
    page.wait_for_timeout(400)
    own = page.evaluate(loop_opacity)
    if not (other < 0.5 and own == 1):
        bad.append(f"Front: the loop does not go with its cable when one is selected (another selected {other}, its own {own})")
    page.keyboard.press("Escape")
    txt = agent_call(page, "inspect", {"id": "c2"})["content"][0]["text"]
    for want in ("as a loop in z1 duct (a duct whose maker states no cable capacity)", "Spare, capacity not stated:"):
        if want not in txt:
            bad.append(f"inspect c2: no {want!r} in {txt!r}")
    z = agent_call(page, "inspect", {"id": "z1"})["content"][0]["text"]
    if "Pathways: duct duct (holds spare); pass-through pass-through-1" not in z:
        bad.append(f"inspect z1: its duct and windows are not said with which hold spare: {z!r}")
    page.click('#view2d [data-view="sides"]')
    page.wait_for_function(SIDE_DRAWN, timeout=READY_MS)
    page.wait_for_function("() => [...document.querySelectorAll('#panes svg[data-side]')].every(s => s.querySelectorAll('[data-spare-loops] [data-spare-loop]').length === 1)", timeout=READY_MS)
    for side in ("left", "right"):
        got = page.evaluate(SPARE_LOOPS_JS, f'#panes svg[data-side][data-pane="{side}"]')
        if len(got) != 1 or not (got[0]["h"] > got[0]["w"]):
            bad.append(f"{side.title()}: not one loop of c2 standing up the duct: {got}")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "spare vertical 3D", tubes=True)
    s3 = page.evaluate("""() => { const L = window.__rack.scene()?.rackCables?.loops;
      return L ? L.loops.map(g => ({members: g.userData.members, run: g.userData.spare.run})) : null; }""")
    if s3 != [{"members": ["c2"], "run": "y"}]:
        bad.append(f"3D: not one loop of c2 up the duct: {s3}")
    return bad


@extra("rack.html: the route editor offers a vertical manager's duct and windows as pick targets; a cord routed through its duct is stored as {item, via: duct}, drawn down the lane through it, and its row says so (kit 0.35.0, Portrayal #1065)")
def check_rack_route_vertical_duct(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    failed = open_spare_ducts(page, base)
    if failed:
        return bad + failed
    page.click('#cableList [data-cable-row="c1"]')
    page.click("#cableEdit")
    page.click("#routeAdd")
    page.wait_for_function("() => document.querySelector('#paneFront svg [data-pick-item=\"z1\"][data-pick-via=\"duct\"]')", timeout=READY_MS)
    picks = page.evaluate("() => [...document.querySelectorAll('#paneFront svg [data-pick-item=\"z1\"]')].map(r => r.dataset.pickVia)")
    if picks[:1] != ["duct"] or sorted(picks[1:]) != [f"pass-through-{k}" for k in range(1, 7)]:
        bad.append(f"pick: the vertical does not offer its duct and six windows: {picks}")
    # A point of the duct's target a visitor can click: not under a lane's or a window's.
    at = page.evaluate("""() => {
      const r = document.querySelector('#paneFront svg [data-pick-item="z1"][data-pick-via="duct"]'), b = r.getBoundingClientRect();
      for (let fy = 0.45; fy < 0.6; fy += 0.01) for (let fx = 0.95; fx > 0.05; fx -= 0.05) {
        const x = b.left + b.width * fx, y = b.top + b.height * fy;
        if (document.elementFromPoint(x, y) === r) return {x, y};
      }
      return null; }""")
    if not at:
        return bad + ["pick: the vertical's duct target is covered everywhere"]
    page.mouse.click(at["x"], at["y"])
    page.keyboard.press("Escape")
    stored = page.evaluate("() => window.__rack.doc().racks[0].cables.find(c => c.id === 'c1').route")
    if {"item": "z1", "via": "duct"} not in stored:
        return bad + [f"pick: the route does not name z1 duct: {stored}"]
    page.wait_for_function("() => (window.__rack.routes() || []).find(([id]) => id === 'c1')?.[1].some(w => w.lane === 'right-front')", timeout=READY_MS)
    rows = page.evaluate("() => [...document.querySelectorAll('[id^=\"routeRow-\"]')].map(r => r.textContent)")
    if not any("VCM duct" in t for t in rows):
        bad.append(f"rows: no row names VCM duct: {rows}")
    drawn = page.evaluate("""() => { const s = document.querySelector('#paneFront svg'), g = s.querySelector('[data-cables] [data-cable-id="c1"]');
      return g ? [...g.querySelectorAll('path')].reduce((a, p) => a + (p.dataset.leader ? 0 : p.getTotalLength()), 0) : 0; }""")
    if not drawn > 20:
        bad.append(f"Front: c1 through the vertical's duct is not drawn ({drawn})")
    txt = agent_call(page, "inspect", {"id": "c1"})["content"][0]["text"]
    if "VCM duct" not in txt:
        bad.append(f"inspect c1: the route does not say it runs through VCM duct: {txt!r}")
    return bad


@extra("rack.html: a route that would enter and leave a ring by one face is drawn to the face and back, in 2D and 3D, and reported (Portrayal #930)")
def check_rack_ring_doubles_back(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    # leaf-1 port-1 is at the left of the switch; its route is edited to go
    # to guide-5, at the manager's right end, and back to the left lane one U
    # up: both neighbours stand on the ring's left, so it is not passed.
    built = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.newRack({name: 'Doubles back'});
      const optic = {'port-1': 'generic/qsfp-lc@2'};
      ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 20, label: 'leaf-1', swaps: optic}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, label: 'mgr-1', on: 'i1', unit: 1}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-1ufce', cfg: cat['fhd-1ufce'].default, ru: 30, label: 'pp-1', swaps: {'bay-1': 'fs/fhd-splice-12-lc@3'}}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i3', path: 'bay-1/module/lc1', view: 'front'}, media: 'os2'}));
      r = {...r, cables: r.cables.map(c => ({...c, route: [{item: 'i2', via: 'guide-5'}, {lane: 'left-front', ru: 21}], routeEdited: true}))};
      return r;
    }""")
    page.evaluate("r => window.__rack.replaceRack(r)", built)
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id]').length === 1", timeout=READY_MS)
    page.wait_for_function("() => (window.__rack.rings()?.marks || []).length === 1", timeout=READY_MS)
    rings = page.evaluate("() => window.__rack.rings()")
    mark = dict(rings["marks"]).get("c1", [None])[0]
    if not mark or mark.get("back") is not True or mark.get("sense") != 1:
        return bad + [f"route: guide-5 is not marked as doubled back from the left (sense 1): {rings}"]
    if [(f["cable"], f["item"], f["via"]) for f in rings["findings"]] != [("c1", "i2", "guide-5")]:
        bad.append(f"findings: not one doubles-back finding for c1 at guide-5: {rings['findings']}")
    warn = page.evaluate("() => [...document.querySelectorAll('[data-route-warning]')].map(p => p.textContent)")
    if not any("ring 5" in w and "same face" in w for w in warn):
        bad.append(f"cable list: the doubled-back ring is not among the warnings: {warn}")
    half = mark["depth"] / 2
    # 2D: the path reaches guide-5's left face and goes no further right.
    geo = page.evaluate("""() => {
      const s = document.querySelector('#paneFront svg');
      const g = s.querySelector('[data-cables] [data-cable-id="c1"]');
      const end = s.querySelector('[data-item-id="i2"] [id="guide-5-end"]');
      const inv = s.getScreenCTM().inverse();
      const eb = end.getBoundingClientRect();
      const c = new DOMPoint(eb.left + eb.width / 2, eb.top + eb.height / 2).matrixTransform(inv);
      let maxX = -Infinity;
      for (const p of g.querySelectorAll('path')) {
        if (p.dataset.leader) continue;
        const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
        for (let t = 0; t <= L; t += 0.25) maxX = Math.max(maxX, new DOMPoint(p.getPointAtLength(t).x, p.getPointAtLength(t).y).matrixTransform(m).x);
      }
      return {cx: c.x, maxX};
    }""")
    # Up to the face, never past it; routed2d rounds the turn back by its
    # corner radius (4), so the stroke stops short of the vertex by up to that.
    face2d = geo["cx"] - half
    if not (face2d - 4 <= geo["maxX"] <= face2d + 0.5):
        bad.append(f"2D: the doubled-back cable reaches x {geo['maxX']:.2f}, not guide-5's left face at {face2d:.2f} (centre {geo['cx']:.2f})")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the doubled-back cable's scene", tubes=True)
    res = page.evaluate("""async () => {
      const s = window.__rack.scene(); await s.complete?.();
      const deadline = Date.now() + 20000;
      while (!(s.rackCables?.tubes ?? []).some(t => t.points?.length) && Date.now() < deadline) await new Promise(r => setTimeout(r, 200));
      const top = await s.guideAnchor({id: 'i2'}, 'guide-5');
      const pts = s.rackCables.tubes.flatMap(t => t.points);
      // the kit's `face` point: since 0.15.0 (#968) a solid ring is gone to as
      // far as its approach point before the face, the radius and CLEAR short
      const face = window.__rack.paths().c1.points.find(q => q.item === 'i2' && q.via === 'guide-5' && q.at === 'face');
      return {cx: top.position.x, face: face?.x ?? null, maxX: Math.max(...pts.map(p => p.x)), n: pts.length};
    }""")
    if not res["n"]:
        bad.append(f"3D: the cable has no tube points ({res})")
    elif res["face"] is None or abs(res["maxX"] - res["face"]) > 0.05 or not (res["face"] <= res["cx"] - half + 1e-6):
        bad.append(f"3D: the doubled-back tube reaches x {res['maxX']:.2f}, not the kit's face point {res['face']} "
                   f"short of guide-5's left face at {res['cx'] - half:.2f}")
    return bad


# THE TUBES STAY OUT OF THE METAL (Portrayal #949, kit 0.11.0, cable-lay
# design 1.4). The kit takes every route round the solid bodies and reports
# what it cannot clear; the 3D tube rounds its corners inside 30 mm of that
# path and could still cut a corner through a tray. So every routed cable's
# tube is sampled along its centre line, densely, against the kit's own solid
# boxes as the scene placed them (scene3d.js solidBoxes), and a sample
# STRICTLY inside a box fails: one on a face, or within TUBE_EPS of it, is a
# cable lying against the plate, not through it. A ring's part and a zero-U
# part are met by the TUBE (kit 0.15.0): their boxes are grown by the tube's
# radius in the scene (scene3d.js solidBoxes), so a centre line inside one is
# a tube touching the part. NOT VACUOUS: it fails when
# there is no routed tube, no box, or fewer samples than tubes times the
# per-tube count.
TUBE_EPS = 0.05     # mm: a sample this close to a face is on it
TUBE_SAMPLES = 1500
TUBES_INSIDE_JS = """async ([eps, n]) => {
  const s = window.__rack.scene(); await s.complete?.();
  const deadline = Date.now() + 60000;
  while (!(s.rackCables?.tubes ?? []).some(t => t.routed && t.mesh) && Date.now() < deadline) await new Promise(r => setTimeout(r, 200));
  const boxes = s.rackCables?.boxes ?? [];
  const tubes = (s.rackCables?.tubes ?? []).filter(t => t.routed && t.mesh);
  const hits = new Map();
  let samples = 0;
  for (const t of tubes) {
    const main = t.mesh.children.find(m => m.geometry?.parameters?.path);
    if (!main) continue;
    for (const p of main.geometry.parameters.path.getSpacedPoints(n)) {
      samples++;
      for (const b of boxes) {
        const {min, max} = b.box;
        if (p.x > min.x + eps && p.x < max.x - eps && p.y > min.y + eps && p.y < max.y - eps && p.z > min.z + eps && p.z < max.z - eps) {
          const k = `${t.link.id}|${b.ref}|${b.part}`;
          if (!hits.has(k)) hits.set(k, {cable: t.link.id, ref: b.ref, part: b.part, at: [p.x, p.y, p.z].map(v => Math.round(v * 10) / 10)});
        }
      }
    }
  }
  return {tubes: tubes.length, boxes: boxes.length, samples, parts: [...new Set(boxes.map(b => `${b.ref}|${b.part}`))], hits: [...hits.values()]};
}"""


def tubes_inside(page, want_tubes, want_parts=()):
    """Every routed tube sampled against the kit's solid boxes: problems, or []."""
    got = page.evaluate(TUBES_INSIDE_JS, [TUBE_EPS, TUBE_SAMPLES])
    bad = []
    if got["tubes"] < want_tubes or got["samples"] < want_tubes * (TUBE_SAMPLES + 1) or not got["boxes"]:
        bad.append(f"3D: sampled {got['tubes']} routed tubes ({got['samples']} points) against {got['boxes']} solid boxes, "
                   f"expected {want_tubes} tubes and at least one box")
    for part in want_parts:
        if part not in got["parts"]:
            bad.append(f"3D: the solid {part} is not among the scene's boxes: {got['parts']}")
    for h in got["hits"][:12]:
        bad.append(f"3D: cable {h['cable']}'s tube passes inside {h['ref']} {h['part']} at {h['at']}")
    return bad


def load_rack_3d_ready(page, base, rack):
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.evaluate("r => window.__rack.replaceRack(r)", rack)
    n = len(rack["cables"])
    page.wait_for_function("n => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id], #paneRear svg [data-cables] [data-cable-id]').length >= n",
                           arg=n, timeout=READY_MS)
    page.wait_for_function("n => Object.keys(window.__rack.paths() || {}).length === n", arg=n, timeout=READY_MS)


CABLE_LAY_FIXTURE = HERE / "tests" / "rack" / "fixtures" / "cable-lay-rack.json"

# How near a cable's drawn line passes each of its lead points (rack mm in,
# pane mm out): {cable: {off: each lead point's distance from its stroke, gap:
# how far each of its arcs stands inside its vertex}}.
LEAD_2D_JS = """async leads => {
  const {RU, OPENING} = await import('/vendor/rack/rails.js');
  const svg = document.querySelector('#paneFront svg'), H = window.__rack.doc().racks[0].frame.heightRU * RU;
  const inv = svg.getScreenCTM().inverse(), out = {};
  for (const [id, qs] of Object.entries(leads)) {
    const g = svg.querySelector(`[data-cables] [data-cable][data-cable-id="${id}"]`);
    if (!g) { out[id] = null; continue; }
    const pts = [];
    for (const p of g.querySelectorAll('path')) {
      const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
      for (let t = 0; t <= L; t += 0.2) { const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m); pts.push([w.x, w.y]); }
    }
    // how far each corner's own arc stands inside its vertex: R (sec(theta/2) - 1)
    // for an arc of radius R whose chord is c, theta = 2 asin(c / 2R)
    const gap = [];
    for (const p of g.querySelectorAll('path')) {
      const d = p.getAttribute('d') || '', re = /(?:^|[ML])([\\d.-]+) ([\\d.-]+) A([\\d.]+) [\\d.]+ 0 0 [01] ([\\d.-]+) ([\\d.-]+)/g;
      let m;
      while ((m = re.exec(d))) {
        const r = +m[3], c = Math.hypot(m[4] - m[1], m[5] - m[2]), th = 2 * Math.asin(Math.min(1, c / (2 * r)));
        gap.push(r * (1 / Math.cos(th / 2) - 1));
      }
    }
    out[id] = pts.length ? {gap, off: qs.map(q => Math.min(...pts.map(w => Math.hypot(w[0] - (OPENING / 2 + q.x), w[1] - (H - q.y)))))} : null;
  }
  return out;
}"""
# The same in the scene: the furthest of a cable's lead points from the nearest vertex of its tube's polyline.
LEAD_3D_JS = """leads => {
  const s = window.__rack.scene(), faceZ = s.metrics().faceZ, out = {};
  for (const [id, qs] of Object.entries(leads)) {
    const t = (s.rackCables?.tubes ?? []).find(x => x.link.id === id && x.routed);
    out[id] = t?.points?.length ? Math.max(...qs.map(q => Math.min(...t.points.map(v => Math.hypot(v.x - q.x, v.y - q.y, v.z - (faceZ + q.z)))))) : null;
  }
  return out;
}"""


@extra("rack.html: cable lay - on the two-leaf rack with an FHD-CMP5DR lacer, every automatic cord goes through rings 3 to 5 on their sills at the kit's lengths (upper leaf 0.48-0.55 m, lower 0.57-0.65 m; c2, c3, c4 and c7 are 0.5 m cords, the rest 1 m) with no lane, no ring, no body and no bend findings, and no 3D tube passes through the tray or a ring's part")
def check_rack_cable_lay(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    load_rack_3d_ready(page, base, rack)
    paths = page.evaluate("() => window.__rack.paths()")
    routes = dict(page.evaluate("() => window.__rack.routes()"))
    ring_found = page.evaluate("() => window.__rack.rings().findings")
    bodies = page.evaluate("() => window.__rack.bodies()")
    if len(paths) != 16 or any(p is None for p in paths.values()):
        return bad + [f"routes: not all 16 cords measured: {sorted(paths)}"]
    for cid, p in sorted(paths.items(), key=lambda kv: int(kv[0][1:])):
        ways = routes.get(cid, [])
        if any("lane" in w for w in ways):
            bad.append(f"{cid}: the automatic route goes out to a lane and back: {ways}")
        vias = [(g["item"], g["via"], g["passed"]) for g in p["rings"]]
        if not vias or any(i != "i4" or v not in ("guide-3", "guide-4", "guide-5") or not ok for i, v, ok in vias):
            bad.append(f"{cid}: not through rings 3, 4 or 5 of the lacer, each passed: {vias}")
        # the kit's lengths (0.18.0): from each plug's reach (an optic's 32.5 mm,
        # the panel's duplex plug 13.7), resting on the ring's sill, over the
        # tray's front edge for the lower leaf. Read off the kit's own output
        # on this rack: the upper leaf's cords measure 0.4883 to 0.5211 m (they
        # were 0.4970 to 0.5655 on kit 0.15.0) and the lower leaf's 0.5769 to
        # 0.6470 (0.6167 to 0.6671). Two things moved them: the end allowance is
        # per media since 0.16.0 (an LC cord adds 113.1 mm an end, not 150, so
        # each is 73.8 mm shorter), and since 0.17.0 a path leaves room for its
        # bends (each is about 10 to 104 mm longer here, by where its turns stand).
        # THE RING IS CHOSEN BY ROOM (kit 0.27.0, Portrayal #1026): c8's lead has no room to turn into ring 5, which it took
        # before, and takes ring 4: 0.5418 m where it was 0.4881, and a 1 m cord where it was 0.5 m. No other cord moved.
        lo, hi = (0.48, 0.55) if int(cid[1:]) <= 8 else (0.57, 0.65)
        if not (lo - 1e-9 <= (p["measured"] or 0) <= hi + 1e-9):
            bad.append(f"{cid}: measured {p['measured']} m, not {lo}-{hi} m")
        # ...and the stock size each rounds up to: c4 (0.4936 m) and c8 (0.4883,
        # which was 0.5158 and a 1 m cord on kit 0.15.0) are 0.5 m cords; every
        # other cord is past the 0.5 m break and is a 1 m cord.
        # THE STOCK BREAK (kit 0.22.0, Portrayal #983): a cord up to 10 mm short of full end play is still chosen,
        # so c2 (0.5015 m), c3 (0.5050) and c7 (0.5017), each within 10 mm over the break, drop from 1 m to 0.5 m.
        # No measured length moved. Held as the rule too: a 0.5 m cord exactly where the measure is at most 0.51 m.
        want = 0.5 if cid in ("c2", "c3", "c4", "c7") else 1
        if p["value"] != want or (p["value"] == 0.5) != ((p["measured"] or 9) <= 0.51 + 1e-9):
            bad.append(f"{cid}: a {p['value']} m cord for {p['measured']} m measured, not {want} m")
        if not any(r.get("kind") == "ring" and r.get("item") == "i4" for r in p.get("rests") or []):
            bad.append(f"{cid}: the kit does not rest it on a ring's sill: {p.get('rests')}")
        if p["crossings"]:
            bad.append(f"{cid}: its path still crosses a body: {p['crossings']}")
    if ring_found:
        bad.append(f"ring findings: {ring_found}")
    if bodies:
        bad.append(f"crosses-body findings: {bodies}")
    # the kit finds room for every bend here (kit 0.17.0), so nothing is said or ringed
    bends = page.evaluate("() => window.__rack.bends()")
    if bends:
        bad.append(f"tight-bend findings: {[b['text'] for b in bends]}")
    warn = page.evaluate("() => [...document.querySelectorAll('[data-route-warning]')].map(p => p.textContent)")
    if any("passes through" in w or "same face" in w for w in warn):
        bad.append(f"cable list: a ring or body warning is shown: {warn}")
    # A LEAD POINT IS DRAWN AS A POINT OF THE PATH (kit 0.17.0, Portrayal #973).
    # Four cords of the upper leaf (c1, c2, c5, c6) stand behind their ring's
    # approach point, and the kit leads each square to it: level with its plug
    # to a lead point beside the approach point, then onto the run. In 2D the
    # pane's line turns at that point: joined straight from the plug to the
    # ring it would pass some 30 mm from it; the line is drawn through the
    # point with an arc of the cable's bend radius at it.
    leads = {cid: [q for q in p["points"] if q["at"] == "lead" and q.get("item")] for cid, p in paths.items()}
    leads = {cid: qs for cid, qs in leads.items() if qs}
    if not leads:
        bad.append("lead points: the kit leads no cord of this rack square to its ring, so none was checked")
    off2d = page.evaluate(LEAD_2D_JS, leads)
    for cid, d in sorted(off2d.items()):
        # (#185) the lead point is a vertex of the 2D line and its corner is an
        # arc, which stands R (sec(theta/2) - 1) inside the vertex for a turn of
        # theta (28 mm at most on this rack). So each lead point is either on the
        # line (a corner too slight to round) or exactly an arc's own gap from it.
        if d is None:
            bad.append(f"2D: {cid} is not drawn")
            continue
        for off in d["off"]:
            if off > 0.3 and not any(abs(off - g) < 0.3 for g in d["gap"]):
                bad.append(f"2D: {cid}'s line passes {off:.2f} mm from a lead point; no arc of it stands that far inside its vertex (arcs: {[round(g, 2) for g in d['gap']]})")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the cable-lay rack's scene", tubes=True)
    bad += tubes_inside(page, 16, want_parts=("i4|tray/floor", "i4|ring/guide-3/seat", "i4|ring/guide-4/rear-leg"))
    # ...and in 3D the tube's own polyline has a vertex there.
    off3d = page.evaluate(LEAD_3D_JS, leads)
    for cid, d in sorted(off3d.items()):
        if d is None or d > 1e-3:
            bad.append(f"3D: {cid}'s tube has no vertex at its lead point (nearest {d} mm)")
    if set(off2d) != set(leads) or set(off3d) != set(leads):
        bad.append(f"lead points: measured {sorted(off2d)} in 2D and {sorted(off3d)} in 3D of {sorted(leads)}")
    # The cords from the leaf below leave their plugs below the tray and rise
    # to its rings: each is drawn out past the tray's front edge and back in,
    # as a lead is dressed by hand (not straight up through the floor).
    front = page.evaluate("""() => { const s = window.__rack.scene();
      const tray = s.rackCables.boxes.filter(b => b.ref === 'i4' && b.part === 'tray/floor');
      const edge = Math.max(...tray.map(b => b.box.max.z));
      return s.rackCables.tubes.filter(t => +t.link.id.slice(1) >= 9).map(t => {
        const main = t.mesh.children.find(m => m.geometry?.parameters?.path);
        return [t.link.id, Math.max(...main.geometry.parameters.path.getSpacedPoints(400).map(p => p.z)) - edge]; }); }""")
    short = [(c, round(dz, 1)) for c, dz in front if dz <= 0]
    if len(front) != 8 or short:
        bad.append(f"3D: the LEAF-B cords are not drawn out past the tray's front edge (mm beyond it): {front}")
    return bad


# THE BEND NOTICE AND THE WARNING RINGS (Portrayal #973, kit 0.17.0). The kit
# lays every path with room for its cable's bend radius and reports what its
# rules found no room for (route.js bendFindings). The page says those
# sentences once per set of them and rings each corner where the kit puts it,
# in both views; it measures no bend itself. On the reference cable-lay rack
# the kit finds none, so nothing is said and nothing is ringed. The finding
# here is a real one, made by an edit: the cord from LEAF-B port 52 becomes
# an AOC to LEAF-A port 52 (an AOC head seated in each cage, the two cords that
# used those ports removed to free them). Its head stands 64.8 mm out of the
# cage, so on its way to the lacer's ring it turns with less room than the 30
# mm an AOC needs. Kit 0.27.0 (#1026) chooses the ring by room, so the cord
# from port 49 to port 49 that this check once used finds one with room and
# has no finding; port 52 to port 52 still has none to turn into, and its
# findings are one single bend and two pairs of turns on a short leg (a pair
# is ONE finding with `turns`, ringed at each corner: route-context.js
# bendPoints).
# What is expected is the kit's own output, read two ways: the findings the
# page holds, and the findings of a context built afresh in the page for the
# same rack (BEND_FRESH_JS). NOT VACUOUS: it fails unless the edit produces
# findings, each in the kit's words, for c9, an AOC, at 30 mm.
AOC_HEAD = "fs/qsfp28-aoc@1"
BEND_SENTENCE_RE = re.compile(r"^c\d+ (turns [\d.]+ degrees (at|between) .+ with room for an? [\d.]+ mm bend; "
                              r"the cable \([\w-]+\) needs [\d.]+ mm, [\d.]+ mm short"
                              # two turns on one short leg, said as one (kit 0.27.0)
                              r"|turns twice within [\d.]+ mm between .+ \([\d.]+ and [\d.]+ degrees\), with room for an? [\d.]+ mm bend; "
                              r"the cable \([\w-]+\) needs [\d.]+ mm, [\d.]+ mm short"
                              r"|doubles back .+, with no room for a bend; the cable \([\w-]+\) needs [\d.]+ mm)\.$")
# The page's routes are the ones read for the rack as it is now.
ROUTES_CURRENT = "() => window.__rack.routesCurrent().current"
BEND_FRESH_JS = """async () => {
  const RC = await import('/site/rack/route-context.js'), C = await import('/vendor/rack/catalog.js');
  const {RU, OPENING} = await import('/vendor/rack/rails.js');
  const rack = window.__rack.doc().racks[0];
  const fresh = await RC.routeFacts(rack, (await C.loadCatalog('/assets/dist/')).chassisOf);
  // `points` is where the finding is ringed: its `at`, or each of its two corners for a pair of turns (bendPoints)
  const plain = f => ({cable: f.cable, text: f.text, at: f.at, need_mm: f.need_mm, room_mm: f.room_mm, point: f.point, points: RC.bendPoints(f),
    pair: Array.isArray(f.turns) && f.turns.length === 2});
  const page = (window.__rack.bends() || []).map(plain);
  return {page, fresh: fresh.bendFindings.map(plain), notice: RC.bendNotice(fresh.bendFindings),
    said: document.querySelector('.rk-side .rk-notice')?.textContent ?? '',
    // where a pane draws a rack point: x from the opening's middle (mirrored on the rear), y down from the top
    want2d: page.flatMap(f => f.points.map(p => [OPENING / 2 + p[0], rack.frame.heightRU * RU - p[1]])),
    rings2d: [...document.querySelectorAll('#paneFront svg [data-bend-finding], #paneRear svg [data-bend-finding]')].map(c => ({
      pane: c.closest('svg').dataset.pane, cable: c.dataset.bendFinding, at: [+c.getAttribute('cx'), +c.getAttribute('cy')],
      title: c.querySelector('title')?.textContent ?? '', ui: c.getAttribute('data-pt-ui')})),
    // the cable list's notes: where the sentences stay, for the keyboard and a screen reader
    listed: [...document.querySelectorAll('#side [data-route-warning]')].map(p => p.textContent),
    media: Object.fromEntries(rack.cables.map(c => [c.id, c.media]))};
}"""
BEND_RINGS_3D_JS = """async () => {
  const s = window.__rack.scene(); await s.complete?.();
  const faceZ = s.metrics().faceZ, found = [];
  s.three.scene.updateMatrixWorld(true);
  s.three.scene.traverse(o => { if (/^cable-.+-bend-\\d+$/.test(o.name)) {
    const p = o.getWorldPosition(o.position.clone());
    found.push({name: o.name, parent: o.parent?.name ?? null, visible: o.visible, mesh: !!o.isMesh,
                at: [p.x, p.y, p.z - faceZ], finding: o.userData?.bendFinding ?? null}); } });
  return {rings: found, listed: (s.rackCables?.bendRings ?? []).map(r => ({cable: r.cable, text: r.text, at: [r.at.x, r.at.y, r.at.z - faceZ]})),
          tubes: (s.rackCables?.tubes ?? []).filter(t => t.mesh).map(t => t.link.id)};
}"""


def aoc_between_the_leaves(rack):
    """The cable-lay rack with c9 as an AOC from LEAF-B port 52 to LEAF-A port 52: an AOC head in each cage, c4 and c12 gone
    (they were the cords on those two ports)."""
    out = json.loads(json.dumps(rack))
    for it in out["items"]:
        if it["id"] in ("i1", "i3"):
            it["swaps"] = {**it["swaps"], "port-52": AOC_HEAD}
    out["cables"] = [c for c in out["cables"] if c["id"] not in ("c4", "c12")]
    for c in out["cables"]:
        if c["id"] == "c9":
            c["media"] = "aoc"
            c["a"] = {"item": "i3", "path": "port-52", "view": "front"}
            c["b"] = {"item": "i1", "path": "port-52", "view": "front"}
    return out


def near(a, b, eps=0.05):
    return len(a) == len(b) and all(abs(x - y) <= eps for x, y in zip(a, b))


@extra("rack.html: bend notice - the reference cable-lay rack has no tight bend, so nothing is said or ringed; an AOC run between the leaves gives the kit's own findings, said once in the notice and ringed at each finding's point in 2D and 3D, never in a GLB, not for a cable with a loose end, and gone again on undo")
def check_rack_bend_notice(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    load_rack_3d_ready(page, base, rack)
    wait_fn(page, "bend notice: the reference rack's routes", ROUTES_CURRENT)

    # 1. THE REFERENCE RACK: the kit reports no tight bend, so the page says none and rings none.
    ref = page.evaluate(BEND_FRESH_JS)
    if ref["page"] or ref["fresh"]:
        bad.append(f"reference rack: the kit reports tight bends: {[f['text'] for f in ref['page'] + ref['fresh']]}")
    if "bend" in ref["said"] or ref["rings2d"] or any("bend" in n for n in ref["listed"]):
        bad.append(f"reference rack: a bend is said, listed or ringed with no finding: notice {ref['said']!r}, "
                   f"list {ref['listed']}, {len(ref['rings2d'])} rings")
    if webgl_trouble(page):
        print("[check_rack_bend_notice] WebGL unavailable - the 3D rings were not exercised")
    else:
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, "bend notice: the reference rack's scene", tubes=True)
        ref3d = page.evaluate(BEND_RINGS_3D_JS)
        if ref3d["rings"] or ref3d["listed"] or len(ref3d["tubes"]) != 16:
            bad.append(f"reference rack in 3D: {len(ref3d['rings'])} bend rings on {len(ref3d['tubes'])} tubes; expected none on 16")
        page.click('#mode [data-mode="2d"]')

    # 2. A REAL FINDING, by an edit: the AOC between the leaves.
    page.evaluate("r => window.__rack.replaceRack(r)", aoc_between_the_leaves(rack))
    wait_fn(page, "bend notice: the edited rack's routes",
            "() => window.__rack.routesCurrent().current && (window.__rack.bends() || []).length > 0")
    wait_sel(page, "bend notice: the notice", ".rk-side .rk-notice")
    got = page.evaluate(BEND_FRESH_JS)
    finds = got["page"]
    if got["media"].get("c9") != "aoc" or "c4" in got["media"] or "c12" in got["media"]:
        return bad + [f"the edit did not land: {got['media']}"]
    if len(finds) < 2:
        return bad + [f"the AOC gives {len(finds)} findings; expected at least two tight bends: {finds}"]
    # NOT VACUOUS: a pair of turns on one short leg is one finding with two corners (kit 0.27.0), and is ringed at each
    if not any(f["pair"] for f in finds) or not any(not f["pair"] for f in finds):
        return bad + [f"the AOC gives no mix of a single bend and a pair of turns: {[(f['pair'], f['text']) for f in finds]}"]
    points = sum(len(f["points"]) for f in finds)
    for f in finds:
        if f["cable"] != "c9" or f["need_mm"] != 30 or not BEND_SENTENCE_RE.match(f["text"]) or "(aoc) needs 30 mm" not in f["text"]:
            bad.append(f"a finding is not the kit's sentence for c9, an AOC, at 30 mm: {f}")
        if not f["room_mm"] < f["need_mm"]:
            bad.append(f"a finding has room for its bend: {f}")
    # the page's findings are the kit's for this rack, from a context built afresh
    if [(f["text"], f["at"]) for f in finds] != [(f["text"], f["at"]) for f in got["fresh"]]:
        bad.append(f"the page's findings are not the kit's for this rack: {finds} vs {got['fresh']}")
    # the notice is those sentences, and nothing else (three or fewer, each in full)
    if got["said"] != got["notice"] or (len(finds) <= 3 and got["said"] != " ".join(f["text"] for f in finds)):
        bad.append(f"the notice is {got['said']!r}, not the kit's sentences {got['notice']!r}")
    # THE SENTENCES STAY IN THE CABLE LIST'S NOTES, each once, where the ring
    # and body findings are: the notice goes with the next redraw.
    if [n for n in got["listed"] if "needs 30 mm" in n] != [f["text"] for f in finds]:
        bad.append(f"the cable list's notes are {got['listed']}; expected the kit's sentences {[f['text'] for f in finds]}")
    # 2D: a ring on the front pane (both stops are there) at each finding's point, and at each of a pair's two corners,
    # each titled with its finding's sentence
    rings = got["rings2d"]
    if [r["pane"] for r in rings] != ["front"] * points:
        bad.append(f"2D: {len(rings)} rings on panes {[r['pane'] for r in rings]}; expected {points} on the front pane")
    for r, f, want in zip(rings, [f for f in finds for _ in f["points"]], got["want2d"]):
        if r["cable"] != "c9" or r["title"] != f["text"] or not near(r["at"], want):
            bad.append(f"2D: a ring at {r['at']} titled {r['title']!r}; expected {want} for {f['text']!r}")
        if r["ui"] != "*":
            bad.append("2D: a bend ring is not marked as page UI (data-pt-ui), so a drawing export would carry it")
    # said once: another redraw (a label, which no route reads) does not say it again
    res = page.evaluate("() => window.__rack.apply({op: 'cable.update', id: 'c2', label: 'said once'})")
    if res.get("error"):
        bad.append(f"relabelling c2 was refused: {res['error']}")
    wait_fn(page, "bend notice: the relabel drawn",
            "() => window.__rack.routesCurrent().current && window.__rack.doc().racks[0].cables.find(c => c.id === 'c2').label === 'said once'"
            " && !(document.querySelector('.rk-side .rk-notice')?.textContent || '').includes('needs 30 mm')")
    again = page.evaluate("""() => ({n: document.querySelectorAll('#paneFront svg [data-bend-finding]').length, bends: window.__rack.bends().length,
      listed: [...document.querySelectorAll('#side [data-route-warning]')].map(p => p.textContent).filter(t => t.includes('needs 30 mm'))})""")
    if again["n"] != points or again["bends"] != len(finds):
        bad.append(f"after a redraw the rings are {again['n']} for {again['bends']} findings; expected {points} for {len(finds)} still")
    if again["listed"] != [f["text"] for f in finds]:
        bad.append(f"after a redraw, with the notice gone, the cable list's notes are {again['listed']}; expected the sentences still")

    if webgl_trouble(page):
        return bad
    # 3D: a ring in the cable's own group at each finding's point (each corner of a pair), and none in the file
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "bend notice: the AOC rack's scene", tubes=True)
    got3d = page.evaluate(BEND_RINGS_3D_JS)
    if len(got3d["rings"]) != points or len(got3d["listed"]) != points:
        bad.append(f"3D: {len(got3d['rings'])} rings in the scene, {len(got3d['listed'])} listed; expected {points}")
    for k, (r, (f, want)) in enumerate(zip(got3d["rings"], [(f, p) for f in finds for p in f["points"]])):
        if r["name"] != f"cable-c9-bend-{k}" or r["parent"] != "cable-c9" or not r["visible"] or not r["mesh"]:
            bad.append(f"3D: ring {k} is {r['name']!r} in {r['parent']!r}, visible {r['visible']}; expected cable-c9-bend-{k} in cable-c9")
        if not near(r["at"], want, 1e-3) or (r["finding"] or {}).get("text") != f["text"]:
            bad.append(f"3D: ring {k} is at {r['at']} for {(r['finding'] or {}).get('text')!r}; expected {want} for {f['text']!r}")
    dl = export_file(page, "glb", timeout=READY_3D_MS)
    glb = pathlib.Path(dl.path()).read_bytes()
    if glb[:4] != b"glTF":
        bad.append(f"GLB: {dl.suggested_filename!r} is not a GLB")
    else:
        names = [n.get("name") or "" for n in json.loads(glb[20:20 + int.from_bytes(glb[12:16], "little")].decode("utf-8"))["nodes"]]
        if "cable-c9" not in names:
            bad.append("GLB: the file has no cable-c9 node, so it says nothing about its rings")
        if any("-bend-" in n for n in names):
            bad.append(f"GLB: the file carries warning rings: {[n for n in names if '-bend-' in n]}")
    back = page.evaluate(BEND_RINGS_3D_JS)
    if [r["visible"] for r in back["rings"]] != [True] * points:
        bad.append(f"3D: after the export the rings are {[(r['name'], r['visible']) for r in back['rings']]}")
    # A REDRAW THAT CHANGES NOTHING KEEPS THE SCENE. The scene is rebuilt when
    # the routes' signature changes, and the signature counts the bends shown:
    # compared before they were set, it differed on every redraw of a rack
    # with a tight bend, and each one tore the scene down and built it again.
    # Selecting a cable row is a redraw and no edit.
    settle_scene(page, "bend notice: the scene before a redraw", tubes=True)
    kept = page.evaluate_handle("() => window.__rack.scene()")
    page.click('#cableList [data-cable-row="c2"]')
    wait_fn(page, "bend notice: c2's row selected", "() => !!document.querySelector('#cableList [data-cable-row=\"c2\"][aria-pressed=\"true\"]')")
    page.wait_for_timeout(1500)   # past the 300 ms rebuild debounce, and into any build it started
    if not page.evaluate("s => !!s && window.__rack.scene() === s", kept):
        bad.append("3D: selecting a cable row, which edits nothing, replaced the scene of a rack with a tight bend")
    page.click('#cableList [data-cable-row="c2"]')   # let it go again

    # A CABLE WITH A LOOSE END IS NOT DRAWN ALONG ITS PATH, so its bends are
    # neither said nor ringed: take the AOC head out of LEAF-A's cage. The
    # kit still lays a path between the two ports and still finds it tight
    # (the fresh context says so); the page says only that it is not connected.
    old = page.evaluate_handle("() => window.__rack.scene()")
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, items: r.items.map(i => (i.id === 'i1'
        ? {...i, swaps: Object.fromEntries(Object.entries(i.swaps).filter(([k]) => k !== 'port-52'))} : i))}); }""")
    wait_fn(page, "bend notice: the head taken out",
            "() => window.__rack.routesCurrent().current && !('port-52' in window.__rack.doc().racks[0].items.find(i => i.id === 'i1').swaps)"
            " && Object.values(window.__rack.cableFacts().reasons).some(Boolean)")
    page.wait_for_function("s => { const n = window.__rack.scene(); return !!n && n !== s; }", arg=old, timeout=READY_3D_MS)
    settle_scene(page, "bend notice: the loose AOC's scene", tubes=True)
    loose = page.evaluate(BEND_FRESH_JS)
    loose3d = page.evaluate(BEND_RINGS_3D_JS)
    if not [f for f in loose["fresh"] if f["cable"] == "c9"]:
        bad.append("loose end: the kit no longer finds c9's path tight, so nothing was withheld")
    if loose["page"] or loose3d["rings"] or loose3d["listed"] or "needs 30 mm" in loose["said"] or any("needs 30 mm" in n for n in loose["listed"]):
        bad.append(f"loose end: a bend of a cable that is not connected is shown: {len(loose['page'])} findings, "
                   f"{len(loose3d['rings'])} rings in 3D, notice {loose['said']!r}, list {loose['listed']}")

    # 3. UNDO: the reference rack again, and with it no finding, no ring, no sentence.
    old = page.evaluate_handle("() => window.__rack.scene()")
    page.evaluate("() => { window.__rack.undo(); window.__rack.undo(); window.__rack.undo(); }")
    wait_fn(page, "bend notice: undone",
            "() => window.__rack.routesCurrent().current && window.__rack.doc().racks[0].cables.length === 16 && window.__rack.bends().length === 0")
    page.wait_for_function("s => { const n = window.__rack.scene(); return !!n && n !== s; }", arg=old, timeout=READY_3D_MS)
    settle_scene(page, "bend notice: the undone rack's scene", tubes=True)
    gone = page.evaluate(BEND_RINGS_3D_JS)
    said = page.evaluate("() => document.querySelector('.rk-side .rk-notice')?.textContent || ''")
    notes = page.evaluate("() => [...document.querySelectorAll('#side [data-route-warning]')].map(p => p.textContent)")
    if gone["rings"] or gone["listed"] or "needs 30 mm" in said or any("needs 30 mm" in n for n in notes):
        bad.append(f"undone: {len(gone['rings'])} rings left in 3D, notice {said!r}, list {notes}")
    page.click('#mode [data-mode="2d"]')
    wait_fn(page, "bend notice: the undone rack in 2D",
            "() => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id]').length >= 16")
    left = page.evaluate("() => document.querySelectorAll('[data-bend-finding]').length")
    if left:
        bad.append(f"undone: {left} bend rings left in 2D")
    return bad


# THE ROUTE FOLLOWS THE RACK (Portrayal #973, kit 0.17.0). The kit keeps what
# it decides for a cable per rack, context and cable, so a page that reused a
# context after what it reads had changed would show a path placed for the
# rack as it was. The page builds a new context on every reading of the
# routes, frozen, and holds its routes beside the rack they were read from.
# Here the reference rack is edited four ways: a device moved, a cable's end
# moved to another port, a cable's type changed, and an optic taken out of a
# cage (the plug's reach). After each, the paths the page holds are compared,
# point for point, with the paths of a context built afresh in the page for
# the rack as it now is, and must be the ones the edit changes; the context
# must be a new, frozen object; the pane must have redrawn the cable. Then, in
# 3D, a device is moved and every tube must start at its plug's reach point
# again (a scene hung by the old paths would start two rack units off).
# NOT VACUOUS: each edit must change at least one path, and name the cable.
ROUTE_FOLLOW_JS = """async () => {
  const RC = await import('/site/rack/route-context.js'), C = await import('/vendor/rack/catalog.js');
  const rack = window.__rack.doc().racks[0];
  const fresh = await RC.routeFacts(rack, (await C.loadCatalog('/assets/dist/')).chassisOf);
  const r2 = v => Math.round(v * 100) / 100;
  const pts = p => (p ? p.points.map(q => [q.at, r2(q.x), r2(q.y), r2(q.z)]) : null);
  const page = window.__rack.paths() || {};
  const ctx = window.__rack.routeContext();
  window.__ctxSeen ??= [];
  const isNew = !!ctx && !window.__ctxSeen.includes(ctx);
  window.__ctxSeen.push(ctx);
  // a write to the context must not change it in place (it is frozen: a
  // module's write throws, and this one, outside strict mode, does nothing)
  const was = ctx?.bendOf;
  try { ctx.bendOf = () => 1; } catch { /* frozen */ }
  const wrote = !ctx || ctx.bendOf !== was;
  return {page: Object.fromEntries(Object.entries(page).map(([id, p]) => [id, pts(p)])),
    fresh: Object.fromEntries([...fresh.paths].map(([id, p]) => [id, pts(p)])),
    lengths: Object.fromEntries(Object.entries(page).map(([id, p]) => [id, [p?.measured ?? null, p?.value ?? null]])),
    freshLengths: Object.fromEntries([...fresh.lengths].map(([id, l]) => [id, [l?.measured ?? null, l?.value ?? null]])),
    stored: Object.fromEntries(rack.cables.map(c => [c.id, c.length?.source === 'routed' ? c.length.value : null])),
    current: window.__rack.routesCurrent(), isNew, wrote, bendOf: typeof ctx?.bendOf,
    drawn: Object.fromEntries([...document.querySelectorAll('#paneFront svg [data-cables] [data-cable][data-cable-id]')]
      .map(g => [g.dataset.cableId, [...g.querySelectorAll('path')].map(p => p.getAttribute('d')).join('|')]))};
}"""


def route_follows(page, label, before, expect):
    """The page's paths against a fresh context's, after an edit: problems, and the reading."""
    got = page.evaluate(ROUTE_FOLLOW_JS)
    bad = []
    if not got["current"]["current"] or not got["current"]["frozen"] or got["wrote"]:
        bad.append(f"{label}: the routes are current {got['current']['current']}, their context frozen {got['current']['frozen']}, written to {got['wrote']}")
    if not got["isNew"]:
        bad.append(f"{label}: the routes were read with a context already used for the rack as it was")
    if got["bendOf"] != "function":
        bad.append(f"{label}: the context has no bendOf, so no cable is judged by its own type's radius")
    stale = sorted(c for c in got["fresh"] if got["page"].get(c) != got["fresh"][c])
    if stale or set(got["page"]) != set(got["fresh"]):
        bad.append(f"{label}: the page's paths are not the kit's for the rack as it is: {stale or sorted(set(got['page']) ^ set(got['fresh']))}")
    if got["lengths"] != got["freshLengths"]:
        bad.append(f"{label}: the page's lengths are not the kit's for the rack as it is")
    off = sorted(c for c, (_, value) in got["freshLengths"].items() if got["stored"].get(c) != value)
    if off:
        bad.append(f"{label}: the stored routed lengths did not follow: {[(c, got['stored'].get(c), got['freshLengths'][c][1]) for c in off]}")
    if before is not None:
        moved = sorted(c for c in got["page"] if before["page"].get(c) != got["page"][c])
        if not set(expect) <= set(moved):
            bad.append(f"{label}: the paths that changed are {moved}; expected at least {sorted(expect)}")
        same = sorted(c for c in expect if before["drawn"].get(c) == got["drawn"].get(c))
        if same:
            bad.append(f"{label}: the pane still draws {same} as before the edit")
    return bad, got


@extra("rack.html: routes follow edits - after a device moves, a cable end moves to another port, a cable's type changes or an optic leaves its cage, the page's paths are the kit's for the rack as it is, read with a new frozen context, redrawn in 2D, and in 3D every tube starts at its plug again")
def check_rack_routes_follow_edits(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    load_rack_3d_ready(page, base, rack)
    wait_fn(page, "follow: the reference rack's routes", ROUTES_CURRENT)
    faults, state = route_follows(page, "the reference rack", None, ())
    bad += faults
    lower = [f"c{i}" for i in range(9, 17)]

    def edit(label, js, arg, expect, done):
        nonlocal state
        res = page.evaluate(js, arg)
        if isinstance(res, dict) and res.get("error"):
            bad.append(f"{label}: refused: {res['error']}")
            return
        wait_fn(page, f"follow: {label}", f"() => window.__rack.routesCurrent().current && ({done})()")
        # the pane is redrawn after the routes are read: wait for the drawing of the first cable expected to change
        page.wait_for_function(
            "([id, was]) => { const g = document.querySelector(`#paneFront svg [data-cables] [data-cable][data-cable-id=\"${id}\"]`);"
            " return !!g && [...g.querySelectorAll('path')].map(p => p.getAttribute('d')).join('|') !== was; }",
            arg=[expect[0], state["drawn"].get(expect[0])], timeout=READY_MS)
        faults, now = route_follows(page, label, state, expect)
        bad.extend(faults)
        state = now

    # A REFUSAL THAT COMES AFTER THE WAIT IS STILL SEEN. The bundle form is
    # opened on c1 with c9 ticked, on the rack as it was loaded: the kit
    # refuses that pair (c1 runs with none of the others). Create is clicked in the same turn as an edit, so
    # the command waits for the redraw, and that redraw rebuilds the side
    # panel: the form's own error line is gone when the refusal arrives, and
    # it must come as the page's notice instead.
    page.click('#cableList [data-cable-row="c1"]')
    page.click("#cableBundle")
    page.check("#bPick-c9")
    page.evaluate("""() => { window.__rack.apply({op: 'cable.update', id: 'c2', label: 'late'});
      document.querySelector('#bCreate').click(); }""")
    try:
        page.wait_for_function("() => (document.querySelector('.rk-side .rk-notice')?.textContent || '').includes('runs with none of the others')",
                               timeout=15000)
    except Exception:
        shown = page.evaluate("() => document.querySelector('.rk-side .rk-notice')?.textContent ?? null")
        bad.append(f"a bundle refused after its wait, its form redrawn meanwhile: the refusal was shown nowhere (notice {shown!r})")
    if page.evaluate("() => (window.__rack.doc().racks[0].bundles || []).length"):
        bad.append("the refused bundle was made")
    page.keyboard.press("Escape")
    page.evaluate("() => document.querySelector('#bCancel')?.click()")
    wait_fn(page, "follow: the routes after the refused bundle", ROUTES_CURRENT)

    apply = "c => window.__rack.apply(c)"
    item = "id => window.__rack.doc().racks[0].items.find(i => i.id === id)"
    # a device moved: LEAF-B from U40 to U38, and every cord from it with it
    edit("LEAF-B moved to U38", apply, {"op": "move", "id": "i3", "ru": 38}, lower,
         f"() => ({item})('i3').ru === 38")
    # a cable's end moved to another port: c16's panel end to a free LC of the panel in another bay
    free = page.evaluate("""async () => { const r = window.__rack.doc().racks[0];
      const bay = r.cables.find(c => c.id === 'c16').b.path.split('/')[0];
      const ports = await window.__rack.query.freePorts('i2');
      const lc = (Array.isArray(ports) ? ports : []).filter(p => p.view === 'front' && /\\/module\\/lc\\d+$/.test(p.path));
      return (lc.find(p => p.path.split('/')[0] !== bay) ?? {}).path ?? null; }""")
    if not free:
        bad.append("a free LC port of the panel in another bay was not found, so no cable end was moved")
    else:
        edit(f"c16's end moved to {free}", apply, {"op": "cable.update", "id": "c16", "b": {"item": "i2", "path": free, "view": "front"}},
             ["c16"], f"() => window.__rack.doc().racks[0].cables.find(c => c.id === 'c16').b.path === {json.dumps(free)}")
    # a cable's type changed: c12 from OM4 to a Cat 6A cord, which is thicker, stiffer to hang and has its own radius
    edit("c12's type changed to cat6a", apply, {"op": "cable.update", "id": "c12", "media": "cat6a"}, ["c12"],
         "() => window.__rack.doc().racks[0].cables.find(c => c.id === 'c12').media === 'cat6a'")
    # an optic taken out of its cage: c4's plug no longer stands where the optic held it
    edit("the optic left LEAF-A port 52", """() => { const r = window.__rack.doc().racks[0];
           window.__rack.replaceRack({...r, items: r.items.map(i => (i.id === 'i1'
             ? {...i, swaps: Object.fromEntries(Object.entries(i.swaps).filter(([k]) => k !== 'port-52'))} : i))}); return {}; }""",
         None, ["c4"], f"() => !('port-52' in ({item})('i1').swaps)")

    # A COMMAND THAT WAITED IS NOT SENT TO ANOTHER RACK. A panel's bundle.create
    # is issued in the same turn as a move, and before the redraw ends another
    # document is put in (as opening a file does) that has a c9 and a c10 too.
    # The command is dropped: it answers `dropped`, and the new rack has no bundle.
    other = page.evaluate("""async () => {
      const doc = structuredClone(window.__rack.doc());
      const next = {...doc, id: `${doc.id}-other`, racks: doc.racks.map(r => ({...r, name: 'Another rack', bundles: []}))};
      const was = window.__rack.doc().id;
      window.__rack.apply({op: 'move', id: 'i3', ru: 36});
      const waiting = window.__rack.bundleCommand({op: 'bundle.create', cables: ['c9', 'c10']});
      window.__rack.loadDoc(next);
      const answer = await waiting;
      const t0 = Date.now();
      while (!window.__rack.routesCurrent().current && Date.now() - t0 < 20000) await new Promise(r => setTimeout(r, 50));
      const now = window.__rack.doc();
      return {was, id: now.id, name: now.racks[0].name, answer, bundles: (now.racks[0].bundles || []).length,
              has: ['c9', 'c10'].every(id => now.racks[0].cables.some(c => c.id === id)), current: window.__rack.routesCurrent().current}; }""")
    if other["id"] == other["was"] or other["name"] != "Another rack" or not other["has"] or not other["current"]:
        bad.append(f"another document was not put in during the wait, so nothing was tested: {other}")
    if other["bundles"] or other["answer"] != {"dropped": True}:
        bad.append(f"a bundle command that waited through a change of document: answered {other['answer']}, and the new rack has "
                   f"{other['bundles']} bundles; expected it dropped and no bundle made")
    faults, state = route_follows(page, "after another document", None, ())
    bad += faults

    # THE DOCUMENT MOVES WHILE THE ROUTES ARE READ. A change that is not an
    # undo step (a DCIM setting stored) redraws nothing. Landing while the
    # redraw after a move is still reading the routes, it used to leave the
    # page holding the routes of the rack before the move, with no redraw in
    # hand to read them again. The move's redraw starts on the next
    # microtask; the setting is stored one microtask later, long before any
    # drawing is read. The routes must become the rack's own.
    res = page.evaluate("""async () => {
      const moved = window.__rack.apply({op: 'move', id: 'i3', ru: 37});
      await Promise.resolve();
      const set = window.__rack.apply({op: 'dcim', site: 'Lab 4', role: 'leaf'});
      return {moved: moved.error ?? null, set: set.error ?? null, current: window.__rack.routesCurrent().current}; }""")
    if res["moved"] or res["set"] or res["current"]:
        bad.append(f"a setting stored during the redraw after a move: {res}; expected both to land with the routes not yet read")
    try:
        page.wait_for_function("() => window.__rack.routesCurrent().current && window.__rack.doc().racks[0].items.find(i => i.id === 'i3').ru === 37",
                               timeout=20000)
    except Exception:
        bad.append("a setting stored during the redraw after a move left the page holding the routes of the rack before it")
    else:
        faults, state = route_follows(page, "after a setting stored during the redraw", None, ())
        bad += faults

    # A COMMAND THAT READS THE ROUTES never takes the last rack's. The page's
    # own apply, in the same turn as an edit, has no context for the rack as
    # it is: the kit refuses a bundle and says the routes are not known, where
    # the page used to hand it the context of the rack before the edit.
    # A PERSON'S BUNDLE COMMAND (a panel's: bundleCommand) waits for the redraw
    # in hand and is then sent with the new rack's routes: made, and checked,
    # never "not checked ... the routes are not known here". So for create,
    # and for add after another move.
    both = page.evaluate("""async () => {
      const moved = window.__rack.apply({op: 'move', id: 'i3', ru: 39});
      const cur = window.__rack.routesCurrent().current;
      const raw = window.__rack.apply({op: 'bundle.create', cables: ['c9', 'c10']});
      const made = await window.__rack.bundleCommand({op: 'bundle.create', cables: ['c9', 'c10']});
      const ru = window.__rack.doc().racks[0].items.find(i => i.id === 'i3').ru, route = (window.__rack.doc().racks[0].bundles || [])[0]?.route ?? null;
      const moved2 = window.__rack.apply({op: 'move', id: 'i3', ru: 38});
      const cur2 = window.__rack.routesCurrent().current;
      const added = await window.__rack.bundleCommand({op: 'bundle.add', id: made.created?.id ?? made.created?.ids?.[0], cables: ['c11']});
      return {moved: moved.error ?? null, current: cur, raw: raw.error ?? null, made, ru, route,
              moved2: moved2.error ?? null, current2: cur2, added,
              members: (window.__rack.doc().racks[0].bundles || []).map(b => b.members.map(m => m.cable))}; }""")
    if both["moved"] or both["current"] or "routes" not in (both["raw"] or ""):
        bad.append(f"a bundle applied in the same turn as a move: the move {both['moved']!r}, routes current {both['current']}, "
                   f"the kit answered {both['raw']!r}; expected a refusal that says the routes are not known")
    unchecked = lambda r: [t for t in (r.get("findings") or []) if "not checked" in t or "not known" in t]
    # (made with a trunk worked out from the routes, which only a route context gives)
    if both["made"]["error"] or both["ru"] != 39 or not both["route"] or unchecked(both["made"]):
        bad.append(f"a panel's bundle.create sent in the same turn as a move: {both['made']}, trunk {both['route']}; "
                   "expected it made, its trunk worked out from the moved rack's routes, and checked")
    if both["moved2"] or both["current2"] or both["added"]["error"] or unchecked(both["added"]) or both["members"] != [["c9", "c10", "c11"]]:
        bad.append(f"a panel's bundle.add sent in the same turn as a move: {both['added']}, routes current before {both['current2']}, "
                   f"members {both['members']}; expected c11 added, with the moved rack's routes, and checked")
    if both["made"]["error"]:
        return bad            # no bundle to wait for: what went wrong is said above
    wait_fn(page, "follow: the bundle", "() => window.__rack.routesCurrent().current && (window.__rack.bundles() || []).length === 1")

    if webgl_trouble(page):
        print("[check_rack_routes_follow_edits] WebGL unavailable - the 3D rebuild was not exercised")
        return bad
    # IN 3D: the scene is hung by the routes of the rack as it is. Each tube
    # starts at the kit's reach point for its plug (reachGap, mm, a and b);
    # hung by the paths of the rack before the move, the cords of LEAF-B
    # would start two rack units, 88.9 mm, from their plugs.
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "follow: the scene", tubes=True)
    old = page.evaluate_handle("() => window.__rack.scene()")
    res = page.evaluate(apply, {"op": "move", "id": "i3", "ru": 40})
    if res.get("error"):
        return bad + [f"3D: moving LEAF-B back was refused: {res['error']}"]
    page.wait_for_function("s => { const n = window.__rack.scene(); return !!n && n !== s; }", arg=old, timeout=READY_3D_MS)
    settle_scene(page, "follow: the scene after the move", tubes=True)
    wait_fn(page, "follow: the routes after the move", ROUTES_CURRENT)
    gaps = page.evaluate("""() => { const s = window.__rack.scene();
      const ru = window.__rack.doc().racks[0].items.find(i => i.id === 'i3').ru;
      return {ru, tubes: (s.rackCables.tubes || []).filter(t => t.routed).map(t => [t.link.id, t.reachGap ?? null])}; }""")
    far = [(c, g) for c, g in gaps["tubes"] if not g or any(v is None or v > 2.0 for v in g)]
    if gaps["ru"] != 40 or len(gaps["tubes"]) < 14 or far:
        bad.append(f"3D: after LEAF-B moved to U{gaps['ru']}, {len(gaps['tubes'])} routed tubes, and these do not start at "
                   f"their plugs' reach points (mm apart, a and b): {far}")
    faults, _ = route_follows(page, "3D: after the move", None, ())
    return bad + faults


# THE CORDS CLEAR THE RINGS (portrayal-site#166, Portrayal #968). A D-ring is
# solid round its opening: its legs, bar, seat and hook are in rack.json's
# `solids` as `ring/<id>/<part>` (kit 0.15.0), and the kit routes each cord
# through the opening from an approach point on the ring's run. On the
# cable-lay rack (the owner's rack: the same items, frame and cable ends,
# saved there with routed lengths), every routed tube's centre line is
# sampled every half millimetre against each ring part AS THE KIT PLACES IT
# (the scene's `raw` box, not grown), and against each zero-U part: none may
# come nearer than the tube's radius, less TUBE_EPS. On site main the scene
# drew its own ring points (the opening's centre, a lead, a spread), and its
# rounded arcs swung through the legs and the bar. NOT VACUOUS: it fails
# without ring parts among the scene's bodies, without 16 routed tubes, or
# with too few samples.
RING_CLEAR_STEP = 0.5
RING_CLEAR_JS = """async ([step, which]) => {
  const s = window.__rack.scene(); await s.complete?.();
  const deadline = Date.now() + 60000;
  while (!(s.rackCables?.tubes ?? []).some(t => t.routed && t.mesh) && Date.now() < deadline) await new Promise(r => setTimeout(r, 200));
  const isRing = b => String(b.part).startsWith('ring/');
  const parts = (s.rackCables?.boxes ?? []).filter(b => isRing(b) || b.zeroU)
    .map(b => { const x = b.raw ?? b.box; return {ring: isRing(b), ref: b.ref, part: b.part, min: [x.min.x, x.min.y, x.min.z], max: [x.max.x, x.max.y, x.max.z]}; });
  const dist = (p, b) => Math.hypot(...[0, 1, 2].map(k => Math.max(b.min[k] - p[k], 0, p[k] - b.max[k])));
  // `which`: the routed cables' tubes, or each bundle's trunk (its own radius)
  let tubes = [];
  if (which === 'trunks') {
    const d = Date.now() + 30000;
    while (!s.rackCables?.bundles && Date.now() < d) await new Promise(r => setTimeout(r, 200));
    s.three.scene.traverse(o => { if (/^bundle-.+-trunk$/.test(o.name) && o.geometry?.parameters?.path) tubes.push({id: o.name, main: o}); });
  } else tubes = (s.rackCables?.tubes ?? []).filter(t => t.routed && t.mesh)
    .map(t => ({id: t.link.id, main: t.mesh.children.find(m => m.geometry?.parameters?.path)}));
  const cords = [];
  let samples = 0;
  for (const {id, main} of tubes) {
    if (!main) continue;
    const curve = main.geometry.parameters.path, r = main.geometry.parameters.radius;
    let worst = null;
    for (const q of curve.getSpacedPoints(Math.max(2, Math.ceil(curve.getLength() / step)))) {
      samples++;
      const p = [q.x, q.y, q.z];
      for (const b of parts) {
        const c = dist(p, b) - r;
        if (!worst || c < worst.clear) worst = {clear: c, ref: b.ref, part: b.part, at: p.map(v => Math.round(v * 10) / 10)};
      }
    }
    if (worst) cords.push({cable: id, clear_mm: Math.round(worst.clear * 100) / 100, ref: worst.ref, part: worst.part, at: worst.at});
  }
  return {rings: parts.filter(b => b.ring).length, tubes: tubes.length, samples, cords};
}"""


def ring_clearance(page, want_tubes, which="cables"):
    """Every routed tube (or, `which` "trunks", every bundle trunk at its own
    radius) against every ring part and zero-U part: problems, or []."""
    got = page.evaluate(RING_CLEAR_JS, [RING_CLEAR_STEP, which])
    if not got["rings"] or got["tubes"] < want_tubes or got["samples"] < want_tubes * 200:
        return [f"3D: {got['rings']} ring parts among the scene's bodies, {got['tubes']} {which}, {got['samples']} samples; "
                f"expected ring parts and {want_tubes} {which}"]
    return [f"3D: {c['cable']}'s tube runs {-c['clear_mm']} mm into {c['ref']} {c['part']} at {c['at']}"
            for c in got["cords"] if c["clear_mm"] < -TUBE_EPS]


@extra("rack.html: ring solids - on the owner's cable-lay rack every cord's 3D tube stays at least its radius from every part of every D-ring (kit 0.15.0 ring/<id>/<part>), drawn from the kit's own reach points, and a bundle's trunk through a ring by its own radius")
def check_rack_ring_clearance(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    load_rack_3d_ready(page, base, rack)
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the ring rack's scene", tubes=True)
    bad += ring_clearance(page, 16)
    # Drawn through the kit's points: each tube starts at the kit's reach
    # point (the plug's far end, plugReachOf), within the 2D/3D port offset.
    gaps = page.evaluate("""() => (window.__rack.scene().rackCables.tubes || []).filter(t => t.routed)
      .map(t => [t.link.id, t.reachGap ?? null])""")
    far = [(c, g) for c, g in gaps if not g or any(v is None or v > 2.0 for v in g)]
    if len(gaps) != 16 or far:
        bad.append(f"3D: the tubes do not start at the kit's reach points (mm apart, a and b): {far or gaps}")
    # A BUNDLE'S TRUNK through a ring (three Cat 6A cords through mgr-1's ring
    # 1, on the front and on the rear rails): it is wider than its members,
    # so it is laid on the sill at its own radius and clears every ring part
    # by it, as a cable does by its own.
    for face in ("front", "rear"):
        open_bundle_rack(page, base, face)
        res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3']})")
        if res.get("error"):
            bad.append(f"{face}: bundle.create refused: {res['error']}")
            continue
        page.wait_for_function("() => (window.__rack.bundles() || [])[0]?.count > 0", timeout=READY_MS)
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, f"{face}: the bundled rack's scene", tubes=True)
        bad += [f"{face}: {b}" for b in ring_clearance(page, 1, "trunks")]
    return bad


# A rack with a zero-U PDU at the right-rear upright, and two switches on the
# rear rails at U10 and U30 joined from port 1 of each (at the rack's right, as
# seen from the front, on a rear-facing switch): the right-rear lane
# runs outboard of the PDU (route.js laneXAt), and each port's leg to it goes
# round the PDU's back, the side facing into the rack (solids.js, rule 3 of
# 1.3). Drawn in 2D and 3D through those detours, the cable goes round the
# PDU, never through it.
PDU_RACK_JS = """async () => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.newRack({name: 'Rear PDU'});
  const optic = {'port-1': 'generic/qsfp-lc@2'};
  ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 10, label: 'sw-low', face: 'rear', swaps: optic}));
  ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 30, label: 'sw-high', face: 'rear', swaps: optic}));
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i2', path: 'port-1', view: 'front'}, media: 'os2'}));
  r = {...r, zeroU: [{id: 'z1', ref: 'evma8365x', cfg: cat['evma8365x'].default, label: 'PDU-A', at: 'right-rear', offsetMm: 0}]};
  return r;
}"""


# EVERY 3D CORNER AT THE CABLE'S BEND RADIUS (portrayal-site#164; Portrayal
# docs/cable-lay-design.md section 3). On the two-leaf fixture rack, bundled
# by the agent tools as an AI session does (c1-c7, c9-c12, c13-c16), each
# bundle answers with its bend radius from the cable types, never "not
# loaded"; then every routed tube's centre line is sampled every half
# millimetre and the radius through each three neighbouring samples taken. A
# sample tighter than the cable's installed radius (less BEND_TOL) must lie on
# a corner the drawing flagged as too tight for its legs, and no tighter than
# the radius it flagged; each flag is true (bend_faults) and in the kit's
# bend-check words, and kept in the scene, not said in the page's notice
# (what the notice says is the kit's own findings, check_rack_bend_notice: a
# flag here is the drawing's account of its arcs); and each tube's length is its polyline's less exactly
# what rounding took off, R(2 tan(theta/2) - theta) a corner. NOT VACUOUS: it
# fails without 16 rounded tubes at OM4's radius, without enough samples, or
# without a corner drawn at the full radius.
# A bend flag as the page says it (bend3d.js tightText, in the kit's
# bend-check words), and the "And n more." that ends a long notice.
BEND_FLAG_RE = re.compile(r"(c\d+|Bundle \d+|[^.]+?) in 3D (turns .*? with room for an? [\d.]+ mm bend; \S+( \([\w-]+\))? needs [\d.]+ mm, [\d.]+ mm short"
                          r"|(turns|doubles back) .*? no room for a bend; \S+( \([\w-]+\))? needs [\d.]+ mm)\.|And \d+ more\.")
BEND_FLAGS_JS = """() => { const s = window.__rack.scene(); const rc = s?.rackCables;
  if (!rc) return null;
  const inside = q => rc.boxes.find(({box}) => q[0] > box.min.x + 0.05 && q[0] < box.max.x - 0.05 && q[1] > box.min.y + 0.05
    && q[1] < box.max.y - 0.05 && q[2] > box.min.z + 0.05 && q[2] < box.max.z - 0.05);
  return {flags: (rc.tight ?? []).map(t => { const b = t.hit ? inside(t.hit) : null;
            return {...t, hitInside: !!b, hitInsideRef: b?.ref ?? null}; }),
          extends: (rc.tubes ?? []).filter(t => t.bend).map(t => ({cable: t.link.id, radius_mm: t.bend.radius_mm,
            extended_mm: t.bend.extended_mm ?? [0, 0]}))}; }"""
# bend3d.js MAX_EXTEND_R: a lead is drawn at most this many radii longer.
MAX_EXTEND_R = 2


def bend_faults(flags, extends=()):
    """The faults in a scene's bend flags (rackCables.tight, read by
    BEND_FLAGS_JS) and its leads' lengthening. Every flagged corner must be
    short for a reason that holds:
    - 'body': a point of its full arc is strictly inside a solid box;
    - 'legs': it is drawn with all the leg its neighbours leave it;
    - a lead out of a port is not flagged for its own device: its arc starts
      at the plug's end, out of the device (bend3d.js kitRoute) - only for
      another item's body (a tray in front of the port), for its legs, or
      when its lead reached the cap.
    And no lead is drawn more than MAX_EXTEND_R radii longer."""
    out = []
    for f in flags:
        who = f.get("cable") or f.get("bundle")
        if f["why"] == "body" and not f.get("hitInside"):
            out.append(f"{who}'s corner is flagged for a body its arc does not meet: {f['text']!r}")
        if f.get("lead") and f["why"] == "body":
            other = f.get("hitInsideRef") and f["hitInsideRef"] != f.get("leadItem")
            capped = (f.get("extended_mm") or 0) >= MAX_EXTEND_R * (f.get("radius_mm") or 0) - 1e-6
            if not (other or capped):
                out.append(f"{who}'s lead out of its port is flagged for its own device: {f['text']!r}")
        if f["why"] == "legs" and f.get("t") is not None and abs(f["t"] - f["room_t"]) > 1e-6:
            out.append(f"{who}'s corner is flagged short of legs but drawn tighter than its legs allow: {f}")
        if f["why"] not in ("body", "legs", "back"):
            out.append(f"{who}'s flag has no reason: {f}")
    for e in extends:
        if any(x > MAX_EXTEND_R * e["radius_mm"] + 1e-6 for x in e["extended_mm"]):
            out.append(f"{e['cable']}'s lead is drawn {e['extended_mm']} mm longer, past {MAX_EXTEND_R} radii of {e['radius_mm']} mm")
    return out


def bend_faults_self_test():
    """bend_faults must find a false flag of each kind, or a check that reads
    it passes whatever the drawing does. []: it does."""
    ok = {"cable": "c1", "text": "t", "why": "legs", "t": 5.0, "room_t": 5.0, "lead": False}
    cases = {
        "a body flag with no hit inside a body": {**ok, "why": "body", "hitInside": False},
        "a flagged lead out of its own device": {**ok, "why": "body", "hitInside": True, "hitInsideRef": "i1",
                                                 "lead": True, "leadItem": "i1", "extended_mm": 0, "radius_mm": 25},
        "a legs flag drawn tighter than its legs": {**ok, "t": 3.0, "room_t": 5.0},
        "a flag with no reason": {**ok, "why": None},
    }
    out = [f"bend_faults does not catch {name}" for name, f in cases.items() if not bend_faults([f])]
    if bend_faults([ok]) or bend_faults([{**ok, "why": "body", "hitInside": True, "hitInsideRef": "i4", "lead": True,
                                          "leadItem": "i1", "extended_mm": 0, "radius_mm": 25}]):
        out.append("bend_faults faults a true flag")
    if not bend_faults([], [{"cable": "c1", "radius_mm": 25, "extended_mm": [51, 0]}]):
        out.append("bend_faults does not catch a lead drawn past the cap")
    return out


def bend_flags_true(page):
    """bend_faults for the scene on `page` (itself self-tested first)."""
    got = page.evaluate(BEND_FLAGS_JS) or {"flags": [], "extends": []}
    return bend_faults_self_test() + bend_faults(got["flags"], got["extends"])


BEND_TOL = 0.01      # 1%: three samples on an arc give its radius; a line-to-arc join gives more
BEND_STEP = 0.5      # mm between samples
BEND_SAMPLE_JS = """async ([tol, step]) => {
  const s = window.__rack.scene(); await s.complete?.();
  const deadline = Date.now() + 60000;
  while (!(s.rackCables?.tubes ?? []).some(t => t.routed && t.mesh) && Date.now() < deadline) await new Promise(r => setTimeout(r, 200));
  const circ = (a, b, c) => { const x = b.clone().sub(a).cross(c.clone().sub(a)).length();
    return x < 1e-9 ? Infinity : a.distanceTo(b) * b.distanceTo(c) * c.distanceTo(a) / (2 * x); };
  const tubes = (s.rackCables?.tubes ?? []).filter(t => t.routed && t.mesh);
  const out = {tubes: tubes.length, rounded: 0, radii: [], samples: 0, full: 0, flagged: 0, bad: [], lengths: [],
               tight: (s.rackCables?.tight ?? []).map(t => t.text)};
  for (const t of tubes) {
    if (!t.bend) continue;
    out.rounded++;
    const R = t.bend.radius_mm;
    out.radii.push(R);
    const main = t.mesh.children.find(m => m.geometry?.parameters?.path);
    const curve = main.geometry.parameters.path;
    const P = curve.getSpacedPoints(Math.ceil(curve.getLength() / step));
    out.samples += P.length;
    const flags = t.bend.corners.filter(c => c.short_mm > 0);
    out.flagged += flags.length;
    out.full += t.bend.corners.filter(c => c.short_mm === 0 && c.drawn_mm >= R).length;
    let worst = null;
    for (let k = 1; k < P.length - 1; k++) {
      const r = circ(P[k - 1], P[k], P[k + 1]);
      if (r >= R * (1 - tol)) continue;
      // the flagged corners whose arcs reach this sample (corners can sit a
      // few mm apart, where the kit hangs a span): one of them must allow it
      const near = flags.filter(c => P[k].distanceTo(c.at) <= c.t + step);
      const why = !near.length ? 'not flagged' : near.every(c => r < c.drawn_mm * (1 - tol))
        ? `tighter than its flag (${Math.min(...near.map(c => c.drawn_mm))} mm)` : null;
      if (why && (!worst || r < worst.r)) worst = {r, why, at: [P[k].x, P[k].y, P[k].z].map(v => Math.round(v))};
    }
    if (worst) out.bad.push({cable: t.link.id, need: R, r: Math.round(worst.r * 100) / 100, why: worst.why, at: worst.at});
    const cut = t.bend.corners.reduce((a, c) => a + (c.drawn_mm > 0 && c.t > 0 ? (c.t / Math.tan(c.theta / 2)) * (2 * Math.tan(c.theta / 2) - c.theta) : 0), 0);
    out.lengths.push({cable: t.link.id, drawn: t.bend.length_mm, polyline: t.bend.polyline_mm, cut,
                      measured: window.__rack.paths()?.[t.link.id]?.measured ?? null});
  }
  out.notice = document.querySelector('.rk-side .rk-notice')?.textContent ?? '';
  return out;
}"""


@extra("rack.html: bend radius - agent-made bundles of OM4 cords on the two-leaf rack report their bend radius from the cable types, and every 3D corner is at least the installed bend radius, or flagged in the scene where its legs cannot hold one")
def check_rack_bend_radius_3d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.add_init_script(STAND_IN_MODEL_CONTEXT)
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    load_rack_3d_ready(page, base, rack)
    wait_fn(page, "bend: agent tools registered", "() => window.__tools && window.__tools.edit_rack && window.__tools.inspect")
    groups = [[f"c{i}" for i in range(1, 8)], [f"c{i}" for i in range(9, 13)], [f"c{i}" for i in range(13, 17)]]
    for g in groups:
        said = agent_call(page, "edit_rack", {"commands": [{"op": "bundle.create", "cables": g}]})["content"][0]["text"]
        if "not loaded" in said or "not checked" in said:
            bad.append(f"agent: bundling {g[0]}-{g[-1]} answered {said!r}")
    for bid in ("b1", "b2", "b3"):
        said = agent_call(page, "inspect", {"id": bid})["content"][0]["text"]
        if "\nbend: radius 25 mm" not in said or "not loaded" in said:
            bad.append(f"agent: inspect {bid} does not give OM4's 25 mm bend radius: {said!r}")
    said = agent_call(page, "describe_rack", {"section": "bundles"})["content"][0]["text"]
    if "not loaded" in said:
        bad.append(f"agent: describe_rack says the cable types are not loaded: {said!r}")
    wait_fn(page, "bend: the page has the bundles", "() => (window.__rack.bundles() || []).length === 3")
    page_bundles = page.evaluate("() => window.__rack.bundles()")
    if any(any("not loaded" in w for w in b["warnings"]) for b in page_bundles):
        bad.append(f"page: a bundle's warnings say the cable types are not loaded: {page_bundles}")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the bend rack's scene", tubes=True)
    got = page.evaluate(BEND_SAMPLE_JS, [BEND_TOL, BEND_STEP])
    if got["tubes"] != 16 or got["rounded"] != 16 or set(got["radii"]) != {25}:
        bad.append(f"3D: {got['rounded']} of {got['tubes']} routed tubes rounded, at radii {sorted(set(got['radii']))}; expected 16 at OM4's 25 mm")
    if got["samples"] < 16 * 200 or not got["full"]:
        bad.append(f"3D: sampled {got['samples']} points, {got['full']} corners at the full radius: too few to have measured anything")
    for b in got["bad"][:16]:
        bad.append(f"3D: {b['cable']}'s tube bends at {b['r']} mm near {b['at']}, under its {b['need']} mm radius: {b['why']}")
    if got["flagged"] != len(got["tight"]):
        bad.append(f"3D: {got['flagged']} corners flagged but {len(got['tight'])} said")
    # The flags are the scene's (rackCables.tight), never the page's to say:
    # the notice says the kit's findings (kit 0.17.0, check_rack_bend_notice),
    # which are worded without "in 3D" and are none on this rack.
    if got["tight"] and BEND_FLAG_RE.search(got["notice"]):
        bad.append(f"3D: the page says a bend flag: {got['notice']!r}")
    for t in got["tight"]:
        if not re.search(r"^c\d+ in 3D (turns .* with room for an? [\d.]+ mm bend; c\d+ \(om4\) needs 25 mm, [\d.]+ mm short|(turns|doubles back) .*no room for a bend; c\d+ \(om4\) needs 25 mm)\.$", t):
            bad.append(f"3D: a tight corner is not in the kit's bend-check words: {t!r}")
    bad += [f"3D: {b}" for b in bend_flags_true(page)]
    # The drawn tube is its polyline less exactly what rounding took off.
    for L in got["lengths"]:
        if abs(L["polyline"] - L["cut"] - L["drawn"]) > 0.5:
            bad.append(f"3D: {L['cable']}'s tube is {L['drawn']:.1f} mm; its polyline {L['polyline']:.1f} less {L['cut']:.1f} rounded off")
    return bad

@extra("rack.html: a routed cable in 2D keeps its bend radius - every corner of its line is an arc of the cable's own radius (OM4's 25 mm) or a smaller one the room allows, never a square corner (#185)")
def check_rack_bend_radius_2d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    load_rack_3d_ready(page, base, rack)
    got = page.evaluate("""() => {
      const out = [];
      for (const g of document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id], #paneRear svg [data-cables] [data-cable-id]')) {
        const d = g.querySelector('path:last-of-type')?.getAttribute('d') || '';
        out.push({cable: g.dataset.cableId, quad: /Q/.test(d), arcs: [...d.matchAll(/A([\\d.]+) ([\\d.]+) 0 0 [01] /g)].map(m => +m[1])});
      }
      return out;
    }""")
    routed = [c for c in got if c["arcs"] or c["quad"]]
    if len(got) != 16 or not routed:
        return bad + [f"2D: {len(got)} cables drawn, {len(routed)} routed: nothing to measure"]
    for c in routed:
        if c["quad"]:
            bad.append(f"2D: {c['cable']}'s line still has a square-cut quadratic corner")
        if any(r > 25 + 0.01 for r in c["arcs"]):
            bad.append(f"2D: {c['cable']} has an arc of radius {max(c['arcs'])}, over OM4's 25 mm")
    if not any(25 in c["arcs"] for c in routed):
        bad.append(f"2D: no corner is drawn at the full 25 mm radius: {[c['arcs'] for c in routed]}")
    return bad


BUNDLE_CORNERS_2D_JS = """() => {
  const out = [];
  for (const svg of document.querySelectorAll('#paneFront svg, #paneRear svg')) {
    const inv = svg.getScreenCTM().inverse();
    const sample = p => { const m = inv.multiply(p.getScreenCTM()), pts = [];
      for (let t = 0, L = p.getTotalLength(); t <= L; t += 1) { const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m); pts.push([w.x, w.y]); }
      return pts; };
    for (const g of svg.querySelectorAll('[data-cables] [data-bundle-id]')) {
      const ids = (g.dataset.members || '').split(' ').filter(Boolean), line = {};
      for (const id of ids) {
        const p = [...svg.querySelectorAll(`[data-cables] [data-cable][data-cable-id="${id}"] path`)].sort((a, b) => b.getTotalLength() - a.getTotalLength())[0];
        line[id] = p ? sample(p) : [];
      }
      const stretches = [...g.querySelectorAll('[data-bundle-trunk]')].map(p => {
        const n = +p.dataset.riders, w = +p.getAttribute('stroke-width'), d = p.getAttribute('d');
        // every point of the trunk, arcs included: the n nearest members are all inside the band
        const reach = sample(p).map(c => ids.map(id => line[id].length ? Math.min(...line[id].map(q => Math.hypot(q[0] - c[0], q[1] - c[1]))) : Infinity).sort((a, b) => a - b)[n - 1]);
        return {bundle: g.dataset.bundleId, pane: svg.dataset.pane, d, width: w, riders: n, reach: Math.max(...reach), arcs: [...d.matchAll(/A([\\d.]+) /g)].map(m => +m[1])};
      });
      const straps = [...svg.querySelectorAll(`[data-strap="${g.dataset.bundleId}"]`)].map(s => {
        const l = s.querySelector('line[data-strap-part="core"]:not([data-strap-least])');
        const c = [(+l.getAttribute('x1') + +l.getAttribute('x2')) / 2, (+l.getAttribute('y1') + +l.getAttribute('y2')) / 2];
        const near = ids.map(id => line[id].length ? Math.min(...line[id].map(q => Math.hypot(q[0] - c[0], q[1] - c[1]))) : Infinity).sort((a, b) => a - b);
        return {pack: +s.dataset.pack, nearest: near[0]};
      });
      out.push({bundle: g.dataset.bundleId, pane: svg.dataset.pane, stretches, straps});
    }
  }
  return out;
}"""


@extra("rack.html: a bundle is drawn round the corners its members turn - in 2D its trunk, envelope and straps are arcs of the bundle's bend radius, so every cable it carries stays inside the band at every turn (#185)")
def check_rack_bundle_corners_2d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    for name, fixture, cables in (("pack", PACK_FIXTURE, 4), ("peel", PEEL_FIXTURE, 5)):
        open_front_fixture(page, base, fixture, cables=cables)
        if name == "pack":
            res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3', 'c4'], label: 'pack'})")
            if res.get("error"):
                return bad + [f"create: refused: {res['error']}"]
        page.wait_for_function("() => document.querySelector('#paneFront [data-bundle-id=\"b1\"] [data-bundle-trunk]') && window.__rack.routesCurrent().current", timeout=READY_MS)
        page.wait_for_timeout(400)
        got = page.evaluate(BUNDLE_CORNERS_2D_JS)
        stretches = [s for b in got for s in b["stretches"]]
        if not stretches:
            bad.append(f"{name}: no bundle trunk is drawn on the panes: nothing was measured")
            continue
        # (the pack's trunk turns from the lacer up the lane; the peel's runs straight up it, and ends where its members' arcs begin)
        if name == "pack" and not any(s["arcs"] for s in stretches):
            bad.append(f"{name}: no stretch of the trunk turns a corner on an arc, so the rounding was not measured: {[s['d'] for s in stretches][:4]}")
        for s in stretches:
            # (every rider's stroke inside the band: its centre line within the half width less half a 3 mm stroke)
            if s["reach"] > s["width"] / 2 - 1.5 + 0.3:
                bad.append(f"{name}: {s['riders']} riding on the {s['pane']} pane: a member is {s['reach']:.2f} mm from the trunk's line, outside the half width {s['width'] / 2:.2f} ({s['d']})")
        for b in got:
            for st in b["straps"]:
                if st["nearest"] > st["pack"] / 2 + 2:
                    bad.append(f"{name}: a strap on the {b['pane']} pane is {st['nearest']:.1f} mm from the nearest member, off the pack ({st['pack']} mm)")
    return bad


UNROUTED_HANG_JS = """async () => {
  const s = window.__rack.scene(); await s.complete?.();
  const paths = window.__rack.paths() || {};
  const out = [];
  for (const t of s.rackCables?.tubes ?? []) {
    if (!t.mesh) continue;
    const p = paths[t.link.id];
    const main = t.mesh.children.find(m => m.geometry?.parameters?.path);
    if (!p || !main) continue;
    const reach = e => p.points.find(q => q.at === 'reach' && q.end === e);
    const a = reach('a'), b = reach('b');
    // the whole path, port to port: the length the kit gives counts each plug's leg
    const inner = p.points;
    let kit = 0;
    for (let k = 1; k < inner.length; k++) kit += Math.hypot(inner[k].x - inner[k - 1].x, inner[k].y - inner[k - 1].y, inner[k].z - inner[k - 1].z);
    out.push({id: t.link.id, routed: !!t.routed, kit, drawn: main.geometry.parameters.path.getLength(), reach: !!(a && b)});
  }
  return out;
}"""
# The tube starts at the plug's far end and the kit's path at the port, so the tube is
# short of the path by the plug's body at each end (about 5 mm) and the arcs of its
# corners; the old hang was 48 and 52 mm LONG on this rack.
UNROUTED_HANG_TOL_MM = 16


UNROUTED_2D_JS = """panes => {
  const paths = window.__rack.paths() || {};
  const top = window.__rack.doc().racks[0].frame.heightRU * 44.45;
  const out = [];
  for (const id of Object.keys(paths)) {
    const pts = paths[id].points;
    const along = f => { let s = 0; for (let k = 1; k < pts.length; k++) { const a = f(pts[k - 1]), b = f(pts[k]); s += Math.hypot(...a.map((v, i) => b[i] - v)); } return s; };
    const row = {id, kit: along(q => [q.x, q.y, q.z]), kitFront: along(q => [q.x, q.y]), kitSide: along(q => [q.z, q.y]),
      kitLow: Math.max(...pts.map(q => top - q.y)), drawn: {}};
    for (const pane of panes) {
      const g = document.querySelector(`svg[data-pane="${pane}"] [data-cables] [data-cable-id="${id}"]`);
      // the cable's main stroke is the last path its group draws (a duplex pair's strands come first)
      const p = g ? [...g.querySelectorAll('path')].filter(n => !n.dataset.leader).at(-1) : null;
      if (!p) continue;
      let low = -Infinity;     // the lowest point it reaches: pane y runs down from the top of the rack
      for (let t = 0, L = p.getTotalLength(); t <= L; t += 1) low = Math.max(low, p.getPointAtLength(t).y);
      row.drawn[pane] = {len: p.getTotalLength(), low};
    }
    out.push(row);
  }
  return out;
}"""
# A pane drops the depth (front) or the width (side) of the kit's path, so it is as long as
# the path seen from that side; what is left over is a duplex pair's join (MERGE, 10 mm) and
# the easing of its corners. The old arc was far over that on this rack.
UNROUTED_2D_TOL_MM = 16


@extra("rack.html: an unrouted cable (no waypoints, nothing to go round) is drawn in the Front and Left/Right elevations on the kit's own points, as in 3D, so its drawn 2D length agrees with the kit's")
def check_rack_unrouted_hang_2d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    ends = [("i1", "port-49", "i3", "port-49"), ("i1", "port-50", "i3", "port-53")]
    rack["items"] = [i for i in rack["items"] if i["id"] != "i4"]    # no lacer to route through
    rack["cables"] = [{"id": f"u{n}", "a": {"item": a, "path": x, "view": "front"},
                       "b": {"item": b, "path": y, "view": "front"}, "media": "om4",
                       "purpose": "uplink", "label": "", "route": []} for n, (a, x, b, y) in enumerate(ends, 1)]
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.evaluate("r => window.__rack.replaceRack(r)", rack)
    page.wait_for_function("n => Object.keys(window.__rack.paths() || {}).length === n", arg=len(ends), timeout=READY_MS)
    drawn = "n => document.querySelectorAll('svg[data-pane=\"%s\"] [data-cables] [data-cable-id]').length === n"
    page.wait_for_function(drawn % "front", arg=len(ends), timeout=READY_MS)
    seen = {t["id"]: t for t in page.evaluate(UNROUTED_2D_JS, ["front"])}
    page.click('#view2d [data-view="sides"]')
    page.wait_for_function(drawn % "left", arg=len(ends), timeout=READY_MS)
    page.wait_for_function(drawn % "right", arg=len(ends), timeout=READY_MS)
    sides = {t["id"]: t for t in page.evaluate(UNROUTED_2D_JS, ["left", "right"])}
    for n in range(1, len(ends) + 1):
        f, s = seen.get(f"u{n}"), sides.get(f"u{n}")
        if not f or not s:
            bad.append(f"2D: u{n} has no kit path")
            continue
        for pane, t, want in (("front", f, f["kitFront"]), ("left", s, s["kitSide"]), ("right", s, s["kitSide"])):
            d = t["drawn"].get(pane)
            if not d:
                bad.append(f"2D: u{n} is not drawn on the {pane} pane")
            elif abs(d["len"] - want) > UNROUTED_2D_TOL_MM:
                bad.append(f"2D {pane}: u{n} is drawn {d['len']:.1f} mm long; the kit's path seen from there is {want:.1f} mm (the whole path {t['kit']:.1f} mm)")
        # no lower than the kit's own lowest point (the old arc went about four U under the lower switch)
        d = f["drawn"].get("front")
        if d and d["low"] > f["kitLow"] + UNROUTED_2D_TOL_MM:
            bad.append(f"2D front: u{n} reaches {d['low']:.1f} mm down the pane; the kit's lowest point is {f['kitLow']:.1f}")
    return bad


CORD_WIDTH_JS = """(panes) => {
  const out = {};
  for (const pane of panes) for (const g of document.querySelectorAll(`svg[data-pane="${pane}"] [data-cables] [data-cable-id], svg[data-pane="${pane}"] [data-cables] [data-link-index]`)) {
    const id = g.dataset.cableId ?? `link${g.dataset.linkIndex}`;
    // the cable's main stroke is the last path its group draws, the outline the one before it
    const ps = [...g.querySelectorAll('path')].filter(n => !n.dataset.leader && n.getAttribute('stroke-width'));
    const p = ps.at(-1);
    if (p) out[`${pane}:${id}`] = {media: g.dataset.media, w: +p.getAttribute('stroke-width'), outline: +ps.at(-2)?.getAttribute('stroke-width')};
  }
  return out;
}"""


@extra("rack.html: a power cord is drawn at its cable type's diameter - 7.1 mm for the C13 cord, 7.9 mm for a C19 - in Front / Rear and Left / Right, and every other cable keeps 3 mm (kit 0.34.0 widthOf)")
def check_rack_cord_width(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    for typ, want in ((None, 7.1), ("power-c19", 7.9), ("power-c13", 7.1)):
        rack = json.loads(json.dumps(CABLE_FIXTURE["racks"][0]))
        cord = next(c for c in rack["cables"] if c["id"] == "c2")      # an RJ45 cable between two devices
        cord["media"] = "power"
        if typ:
            cord["type"] = typ
        page.evaluate("r => window.__rack.replaceRack(r)", rack)
        page.wait_for_function("() => document.querySelector('svg[data-pane=\"front\"] [data-cables] [data-link-index]') && window.__rack.routesCurrent().current", timeout=READY_MS)
        got = {"front": page.evaluate(CORD_WIDTH_JS, ["front", "rear"])}
        page.click('#view2d [data-view="sides"]')
        page.wait_for_function("() => document.querySelector('svg[data-pane=\"left\"] [data-cables] [data-cable-id]')", timeout=READY_MS)
        got["sides"] = page.evaluate(CORD_WIDTH_JS, ["left", "right"])
        page.click('#view2d [data-view="faces"]')
        page.wait_for_function("() => document.querySelector('svg[data-pane=\"front\"] [data-cables]')", timeout=READY_MS)
        for view, rows in got.items():
            cords = [(k, r) for k, r in rows.items() if r["media"] == "power"]
            if not cords:
                bad.append(f"{view}, type {typ}: no power cord is drawn: {sorted(rows)}")
            for k, r in cords:
                if abs(r["w"] - want) > 0.01 or abs(r["outline"] - (want + 1.2)) > 0.01:
                    bad.append(f"{view}, type {typ}: {k} is drawn {r['w']} wide with an outline {r['outline']}; expected {want} and {want + 1.2:.1f}")
            for k, r in rows.items():
                if r["media"] != "power" and abs(r["w"] - 3) > 0.01:
                    bad.append(f"{view}, type {typ}: {k} ({r['media']}) is drawn {r['w']} wide; every other cable keeps 3")
    return bad


@extra("rack.html: an unrouted cable (no waypoints, nothing to go round) is drawn in 3D through the kit's own points, so the drawn tube is as long as the length the kit gives, as a routed one is")
def check_rack_unrouted_hang_3d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    rack = json.loads(CABLE_LAY_FIXTURE.read_text())
    rack.pop("_note", None)
    # two cords between the two switches with no manager in the rack: the kit
    # gives them no waypoint and no detour
    ends = [("i1", "port-49", "i3", "port-49"), ("i1", "port-50", "i3", "port-53")]
    rack["items"] = [i for i in rack["items"] if i["id"] != "i4"]    # no lacer to route through
    rack["cables"] = [{"id": f"u{n}", "a": {"item": a, "path": x, "view": "front"},
                       "b": {"item": b, "path": y, "view": "front"}, "media": "om4",
                       "purpose": "uplink", "label": "", "route": []} for n, (a, x, b, y) in enumerate(ends, 1)]
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.evaluate("r => window.__rack.replaceRack(r)", rack)
    page.wait_for_function("n => Object.keys(window.__rack.paths() || {}).length === n", arg=len(ends), timeout=READY_MS)
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the unrouted rack's scene", tubes=True)
    got = {t["id"]: t for t in page.evaluate(UNROUTED_HANG_JS)}
    for n in range(1, len(ends) + 1):
        t = got.get(f"u{n}")
        if not t or not t["reach"]:
            bad.append(f"3D: u{n} has no tube or no kit reach points: {t}")
            continue
        if t["routed"]:
            bad.append(f"3D: u{n} is drawn as a routed cable; the check wants an unrouted one")
        if abs(t["drawn"] - t["kit"]) > UNROUTED_HANG_TOL_MM:
            bad.append(f"3D: u{n}'s tube is {t['drawn']:.1f} mm long; the kit's path from port to port is {t['kit']:.1f} mm")
    return bad


@extra("rack.html: cable lay - beside a rear zero-U Eaton PDU the lane runs outboard of it, and the cable is drawn round the PDU's back in 2D and 3D, never through it")
def check_rack_cable_lay_pdu(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    rack = page.evaluate(PDU_RACK_JS)
    load_rack_3d_ready(page, base, rack)
    paths = page.evaluate("() => window.__rack.paths()")
    p = paths.get("c1")
    routes = dict(page.evaluate("() => window.__rack.routes()"))
    if not p:
        return bad + [f"route: c1 is not measured: {paths}"]
    if not any(w.get("lane") == "right-rear" for w in routes.get("c1", [])):
        bad.append(f"route: c1 does not run up the right-rear lane beside the PDU: {routes.get('c1')}")
    if not p["detours"]:
        bad.append(f"route: c1 has no detour round the PDU: {p}")
    if p["crossings"] or page.evaluate("() => window.__rack.bodies()"):
        bad.append(f"route: c1 still crosses a body: {p['crossings']}")
    # 2D (the rear pane, mirrored, so the right-rear PDU is on its left): the
    # drawn cable goes outboard of the PDU's outer edge, where the lane runs,
    # and passes every detour point.
    geo = page.evaluate("""(p) => {
      const s = document.querySelector('#paneRear svg');
      const g = s.querySelector('[data-cables] [data-cable-id="c1"]');
      const z = s.querySelector('[data-zerou-id="z1"]');
      const inv = s.getScreenCTM().inverse();
      const zb = z.getBoundingClientRect();
      const a = new DOMPoint(zb.left, zb.top).matrixTransform(inv), b = new DOMPoint(zb.right, zb.bottom).matrixTransform(inv);
      const pts = [];
      for (const path of g.querySelectorAll('path')) {
        if (path.dataset.leader) continue;
        const m = inv.multiply(path.getScreenCTM()), L = path.getTotalLength();
        for (let t = 0; t <= L; t += 0.5) { const q = path.getPointAtLength(t); const w = new DOMPoint(q.x, q.y).matrixTransform(m); pts.push([w.x, w.y]); }
      }
      const H = window.__rack.doc().racks[0].frame.heightRU * 44.45, O = 450.85;
      const want = p.detours.flatMap(d => d.points).map(q => [O / 2 - q.x, H - q.y]);
      const miss = want.map(w => Math.min(...pts.map(q => Math.hypot(q[0] - w[0], q[1] - w[1]))));
      // the run up the lane, half way between the two switches (U20)
      const run = pts.filter(q => Math.abs(q[1] - (H - 19.5 * 44.45)) < 60);
      return {pdu: [Math.min(a.x, b.x), Math.max(a.x, b.x)], minX: Math.min(...run.map(q => q[0])), maxX: Math.max(...run.map(q => q[0])),
              mid: O / 2, miss, n: pts.length, run: run.length};
    }""", p)
    if not geo["n"]:
        bad.append("2D: c1 is not drawn on the rear pane")
    else:
        # the lane's run, at U20, is wholly outboard: past the PDU's edge away from the rack's centre
        left = (geo["pdu"][0] + geo["pdu"][1]) / 2 < geo["mid"]
        inner = geo["maxX"] if left else geo["minX"]
        if not geo["run"] or not (inner < geo["pdu"][0] if left else inner > geo["pdu"][1]):
            bad.append(f"2D: the cable's run up the lane at U20 comes to x {inner:.1f} ({geo['run']} samples), "
                       f"not outboard of the PDU ({geo['pdu'][0]:.1f}-{geo['pdu'][1]:.1f})")
        # routed2d rounds each corner by 4 mm, so a detour corner is passed within that
        far = [round(m, 2) for m in geo["miss"] if m > 4.5]
        if far:
            bad.append(f"2D: the drawn cable misses detour points by {far} mm")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the PDU rack's scene", tubes=True)
    bad += tubes_inside(page, 1, want_parts=("z1|envelope",))
    return bad


# A RACK WITH A PDU AND TWO DEVICES THAT TAKE A C14 (portrayal-site#202): the
# PDU on the front face so its C13 outlets are on the front pane, the two
# MX150s with an inlet on the rear.
POWER_RACK_JS = """async () => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.withFrame(M.newRack({name: 'Power', kind: 'four-post'}), {heightRU: 24});
  ({rack: r} = M.withItem(r, {ref: 'pdu12iec', cfg: cat['pdu12iec'].default, ru: 2, label: 'pdu-1'}));
  ({rack: r} = M.withItem(r, {ref: 'mx150', cfg: cat['mx150'].default, ru: 10, label: 'srv-1'}));
  ({rack: r} = M.withItem(r, {ref: 'mx150', cfg: cat['mx150'].default, ru: 14, label: 'srv-2'}));
  return r;
}"""


def power_click(page, pane, item, path):
    """Click the middle of the slot at `path` on `item`'s group in `pane`."""
    sel = f'#pane{pane} svg [data-item-id="{item}"][data-panel] [data-path="{path}"]'
    box = page.evaluate("""sel => { const e = document.querySelector(sel); if (!e) return null;
      const r = e.getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; }""", sel)
    if not box:
        raise RuntimeError(f"power: {path} of {item} is not drawn on the {pane.lower()} pane")
    page.mouse.click(box[0], box[1])


@extra("rack.html: power cords - an inlet and a PDU outlet are picked in Cable mode, the form names each end and offers power, the cord is drawn in 2D and 3D with a plug at each end, listed, edited, warned and deleted, and the exports carry it")
def check_rack_power_cords(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    click = page.click

    def labelled(sel, **kw):
        # a click that times out says which one, not just "Timeout 30000ms"
        try:
            return click(sel, **kw)
        except Exception as e:
            raise RuntimeError(f"power: click {sel}: {str(e).splitlines()[0]}") from e
    page.click = labelled
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.evaluate("r => window.__rack.replaceRack(r)", page.evaluate(POWER_RACK_JS))
    try:
        # Every slot a cord lands on is listed on the panel that draws it, and nothing else is.
        wait_fn(page, "power: the PDU's outlets are listed for picking",
                "() => (document.querySelector('#paneFront svg [data-item-id=\"i1\"][data-panel=\"mounted\"]')?.getAttribute('data-cable-ends') || '').includes('outlet-front-1')")
        ends = page.evaluate("""() => Object.fromEntries([...document.querySelectorAll('[data-item-id][data-panel]')].map(g =>
          [`${g.dataset.itemId}|${g.closest('svg').dataset.pane}`, (g.getAttribute('data-cable-ends') || '').split(' ').filter(Boolean)]))""")
        if ends.get("i1|front") != ["outlet-front-1", "outlet-front-2", "outlet-front-3", "outlet-front-4"]:
            bad.append(f"picking: the PDU's front outlets are {ends.get('i1|front')}")
        if sorted(ends.get("i2|rear", [])) != ["ground-studs", "inlet"]:
            bad.append(f"picking: srv-1's rear slots are {ends.get('i2|rear')}")
        if ends.get("i2|front"):
            bad.append(f"picking: srv-1's front lists slots a cord lands on: {ends.get('i2|front')}")
        page.click("#cableBtn")
        power_click(page, "Rear", "i2", "inlet")
        step = page.text_content("#cableStep") or ""
        if "srv-1" not in step or "inlet" not in step:
            bad.append(f"picking: the inlet was not picked: {step!r}")
        power_click(page, "Front", "i1", "outlet-front-1")
        wait_sel(page, "power: the new-cable form", "#cableForm")
    except RuntimeError as e:
        return bad + [str(e)]
    end_a, end_b = page.text_content("#cEndA") or "", page.text_content("#cEndB") or ""
    if "C14 inlet" not in end_a or "C13 outlet" not in end_b:
        bad.append(f"form: the ends do not say what they are: {end_a!r} / {end_b!r}")
    offered = page.eval_on_selector_all("#cMedia option", "o => o.map(x => x.value)")
    if "power" not in offered or "ground" not in offered:
        bad.append(f"form: the media offered are {offered}")
    if page.input_value("#cMedia") != "power":
        bad.append(f"form: the media proposed for an inlet and an outlet is {page.input_value('#cMedia')!r}")
    if (page.text_content("#cWarn") or "").strip():
        bad.append(f"form: a cord from an outlet to an inlet is warned: {page.text_content('#cWarn')!r}")
    # A ground wire does not suit a power end, and the form says so before it is saved.
    page.select_option("#cMedia", "ground")
    if "does not suit" not in (page.text_content("#cWarn") or ""):
        bad.append(f"form: a ground wire on a power end is not warned: {page.text_content('#cWarn')!r}")
    page.select_option("#cMedia", "power")
    page.click("#cSave")
    try:
        wait_fn(page, "power: the cord is saved", "() => window.__rack.doc().racks[0].cables.length === 1")
        wait_sel(page, "power: the cord on the front pane", 'svg[data-pane="front"] [data-cables] [data-cable-id="c1"]')
        wait_sel(page, "power: the cord on the rear pane", 'svg[data-pane="rear"] [data-cables] [data-cable-id="c1"]')
    except RuntimeError as e:
        return bad + [str(e)]
    c1 = page.evaluate("() => window.__rack.doc().racks[0].cables[0]")
    if c1["media"] != "power" or c1["a"] != {"item": "i2", "path": "inlet", "view": "rear"} \
            or c1["b"] != {"item": "i1", "path": "outlet-front-1", "view": "front"}:
        bad.append(f"saved: the cord is {c1}")
    if page.evaluate("() => !!window.__rack.doc().racks[0].items.some(i => i.swaps && Object.keys(i.swaps).length)"):
        bad.append("saved: a plug was written into an item's swaps (a derived plug is never stored)")
    # A plug is drawn at each end, and the cord ends on its cable point, not on the port's middle.
    seated = page.evaluate("""() => ({
      inlet: !!document.querySelector('#paneRear svg [data-item-id="i2"][data-panel] [data-path="inlet-occupant"]'),
      outlet: !!document.querySelector('#paneFront svg [data-item-id="i1"][data-panel] [data-path="outlet-front-1-occupant"]'),
      refs: [...document.querySelectorAll('[data-path$="-occupant"][data-ref]')].map(e => e.getAttribute('data-ref')).sort()})""")
    if not seated["inlet"] or not seated["outlet"]:
        bad.append(f"2D: the plugs are not drawn at both ends: {seated}")
    if not any("c13-plug" in r for r in seated["refs"]) or not any("c14-plug" in r for r in seated["refs"]):
        bad.append(f"2D: the plugs are not a C13 in the inlet and a C14 in the outlet: {seated['refs']}")
    if page.evaluate("() => document.querySelectorAll('[data-open-plug]').length"):
        bad.append("2D: the cord hangs as an unplugged lead")
    # The list, and the row's own words.
    wait_sel(page, "power: the list row", '#cableList [data-cable-row="c1"]')
    row = page.text_content('#cableItem-c1') or ""
    if "inlet" not in row or "outlet-front-1" not in row or "Power cable" not in row:
        bad.append(f"list: the row reads {row!r}")
    if page.query_selector('#cableItem-c1 [data-loose]'):
        bad.append(f"list: a landed cord has a loose end: {row!r}")
    # 3D: a tube for the cord, hung between the two devices. (Cable mode is left first.)
    if page.get_attribute("#cableBtn", "aria-pressed") == "true":
        page.click("#cableBtn")
    page.click('#mode [data-mode="3d"]')
    try:
        settle_scene(page, "power: 3D", tubes=True)
    except RuntimeError as e:
        bad.append(str(e))
    else:
        got = page.evaluate("() => (window.__rack.scene().three.scene.getObjectByName('patch-cables')?.children || []).map(g => g.name)")
        if got != ["cable-c1"]:
            bad.append(f"3D: the scene's cables are {got}")
    # EDIT: the media changes to ground and the row follows; delete takes the cord and its plugs.
    page.click('#mode [data-mode="2d"]')
    wait_sel(page, "power: the row after 2D", '#cableList [data-cable-row="c1"]')
    if page.get_attribute('#cableList [data-cable-row="c1"]', "aria-pressed") != "true":   # a saved cord is left selected
        page.click('#cableList [data-cable-row="c1"]')
    wait_sel(page, "power: the row's Edit", "#cableEdit")
    page.click("#cableEdit")
    wait_sel(page, "power: the edit form", "#cableForm")
    if page.input_value("#cMedia") != "power":
        bad.append(f"edit: the form opens on {page.input_value('#cMedia')!r}")
    page.select_option("#cMedia", "ground")
    page.click("#cSave")
    try:
        wait_fn(page, "power: the media is saved", "() => window.__rack.doc().racks[0].cables[0].media === 'ground'")
        wait_fn(page, "power: the list says the ground wire does not suit",
                "() => /does not suit end A, which is power/.test(document.querySelector('#cableItem-c1')?.textContent || '')")
    except RuntimeError as e:
        bad.append(str(e))
    wait_sel(page, "power: Edit after a save", "#cableEdit")
    page.click("#cableEdit")
    wait_sel(page, "power: the second edit form", "#cableForm")
    page.select_option("#cMedia", "power")
    page.click("#cSave")
    wait_fn(page, "power: back to power", "() => window.__rack.doc().racks[0].cables[0].media === 'power'")
    # A second cord, outlet to outlet: a warning that is plain, in the list.
    page.evaluate("""() => window.__rack.apply({op: 'cable.add', a: {item: 'i1', path: 'outlet-front-2', view: 'front'},
                                                 b: {item: 'i1', path: 'outlet-front-3', view: 'front'}, media: 'power'})""")
    try:
        wait_fn(page, "power: the outlet-to-outlet cord warns",
                "() => /Both ends are outlets/.test(document.querySelector('#cableItem-c2')?.textContent || '')")
    except RuntimeError as e:
        bad.append(str(e))
    # A GROUND WIRE falls out of the same work: stud to stud, landed, and not called power.
    page.evaluate("""() => window.__rack.apply({op: 'cable.add', a: {item: 'i2', path: 'ground-studs', view: 'rear'},
                                                 b: {item: 'i3', path: 'ground-studs', view: 'rear'}, media: 'ground'})""")
    try:
        wait_sel(page, "power: the ground wire is listed", "#cableItem-c3")
    except RuntimeError as e:
        bad.append(str(e))
    else:
        g = page.text_content("#cableItem-c3") or ""
        if "Ground wire" not in g or "Loose end" in g or "does not suit" in g:
            bad.append(f"ground: the wire's row reads {g!r}")
    # The exports carry the cord: the BOM counts it, the schedule lists it connected.
    bom = pathlib.Path(export_file(page, "bom").path()).read_text(encoding="utf-8")
    if "Power cable" not in bom or "power at both ends" not in bom:
        bad.append(f"BOM: the cords are not counted as landed power cables: {bom!r}")
    sched = pathlib.Path(export_file(page, "cables").path()).read_text(encoding="utf-8")
    if "srv-1,10,inlet,pdu-1,2,outlet-front-1,Power cable" not in sched or "loose end" in sched:
        bad.append(f"schedule: the cords are not listed as connected: {sched!r}")
    # Delete the second, then the first: no cable, no plug left drawn.
    for cid in ("c2", "c1"):
        page.click(f'#cableList [data-cable-row="{cid}"]')
        page.click("#cableDelete")
        wait_fn(page, f"power: {cid} is deleted", f"() => !window.__rack.doc().racks[0].cables.some(c => c.id === '{cid}')")
    wait_fn(page, "power: no plug stays after the cords are deleted",
            "() => !document.querySelector('[data-path$=\"-occupant\"][data-ref*=\"-plug\"]')")
    return bad


# A RACK WITH A VERTICAL PDU AT EACH REAR UPRIGHT (kit 0.36.0, Portrayal
# #1068): a 2U switch with two C20 inlets at U35 and a 1U console with two C14
# inlets at U42, both on the front rails, so their inlets are on the rear pane
# beside the PDUs.
PDU_CORD_RACK_JS = """async () => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.withFrame(M.newRack({name: 'Cords', kind: 'four-post'}), {heightRU: 42});
  ({rack: r} = M.withItem(r, {ref: 's9700-53dx', cfg: cat['s9700-53dx'].default, ru: 35, label: 'sw-1'}));
  ({rack: r} = M.withItem(r, {ref: 'ds1000', cfg: cat['ds1000'].default, ru: 42, label: 'con-1'}));
  return {...r, zeroU: [{id: 'z1', ref: 'evma8365x', cfg: cat['evma8365x'].default, label: 'PDU-A', at: 'left-rear', offsetMm: 0},
                        {id: 'z2', ref: 'evma8365x', cfg: cat['evma8365x'].default, label: 'PDU-B', at: 'right-rear', offsetMm: 0}]};
}"""

# Where a cord's drawn line ends on a pane, against the outlet it ends at: the
# nearest sampled point of its stroke to the outlet's middle, in pane mm.
CORD_AT_OUTLET_JS = """([pane, id, zid, path]) => {
  const s = document.querySelector(`#pane${pane} svg`);
  const g = s?.querySelector(`[data-cables] [data-cable][data-cable-id="${id}"]`);
  const o = s?.querySelector(`[data-zerou-id="${zid}"] [data-path="${path}"]`);
  if (!g || !o) return {drawn: !!g, outlet: !!o};
  const inv = s.getScreenCTM().inverse(), b = o.getBoundingClientRect();
  const c = new DOMPoint(b.left + b.width / 2, b.top + b.height / 2).matrixTransform(inv);
  let best = Infinity;
  for (const p of g.querySelectorAll('path')) {
    if (p.dataset.leader) continue;
    const m = inv.multiply(p.getScreenCTM()), L = p.getTotalLength();
    for (let t = 0; t <= L; t += 0.5) { const q = new DOMPoint(p.getPointAtLength(t).x, p.getPointAtLength(t).y).matrixTransform(m); best = Math.min(best, Math.hypot(q.x - c.x, q.y - c.y)); }
  }
  return {drawn: true, outlet: true, miss: best};
}"""


@extra("rack.html: power cords to a vertical PDU beside the rack (kit 0.36.0) - a PSU inlet and a PDU outlet are picked in Cable mode and the cord saved, a second cord is added by the assistant's edit_rack, and each is drawn to its outlet on the Rear pane with the paired plug, from the side and in 3D, with a length; the assistant lists the PDU's free outlets")
def check_rack_pdu_cords(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.add_init_script(STAND_IN_MODEL_CONTEXT)
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    page.evaluate("r => window.__rack.replaceRack(r)", page.evaluate(PDU_CORD_RACK_JS))
    inlet0 = {"item": "i1", "path": "psu-0/module/inlet", "view": "rear"}
    try:
        # Every outlet of the PDU is listed for picking, on the pane it looks out of.
        wait_fn(page, "pdu: PDU-A's outlets are listed for picking",
                "() => (document.querySelector('#paneRear svg [data-zerou-id=\"z1\"]')?.getAttribute('data-cable-ends') || '').split(' ').includes('outlet-e34')")
        page.click("#cableBtn")
        power_click(page, "Rear", "i1", inlet0["path"])
        step = page.text_content("#cableStep") or ""
        if "sw-1" not in step or "inlet" not in step:
            bad.append(f"picking: the inlet was not picked: {step!r}")
        box = page.evaluate("""() => { const e = document.querySelector('#paneRear svg [data-zerou-id="z1"] [data-path="outlet-e34"]');
          if (!e) return null; const r = e.getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; }""")
        if not box:
            return bad + ["picking: outlet-e34 of PDU-A is not drawn on the rear pane"]
        page.mouse.click(box[0], box[1])
        wait_sel(page, "pdu: the new-cable form", "#cableForm")
    except RuntimeError as e:
        return bad + [str(e)]
    end_a, end_b = page.text_content("#cEndA") or "", page.text_content("#cEndB") or ""
    if "C20 inlet" not in end_a or "PDU-A" not in end_b or "C39 outlet" not in end_b:
        bad.append(f"form: the ends do not say what they are: {end_a!r} / {end_b!r}")
    if page.input_value("#cMedia") != "power":
        bad.append(f"form: the media proposed for an inlet and a PDU outlet is {page.input_value('#cMedia')!r}")
    page.click("#cSave")
    try:
        wait_fn(page, "pdu: the cord is saved", "() => window.__rack.doc().racks[0].cables.length === 1")
    except RuntimeError as e:
        return bad + [str(e)]
    c1 = page.evaluate("() => window.__rack.doc().racks[0].cables[0]")
    if c1["a"] != inlet0 or c1["b"] != {"item": "z1", "path": "outlet-e34", "view": "front"} or c1["media"] != "power":
        bad.append(f"saved: the cord is {c1}")
    # The second cord through the assistant's own tool, as an agent sends it.
    page.click("#cableBtn")
    res = page.evaluate("""() => window.__tools.edit_rack.execute({commands: [{op: 'cable.add', a: {item: 'i2', path: 'psu-1/module/inlet', view: 'rear'},
                                                                       b: {item: 'z2', path: 'outlet-f42', view: 'front'}, media: 'power'}]})
                             .then(r => ({error: !!r.isError, text: r.content[0].text}))""")
    if res["error"]:
        return bad + [f"agent: cable.add to PDU-B was refused: {res['text']}"]
    try:
        wait_fn(page, "pdu: both cords measured",
                "() => { const p = window.__rack.paths(); return !!(p && p.c1?.measured > 0 && p.c2?.measured > 0); }")
        for cid, zid, path in (("c1", "z1", "outlet-e34"), ("c2", "z2", "outlet-f42")):
            wait_sel(page, f"pdu: {cid} on the rear pane", f'svg[data-pane="rear"] [data-cables] [data-cable-id="{cid}"]')
    except RuntimeError as e:
        return bad + [str(e)]
    paths = page.evaluate("() => window.__rack.paths()")
    for cid in ("c1", "c2"):
        m = paths[cid]["measured"]
        if not 0.2 < m < 3:
            bad.append(f"length: {cid} is measured {m} m")
    for cid, zid, path in (("c1", "z1", "outlet-e34"), ("c2", "z2", "outlet-f42")):
        at = page.evaluate(CORD_AT_OUTLET_JS, ["Rear", cid, zid, path])
        if not at.get("drawn") or not at.get("outlet") or at.get("miss", 99) > 20:
            bad.append(f"2D: {cid} is not drawn to {path} of {zid} on the rear pane: {at}")
    # The plug at each outlet is the one that pairs with the cord's other end: a C20 at the C39, a C14 at the C13.
    plugs = page.evaluate("""() => Object.fromEntries(['z1|outlet-e34', 'z2|outlet-f42'].map(k => { const [z, p] = k.split('|');
      return [k, document.querySelector(`#paneRear svg [data-zerou-id="${z}"] [data-path="${p}-occupant"]`)?.getAttribute('data-ref') ?? null]; }))""")
    if "c20-plug" not in (plugs["z1|outlet-e34"] or "") or "c14-plug" not in (plugs["z2|outlet-f42"] or ""):
        bad.append(f"2D: the plugs at the outlets are {plugs}")
    if page.evaluate("() => (window.__rack.doc().racks[0].zeroU || []).some(z => z.swaps && Object.keys(z.swaps).length)"):
        bad.append("saved: a plug was written into a PDU (a derived plug is never stored)")
    row = page.text_content('#cableItem-c1') or ""
    if "PDU-A" not in row or "outlet-e34" not in row or page.query_selector('#cableItem-c1 [data-loose]'):
        bad.append(f"list: c1's row reads {row!r}")
    # The assistant lists PDU-A's free outlets, the one taken left out, nearest U35 first. (A free
    # C39 has no cord to pair with: the kit names its first plug.)
    free = page.evaluate("""() => window.__tools.list_free_ports.execute({id: 'z1', kinds: ['power'], type: 'C39', near: 35})
                              .then(r => ({error: !!r.isError, text: r.content[0].text}))""")
    if free["error"] or not re.match(r"z1 \(PDU-A\): \d+ free ports", free["text"]) or "outlet-e34," in free["text"] \
            or not re.search(r"^[^\n]*\noutlet-e3\d, front: C39 outlet E3\d at U3\d, plug generic/c\d+-plug@1\n", free["text"]):
        bad.append(f"agent: PDU-A's free outlets read {free['text']!r}")
    # From the side: both cords, each with a plug block at each end.
    page.click('#view2d [data-view="sides"]')
    try:
        wait_fn(page, "pdu: the cords from the side",
                "() => ['c1', 'c2'].every(id => document.querySelector(`#paneFront svg [data-cables] [data-cable-id=\"${id}\"]`))")
    except RuntimeError as e:
        bad.append(str(e))
    else:
        blocks = page.evaluate("() => ['c1', 'c2'].map(id => document.querySelectorAll(`#paneFront svg [data-cables] [data-cable-id=\"${id}\"] [data-side-plug]`).length)")
        if blocks != [2, 2]:
            bad.append(f"side: the plug blocks of c1 and c2 are {blocks}, not two each")
    page.click('#view2d [data-view="faces"]')
    # 3D: a tube for each cord, and the plug seated at each outlet.
    page.click('#mode [data-mode="3d"]')
    try:
        settle_scene(page, "pdu: 3D", tubes=True)
    except RuntimeError as e:
        return bad + [str(e)]
    # (the PDUs are the stack's last two mounts, after the rack's two items: scene3d.js sideParts)
    got = page.evaluate("""() => { const s = window.__rack.scene(), rc = s.rackCables;
      return {tubes: (s.three.scene.getObjectByName('patch-cables')?.children || []).map(g => g.name).sort(),
              anchors: (rc?.anchors ?? []).map(a => `${a.i}:${a.side}:${a.anchor.path}`).sort(),
              overrides: s.resolved().stack.slice(2).map(e => e.overrides)}; }""")
    if got["tubes"] != ["cable-c1", "cable-c2"]:
        bad.append(f"3D: the scene's cables are {got['tubes']}")
    if got["overrides"] != [{"outlet-e34": "generic/c20-plug@1"}, {"outlet-f42": "generic/c14-plug@1"}]:
        bad.append(f"3D: the plugs seated on the PDUs are {got['overrides']}")
    for a in ("0:to:outlet-e34-occupant", "1:to:outlet-f42-occupant"):
        if a not in got["anchors"]:
            bad.append(f"3D: no anchor {a} (the cord at its plug) among {got['anchors']}")
    return bad


@extra("rack.html: zero-U - a vertical duct placed beside a two-post rack is drawn in 2D and 3D, a cable's lane runs through it and fills it, narrow brackets go on one rail each, and the exports carry it with no position")
def check_rack_zero_u(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')
    # A 45U two-post (the FS ducts' own rack is the APC AR201, a 45U two-post), a
    # switch at U10 with an optic, a splice panel at U30, one fiber between them.
    built = page.evaluate("""async () => {
      const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
      const cat = (await C.loadCatalog('/assets/dist/')).devices;
      let r = M.withFrame(M.newRack({name: 'Zero-U', kind: 'two-post'}), {heightRU: 45});
      ({rack: r} = M.withItem(r, {ref: 'as7726-32x', cfg: cat['as7726-32x'].default, ru: 10, label: 'leaf-1', swaps: {'port-1': 'generic/qsfp-lc@2'}}));
      ({rack: r} = M.withItem(r, {ref: 'fhd-1ufce', cfg: cat['fhd-1ufce'].default, ru: 30, label: 'pp-1', swaps: {'bay-1': 'fs/fhd-splice-12-lc@3'}}));
      ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-1', view: 'front'}, b: {item: 'i2', path: 'bay-1/module/lc1', view: 'front'}, media: 'os2'}));
      return r;
    }""")
    page.evaluate("r => window.__rack.replaceRack(r)", built)
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id]').length === 1", timeout=READY_MS)
    # Placed through the catalog at U1: beside the left upright, never on the rails.
    page.click('svg[data-pane="front"] rect.rk-u[data-u="1"]')
    page.fill("#catQuery", "CMV-SFD45U5W")
    page.select_option("#catDevice", "cmv-sfd45u5w")
    if page.is_hidden("#catAt"):
        bad.append("picker: a rack-side duct does not offer the upright it stands beside")
    page.select_option("#catAt", "left")
    page.click("#catPlace")
    page.wait_for_function("() => window.__rack.doc().racks[0].zeroU.length === 1", timeout=READY_MS)
    doc = page.evaluate("() => window.__rack.doc().racks[0]")
    z = doc["zeroU"][0]
    if (z.get("ref"), z.get("at"), z.get("offsetMm")) != ("cmv-sfd45u5w", "left", 0) or len(doc["items"]) != 2:
        bad.append(f"place: the duct is not in zeroU at left, offset 0, with the items untouched: {z}, {len(doc['items'])} items")
    page.wait_for_function("() => document.querySelector('#paneFront svg [data-zerou-id=\"z1\"]') && document.querySelector('#paneRear svg [data-zerou-id=\"z1\"]')", timeout=READY_MS)
    # 2D: outside the left rail on the front, outside the right one on the rear (mirrored), portrait.
    geo = page.evaluate("""() => {
      const box = pane => { const s = document.querySelector(`#${pane} svg`), g = s.querySelector('[data-zerou-id="z1"]');
        const m = s.getScreenCTM().inverse().multiply(g.getScreenCTM()), b = g.getBBox();
        const p0 = new DOMPoint(b.x, b.y).matrixTransform(m), p1 = new DOMPoint(b.x + b.width, b.y + b.height).matrixTransform(m);
        return {x0: Math.min(p0.x, p1.x), x1: Math.max(p0.x, p1.x), h: Math.abs(p1.y - p0.y)}; };
      return {front: box('paneFront'), rear: box('paneRear')};
    }""")
    f, r = geo["front"], geo["rear"]
    if not (f["x1"] <= -26 + 0.5 and f["h"] > f["x1"] - f["x0"]):
        bad.append(f"2D: the front pane's duct is not portrait and left of the left rail: {f}")
    if not (r["x0"] >= 450.85 + 26 - 0.5):
        bad.append(f"2D: the rear pane's duct is not right of the (mirrored) left rail: {r}")
    # The cable's lane runs up the duct's channel: its centre line, not the 40 mm gutter.
    page.wait_for_function("() => (window.__rack.routes() || []).some(([id, ws]) => ws.some(w => w.lane === 'left'))", timeout=READY_MS)
    lane = page.evaluate("""() => { const s = document.querySelector('#paneFront svg');
      const g = s.querySelector('[data-cables] [data-cable-id="c1"]'); const xs = [];
      for (const p of g.querySelectorAll('path')) { if (p.dataset.leader) continue; const L = p.getTotalLength();
        for (let t = 0; t <= L; t += 1) xs.push(p.getPointAtLength(t).x); }
      return Math.min(...xs); }""")
    centre = -26 - 138.8 / 2
    if abs(lane - centre) > 2:
        bad.append(f"2D: the cable's lane runs at x {lane}, not through the duct's centre {centre}")
    fill = page.evaluate("() => window.__rack.fill()")
    zf = [x for x in (fill or {}).get("fill", []) if x["item"] == "z1"]
    # ONCE: the kit's fill counts a duct beside the rack (kit 0.6.0, ctx.zeroUAperture),
    # and the page no longer adds its own count of it, which would list it twice.
    if len(zf) != 1 or zf[0]["count"] != 1 or zf[0]["cables"] != ["c1"] or not zf[0].get("zeroU"):
        bad.append(f"fill: the duct is not counted once, by the kit, with the cable through it: {fill}")
    else:
        # Its channel: the drawn guide's 93.4 mm by the part's 165.1 mm depth; one OS2 fiber (3.0 mm) against 40% of it.
        # THE CHANNEL ITSELF, as the page read it off the drawing: one fiber in
        # a duct rounds to 0% whatever the channel is, so the percent alone
        # would pass with any aperture.
        ap = zf[0].get("aperture") or {}
        if (ap.get("w"), ap.get("h"), ap.get("estimated")) != (93.4, 165.1, True):
            bad.append(f"fill: the duct's channel is not the drawn guide's 93.4 mm by the part's 165.1 mm depth, an estimate: {ap}")
        want_pct = round(math.pi * 1.5 ** 2 / (0.4 * 93.4 * 165.1) * 100)
        if zf[0]["percent"] != want_pct or zf[0]["over"]:
            bad.append(f"fill: the duct's percent is not one OS2 fiber in 93.4 x 165.1 mm, {want_pct}%: {zf[0]}")
    zo = [x for x in (fill or {}).get("over", []) if x["item"] == "z1"]
    if zo:
        bad.append(f"fill: one cable is over the duct's stated capacity: {zo}")
    # Selected, it has its own panel; an edit there is one undo step.
    page.click('#paneFront svg [data-zerou-id="z1"] [data-zerou-hit]', force=True)
    page.wait_for_selector("#zeroUPanel", timeout=READY_MS)
    page.check("#zBetween")
    page.wait_for_function("() => window.__rack.doc().racks[0].zeroU[0].between === true", timeout=READY_MS)
    page.evaluate("() => window.__rack.undo()")
    page.wait_for_function("() => !('between' in window.__rack.doc().racks[0].zeroU[0])", timeout=READY_MS)
    # Narrow finger brackets: one on each rail at one U, through the catalog.
    for side in ("right", "left"):
        page.click('svg[data-pane="front"] rect.rk-u[data-u="20"]')
        page.fill("#catQuery", "CMV-5U3W")
        page.select_option("#catDevice", "cmv-5u3w")
        page.select_option("#catSide", side)
        page.click("#catPlace")
        page.wait_for_function("(s) => window.__rack.doc().racks[0].items.some(i => i.ref === 'cmv-5u3w' && i.side === s)", arg=side, timeout=READY_MS)
    # (once the redraw that draws the second is done: the routes now read each plug's reach first)
    page.wait_for_function("() => document.querySelectorAll('#paneFront svg [data-side]').length >= 2", timeout=READY_MS)
    xs = page.evaluate("""() => { const s = document.querySelector('#paneFront svg');
      return Object.fromEntries([...s.querySelectorAll('[data-side]')].map(g => { const b = g.getBoundingClientRect();
        const m = s.getScreenCTM().inverse(); return [g.dataset.side, new DOMPoint(b.left + b.width / 2, 0).matrixTransform(m).x]; })); }""")
    if not (xs.get("left", 999) < 20 and xs.get("right", -999) > 450.85 - 20):
        bad.append(f"2D: the brackets are not on their rails (centres {xs})")
    # A third on a rail already taken there is refused, and changes nothing.
    third = page.evaluate("() => window.__rack.apply({op: 'side.place', ref: 'cmv-5u3w', face: 'front', ru: 22, side: 'left'})")
    n = page.evaluate("() => window.__rack.doc().racks[0].items.filter(i => i.ref === 'cmv-5u3w').length")
    if not (third.get("error") and "Taken by" in third["error"]) or n != 2:
        bad.append(f"side: a second bracket on the left rail at U22 was not refused ({third.get('error')}, {n} brackets)")
    # It survives a reload, sides and all.
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    again = page.evaluate("() => { const r = window.__rack.doc().racks[0]; return {z: r.zeroU.map(z => z.id + '@' + z.at), sides: r.items.filter(i => i.side).map(i => i.side).sort()}; }")
    if again != {"z": ["z1@left"], "sides": ["left", "right"]}:
        bad.append(f"reload: the duct or the brackets' sides did not come back: {again}")
    # DCIM: a device of the rack with no position and no face, its place in the comment.
    page.wait_for_function("() => document.querySelector('#paneFront svg [data-zerou-id=\"z1\"]')", timeout=READY_MS)
    _, kit = export_kit(page, "netbox")
    rows = list(csv.DictReader(io.StringIO(kit["zip"]["2-devices.csv"])))
    duct = [x for x in rows if x["device_type"] == "CMV-SFD45U5W"]
    if not duct or duct[0]["position"] or duct[0]["face"] or duct[0]["rack"] != "Zero-U" or "beside the rack at left" not in duct[0]["comments"]:
        bad.append(f"NetBox: the duct's device row is not in the rack with no position and no face: {duct}")
    if not any(n.endswith("CMV-SFD45U5W.yaml") for n in kit["names"]):
        bad.append("NetBox: the duct's device type (u_height 0) is not in the kit")
    # 3D: stood beside the upright, and the tube runs up its channel.
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D: the zero-U rack's scene", tubes=True)
    res = page.evaluate("""async () => {
      const s = window.__rack.scene(); await s.complete?.();
      const deadline = Date.now() + 20000;
      while (!(s.rackCables?.tubes ?? []).some(t => t.points?.length) && Date.now() < deadline) await new Promise(r => setTimeout(r, 200));
      const g = s.three.scene.getObjectByName('device-z1');
      const pts = (s.rackCables?.tubes ?? []).flatMap(t => t.points || []);
      const sided = Object.fromEntries(window.__rack.doc().racks[0].items.filter(i => i.side).map(i => {
        const b = s.three.scene.getObjectByName(`device-${i.id}`);
        return [i.side, b ? {x: b.position.x, rz: b.rotation.z} : null]; }));
      return {x: g ? g.position.x : null, minX: pts.length ? Math.min(...pts.map(p => p.x)) : null, sided};
    }""")
    want = -(450.85 / 2 + 26 + 138.8 / 2)
    if res["x"] is None or abs(res["x"] - want) > 1:
        bad.append(f"3D: the duct does not stand beside the left upright (x {res['x']}, want {want})")
    if res["minX"] is None or abs(res["minX"] - want) > 8:
        bad.append(f"3D: the tube does not run up the duct's channel (closest x {res['minX']}, want {want})")
    # The brackets stand over their own rails' hole lines (rails.js: 232.55 mm either side), the right one turned.
    sd = res["sided"]
    lx, rx = (sd.get("left") or {}).get("x"), (sd.get("right") or {}).get("x")
    if lx is None or rx is None or abs(lx + 232.55) > 0.5 or abs(rx - 232.55) > 0.5 or abs(abs(sd["right"]["rz"]) - math.pi) > 1e-3:
        bad.append(f"3D: the brackets are not on their rails (left x {lx}, right x {rx}, turned {sd.get('right')})")
    return bad


@extra("rack.html: a version 2 rack an older page saved opens whole - sides, parts beside the rack and their ids - and is saved back as version 4")
def check_rack_v2_migrates(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    # As the site wrote it before kit 0.7.0: version 2, a bracket on one rail,
    # a duct beside the rack, and a second duct an older page left without an id.
    v2 = {"format": "portrayal-rack", "version": 2, "id": "doc-v2-site",
          "racks": [{"id": "r1", "name": "Saved v2", "frame": {"kind": "two-post", "heightRU": 45},
                     "items": [{"id": "i1", "ref": "cmv-5u3w", "cfg": "base", "label": "fb-1", "ru": 20, "face": "front",
                                "turned": False, "swaps": {}, "fields": {}, "side": "right"}],
                     "zeroU": [{"id": "z1", "ref": "cmv-sfd45u5w", "cfg": "base", "label": "vcm-1", "at": "left", "offsetMm": 0},
                               {"ref": "cmv-sfd45u5w", "cfg": "base", "label": "vcm-2", "at": "right", "offsetMm": 0, "between": True}],
                     "cables": []}]}
    page.evaluate("""async doc => {
      await window.__rack.flush();
      await new Promise((res, rej) => { const o = indexedDB.open('portrayal-racks', 1);
        o.onerror = rej; o.onsuccess = () => { const tx = o.result.transaction('docs', 'readwrite');
          tx.objectStore('docs').put({...doc, updatedAt: Date.now() + 60000});
          tx.oncomplete = () => { o.result.close(); res(); }; tx.onerror = rej; }; });
      localStorage.setItem('portrayal.rack.last', doc.id);
    }""", v2)
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    try:
        page.wait_for_function("() => ['z1', 'z2'].every(id => document.querySelector(`#paneFront svg [data-zerou-id=\"${id}\"]`))", timeout=READY_MS)
    except Exception:
        pass   # said below, with what was drawn
    got = page.evaluate("""() => { const d = window.__rack.doc(), r = d.racks[0];
      return {id: d.id, version: d.version, side: r.items.map(i => i.side ?? null), zeroU: r.zeroU.map(z => [z.id, z.at, !!z.between]),
              drawn: ['z1', 'z2'].map(id => !!document.querySelector(`#paneFront svg [data-zerou-id="${id}"]`))}; }""")
    want = {"id": "doc-v2-site", "version": 4, "side": ["right"], "zeroU": [["z1", "left", False], ["z2", "right", True]],
            "drawn": [True, True]}
    if got != want:
        bad.append(f"v2: the saved rack did not open whole as version 4: {got}, expected {want}")
    # One edit, one save: the stored record is version 4 (kit 0.22.0), and keeps what it read.
    page.evaluate("() => window.__rack.apply({op: 'rename', name: 'Saved v3'})")
    stored = page.evaluate("""async () => { await window.__rack.flush();
      return await new Promise((res, rej) => { const o = indexedDB.open('portrayal-racks', 1);
        o.onerror = rej; o.onsuccess = () => { const q = o.result.transaction('docs').objectStore('docs').get('doc-v2-site');
          q.onsuccess = () => { o.result.close(); const d = q.result;
            res(d && {version: d.version, name: d.racks[0].name, side: d.racks[0].items[0]?.side ?? null, zeroU: d.racks[0].zeroU.map(z => z.id)}); };
          q.onerror = rej; }; }); }""")
    if stored != {"version": 4, "name": "Saved v3", "side": "right", "zeroU": ["z1", "z2"]}:
        bad.append(f"v2: after one save the stored rack is not version 4 with its sides and ids: {stored}")
    # The downloaded file is version 4 too (serialize writes VERSION).
    with page.expect_download(timeout=READY_MS) as dl:
        page.click("#libMenu summary")
        page.click("#libItems >> text=Save as .json")
    data = json.loads(pathlib.Path(dl.value.path()).read_text())
    if data.get("version") != 4 or "updatedAt" in data:
        bad.append(f"v2: the downloaded rack file is version {data.get('version')}, not 4, or carries the library's own updatedAt: {sorted(data)}")
    page.evaluate("""async () => { const L = await import('/site/rack/library.js'); const lib = await L.openLibrary(); await lib.remove('doc-v2-site'); }""")
    return bad


@extra("rack.html: Export - a slot emptied by a null swap yields no part, where its default would have seated one")
def check_rack_export_emptied_slot(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)
    got = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js');
      const r = window.__rack.doc().racks[0];
      const it = r.items.find(i => i.id === 'i1');
      const stub = () => ({manufacturer: 'Cisco'});
      const paths = async swaps => (await X.dcimContext({...r, items: [{...it, swaps}]}, stub, 'netbox'))
        .parts.map(p => p.path);
      return {full: await paths({}), emptied: await paths({'slot-5': null})};
    }""")
    if "slot-5/module" not in got["full"]:
        bad.append(f"emptied slot: the default does not seat slot-5 ({got['full']}); the check proves nothing")
    if "slot-5/module" in got["emptied"]:
        bad.append("emptied slot: slot-5 is still a part after a null swap")
    if "slot-4/module" not in got["emptied"]:
        bad.append(f"emptied slot: slot-4's default went missing too: {got['emptied']}")
    return bad


@extra("rack.html: Export - the BOM counts devices, modules, optics and 4 x U of mounting hardware")
def check_rack_export_bom(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)

    def qty(rows, section, key):
        return next((int(r["qty"]) for r in rows if r["section"] == section and key in (r["model"], r["ref"])), None)

    dl = export_file(page, "bom")
    if dl.suggested_filename != "Export-test-bom.csv":
        bad.append(f"BOM: named {dl.suggested_filename!r}")
    cols, rows, text = read_csv(dl)
    if cols != ["section", "qty", "manufacturer", "model", "description", "ref"]:
        bad.append(f"BOM: columns {cols}")
    for section, key, n in (("Devices", "ASR 9006", 1), ("Devices", "AS7726-32X", 1), ("Devices", "TM-280", 2),
                            ("Line cards", "A9K-16X100GE-TR", 1), ("Blanks", "A9K Slot Cover", 5),
                            ("Power supplies", "A9K-3KW-AC", 3), ("Fans", "ASR-9006-FAN", 2),
                            ("Optics", "generic/qsfp-lc@2", 1),
                            ("Mounting hardware", "Cage nut, M6", 52), ("Mounting hardware", "Screw, M6", 52)):
        got = qty(rows, section, key)
        if got != n:
            bad.append(f"BOM: {section} / {key} is {got}, expected {n}")
    if "\r\nNotes\r\n" not in text or "M6" not in text.partition("\r\nNotes\r\n")[2]:
        bad.append(f"BOM: no notes section naming the M6 assumption: {text[-300:]!r}")

    # A cell that opens as a formula is apostrophe-guarded (a model from the
    # ref, a note from the label), through the same builder the menu uses.
    guarded = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js');
      const r = window.__rack.doc().racks[0];
      const item = {...r.items[0], id: 'x1', ref: '=evil', label: '=lbl', swaps: {}};
      return (await X.bomCsv({...r, items: [item]}, () => null)).data;
    }""")
    if "'=evil" not in guarded or "'=lbl" not in guarded or re.search(r"(^|\n)=", guarded):
        bad.append(f"BOM: a formula-like cell is not apostrophe-guarded: {guarded[:300]!r}")

    # A seated ref that is not in the component index keeps its row (model = the ref) and is noted.
    unknown = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), F = await import('/site/rack/face.js');
      const r = window.__rack.doc().racks[0];
      const rack = {...r, items: r.items.filter(i => i.id === 'i1')};
      const chassisOf = () => ({manufacturer: 'Cisco'});
      const before = (await X.bomCsv(rack, chassisOf)).data;
      const ref = before.split('\\n').find(l => l.startsWith('Power supplies,'))?.split(',').pop().trim();
      const list = await F.components();
      const at = list.findIndex(c => `${c.ns}/${c.name}@${c.major.slice(1)}` === ref);
      if (at < 0) return {ref, error: 'ref not found in the index'};
      const [gone] = list.splice(at, 1);
      try { return {ref, data: (await X.bomCsv(rack, chassisOf)).data}; }
      finally { list.splice(at, 0, gone); }
    }""")
    if unknown.get("error"):
        bad.append(f"BOM: unindexed-ref probe could not set up: {unknown}")
    else:
        urows = list(csv.DictReader(io.StringIO(unknown["data"].partition("\r\n\r\nNotes\r\n")[0], newline="")))
        krow = next((r for r in urows if r["ref"] == unknown["ref"]), None)
        if not krow or krow["model"] != unknown["ref"]:
            bad.append(f"BOM: an unindexed seated ref is {krow!r}, expected a row whose model is the ref")
        if "not in the component index" not in unknown["data"]:
            bad.append("BOM: no 'not in the component index' note for an unindexed ref")

    # Tapped rails: screws of the chosen thread, no cage nuts.
    page.click("#frameBtn")
    page.select_option("#fHoles", "tapped")
    page.wait_for_selector("#fThread", timeout=READY_MS)
    page.select_option("#fThread", "12-24")
    page.wait_for_function("() => window.__rack.doc().racks[0].frame.holes.thread === '12-24'", timeout=READY_MS)
    _, rows, _ = read_csv(export_file(page, "bom"))
    if qty(rows, "Mounting hardware", "Screw, 12-24") != 52 or qty(rows, "Mounting hardware", "Cage nut, M6"):
        bad.append(f"BOM tapped: hardware rows {[(r['model'], r['qty']) for r in rows if r['section'] == 'Mounting hardware']}")
    return bad


def notes_status(n):
    return f"Downloaded, with {n} note{'' if n == 1 else 's'} in the file." if n else "Downloaded."


def export_status(page):
    page.wait_for_function("""() => { const t = document.getElementById('exportStatus').textContent;
      return !!t && t !== 'Preparing…'; }""", timeout=READY_3D_MS)
    return page.inner_text("#exportStatus")


@extra("rack.html: a desktop device is flagged in the picker and the exports, placeable, with no ears and no rail hardware")
def check_rack_mount_flag(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    pick(page, "front", 10, "TM-280", "tm-280")
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="tm-280"]', timeout=READY_MS)
    page.click('svg[data-pane="front"] rect.rk-u[data-u="12"]')
    page.fill("#catQuery", "hlx")
    row = page.inner_text('#catDevice option[value="hlx-tgv"]')
    if "desktop" not in row:
        bad.append(f"picker row for hlx-tgv: {row!r}")
    page.select_option("#catDevice", "hlx-tgv")
    fit = page.inner_text("#catFit")
    if fit != "Fits here, on a shelf: this is a desktop device.":
        bad.append(f"picker fit line: {fit!r}")
    if page.is_disabled("#catPlace"):
        bad.append("picker: Place is disabled for a desktop device")
    page.click("#catPlace")
    try:
        page.wait_for_selector('svg[data-pane="front"] [data-device-ref="hlx-tgv"]', timeout=READY_MS)
    except Exception:
        bad.append("a desktop device was not placed")
        return bad
    ears = page.evaluate("""() => [...document.querySelectorAll('svg[data-pane="front"] g.rk-ears')]
      .map(g => document.querySelector(`svg[data-pane="front"] [data-item-id="${g.dataset.earsFor}"][data-device-ref]`)?.dataset.deviceRef)""")
    if "tm-280" not in ears or "hlx-tgv" in ears:
        bad.append(f"ears are drawn for {ears}, expected tm-280 only")
    page.evaluate("() => window.__rack.flush()")

    note = "at U12: a desktop device, so it needs a shelf."
    dl = export_file(page, "sheet-svg")
    svg = pathlib.Path(dl.path()).read_bytes().decode("utf-8")
    if "a desktop device, so it needs a shelf" not in svg:
        bad.append("sheet: no mount note")
    if svg.count("data-ears-for") != 1:
        bad.append(f"sheet: {svg.count('data-ears-for')} ear groups, expected 1")
    _, rows, text = read_csv(export_file(page, "bom"))
    if note not in text.partition("\r\nNotes\r\n")[2]:
        bad.append(f"BOM: no mount note: {text[-300:]!r}")
    cage = next((int(r["qty"]) for r in rows if r["model"] == "Cage nut, M6"), None)
    if cage != 4:
        bad.append(f"BOM: cage nuts {cage}, expected 4 (the rack-mount 1U device only)")
    dev = next((r for r in rows if r["ref"] == "hlx-tgv"), None)
    if not dev:
        bad.append("BOM: the desktop device is not listed")
    crows = device_rows(page, "netbox")
    if not any("needs a shelf" in r["comments"] for r in crows):
        bad.append(f"devices file: no mount comment {[r['comments'] for r in crows]}")
    return bad


@extra("rack.html: a desktop and a DIN-rail device get no 3D ears and are named in the GLB, draw.io, kit README and BOM notes")
def check_rack_mount_flag_3d_exports(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    for u, q, ref in ((10, "TM-280", "tm-280"), (12, "hlx", "hlx-tgv"), (14, "ais2003", "ais2003")):
        pick(page, "front", u, q, ref)
        page.wait_for_selector(f'svg[data-pane="front"] [data-device-ref="{ref}"]', timeout=READY_MS)
    page.evaluate("() => window.__rack.flush()")
    din = "at U14: a DIN-rail device, so it needs a shelf or DIN-rail bracket."
    desk = "at U12: a desktop device, so it needs a shelf."

    # The BOM of a rack holding only these says nothing of cage nuts it does not count.
    only = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      const r = window.__rack.doc().racks[0];
      return (await X.bomCsv({...r, items: r.items.filter(i => i.ref !== 'tm-280')}, of)).data;
    }""")
    if "Cage nuts and screws" in only or "Mounting hardware" in only:
        bad.append(f"BOM of non-rack devices only: hardware or its note present: {only[-300:]!r}")
    if din not in only or desk not in only:
        bad.append("BOM of non-rack devices only: a mount note is missing")

    dl = export_file(page, "drawio")
    xml = pathlib.Path(dl.path()).read_bytes().decode("utf-8")
    if din not in xml or desk not in xml:
        bad.append("draw.io: the mount notes are not in the file")
    _, kit = export_kit(page, "netbox")
    notes = flat_readme(kit["zip"]["README.txt"])
    if din not in notes or desk not in notes:
        bad.append(f"NetBox kit: the README lacks the mount notes: {notes[:400]!r}")
    comments = " ".join(r["comments"] for r in kit_rows(kit, "2-devices.csv"))
    if "A DIN-rail device, so it needs a shelf or DIN-rail bracket." not in comments:
        bad.append(f"devices file: no DIN-rail comment: {comments[:300]!r}")

    page.click("#exportMenu > summary")
    page.click('#exportItems [data-export="to-3d"]')
    settle_scene(page, "3D ears by device: the scene")
    ears = page.evaluate("""async () => {
      const s = window.__rack.scene(); await s.complete();
      const ids = Object.fromEntries(window.__rack.doc().racks[0].items.map(i => [i.ref, i.id]));
      return Object.fromEntries(Object.entries(ids).map(([ref, id]) =>
        [ref, !!s.three.scene.getObjectByName(`ears-${id}`)]));
    }""")
    if ears != {"tm-280": True, "hlx-tgv": False, "ais2003": False}:
        bad.append(f"3D ears by device: {ears}, expected only tm-280")
    dl = export_file(page, "glb", timeout=READY_3D_MS)
    glb = pathlib.Path(dl.path()).read_bytes()
    if din.encode() not in glb or desk.encode() not in glb:
        bad.append("GLB: the mount notes are not in the scene's extras")
    return bad


@extra("rack.html: Export - a model whose 3D view changed under the exporter is not saved or called downloaded")
def check_rack_export_overtaken(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    downloads = []
    page.on("download", lambda d: downloads.append(d.suggested_filename))
    open_fixture(page, base)
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "overtaken by 2D: the scene")
    # save() clicks a download link; counting those is the page's own account
    # of what it offered, with no wait for a download that must not come.
    page.evaluate("""() => { window.__saves = [];
      const click = HTMLAnchorElement.prototype.click;
      HTMLAnchorElement.prototype.click = function () {
        if (this.download) window.__saves.push(this.download);
        return click.call(this); }; }""")
    overtaken = "The 3D view changed before the model was ready. Try the export again."

    # 1. A switch to 2D in the same task as the click: the export has its
    #    scene in hand and has not yet awaited anything, so the scene is
    #    disposed under it every time.
    page.click("#exportMenu > summary")
    page.wait_for_selector('#exportItems [data-export="glb"]', timeout=READY_MS)
    page.evaluate("""() => { document.querySelector('#exportItems [data-export="glb"]').click();
      document.querySelector('#mode [data-mode="2d"]').click(); }""")
    status = export_status(page)
    if status != overtaken:
        bad.append(f"overtaken by 2D: the status reads {status!r}")
    if page.get_attribute("#exportStatus", "title") != status:
        bad.append("overtaken by 2D: the status's title is not its full text, so the cut-off sentence cannot be read")
    saves = page.evaluate("() => window.__saves")
    if saves:
        bad.append(f"overtaken by 2D: a file was offered anyway: {saves}")

    # 2. An edit committed in the same task as the click: the scene on screen
    #    is no longer this rack's, and is rebuilt (disposed) 300 ms later.
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "overtaken by an edit: the scene")
    page.click("#frameBtn")
    page.wait_for_selector("#fNumbering", timeout=READY_MS)
    page.click("#exportMenu > summary")
    page.wait_for_selector('#exportItems [data-export="glb"]', timeout=READY_MS)
    page.evaluate("""() => { window.__saves.length = 0;
      document.querySelector('#exportItems [data-export="glb"]').click();
      const sel = document.getElementById('fNumbering');
      sel.value = 'top-down';
      sel.dispatchEvent(new Event('change', {bubbles: true})); }""")
    if page.evaluate("() => window.__rack.doc().racks[0].frame.numbering") != "top-down":
        return bad + ["overtaken by an edit: the edit did not commit; the check proves nothing"]
    status = export_status(page)
    if status != overtaken:
        bad.append(f"overtaken by an edit: the status reads {status!r}")
    saves = page.evaluate("() => window.__saves")
    if saves:
        bad.append(f"overtaken by an edit: a file was offered anyway: {saves}")
    # The same export, left alone, still downloads.
    settle_scene(page, "overtaken: the scene after the edit")
    dl = export_file(page, "glb", timeout=READY_3D_MS)
    if dl.suggested_filename != "Export-test.glb" or not export_status(page).startswith("Downloaded"):
        bad.append(f"overtaken: an undisturbed export after it gave {dl.suggested_filename!r}, "
                   f"{page.inner_text('#exportStatus')!r}")
    if downloads != ["Export-test.glb"]:
        bad.append(f"overtaken: downloads were {downloads}, expected only the undisturbed one")
    page.click('#mode [data-mode="2d"]')
    return bad


@extra("rack.html: Export - a swap that failed is in the BOM's and the kits' notes; the status counts only what the file carries")
def check_rack_export_notes_truthful(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    fixture = json.loads(json.dumps(EXPORT_FIXTURE))
    fixture["id"] = "doc-export-unseated"
    fixture["racks"][0]["name"] = "Export unseated"
    # A ref the index does not know: the cage keeps what the configuration seats.
    fixture["racks"][0]["items"][1]["swaps"] = {"port-1": "generic/no-such-optic@1"}
    fixture["racks"][0]["items"][1]["fields"] = {}
    open_fixture(page, base, fixture)
    failed = ("leaf-1 at U14: the part chosen for port-1 couldn't be loaded, "
              "so the part the configuration seats there is listed instead.")

    # files.json down: the BOM still comes, and says why manufacturers are blank.
    page.route("**/assets/exports/files.json", lambda r: r.abort())
    _, _, text = read_csv(export_file(page, "bom"))
    page.unroute("**/assets/exports/files.json")
    notes = text.partition("\r\nNotes\r\n")[2]
    if "Manufacturer names could not be loaded, so some are blank." not in notes:
        bad.append(f"BOM without files.json: no note says so: {notes!r}")
    if failed not in notes:
        bad.append(f"BOM: a swap that could not be loaded is not in the notes: {notes!r}")
    if "generic/no-such-optic@1" in text.partition("\r\nNotes\r\n")[0]:
        bad.append("BOM: the part that could not be loaded is listed as if seated; the check's premise is wrong")
    _, _, text = read_csv(export_file(page, "bom"))
    if "Manufacturer names could not be loaded" in text:
        bad.append("BOM: the files.json note is still there once files.json loads")
    status = page.inner_text("#exportStatus")
    n = len([l for l in text.partition("\r\nNotes\r\n")[2].split("\r\n") if l])
    if status != notes_status(n):
        bad.append(f"BOM: {n} notes in the file, but the status reads {status!r}")
    if page.get_attribute("#exportStatus", "title") != status:
        bad.append("status: its title is not its full text")

    for target in ("netbox", "nautobot"):
        _, kit = export_kit(page, target)
        status = export_status(page)
        left, notes = readme_lists(kit["zip"]["README.txt"])
        if failed not in notes:
            bad.append(f"{target} kit: a swap that could not be loaded is not in the README's notes: {notes!r}")
        # The kit's notes are its README's: the blank-settings warning, what is left out, and the notes.
        if status != notes_status(readme_count(kit["zip"]["README.txt"])):
            bad.append(f"{target} kit: the README carries {readme_count(kit['zip']['README.txt'])} notes, but the status reads {status!r}")

    got = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), E = await import('/vendor/rack/export-data.js');
      const r = window.__rack.doc().racks[0];
      const lookup = () => ({manufacturer: 'Edgecore', ru: 1});
      const wired = {...r, items: r.items.filter(i => i.id === 'i2'), zeroU: [{}, {}],
        cables: [{id: 'c1', a: {item: 'i2', path: 'port-1', view: 'front'}, b: {item: 'i2', path: 'port-2', view: 'front'},
                  media: 'os2', purpose: '', label: '', route: []}]};
      const kit = await X.dcimKit(wired, lookup, 'netbox');
      // A model's notes, with a scene that exports nothing: only the notes are under test.
      const scene = {running: () => false, complete: async () => {}, three: {scene: {userData: {}}},
                     toGLB: async () => new Uint8Array(4), toUSDZ: async () => new Uint8Array(4)};
      const ghost = {...r, items: [...r.items, {id: 'i9', ref: 'no-such-device', cfg: 'base', label: 'mystery',
        ru: 22, face: 'front', turned: false, swaps: {}, fields: {}}]};
      const glb = await X.modelFile(scene, ghost, 'glb');
      const extras = [...scene.three.scene.userData.portrayal.notes];
      const usdz = await X.modelFile(scene, ghost, 'usdz');
      return {kitStatus: E.exportStatus(kit), kitNotes: kit.notes, readme: kit.files['README.txt'], glbNotes: glb.notes, extras,
              glbStatus: E.exportStatus(glb), usdzStatus: E.exportStatus(usdz), usdzNotes: usdz.notes};
    }""")
    # A kit carries the cables, so it never says they are left out; what it does leave out (zero-U items) is in its README.
    left, notes = readme_lists(got["readme"])
    if "2 zero-U items are not in this export yet." not in notes or any("cable is not in this export yet" in n for n in left + notes):
        bad.append(f"kit with cables and zero-U items: the README's notes are {notes}")
    if got["kitStatus"] != notes_status(len(got["kitNotes"])) or len(got["kitNotes"]) != readme_count(got["readme"]):
        bad.append(f"kit with cables and zero-U items: {len(got['kitNotes'])} notes, README {readme_count(got['readme'])}, status {got['kitStatus']!r}")
    for note in ("mystery at U22: no front drawing, so the front shows an outline.",
                 "mystery at U22: no rear drawing, so the rear shows an outline."):
        if note not in got["glbNotes"] or note not in got["extras"]:
            bad.append(f"GLB: a device with no drawing is not in the notes ({note!r}): {got['glbNotes']}")
    if got["glbStatus"] != notes_status(len(got["glbNotes"])):
        bad.append(f"GLB: the status reads {got['glbStatus']!r} for {len(got['glbNotes'])} notes")
    if got["usdzStatus"] != "Downloaded. USDZ carries no notes; the GLB does." or got["usdzNotes"]:
        bad.append(f"USDZ: the status reads {got['usdzStatus']!r}, notes {got['usdzNotes']}")
    return bad


EMPTY_FIXTURE = {
    "format": "portrayal-rack", "version": 1, "id": "doc-export-empty",
    "racks": [{
        "id": "r1", "name": "Empty rack",
        "frame": {"kind": "two-post", "heightRU": 12, "numbering": "bottom-up",
                  "holes": {"style": "tapped", "thread": "12-24"},
                  "railDepth": None, "usableDepth": 1000, "ref": None},
        "items": [], "zeroU": [], "cables": []}]}


@extra("rack.html: Export - an empty two-post rack exports every 2D file well formed, and says it has no devices")
def check_rack_export_empty(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base, EMPTY_FIXTURE)
    page.wait_for_selector('svg[data-pane="rear"] rect[data-rail]', timeout=READY_MS)

    def ok_status(kind):
        status = page.inner_text("#exportStatus")
        if not status.startswith("Downloaded"):
            bad.append(f"empty rack {kind}: the status reads {status!r}")

    for kind, name, panes in (("sheet-svg", "Empty-rack-sheet.svg", 2), ("front-svg", "Empty-rack-front.svg", 1),
                              ("rear-svg", "Empty-rack-rear.svg", 1)):
        dl = export_file(page, kind)
        ok_status(kind)
        text = pathlib.Path(dl.path()).read_text(encoding="utf-8")
        try:
            ET.fromstring(text.encode("utf-8"))
        except ET.ParseError as e:
            bad.append(f"empty rack {kind}: not well-formed XML ({e})")
        if dl.suggested_filename != name or text.count("data-pane=") != panes or "Two-post frame, 12U" not in text:
            bad.append(f"empty rack {kind}: {dl.suggested_filename!r} with {text.count('data-pane=')} panes")
        if "data-item-id" in text:
            bad.append(f"empty rack {kind}: a device is drawn")

    dl = export_file(page, "sheet-png")
    ok_status("sheet-png")
    if pathlib.Path(dl.path()).read_bytes()[:8] != b"\x89PNG\r\n\x1a\n":
        bad.append("empty rack sheet-png: not a PNG")

    dl = export_file(page, "drawio")
    ok_status("drawio")
    try:
        d = drawio_page(pathlib.Path(dl.path()).read_text(encoding="utf-8"))
        if d["names"] != ["Empty rack"] or [c["value"] for c in d["cabinets"].values()] != \
                ["Empty rack · front", "Empty rack · rear"] or any(c["holds"] for c in d["cabinets"].values()):
            bad.append(f"empty rack drawio: not one page with an empty front and rear cabinet: {d['names']}, {d['cabinets']}")
    except ET.ParseError as e:
        bad.append(f"empty rack drawio: not well-formed XML ({e})")

    for target, T, files in (("netbox", "NetBox", ["1-rack.csv", "2-devices.csv", "3-modules.csv", "4-cables.csv"]),
                             ("nautobot", "Nautobot", ["1-devices.csv", "2-modules.csv", "3-cables.csv", "import_cables.py"])):
        _, kit = export_kit(page, target)
        ok_status(f"{target}-import")
        if kit["names"] != files + ["README.txt"]:
            bad.append(f"empty rack {T} kit: entries {kit['names']}")
        # Every CSV is there with its header alone - except the NetBox rack file, which is the rack itself.
        for name in files:
            text = kit["zip"].get(name, "")
            if name.endswith(".csv") and text.count("\r\n") != (2 if name == "1-rack.csv" else 1):
                bad.append(f"empty rack {T} kit: {name} is not a header alone: {text!r}")
        readme = kit["zip"]["README.txt"]
        if "This rack has no devices, so there is nothing to import." not in readme_lists(readme)[1] or \
                "Step 1: types/: no files, so there is nothing to import." not in readme or \
                "(no rows: it holds its header only, so skip it)" not in readme:
            bad.append(f"empty rack {T} kit: the README reads {readme!r}")

    cols, rows, text = read_csv(export_file(page, "bom"))
    ok_status("bom")
    if cols != ["section", "qty", "manufacturer", "model", "description", "ref"] or rows:
        bad.append(f"empty rack BOM: columns {cols}, rows {rows}")
    notes = text.partition("\r\nNotes\r\n")[2]
    if "This rack has no devices" not in notes:
        bad.append(f"empty rack BOM: the notes do not say the rack is empty: {text!r}")
    if "Screw" in text or "Cage nut" in text:
        bad.append(f"empty rack BOM: hardware for no devices: {text!r}")

    dl = export_file(page, "json")
    if dl.suggested_filename != "Empty-rack.rack.json":
        bad.append(f"empty rack file: named {dl.suggested_filename!r}")
    return bad


@extra("rack.html: Export - the sheet is the same ink in light and dark, a missing face's outline included")
def check_rack_export_sheet_theme(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    fixture = json.loads(json.dumps(EXPORT_FIXTURE))
    fixture["id"] = "doc-export-theme"
    fixture["racks"][0]["name"] = "Export theme"
    fixture["racks"][0]["items"] = [
        {"id": "i5", "ref": "no-such-device", "cfg": "base", "label": "mystery", "ru": 22, "face": "front",
         "turned": False, "swaps": {}, "fields": {}}]
    seen = {}
    for scheme in ("light", "dark"):
        page.emulate_media(color_scheme=scheme)
        open_fixture(page, base, fixture)
        text = pathlib.Path(export_file(page, "front-svg").path()).read_text(encoding="utf-8")
        root = ET.fromstring(text.encode("utf-8"))
        ns = "{http://www.w3.org/2000/svg}"
        g = next((e for e in root.iter(f"{ns}g") if e.get("data-panel") == "missing"), None)
        if g is None:
            return bad + [f"sheet theme ({scheme}): no missing-face outline in the sheet"]
        rect, label = g.find(f"{ns}rect"), g.find(f"{ns}text")
        seen[scheme] = (rect.get("fill"), rect.get("stroke"), label.get("fill"))
        if "var(--" in text:
            bad.append(f"sheet theme ({scheme}): a theme token is left in the file")
    if seen["light"] != seen["dark"]:
        bad.append(f"sheet: a missing face's outline follows the theme: light {seen['light']}, dark {seen['dark']}")
    # On screen the outline stays the theme's.
    fill = page.evaluate("""() => document.querySelector(
      'svg[data-pane="front"] [data-panel="missing"] rect').getAttribute('fill')""")
    if fill != "var(--pt-surface-2)":
        bad.append(f"the pane's own missing-face outline lost its theme color ({fill})")
    return bad


@extra("the Explorer lens: Escape reads back like Done; a lens showing another device hands back nothing")
def check_rack_lens_edges(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/index.html", wait_until="load")
    page.evaluate("""() => { window.__lens = import('/site/rack/explorer-lens.js').then(L =>
      L.openLens({ref: 'as7726-32x', cfg: 'ac-f2b', title: 'AS7726', swaps: {'port-1': 'generic/qsfp-lc@2'}})); }""")
    page.wait_for_function("() => !!document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed",
                           timeout=READY_MS)
    page.evaluate("async () => { await document.querySelector('.rk-lens iframe').contentWindow.portrayalEmbed.ready; }")
    page.focus(".rk-lens-done")
    page.keyboard.press("Escape")
    r = page.evaluate("async () => await window.__lens")
    if not r or r.get("swaps", {}).get("port-1") != "generic/qsfp-lc@2":
        bad.append(f"lens: Escape read back {r!r}")
    if page.query_selector(".rk-lens"):
        bad.append("lens: the overlay is still open after Escape")
    page.evaluate("""() => { window.__lens2 = import('/site/rack/explorer-lens.js').then(L =>
      L.openLens({ref: 'no-such-device', cfg: 'base', title: 'Nothing'})); }""")
    page.click(".rk-lens-done", timeout=READY_MS)
    got2 = page.evaluate("async () => await window.__lens2")
    if got2 is not None:
        bad.append(f"lens: a lens that never showed its device handed back {got2!r}")
    # A reload whose new document never becomes ready: the lens was shown once,
    # but that is not this document, so Done hands back nothing.
    page.evaluate("""() => { window.__lens3 = import('/site/rack/explorer-lens.js').then(L =>
      L.openLens({ref: 'as7726-32x', cfg: 'ac-f2b', title: 'AS7726'})); }""")
    page.wait_for_function("() => !!document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed",
                           timeout=READY_MS)
    page.evaluate("async () => { await document.querySelector('.rk-lens iframe').contentWindow.portrayalEmbed.ready; }")
    # The lens resets itself in its own `load` listener. This listener is added
    # after the lens's, so it runs after it: once it has fired for the NEW
    # document (the one carrying the marker), the lens has seen the reload.
    # The old document also has a portrayalEmbed and is also `complete`, so
    # nothing short of the marker and the event tells the two apart.
    page.evaluate("""() => { const f = document.querySelector('.rk-lens iframe');
      window.__lens3Loads = 0;
      f.addEventListener('load', () => { if (f.contentWindow.portrayalEmbed?.lens3) window.__lens3Loads++; });
      f.srcdoc =
      '<script>window.portrayalEmbed = {lens3: true, ready: new Promise(() => {}), ' +
      'current: () => ({device: "as7726-32x", config: "ac-f2b", swaps: {}, fields: {}})}<' + '/script>'; }""")
    page.wait_for_function("() => window.__lens3Loads > 0", timeout=READY_MS)
    page.click(".rk-lens-done", timeout=READY_MS)
    got3 = page.evaluate("async () => await window.__lens3")
    if got3 is not None:
        bad.append(f"lens: a reload that never became ready handed back {got3!r}")
    return bad


@extra("rack.html: the library menu renames and marks the current rack; the summary lists depth warnings")
def check_rack_menu_and_warnings(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.once("dialog", lambda d: d.accept("Renamed rack"))
    page.click("#libMenu > summary")
    page.click("#libItems button:has-text('Rename')")
    page.wait_for_function("() => window.__rack.doc().racks[0].name === 'Renamed rack'", timeout=READY_MS)
    if (page.text_content("#rackName") or "") != "Renamed rack":
        bad.append("menu: the rack name in the bar did not follow a rename")
    page.click("#libMenu > summary")
    # The list is redrawn when the menu opens; wait for that draw, not the previous one.
    try:
        page.wait_for_function("() => document.querySelector('#libItems .rk-current')?.textContent === 'Renamed rack'",
                               timeout=READY_MS)
    except Exception:
        cur = page.evaluate("() => document.querySelector('#libItems .rk-current')?.textContent ?? null")
        bad.append(f"menu: the current rack is marked {cur!r}")
    page.click("#libMenu > summary")
    pick(page, "front", 10, "R740", "r740xd")
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="r740xd"][data-panel="mounted"]', timeout=READY_MS)
    page.click("#frameBtn")
    page.fill("#fUsable", "500")
    page.dispatch_event("#fUsable", "change")
    page.wait_for_function("() => window.__rack.doc().racks[0].frame.usableDepth === 500", timeout=READY_MS)
    page.click("#frameBtn")                       # back to the summary
    page.wait_for_selector(".rk-side .rk-error", timeout=READY_MS)
    if "this rack allows 500 mm" not in (page.text_content(".rk-side") or ""):
        bad.append(f"summary: no depth warning for the R740xd ({page.text_content('.rk-side')!r})")
    return bad


@extra("rack.html: the frame form keeps keyboard focus across a change")
def check_rack_frame_focus(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
