@extra("rack.html: place from the picker; both faces show it; a device that won't fit says why")
def check_rack_place(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    # A fresh, empty rack, whatever an earlier check left in this browser.
    open_new_rack(page, "place")

    pick(page, "front", 10, "R740", "r740xd")
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="r740xd"][data-panel="mounted"]', timeout=READY_MS)
    page.wait_for_selector('svg[data-pane="rear"] [data-device-ref="r740xd"][data-panel="through"]', timeout=READY_MS)
    pick(page, "front", 20, "AS7726", "as7726-32x")
    page.wait_for_selector('svg[data-pane="rear"] [data-device-ref="as7726-32x"][data-panel="through"]', timeout=READY_MS)
    # Behind the switch: the patch panel is too deep, the TM-280 fits - the
    # FHD-1UFCE needs "Only what fits here" off to even show up. AS7726's
    # through panel now covers this U's own hit rectangle, so this dispatches
    # straight to it rather than a real, position-based click.
    page.dispatch_event('svg[data-pane="rear"] rect.rk-u[data-u="20"]', "click")
    page.uncheck("#catFitsOnly")
    page.fill("#catQuery", "FHD")
    opt_text = page.text_content('#catDevice option[value="fhd-1ufce"]') or ""
    if not opt_text.endswith("— doesn't fit"):
        bad.append(f"place: the FHD-1UFCE's option text is {opt_text!r}, expected it to end with \"doesn't fit\"")
    page.select_option("#catDevice", "fhd-1ufce")
    why = page.text_content("#catFit") or ""
    if "mm free behind" not in why:
        bad.append(f"place: the FHD-1UFCE's reason is {why!r}, expected a depth reason")
    before = page.evaluate("() => window.__rack.doc().racks[0].items.length")
    page.click("#catPlace")
    after = page.evaluate("() => window.__rack.doc().racks[0].items.length")
    if after != before:
        bad.append(f"place: pressing Place on a device that doesn't fit added an item ({before} -> {after})")
    pick(page, "rear", 20, "TM-280", "tm-280", dispatch=True)
    page.wait_for_selector('svg[data-pane="rear"] [data-device-ref="tm-280"][data-panel="mounted"]', timeout=READY_MS)
    doc = page.evaluate("() => window.__rack.doc()")
    got = [(i["ref"], i["ru"], i["face"], i["cfg"]) for i in doc["racks"][0]["items"]]
    want = [("r740xd", 10, "front", "sff24-rc5-1b2a3a"), ("as7726-32x", 20, "front", "ac-f2b"),
            ("tm-280", 20, "rear", doc["racks"][0]["items"][2]["cfg"])]
    if got != want:
        bad.append(f"place: items {got}, expected {want}")
    return bad


@extra("rack.html: inspect, move with arrows, face refusal, Explorer round trip, remove")
def check_rack_inspect(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("dialog", lambda d: d.accept())
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    open_new_rack(page, "inspect")
    pick(page, "front", 20, "AS7726", "as7726-32x")
    item = lambda: page.evaluate("() => window.__rack.doc().racks[0].items[0]")
    page.wait_for_selector("#iLabel", timeout=READY_MS)
    # Move with the arrow keys.
    page.keyboard.press("ArrowUp"); page.keyboard.press("ArrowUp")
    page.wait_for_function("() => window.__rack.doc().racks[0].items[0].ru === 22")
    # Another device at U22 on the rear; switching the switch's face to rear is
    # refused. AS7726's own through panel now covers this U's hit rectangle
    # on the rear pane, so this dispatches straight to it.
    pick(page, "rear", 22, "TM-280", "tm-280", dispatch=True)
    # The TM-280 just placed has an inspector with an #iFace of its own: the
    # one changed has to be the AS7726's, drawn by this click's render. The
    # place's own render is waited out first, or it could be the one met.
    wait_fn(page, "inspect: TM-280 placed",
        "() => window.__rack.doc().racks[0].items.length === 2 && !document.getElementById('catPlace')")
    tok = render_token(page)
    page.click('svg[data-pane="front"] [data-device-ref="as7726-32x"]')
    wait_rendered(page, "inspect: AS7726 selected", tok)
    page.select_option("#iFace", "rear")
    err = page.text_content(".rk-side .rk-error") or ""
    if "Taken by" not in err or item()["face"] != "front":
        bad.append(f"inspect: a face change onto an occupied U was not refused ({err!r}, {item()['face']})")
    # Label edit.
    page.fill("#iLabel", "tor-1"); page.dispatch_event("#iLabel", "change")
    page.wait_for_function("() => window.__rack.doc().racks[0].items[0].label === 'tor-1'")
    # Move by clicking a U while in move mode: a free U changes ru and face.
    page.click("#iMove")
    page.wait_for_selector(".rk-side h3:has-text('Move tor-1')", timeout=READY_MS)
    page.click('svg[data-pane="rear"] rect.rk-u[data-u="5"]')
    page.wait_for_function(
        "() => window.__rack.doc().racks[0].items[0].ru === 5 && window.__rack.doc().racks[0].items[0].face === 'rear'",
        timeout=READY_MS)
    # Moving by click onto an occupied U is refused; the reason must survive
    # the redraw (it is written through S.notice, not into the panel the
    # redraw is about to replace), and the item stays where it was.
    page.click("#iMove")
    page.wait_for_selector(".rk-side h3:has-text('Move tor-1')", timeout=READY_MS)
    # The occupying device's own panel is drawn over its U's hit rectangle
    # (elevation.js: "a click on a device is the device's"), so a real click
    # there would hit the device, not the U - dispatch straight to the rect,
    # the same target the app's own click handler reads ev.target from.
    page.dispatch_event('svg[data-pane="rear"] rect.rk-u[data-u="22"]', "click")
    # The reason is written through S.notice, as .rk-notice.rk-error, and
    # only reaches the DOM once the redraw it triggers (select() -> render())
    # finishes - unlike the synchronous onPatch refusals above (which land in
    # the inspector's own, always-present .rk-error), this one needs a wait
    # on the distinct .rk-notice element, not an immediate read of the first
    # .rk-error in the panel.
    page.wait_for_selector(".rk-side .rk-notice", timeout=READY_MS)
    err = page.text_content(".rk-side .rk-notice") or ""
    if "Taken by" not in err or item()["ru"] != 5 or item()["face"] != "rear":
        bad.append(f"inspect: a move-by-click onto an occupied U was not refused ({err!r}, {item()['ru']}, {item()['face']!r})")
    # Move it back to the front for the rest of this check.
    page.click("#iMove")
    page.click('svg[data-pane="front"] rect.rk-u[data-u="10"]')
    page.wait_for_function(
        "() => window.__rack.doc().racks[0].items[0].ru === 10 && window.__rack.doc().racks[0].items[0].face === 'front'",
        timeout=READY_MS)
    # Explorer round trip: seat an optic in the lens through its own URL state.
    page.click("#iExplore")
    page.wait_for_selector(".rk-lens iframe", timeout=READY_MS)
    # A synchronous predicate: a Promise returned from wait_for_function is truthy at once.
    page.wait_for_function("() => !!document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed",
                           timeout=READY_MS)
    page.evaluate("async () => { await document.querySelector('.rk-lens iframe').contentWindow.portrayalEmbed.ready; }")
    page.evaluate("""() => {
      const w = document.querySelector('.rk-lens iframe').contentWindow;
      // swap= is written raw (it carries its own escaping), so it is appended, not set.
      const rest = w.location.search.replace(/&?swap=[^&]*/, '');
      w.location.replace(`${w.location.pathname}${rest}&swap=port-1~generic%2Fqsfp-lc%402`);
    }""")
    # Synchronous polling: the reloaded frame's API exists and reports the swap.
    page.wait_for_function("""() => {
      const w = document.querySelector('.rk-lens iframe')?.contentWindow;
      try { return !!w?.portrayalEmbed && !!w.portrayalEmbed.current().swaps['port-1']; } catch { return false; } }""",
                           timeout=READY_MS)
    # Done reads back only a settled Explorer; the swap can show a moment before.
    page.wait_for_function("() => document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed?.settled === true",
                           timeout=READY_MS)
    page.click(".rk-lens-done")
    page.wait_for_function("() => (window.__rack.doc().racks[0].items[0].swaps || {})['port-1'] === 'generic/qsfp-lc@2'",
                           timeout=READY_MS)
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="as7726-32x"] [data-ref^="generic/qsfp-lc@2"]',
                           timeout=READY_MS)
    # A configuration change clears swaps and fields (a delta against the old
    # configuration), and the page says so once, beside the panel it redraws.
    page.select_option("#iCfg", "ac-b2f")
    page.wait_for_function("() => window.__rack.doc().racks[0].items[0].cfg === 'ac-b2f'", timeout=READY_MS)
    page.wait_for_selector(".rk-side .rk-notice", timeout=READY_MS)
    note = page.text_content(".rk-side .rk-notice") or ""
    if "cleared" not in note:
        bad.append(f"inspect: a configuration change did not show the cleared-changes note ({note!r})")
    if item()["swaps"] or item()["fields"]:
        bad.append(f"inspect: a configuration change left swaps/fields behind ({item()['swaps']!r}, {item()['fields']!r})")
    # A configuration changed inside Explorer changes the item's own cfg too.
    page.click("#iExplore")
    page.wait_for_selector(".rk-lens iframe", timeout=READY_MS)
    page.wait_for_function("() => !!document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed",
                           timeout=READY_MS)
    page.evaluate("async () => { await document.querySelector('.rk-lens iframe').contentWindow.portrayalEmbed.ready; }")
    page.evaluate("""() => {
      const w = document.querySelector('.rk-lens iframe').contentWindow;
      const u = new URL(w.location.href);
      u.searchParams.set('config', 'dc-f2b');
      w.location.replace(u.toString());
    }""")
    # Synchronous polling: the reloaded frame's API exists and reports the config.
    page.wait_for_function("""() => {
      const w = document.querySelector('.rk-lens iframe')?.contentWindow;
      try { return !!w?.portrayalEmbed && w.portrayalEmbed.current().config === 'dc-f2b'; } catch { return false; } }""",
                           timeout=READY_MS)
    page.wait_for_function("() => document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed?.settled === true",
                           timeout=READY_MS)
    page.click(".rk-lens-done")
    page.wait_for_function("() => window.__rack.doc().racks[0].items[0].cfg === 'dc-f2b'", timeout=READY_MS)
    # Remove.
    page.click('svg[data-pane="front"] [data-device-ref="as7726-32x"]')
    page.click("#iRemove")
    page.wait_for_function("() => !window.__rack.doc().racks[0].items.some(i => i.ref === 'as7726-32x')")
    return bad


@extra("rack.html: the device picker narrows by vendor, respects fit, and remembers state across U clicks")
def check_rack_picker(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    open_new_rack(page, "picker")

    device_refs = lambda: page.eval_on_selector_all("#catDevice option", "os => os.map(o => o.value)")
    fits_false = lambda: page.eval_on_selector_all(
        "#catDevice option", "os => os.filter(o => o.dataset.fits === 'false').length")

    # Near the top of the rack only 3U is free, so any 4U-and-up device does
    # not fit here - unticking "Only what fits here" has to reveal some.
    # Each U click waits for its own render: #catDevice alone is met by the
    # picker the last click (or Place) left on screen.
    tok = render_token(page)
    page.click('svg[data-pane="front"] rect.rk-u[data-u="40"]')
    wait_rendered(page, "picker: U40 picker opens", tok)
    if fits_false() != 0:
        bad.append("picker: an option has data-fits=false while 'Only what fits here' is ticked")
    page.uncheck("#catFitsOnly")
    if fits_false() == 0:
        bad.append("picker: unticking 'Only what fits here' revealed nothing that doesn't fit")
    page.check("#catFitsOnly")

    # Lower in the rack, where everything fits: the vendor dropdown narrows
    # the list, and its counts match what the query alone already narrowed to.
    tok = render_token(page)
    page.click('svg[data-pane="front"] rect.rk-u[data-u="10"]')
    wait_rendered(page, "picker: U10 picker opens", tok)

    # "All vendors"'s own count matches the (unfiltered) device list, and the
    # list box fills the side panel's width rather than shrinking to its
    # longest option's intrinsic width.
    all_count = len(device_refs())
    all_text = page.eval_on_selector('#catVendor option[value="all"]', "o => o && o.textContent") or ""
    m_all = re.search(r"\((\d+)\)", all_text)
    if not m_all or int(m_all.group(1)) != all_count:
        bad.append(f"picker: 'All vendors' says {all_text!r} but the device list has {all_count} devices")
    device_width = page.eval_on_selector("#catDevice", "s => s.getBoundingClientRect().width")
    panel_width = page.eval_on_selector(".rk-picker", "el => el.getBoundingClientRect().width")
    if device_width < panel_width * 0.9:
        bad.append(f"picker: #catDevice is {device_width}px wide, less than 90% of the {panel_width}px panel")

    page.fill("#catQuery", "AS77")
    vendor_text = page.eval_on_selector('#catVendor option[value="Edgecore"]', "o => o && o.textContent")
    if not vendor_text:
        bad.append("picker: no Edgecore option in #catVendor for the 'AS77' search")
    else:
        page.select_option("#catVendor", "Edgecore")
        refs = device_refs()
        m = re.search(r"\((\d+)\)", vendor_text)
        if not m or int(m.group(1)) != len(refs):
            bad.append(f"picker: Edgecore's count says {vendor_text!r} but the list has {len(refs)} devices")
        if "as7726-32x" not in refs:
            bad.append("picker: as7726-32x is missing from the filtered Edgecore list")

    # A device with several configurations preselects its default; choosing
    # another one and placing stores that configuration.
    page.select_option("#catDevice", "as7726-32x")
    cfg_value = page.eval_on_selector("#catCfg", "s => s.value")
    if cfg_value != "ac-f2b":
        bad.append(f"picker: as7726-32x's preselected configuration is {cfg_value!r}, expected its default 'ac-f2b'")
    page.select_option("#catCfg", "dc-b2f")
    page.click("#catPlace")
    doc = page.evaluate("() => window.__rack.doc()")
    item = doc["racks"][0]["items"][0]
    if item["ref"] != "as7726-32x" or item["cfg"] != "dc-b2f":
        bad.append(f"picker: placed {item['ref']!r} with cfg {item['cfg']!r}, expected as7726-32x/dc-b2f")

    # Clicking another empty U keeps the chosen vendor and query. The
    # place's own render is waited out first, or it could be the one met.
    wait_fn(page, "picker: as7726-32x placed",
        "() => window.__rack.doc().racks[0].items.length === 1 && !document.getElementById('catPlace')")
    tok = render_token(page)
    page.click('svg[data-pane="front"] rect.rk-u[data-u="30"]')
    wait_rendered(page, "picker: U30 picker opens", tok)
    if page.eval_on_selector("#catQuery", "i => i.value") != "AS77":
        bad.append("picker: the search query did not survive clicking another U")
    if page.eval_on_selector("#catVendor", "s => s.value") != "Edgecore":
        bad.append("picker: the vendor filter did not survive clicking another U")
    return bad


@extra("rack.html: zoom defaults to Fit, reads relative to it, ctrl+wheel is anchored at the pointer without drift, and it survives a reload")
def check_rack_zoom(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")

    level = lambda: page.text_content("#zoomLevel") or ""
    front_box = lambda: page.eval_on_selector('svg[data-pane="front"]', "s => s.getBoundingClientRect()")
    panes_box = lambda: page.eval_on_selector('#panes', "p => p.getBoundingClientRect()")

    if level() != "Fit":
        bad.append(f"zoom: on load the readout is {level()!r}, expected 'Fit'")
    fh, ph = front_box()["height"], panes_box()["height"]
    if fh > ph + 1:
        bad.append(f"zoom: the front SVG's height {fh} exceeds the panes' client height {ph} at Fit")
    fit_width = front_box()["width"]

    # The readout is relative to Fit (a controller ruling), not to the raw
    # column-width factor: two 1.25x steps up from Fit is 1.5625x Fit, which
    # reads as ~156% regardless of what Fit's own factor happens to be in
    # this window.
    page.click("#zoomIn"); page.click("#zoomIn")
    m = re.search(r"(\d+)%", level())
    if not m or abs(int(m.group(1)) - 156) > 1:
        bad.append(f"zoom: two zoom-ins from Fit read {level()!r}, expected about 156%")
    if front_box()["width"] <= fit_width:
        bad.append("zoom: #zoomIn twice did not make the SVG wider than its Fit width")
    before_pct = int(m.group(1)) if m else 0
    page.click("#zoomIn")
    m2 = re.search(r"(\d+)%", level())
    if not m2 or int(m2.group(1)) <= before_pct:
        bad.append(f"zoom: zooming in again did not increase the displayed percentage ({level()!r})")
    zoomed_width = front_box()["width"]

    # Anchoring works by adjusting scrollLeft/scrollTop, which the browser
    # clamps to [0, scrollWidth - clientWidth]: below the zoom level where a
    # pane actually needs a scrollbar, that range is just {0} and no
    # scrollLeft assignment can compensate, so growing from a fixed left edge
    # unavoidably drifts. That's a limit of panning via native overflow, not
    # the bug being fixed here - so this reaches a level that genuinely
    # overflows before testing the anchor invariant.
    for _ in range(10):
        if page.eval_on_selector("#panes", "p => p.scrollWidth > p.clientWidth + 1"):
            break
        page.click("#zoomIn")
    else:
        bad.append("zoom: could not reach a horizontally-overflowing zoom level to test wheel anchoring")

    # ctrl+wheel is anchored at the pointer: a fixed point in the viewport
    # has to land on the same fraction of the SVG's own box before and after
    # - not drift, which a coarser anchor built from column width alone
    # would do, since it leaves out the panes' padding, the gap between the
    # two panes, and the heading above the SVG. The point is clamped to the
    # panes' own visible box (not just a fraction of the SVG's full,
    # possibly-taller-than-the-viewport box), so Playwright's mouse actually
    # lands inside the window rather than off-screen.
    r, pb = front_box(), panes_box()
    fx = r["x"] + min(r["width"], pb["width"]) * 0.3
    fy = r["y"] + min(r["height"], pb["height"]) * 0.5
    fraction = lambda: (lambda b: ((fx - b["x"]) / b["width"], (fy - b["y"]) / b["height"]))(front_box())
    before_fraction = fraction()
    page.mouse.move(fx, fy)
    page.keyboard.down("Control")
    page.mouse.wheel(0, -300)
    page.keyboard.up("Control")
    after_fraction = fraction()
    if (abs(before_fraction[0] - after_fraction[0]) > 0.01
            or abs(before_fraction[1] - after_fraction[1]) > 0.01):
        bad.append(f"zoom: ctrl+wheel drifted the pointer's anchor in the SVG - "
                   f"fraction {before_fraction} -> {after_fraction}, expected <=1% drift")
    if front_box()["width"] <= zoomed_width:
        bad.append("zoom: ctrl+wheel over the panes did not increase the width further")

    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    if "%" not in level():
        bad.append(f"zoom: after a reload the readout is {level()!r}, expected the zoom to survive")

    page.click("#zoomFit")
    if level() != "Fit":
        bad.append(f"zoom: #zoomFit did not return the readout to 'Fit' ({level()!r})")
    return bad


@extra("rack.html: deleting a rack does not let a pending autosave resurrect it")
def check_rack_delete(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("dialog", lambda d: d.accept())
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    boot_id = page.evaluate("() => window.__rack.doc().id")
    page.click("#libMenu summary")
    page.click("#libItems >> text=New rack")
    # "New rack" is fired-and-forgotten from its click handler; window.__rack.ready
    # is only boot()'s promise, already settled, so it cannot be waited on again -
    # wait on the one thing that does change: the active document's id.
    page.wait_for_function("(id) => window.__rack.doc().id !== id", arg=boot_id, timeout=READY_MS)
    deleted_id = page.evaluate("() => window.__rack.doc().id")
    # A commit queues a 500ms autosave. Deleting right after it - the case
    # that used to resurrect the rack - means that timer is still pending
    # when remove() runs.
    page.click("#frameBtn")
    page.fill("#fHeight", "24")
    page.dispatch_event("#fHeight", "change")
    page.wait_for_function("""() => document.querySelectorAll('svg[data-pane="front"] rect.rk-u').length === 24""",
                           timeout=READY_MS)
    page.click("#libMenu summary")
    page.click("#libItems >> text=Delete…")
    page.wait_for_function("(id) => window.__rack.doc().id !== id", arg=deleted_id, timeout=READY_MS)
    # Give a stale 500ms timer, if it is still armed, a chance to fire and
    # queue a put() before we flush and check the library.
    page.wait_for_timeout(700)
    page.evaluate("() => window.__rack.flush()")
    remaining = page.evaluate("""async (id) => {
      const {openLibrary} = await import('/site/rack/library.js');
      const lib = await openLibrary();
      const list = await lib.list();
      return list.some(d => d.id === id);
    }""", deleted_id)
    if remaining:
        bad.append("rack page: a deleted rack came back after its pending autosave flushed")
    return bad


@extra("rack.html: opening a .json whose id is already in the library never overwrites it, and switching docs flushes a pending edit first")
def check_rack_import_keeps_library(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    orig_id = page.evaluate("() => window.__rack.doc().id")

    def set_height(h, wait_redraw=True):
        # #frameBtn toggles the frame form open/closed, so only click it when
        # the form isn't already showing (a second call would otherwise close it).
        if not page.is_visible("#fHeight"):
            page.click("#frameBtn")
        page.fill("#fHeight", str(h))
        page.dispatch_event("#fHeight", "change")
        # dispatch_event runs the change handler (commit(), which updates
        # S.doc synchronously) before returning, so the redraw itself need
        # not be waited on to know the new height is already in S.doc - and
        # for the pending-edit case below, waiting on it would only give a
        # 500ms autosave timer more time to land on its own.
        if wait_redraw:
            page.wait_for_function(
                f"""() => document.querySelectorAll('svg[data-pane="front"] rect.rk-u').length === {h}""",
                timeout=READY_MS)

    # First edit: flush it, then save the doc (as it stands, height 20) to a
    # file - this is the file we later re-import.
    set_height(20)
    page.evaluate("() => window.__rack.flush()")
    first_doc = page.evaluate("() => window.__rack.doc()")
    tmp_path = pathlib.Path(tempfile.mkstemp(suffix=".rack.json")[1])
    tmp_path.write_text(json.dumps(first_doc))

    # Second edit, left pending (no explicit flush): switching to the same
    # rack from the library list must flush it first, or the switch reads
    # back the stale, pre-edit copy. The autosave lands 500ms after the edit,
    # so the edit and the switch are fired from a single page.evaluate (no
    # round trip between them) to make the race deterministic rather than
    # dependent on how long Playwright's own IPC happens to take.
    page.click("#libMenu summary")   # renders #libItems, including the current-rack button, ahead of time
    # A synchronous predicate: the library list redraws asynchronously, and the click below
    # is in the same page task as the edit, with no room to wait for the row there.
    page.wait_for_function("() => !!document.querySelector('#libItems button.rk-current')", timeout=READY_MS)
    page.evaluate("""() => {
      const h = document.getElementById('fHeight');
      h.value = '30';
      h.dispatchEvent(new Event('change', {bubbles: true}));
      document.querySelector('#libItems button.rk-current').click();
    }""")
    # Give the click handler (its getDoc/setDoc) and the 500ms autosave timer
    # both time to fully settle before reading the final state - the height
    # can read 30 transiently (before the switch's own read lands) and then
    # drop back to a stale value, so an early poll would miss that.
    page.wait_for_timeout(800)
    got = page.evaluate("() => window.__rack.doc().racks[0].frame.heightRU")
    if got != 30:
        bad.append(f"library switch: doc height is {got} after switching to the current rack, expected 30 "
                    "(a pending edit was lost)")
    page.evaluate("() => window.__rack.flush()")

    # Now import the earlier file (id = orig_id, height 20). The library
    # already holds a document with that id (the one just edited to height
    # 30): importing must not overwrite it.
    page.set_input_files("#openFile", str(tmp_path))
    try:
        page.wait_for_function("(id) => window.__rack.doc().id !== id", arg=orig_id, timeout=5000)
    except Exception:
        pass
    imported = page.evaluate("() => window.__rack.doc()")
    if imported["id"] == orig_id:
        bad.append("import: the imported document kept the original file's id")
    if imported["racks"][0]["frame"]["heightRU"] != 20:
        bad.append(f"import: imported doc height is {imported['racks'][0]['frame']['heightRU']}, expected 20")

    docs = page.evaluate("""async () => {
      const {openLibrary} = await import('/site/rack/library.js');
      const lib = await openLibrary();
      return await lib.list();
    }""")
    if len(docs) != 2:
        bad.append(f"import: library holds {len(docs)} document(s), expected 2 "
                    "(the edited original plus the import)")
    orig = page.evaluate("""async (id) => {
      const {openLibrary} = await import('/site/rack/library.js');
      const lib = await openLibrary();
      return await lib.get(id);
    }""", orig_id)
    if not orig or orig["racks"][0]["frame"]["heightRU"] != 30:
        bad.append(f"import: the original rack in the library reads height "
                    f"{orig and orig['racks'][0]['frame']['heightRU']}, expected 30 (its latest edit)")
    tmp_path.unlink(missing_ok=True)
    return bad


@extra("rack.html: without IndexedDB the note shows, both faces still draw, and Save as .json still works")
def check_rack_no_idb(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.add_init_script("Object.defineProperty(window, 'indexedDB', {value: undefined})")
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    if page.is_hidden("#libNote"):
        bad.append("rack page without IndexedDB: #libNote is not shown")
    counts = page.evaluate("""() => ['front', 'rear'].map(f =>
      document.querySelectorAll(`svg[data-pane="${f}"] rect.rk-u`).length)""")
    if counts != [42, 42]:
        bad.append(f"rack page without IndexedDB: U targets {counts}, expected [42, 42]")
    with page.expect_download() as download_info:
        page.click("#libMenu summary")
        page.click("#libItems >> text=Save as .json")
    saved = pathlib.Path(download_info.value.path())
    data = json.loads(saved.read_text())
    if data.get("format") != "portrayal-rack":
        bad.append(f"rack page without IndexedDB: downloaded file format is {data.get('format')!r}, expected 'portrayal-rack'")
    # Without a library, New rack still counts up rather than naming every rack "Rack 1".
    page.on("dialog", lambda d: d.dismiss())
    for want in ("Rack 2", "Rack 3"):
        page.click("#libMenu > summary")
        page.click("#libItems button:has-text('New rack')")
        try:
            page.wait_for_function("(n) => window.__rack.doc().racks[0].name === n", arg=want, timeout=5000)
        except Exception:
            bad.append(f"rack page without IndexedDB: New rack is named {page.evaluate('() => window.__rack.doc().racks[0].name')!r}, expected {want!r}")
            break
    return bad


def wait_fn(page, label, expr, timeout=READY_MS, arg=None):
    # page.wait_for_function, but a timeout says which step it was - CI-only
    # failures otherwise all look identical ("Timeout 60000ms exceeded.")
    # with no clue which of a dozen waits in the check actually stalled.
    try:
        page.wait_for_function(expr, arg=arg, timeout=timeout)
    except Exception as e:
        raise RuntimeError(f"{label}: {str(e).splitlines()[0]}") from e


def wait_sel(page, label, selector, timeout=READY_MS, state=None):
    # Playwright's default is to wait until the element is VISIBLE, and an SVG
    # group is visible only if its box has an area: a cable that is one
    # vertical stroke (both ends at one x) has a zero-width box and never is.
    # A cable group or a cable layer is therefore waited for as ATTACHED, so no
    # check depends on where its fixture's ports happen to be.
    if state is None and ("[data-cable-id" in selector or "[data-cables" in selector):
        state = "attached"
    try:
        return page.wait_for_selector(selector, timeout=timeout, **({"state": state} if state else {}))
    except Exception as e:
        raise RuntimeError(f"{label}: {str(e).splitlines()[0]}") from e


def u_center(page, face, u):
    box = page.eval_on_selector(
        f'svg[data-pane="{face}"] rect.rk-u[data-u="{u}"]',
        "el => { const r = el.getBoundingClientRect(); return {x: r.x + r.width / 2, y: r.y + r.height / 2}; }")
    return box["x"], box["y"]


def render_token(page):
    # commit() (rack-page.js) writes the new ru/face onto window.__rack.doc()
    # synchronously, then fires its `render()` WITHOUT awaiting it - render()
    # is itself async (drawElevation awaits configuredFace per item), so the
    # doc model can read as moved a tick before the DOM does. Locally that gap
    # closes before Playwright's next command round-trips; on a loaded CI
    # runner it doesn't, and a bare u_center()+mouse.down() right after the
    # model wait grabs a stale (or momentarily missing) panel, so a fresh drag
    # never even starts. render() replaces both pane <svg>s wholesale on every
    # draw, so capturing the front one here and waiting for it to become a
    # different node (below) is a precise, synchronous "the DOM caught up"
    # signal - not a fixed sleep or frame count.
    return page.evaluate_handle('() => document.querySelector(\'svg[data-pane="front"]\')')


def wait_rendered(page, label, token, timeout=READY_MS):
    try:
        page.wait_for_function(
            'old => document.querySelector(\'svg[data-pane="front"]\') !== old', arg=token, timeout=timeout)
    except Exception as e:
        raise RuntimeError(f"{label}: {str(e).splitlines()[0]}") from e
    finally:
        token.dispose()


@extra("rack.html: drag a device to move it, across faces, with fit feedback and Esc to cancel")
def check_rack_drag(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    wait_fn(page, "initial ready", "() => window.__rack && window.__rack.ready")
    page.evaluate("() => window.__rack.ready")
    open_new_rack(page, "drag")

    pick(page, "front", 20, "AS7726", "as7726-32x")
    wait_sel(page, "place as7726-32x on front U20",
             'svg[data-pane="front"] [data-device-ref="as7726-32x"][data-panel="mounted"]')

    # Drag it from front U20 to front U25 - coordinates come from the U rects'
    # own boxes at the moment of each move, since the layout does not change
    # mid-drag but the rack could be scrolled or zoomed differently than the
    # values above assume.
    x0, y0 = u_center(page, "front", 20)
    page.mouse.move(x0, y0)
    page.mouse.down()
    for u in (22, 25):
        x, y = u_center(page, "front", u)
        page.mouse.move(x, y, steps=3)
    # Mid-drag: a preview outline, a live status line, and the dragged group
    # dimmed - all before the drop.
    if page.eval_on_selector_all("rect.rk-drop", "els => els.length") != 1:
        bad.append("drag: no single rect.rk-drop preview shown mid-drag")
    status = page.text_content("#dragStatus") or ""
    if not status.strip():
        bad.append("drag: #dragStatus has no text mid-drag")
    opacity = page.eval_on_selector('svg[data-pane="front"] [data-device-ref="as7726-32x"]',
                                     "el => getComputedStyle(el).opacity")
    if float(opacity) >= 0.99:
        bad.append(f"drag: the dragged group is not dimmed mid-drag (opacity {opacity})")
    tok = render_token(page)
    page.mouse.up()
    wait_fn(page, "same-pane drag front U20 -> U25",
        "() => window.__rack.doc().racks[0].items[0].ru === 25 && window.__rack.doc().racks[0].items[0].face === 'front'")
    wait_rendered(page, "same-pane drag front U20 -> U25: DOM settle", tok)

    # Drag it onto the rear pane: the face switches.
    x0, y0 = u_center(page, "front", 25)
    page.mouse.move(x0, y0)
    page.mouse.down()
    xr, yr = u_center(page, "rear", 25)
    page.mouse.move((x0 + xr) / 2, y0, steps=2)
    page.mouse.move(xr, yr, steps=3)
    tok = render_token(page)
    page.mouse.up()
    wait_fn(page, "cross-face drag front -> rear U25", "() => window.__rack.doc().racks[0].items[0].face === 'rear'")
    wait_rendered(page, "cross-face drag front -> rear U25: DOM settle", tok)

    # A device already on rear U30 refuses a drop onto it, unchanged, and the
    # reason - not the whole side panel - is what tells the user why.
    pick(page, "rear", 30, "TM-280", "tm-280")
    wait_sel(page, "place tm-280 on rear U30",
             'svg[data-pane="rear"] [data-device-ref="tm-280"][data-panel="mounted"]')
    before = page.evaluate("() => window.__rack.doc().racks[0].items[0]")
    x0, y0 = u_center(page, "rear", before["ru"])
    page.mouse.move(x0, y0)
    page.mouse.down()
    x30, y30 = u_center(page, "rear", 30)
    page.mouse.move(x0, (y0 + y30) / 2, steps=2)
    page.mouse.move(x30, y30, steps=3)
    page.mouse.up()
    wait_sel(page, "refused drop onto occupied rear U30 shows notice", ".rk-side .rk-notice")
    err = page.text_content(".rk-side .rk-notice") or ""
    after = page.evaluate("() => window.__rack.doc().racks[0].items[0]")
    if "Taken by" not in err:
        bad.append(f"drag: dropping onto an occupied U was not refused with 'Taken by' ({err!r})")
    if after["ru"] != before["ru"] or after["face"] != before["face"]:
        bad.append(f"drag: a refused drop changed the item ({before} -> {after})")

    # Some engines (Firefox, Safari) fire a trailing 'click' after a drag that
    # used setPointerCapture; Chromium in this harness does not. Either way,
    # that echo must never be treated as a fresh click - simulate the
    # Firefox-style trailing click here and check it did not re-select or
    # clear the refusal notice still showing from the drop above.
    page.evaluate("""() => {
      const g = document.querySelector('svg[data-pane="rear"] [data-device-ref="as7726-32x"]');
      g.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true}));
    }""")
    err_after_echo = page.text_content(".rk-side .rk-notice") or ""
    if "Taken by" not in err_after_echo:
        bad.append(f"drag: a synthetic trailing click after a refused drop cleared the notice ({err_after_echo!r})")

    # A real click right after that - on an empty U - still opens the picker:
    # the echo must not have swallowed this one instead.
    page.click('svg[data-pane="front"] rect.rk-u[data-u="1"]')
    wait_sel(page, "real click on empty front U1 opens picker", "#catQuery")

    # A short click (no movement) still selects.
    page.click('svg[data-pane="rear"] [data-device-ref="as7726-32x"]')
    wait_sel(page, "short click on rear device selects it", "#iLabel")

    # Esc mid-drag cancels: the item stays exactly where it was.
    before = page.evaluate("() => window.__rack.doc().racks[0].items[0]")
    x0, y0 = u_center(page, "rear", before["ru"])
    page.mouse.move(x0, y0)
    page.mouse.down()
    page.mouse.move(x0, max(0, y0 - 80), steps=3)
    page.keyboard.press("Escape")
    page.mouse.up()
    after = page.evaluate("() => window.__rack.doc().racks[0].items[0]")
    if after["ru"] != before["ru"] or after["face"] != before["face"]:
        bad.append(f"drag: Esc mid-drag did not cancel ({before} -> {after})")

    # Two-post: front and rear are the same plane, so dragging one device onto
    # the other's U (even on the other face) is refused.
    open_new_rack(page, "two-post setup")
    page.click("#frameBtn")
    page.select_option("#fKind", "two-post")
    wait_fn(page, "two-post setup: frame kind switched", "() => window.__rack.doc().racks[0].frame.kind === 'two-post'")
    pick(page, "front", 10, "TM-280", "tm-280")
    wait_sel(page, "two-post: place tm-280 on front U10",
             'svg[data-pane="front"] [data-device-ref="tm-280"][data-panel="mounted"]')
    # The second device sits on the FRONT too (at U20): dragging the first
    # one onto the REAR at U20 makes the candidate's face differ from the
    # occupant's, which is exactly the two-post case ("one plane"), not a
    # same-face "Taken by" collision.
    pick(page, "front", 20, "TM-280", "tm-280")
    wait_fn(page, "two-post: second tm-280 placed on front U20",
            "() => window.__rack.doc().racks[0].items.length === 2")
    x0, y0 = u_center(page, "front", 10)
    page.mouse.move(x0, y0)
    page.mouse.down()
    x20, y20 = u_center(page, "rear", 20)
    page.mouse.move((x0 + x20) / 2, (y0 + y20) / 2, steps=2)
    page.mouse.move(x20, y20, steps=3)
    page.mouse.up()
    wait_sel(page, "two-post refused cross-face drop shows notice", ".rk-side .rk-notice")
    tp_err = page.text_content(".rk-side .rk-notice") or ""
    if "two-post rails are shared" not in tp_err:
        bad.append(f"drag: a two-post drop onto the other face's U was not refused as shared rails ({tp_err!r})")

    # Part 1's regression: a stale S.sel from an earlier click on an EMPTY U
    # (its catalog panel left open) must not keep painting that U's brass
    # highlight forever - a later drag of an unrelated device has to replace
    # the selection, on both a same-pane and a cross-pane drop.
    open_new_rack(page, "stale-selection setup")
    pick(page, "front", 20, "AS7726", "as7726-32x")
    wait_sel(page, "stale-selection setup: place as7726-32x on front U20",
             'svg[data-pane="front"] [data-device-ref="as7726-32x"][data-panel="mounted"]')
    page.click('svg[data-pane="rear"] rect.rk-u[data-u="12"]')
    wait_sel(page, "stale-selection: click empty rear U12 opens picker", "#catQuery")
    x0, y0 = u_center(page, "front", 20)
    page.mouse.move(x0, y0)
    page.mouse.down()
    xf, yf = u_center(page, "front", 7)
    page.mouse.move((x0 + xf) / 2, (y0 + yf) / 2, steps=2)
    page.mouse.move(xf, yf, steps=3)
    tok = render_token(page)
    page.mouse.up()
    wait_fn(page, "same-pane drag front U20 -> U7 after stale selection",
        "() => window.__rack.doc().racks[0].items[0].ru === 7 && window.__rack.doc().racks[0].items[0].face === 'front'")
    # The stray-rect check below reads rk-u-selected, which drawElevation only
    # sets during the (async) render triggered by this drop - without waiting
    # for it, a stale pre-drop DOM could still show the old selection and be
    # misread as the bug this block exists to catch.
    wait_rendered(page, "same-pane drag front U20 -> U7 after stale selection: DOM settle", tok)
    stray = page.eval_on_selector_all("rect.rk-drop, rect.rk-u-selected", "els => els.length")
    if stray != 0:
        bad.append(f"drag: a stale rk-drop/rk-u-selected rect stayed after a same-pane drop ({stray} found)")

    # Repeat across a cross-pane drop: select empty rear U5 (opens the
    # catalog there), then drag the device from front to rear.
    page.click('svg[data-pane="rear"] rect.rk-u[data-u="5"]')
    wait_sel(page, "stale-selection: click empty rear U5 opens picker", "#catQuery")
    x0, y0 = u_center(page, "front", 7)
    page.mouse.move(x0, y0)
    page.mouse.down()
    xr, yr = u_center(page, "rear", 15)
    page.mouse.move((x0 + xr) / 2, y0, steps=2)
    page.mouse.move(xr, yr, steps=3)
    tok = render_token(page)
    page.mouse.up()
    wait_fn(page, "cross-pane drag front U7 -> rear U15 after stale selection",
        "() => window.__rack.doc().racks[0].items[0].face === 'rear'")
    wait_rendered(page, "cross-pane drag front U7 -> rear U15 after stale selection: DOM settle", tok)
    stray2 = page.eval_on_selector_all("rect.rk-drop, rect.rk-u-selected", "els => els.length")
    if stray2 != 0:
        bad.append(f"drag: a stale rk-drop/rk-u-selected rect stayed after a cross-pane drop ({stray2} found)")
    return bad


def open_new_rack(page, label):
    # NEW RACK IS ASYNCHRONOUS, AND THE PAGE ALREADY HOLDS AN EMPTY RACK.
    # startNewRack (rack-page.js) flushes the autosave, lists the library and
    # stores the new document - three IndexedDB round trips - before setDoc()
    # swaps it in. A fresh page boots with an empty rack of its own, so a wait
    # for "no items" is met at once, before the click has done anything; the
    # new rack then lands in the middle of whatever the check does next and
    # wipes it. What says the switch happened is the document's id changing,
    # and then the new document's own render: a pane already on screen (or
    # one painted by a render still in flight from the step before) is the
    # last document's. So each repaint of the front pane is logged with the
    # document it was drawn for, and the wait is for a paint of the new one -
    # after which the panes and the side panel are this rack's, and a
    # render_token taken next is its pane.
    rid = page.evaluate("""() => {
      window.__paints = [];
      if (!window.__paintLog) {
        window.__paintLog = new MutationObserver(() => window.__paints.push(window.__rack.doc().id));
        window.__paintLog.observe(document.getElementById('paneFront'), {childList: true});
      }
      return window.__rack.doc().id;
    }""")
    page.click("#libMenu > summary"); page.click("#libItems button:has-text('New rack')")
    wait_fn(page, f"{label}: New rack opens a new document, drawn",
        "(id) => { const now = window.__rack.doc().id; return now !== id"
        " && window.__rack.doc().racks[0].items.length === 0 && window.__paints.includes(now); }", arg=rid)


@extra("rack.html: shrinking the frame compacts, then trims from the bottom, with Undo")
def check_rack_shrink(page, base):
    # Every step waits on the page's own state, never on time: the document
    # for the edit, and the render that follows it (render() is async and
    # paints the panes and the side panel together, last) for anything read
    # off or clicked in the DOM. Under load the model moves well before the
    # DOM does, and a check that reads the panel in between reads the last one.
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    open_new_rack(page, "shrink")

    # 1U, 1U and a 2U device, at U5, U20 and U30 of a 42U rack. Each place
    # is waited for until its render has replaced the picker: a picker still
    # on screen when the next U is clicked is the last U's, and its Place
    # button places there (and is refused, as that U is now taken).
    for n, (u, query, ref) in enumerate([(5, "MX204", "mx204"), (20, "AS7726", "as7726-32x"), (30, "R740", "r740xd")], 1):
        pick(page, "front", u, query, ref)
        wait_fn(page, f"shrink: {ref} placed at U{u}",
            "(n) => window.__rack.doc().racks[0].items.length === n && !document.getElementById('catPlace')", arg=n)
    sorted_items = lambda: sorted(page.evaluate("() => window.__rack.doc().racks[0].items"), key=lambda i: i["ru"])

    def set_height(ru):
        # The form is the one the last render drew, and the edit's own render
        # draws the notice: wait for that render, not just the model.
        tok = render_token(page)
        page.fill("#fHeight", str(ru))
        page.dispatch_event("#fHeight", "change")
        wait_fn(page, f"shrink: the frame becomes {ru}U",
            "(ru) => window.__rack.doc().racks[0].frame.heightRU === ru", arg=ru)
        wait_rendered(page, f"shrink: the frame becomes {ru}U: DOM settle", tok)
        notice = page.query_selector(".rk-side .rk-notice")
        return notice.text_content() if notice else None

    tok = render_token(page)
    page.click("#frameBtn")
    wait_rendered(page, "shrink: the frame form opens", tok)
    note = set_height(12)
    got = [(i["ref"], i["ru"]) for i in sorted_items()]
    want = [("mx204", 1), ("as7726-32x", 2), ("r740xd", 3)]
    if got != want:
        bad.append(f"shrink: after compacting to 12U items are {got}, expected {want}")
    if note is None or "moved" not in note.lower():
        bad.append(f"shrink: the notice does not mention moving devices ({note!r})")

    # Shrinking further to 3U (from the 12U-compacted state, top at U4) means
    # 1+1+2 = 4U of devices no longer fit in 3U: the bottom one (MX204) goes.
    note2 = set_height(3)
    refs = [i["ref"] for i in sorted_items()]
    if refs != ["as7726-32x", "r740xd"]:
        bad.append(f"shrink: shrinking to 3U left {refs}, expected the bottom device (mx204) removed")
    if note2 is None or "MX204" not in note2:
        bad.append(f"shrink: the removal notice does not name MX204 ({note2!r})")

    # Undo restores the rack from just before this shrink - the 12U-compacted
    # state, frame included - exactly. The Undo clicked is the 3U render's.
    page.click("#undoShrink")
    wait_fn(page, "shrink: Undo puts the rack back",
        "() => window.__rack.doc().racks[0].items.length === 3")
    got2 = [(i["ref"], i["ru"]) for i in sorted_items()]
    if got2 != want:
        bad.append(f"shrink: Undo did not restore the pre-shrink positions, got {got2}")
    if page.evaluate("() => window.__rack.doc().racks[0].frame.heightRU") != 12:
        bad.append("shrink: Undo did not restore the pre-shrink frame height")
    return bad


@extra("rack.html: each pane shows a device's real panel, ears on the mounted face, through/mounted precedence")
def check_rack_faces(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    open_new_rack(page, "faces")

    # MX204 (short of a four-post's rear rail) at front U10, TM-280 at rear
    # U10: a four-post pair sharing a U.
    pick(page, "front", 10, "MX204", "mx204")
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="mx204"][data-panel="mounted"]', timeout=READY_MS)
    # MX204's own through panel now covers this same U's hit rectangle on the
    # rear pane, so this dispatches straight to it.
    pick(page, "rear", 10, "TM-280", "tm-280", dispatch=True)
    page.wait_for_selector('svg[data-pane="rear"] [data-device-ref="tm-280"][data-panel="mounted"]', timeout=READY_MS)

    mx_id = page.eval_on_selector('svg[data-pane="front"] [data-device-ref="mx204"]', "el => el.dataset.itemId")
    tm_id = page.eval_on_selector('svg[data-pane="rear"] [data-device-ref="tm-280"]', "el => el.dataset.itemId")

    # Front pane: MX204 is mounted, with ears.
    if not page.query_selector(f'svg[data-pane="front"] g.rk-ears[data-ears-for="{mx_id}"]'):
        bad.append("faces: no rk-ears group for the front-mounted MX204 in the front pane")

    # Rear pane: MX204 shows its real rear panel as `through`, with no ears;
    # TM-280 is `mounted` there, with ears, and comes after (on top of)
    # MX204's through panel in document order.
    mx_rear = page.query_selector('svg[data-pane="rear"] [data-device-ref="mx204"][data-panel="through"]')
    if not mx_rear:
        bad.append("faces: MX204's rear panel is not data-panel=through in the rear pane")
    elif not mx_rear.query_selector('[data-path="cutout:esd-rear"]'):
        bad.append("faces: the rear pane does not show MX204's real rear panel (missing cutout:esd-rear)")
    if page.query_selector(f'svg[data-pane="rear"] g.rk-ears[data-ears-for="{mx_id}"]'):
        bad.append("faces: MX204's through panel in the rear pane has ears, expected none")
    if not page.query_selector(f'svg[data-pane="rear"] g.rk-ears[data-ears-for="{tm_id}"]'):
        bad.append("faces: no rk-ears group for the rear-mounted TM-280 in the rear pane")
    order = page.eval_on_selector('svg[data-pane="rear"]', """(svg, ids) => {
      const a = svg.querySelector(`[data-item-id="${ids[0]}"][data-panel="through"]`);
      const b = svg.querySelector(`[data-item-id="${ids[1]}"][data-panel="mounted"]`);
      return !!(a && b) && !!(a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING);
    }""", [mx_id, tm_id])
    if not order:
        bad.append("faces: the rear pane does not draw TM-280 (mounted) after MX204 (through)")

    # No leftover ghost wording anywhere on the page.
    body_text = page.text_content("body") or ""
    if "short of this rail" in body_text or "-mounted," in body_text:
        bad.append(f"faces: stale ghost wording is still on the page")

    # A second MX204 at front U20, nothing at rear U20: the rear pane's U20
    # is free even though MX204's through panel there covers its hit target -
    # a click on it opens the picker for that free rear U.
    pick(page, "front", 20, "MX204", "mx204")
    page.wait_for_function("() => window.__rack.doc().racks[0].items.length === 3")
    page.wait_for_selector('svg[data-pane="rear"] rect.rk-u[data-u="20"]', timeout=READY_MS)
    wait_fn(page, "faces: second MX204 placed, drawn", "() => !document.getElementById('catPlace')")
    x20, y20 = u_center(page, "rear", 20)
    tok = render_token(page)
    page.mouse.click(x20, y20)
    wait_rendered(page, "faces: the rear U20 click redraws", tok)
    heading = page.text_content(".rk-side h3") or ""
    if "rear, empty" not in heading or "U20" not in heading.replace("U 20", "U20"):
        bad.append(f"faces: clicking the free rear U under MX204's through panel opened {heading!r}, not the U20/rear picker")

    # Fix round 1 #1: a through panel opens the picker ONLY when the frame is
    # four-post, the item does not reach this rail, and the U is free here -
    # otherwise a click on it selects the item, same as any other panel.
    #
    # Two-post: front and rear are the same shared plane (fit.js's reaches()
    # is always true there), so a real click on a front device's rear
    # (through) panel selects the device.
    open_new_rack(page, "faces: two-post")
    page.click("#frameBtn")
    page.select_option("#fKind", "two-post")
    page.wait_for_function("() => window.__rack.doc().racks[0].frame.kind === 'two-post'")
    pick(page, "front", 10, "TM-280", "tm-280")
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="tm-280"][data-panel="mounted"]', timeout=READY_MS)
    page.wait_for_selector('svg[data-pane="rear"] [data-device-ref="tm-280"][data-panel="through"]', timeout=READY_MS)
    xr, yr = u_center(page, "rear", 10)
    page.mouse.click(xr, yr)
    page.wait_for_selector("#iLabel, #catQuery", timeout=READY_MS)
    if page.query_selector("#catQuery"):
        bad.append("faces: a two-post click on a front device's rear (through) panel opened the picker instead of selecting the device")

    # Four-post, full depth: R740xd (737.5 mm) reaches the far rail (>= 740 -
    # 50), so its through panel IS its real, present rear - a click there
    # selects it too, not the picker.
    open_new_rack(page, "faces: full depth")
    pick(page, "front", 10, "R740", "r740xd")
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="r740xd"][data-panel="mounted"]', timeout=READY_MS)
    page.wait_for_selector('svg[data-pane="rear"] [data-device-ref="r740xd"][data-panel="through"]', timeout=READY_MS)

    # Two screws per ear per U, on the rail's own holes - rack3d.js's rackEars
    # and the BOM's 4 x U count the same way. The R740xd is 2U: 8 heads.
    r740_id = page.eval_on_selector('svg[data-pane="front"] [data-device-ref="r740xd"]', "el => el.dataset.itemId")
    screws = page.eval_on_selector('svg[data-pane="front"]', """(svg, id) => {
      const ears = svg.querySelector(`g.rk-ears[data-ears-for="${id}"]`);
      const holes = [...svg.querySelectorAll('[data-rail-hole]')].map(h => h.tagName === 'circle'
        ? +h.getAttribute('cy') : +h.getAttribute('y') + +h.getAttribute('height') / 2);
      const heads = ears ? [...ears.querySelectorAll('circle')] : [];
      return {n: heads.length,
              onHoles: heads.every(c => holes.some(y => Math.abs(y - +c.getAttribute('cy')) < 0.01))};
    }""", r740_id)
    if screws["n"] != 8:
        bad.append(f"faces: a 2U device's ears carry {screws['n']} screws, expected 8 (2 per ear per U)")
    if not screws["onHoles"]:
        bad.append("faces: a screw head is not on a rail hole")

    xr2, yr2 = u_center(page, "rear", 10)
    page.mouse.click(xr2, yr2)
    page.wait_for_selector("#iLabel, #catQuery", timeout=READY_MS)
    if page.query_selector("#catQuery"):
        bad.append("faces: a four-post click on a full-depth R740xd's rear (through) panel opened the picker instead of selecting it")
    return bad


@extra("rack.html: the 3D view - frame-aware posts, rear mounting, and the 2D/3D toggle")
def check_rack_3d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    open_new_rack(page, "3d")

    # A new rack defaults to four-post. R740xd on the front at U10, TM-280 on
    # the rear at U20 - a front and a rear mount that do not share a U, so
    # neither click is covered by the other's through panel.
    pick(page, "front", 10, "R740", "r740xd")
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="r740xd"][data-panel="mounted"]', timeout=READY_MS)
    pick(page, "rear", 20, "TM-280", "tm-280")
    page.wait_for_selector('svg[data-pane="rear"] [data-device-ref="tm-280"][data-panel="mounted"]', timeout=READY_MS)

    # THE SAME BRANCH check_stages TAKES: this runner may have no WebGL at
    # all, in which case the 3D view can only ever show its fallback
    # sentence - asserted here instead of failing on a scene that can never
    # exist.
    no_webgl = webgl_trouble(page)
    print(f"[check_rack_3d] WebGL path: {'unavailable - checking the fallback sentence' if no_webgl else 'available - running the full 3D checks'}")

    page.click('#mode [data-mode="3d"]')

    if no_webgl:
        page.wait_for_function(
            "() => (document.querySelector('#stage3d')?.textContent || '').includes(\"3D isn't available\")",
            timeout=READY_MS)
        if not page.is_visible("#stage3d"):
            bad.append("rack 3D (no WebGL): #stage3d is not shown with the fallback sentence")
        if page.is_visible("#panes"):
            bad.append("rack 3D (no WebGL): #panes is still visible once 3D is chosen")
        return bad

    settle_scene(page, "rack 3D: the scene")

    posts = page.evaluate("() => window.__rack.scene().posts()")
    if posts != 4:
        bad.append(f"rack 3D: posts() is {posts}, expected 4 on a four-post rack")

    devices = page.evaluate("() => window.__rack.scene().devices()")
    r740 = next((d for d in devices if d["ref"] == "r740xd"), None)
    tm280 = next((d for d in devices if d["ref"] == "tm-280"), None)
    if not r740 or not tm280:
        bad.append(f"rack 3D: devices() did not report both mounts ({devices})")
    else:
        if abs(tm280["rotY"] - math.pi) > 0.01:
            bad.append(f"rack 3D: the rear-mounted TM-280's rotation.y is {tm280['rotY']}, expected ~pi")
        if not (tm280["z"] < r740["z"]):
            bad.append(f"rack 3D: TM-280's z ({tm280['z']}) is not behind the R740xd's front-mounted z ({r740['z']})")

    # Shrinking the frame while in 3D moves devices - fit.js's shrinkRack
    # compacts everything from the bottom once anything no longer fits - and
    # Undo must restore the ORIGINAL rack. The 3D scene has to follow it
    # (round 1 fix #2: undoShrink() used to leave the shrunk scene standing,
    # never scheduling a rebuild).
    page.click("#frameBtn")
    page.fill("#fHeight", "15")
    page.dispatch_event("#fHeight", "change")
    page.wait_for_selector("#undoShrink", timeout=READY_MS)
    moved = page.evaluate("""() => Object.fromEntries(
      window.__rack.doc().racks[0].items.map(i => [i.ref, i.ru]))""")
    if moved.get("r740xd") == 10 and moved.get("tm-280") == 20:
        bad.append(f"rack 3D shrink: nothing moved, so Undo was not exercised ({moved})")
    page.click("#undoShrink")
    page.wait_for_function("""() => { const it = window.__rack.doc().racks[0].items;
      const r = it.find(i => i.ref === 'r740xd'), t = it.find(i => i.ref === 'tm-280');
      return !!r && !!t && r.ru === 10 && t.ru === 20; }""", timeout=READY_MS)
    # The rebuild is debounced (300ms) - poll the scene until it agrees too.
    page.wait_for_function("""() => { const s = window.__rack.scene(); if (!s) return false;
      const st = s.resolved().stack, r = st.find(i => i.ref === 'r740xd'),
        t = st.find(i => i.ref === 'tm-280'); return !!r && !!t && r.ru === 10 && t.ru === 20; }""",
        timeout=READY_MS)

    # Switch the frame to two-post while still in 3D: the rear pair goes away.
    page.select_option("#fKind", "two-post")
    page.wait_for_function("() => window.__rack.scene() != null && window.__rack.scene().posts() === 2",
                           timeout=READY_MS)

    # Back to 2D: the scene is gone and the panes return, still 42 U each,
    # and NOT stuck at height 0 (round 1 fix #1: render() applied zoom against
    # a #panes that was still `hidden`, measuring a 0 column and leaving every
    # SVG at height:0 once the panes came back).
    page.click('#mode [data-mode="2d"]')
    page.wait_for_function("() => window.__rack.scene() == null", timeout=READY_MS)
    if not page.is_visible("#panes"):
        bad.append("rack 3D: #panes is not visible after switching back to 2D")
    counts = page.evaluate("""() => ['front', 'rear'].map(f =>
      document.querySelectorAll(`svg[data-pane="${f}"] rect.rk-u`).length)""")
    if counts != [42, 42]:
        bad.append(f"rack 3D: after switching back to 2D, U targets are {counts}, expected [42, 42]")
    h = page.eval_on_selector('svg[data-pane="front"]', "s => s.getBoundingClientRect().height")
    if not (h > 100):
        bad.append(f"rack 3D: after editing in 3D and switching back to 2D, the front SVG's height is {h}, expected > 100")

    # Reload while in 3D (the mode is remembered) and switch back to 2D: the
    # same blank-pane bug, from the reload direction rather than the toggle.
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "rack 3D: the scene before the reload")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    if page.get_attribute('#mode [data-mode="3d"]', "aria-pressed") != "true":
        bad.append("rack 3D: the 3D mode was not remembered across a reload")
    page.wait_for_function("() => window.__rack.scene() != null", timeout=READY_MS)
    page.click('#mode [data-mode="2d"]')
    page.wait_for_function("() => window.__rack.scene() == null", timeout=READY_MS)
    h2 = page.eval_on_selector('svg[data-pane="front"]', "s => s.getBoundingClientRect().height")
    if not (h2 > 100):
        bad.append(f"rack 3D: after reloading into remembered 3D and switching back to 2D, the front SVG's height is {h2}, expected > 100")

    # A reload remembers the mode - 2D, just chosen above.
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    if page.get_attribute('#mode [data-mode="2d"]', "aria-pressed") != "true":
        bad.append("rack 3D: the 2D mode was not remembered across a reload")
    if not page.is_visible("#panes"):
        bad.append("rack 3D: after reload in the remembered 2D mode, #panes is not visible")
    return bad


@extra("rack.html: the 2D/3D switch stays put when the mode changes")
def check_rack_mode_toggle_stable(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    x = lambda: page.evaluate("() => Math.round(document.getElementById('mode').getBoundingClientRect().left)")
    page.click('#mode [data-mode="2d"]')
    before = x()
    page.click('#mode [data-mode="3d"]')
    in3d = x()
    page.click('#mode [data-mode="2d"]')
    after = x()
    if not (before == in3d == after):
        bad.append(f"mode switch: the toggle moved (2D {before}px, 3D {in3d}px, back {after}px)")
    if page.is_visible("#zoomIn"):
        page.click('#mode [data-mode="3d"]')
        if page.is_visible("#zoomIn"):
            bad.append("mode switch: the zoom controls are still visible in 3D")
    return bad


@extra("rack.html: the Explorer's 2D/3D switch and stage swatches; the stage is the ground in 2D and 3D")
def check_rack_stage(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    # THE SWITCH IS THE EXPLORER'S: the same computed look, read off both pages.
    look = """() => { const out = {};
      for (const sel of ['#mode button.on', '#mode button:not(.on)']) {
        const b = document.querySelector(sel), c = b && getComputedStyle(b);
        out[sel] = c && [c.backgroundColor, c.borderTopColor, c.color, c.fontFamily, c.fontWeight, c.fontSize, c.paddingTop,
                         c.paddingLeft, c.borderTopLeftRadius, c.borderTopRightRadius];
      }
      const sw = document.querySelector('#stagebg .sw'), w = sw && getComputedStyle(sw);
      out.sw = w && [w.width, w.height, w.borderTopLeftRadius];
      return out; }"""
    page.goto(f"{base}/explorer.html", wait_until="load")
    page.wait_for_selector("#mode button.on", timeout=READY_MS)
    page.wait_for_selector("#stagebg .sw", timeout=READY_MS)
    explorer = page.evaluate(look)
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.evaluate("() => { localStorage.removeItem('portrayal.stage'); localStorage.removeItem('portrayal.rack.mode'); }")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    rack = page.evaluate(look)
    if rack != explorer:
        bad.append(f"switch: the Rack Builder's #mode and swatches do not look like the Explorer's: {rack} vs {explorer}")
    if page.get_attribute('#mode [data-mode="2d"]', "aria-pressed") != "true":
        bad.append("switch: 2D is not aria-pressed")
    page.evaluate("() => window.__rack.apply([{op: 'place', ref: 'as7726-32x', face: 'front', ru: 3}])")
    # 2D: as in the Explorer, the swatches show and the stage is the ground.
    pane = """() => { const p = document.getElementById('panes');
      return {bg: getComputedStyle(p).backgroundColor, tone: p.dataset.stage,
              head: getComputedStyle(document.getElementById('headFront')).color}; }"""
    if not page.is_visible('#stagebg .sw[data-c="#ffffff"]'):
        bad.append("stage: the swatches are not shown in 2D, as the Explorer shows them")
    got = page.evaluate(pane)
    if got != {"bg": "rgb(16, 18, 20)", "tone": "dark", "head": "rgb(154, 161, 168)"}:
        bad.append(f"stage 2D: a reader who never chose is not on the shell's black, in the dark palette: {got}")
    page.click('#stagebg .sw[data-c="#ffffff"]')
    got = page.evaluate(pane)
    if got != {"bg": "rgb(255, 255, 255)", "tone": "light", "head": "rgb(86, 94, 103)"}:
        bad.append(f"stage 2D: white did not reach the panes and their ink: {got}")
    page.click('#mode [data-mode="3d"]')
    if page.get_attribute('#mode [data-mode="3d"]', "class") != "on" or \
       page.get_attribute('#mode [data-mode="3d"]', "aria-pressed") != "true":
        bad.append("switch: 3D pressed is not marked `on` and aria-pressed")
    if webgl_trouble(page):
        print("[check_rack_stage] WebGL unavailable - the 3D half is not checked")
        return bad
    settle_scene(page, "stage 3D: the scene")
    tones = lambda: page.evaluate("""() => {
      const s = window.__rack.scene(), t = {};
      s.three.scene.traverse(x => { if (x.isSprite && x.userData.labelTone) t[x.userData.labelTone] = x.material.color.getHexString('srgb'); });
      return {bg: s.three.scene.background.getHexString('srgb'), ...t}; }""")
    light = tones()
    if light != {"bg": "ffffff", "tag": "2b3035", "unit": "5a6168", "emph": "101214"}:
        bad.append(f"stage 3D: a scene built on white did not take it and its labels: {light}")
    # Changed on a built scene, in place.
    page.click('#stagebg .sw[data-c="#3b3f45"]')
    grey = tones()
    if grey != {"bg": "3b3f45", "tag": "d7dbdf", "unit": "9aa1a8", "emph": "e4e7ea"}:
        bad.append(f"stage 3D: dark grey did not reach the built scene: {grey}")
    page.click('#stagebg .sw[data-c="#ffffff"]')
    # Remembered, under the Explorer's key, and given to the next scene built.
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    settle_scene(page, "stage 3D: the scene after a reload")
    if tones() != light:
        bad.append(f"stage 3D: after a reload the scene is {tones()}, not the white it was left on")
    if page.evaluate("() => localStorage.getItem('portrayal.stage')") != "#ffffff":
        bad.append("stage: the choice is not kept under portrayal.stage, the Explorer's key")
    page.click('#stagebg .sw[data-c="#101214"]')
    if tones() != {"bg": "101214", "tag": "d7dbdf", "unit": "6b727a", "emph": "e4e7ea"}:
        bad.append(f"stage 3D: black is not the scene's own label tones again: {tones()}")
    # PICKED WHILE THE SCENE IS BUILDING: there is no scene to tell, so the
    # build takes the colour when it lands (rack-page.js rebuild3d). The switch
    # to 3D and the swatch are clicked in one task, so the click finds no scene.
    page.click('#mode [data-mode="2d"]')
    page.wait_for_function("() => window.__rack.scene() == null", timeout=READY_MS)
    none = page.evaluate("""() => { document.querySelector('#mode [data-mode="3d"]').click();
      document.querySelector('#stagebg .sw[data-c="#c5c9ce"]').click();
      return window.__rack.scene() == null; }""")
    if not none:
        bad.append("stage 3D: the swatch was not clicked during a build (a scene was up), so that path was not measured")
    settle_scene(page, "stage 3D: the scene built under a swatch click")
    if tones() != {"bg": "c5c9ce", "tag": "2b3035", "unit": "5a6168", "emph": "101214"}:
        bad.append(f"stage 3D: light grey, picked while the scene was building, did not reach it: {tones()}")
    page.evaluate("() => { localStorage.removeItem('portrayal.stage'); localStorage.removeItem('portrayal.rack.mode'); }")
    # NO WEBGL: mountRack3d gives no scene and its own sentence, and the page
    # goes on - no exception from the rebuild, and a swatch still turns the panes.
    nogl = page.context.browser.new_page()
    try:
        errs = []
        nogl.on("pageerror", lambda e: errs.append(str(e)))
        nogl.add_init_script(NO_WEBGL_JS)
        nogl.goto(f"{base}/rack.html?probe=1", wait_until="load")
        nogl.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
        nogl.evaluate("() => window.__rack.ready")
        nogl.click('#mode [data-mode="2d"]')
        nogl.click('#mode [data-mode="3d"]')
        nogl.wait_for_function("() => (document.querySelector('#stage3d')?.textContent || '').includes(\"3D isn't available\")",
                               timeout=READY_MS)
        nogl.click('#stagebg .sw[data-c="#ffffff"]')
        nogl.wait_for_timeout(600)          # past a rebuild's 300 ms, were one waiting
        if errs:
            bad.append(f"stage, no WebGL: the 3D switch threw: {errs}")
        if nogl.evaluate("() => window.__rack.scene()") is not None:
            bad.append("stage, no WebGL: the page holds a scene")
        if nogl.evaluate("() => document.getElementById('panes').dataset.stage") != "light":
            bad.append("stage, no WebGL: a swatch picked in 3D did not reach the panes")
        nogl.evaluate("() => { localStorage.removeItem('portrayal.stage'); localStorage.removeItem('portrayal.rack.mode'); }")
    finally:
        nogl.close()
    return bad


@extra("rack.html: rails, ears and screws are the same silver in light and dark")
def check_rack_rails_metal(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    seen = {}
    for scheme in ("light", "dark"):
        page.emulate_media(color_scheme=scheme)
        page.goto(f"{base}/rack.html?probe=1", wait_until="load")
        page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
        page.evaluate("() => window.__rack.ready")
        page.wait_for_selector('svg[data-pane="front"] rect[data-rail]', timeout=READY_MS)
        seen[scheme] = page.evaluate("""() => {
          const rail = document.querySelector('svg[data-pane="front"] rect[data-rail]');
          return getComputedStyle(rail).fill; }""")
    if seen["light"] != seen["dark"]:
        bad.append(f"rails change with the theme: light {seen['light']}, dark {seen['dark']}")
    # The showcase keeps its themed rails.
    page.goto(f"{base}/index.html", wait_until="load")
    fill = page.evaluate("""async () => {
      const {build2dElevation} = await import('/site/showcase/rack.js');
      const svg = await build2dElevation({stack: [], heightRU: 2});
      return svg.querySelector('rect[data-rail]').getAttribute('fill'); }""")
    if fill != "var(--pt-surface-2)":
        bad.append(f"the showcase's rails lost their theme color ({fill})")
    return bad


@extra("rack.html: an In development pill opens a note on what's done and what's coming")
def check_rack_dev_note(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    if not page.is_visible("#devNote > summary"):
        return bad + ["dev note: no In development pill in the top bar"]
    if (page.text_content("#devNote > summary") or "").strip() != "In development":
        bad.append(f"dev note: the pill reads {page.text_content('#devNote > summary')!r}")
    if page.is_visible("#devNote .rk-devnote-body"):
        bad.append("dev note: the note is open before it is clicked")
    page.click("#devNote > summary")
    body = page.text_content("#devNote .rk-devnote-body") or ""
    for want in ("still being built", "You can cable ports in 2D",
                 "Cables are in 3D and in the exports: the sheet, draw.io, the 3D model, the bill of materials and a cable schedule.",
                 "Export has an import kit for NetBox and one for Nautobot: types, devices, modules and cables, in import order, with a README.",
                 "Set the site and the device role they name under Export, DCIM import settings."):
        if want not in body:
            bad.append(f"dev note: the note doesn't mention {want!r}")
    for gone in ("Coming next: cabling.", "Coming next: cables in the exports and in 3D.",
                 "Coming next: cable import for NetBox and Nautobot."):
        if gone in body:
            bad.append(f"dev note: it still says {gone!r}, and that has shipped")
    box = page.evaluate("""() => { const r = document.querySelector('#devNote .rk-devnote-body').getBoundingClientRect();
                              return [Math.round(r.left), Math.round(r.right), innerWidth]; }""")
    if box[0] < 0 or box[1] > box[2]:
        bad.append(f"dev note: the note opens off screen ({box})")
    return bad


# ...AND THE DESKTOP. components.html draws every part at true scale in a card
# capped at 340px, so a line card or a faceplate spilled out of it and the page
# scrolled sideways at every width - 3729px wide at 1280. A drawing wider than
# its card scrolls inside it instead (roc-ops/portrayal-site#53).
@extra("the tool-bar pages have no horizontal scroll at a 1280px viewport")
def check_wide_tool_pages(page, base):
    bad = []
    page.set_viewport_size({"width": 1280, "height": 800})
    for name in NARROW_PAGES:
        page.goto(f"{base}/{name}", wait_until="load")
        page.wait_for_timeout(1500)
        w = page.evaluate("document.documentElement.scrollWidth")
        if w > 1280:
            bad.append(f"{name}: scrollWidth {w} at a 1280px viewport")
    return bad


# THE DRAWING IS THERE ON A PHONE. Explorer and Annotate put the drawing beside
# a 23rem side panel (Annotate adds a second at 28rem), and on a phone the
# panels took the whole row - the stage was 7px wide at 375 and 0 at 360, so
# the one thing both tools are for could not be seen. Below 720px they stack:
# the drawing full width on top, the panels under it (roc-ops/portrayal-site#54).
@extra("Explorer and Annotate show the drawing on a 360px phone")
def check_phone_stage(page, base):
    bad = []
    page.set_viewport_size({"width": 360, "height": 740})
    for name in ["explorer.html", "annotate.html"]:
        page.goto(f"{base}/{name}", wait_until="load")
        try:
            page.wait_for_selector("#stage svg", timeout=15000)
        except Exception:
            bad.append(f"{name}: no drawing in the stage")
            continue
        r = page.evaluate("""() => {
          const st = document.querySelector('#stage').getBoundingClientRect();
          const panels = [...document.querySelectorAll('main > aside')].map(a => {
            const b = a.getBoundingClientRect();
            return {w: Math.round(b.width), h: Math.round(b.height), top: Math.round(b.top)};
          });
          return {w: Math.round(st.width), h: Math.round(st.height), bottom: Math.round(st.bottom),
                  panels, sw: document.documentElement.scrollWidth,
                  sh: document.documentElement.scrollHeight};
        }""")
        if r["w"] < 300 or r["h"] < 150:
            bad.append(f"{name}: at 360x740 the stage is {r['w']}x{r['h']}px - too small to see the drawing")
        for i, p in enumerate(r["panels"]):
            if p["h"] < 80:
                bad.append(f"{name}: side panel {i} is only {p['h']}px tall on a phone")
            if p["top"] < r["bottom"] - 1:
                bad.append(f"{name}: side panel {i} is beside the stage, not under it")
        if r["sw"] > 360 or r["sh"] > 740:
            bad.append(f"{name}: the page scrolls at 360x740 ({r['sw']}x{r['sh']}) - the tool should fit the screen")
    return bad


# ANNOTATE'S DIAGRAM EXPORTS ARE THE DRAWING AS IT STANDS. The point of the two
# buttons is that what was set up here - an optic seated, a lamp lit, a crop -
# reaches draw.io and OmniGraffle with a connection point on every port, and
# not one on a port the crop cut away. Downloads are caught as blobs, not saved.
@extra("Annotate's draw.io and OmniGraffle exports carry the seated optic, the lamp and the crop")
def check_annotate_diagram_exports(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/annotate.html", wait_until="load")
    for crop in (None, {"x": 170, "y": 5, "w": 120, "h": 35}):
        page.evaluate("""async crop => {
          const m = await import('/vendor/marks.js');
          location.hash = m.encode({v: 1, device: 's9510-28dc', config: 'dc', view: 'front',
            legend: false, crop, swaps: {'port-0': 'generic/qsfp-cable@1'},
            marks: [{select: '#led-gnss', state: 'antenna-short'}]});
        }""", crop)
        page.reload(wait_until="load")
        page.wait_for_selector("#stage svg [id='port-0-occupant']", state="attached", timeout=20000)
        r = page.evaluate("""async () => {
          const blobs = [];
          const orig = URL.createObjectURL.bind(URL);
          URL.createObjectURL = b => { blobs.push(b); return orig(b); };
          HTMLAnchorElement.prototype.click = function () {};
          // By type: toGraffle rasterises its face through a blob URL of its
          // own, so the first blob after the click is the SVG, not the file.
          const press = async (act, type) => {
            const n = blobs.length;
            document.querySelector(`button[data-act="${act}"]`).click();
            for (let i = 0; i < 100; i++) {
              const hit = blobs.slice(n).find(b => b.type === type);
              if (hit) return hit;
              await new Promise(ok => setTimeout(ok, 100));
            }
          };
          const dio = await press('drawio', 'application/vnd.jgraph.mxfile');
          const og = await press('graffle', 'application/octet-stream');
          if (!dio || !og) return {missing: true, msg: document.querySelector('#expmsg').textContent};
          const x = new DOMParser().parseFromString(await dio.text(), 'text/xml');
          const face = x.querySelector('mxCell[id$="-face"]')?.getAttribute('style') || '';
          const b64 = (face.match(/image=data:image\\/svg\\+xml,([^;]+)/) || [])[1] || '';
          const svg = new TextDecoder().decode(Uint8Array.from(atob(b64), c => c.charCodeAt(0)));
          const zip = new Uint8Array(await og.arrayBuffer());
          return {parses: !x.querySelector('parsererror'),
                  ports: x.querySelectorAll('object[portrayal-path]').length,
                  optic: svg.includes('id="port-0-occupant'), lit: /#eab308/i.test(svg),
                  zip: zip[0] === 0x50 && zip[1] === 0x4b,
                  plist: new TextDecoder().decode(zip).includes('portrayal-path')};
        }""")
        what = "cropped" if crop else "whole"
        if r.get("missing"):
            bad.append(f"annotate ({what}): an export produced no file - {r['msg']}")
            continue
        if not r["parses"]:
            bad.append(f"annotate ({what}): the .drawio is not well-formed XML")
        if not crop and r["ports"] != 36:
            bad.append(f"annotate (whole): {r['ports']} port cells, expected the S9510-28DC's 36")
        if crop and not 0 < r["ports"] < 36:
            bad.append(f"annotate (cropped): {r['ports']} port cells - the crop did not drop the ports it cut away")
        if not r["optic"]:
            bad.append(f"annotate ({what}): the seated optic is not in the draw.io picture")
        if not r["lit"]:
            bad.append(f"annotate ({what}): the GNSS lamp's antenna-short colour is not in the draw.io picture")
        if not (r["zip"] and r["plist"]):
            bad.append(f"annotate ({what}): the .gstencil is not a zip with named port shapes")
    return bad


# OPTICS ARE THEIR OWN SECTION OF THE LIBRARY, AND THEY LAND ON THEIR BORES.
# An optic is no one vendor's module, so the draw.io page offers every one under
# its own checkbox (#78). The generic QSFP LC optic's face starts at -0.325,-1.4,
# and its two port cells sit where the bores are only if the cells are measured
# from that corner (Portrayal #722) - 8.05,4.70 and 20.55,4.70 at 2 px/mm.
# FS is the scope because it was the vendor whose modules a derived namespace
# lost (`fscom` for `fs`), so its cards being offered at all is half the check.
@extra("draw.io: the optics library, with the LC optic's ports on its bores")
def check_drawio_optics_library(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/drawio.html?device=fhd-1ube", wait_until="load")
    # NULL-SAFE, AND SAID OUT LOUD WHEN IT IS NULL. A predicate that reads
    # `.textContent` off a missing element throws, and wait_for_function gives
    # up on a throw instead of polling - which failed this check once in a full
    # pass. The checkbox is static markup, so if it never appears the page that
    # was served is not this tree's drawio.html, and the message says that.
    try:
        page.wait_for_function(
            "(document.getElementById('optics-count')?.textContent || '') !== ''", timeout=15000)
    except Exception:
        has = page.evaluate("!!document.getElementById('optics')")
        return bad + ["draw.io optics: " + (
            "the optics count never filled in" if has else
            f"{page.url} has no optics checkbox - is the server serving this tree?")]
    r = page.evaluate("""async () => {
      const $ = id => document.getElementById(id);
      const mods = $('mods-count')?.textContent || '', optics = $('optics-count')?.textContent || '';
      $('optics').checked = true;
      const blobs = [];
      const orig = URL.createObjectURL.bind(URL);
      URL.createObjectURL = b => { blobs.push(b); return orig(b); };
      HTMLAnchorElement.prototype.click = function () {};
      $('dl-lib').click();
      let lib;
      for (let i = 0; i < 300 && !(lib = blobs.find(b => b.type === 'application/xml')); i++)
        await new Promise(ok => setTimeout(ok, 100));
      if (!lib) return {missing: true, stat: $('stat-lib').textContent};
      const xml = await lib.text();
      const entries = JSON.parse(xml.slice(xml.indexOf('<mxlibrary>') + 11, xml.lastIndexOf('</mxlibrary>'))
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&'));
      const lc = entries.find(e => e.title === 'generic/qsfp-lc');
      const cells = lc ? Object.fromEntries([...lc.xml.matchAll(
        /portrayal-path="([^"]+)"[^>]*><mxCell[^>]*><mxGeometry x="([^"]+)" y="([^"]+)"/g)]
        .map(m => [m[1], [+m[2], +m[3]]])) : {};
      return {mods, optics, cells, titles: entries.map(e => e.title)};
    }""")
    if r.get("missing"):
        return bad + [f"draw.io optics: no library was produced - {r['stat']}"]
    if not r["mods"].strip(" ()").isdigit():
        bad.append("draw.io: FS offers no modules - its namespace is derived again, not read from devices.json")
    if not r["optics"].strip(" ()").isdigit():
        bad.append("draw.io: the optics checkbox has no count")
    if "generic/qsfp-lc" not in r["titles"]:
        bad.append("draw.io optics: no generic/qsfp-lc entry in the library")
    for port, want in {"qsfp-lc/tx": [8.05, 4.7], "qsfp-lc/rx": [20.55, 4.7]}.items():
        got = r["cells"].get(port)
        if not got or any(abs(a - b) > 0.01 for a, b in zip(got, want)):
            bad.append(f"draw.io optics: {port} cell at {got}, expected {want} - on the bore")
    return bad


# THREE.JS IS PAID FOR ON THE PRESS, NOT ON THE PAGE. site/mode3d.js imports
# vendor/viewer3d.js on the first press of 3D, and the viewer pulls three.js
# through the import map; a page that never shows 3D must fetch neither.
@extra("Explorer fetches no three.js and no viewer until 3D is pressed")
def check_explorer_three_lazy(page, base):
    bad, asked = [], []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("request", lambda r: asked.append(r.url))
    page.goto(f"{base}/explorer.html?device=s9510-28dc", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    early = [u for u in asked if "/vendor/three/" in u or u.endswith("/vendor/viewer3d.js")]
    if early:
        bad.append(f"explorer: fetched before 3D was pressed: {early[:3]}")
    if webgl_trouble(page):
        print("[check_explorer_three_lazy] no WebGL here - checked the 2D half only")
        return bad
    page.click('#mode [data-mode="3d"]')
    page.wait_for_function("() => document.querySelector('#stage-3d canvas')", timeout=READY_3D_MS)
    if not any(u.endswith("/vendor/viewer3d.js") for u in asked):
        bad.append("explorer: 3D came up without fetching vendor/viewer3d.js")
    return bad


# ANNOTATE IN 3D SHOWS THE DOCUMENT (portrayal-site#46). On the S9510-28DC:
# three marks in three colours, a lamp colour, a lamp state, a mark that
# matches no face, a mark on a rear-only fan while the front is the drawing, a
# click, an optic seated in 3D and a mode round trip - all read back from the
# viewer itself.
@extra("Annotate in 3D: marks, lamps, states, legend, picks, swaps and exports reach the scene")
def check_annotate_3d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))

    # A NAMED WAIT. A bare Playwright timeout says only that something took 240s;
    # this says which step it was, and the check stops there with what it has.
    class Stop(Exception):
        pass

    def until(expr, what, timeout=READY_MS):
        try:
            page.wait_for_function(expr, timeout=timeout)
        except Exception:
            st = page.evaluate("""() => ({url: location.pathname + location.search,
              on3d: !!document.querySelector('#mode [data-mode="3d"].on'),
              status: document.querySelector('#status')?.textContent || '',
              marks: window.__viewer ? window.__viewer.marks().length : null,
              rows: [...document.querySelectorAll('#rows .mark .sel')].map(e => e.value),
              paths: window.__viewer ? window.__viewer.marks().map(m => m.path) : null})""")
            bad.append(f"annotate 3D: timed out waiting for {what} - {st}")
            raise Stop()

    doc = {"v": 1, "device": "s9510-28dc", "config": "dc", "view": "front", "legend": True,
           "marks": [
               {"select": "[data-path='port-0']", "color": "#e0574f", "label": "uplink"},
               {"select": "[data-path='port-4']", "color": "#2bb3c8"},
               # fan-2 is drawn on the REAR face only (fans 1-5 exhaust at the back):
               # marked while the front is the drawing, it must still reach 3D
               {"select": "[data-path='fan-2']", "color": "#9b5de5", "label": "exhaust fan"},
               {"select": "#led-gnss", "lamp": "#ff00ff"},
               {"select": "[data-path='led-sync']", "state": "synced"},
               # a PSU this device does not have: nothing on any face to place in 3D
               {"select": "[data-path='psu-9']", "color": "#ffd400"},
           ]}
    page.goto(f"{base}/annotate.html?debug=1", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    page.evaluate("""async d => { const m = await import('/vendor/marks.js');
                       location.hash = m.encode(d); }""", doc)
    page.reload(wait_until="load")
    page.wait_for_selector("#stage svg [data-path='port-0']", state="attached", timeout=READY_MS)
    if webgl_trouble(page):
        print("[check_annotate_3d] no WebGL here - checking the fallback only")
        page.click('#mode [data-mode="3d"]')
        page.wait_for_function("() => /3D unavailable/.test(document.querySelector('#status')?.textContent || '')"
                               " || !document.querySelector('#stage-3d').hidden", timeout=READY_MS)
        return bad
    try:
        # A PAN AND AN ARMED CROP IN 2D, THEN 3D (final review). The drag guard is
        # the drawing's: a pan before 3D must not stop 3D clicks adding marks. And
        # an armed crop's veil sits over the stage: going to 3D must disarm it.
        sb = page.locator("#stage svg").bounding_box()
        page.mouse.move(sb["x"] + sb["width"] * 0.3, sb["y"] + sb["height"] * 0.5)
        page.mouse.down()
        page.mouse.move(sb["x"] + sb["width"] * 0.45, sb["y"] + sb["height"] * 0.5, steps=8)
        page.mouse.up()
        page.click("#crop")
        page.click('#mode [data-mode="3d"]')
        until("() => window.__viewer && window.__viewer.marks().length >= 3", "the scene's first marks", READY_3D_MS)
        if page.evaluate("() => document.querySelector('#crop').classList.contains('on')"):
            bad.append("annotate 3D: a crop armed in 2D is still armed in 3D, its veil over the scene")
        # SETTLED, NOT JUST STARTED: marks are sent before the build and again on
        # the built scene, and the rows repaint on the viewer's report. Read once the
        # report has found the ports; if it never does, the assertions below say so.
        try:
            page.wait_for_function("""() => { const r = window.__viewer.markReport;
                return r && !['port-0', 'port-4', 'fan-2'].some(p => r.missing.includes(p)); }""", timeout=READY_MS)
        except Exception:
            pass
        page.wait_for_timeout(300)
        r = page.evaluate("""() => { const v = window.__viewer;
          return {marks: v.marks().map(m => [m.path, m.color]).sort(),
                  lamps: v.lampColors(), states: v.states(),
                  legend: [...document.querySelectorAll('#legend3d .row')].map(e => e.textContent.trim()),
                  notIn3d: [...document.querySelectorAll('#rows .mark')].map(r =>
                    /not in 3D/.test(r.querySelector('.notes').textContent)),
                  off: [...document.querySelectorAll('.btns button[data-act]')]
                         .filter(b => b.dataset.act !== 'share').every(b => b.disabled && /2D only/.test(b.title))}; }""")
        got = dict((p, c) for p, c in r["marks"])
        for path, colour in [("port-0", "#e0574f"), ("port-4", "#2bb3c8"), ("fan-2", "#9b5de5")]:
            if got.get(path) != colour:
                bad.append(f"annotate 3D: mark on {path} is {got.get(path)}, expected {colour}")
        if "#ff00ff" not in [c.lower() for c in r["lamps"].values()]:
            bad.append(f"annotate 3D: the lamp colour never reached the viewer - {r['lamps']}")
        if r["states"].get("led-sync") != "state-synced":
            bad.append(f"annotate 3D: led-sync state is {r['states'].get('led-sync')}")
        if r["legend"] != ["uplink", "exhaust fan"]:
            bad.append(f"annotate 3D: legend rows {r['legend']}, expected ['uplink', 'exhaust fan']")
        if r["notIn3d"] != [False, False, False, False, False, True]:
            bad.append(f"annotate 3D: 'not in 3D' flags {r['notIn3d']}")
        if not r["off"]:
            bad.append("annotate 3D: a 2D-only export is enabled, or lacks its '2D only' title")

        # A CLICK IN 3D IS A CLICK (Review Focus 4). select() frames the camera on
        # the part, centred, so a real click at the canvas centre lands on it - the
        # whole path: canvas, the viewer's select event, onPick, Annotate's toggle.
        # AS IN 2D, where the shell turns a click on the selected part into a
        # deselect: the first click selects port-8 and adds its mark, the second
        # clears the selection and keeps the mark, the third takes the mark off.
        n = len(doc["marks"])
        page.evaluate("() => { window.__viewer.select('port-8'); }")
        page.wait_for_timeout(500)
        box = page.locator("#stage-3d canvas").bounding_box()
        cx, cy = box["x"] + box["width"] / 2, box["y"] + box["height"] / 2
        page.mouse.click(cx, cy)
        until(f"() => document.querySelectorAll('#rows .mark').length === {n + 1}", "a 3D click to add a mark")
        if not page.evaluate("() => !!document.querySelector(\".node.sel[data-path='port-8']\")"):
            bad.append("annotate 3D: a click on port-8 did not select it in the tree")
        page.mouse.click(cx, cy)
        page.wait_for_timeout(600)
        second = page.evaluate("() => [document.querySelectorAll('#rows .mark').length, !!document.querySelector('.node.sel')]")
        if second != [n + 1, False]:
            bad.append(f"annotate 3D: a second click gave {second} (rows, selected) - 2D gives [{n + 1}, False]: deselect, keep the mark")
        page.mouse.click(cx, cy)
        until(f"() => document.querySelectorAll('#rows .mark').length === {n}", "a third 3D click to take the mark off")

        # AN OPTIC SEATED IN 3D KEEPS EVERY MARK. Through the inspector, as a
        # reader does it: select the cage in the tree, choose the first optic.
        # Click highlights go off for the select - with them on, a click on port-4's
        # row is a click that takes port-4's mark off, which is Annotate's 2D
        # behaviour and not what this step is about.
        page.click("#clickadd")
        page.click(".node[data-path='port-4']")
        page.click("#clickadd")
        page.wait_for_selector("#optic", timeout=READY_MS)
        optic = page.evaluate("() => [...document.querySelectorAll('#optic option')].map(o => o.value).find(Boolean)")
        page.select_option("#optic", optic)
        until("() => window.__viewer.marks().length >= 3", "the marks after seating an optic", READY_3D_MS)
        page.wait_for_timeout(1500)
        after_swap = page.evaluate("() => window.__viewer.marks().map(m => m.path).sort()")
        if not set(got) <= set(after_swap):
            bad.append(f"annotate 3D: seating {optic} in port-4 lost marks {sorted(set(got) - set(after_swap))}")

        # A 3D -> 2D -> 3D round trip leaves the document and the marks as they were.
        # The DOCUMENT too, not only the scene: returning to 2D re-selects what was
        # selected (port-4, from the swap), and a re-selection that counted as a
        # click took port-4's mark off.
        rows = "() => [...document.querySelectorAll('#rows .mark .sel')].map(e => e.value)"
        before_rows = page.evaluate(rows)
        page.click('#mode [data-mode="2d"]')
        page.click('#mode [data-mode="3d"]')
        until("() => window.__viewer.marks().length >= 3", "the marks after a 2D/3D round trip", READY_3D_MS)
        after = page.evaluate("() => window.__viewer.marks().map(m => m.path).sort()")
        if after != after_swap:
            bad.append(f"annotate 3D: a 2D/3D round trip changed the marks {after_swap} -> {after}")
        if page.evaluate(rows) != before_rows:
            bad.append(f"annotate 3D: a 2D/3D round trip changed the document {before_rows} -> {page.evaluate(rows)}")

        # A CONFIGURATION CHANGE IN 3D (final review). The shell refetches the
        # other faces after the load, and the rear-only fan-2 must be marked again
        # once they are back; and the scene is built once, not once per listener.
        page.evaluate("""() => { const v = window.__viewer; window.__loads = 0;
          const l = v.load; v.load = o => { window.__loads++; return l(o); }; }""")
        page.select_option("#cfg", "ac")
        until("() => window.__viewer.info.config === 'ac'", "the scene to load the ac configuration", READY_3D_MS)
        try:
            page.wait_for_function("() => window.__viewer.marks().some(m => m.path === 'fan-2')", timeout=READY_MS)
        except Exception:
            bad.append("annotate 3D: after a configuration change, the rear-only fan-2 is no longer marked")
        page.wait_for_timeout(1500)
        loads = page.evaluate("() => window.__loads")
        if loads != 1:
            bad.append(f"annotate 3D: a configuration change built the scene {loads} times, not once")
        page.select_option("#cfg", "dc")
        until("() => window.__viewer.info.config === 'dc' && window.__viewer.marks().length >= 3",
              "the dc configuration and its marks back", READY_3D_MS)

        # Back in 2D the exports come back with their own titles (Review Focus 5)
        page.click('#mode [data-mode="2d"]')
        back = page.evaluate("""() => [...document.querySelectorAll('.btns button[data-act]')]
          .every(b => !b.disabled && !/2D only/.test(b.title))""")
        if not back:
            bad.append("annotate: back in 2D, an export is still disabled or still titled '2D only'")

        # A share link made in 3D opens in 3D, with its marks
        page.click('#mode [data-mode="3d"]')
        until("() => window.__viewer.marks().length >= 3", "the marks back in 3D before sharing", READY_3D_MS)
        page.click('.btns button[data-act="share"]')
        url = page.input_value('#share')
        if "?mode=3d#" not in url:
            # Reopening a link that does not say 3D opens the drawing, and the waits
            # below would sit out their timeout and throw away everything above.
            return bad + [f"annotate 3D: the share link does not record the mode - {url[:80]}"]
        page.goto(url.replace("?mode=3d", "?mode=3d&debug=1"), wait_until="load")
        until("() => window.__viewer && window.__viewer.marks().length >= 3", "the shared link to open in 3D with its marks", READY_3D_MS)

        # The GLB is the model: as many meshes with the marks as without (needs PR 1 synced).
        # Only once the halos are DRAWN - counted on a scene whose report still says
        # every mark is missing, there are no plates to leak and this passes vacuously.
        until("""() => { const r = window.__viewer.markReport;
            return r && !['port-0', 'fan-2'].some(p => r.missing.includes(p)); }""",
              "the reopened scene to draw its marks", READY_3D_MS)
        meshes = page.evaluate("""async () => { const v = window.__viewer;
          const count = async () => { const b = await v.exportData('glb'), d = new DataView(b);
            return (JSON.parse(new TextDecoder().decode(new Uint8Array(b, 20, d.getUint32(12, true)))).meshes || []).length; };
          const held = v.marks(); const marked = await count();
          v.setMarks([]); const plain = await count(); v.setMarks(held);
          return [marked, plain]; }""")
        if meshes[0] != meshes[1]:
            bad.append(f"annotate 3D: the GLB carries the marks ({meshes[0]} meshes marked, {meshes[1]} plain)")
    except Stop:
        pass
    return bad


# A LOST GRAPHICS CONTEXT SAYS SO (Portrayal #746). The viewer stops drawing when
# the browser takes the WebGL context away, rebuilds when it is handed back, and
# announces both; site/mode3d.js puts that in the status line, so Explorer and
# Annotate both say why the canvas went blank instead of just going blank. The
# context is lost and restored for real, through WEBGL_lose_context.
@extra("3D says when the graphics context is lost, and clears it when it is back")
def check_3d_context_loss(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/explorer.html?device=s9510-28dc&debug=1", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    if webgl_trouble(page):
        print("[check_3d_context_loss] no WebGL here - nothing to lose")
        return bad
    page.click('#mode [data-mode="3d"]')
    page.wait_for_function("() => window.__viewer && document.querySelector('#stage-3d canvas')", timeout=READY_3D_MS)
    page.wait_for_function("() => document.querySelector('#status').textContent === ''", timeout=READY_3D_MS)
    lost = page.evaluate("""() => { const c = document.querySelector('#stage-3d canvas');
      const gl = c.getContext('webgl2') || c.getContext('webgl');
      const ext = gl && gl.getExtension('WEBGL_lose_context');
      if (!ext) return false; window.__lose = ext; ext.loseContext(); return true; }""")
    if not lost:
        print("[check_3d_context_loss] no WEBGL_lose_context here - not exercised")
        return bad
    try:
        page.wait_for_function("() => /3D paused/.test(document.querySelector('#status').textContent)", timeout=READY_MS)
    except Exception:
        return bad + [f"3D: the context was lost and the status line says {page.text_content('#status')!r}, not '3D paused'"]
    page.evaluate("() => window.__lose.restoreContext()")
    try:
        page.wait_for_function("() => !/3D paused/.test(document.querySelector('#status').textContent)", timeout=READY_3D_MS)
    except Exception:
        bad.append("3D: the context came back and the status line still says '3D paused'")
    return bad


# A GLB PRESSED BEFORE THE SCENE HAS BUILT IS NOT A GLB OF THE DEVICE
# (portrayal-site#111). The viewer exports the scene as it stands, so a press
# straight after switching to 3D saved a 112-byte file with no geometry and
# called it "0.1 KB". Pressed here the moment the button exists, without
# waiting: no file may arrive until the scene is up, and every file that does
# arrive is the model. Then the same during a config rebuild, and an export with
# no meshes must say it failed rather than save.
#
# AND THE THREE WAYS A SCENE CHANGES UNDER THE BAR (site/mode3d.js): a file
# still being built when the configuration changes is not saved; a round trip
# dc -> ac -> dc made while the ac scene is building ends on dc, with the
# buttons back; a seated optic rebuilds the scene and the buttons follow it;
# and a build that fails says so instead of "building the scene…" for ever.
#
# 3D OFF IS NOT 3D REFUSED. A runner with no WebGL has nothing to check, and
# says so. A page that has WebGL and still came back to 2D refused, and that is
# a failure with the page's own reason - it used to be a press loop that never
# found its button, reported as a bare timeout.
GLB_EARLY_MIN_BYTES = 4096


@extra("3D: Download GLB saves only the scene on screen - not before it has built, not one that changed under the export, not a failed build")
def check_3d_download_waits_for_scene(page, base):
    bad, got = [], []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("download", lambda d: got.append(d))

    def sizes():
        return [pathlib.Path(d.path()).stat().st_size for d in got]

    glb = '#glx button[data-fmt="glb"]'
    ready_js = (f"() => document.querySelector('{glb}') && !document.querySelector('{glb}').disabled"
                " && document.querySelector('#status').textContent === ''")

    def until(expr, what, timeout=READY_3D_MS):
        try:
            page.wait_for_function(expr, timeout=timeout)
            return True
        except Exception:
            st = page.evaluate(f"""() => ({{status: document.querySelector('#status')?.textContent,
              msg: document.querySelector('#glx .msg')?.textContent,
              disabled: document.querySelector('{glb}')?.disabled,
              ready: document.querySelector('#glx')?.dataset.ready,
              mode: document.querySelector('#mode button.on')?.dataset.mode,
              scene: window.__viewer?.info?.config,
              cfg: document.querySelector('#cfg')?.value}})""")
            bad.append(f"timed out waiting for {what} - {st}")
            return False

    def pick_cfg(name):
        page.evaluate("""name => { const sel = document.querySelector('#cfg');
          sel.value = name; sel.dispatchEvent(new Event('change', {bubbles: true})); }""", name)

    scene_is = lambda cfg: (f"() => window.__viewer.info.config === '{cfg}'"
                            f" && document.querySelector('#glx').dataset.ready === '1'")

    page.goto(f"{base}/explorer.html?device=s9510-28dc&config=dc&debug=1", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    if webgl_trouble(page):
        print("[check_3d_download_waits_for_scene] 3D is off: no WebGL here - nothing to export")
        return bad
    # The press is made from the page itself, on the first frame the button is
    # in the DOM - a Playwright click would wait for it to be enabled, which is
    # exactly the wait this check must not do. The same loop notices a page that
    # went back to 2D: the button it is waiting for is never coming.
    pressed = page.evaluate("""() => new Promise(done => {
      const t0 = performance.now();
      const press = () => {
        const b = document.querySelector('#glx button[data-fmt="glb"]');
        if (b) { b.click(); return done({pressed: true}); }
        const status = document.querySelector('#status').textContent;
        const back = document.querySelector('#mode button.on')?.dataset.mode === '2d';
        if (back && (/^3D( unavailable| needs|:)/.test(status) || performance.now() - t0 > 20000))
          return done({refused: status || 'the page went back to 2D and gave no reason'});
        requestAnimationFrame(press);
      };
      document.querySelector('#mode [data-mode="3d"]').click();
      press();
    })""")
    if pressed.get("refused"):
        return bad + [f"3D was refused on a runner that has WebGL: {pressed['refused']!r}"]
    page.wait_for_timeout(3000)
    early = [n for n in sizes() if n < GLB_EARLY_MIN_BYTES]
    if early:
        msg = page.text_content("#glx .msg")
        return bad + [f"early press: saved a {early[0]}-byte file before the scene had built (status {msg!r})"]
    if not until(ready_js, "the scene to come up"):
        return bad
    page.wait_for_timeout(500)
    if got:
        bad.append(f"early press: a file arrived after the scene was up, from a press made before it - {sizes()}")
    got.clear()

    # Ready: the same button gives the model.
    with page.expect_download(timeout=READY_3D_MS) as dl:
        page.click(glb)
    n = pathlib.Path(dl.value.path()).stat().st_size
    if not until("() => !/building GLB/.test(document.querySelector('#glx .msg').textContent)", "the GLB to finish"):
        return bad
    if n < GLB_EARLY_MIN_BYTES:
        bad.append(f"ready press: the GLB is {n} bytes")
    got.clear()

    # A rebuild for another config turns the buttons off at once, and a press
    # made as it starts saves nothing.
    page.evaluate("""() => {
      const b = document.querySelector('#glx button[data-fmt="glb"]');
      window.__offs = 0;
      new MutationObserver(() => { if (b.disabled) window.__offs++; })
        .observe(b, {attributes: true, attributeFilter: ['disabled']});
      const sel = document.querySelector('#cfg');
      sel.value = 'ac';
      sel.dispatchEvent(new Event('change', {bubbles: true}));
      b.click();
    }""")
    page.wait_for_timeout(1500)
    # (the status line is not a signal here: after a config change it holds the
    # drawing's own note, "2 bays")
    if not until(f"() => !document.querySelector('{glb}').disabled", "the rebuild for config ac"):
        return bad
    page.wait_for_timeout(500)
    if not page.evaluate("() => window.__offs"):
        bad.append("rebuild: the Download buttons stayed on while the scene rebuilt for another config")
    if got:
        bad.append(f"rebuild: a press as the rebuild started saved a file - {sizes()}")
    got.clear()

    # A FILE STILL BEING BUILT WHEN THE CONFIGURATION CHANGES IS NOT SAVED. The
    # export is held open (the real exporter's bytes, kept back), the
    # configuration is changed and its scene left to build, and only then are
    # the bytes handed over: they are the ac scene, under a page now showing dc.
    page.evaluate("""() => {
      const v = window.__viewer, real = v.exportData.bind(v);
      window.__realExport = v.exportData;
      window.__handOver = null;
      v.exportData = async fmt => {
        const data = await real(fmt);
        await new Promise(go => { window.__handOver = go; });
        return data;
      };
    }""")
    page.click(glb)
    if until("() => typeof window.__handOver === 'function'", "the held export to have its bytes"):
        pick_cfg("dc")
        if until(scene_is("dc"), "the dc scene to build under a held export"):
            page.evaluate("() => window.__handOver()")
            until("() => /changed while the file was being built/.test(document.querySelector('#glx .msg').textContent)"
                  " && document.querySelector('#glx .msg').classList.contains('bad')",
                  "an export overtaken by a config change to say nothing was saved", READY_MS)
            page.wait_for_timeout(500)
            if got:
                bad.append(f"export during a config change: a file was saved - {sizes()}, "
                           f"named {[d.suggested_filename for d in got]}")
            if page.evaluate(f"() => document.querySelector('{glb}').disabled"):
                bad.append("export during a config change: the buttons stayed off after the refusal")
    page.evaluate("() => { window.__viewer.exportData = window.__realExport; }")
    got.clear()
    if bad:
        return bad

    # A ROUND TRIP WHILE THE SCENE BUILDS ENDS WHERE THE PAGE IS. On dc: change
    # to ac, and back to dc while the ac scene is still building. The viewer's
    # loads are passed through in order with the ac one held, so "still
    # building" is a fact here rather than a race with the runner's speed.
    page.evaluate("""() => {
      const v = window.__viewer, real = v.load.bind(v);
      window.__realLoad = v.load;
      window.__loads = [];
      window.__letAc = null;
      let chain = Promise.resolve();
      v.load = spec => {
        window.__loads.push(spec.config);
        const held = spec.config === 'ac' ? new Promise(go => { window.__letAc = go; }) : null;
        const run = chain.then(() => held).then(() => real(spec));
        chain = run.catch(() => {});
        return run;
      };
    }""")
    pick_cfg("ac")
    if until("() => typeof window.__letAc === 'function'", "the ac scene to start building"):
        pick_cfg("dc")
        # the dc drawing is back on the 2D stage, and the page has had its turn to sync
        until("() => /· dc ·/.test(document.querySelector('#crumb')?.textContent || '')"
              " && document.querySelector('#stage-svg svg')", "the dc drawing after the round trip", READY_MS)
        page.wait_for_timeout(500)
        page.evaluate("() => window.__letAc()")
        if not until(scene_is("dc"), "the scene to end on dc after dc -> ac -> dc", READY_MS):
            bad.append(f"round trip: the page shows dc and the scene holds "
                       f"{page.evaluate('() => window.__viewer.info.config')!r} "
                       f"(loads asked for: {page.evaluate('() => window.__loads')})")
        elif page.evaluate(f"() => document.querySelector('{glb}').disabled"):
            bad.append("round trip: the scene is dc and the Download buttons are still off")
    page.evaluate("() => { window.__viewer.load = window.__realLoad; }")
    if bad:
        return bad

    # A SEATED OPTIC IS A REBUILD TOO: the swap is part of what is on screen.
    # Through the inspector, as a reader does it. The buttons go off for the
    # rebuild and come back, and the file saved then is the model.
    page.evaluate("""() => {
      const bar = document.querySelector('#glx');
      window.__notReady = 0;
      new MutationObserver(() => { if (bar.dataset.ready === '0') window.__notReady++; })
        .observe(bar, {attributes: true, attributeFilter: ['data-ready']});
    }""")
    page.click(".node[data-path='port-0']")
    page.wait_for_selector("#optic", timeout=READY_MS)
    optic = page.evaluate("() => [...document.querySelectorAll('#optic option')].map(o => o.value).find(Boolean)")
    page.select_option("#optic", optic)
    if not until("() => window.__notReady > 0", f"the Download buttons to go off while {optic} is seated", READY_MS):
        return bad
    if not until(scene_is("dc"), "the rebuild for the seated optic"):
        return bad
    with page.expect_download(timeout=READY_3D_MS) as dl:
        page.click(glb)
    n = pathlib.Path(dl.value.path()).stat().st_size
    if n < GLB_EARLY_MIN_BYTES:
        bad.append(f"after a swap: the GLB is {n} bytes")
    until("() => !/building GLB/.test(document.querySelector('#glx .msg').textContent)", "the GLB after a swap to finish")
    got.clear()

    # A BUILD THAT FAILS SAYS SO. The bar read "building the scene…" under a
    # scene that was never coming, and the status line called it "3D
    # unavailable" with 3D up. The next build that works clears both.
    page.evaluate("""() => {
      const v = window.__viewer;
      window.__realLoad = v.load;
      v.load = () => Promise.reject(new Error('no such face'));
    }""")
    pick_cfg("ac")
    if until("() => /scene failed to build/.test(document.querySelector('#glx .msg').textContent)",
             "a failed build to say so in the download bar", READY_MS):
        said = page.evaluate(f"""() => ({{msg: document.querySelector('#glx .msg').textContent,
          bad: document.querySelector('#glx .msg').classList.contains('bad'),
          off: document.querySelector('{glb}').disabled,
          status: document.querySelector('#status').textContent}})""")
        if "building the scene" in said["msg"] or not said["bad"] or not said["off"]:
            bad.append(f"failed build: the download bar reads {said['msg']!r} (bad {said['bad']}, buttons off {said['off']})")
        if "scene failed to build" not in said["status"] or "no such face" not in said["status"] \
                or "unavailable" in said["status"]:
            bad.append(f"failed build: the status line reads {said['status']!r}")
    page.evaluate("() => { window.__viewer.load = window.__realLoad; }")
    pick_cfg("dc")
    if not until(scene_is("dc"), "a build that works after one that failed"):
        return bad
    if "failed" in (page.text_content("#glx .msg") or ""):
        bad.append(f"failed build: after a build that worked the bar still reads {page.text_content('#glx .msg')!r}")
    got.clear()

    # An export with no meshes is a failure in the status line, and no file.
    page.evaluate("""() => {
      const json = new TextEncoder().encode('{"asset":{"version":"2.0"},"scenes":[{}],"scene":0}  ');
      const out = new Uint8Array(20 + json.length), dv = new DataView(out.buffer);
      dv.setUint32(0, 0x46546c67, true); dv.setUint32(4, 2, true); dv.setUint32(8, out.length, true);
      dv.setUint32(12, json.length, true); dv.setUint32(16, 0x4e4f534a, true); out.set(json, 20);
      window.__viewer.exportData = async () => out.buffer;
    }""")
    page.click(glb)
    until("() => document.querySelector('#glx .msg').classList.contains('bad')",
          "the empty export to say it failed", READY_MS)
    page.wait_for_timeout(1000)
    if got:
        bad.append(f"empty export: a file was saved - {sizes()}")
    return bad


# A LINK CANNOT ASK FOR WHAT THE BUTTON REFUSES (#93). The 3D button is disabled
# below portrayal level 3 - the scene would be a plausible wrong box - and a
# ?mode=3d link to such a device has to be refused the same way, with the reason,
# rather than opening the box the gate exists to prevent. The S9502-12SM has no
# bottom face (level 2); the S9510-28DC has all six.
@extra("a ?mode=3d link to a device that cannot do 3D stays in 2D and says why")
def check_mode_link_respects_gate(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))

    def open_link(device, config):
        page.goto(f"{base}/annotate.html", wait_until="load")
        page.wait_for_selector("#stage svg", timeout=READY_MS)
        enc = page.evaluate("""async d => (await import('/vendor/marks.js')).encode(d)""",
                            {"v": 1, "device": device, "config": config, "view": "front", "marks": []})
        page.goto(f"{base}/annotate.html?mode=3d#{enc}", wait_until="load")
        page.wait_for_function(f"() => document.querySelector('#devpick')?.value === '{device}'"
                               f" || /{device}/.test(document.querySelector('#expmsg')?.textContent || '')"
                               " || /restored/.test(document.querySelector('#expmsg')?.textContent || '')",
                               timeout=READY_MS)
        page.wait_for_timeout(1500)
        return page.evaluate("""() => ({on3d: !!document.querySelector('#mode [data-mode="3d"].on'),
          disabled: document.querySelector('#mode [data-mode="3d"]').disabled,
          shown3d: !document.querySelector('#stage-3d').hidden,
          status: document.querySelector('#status').textContent})""")

    low = open_link("s9502-12sm", "")
    if not low["disabled"]:
        bad.append(f"gate: the 3D button is not disabled for the S9502-12SM - {low}")
    if low["on3d"] or low["shown3d"]:
        bad.append(f"gate: a ?mode=3d link opened 3D on a device below level 3 - {low}")
    if "3D needs" not in low["status"]:
        bad.append(f"gate: the refused link does not say why - status is {low['status']!r}")
    if webgl_trouble(page):
        return bad
    ok = open_link("s9510-28dc", "dc")
    if not ok["on3d"]:
        bad.append(f"gate: a ?mode=3d link to a level 3 device did not open in 3D - {ok}")
    return bad


# AN EXPORT IN FLIGHT KEEPS ITS BUTTONS OFF (#94). The export handler disables
# the bar while it works; the 3D mode repaints which exports are on offer on
# every mode change, from the mode alone - so switching to 3D and back during a
# slow PNG turned the buttons on again under the export, and a second could be
# started beside it. The PNG is made slow here by holding canvas.toBlob.
@extra("Annotate: switching modes during an export leaves the export buttons off")
def check_annotate_export_survives_mode_switch(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/annotate.html?device=s9510-28dc", wait_until="load")
    page.wait_for_selector("#stage svg [data-path='port-0']", state="attached", timeout=READY_MS)
    page.evaluate("""() => {
      HTMLAnchorElement.prototype.click = function () {};          // no download
      const toBlob = HTMLCanvasElement.prototype.toBlob;
      HTMLCanvasElement.prototype.toBlob = function (cb, ...rest) {
        window.__held = true;
        setTimeout(() => { window.__held = false; toBlob.call(this, cb, ...rest); }, 6000);
      };
    }""")
    page.click('.btns button[data-act="png-4"]')
    page.wait_for_function("() => window.__held === true", timeout=READY_MS)
    page.click('#mode [data-mode="3d"]')
    page.click('#mode [data-mode="2d"]')
    page.wait_for_timeout(300)
    r = page.evaluate("""() => ({held: window.__held,
      on: [...document.querySelectorAll('.btns button[data-act]')].filter(b => !b.disabled).map(b => b.dataset.act)})""")
    if not r["held"]:
        return bad + ["export: the held PNG finished before the mode was switched - nothing was tested"]
    if r["on"]:
        bad.append(f"export: with a PNG still in flight, a mode switch re-enabled {r['on']}")
    page.wait_for_function("() => window.__held === false", timeout=READY_MS)
    try:
        page.wait_for_function("""() => [...document.querySelectorAll('.btns button[data-act]')].every(b => !b.disabled)""",
                               timeout=READY_MS)
    except Exception:
        bad.append("export: the buttons did not come back after the export finished")
    return bad


# THE 3D LEGEND'S SWATCH IS THE STATE'S COLOUR (#95). A labelled mark with only
# a state has no ring and no lamp colour; the 2D strip shows the colour that
# state paints, read off the drawing's own stylesheet, and the 3D panel showed
# grey. Compared here against the matched lamp's own computed colour in the
# live drawing - the way marks.js asks.
@extra("Annotate 3D: a state-only mark's legend swatch is the colour its state paints")
def check_annotate_3d_legend_state_colour(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/annotate.html?debug=1", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    page.evaluate("""async () => { const m = await import('/vendor/marks.js');
      location.hash = m.encode({v: 1, device: 's9510-28dc', config: 'dc', view: 'front', legend: true,
        marks: [{select: "[data-path='led-sync']", state: 'synced', label: 'in sync'}]}); }""")
    page.reload(wait_until="load")
    page.wait_for_selector("#stage svg [data-path='led-sync']", state="attached", timeout=READY_MS)
    if webgl_trouble(page):
        print("[check_annotate_3d_legend_state_colour] no WebGL here - not exercised")
        return bad
    page.click('#mode [data-mode="3d"]')
    try:
        page.wait_for_function("() => document.querySelector('#legend3d .row .sw')", timeout=READY_3D_MS)
    except Exception:
        return bad + ["legend: no row in the 3D legend for a labelled state-only mark"]
    r = page.evaluate("""() => {
      const rgb = c => { const d = document.createElement('i'); d.style.color = c; document.body.append(d);
                         const v = getComputedStyle(d).color; d.remove(); return v; };
      // as marks.js's litColor: the matched part's lamp, with the mark's state on it.
      // (A probe at the root finds nothing: the stylesheet scopes a state's rule
      // to the component that owns the lamp.)
      const el = document.querySelector("#stage svg [data-path='led-sync']");
      const lamp = el.getAttribute('data-class') === 'led' ? el : el.querySelector('[data-class="led"]');
      const want = getComputedStyle(lamp || el).getPropertyValue('--led-color').trim();
      const sw = document.querySelector('#legend3d .row .sw');
      return {want, wantRgb: rgb(want), got: getComputedStyle(sw).borderTopColor, grey: rgb('#8d939a')}; }""")
    if not r["want"]:
        return bad + ["legend: the drawing paints no colour for state-synced - the check has nothing to compare"]
    if r["got"] != r["wantRgb"]:
        bad.append(f"legend: the 3D swatch is {r['got']}, the state paints {r['want']} ({r['wantRgb']})"
                   + (" - it is the fallback grey" if r["got"] == r["grey"] else ""))
    return bad


# THE ROWS READ THE DOCUMENT THEY ARE DRAWN FROM (#96). The 3D notes are indexed
# by a mark's position, and the scene they read was recomputed only inside the
# sync, which awaits. So deleting the first mark drew the remaining rows against
# the old scene, one position out: the mark now first wore the deleted mark's
# "not in 3D" until the sync caught up. Read here in the same tick as the delete.
@extra("Annotate 3D: after a delete, no row wears another mark's 'not in 3D'")
def check_annotate_3d_rows_after_delete(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/annotate.html?debug=1", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    page.evaluate("""async () => { const m = await import('/vendor/marks.js');
      location.hash = m.encode({v: 1, device: 's9510-28dc', config: 'dc', view: 'front', legend: true,
        marks: [{select: "[data-path='psu-9']", color: '#ffd400', label: 'nowhere'},
                {select: "[data-path='port-0']", color: '#e0574f', label: 'uplink'},
                {select: "[data-path='port-4']", color: '#2bb3c8', label: 'access'}]}); }""")
    page.reload(wait_until="load")
    page.wait_for_selector("#stage svg [data-path='port-0']", state="attached", timeout=READY_MS)
    if webgl_trouble(page):
        print("[check_annotate_3d_rows_after_delete] no WebGL here - not exercised")
        return bad
    page.click('#mode [data-mode="3d"]')
    flags = "[...document.querySelectorAll('#rows .mark')].map(r => /not in 3D/.test(r.querySelector('.notes').textContent))"
    try:
        page.wait_for_function(f"() => JSON.stringify({flags}) === '[true,false,false]'", timeout=READY_3D_MS)
    except Exception:
        return bad + [f"rows: before the delete the flags never settled to [true, false, false] - {page.evaluate('() => ' + flags)}"]
    r = page.evaluate(f"""() => {{
      document.querySelector('#rows .mark .x').click();
      return {{flags: {flags},
               legend: [...document.querySelectorAll('#legend3d .row')].map(e => e.textContent.trim())}}; }}""")
    if r["flags"] != [False, False]:
        bad.append(f"rows: straight after deleting the first mark the 'not in 3D' flags are {r['flags']}, not [False, False]")
    if r["legend"] != ["uplink", "access"]:
        bad.append(f"rows: straight after the delete the 3D legend reads {r['legend']}, not ['uplink', 'access']")
    return bad


# ONE NOTE FOR A SELECTOR THAT NEVER RAN (#97). Invalid CSS is "skipped - bad
# selector"; in 3D the row also said "not in 3D: nothing the scene builds
# matches this mark", which is a statement about a search that was never made.
@extra("Annotate 3D: an invalid selector says 'skipped', and not 'not in 3D' as well")
def check_annotate_3d_bad_selector_note(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/annotate.html?debug=1", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    page.evaluate("""async () => { const m = await import('/vendor/marks.js');
      location.hash = m.encode({v: 1, device: 's9510-28dc', config: 'dc', view: 'front', legend: true,
        marks: [{select: "[data-path=", color: '#ffd400'},
                {select: "[data-path='psu-9']", color: '#2bb3c8'},
                {select: "[data-path='port-0']", color: '#e0574f'}]}); }""")
    page.reload(wait_until="load")
    page.wait_for_selector("#stage svg [data-path='port-0']", state="attached", timeout=READY_MS)
    if webgl_trouble(page):
        print("[check_annotate_3d_bad_selector_note] no WebGL here - not exercised")
        return bad
    page.click('#mode [data-mode="3d"]')
    notes = "[...document.querySelectorAll('#rows .mark .notes')].map(n => n.textContent.replace(/\\s+/g, ' ').trim())"
    # settled when the row that really is not in 3D (psu-9) says so
    try:
        page.wait_for_function(f"() => /not in 3D/.test({notes}[1] || '')", timeout=READY_3D_MS)
    except Exception:
        return bad + [f"notes: the psu-9 row never said 'not in 3D' - {page.evaluate('() => ' + notes)}"]
    got = page.evaluate("() => " + notes)
    if "skipped" not in got[0]:
        bad.append(f"notes: the invalid selector's row does not say 'skipped' - {got[0]!r}")
    if "not in 3D" in got[0]:
        bad.append(f"notes: the invalid selector's row also says 'not in 3D' - {got[0]!r}")
    if "not in 3D" in got[2]:
        bad.append(f"notes: port-0, which is in the scene, says 'not in 3D' - {got[2]!r}")
    return bad


# THE ADDRESS SAYS WHAT IS ON SCREEN (#98). A page opened from a 3D link keeps
# ?mode=3d in its address after the reader returns to 2D, so a reload - or a
# copy of the address bar - reopened in 3D. The mode is written on every switch:
# present in 3D, absent in 2D, the page's other parameters and its hash kept.
@extra("Annotate: the address carries ?mode=3d in 3D and drops it in 2D")
def check_annotate_mode_in_address(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/annotate.html", wait_until="load")
    page.wait_for_selector("#stage svg", timeout=READY_MS)
    enc = page.evaluate("""async () => (await import('/vendor/marks.js')).encode(
      {v: 1, device: 's9510-28dc', config: 'dc', view: 'front',
       marks: [{select: "[data-path='port-0']", color: '#e0574f'}]})""")
    if webgl_trouble(page):
        print("[check_annotate_mode_in_address] no WebGL here - not exercised")
        return bad
    page.goto(f"{base}/annotate.html?mode=3d&debug=1#{enc}", wait_until="load")
    page.wait_for_function("() => !!document.querySelector('#mode [data-mode=\"3d\"].on')", timeout=READY_3D_MS)
    where = "() => ({q: Object.fromEntries(new URLSearchParams(location.search)), hash: location.hash.length})"
    at3d = page.evaluate(where)
    page.click('#mode [data-mode="2d"]')
    page.wait_for_timeout(300)
    at2d = page.evaluate(where)
    if "mode" in at2d["q"]:
        bad.append(f"address: back in 2D the address still says mode={at2d['q']['mode']}")
    if at2d["q"].get("debug") != "1" or at2d["hash"] != at3d["hash"] or not at2d["hash"]:
        bad.append(f"address: switching to 2D lost another parameter or the document - {at3d} -> {at2d}")
    page.click('#mode [data-mode="3d"]')
    page.wait_for_function("() => !!document.querySelector('#mode [data-mode=\"3d\"].on')", timeout=READY_3D_MS)
    page.wait_for_timeout(300)
    again = page.evaluate(where)
    if again["q"].get("mode") != "3d" or again["q"].get("debug") != "1" or again["hash"] != at3d["hash"]:
        bad.append(f"address: back in 3D the address is {again}, not mode=3d with debug=1 and the document")
    return bad


# ANNOTATE'S API FOR AGENTS (spec 2026-10-08-annotate-command-api-design.md
# §2.3): window.portrayalAnnotate sets a document that names another drawing
# and a swap, edits through commands with Undo and Redo, refuses in words
# without touching the document, and reads back a selector that matches
# nothing. Then the page's own row: typing keeps focus and a burst is one Undo.
# Then a link pasted into the open tab restores, and the page's own hash write
# does not loop back into a load.
@extra("annotate.html: window.portrayalAnnotate sets and reads the document, edits through commands with Undo and Redo, restores a pasted hash, and says when a selector matches nothing")
def check_annotate_api(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/annotate.html", wait_until="load")
    api = "window.portrayalAnnotate"
    wait_fn(page, "annotate api: settled", f"() => {api} && {api}.settled")
    if not page.evaluate(f"() => {api}.getDoc().device"):
        return bad + ["annotate api: getDoc() names no device after the page settled"]
    # setDoc: another drawing, a swap on it, and one mark with an id
    res = page.evaluate(f"""() => {api}.setDoc({{device: 's9510-28dc', config: 'dc', view: 'front',
        swaps: {{'port-0': 'generic/qsfp-cable@1'}},
        marks: [{{id: 'one', select: "[data-path='port-0']", color: '#ff2d95'}}]}})""")
    if res.get("error") or res.get("findings"):
        bad.append(f"annotate api: setDoc answered {res}")
    page.wait_for_selector("#stage svg [id='port-0-occupant']", state="attached", timeout=READY_MS)
    got = page.evaluate(f"() => {{ const d = {api}.getDoc(); return [d.device, d.swaps['port-0'], d.marks.length]; }}")
    if got != ["s9510-28dc", "generic/qsfp-cable@1", 1]:
        bad.append(f"annotate api: after setDoc the document reads {got}")
    wait_fn(page, "annotate api: the mark is a row", "() => document.querySelectorAll('#rows .mark').length === 1")
    # apply, as one step, then undo and redo
    r = page.evaluate(f"""() => {api}.apply([{{op: 'mark.add', select: '.does-not-exist', as: 'miss'}},
                                            {{op: 'mark.update', mark: 'one', label: 'Here'}}])""")
    if r.get("error") or r.get("created", {}).get("miss") != "m1":
        bad.append(f"annotate api: apply answered {r}")
    wait_fn(page, "annotate api: two rows", "() => document.querySelectorAll('#rows .mark').length === 2")
    if page.is_hidden("#undoStep"):
        bad.append("annotate api: Undo is not offered after an edit")
    text = page.evaluate(f"() => {api}.describe()")
    if "m1 .does-not-exist: matches nothing" not in text or 'label "Here"' not in text:
        bad.append(f"annotate api: describe() reads {text!r}")
    page.evaluate(f"() => {api}.undo()")
    wait_fn(page, "annotate api: undone", f"() => {api}.getDoc().marks.length === 1 && {api}.getDoc().marks[0].label === ''")
    if page.evaluate(f"() => {api}.getDoc().device") != "s9510-28dc":
        bad.append("annotate api: Undo took the device back")
    if page.is_hidden("#redoStep"):
        bad.append("annotate api: Redo is not offered after an Undo")
    page.evaluate(f"() => {api}.redo()")
    wait_fn(page, "annotate api: redone", "() => document.querySelectorAll('#rows .mark').length === 2")
    # a refusal changes nothing and says why
    before = page.evaluate(f"() => JSON.stringify({api}.getDoc())")
    r = page.evaluate(f"() => {api}.apply({{op: 'mark.remove', mark: 'nope'}})")
    if r.get("error") != "There is no mark nope." or page.evaluate(f"() => JSON.stringify({api}.getDoc())") != before:
        bad.append(f"annotate api: a refused remove answered {r} or changed the document")
    # typing in a row keeps focus, and the burst is one step
    page.click("#rows .mark:first-child .lab")
    page.keyboard.press("End")
    page.keyboard.type("abc")
    page.wait_for_timeout(400)       # past the row's restage
    if not page.evaluate("() => !!document.activeElement?.classList.contains('lab')"):
        bad.append("annotate api: typing in a row's label lost focus")
    if page.evaluate(f"() => {api}.getDoc().marks[0].label") != "Hereabc":
        bad.append(f"annotate api: typing wrote {page.evaluate(f'() => {api}.getDoc().marks[0].label')!r}, expected 'Hereabc'")
    page.keyboard.press("Escape")
    page.evaluate(f"() => {api}.undo()")
    lab = page.evaluate(f"() => {api}.getDoc().marks[0].label")
    if lab != "Here":
        bad.append(f"annotate api: one Undo after typing 'abc' left the label {lab!r}, expected 'Here'")
    # the page's own hash write (share) is not a document arriving: no load, so
    # the Redo just made available survives it
    page.click('button[data-act="share"]')
    page.wait_for_timeout(300)
    if not page.evaluate(f"() => {api}.history().canRedo"):
        bad.append("annotate api: the share button's own hash write reloaded the document")
    # a link pasted into the open tab restores that document
    enc = page.evaluate("""async () => (await import('/vendor/marks.js')).encode({device: 's9510-28dc', config: 'dc',
        marks: [{select: '.pasted', label: 'from a link'}]})""")
    page.evaluate("h => { location.hash = h; }", enc)
    wait_fn(page, "annotate api: pasted hash restored",
            f"() => {api}.getDoc().marks.length === 1 && {api}.getDoc().marks[0].label === 'from a link'")
    if page.evaluate(f"() => {api}.history().canUndo"):
        bad.append("annotate api: a pasted document kept the history of the one before it")
    # a document naming a device that is not here is said, as a finding, and its
    # swaps are not laid on the drawing that is
    res = page.evaluate(f"""() => {api}.setDoc({{device: 'bogus', swaps: {{'port-0': 'generic/qsfp-cable@1'}},
        marks: [{{select: '.x'}}]}})""")
    notes = [f.get("text", "") for f in res.get("findings", []) if f.get("kind") == "note"]
    if not any("bogus" in t for t in notes) or not any("none were applied" in t for t in notes):
        bad.append(f"annotate api: setDoc with an unknown device answered {res}")
    got = page.evaluate(f"() => {{ const d = {api}.getDoc(); return [d.device, Object.keys(d.swaps).length, d.marks.length]; }}")
    if got[0] in ("", "bogus") or got[2] != 1:
        bad.append(f"annotate api: after an unknown device the document reads {got}")
    if page.evaluate(f"() => {api}.ready.then(r => JSON.stringify(r))") != "{}":
        bad.append("annotate api: ready did not resolve to {} on a clean start")
    # setDoc resolves with the answer and the drawing it describes: findings as
    # texts, and the document as getDoc() reads it straight after
    set_doc = lambda d: page.evaluate(f"""async d => {{ const r = await {api}.setDoc(d);
        const g = {api}.getDoc();
        return {{findings: (r.findings || []).map(f => f.kind + ': ' + f.text), error: r.error || null,
                 target: [g.device, g.config, g.view], swaps: g.swaps, describe: {api}.describe()}}; }}""", d)
    # another device, a view only: the device's own configuration, read at once.
    # First, so that the s9510 below is loaded fresh, with nothing seated.
    r = set_doc({"device": "c40g", "view": "rear", "marks": [{"select": ".a"}]})
    if r["error"] or r["findings"] or r["target"] != ["c40g", "base", "rear"]:
        bad.append(f"annotate api: another device's view resolved to {r['target']} with {r['findings']}")
    swap = {"port-0": "generic/qsfp-cable@1"}
    # a configuration that is not here: the device is reached, the swaps are not laid on another drawing
    r = set_doc({"device": "s9510-28dc", "config": "nope", "view": "front", "swaps": swap, "marks": [{"select": ".a"}]})
    if not any("no config called nope" in f for f in r["findings"]) or not any("none were applied" in f for f in r["findings"]):
        bad.append(f"annotate api: a refused config answered {r['findings']}")
    if r["target"][0] != "s9510-28dc" or "port-0" in r["swaps"]:
        bad.append(f"annotate api: after a refused config the document reads {r['target']} with swaps {r['swaps']}")
    # a view that is not here: a note, and the swaps still go on - they belong to the device and configuration
    r = set_doc({"device": "s9510-28dc", "config": "dc", "view": "nope", "swaps": swap, "marks": [{"select": ".a"}]})
    if not any(f.startswith("note: ") and "no view called nope" in f for f in r["findings"]) \
            or any("none were applied" in f or "do not fit" in f for f in r["findings"]):
        bad.append(f"annotate api: a refused view answered {r['findings']}")
    if r["target"][:2] != ["s9510-28dc", "dc"] or r["swaps"].get("port-0") != swap["port-0"]:
        bad.append(f"annotate api: after a refused view the document reads {r['target']} with swaps {r['swaps']}")
    # a configuration and a view changed together: both reached before setDoc
    # resolves, and still so once any reload the shell started has finished
    r = set_doc({"device": "s9510-28dc", "config": "ac", "view": "rear", "marks": [{"select": ".a"}]})
    if r["error"] or r["findings"] or r["target"] != ["s9510-28dc", "ac", "rear"] \
            or not r["describe"].startswith("s9510-28dc, config ac, rear."):
        bad.append(f"annotate api: config and view together resolved to {r['target']} with {r['findings']}, describe {r['describe'][:60]!r}")
    page.wait_for_timeout(3000)
    later = page.evaluate(f"() => {{ const g = {api}.getDoc(); return [g.device, g.config, g.view]; }}")
    if later != ["s9510-28dc", "ac", "rear"]:
        bad.append(f"annotate api: 3 s after setDoc the document reads {later}, not the ac rear it resolved with")

    # portrayal-site#146: the setDoc defects found in review, one case each.
    occupant = "() => document.querySelector(\"#stage svg [id='port-0-occupant']\")?.dataset.ref || null"
    # 3. A SETDOC NAMING NO SWAPS CLEARS THE SEATED ONES. Same device,
    # configuration and view, so nothing reloads on its own: the swap seated by
    # the first call must not survive the second, in the document or the drawing.
    r = set_doc({"device": "s9510-28dc", "config": "dc", "view": "front", "swaps": swap, "marks": [{"select": ".a"}]})
    if r["swaps"].get("port-0") != swap["port-0"]:
        bad.append(f"annotate api #146: the swap to clear was never seated ({r['swaps']}, {r['findings']})")
    r = set_doc({"device": "s9510-28dc", "config": "dc", "view": "front", "marks": [{"select": ".a"}]})
    seated = page.evaluate(occupant)
    if r["error"] or r["findings"] or r["swaps"] or seated == swap["port-0"]:
        bad.append(f"annotate api #146: a setDoc naming no swaps left swaps {r['swaps']}, port-0 holding {seated}, "
                   f"findings {r['findings']}")
    # 1. BACK-TO-BACK SETDOC ON THE SAME DEVICE. From c40g base/rear, the second
    # call is sent while the first is still loading c100g: it must land on its
    # own configuration and view, with no false refusal, and stay there.
    set_doc({"device": "c40g", "config": "base", "view": "rear", "marks": []})
    r = page.evaluate(f"""async () => {{
        const a = {api}.setDoc({{device: 'c100g', view: 'rear'}});
        const b = {api}.setDoc({{device: 'c100g', config: 'docsis-classic', view: 'front'}});
        const [ra, rb] = await Promise.all([a, b]);
        const g = {api}.getDoc();
        return {{findings: (rb.findings || []).map(f => f.text), error: rb.error || null,
                 target: [g.device, g.config, g.view], describe: {api}.describe()}}; }}""")
    if r["error"] or r["findings"] or r["target"] != ["c100g", "docsis-classic", "front"] \
            or not r["describe"].startswith("c100g, config docsis-classic, front."):
        bad.append(f"annotate api #146: back-to-back setDoc resolved to {r['target']} with {r['findings']} "
                   f"{r['error']}, describe {r['describe'][:60]!r}")
    page.wait_for_timeout(2000)
    later = page.evaluate(f"() => {{ const g = {api}.getDoc(); return [g.device, g.config, g.view, {api}.describe().slice(0, 40)]; }}")
    if later[:3] != ["c100g", "docsis-classic", "front"] or not later[3].startswith("c100g, config docsis-classic, front."):
        bad.append(f"annotate api #146: 2 s after back-to-back setDoc the page reads {later}")
    # 2. A DEVICE LOAD THAT NEVER FINISHES is bounded. Its manifest is held, so
    # the load never completes; setDoc must still answer, with a drawing
    # finding, and the document must not name the device it never reached. The
    # bound is shortened for the check: the page reads window.__portrayalLoadMs
    # per call. Then a configuration whose face is held, the same way.
    #
    # THE SHORT BOUND IS THE CHECK'S ALONE: the page reads it only when it was
    # opened with ?debug=1. On this page, which was not, a bound of 1 ms - one
    # no load could meet - changes nothing.
    page.evaluate("() => { window.__portrayalLoadMs = 1; }")
    try:
        r = set_doc({"device": "c40g", "config": "base", "view": "front", "marks": []})
    finally:
        page.evaluate("() => { delete window.__portrayalLoadMs; }")
    if r["error"] or r["findings"] or r["target"][0] != "c40g":
        bad.append(f"annotate api: without ?debug=1 the page still read __portrayalLoadMs - a load answered "
                   f"{r['findings']} {r['error']}, document {r['target']}")
    page.goto(f"{base}/annotate.html?debug=1", wait_until="load")
    wait_fn(page, "annotate api: settled under ?debug=1", f"() => {api} && {api}.settled")
    held = []
    hang = lambda route: held.append(route)
    page.route("**/assets/dist/agr110.configs.json", hang)
    page.route("**/assets/dist/c100g.bdm2m-11plus1.front.svg", hang)
    # 6 s, not 3: the bound is on every load while it is set, the two that are
    # not held included, and a real load on a busy machine has taken over 3 s
    page.evaluate("() => { window.__portrayalLoadMs = 6000; }")
    note = "() => document.querySelector('#stage-svg .stage-note')?.textContent || null"
    race = lambda d: page.evaluate(f"""async d => {{
        const r = await Promise.race([{api}.setDoc(d), new Promise(ok => setTimeout(() => ok('hung'), 20000))]);
        if (r === 'hung') return {{hung: true}};
        const g = {api}.getDoc();
        return {{findings: (r.findings || []).map(f => f.text), error: r.error || null,
                 target: [g.device, g.config, g.view], swaps: g.swaps}}; }}""", d)
    try:
        r = race({"device": "agr110", "swaps": swap, "marks": []})
        if r.get("hung"):
            bad.append("annotate api #146: setDoc on a device whose load never finishes did not answer in 20 s")
        else:
            if not any("did not finish loading" in f for f in r["findings"]) \
                    or not any("none were applied" in f for f in r["findings"]):
                bad.append(f"annotate api #146: a device load that never finished answered {r['findings']}")
            if r["target"][0] == "agr110" or r["swaps"]:
                bad.append(f"annotate api #146: after a stalled device load the document reads {r['target']}, swaps {r['swaps']}")
            # a manifest that never came has not touched the stage: the drawing
            # is still up, and the message box alone says what happened
            if page.evaluate(note) or not page.evaluate("() => !!document.querySelector('#stage-svg svg')"):
                bad.append(f"annotate api #146: after a stalled device load the stage holds note {page.evaluate(note)!r}")
        # the page is not left believing it is on the stalled device: the next
        # document is laid on the drawing it names
        r = set_doc({"device": "c100g", "config": "docsis-classic", "view": "front", "marks": []})
        if r["error"] or r["findings"] or r["target"] != ["c100g", "docsis-classic", "front"] \
                or not r["describe"].startswith("c100g, config docsis-classic, front."):
            bad.append(f"annotate api #146: after a stalled load the next setDoc resolved to {r['target']} "
                       f"with {r['findings']}, describe {r['describe'][:60]!r}")
        # a configuration that times out is not the one the document names
        r = race({"device": "c100g", "config": "bdm2m-11plus1", "view": "front", "marks": []})
        if r.get("hung"):
            bad.append("annotate api #146: setDoc on a configuration whose drawing never loads did not answer in 20 s")
        elif not any("did not finish loading" in f for f in r["findings"]) or r["target"][1] == "bdm2m-11plus1":
            bad.append(f"annotate api #146: a stalled configuration answered {r['findings']}, the document reads {r['target']}")
        else:
            # A FACE THAT NEVER CAME LEAVES NO DRAWING ON THE STAGE: the stage
            # says why, in the sentence the message box has, rather than
            # standing blank; and the next load that arrives takes it away.
            said = page.evaluate(note)
            if "did not finish loading" not in (said or "") or (page.text_content("#expmsg") or "") not in (said or ""):
                bad.append(f"annotate api: a stalled configuration left the stage saying {said!r} "
                           f"(message box: {page.text_content('#expmsg')!r})")
            r = set_doc({"device": "c100g", "config": "docsis-classic", "view": "front", "marks": []})
            if r["error"] or r["findings"] or page.evaluate(note) \
                    or not page.evaluate("() => !!document.querySelector('#stage-svg svg')"):
                bad.append(f"annotate api: after a stalled configuration the next setDoc answered {r['findings']} "
                           f"{r['error']}, stage note {page.evaluate(note)!r}")
    finally:
        page.evaluate("() => { delete window.__portrayalLoadMs; }")
        # released before the routes go, so no handler is left waiting to be cancelled
        for route in held:
            with contextlib.suppress(Exception):
                route.abort()
        page.unroute("**/assets/dist/agr110.configs.json")
        page.unroute("**/assets/dist/c100g.bdm2m-11plus1.front.svg")
    return bad


# A LOAD THAT A NEWER ONE REPLACED IS NOT A STALL. The kit holds one load at a
# time and rejects one a newer load overtook with an error `isSuperseded`
# recognizes (Portrayal #929). A setDoc whose device is still loading when the
# reader switches devices twice in quick succession has been replaced, not
# stalled: Annotate must not log it as a drawing that did not load, must not say
# "did not finish loading", and must not lay the replaced document's swaps on
# the drawing the reader chose. The setDoc's manifest is held until both picks
# are made, so its load is overtaken every time rather than when the timing
# happens to fall that way.
@extra("annotate.html: a load that a newer one replaces is said as replaced, not as a stall, and a link overtaken at boot is not an error")
def check_annotate_replaced_load_is_not_a_stall(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    errors = []
    page.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    page.goto(f"{base}/annotate.html", wait_until="load")
    api = "window.portrayalAnnotate"
    wait_fn(page, "annotate replaced: settled", f"() => {api} && {api}.settled")
    held = []
    page.route("**/assets/dist/agr110.configs.json", lambda route: held.append(route))
    try:
        page.evaluate(f"""() => {{ window.__replaced = {api}.setDoc({{device: 'agr110',
            swaps: {{'port-0': 'generic/qsfp-cable@1'}}, marks: [{{select: '.a'}}]}}); }}""")
        for _ in range(400):     # the route handler runs while the page is waited on
            if held:
                break
            page.wait_for_timeout(50)
        if not held:
            return bad + ["annotate replaced: the setDoc never asked for agr110's manifest"]
        # two device switches, back to back, while the setDoc's load is on the wire
        q = page.locator(".devpick input[type=search]")
        for name in ("c100g", "s9510-28dc"):
            q.fill(name)
            q.press("Enter")
        for route in held:
            route.continue_()
        held.clear()
        r = page.evaluate("""async () => {
            const r = await Promise.race([window.__replaced, new Promise(ok => setTimeout(() => ok('hung'), 12000))]);
            return r === 'hung' ? {hung: true} : {error: r.error || null, findings: (r.findings || []).map(f => f.text)}; }""")
    finally:
        for route in held:
            with contextlib.suppress(Exception):
                route.continue_()
        page.unroute("**/assets/dist/agr110.configs.json")
    if r.get("hung"):
        return bad + ["annotate replaced: setDoc did not answer in 12 s once its load was replaced"]
    if any("did not finish loading" in f for f in r["findings"]) or "Overtaken by a newer drawing" not in (r["error"] or ""):
        bad.append(f"annotate replaced: a replaced load answered error {r['error']!r}, findings {r['findings']}")
    wait_fn(page, "annotate replaced: the last pick is on the stage",
            f"() => {api}.getDoc().device === 's9510-28dc'")
    page.wait_for_timeout(500)
    msg = page.text_content("#expmsg") or ""
    if "did not finish loading" in msg:
        bad.append(f"annotate replaced: the message box reads {msg!r}")
    logged = [e for e in errors if "did not load" in e or "superseded" in e]
    if logged:
        bad.append(f"annotate replaced: a replaced load was logged as an error: {logged[:2]}")
    doc = page.evaluate(f"() => {{ const d = {api}.getDoc(); return [d.device, Object.keys(d.swaps).length]; }}")
    if doc != ["s9510-28dc", 0]:
        bad.append(f"annotate replaced: after the picks the document reads {doc}, expected s9510-28dc with no swaps")

    # A LOAD THAT HANGS AND IS THEN OVERTAKEN IS REPLACED TOO, AND AT BOOT IT IS
    # NOT AN ERROR. Above, the held manifest is released, so the kit gets to
    # reject the replaced load. Here it never answers: a link to agr110 whose
    # manifest is held for good, and one pick while it is out. The kit cannot
    # say "superseded" for a fetch that has not come back, so this used to wait
    # out the 20 s bound and read as a stall, and `ready` then resolved {error}
    # with nothing to tell that apart from a page that could not start.
    # `ready` must resolve well inside the bound, keeping its `error` and
    # carrying `replaced: true` beside it; and the page must not log it or say
    # it in the message box.
    enc = page.evaluate("""async d => (await import('/vendor/marks.js')).encode(d)""",
                        {"device": "agr110", "marks": [{"select": ".port"}]})
    page.goto("about:blank")
    errors.clear()
    page.route("**/assets/dist/agr110.configs.json", lambda route: held.append(route))
    try:
        page.goto(f"{base}/annotate.html#{enc.lstrip('#')}", wait_until="domcontentloaded")
        for _ in range(400):
            if held:
                break
            page.wait_for_timeout(50)
        if not held:
            return bad + ["annotate replaced: the link never asked for agr110's manifest"]
        if page.evaluate(f"() => {api}.settled"):
            bad.append("annotate replaced: the page settled while its link's manifest was still held")
        q = page.locator(".devpick input[type=search]")
        q.fill("s9510-28dc")
        q.press("Enter")
        boot = page.evaluate(f"""async () => {{
            const t = performance.now();
            const r = await Promise.race([{api}.ready, new Promise(ok => setTimeout(() => ok('hung'), 10000))]);
            return r === 'hung' ? {{hung: true}} : {{...r, ms: Math.round(performance.now() - t)}}; }}""")
        if boot.get("hung"):
            bad.append("annotate replaced: with its link's load hung and a pick made, `ready` had not resolved in 10 s "
                       "- the overtaken load waited out the bound")
        elif boot.get("replaced") is not True or "Overtaken by a newer drawing" not in (boot.get("error") or ""):
            # BOTH FIELDS: `error` is the answer this stable API has always
            # given for an overtaken link, and `replaced` says it is not a failure
            bad.append(f"annotate replaced: `ready` resolved {boot} for a link a pick overtook, "
                       "not {error: 'Overtaken by a newer drawing…', replaced: true}")
        wait_fn(page, "annotate replaced: the pick is on the stage after an overtaken link",
                f"() => {api}.getDoc().device === 's9510-28dc' && document.querySelector('#stage-svg svg')")
        msg = page.text_content("#expmsg") or ""
        if "did not finish loading" in msg or "could not restore" in msg \
                or page.evaluate("() => !!document.querySelector('#stage-svg .stage-note')"):
            bad.append(f"annotate replaced: after an overtaken link the page says {msg!r}")
        # the held fetch failing later is still a replaced load, not one to log
        for route in held:
            with contextlib.suppress(Exception):
                route.abort()
        held.clear()
        page.wait_for_timeout(500)
        logged = [e for e in errors if "did not load" in e or "superseded" in e or "could not" in e.lower()]
        if logged:
            bad.append(f"annotate replaced: an overtaken link was logged as an error: {logged[:2]}")
        if page.evaluate(f"() => {api}.getDoc().device") != "s9510-28dc":
            bad.append("annotate replaced: the overtaken link's drawing landed after all")
    finally:
        for route in held:
            with contextlib.suppress(Exception):
                route.abort()
        page.unroute("**/assets/dist/agr110.configs.json")
    return bad


@extra("svg-export.js is the one save/standalone; the showcase re-exports the same functions")
def check_svg_export_leaf(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/index.html", wait_until="load")
    r = page.evaluate("""async () => {
      const S = await import('/site/svg-export.js');
      const A = await import('/site/showcase/artifact.js');
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      svg.innerHTML = '<g data-pt-ui="tabindex" tabindex="0"><rect/></g><g data-pt-ui="*"/>';
      document.body.append(svg);
      const text = S.standalone(svg);
      svg.remove();
      return {same: A.save === S.save && A.standalone === S.standalone && A.saveSvg === S.saveSvg,
              stripped: !text.includes('data-pt-ui') && !text.includes('tabindex'),
              prolog: text.startsWith('<?xml')};
    }""")
    for k in ("same", "stripped", "prolog"):
        if not r.get(k):
            bad.append(f"svg-export: {k} is {r.get(k)!r}")
    return bad


@extra("rack.html: Export - the SVG sheet and PNG carry both faces as configured, a title block and notes, no screen UI")
def check_rack_export_sheet(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    open_fixture(page, base)
    root_tag = lambda t: (re.search(r"<svg[^>]*>", t) or [""])[0]

    dl = export_file(page, "sheet-svg")
    if dl.suggested_filename != "Export-test-sheet.svg":
        bad.append(f"sheet: named {dl.suggested_filename!r}")
    text = pathlib.Path(dl.path()).read_text(encoding="utf-8")
    for ref, want in (("asr-9006", 2), ("as7726-32x", 2), ("tm-280", 4)):   # once per face per item
        got = text.count(f'data-device-ref="{ref}"')
        if got != want:
            bad.append(f"sheet: {ref} drawn {got} times, expected {want}")
    for bit in ('data-pane="front"', 'data-pane="rear"', 'data-ref="cisco/a9k-16x100ge-tr@1',
                'data-ref="generic/qsfp-lc@2', ">Export test<", "Four-post frame, 24U, U1 at the bottom",
                "Rail depth 740 mm · usable depth 1000 mm", "Square holes (cage nuts)"):
        if bit not in text:
            bad.append(f"sheet: missing {bit!r}")
    if not re.search(r"Drawn \d{4}-\d{2}-\d{2} with the Portrayal Rack Builder", text):
        bad.append("sheet: no dated title line")
    for ui_bit in ('class="rk-u', "data-pt-ui", "rk-selected", "rk-sel-ring"):
        if ui_bit in text:
            bad.append(f"sheet: screen UI in the file ({ui_bit})")
    root = root_tag(text)
    if ' width="' not in root or ' height="' not in root:
        bad.append(f"sheet: the root <svg> has no width and height ({root[:120]!r})")

    dl = export_file(page, "front-svg")
    front = pathlib.Path(dl.path()).read_text(encoding="utf-8")
    if dl.suggested_filename != "Export-test-front.svg" or 'data-pane="rear"' in front \
            or 'data-pane="front"' not in front:
        bad.append(f"front only: {dl.suggested_filename!r} is not the front face alone")

    dl = export_file(page, "sheet-png")
    png = pathlib.Path(dl.path()).read_bytes()
    if dl.suggested_filename != "Export-test-sheet.png" or png[:8] != b"\x89PNG\r\n\x1a\n":
        bad.append(f"sheet PNG: {dl.suggested_filename!r} is not a PNG")
    else:
        w, h = int.from_bytes(png[16:20], "big"), int.from_bytes(png[20:24], "big")
        if w < 2000 or h < 2000 or len(png) < 50_000:
            bad.append(f"sheet PNG: {w}x{h}, {len(png)} bytes - not the sheet at 2x")

    dl = export_file(page, "json")
    if dl.suggested_filename != "Export-test.rack.json":
        bad.append(f"rack file: named {dl.suggested_filename!r}")

    # A face nobody drew is listed in the sheet's notes block.
    notes_fixture = json.loads(json.dumps(EXPORT_FIXTURE))
    notes_fixture["id"] = "doc-export-notes"
    notes_fixture["racks"][0]["name"] = "Export notes"
    notes_fixture["racks"][0]["items"].append(
        {"id": "i5", "ref": "no-such-device", "cfg": "base", "label": "mystery", "ru": 22, "face": "front",
         "turned": False, "swaps": {}, "fields": {}})
    open_fixture(page, base, notes_fixture)
    text = pathlib.Path(export_file(page, "sheet-svg").path()).read_text(encoding="utf-8")
    for bit in (">Notes<", "mystery at U22: no front drawing, so the front shows an outline.",
                "mystery at U22: no rear drawing, so the rear shows an outline."):
        if bit not in text:
            bad.append(f"sheet notes: missing {bit!r}")
    return bad


@extra("cables.js lives in site/rack, and the showcase's old address re-exports the same bindings")
def check_cables_moved(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/index.html", wait_until="load")
    r = page.evaluate("""async () => {
      const names = ['COLORS', 'colorOf', 'JACKETS', 'colorOfJacket', 'PLUGS', 'plugColorOf', 'WIDTH', 'TAG_H',
                     'sag2d', 'plugAt', 'ends2d', 'LEAD_DROP', 'drawCables2d', 'looseOn', 'LEAD', 'hangPoints3d',
                     'danglePoints3d', 'clearOf', 'drawCables3d'];
      let R;
      try { R = await import('/site/rack/cables.js'); }
      catch (err) { return {error: String(err.message || err)}; }
      const S = await import('/site/showcase/cables.js');
      return {missing: names.filter(n => !(n in R)), differ: names.filter(n => R[n] !== S[n]),
              extra: Object.keys(S).filter(n => !(n in R))};
    }""")
    if r.get("error"):
        return bad + [f"cables moved: site/rack/cables.js does not load ({r['error']})"]
    for k in ("missing", "differ", "extra"):
        if r[k]:
            bad.append(f"cables moved: {k} {r[k]}")
    return bad


# THE CABLE FIXTURE: the export fixture's rack with the cases cabling has to
# get right - a port on a seated card that holds an optic (core-1's
# slot-2/module/p0), an optic port (leaf-1's port-1), a copper port
# (leaf-1's mgmt-eth), a cross-face pair (leaf-1 shows its front in the front
# pane, the rear-mounted demarc shows its front in the rear pane), an empty
# cage (leaf-1's port-2), and two devices with one ref (the two tm-280
# demarcs, each cabled on the same port path).
#   c1  leaf-1 port-1   -> core-1 slot-2/module/p0   fiber, both in the front pane
#   c2  leaf-1 mgmt-eth -> demarc (U14) port-2-1     copper, front pane to rear pane
#   c3  leaf-1 port-2   -> demarc (U20) port-2-1     end A is an empty cage: a loose end
CABLE_FIXTURE = {
    "format": "portrayal-rack", "version": 1, "id": "doc-cable-fixture",
    "racks": [{
        "id": "r1", "name": "Cable test",
        "frame": {"kind": "four-post", "heightRU": 24, "numbering": "bottom-up",
                  "holes": {"style": "square", "thread": None},
                  "railDepth": 740, "usableDepth": 1000, "ref": None},
        "items": [
            {"id": "i1", "ref": "asr-9006", "cfg": "base", "label": "core-1", "ru": 2, "face": "front",
             "turned": False, "swaps": {"slot-2": "cisco/a9k-16x100ge-tr@1",
                                        "slot-2/module/p0": "generic/qsfp-lc@2"}, "fields": {}},
            {"id": "i2", "ref": "as7726-32x", "cfg": "ac-f2b", "label": "leaf-1", "ru": 14, "face": "front",
             "turned": False, "swaps": {"port-1": "generic/qsfp-lc@2"}, "fields": {}},
            {"id": "i3", "ref": "tm-280", "cfg": "base", "label": "demarc", "ru": 14, "face": "rear",
             "turned": False, "swaps": {}, "fields": {}},
            {"id": "i4", "ref": "tm-280", "cfg": "base", "label": "demarc", "ru": 20, "face": "rear",
             "turned": False, "swaps": {}, "fields": {}},
        ],
        "zeroU": [],
        "cables": [
            {"id": "c1", "a": {"item": "i2", "path": "port-1", "view": "front"},
             "b": {"item": "i1", "path": "slot-2/module/p0", "view": "front"},
             "media": "os2", "purpose": "uplink", "label": "A1",
             "length": {"value": 2, "unit": "m", "source": "entered"}, "route": []},
            {"id": "c2", "a": {"item": "i2", "path": "mgmt-eth", "view": "front"},
             "b": {"item": "i3", "path": "port-2-1", "view": "front"},
             "media": "cat6a", "purpose": "management", "label": "", "route": []},
            {"id": "c3", "a": {"item": "i2", "path": "port-2", "view": "front"},
             "b": {"item": "i4", "path": "port-2-1", "view": "front"},
             "media": "os2", "purpose": "uplink", "label": "", "route": []},
        ]}]}

# How many seated plugs of each kind one item's panel shows in one pane.
PLUGS_JS = """([pane, item]) => {
  const g = document.querySelector(`svg[data-pane="${pane}"] [data-item-id="${item}"][data-panel]`);
  const n = ref => (g ? g.querySelectorAll(`[data-ref^="${ref}"]`).length : -1);
  return {lc: n('generic/lc-plug@2'), rj45: n('generic/rj45-plug@1')};
}"""


@extra("rack.html: a cabled end seats the plug its port takes, drawn but never stored")
def check_rack_cable_plugs(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    plugs = lambda pane, item: page.evaluate(PLUGS_JS, [pane, item])

    # No cables, no plugs: the export fixture draws exactly as before.
    open_fixture(page, base)
    if page.evaluate("() => typeof window.__rack.cableFacts") != "function":
        return bad + ["cable plugs: window.__rack has no cableFacts probe"]
    for pane, item in (("front", "i1"), ("front", "i2"), ("rear", "i3"), ("rear", "i4")):
        got = plugs(pane, item)
        if got != {"lc": 0, "rj45": 0}:
            bad.append(f"cable plugs: with no cables, {item} shows plugs {got}")

    open_fixture(page, base, CABLE_FIXTURE)
    wait_sel(page, "cable plugs: leaf-1's copper plug",
             'svg[data-pane="front"] [data-item-id="i2"][data-panel] [data-ref^="generic/rj45-plug@1"]')
    wait_sel(page, "cable plugs: the far demarc's copper plug",
             'svg[data-pane="rear"] [data-item-id="i4"][data-panel] [data-ref^="generic/rj45-plug@1"]')
    # An LC plug in each bore of each cabled optic, an RJ45 plug in each cabled
    # jack, and nothing in the empty cage.
    for pane, item, want in (("front", "i2", {"lc": 2, "rj45": 1}), ("front", "i1", {"lc": 2, "rj45": 0}),
                             ("rear", "i3", {"lc": 0, "rj45": 1}), ("rear", "i4", {"lc": 0, "rj45": 1})):
        got = plugs(pane, item)
        if got != want:
            bad.append(f"cable plugs: {item} on the {pane} shows {got}, expected {want}")
    if page.query_selector('svg[data-pane="front"] [data-item-id="i2"][data-panel] [data-path="port-2-occupant"]'):
        bad.append("cable plugs: the empty cage port-2 was given an occupant")

    # Derived, not stored: the document's swaps are the file's own.
    swaps = page.evaluate("() => window.__rack.doc().racks[0].items.map(i => i.swaps)")
    want_swaps = [i["swaps"] for i in CABLE_FIXTURE["racks"][0]["items"]]
    if swaps != want_swaps:
        bad.append(f"cable plugs: plugs were written into item.swaps: {swaps}")

    facts = page.evaluate("() => window.__rack.cableFacts()")
    want_seats = {
        "i1": {"slot-2/module/p0-occupant/tx": "generic/lc-plug@2", "slot-2/module/p0-occupant/rx": "generic/lc-plug@2"},
        "i2": {"port-1-occupant/tx": "generic/lc-plug@2", "port-1-occupant/rx": "generic/lc-plug@2",
               "mgmt-eth": "generic/rj45-plug@1"},
        "i3": {"port-2-1": "generic/rj45-plug@1"},
        "i4": {"port-2-1": "generic/rj45-plug@1"}}
    if facts["seats"] != want_seats:
        bad.append(f"cable plugs: the derived seats are {facts['seats']}")
    want_reasons = {"i2|front|port-1": None, "i1|front|slot-2/module/p0": None, "i2|front|mgmt-eth": None,
                    "i3|front|port-2-1": None, "i2|front|port-2": "port-2 holds no optic",
                    "i4|front|port-2-1": None}
    if facts["reasons"] != want_reasons:
        bad.append(f"cable plugs: the loose-end reasons are {facts['reasons']}")

    # The BOM reads item.swaps, so it lists the two optics and no plug.
    _, rows, _ = read_csv(export_file(page, "bom"))
    if any(r["section"] == "Plugs" for r in rows):
        bad.append("cable plugs: the BOM lists a plug, and a derived plug is not a part of the rack")
    optics = next((int(r["qty"]) for r in rows if r["section"] == "Optics" and r["ref"] == "generic/qsfp-lc@2"), None)
    if optics != 2:
        bad.append(f"cable plugs: the BOM counts {optics} QSFP optics, expected 2")
    return bad


def open_cabled(page, base, fixture=None):
    open_fixture(page, base, fixture or CABLE_FIXTURE)
    wait_sel(page, "cable fixture: the rear pane's cables", 'svg[data-pane="rear"] [data-cable-id]')
    wait_sel(page, "cable fixture: the front pane's cables", 'svg[data-pane="front"] [data-cable-id]')


# Both panes as drawn: the viewBox, the rendered box, U1's hit rectangle (the
# shared U scale), and every cable group and tag.
PANES_JS = """() => {
  const box = e => { const r = e.getBoundingClientRect(); return {x: r.x, w: r.width, h: r.height, top: r.top, bottom: r.bottom}; };
  return Object.fromEntries(['front', 'rear'].map(p => {
    const svg = document.querySelector(`svg[data-pane="${p}"]`);
    return [p, {
      vb: svg.getAttribute('viewBox').split(/\\s+/).map(Number), baseBox: svg.dataset.baseBox || null,
      box: box(svg),
      u1: box(svg.querySelector('rect.rk-u[data-u="1"]')),
      layers: svg.querySelectorAll('[data-cables], [data-cable-tags]').length,
      cables: [...svg.querySelectorAll('[data-cables] [data-cable]')].map(g => ({
        id: g.dataset.cableId || null, lead: g.dataset.looseLead || null,
        color: [...g.children].filter(n => n.tagName === 'path').pop()?.getAttribute('stroke') || null,
        box: box(g)})),
      tags: [...svg.querySelectorAll('[data-cable-tags] [data-cable-tag]')].map(t => ({
        id: t.dataset.cableId || null, text: t.querySelector('text').textContent,
        loose: t.classList.contains('not-connected'), why: t.querySelector('title')?.textContent || ''})),
    }];
  }));
}"""


@extra("cables.js colors the Rack Builder's media without changing a showcase color")
def check_cable_colors(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/index.html", wait_until="load")
    got = page.evaluate("""async () => {
      const {colorOf} = await import('/site/rack/cables.js');
      const links = [['os2', 'uplink'], ['copper', 'server'], ['copper', 'management'], ['copper', 'other'],
                     ['om3', ''], ['om4', ''], ['om5', ''], ['cat6', ''], ['cat6a', ''], ['dac', ''], ['aoc', ''],
                     ['unset', ''], ['something-else', ''],
                     // Names every object has are not media, and not purposes.
                     ['toString', ''], ['constructor', ''], ['__proto__', ''], ['hasOwnProperty', ''],
                     ['copper', 'toString'], ['copper', 'constructor']];
      return links.map(([media, purpose]) => [media, purpose, colorOf({media, purpose})]);
    }""")
    want = [["os2", "uplink", "#e8c547"], ["copper", "server", "#5aa7ff"], ["copper", "management", "#9aa3ad"],
            ["copper", "other", "#5aa7ff"],
            ["om3", "", "#2bb3c8"], ["om4", "", "#2bb3c8"], ["om5", "", "#9acd32"], ["cat6", "", "#5aa7ff"],
            ["cat6a", "", "#5aa7ff"], ["dac", "", "#15171a"], ["aoc", "", "#3a3f45"], ["unset", "", "#9aa3ad"],
            ["something-else", "", "#e8c547"],
            ["toString", "", "#e8c547"], ["constructor", "", "#e8c547"], ["__proto__", "", "#e8c547"],
            ["hasOwnProperty", "", "#e8c547"], ["copper", "toString", "#5aa7ff"], ["copper", "constructor", "#5aa7ff"]]
    if len(got) != len(want):
        bad.append(f"cable colors: {len(got)} colors read, {len(want)} expected")
    for g, w in zip(got, want):
        if g != w:
            bad.append(f"cable colors: {g[0]} / {g[1]!r} is {g[2]}, expected {w[2]}")
    return bad


@extra("rack.html: cables hang in both panes, a cross-face run leaves by a tag, a loose end hangs unplugged; the panes widen together and zoom still works")
def check_rack_cables_drawn(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    near = lambda a, b, tol=0.6: abs(a - b) <= tol

    # No cables: the panes are exactly as they were.
    open_fixture(page, base)
    plain = page.evaluate(PANES_JS)
    for p in ("front", "rear"):
        if not near(plain[p]["vb"][2], 514.85, 0.01) or plain[p]["layers"] or plain[p]["baseBox"]:
            bad.append(f"cables drawn: with no cables the {p} pane is {plain[p]['vb']} (base box {plain[p]['baseBox']}) with {plain[p]['layers']} cable layers")

    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cables drawn: {e}"]
    got = page.evaluate(PANES_JS)
    front, rear = got["front"], got["rear"]

    # With cables the rack draws 40 mm lane gutters beside the rails (route.js LANE_GAP) instead of the
    # plain 6 mm, so the recorded base box is the plain viewBox 34 mm wider on each side. These
    # fixture cables are routed (their automatic routes have lane waypoints), and a routed cable's tag
    # sits in its gutter on either side, so each pane then widens by the 260 mm column on BOTH sides
    # (widenForCables, both) and by 40 mm below.
    pf, pr = plain["front"]["vb"], plain["rear"]["vb"]
    lane = 40 - 6
    for p, pv in (("front", pf), ("rear", pr)):
        want = [round(n, 4) for n in (pv[0] - lane, pv[1], pv[2] + 2 * lane, pv[3])]
        if [round(float(n), 4) for n in (got[p]["baseBox"] or "x").split()[:4] if n != "x"] != want:
            bad.append(f"cables drawn: the {p} pane's base box is {got[p]['baseBox']}, the plain viewBox widened by the lane gutters is {want}")
    for name, pane, pv in (("front", front, pf), ("rear", rear, pr)):
        if not (near(pane["vb"][0], pv[0] - lane - 260, 0.01) and near(pane["vb"][2], pv[2] + 2 * lane + 520, 0.01)
                and near(pane["vb"][3], pv[3] + 40, 0.01)):
            bad.append(f"cables drawn: the {name} pane's viewBox is {pane['vb']}, from {pv}")
    # One U scale: the two panes are the same size, and U1 sits at the same height in both.
    if not (near(front["box"]["w"], rear["box"]["w"]) and near(front["box"]["h"], rear["box"]["h"])):
        bad.append(f"cables drawn: the panes differ in size ({front['box']} / {rear['box']})")
    if not (near(front["u1"]["h"], rear["u1"]["h"], 0.3) and near(front["u1"]["top"], rear["u1"]["top"], 1)):
        bad.append(f"cables drawn: U1 is not level across the panes ({front['u1']} / {rear['u1']})")

    ids = lambda pane, key: sorted(c["id"] or "?" for c in pane[key])
    if ids(front, "cables") != ["c1", "c2"] or ids(rear, "cables") != ["c2", "c3"]:
        bad.append(f"cables drawn: front draws {ids(front, 'cables')}, rear {ids(rear, 'cables')}; "
                   "expected c1, c2 and c2, c3")
    by = lambda pane, key, cid: next((c for c in pane[key] if c["id"] == cid), None)
    # c1: both ends in the front pane - a cable hanging from the switch's optic to the router's card port.
    c1 = by(front, "cables", "c1")
    if c1:
        leaf, core = (page.eval_on_selector(f'svg[data-pane="front"] [data-item-id="{i}"][data-panel]',
                      "g => { const r = g.getBoundingClientRect(); return {top: r.top, bottom: r.bottom}; }")
                      for i in ("i2", "i1"))
        if not (leaf["top"] - 1 <= c1["box"]["top"] <= leaf["bottom"] and c1["box"]["bottom"] > core["top"]):
            bad.append(f"cables drawn: c1 spans {c1['box']}, not from leaf-1 {leaf} down into core-1 {core}")
        if c1["color"] != "#e8c547" or c1["lead"]:
            bad.append(f"cables drawn: c1 is {c1['color']}, lead {c1['lead']}; expected OS2 yellow, plugged at both ends")
    if by(front, "tags", "c1"):
        bad.append("cables drawn: c1 has a tag, and both its ends are in one pane")
    # c2: front pane to rear pane - each pane hangs it off to the side column, with a tag naming the far end.
    # (a port is named in words, kit 0.26.0 portLabel: "port-2-1" is "port 2 1")
    for pane, name, text in ((front, "front", "→ demarc port 2 1"), (rear, "rear", "→ leaf-1 mgmt eth")):
        tag = by(pane, "tags", "c2")
        if not tag or tag["text"] != text or tag["loose"]:
            bad.append(f"cables drawn: c2's tag on the {name} is {tag}, expected {text!r}")
    c2 = by(front, "cables", "c2")
    if c2 and c2["color"] != "#5aa7ff":
        bad.append(f"cables drawn: c2 is {c2['color']}, expected copper blue")
    # c3: its far end is an empty cage - an unplugged lead in the rear pane, tagged with the reason.
    c3, tag3 = by(rear, "cables", "c3"), by(rear, "tags", "c3")
    if not c3 or c3["lead"] != "from":
        bad.append(f"cables drawn: c3 on the rear is {c3}, expected an unplugged lead for its A end")
    if not tag3 or not tag3["loose"] or tag3["why"] != "✕ not connected — port-2 holds no optic":
        bad.append(f"cables drawn: c3's not-connected tag is {tag3}")
    if len(front["tags"]) != 1 or len(rear["tags"]) != 2:
        bad.append(f"cables drawn: {len(front['tags'])} front tags and {len(rear['tags'])} rear tags, expected 1 and 2")

    # Zoom and Fit still work on the widened panes.
    panes_h = page.eval_on_selector("#panes", "p => p.getBoundingClientRect().height")
    if (page.text_content("#zoomLevel") or "") != "Fit" or front["box"]["h"] > panes_h + 1:
        bad.append(f"cables drawn: at Fit the front pane is {front['box']['h']} tall in a {panes_h} area")
    # ... and Fit fits the width too, at the default size and in a narrower window.
    for w, h in ((1280, 900), (1000, 900), (800, 700)):
        page.set_viewport_size({"width": w, "height": h})
        try:    # the resize handler runs a frame later; wait for the panes to settle, then judge
            page.wait_for_function("() => document.getElementById('panes').scrollWidth <= document.getElementById('panes').clientWidth + 1", timeout=3000)
        except Exception:
            pass
        over = page.evaluate("""() => { const p = document.getElementById('panes');
          const cols = [...p.children].map(c => c.getBoundingClientRect());
          const svgs = ['front', 'rear'].map(n => document.querySelector(`svg[data-pane="${n}"]`).getBoundingClientRect());
          return {scroll: p.scrollWidth - p.clientWidth, svgOver: svgs.map((r, i) => r.right - cols[i].right)}; }""")
        if over["scroll"] > 1 or any(o > 1 for o in over["svgOver"]):
            bad.append(f"cables drawn: at Fit in a {w}x{h} window the panes overflow their column width ({over})")
    page.set_viewport_size({"width": 1280, "height": 900})
    page.click("#zoomIn")
    zoomed = page.evaluate(PANES_JS)
    if not (zoomed["front"]["box"]["w"] > front["box"]["w"] + 1
            and near(zoomed["front"]["box"]["w"], zoomed["rear"]["box"]["w"])):
        bad.append(f"cables drawn: zooming in gave {zoomed['front']['box']['w']} and {zoomed['rear']['box']['w']} wide panes")
    if ids(zoomed["front"], "cables") != ["c1", "c2"]:
        bad.append("cables drawn: zooming lost the cables")
    page.click("#zoomFit")
    if (page.text_content("#zoomLevel") or "") != "Fit":
        bad.append("cables drawn: Fit did not come back")
    return bad


@extra("rack.html: a face that fails to load leaves its cable end loose, not the rack undrawn; an item's own swap beats a derived plug")
def check_rack_cable_plugs_resilient(page, base):
    import copy
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    loose_key = "i1|front|slot-2/module/p0"
    seats = lambda: page.evaluate("() => window.__rack.cableFacts()")

    # A face that fails to load. core-1 (i1) is the one item whose own swaps make
    # the face read fetch asr-9006.configs.json twice: faceUrl asks for it and
    # swallows a failure, then the swap step asks again and does not. So the
    # first TWO requests for that file after the file is opened are aborted
    # (the facts read comes before the elevations draw) and every later one
    # is let through: configuredFace rejects for the facts read only, and the
    # page's own draw succeeds.
    state = {"abort": 0, "aborted": 0}
    def maybe_abort(route):
        if state["abort"] > 0:
            state["abort"] -= 1
            state["aborted"] += 1
            route.abort()
        else:
            route.continue_()
    page.route("**/assets/dist/asr-9006.configs.json", maybe_abort)
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    state["abort"] = 2
    page.set_input_files("#openFile", files=[{"name": "fixture.rack.json", "mimeType": "application/json",
                                              "buffer": json.dumps(CABLE_FIXTURE).encode()}])
    try:
        wait_sel(page, "resilient: the rack's cables despite a failed face", 'svg[data-pane="rear"] [data-cable-id]')
    except RuntimeError as e:
        return bad + [f"face failure: the rack was not drawn: {e}"]
    if state["aborted"] != 2:
        bad.append(f"face failure: {state['aborted']} requests were aborted, expected 2 (the check did not fail a face)")
    n = page.evaluate("""() => ['front', 'rear'].map(p =>
      document.querySelectorAll(`svg[data-pane="${p}"] [data-item-id][data-panel]`).length)""")
    if n != [4, 4]:
        bad.append(f"face failure: the panes draw {n} devices, expected 4 on each (i1-i4 on both faces)")
    if page.query_selector("#side .rk-error[role=alert]"):
        bad.append("face failure: the side panel says the rack could not be drawn")
    facts = seats()
    if facts["reasons"].get(loose_key) != "this panel has no drawing":
        bad.append(f"face failure: core-1's end reads {facts['reasons'].get(loose_key)!r}, expected the no-drawing sentence")
    others = {k: v for k, v in facts["reasons"].items() if k != loose_key}
    if others != {"i2|front|port-1": None, "i2|front|mgmt-eth": None, "i3|front|port-2-1": None,
                  "i2|front|port-2": "port-2 holds no optic", "i4|front|port-2-1": None}:
        bad.append(f"face failure: the other ends read {others}")
    if facts["seats"].get("i1"):
        bad.append(f"face failure: core-1 was seated plugs from a panel that failed: {facts['seats']['i1']}")
    # c1 has one end loose, so it hangs from leaf-1 as an unplugged lead; c2 is whole.
    c1 = page.evaluate("""() => document.querySelector('svg[data-pane="front"] [data-cable-id="c1"]')?.dataset.looseLead || null""")
    if c1 != "to":
        bad.append(f"face failure: c1 is {c1!r}, expected an unplugged lead for its B end")
    if not page.query_selector('svg[data-pane="front"] [data-item-id="i2"][data-panel] [data-ref^="generic/lc-plug@2"]'):
        bad.append("face failure: leaf-1's plugs went missing with core-1's face")

    if not page.evaluate("() => { const s = window.__rack.cableFacts().seats; return Object.isFrozen(s) && Object.values(s).every(Object.isFrozen); }"):
        bad.append("face failure: the seats handed out are not frozen")

    # The failure is not remembered: a redraw (selecting leaf-1) reads again, and the end lands.
    x, y = u_center(page, "front", 14)
    page.mouse.click(x, y)
    try:
        page.wait_for_function(
            "() => window.__rack.cableFacts().reasons['i1|front|slot-2/module/p0'] === null", timeout=READY_MS)
    except Exception:
        bad.append(f"face failure: after the failure was lifted the end still reads {seats()['reasons'].get(loose_key)!r}")
    else:
        if not page.query_selector('svg[data-pane="front"] [data-item-id="i1"][data-panel] [data-ref^="generic/lc-plug@2"]'):
            bad.append("face failure: after the redraw core-1 shows no plug")

    # An item's own swap wins over a derived plug: leaf-1's port-1 optic has its tx
    # bore seated by the user (a dust cap); only the rx bore takes a derived plug.
    fx = copy.deepcopy(CABLE_FIXTURE)
    fx["racks"][0]["items"][1]["swaps"]["port-1-occupant/tx"] = "common/lc-dust-cap@1"
    open_fixture(page, base, fx)
    wait_sel(page, "own swap: leaf-1's plug", 'svg[data-pane="front"] [data-item-id="i2"][data-panel] [data-ref^="generic/lc-plug@2"]')
    i2 = seats()["seats"].get("i2", {})
    if "port-1-occupant/tx" in i2 or i2.get("port-1-occupant/rx") != "generic/lc-plug@2":
        bad.append(f"own swap: leaf-1's derived seats are {i2}, expected rx only")
    got = page.evaluate("""() => { const g = document.querySelector('svg[data-pane="front"] [data-item-id="i2"][data-panel]');
      const n = r => g.querySelectorAll(`[data-ref^="${r}"]`).length;
      return {plug: n('generic/lc-plug@2'), cap: n('common/lc-dust-cap@1')}; }""")
    if got != {"plug": 1, "cap": 1}:
        bad.append(f"own swap: leaf-1's port-1 shows {got}, expected one plug (rx) and the user's dust cap (tx)")
    if page.evaluate("() => window.__rack.doc().racks[0].items[1].swaps") != fx["racks"][0]["items"][1]["swaps"]:
        bad.append("own swap: the document's swaps changed")
    return bad


# Points where a cable stroke crosses something clickable, computed from the
# strokes' own geometry: sampled along each cable path, mapped to the screen,
# and classified by what is under them with the cable layers made click-through.
STROKE_POINTS_JS = """() => {
  const out = [], layers = [...document.querySelectorAll('[data-cables]')];
  const was = layers.map(l => l.style.pointerEvents);
  layers.forEach(l => { l.style.pointerEvents = 'none'; });
  for (const p of document.querySelectorAll('[data-cables] [data-cable] > path:not([data-leader])')) {
    const len = p.getTotalLength(), m = p.getScreenCTM();
    for (let t = 0.04; t < 0.97; t += 0.02) {
      const q = p.getPointAtLength(len * t), pt = new DOMPoint(q.x, q.y).matrixTransform(m);
      if (pt.x < 5 || pt.y < 5 || pt.x > innerWidth - 5 || pt.y > innerHeight - 5) continue;
      const under = document.elementFromPoint(pt.x, pt.y);
      if (!under || under.closest('[data-cable-tags]')) continue;
      const dev = under.closest('[data-item-id][data-panel]');
      const pane = under.closest('svg[data-pane]')?.dataset.pane;
      if (dev) out.push({x: pt.x, y: pt.y, kind: 'device', item: dev.dataset.itemId, pane});
      else if (under.matches('rect.rk-u')) out.push({x: pt.x, y: pt.y, kind: 'u', u: under.dataset.u, pane});
    }
  }
  layers.forEach((l, i) => { l.style.pointerEvents = was[i]; });
  return out;
}"""

LIT = '<b>&"\''
LONG = "a-rather-long-device-label-" * 5


@extra("rack.html: a cable stroke never takes the click meant for what is beneath it; a tag never outgrows its pane; labels are literal")
def check_rack_cables_clicks(page, base):
    import copy
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return [f"cable clicks: {e}"]
    pts = page.evaluate(STROKE_POINTS_JS)
    on_dev = [p for p in pts if p["kind"] == "device"]
    on_u = [p for p in pts if p["kind"] == "u"]
    if not on_dev or not on_u:
        return [f"cable clicks: found {len(on_dev)} stroke points over a device and {len(on_u)} over an empty U"]
    # Strokes carry no focus stop and no pointer cursor; tags keep both.
    if page.evaluate("() => document.querySelectorAll('[data-cables] [data-cable][tabindex]').length"):
        bad.append("cable clicks: a cable stroke is a tab stop")
    if page.evaluate("() => [...document.querySelectorAll('[data-cables] [data-cable]')].some(g => getComputedStyle(g).pointerEvents !== 'none')"):
        bad.append("cable clicks: a cable stroke takes pointer events")
    if page.evaluate("() => [...document.querySelectorAll('[data-cable-tags] [data-cable-tag]')].some(g => getComputedStyle(g).pointerEvents === 'none' || g.getAttribute('tabindex') !== '0')"):
        bad.append("cable clicks: a tag is not interactive")

    # A real click over a stroke on a device selects that device.
    pt = on_dev[len(on_dev) // 2]
    page.mouse.click(pt["x"], pt["y"])
    try:
        page.wait_for_selector("#iLabel", timeout=READY_MS)
    except Exception:
        bad.append(f"cable clicks: a click on {pt['item']} under a stroke did not select it")
    sel = page.evaluate("() => document.querySelector('#iLabel')?.value || null")
    want = next(i["label"] for i in CABLE_FIXTURE["racks"][0]["items"] if i["id"] == pt["item"])
    if sel != want:
        bad.append(f"cable clicks: clicking {pt['item']} ({want}) under a stroke shows {sel!r} in the inspector")
    # The same device is still selected after the redraw; each pane holds one cable layer, the same cables.
    layers = page.evaluate("() => ['front', 'rear'].map(p => document.querySelectorAll(`svg[data-pane=\"${p}\"] [data-cables]`).length)")
    cables = page.evaluate(PANES_JS)
    if layers != [1, 1] or sorted(c["id"] for c in cables["front"]["cables"]) != ["c1", "c2"] \
            or sorted(c["id"] for c in cables["rear"]["cables"]) != ["c2", "c3"]:
        bad.append(f"cable clicks: after a selection redraw the panes hold {layers} cable layers and "
                   f"{[c['id'] for c in cables['front']['cables']]} / {[c['id'] for c in cables['rear']['cables']]}")

    # A real click over a stroke on an empty U opens the picker.
    pts = page.evaluate(STROKE_POINTS_JS)
    u = next((p for p in pts if p["kind"] == "u"), None)
    if not u:
        bad.append("cable clicks: no stroke over an empty U after the redraw")
    else:
        page.mouse.click(u["x"], u["y"])
        try:
            page.wait_for_selector("#catQuery", state="visible", timeout=READY_MS)
        except Exception:
            bad.append(f"cable clicks: a click on empty U{u['u']} under a stroke did not open the picker")

    # A drag begun on a device under a stroke still moves it. leaf-1 (1U, front U14)
    # goes to the free U22 of the same pane.
    pts = page.evaluate(STROKE_POINTS_JS)
    d = next((p for p in pts if p["kind"] == "device" and p["item"] == "i2"), None)
    if not d:
        bad.append("cable clicks: no stroke point over leaf-1")
    else:
        x1, y1 = u_center(page, "front", 22)
        page.mouse.move(d["x"], d["y"])
        page.mouse.down()
        page.mouse.move((d["x"] + x1) / 2, (d["y"] + y1) / 2, steps=4)
        page.mouse.move(x1, y1, steps=4)
        page.mouse.up()
        try:
            page.wait_for_function("() => window.__rack.doc().racks[0].items[1].ru === 22", timeout=READY_MS)
        except Exception:
            bad.append(f"cable clicks: dragging leaf-1 from under a stroke left it at U{page.evaluate('() => window.__rack.doc().racks[0].items[1].ru')}")

    # Literal text: a label full of markup characters is text in the tag, never markup.
    fx = copy.deepcopy(CABLE_FIXTURE)
    fx["racks"][0]["items"][2]["label"] = LIT
    fx["racks"][0]["items"][1]["label"] = LIT
    fx["racks"][0]["cables"][1]["label"] = LIT
    try:
        open_cabled(page, base, fx)
    except RuntimeError as e:
        return bad + [f"cable clicks: {e}"]
    got = page.evaluate(PANES_JS)
    tag = next((t for t in got["front"]["tags"] if t["id"] == "c2"), None)
    if not tag or tag["text"] != f"→ {LIT} port 2 1":
        bad.append(f"cable clicks: c2's tag reads {tag}, expected the label literally")
    if page.evaluate("() => document.querySelectorAll('svg[data-pane] b').length"):
        bad.append("cable clicks: a label injected markup into the pane")

    # A long label never takes the tag past the room beside the pane.
    fx = copy.deepcopy(CABLE_FIXTURE)
    fx["racks"][0]["items"][2]["label"] = LONG
    fx["racks"][0]["items"][1]["label"] = LONG
    fx["racks"][0]["cables"][1]["label"] = LONG
    try:
        open_cabled(page, base, fx)
    except RuntimeError as e:
        return bad + [f"cable clicks: {e}"]
    over = page.evaluate("""() => ['front', 'rear'].flatMap(p => {
      const svg = document.querySelector(`svg[data-pane="${p}"]`);
      const vb = svg.viewBox.baseVal, base = svg.dataset.baseBox.split(' ').map(Number);
      const inv = svg.getScreenCTM().inverse();
      return [...svg.querySelectorAll('[data-cable-tag] rect')].map(r => {
        const b = r.getBoundingClientRect(), a = new DOMPoint(b.left, b.top).matrixTransform(inv),
              z = new DOMPoint(b.right, b.bottom).matrixTransform(inv);
        return {p, left: a.x - vb.x, right: vb.x + vb.width - z.x};
      });
    })""")
    if not over or any(o["left"] < -0.5 or o["right"] < -0.5 for o in over):
        bad.append(f"cable clicks: a tag runs outside its pane's viewBox ({over})")
    got = page.evaluate(PANES_JS)
    t2 = next((t for t in got["front"]["tags"] if t["id"] == "c2"), None)
    if not t2 or not t2["text"].endswith("…") or len(t2["text"]) > 33:
        bad.append(f"cable clicks: the long tag reads {t2['text'] if t2 else None!r}, expected a short text with an ellipsis")
    titles = page.evaluate("""() => Object.fromEntries(['front', 'rear'].map(p => [p, [...document.querySelectorAll(
      `svg[data-pane="${p}"] [data-cable-tag]`)].map(t => [t.dataset.cableId, t.querySelector('title')?.textContent || ''])]))""")
    full = dict(titles["front"]).get("c2", "")
    if f"→ {LONG} port-2-1" != full:
        bad.append(f"cable clicks: the long tag's title is {full!r}, expected its full text")
    loose = dict(titles["rear"]).get("c3", "")
    if "✕ not connected" not in loose or "port-2 holds no optic" not in loose:
        bad.append(f"cable clicks: the loose tag's title is {loose!r}, expected its text and its reason")
    # Whatever text it is given, the drawing caps the pill to the room.
    cap = page.evaluate("""async () => { const v = await import('/site/rack/cable-view.js');
      return typeof v.pillText === 'function' ? [v.pillText('x'.repeat(300)), v.pillText('short'), v.pillText('😀'.repeat(100))] : null; }""")
    if not cap or len(cap[0]) > 36 or not cap[0].endswith("…") or cap[1] != "short" \
            or not cap[2].endswith("…") or len(list(cap[2])) > 36:
        bad.append(f"cable clicks: pillText caps to {cap}")
    return bad


# The cable form on its own, in a host over the page: what it shows, what it
# warns, and what it hands back. window.__form records the callbacks.
FORM_JS = """async (opts) => {
  let P;
  try { P = await import('/site/rack/cable-panel.js'); }
  catch (err) { return String(err.message || err); }
  document.getElementById('formHost')?.remove();
  const host = document.createElement('aside');
  host.id = 'formHost';
  host.className = 'rk-side';
  host.style.cssText = 'position:fixed;left:0;top:0;z-index:50;width:20rem;max-height:100vh';
  document.body.append(host);
  window.__form = {saved: null, cancelled: 0};
  host.append(P.cableForm({...opts, onSave: f => { window.__form.saved = f; },
                           onCancel: () => { window.__form.cancelled += 1; }}));
  return '';
}"""


@extra("rack.html: the cable form offers the ten media (power and ground too), warns on a mismatch without blocking, and checks the length")
def check_rack_cable_form(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    saved = lambda: page.evaluate("() => window.__form.saved")
    warn = lambda: (page.text_content("#formHost #cWarn") or "")

    # A NEW CABLE between a fiber end and a copper end, offered as OS2.
    err = page.evaluate(FORM_JS, {
        "title": "New cable", "endA": "leaf-1 (U14) port-3", "endB": "demarc (U20) port-2-2",
        "cable": {"media": "os2", "purpose": "", "label": "", "length": None},
        "infoA": {"family": "fiber", "mode": None}, "infoB": {"family": "copper", "mode": None},
        "purposes": ["uplink", "management"]})
    if err:
        return bad + [f"cable form: cable-panel.js does not load ({err})"]
    if (page.text_content("#formHost h3") or "") != "New cable":
        bad.append("cable form: no New cable heading")
    if (page.text_content("#cEndA"), page.text_content("#cEndB")) != ("A: leaf-1 (U14) port-3", "B: demarc (U20) port-2-2"):
        bad.append("cable form: the two ends are not named")
    values = page.eval_on_selector_all("#cMedia option", "os => os.map(o => o.value)")
    if values != ["", "os2", "om3", "om4", "om5", "cat6", "cat6a", "dac", "aoc", "power", "ground"]:
        bad.append(f"cable form: the media offered are {values}")
    if page.input_value("#cMedia") != "os2" or (page.text_content("#cSave") or "") != "Add cable":
        bad.append("cable form: a new cable does not open on its proposed media with an Add cable button")
    if page.eval_on_selector_all("#cPurposes option", "os => os.map(o => o.value)") != ["uplink", "management"]:
        bad.append("cable form: the rack's purposes are not offered")
    if "The ends differ: A is fiber, B is copper." not in warn() or "does not suit end B" not in warn():
        bad.append(f"cable form: the mismatch warning reads {warn()!r}")
    page.select_option("#cMedia", "cat6a")
    if "does not suit end A" not in warn():
        bad.append(f"cable form: the warning did not follow the media ({warn()!r})")
    page.select_option("#cMedia", "")
    if warn() != "The ends differ: A is fiber, B is copper.":
        bad.append(f"cable form: with no media the warning reads {warn()!r}")
    # A length that is not a number stops the save, with a sentence.
    page.fill("#cLength", "abc")
    page.click("#cSave")
    if (page.text_content("#cError") or "") != "Enter a length above 0, or leave it empty." or saved() is not None:
        bad.append(f"cable form: a bad length gave {page.text_content('#cError')!r} and saved {saved()}")
    if page.evaluate("() => document.activeElement.id") != "cLength":
        bad.append("cable form: after a refused save focus is not on the length field")
    ties = page.evaluate("() => [cMedia, cLength].map(e => e.getAttribute('aria-describedby'))")
    if ties != ["cWarn", "cError"]:
        bad.append(f"cable form: the media and length fields point at {ties}, expected the warning and the error")
    # The error goes when the user corrects the field (typing, or the unit), not at the next save.
    page.fill("#cLength", "abcd")
    if page.text_content("#cError") != "":
        bad.append(f"cable form: the length error stays after typing ({page.text_content('#cError')!r})")
    page.click("#cSave")
    if not page.text_content("#cError"):
        bad.append("cable form: a second bad length gave no error")
    page.select_option("#cUnit", "ft")
    if page.text_content("#cError") != "":
        bad.append(f"cable form: the length error stays after a unit change ({page.text_content('#cError')!r})")
    page.select_option("#cUnit", "m")
    # A warning does not: the mismatched cable saves.
    page.fill("#cPurpose", " uplink ")
    page.fill("#cLabel", "A7")
    page.fill("#cLength", "2.5")
    page.select_option("#cUnit", "ft")
    page.click("#cSave")
    want = {"media": "", "purpose": "uplink", "label": "A7", "length": {"value": 2.5, "unit": "ft", "source": "entered"}}
    if saved() != want:
        bad.append(f"cable form: saved {saved()}, expected {want}")
    # Markup characters come back as the literal text, not parsed.
    page.fill("#cPurpose", "<b>&\"'")
    page.fill("#cLabel", "<b>&\"'")
    page.click("#cSave")
    got = saved()
    if (got or {}).get("purpose") != "<b>&\"'" or (got or {}).get("label") != "<b>&\"'":
        bad.append(f"cable form: markup characters came back as {got}")
    page.click("#cCancel")
    if page.evaluate("() => window.__form.cancelled") != 1:
        bad.append("cable form: Cancel did not report")

    # EDITING: the same form, opened on the cable's own values.
    page.evaluate(FORM_JS, {
        "title": "Edit cable", "endA": "a", "endB": "b",
        "cable": {"id": "c1", "media": "om9", "purpose": "core", "label": "B1",
                  "length": {"value": 3, "unit": "m", "source": "entered"}},
        "infoA": None, "infoB": None, "purposes": []})
    got = [page.input_value(s) for s in ("#cMedia", "#cPurpose", "#cLabel", "#cLength", "#cUnit")]
    if got != ["om9", "core", "B1", "3", "m"] or (page.text_content("#cSave") or "") != "Save":
        bad.append(f"cable form: editing opens on {got} with a {page.text_content('#cSave')!r} button")
    if warn():
        bad.append(f"cable form: a warning with nothing known about the ends ({warn()!r})")
    page.fill("#cLength", "")
    page.press("#cLabel", "Enter")
    want = {"media": "om9", "purpose": "core", "label": "B1", "length": None}
    if saved() != want:
        bad.append(f"cable form: Enter saved {saved()}, expected {want}")

    # A hand-edited length the form's own rule would refuse is kept as it was
    # while the user leaves the length alone, and never blocks Save: the form
    # then reports no `length` at all, and the page leaves the cable's alone.
    for odd, label in (({"value": 1e-7, "unit": "m", "source": "routed", "note": "kept"}, "a tiny value"),
                       ({"value": 3, "unit": "yd", "source": "entered"}, "an unknown unit")):
        page.evaluate(FORM_JS, {
            "title": "Edit cable", "endA": "a", "endB": "b",
            "cable": {"id": "c1", "media": "os2", "purpose": "", "label": "", "length": odd},
            "infoA": None, "infoB": None, "purposes": []})
        if page.input_value("#cUnit") != odd["unit"]:
            bad.append(f"cable form: {label} opens with the unit {page.input_value('#cUnit')!r}, expected {odd['unit']!r}")
        page.fill("#cLabel", "touched")             # something else changes; the length does not
        page.click("#cSave")
        got = saved()
        if not got or "length" in got or got.get("label") != "touched" or page.text_content("#cError"):
            bad.append(f"cable form: {label} was rewritten on Save: {got}, error {page.text_content('#cError')!r}")
    # Once the user does change it, the rule applies: a value that is refused is refused,
    # and an unknown unit is not quietly turned into meters.
    page.fill("#cLength", "4")
    page.click("#cSave")
    if page.text_content("#cError") != "Choose m or ft for the new length." or "length" in saved():
        bad.append(f"cable form: a changed length on an unknown unit gave {page.text_content('#cError')!r}, saved {saved()}")
    page.select_option("#cUnit", "ft")
    page.click("#cSave")
    if saved().get("length") != {"value": 4, "unit": "ft", "source": "entered"}:
        bad.append(f"cable form: a changed length saved {saved()}")
    return bad


def port_sel(pane, item, path):
    return f'svg[data-pane="{pane}"] [data-item-id="{item}"][data-panel] [data-path="{path}"]'


@extra("rack.html: Cable mode - click one port, then another, on either face; a taken port says why; Esc backs out; nothing drags")
def check_rack_cable_mode(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cable mode: {e}"]
    cables = lambda: page.evaluate("() => window.__rack.doc().racks[0].cables")
    pressed = lambda: page.get_attribute("#cableBtn", "aria-pressed")
    marks = lambda pane: page.eval_on_selector_all(f'svg[data-pane="{pane}"] .rk-end-pick', "els => els.length")
    notice = lambda: (page.text_content(".rk-side .rk-notice") or "") if page.query_selector(".rk-side .rk-notice") else ""
    if not page.query_selector("#cableBtn"):
        return bad + ["cable mode: no Cable button in the top bar"]

    # Off: a click on a port is a click on its device.
    page.click(port_sel("rear", "i4", "port-2-2"))
    wait_sel(page, "cable mode: off, a port click selects the device", "#iLabel")

    page.click("#cableBtn")
    wait_sel(page, "cable mode: the help panel", "#cableStep")
    if pressed() != "true" or not page.evaluate("() => document.getElementById('panes').classList.contains('rk-cabling')"):
        bad.append("cable mode: the button is not pressed, or the panes are not marked as cabling")

    # One cable per port. leaf-1's port-1 holds an optic, which is drawn
    # beside its cage: a click on the optic is a click on the port.
    page.click(port_sel("front", "i2", "port-1-occupant"))
    wait_sel(page, "cable mode: the refusal", ".rk-side .rk-notice")
    if notice() != "leaf-1 (U14) port-1 already has a cable (A1).":
        bad.append(f"cable mode: a taken port said {notice()!r}")
    if marks("front") or marks("rear"):
        bad.append("cable mode: a refused port was picked")

    # A then B, both in the rear pane: the two demarcs share a ref and a port path.
    token = render_token(page)
    page.click(port_sel("rear", "i3", "port-2-2"))
    wait_rendered(page, "cable mode: the A end", token)
    wait_sel(page, "cable mode: the A end's outline", 'svg[data-pane="rear"] .rk-end-pick')
    step = page.text_content("#cableStep") or ""
    if "From demarc (U14) port-2-2." not in step:
        bad.append(f"cable mode: after the A end the panel reads {step!r}")
    page.click(port_sel("rear", "i4", "port-2-2"))
    wait_sel(page, "cable mode: the form", "#cableForm")
    if (page.text_content("#cEndA"), page.text_content("#cEndB")) != ("A: demarc (U14) port-2-2", "B: demarc (U20) port-2-2"):
        bad.append(f"cable mode: the form names {page.text_content('#cEndA')!r} and {page.text_content('#cEndB')!r}")
    if page.input_value("#cMedia") != "cat6a":
        bad.append(f"cable mode: two copper jacks proposed {page.input_value('#cMedia')!r}, expected cat6a")
    if marks("rear") != 2:
        bad.append(f"cable mode: {marks('rear')} ports are outlined while the form is open, expected both ends")
    page.fill("#cPurpose", "access")
    page.fill("#cLabel", "X1")
    page.fill("#cLength", "1.5")
    page.click("#cSave")
    wait_fn(page, "cable mode: the new cable", "() => window.__rack.doc().racks[0].cables.length === 4")
    # The view is the DEVICE's panel: these two show their front in the rear pane.
    want = {"id": "c4", "a": {"item": "i3", "path": "port-2-2", "view": "front"},
            "b": {"item": "i4", "path": "port-2-2", "view": "front"}, "media": "cat6a", "purpose": "access",
            "label": "X1", "length": {"value": 1.5, "unit": "m", "source": "entered"}, "route": []}
    if cables()[3] != want:
        bad.append(f"cable mode: the new cable is {cables()[3]}")
    # Attached, not visible: the two jacks share an x, so the cable is a vertical line with a zero-width box.
    wait_fn(page, "cable mode: the new cable drawn",
            "() => !!document.querySelector('svg[data-pane=\"rear\"] [data-cables] [data-cable-id=\"c4\"]')")
    # An in-DOM wait lost the geometry: it is a vertical run, so its box has height and its path a d.
    geo = page.evaluate("""() => { const g = document.querySelector('svg[data-pane="rear"] [data-cables] [data-cable-id="c4"]');
      return {h: g.getBBox().height, d: [...g.querySelectorAll('path')].map(p => p.getAttribute('d') || '')}; }""")
    if not geo["h"] > 0 or not geo["d"] or not all(geo["d"]):
        bad.append(f"cable mode: the new cable's drawing is {geo}")
    if page.evaluate(PLUGS_JS, ["rear", "i3"]) != {"lc": 0, "rj45": 2}:
        bad.append("cable mode: the new cable's end did not get its plug")
    if pressed() != "true":
        bad.append("cable mode: adding a cable left Cable mode")
    # That port is taken now; its plug is drawn over the jack, so the click lands on the plug.
    page.click(port_sel("rear", "i3", "port-2-2-occupant"))
    wait_sel(page, "cable mode: the second refusal", ".rk-side .rk-notice")
    if notice() != "demarc (U14) port-2-2 already has a cable (X1).":
        bad.append(f"cable mode: the port just cabled said {notice()!r}")

    # Esc: first the picked end, then the mode.
    page.click(port_sel("front", "i2", "port-3"))
    wait_sel(page, "cable mode: an A end on the front", 'svg[data-pane="front"] .rk-end-pick')
    page.keyboard.press("Escape")
    wait_fn(page, "cable mode: Esc drops the picked end", "() => !document.querySelector('.rk-end-pick')")
    if pressed() != "true":
        bad.append("cable mode: the first Esc left Cable mode")
    page.keyboard.press("Escape")
    wait_fn(page, "cable mode: Esc leaves the mode",
            "() => document.getElementById('cableBtn').getAttribute('aria-pressed') === 'false'")
    if page.evaluate("() => document.getElementById('panes').classList.contains('rk-cabling')"):
        bad.append("cable mode: the panes are still marked as cabling after leaving")

    # Cancel adds nothing. Two empty cages say nothing about a media, so none is proposed.
    page.click("#cableBtn")
    page.click(port_sel("front", "i2", "port-3"))
    wait_sel(page, "cable mode: A again", 'svg[data-pane="front"] .rk-end-pick')
    page.click(port_sel("front", "i2", "port-4"))
    wait_sel(page, "cable mode: the form again", "#cableForm")
    if page.input_value("#cMedia") != "":
        bad.append(f"cable mode: two empty cages proposed {page.input_value('#cMedia')!r}")
    page.click("#cCancel")
    wait_fn(page, "cable mode: Cancel closes the form", "() => !document.getElementById('cableForm')")
    if len(cables()) != 4 or pressed() != "true":
        bad.append(f"cable mode: after Cancel there are {len(cables())} cables, pressed {pressed()}")

    # No drag in Cable mode: a press and a move on a device leaves it where it is.
    box = page.eval_on_selector('svg[data-pane="rear"] [data-item-id="i4"][data-panel]',
                                "g => { const r = g.getBoundingClientRect(); return {x: r.x + 8, y: r.y + r.height / 2}; }")
    page.mouse.move(box["x"], box["y"])
    page.mouse.down()
    page.mouse.move(box["x"], box["y"] - 90, steps=6)
    dragging = page.query_selector("#dragStatus") is not None
    page.mouse.up()
    if dragging or page.evaluate("() => window.__rack.doc().racks[0].items.find(i => i.id === 'i4').ru") != 20:
        bad.append("cable mode: a device could be dragged while cabling")

    # 3D has no ports to click: switching leaves Cable mode.
    page.click('#mode [data-mode="3d"]')
    if pressed() != "false":
        bad.append("cable mode: still on after switching to 3D")
    return bad


# The cable list as shown: each row's id, text, pressed and hidden state, its
# loose-end and warning lines, and the filter buttons and count.
LIST_JS = """() => {
  const list = document.getElementById('cableList');
  if (!list) return null;
  const count = list.querySelector('[data-filter-count]');
  return {
    rows: [...list.querySelectorAll('li[data-cable-item]')].map(li => ({
      id: li.dataset.cableItem, hidden: li.hidden,
      text: li.querySelector('[data-cable-row]').textContent,
      pressed: li.querySelector('[data-cable-row]').getAttribute('aria-pressed') === 'true',
      meta: li.querySelector('.rk-cable-meta')?.textContent || '',
      loose: Object.fromEntries([...li.querySelectorAll('[data-loose]')].map(s => [s.dataset.loose, s.textContent])),
      warnings: [...li.querySelectorAll('[data-warning]')].map(s => s.textContent)})),
    purpose: [...list.querySelectorAll('[data-filter-purpose]')].map(b => b.textContent),
    media: [...list.querySelectorAll('[data-filter-media]')].map(b => b.textContent),
    count: count.textContent, matching: count.dataset.matching, total: count.dataset.total,
  };
}"""

# Per pane: is it in focus mode, which cable ids are lit, which are ghosted.
LIT_JS = """() => Object.fromEntries(['front', 'rear'].map(p => {
  const svg = document.querySelector(`svg[data-pane="${p}"]`);
  const ids = sel => [...new Set([...svg.querySelectorAll(sel)].map(n => n.dataset.cableId))].sort();
  return [p, {focus: svg.classList.contains('cable-focus'), on: ids('[data-cable-id].on'),
              parts: svg.querySelectorAll('[data-cable-id].on').length, ghost: ids('[data-cable-id].ghost')}];
}))"""


@extra("rack.html: the cable list - rows with reasons and warnings, filters that ghost, a row or a tag selects and lights both panes, edit and delete")
def check_rack_cable_list(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cable list: {e}"]
    cables = lambda: page.evaluate("() => window.__rack.doc().racks[0].cables")
    row = lambda cid: f'#cableList [data-cable-row="{cid}"]'
    # A synchronous predicate: is this row pressed (or, with want=False, not pressed)?
    pressed_js = lambda cid, want=True: (
        f"""() => (document.querySelector('#cableList [data-cable-row="{cid}"]')"""
        f"""?.getAttribute('aria-pressed') === 'true') === {'true' if want else 'false'}""")

    try:
        wait_sel(page, "cable list: the list under the summary", "#cableList")
    except RuntimeError as e:
        return bad + [str(e)]
    got = page.evaluate(LIST_JS)
    by = {r["id"]: r for r in got["rows"]}
    if list(by) != ["c1", "c2", "c3"]:
        return bad + [f"cable list: the rows are {list(by)}"]
    if by["c2"]["text"] != "leaf-1 (U14) mgmt-eth → demarc (U14) port-2-1":
        bad.append(f"cable list: c2 reads {by['c2']['text']!r}")
    # c1 is routed and lands at both ends, so its 2 m is said as a cord with its
    # spare (spare.js; the figure is check_rack_cable_spare's to hold).
    if not re.fullmatch(r"A1 · OS2 single-mode fiber · uplink · 2 m cord, \d+(\.\d+)? m spare", by["c1"]["meta"]):
        bad.append(f"cable list: c1's details read {by['c1']['meta']!r}")
    if by["c3"]["loose"] != {"a": "Loose end A: port-2 holds no optic."} or by["c1"]["loose"] or by["c2"]["loose"]:
        bad.append(f"cable list: the loose ends are {[(r['id'], r['loose']) for r in got['rows']]}")
    if by["c3"]["warnings"] != ["OS2 single-mode fiber does not suit end B, which is copper."] or by["c1"]["warnings"]:
        bad.append(f"cable list: the warnings are {[(r['id'], r['warnings']) for r in got['rows']]}")
    if got["purpose"] != ["uplink (2)", "management (1)"] or got["media"] != ["os2 (2)", "cat6a (1)"]:
        bad.append(f"cable list: the filters are {got['purpose']} and {got['media']}")
    if (got["count"], got["matching"], got["total"]) != ("3 of 3 cables match.", "3", "3"):
        bad.append(f"cable list: the count reads {got['count']!r}")

    # A ROW selects its cable: lit in BOTH panes (the run and its tag in each), every other one dimmed.
    page.click(row("c2"))
    wait_fn(page, "cable list: row c2 selected", pressed_js("c2"))
    if page.evaluate("() => document.activeElement.id") != "cableRow-c2":
        bad.append("cable list: focus did not stay on the clicked row")
    lit = page.evaluate(LIT_JS)
    for p in ("front", "rear"):
        if not lit[p]["focus"] or lit[p]["on"] != ["c2"] or lit[p]["parts"] != 2:
            bad.append(f"cable list: with c2 selected the {p} pane is {lit[p]}")
    if not page.is_visible("#cableEdit") or not page.is_visible("#cableDelete"):
        bad.append("cable list: the selected row has no Edit and Delete")
    page.click(row("c2"))
    wait_fn(page, "cable list: a second click lets the row go", pressed_js("c2", False))
    if page.evaluate(LIT_JS)["front"]["focus"]:
        bad.append("cable list: the panes are still dimmed with nothing selected")

    # A TAG selects its cable too, by a click or from the keyboard.
    page.click('svg[data-pane="rear"] [data-cable-tags] [data-cable-tag][data-cable-id="c3"]')
    wait_fn(page, "cable list: the rear tag selects c3", pressed_js("c3"))
    page.focus('svg[data-pane="front"] [data-cable-tag][data-cable-id="c2"]')
    page.keyboard.press("Enter")
    wait_fn(page, "cable list: Enter on the front tag selects c2", pressed_js("c2"))
    if page.evaluate(LIT_JS)["rear"]["on"] != ["c2"]:
        bad.append("cable list: the front tag did not light the cable's rear end")
    if page.evaluate("() => document.activeElement.id") != "cableRow-c2":
        bad.append("cable list: a keyboard selection by a tag did not put focus on the row")
    page.keyboard.press("Escape")
    wait_fn(page, "cable list: Esc lets the selection go", pressed_js("c2", False))
    # Space on a tag selects too; selecting a device lets the cable go.
    page.focus('svg[data-pane="rear"] [data-cable-tags] [data-cable-tag][data-cable-id="c3"]')
    page.keyboard.press("Space")
    wait_fn(page, "cable list: Space on the rear tag selects c3", pressed_js("c3"))
    page.click('svg[data-pane="rear"] [data-item-id="i4"][data-panel]', position={"x": 8, "y": 8})
    wait_sel(page, "cable list: selecting a device", "#iLabel")
    wait_fn(page, "cable list: a device selection clears the cable", pressed_js("c3", False))
    if page.evaluate(LIT_JS)["rear"]["focus"]:
        bad.append("cable list: the panes are still dimmed after selecting a device")
    page.keyboard.press("Escape")
    wait_sel(page, "cable list: the list is back", "#cableList")

    # THE FILTERS ghost what they leave out and hide its row; the two axes combine.
    page.click('#cableList [data-filter-media="os2"]')
    got = page.evaluate(LIST_JS)
    if (got["count"], got["matching"]) != ("2 of 3 cables match.", "2"):
        bad.append(f"cable list: filtering to os2 reads {got['count']!r}")
    if [r["id"] for r in got["rows"] if r["hidden"]] != ["c2"]:
        bad.append("cable list: the os2 filter did not hide c2's row alone")
    lit = page.evaluate(LIT_JS)
    if lit["front"]["ghost"] != ["c2"] or lit["rear"]["ghost"] != ["c2"]:
        bad.append(f"cable list: the os2 filter ghosted {lit['front']['ghost']} and {lit['rear']['ghost']}")
    if page.get_attribute('#cableList [data-filter-media="os2"]', "aria-pressed") != "true":
        bad.append("cable list: the pressed filter is not marked")
    page.click('#cableList [data-filter-purpose="management"]')
    if page.evaluate(LIST_JS)["matching"] != "0":
        bad.append("cable list: os2 and management together should match nothing")
    page.click('#cableList [data-filter-media="os2"]')
    if page.evaluate(LIST_JS)["matching"] != "1":
        bad.append("cable list: management alone should match c2")
    page.click('#cableList [data-filter-purpose="management"]')
    lit = page.evaluate(LIT_JS)
    if page.evaluate(LIST_JS)["matching"] != "3" or lit["front"]["ghost"] or lit["rear"]["ghost"]:
        bad.append("cable list: releasing the filters did not bring every cable back")

    # A SELECTED cable a filter leaves out is never ghosted, and its row stays with Edit and Delete.
    page.click(row("c2"))
    wait_fn(page, "cable list: c2 selected before the filter", pressed_js("c2"))
    page.click('#cableList [data-filter-media="os2"]')
    got = page.evaluate(LIST_JS)
    lit = page.evaluate(LIT_JS)
    for p in ("front", "rear"):
        if lit[p]["on"] != ["c2"] or "c2" in lit[p]["ghost"]:
            bad.append(f"cable list: the selected c2, filtered out, is {lit[p]} in the {p} pane")
    c2 = next(r for r in got["rows"] if r["id"] == "c2")
    if c2["hidden"] or not page.is_visible("#cableEdit") or not page.is_visible("#cableDelete"):
        bad.append("cable list: the selected cable's row or its Edit and Delete vanished under a filter")
    if page.query_selector('li[data-cable-item="c2"] [data-off-filter]') is None:
        bad.append("cable list: the selected row does not say it is outside the filter")
    if (got["count"], got["matching"]) != ("2 of 3 cables match.", "2"):
        bad.append(f"cable list: the count with c2 kept visible reads {got['count']!r}")
    page.click('#cableList [data-filter-media="os2"]')
    page.click(row("c2"))
    wait_fn(page, "cable list: c2 let go", pressed_js("c2", False))

    # EDIT reuses the form, opened on the cable's own values.
    page.click(row("c1"))
    wait_sel(page, "cable list: Edit", "#cableEdit")
    page.click("#cableEdit")
    wait_sel(page, "cable list: the form", "#cableForm")
    vals = [page.input_value(s) for s in ("#cMedia", "#cPurpose", "#cLabel", "#cLength", "#cUnit")]
    if vals != ["os2", "uplink", "A1", "2", "m"] or (page.text_content("#cSave") or "") != "Save":
        bad.append(f"cable list: the edit form opens on {vals}")
    page.select_option("#cMedia", "om4")
    page.fill("#cLabel", "A2")
    page.click("#cSave")
    wait_fn(page, "cable list: the edit saved",
            "() => window.__rack.doc().racks[0].cables[0].label === 'A2'")
    c1 = cables()[0]
    if (c1["media"], c1["a"], c1["length"]) != ("om4", {"item": "i2", "path": "port-1", "view": "front"},
                                                {"value": 2, "unit": "m", "source": "entered"}):
        bad.append(f"cable list: after the edit c1 is {c1}")
    wait_fn(page, "cable list: the edited cable stays selected", pressed_js("c1"))
    color = page.eval_on_selector('svg[data-pane="front"] [data-cables] [data-cable-id="c1"]',
                                  "g => [...g.children].filter(n => n.tagName === 'path').pop().getAttribute('stroke')")
    if color != "#2bb3c8":
        bad.append(f"cable list: c1 is drawn {color} after becoming OM4, expected aqua")

    # DELETE takes the cable, its drawing and its derived plug.
    page.click(row("c3"))
    wait_sel(page, "cable list: Delete", "#cableDelete")
    page.click("#cableDelete")
    wait_fn(page, "cable list: c3 deleted", "() => window.__rack.doc().racks[0].cables.length === 2")
    wait_fn(page, "cable list: c3 off the drawing",
            """() => !document.querySelector('svg[data-pane="rear"] [data-cable-id="c3"]')""")
    if page.evaluate(PLUGS_JS, ["rear", "i4"]) != {"lc": 0, "rj45": 0}:
        bad.append("cable list: the deleted cable's plug is still seated on the far demarc")
    if [c["id"] for c in cables()] != ["c1", "c2"]:
        bad.append(f"cable list: Delete left {[c['id'] for c in cables()]}, expected c1 and c2")

    # What is left survives a reload (autosave).
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    wait_sel(page, "cable list: the list after a reload", "#cableList")
    if [r["id"] for r in page.evaluate(LIST_JS)["rows"]] != ["c1", "c2"]:
        bad.append("cable list: the cables did not survive a reload")

    # A FILTER NO CABLE MATCHES any more is dropped before anything is painted.
    unfiltered = lambda what: (
        [what + f": ghosted {lit_[p]['ghost']} in {p}" for p in ("front", "rear") if (lit_ := page.evaluate(LIT_JS))[p]["ghost"]]
        + ([what + ": a filter button is still pressed"] if page.query_selector("#cableList [aria-pressed=true][data-filter-purpose], #cableList [aria-pressed=true][data-filter-media]") else []))
    page.click('#cableList [data-filter-purpose="management"]')
    page.click(row("c2"))
    wait_sel(page, "cable list: Delete on c2", "#cableDelete")
    page.click("#cableDelete")
    wait_fn(page, "cable list: c2 deleted under a filter", "() => window.__rack.doc().racks[0].cables.length === 1")
    wait_fn(page, "cable list: the redraw", "() => !document.querySelector('[data-cable-id=\"c2\"]')")
    bad += unfiltered("cable list: after deleting the last cable of a filtered purpose")
    page.click('#cableList [data-filter-purpose="uplink"]')
    page.click(row("c1"))
    wait_sel(page, "cable list: Edit on c1", "#cableEdit")
    page.click("#cableEdit")
    wait_sel(page, "cable list: the form", "#cableForm")
    page.fill("#cPurpose", "core")
    page.click("#cSave")
    wait_fn(page, "cable list: c1 re-purposed", "() => window.__rack.doc().racks[0].cables[0].purpose === 'core'")
    wait_sel(page, "cable list: the list after the edit", "#cableList [data-filter-purpose]")
    bad += unfiltered("cable list: after re-purposing the last cable of a filtered purpose")
    # With no cables the section says how to add one, and a stale filter does not come back.
    page.click('#cableList [data-filter-purpose="core"]')   # c1 is still selected from its edit
    wait_sel(page, "cable list: Delete on c1", "#cableDelete")
    page.click("#cableDelete")
    wait_sel(page, "cable list: the empty state", "#cableList #cableEmpty")
    if (page.text_content("#cableEmpty") or "") != "No cables yet. Use Cable mode and click a port at each end.":
        bad.append(f"cable list: the empty state reads {page.text_content('#cableEmpty')!r}")
    page.click("#cableBtn")
    page.click(port_sel("front", "i2", "port-3"))
    wait_sel(page, "cable list: A", 'svg[data-pane="front"] .rk-end-pick')
    page.click(port_sel("front", "i2", "port-4"))
    wait_sel(page, "cable list: the form", "#cableForm")
    page.fill("#cPurpose", "core")
    page.click("#cSave")
    wait_sel(page, "cable list: the new cable's row", "#cableList [data-cable-row]")
    got = page.evaluate(LIST_JS)
    if got["matching"] != "1" or [r["hidden"] for r in got["rows"]] != [False]:
        bad.append(f"cable list: a stale filter came back ({got['count']!r}, rows {got['rows']})")
    bad += unfiltered("cable list: after the list emptied and refilled")
    return bad


@extra("rack.html: Cable mode - a picked end never outlives its device, Esc cancels the form, Save reads the rack as it is now, the Frame button leaves the mode")
def check_rack_cable_stale(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cable stale: {e}"]
    doc = lambda: page.evaluate("() => window.__rack.doc().racks[0]")
    pressed = lambda: page.get_attribute("#cableBtn", "aria-pressed")
    picks = lambda: page.eval_on_selector_all(".rk-end-pick", "els => els.length")
    step = lambda: (page.text_content("#cableStep") or "") if page.query_selector("#cableStep") else ""
    notice = lambda: (page.text_content(".rk-side .rk-notice") or "") if page.query_selector(".rk-side .rk-notice") else ""
    # A device removed from the rack as an edit that bypasses the frame form would: item i1 and its cable.
    drop_i1 = """() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, items: r.items.filter(i => i.id !== 'i1'),
                                 cables: r.cables.filter(c => c.a.item !== 'i1' && c.b.item !== 'i1')}); }"""
    free_i1 = port_sel("front", "i1", "slot-2/module/p1")

    # 1. A picked A end goes with its device.
    page.click("#cableBtn")
    page.click(free_i1)
    wait_sel(page, "cable stale: A on core-1", 'svg[data-pane="front"] .rk-end-pick')
    page.evaluate(drop_i1)
    wait_fn(page, "cable stale: the pick is dropped", "() => !document.querySelector('.rk-end-pick')")
    if not step().startswith("Click the port at one end"):
        bad.append(f"cable stale: after its device went the help reads {step()!r}")
    if pressed() != "true":
        bad.append("cable stale: losing the picked device left Cable mode")
    # ...and with the form open, the form goes too, with a sentence, and nothing is added.
    open_cabled(page, base)
    page.click("#cableBtn")
    page.click(free_i1)
    wait_sel(page, "cable stale: A again", 'svg[data-pane="front"] .rk-end-pick')
    page.click(port_sel("front", "i2", "port-3"))
    wait_sel(page, "cable stale: the form", "#cableForm")
    page.evaluate(drop_i1)
    wait_fn(page, "cable stale: the form closes", "() => !document.getElementById('cableForm')")
    if "not added" not in notice() or "removed" not in notice():
        bad.append(f"cable stale: closing the form said {notice()!r}")
    if len(doc()["cables"]) != 2 or picks():
        bad.append(f"cable stale: {len(doc()['cables'])} cables and {picks()} outlines after the device went")

    # 2. Esc cancels the form from the focused field; the next Esc leaves the mode (no end is held).
    open_cabled(page, base)
    page.click("#cableBtn")
    for field in ("#cMedia", "#cLabel"):
        page.click(port_sel("front", "i2", "port-3"))
        wait_sel(page, "cable stale: A for Esc", 'svg[data-pane="front"] .rk-end-pick')
        page.click(port_sel("front", "i2", "port-4"))
        wait_sel(page, "cable stale: the form for Esc", "#cableForm")
        page.focus(field)
        page.keyboard.press("Escape")
        wait_fn(page, f"cable stale: Esc in {field} cancels the form", "() => !document.getElementById('cableForm')")
        if len(doc()["cables"]) != 3 or pressed() != "true":
            bad.append(f"cable stale: Esc in {field} left {len(doc()['cables'])} cables, pressed {pressed()}")
    page.keyboard.press("Escape")
    wait_fn(page, "cable stale: the next Esc leaves the mode",
            "() => document.getElementById('cableBtn').getAttribute('aria-pressed') === 'false'")

    # 3. Save reads the rack as it is now: Undo beside the open form stands.
    open_cabled(page, base)
    page.click("#frameBtn")
    page.fill("#fHeight", "12")
    page.dispatch_event("#fHeight", "change")
    wait_fn(page, "cable stale: shrunk", "() => window.__rack.doc().racks[0].frame.heightRU === 12")
    wait_sel(page, "cable stale: Undo offered", "#undoShrink")
    page.click("#cableBtn")
    page.click(port_sel("front", "i2", "port-3"))
    wait_sel(page, "cable stale: A on the shrunk rack", 'svg[data-pane="front"] .rk-end-pick')
    page.click(port_sel("front", "i2", "port-4"))
    wait_sel(page, "cable stale: the form on the shrunk rack", "#cableForm")
    page.click("#undoShrink")
    wait_fn(page, "cable stale: Undo stood", "() => window.__rack.doc().racks[0].frame.heightRU === 24")
    wait_sel(page, "cable stale: the form survives Undo", "#cableForm")
    page.click("#cSave")
    wait_fn(page, "cable stale: the cable saved", "() => window.__rack.doc().racks[0].cables.length === 4")
    if doc()["frame"]["heightRU"] != 24:
        bad.append(f"cable stale: Save reverted the Undo (frame {doc()['frame']['heightRU']}U)")

    # The same, in the window before the form is rebuilt: the rack changes and Save is pressed in one task.
    page.click(port_sel("front", "i2", "port-6"))
    wait_sel(page, "cable stale: A for the race", 'svg[data-pane="front"] .rk-end-pick')
    page.click(port_sel("front", "i2", "port-7"))
    wait_sel(page, "cable stale: the form for the race", "#cableForm")
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, frame: {...r.frame, heightRU: 30}});
      document.getElementById('cSave').click(); }""")
    wait_fn(page, "cable stale: the raced cable saved", "() => window.__rack.doc().racks[0].cables.length === 5")
    if doc()["frame"]["heightRU"] != 30:
        bad.append(f"cable stale: a Save pressed as the rack changed wrote the old rack back (frame {doc()['frame']['heightRU']}U)")

    # 4. The Frame button is a different activity: it turns Cable mode off.
    page.click(port_sel("front", "i2", "port-5"))
    wait_sel(page, "cable stale: A before Frame", 'svg[data-pane="front"] .rk-end-pick')
    page.click("#frameBtn")
    wait_sel(page, "cable stale: the frame form", "#fHeight")
    if pressed() != "false" or picks() or page.evaluate("() => document.getElementById('panes').classList.contains('rk-cabling')"):
        bad.append(f"cable stale: Frame left Cable mode {pressed()} with {picks()} outlines")
    page.keyboard.press("Escape")
    wait_fn(page, "cable stale: Esc closes the frame form", "() => !document.getElementById('fHeight')")
    return bad


REASONS_JS = "() => window.__rack.cableFacts().reasons"


def select_item(page, pane, item):
    # Dispatched to the panel itself: a cable or another device's panel may
    # be drawn over its middle, and onPaneClick reads the same target.
    page.dispatch_event(f'svg[data-pane="{pane}"] [data-item-id="{item}"][data-panel]', "click")
    wait_fn(page, f"select {item}", "() => !!document.getElementById('iLabel')")


@extra("rack.html: cables follow their devices - a move keeps them, a remove asks, a shrink and a changed port leave loose ends with reasons")
def check_rack_cable_lifecycle(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    # Nothing here may open a browser dialog: a device with cables asks in the side panel.
    page.on("dialog", lambda d: (bad.append(f"lifecycle: a browser dialog opened ({d.message!r})"), d.dismiss()))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"lifecycle: {e}"]
    doc = lambda: page.evaluate("() => window.__rack.doc().racks[0]")
    reason_is = lambda key, want: (
        f"() => window.__rack.cableFacts().reasons[{json.dumps(key)}] === {json.dumps(want)}")
    before = doc()["cables"]

    # A MOVE keeps the cables: they name the item, not its place.
    select_item(page, "front", "i2")
    page.keyboard.press("ArrowUp")
    wait_fn(page, "lifecycle: leaf-1 moved up", "() => window.__rack.doc().racks[0].items[1].ru === 15")
    # A routed length is recomputed on every redraw (spec 8), so moving a device may re-measure it; nothing
    # else may change - ends, media, label, route, routeEdited and entered lengths all stay exactly as they were.
    # A routed length's value may change with a move, but it may not appear or vanish: it is a marker.
    unrouted = lambda cs: [{k: ("routed" if k == "length" and v.get("source") == "routed" else v) for k, v in c.items()} for c in cs]
    if unrouted(doc()["cables"]) != unrouted(before):
        bad.append("lifecycle: moving a device changed its cables")
    wait_sel(page, "lifecycle: c1 drawn after the move", 'svg[data-pane="front"] [data-cables] [data-cable-id="c1"]')
    if page.get_attribute('svg[data-pane="front"] [data-cables] [data-cable-id="c1"]', "data-loose-lead"):
        bad.append("lifecycle: c1 came loose when its device moved")

    # A CHANGED PORT (a new configuration clears the swaps, as an Explorer
    # change can): the optic is gone, the cable stays, and it says why.
    page.select_option("#iCfg", "ac-b2f")
    wait_fn(page, "lifecycle: port-1 lost its optic", reason_is("i2|front|port-1", "port-1 holds no optic"))
    if len(doc()["cables"]) != 3:
        bad.append("lifecycle: a cable was deleted when its port's optic went")
    wait_sel(page, "lifecycle: c1 hangs loose from its other end",
             'svg[data-pane="front"] [data-cables] [data-cable-id="c1"][data-loose-lead="from"]')
    # The configuration select still has the keyboard, and the page leaves
    # keys typed into a field alone: let go of it before Esc.
    page.evaluate("() => document.activeElement && document.activeElement.blur()")
    page.keyboard.press("Escape")
    wait_sel(page, "lifecycle: the list", "#cableList")
    line = page.text_content('#cableList li[data-cable-item="c1"] [data-loose="a"]') or ""
    if line != "Loose end A: port-1 holds no optic.":
        bad.append(f"lifecycle: the list says {line!r} of c1")

    # A REMOVE asks, in the side panel. Cancel changes nothing.
    select_item(page, "rear", "i3")
    page.click("#iRemove")
    try:
        wait_sel(page, "lifecycle: the remove panel", "#removePanel")
    except RuntimeError as e:
        return bad + [str(e)]
    said = page.text_content("#removePanel") or ""
    if "demarc has 1 cable." not in said:
        bad.append(f"lifecycle: the remove panel reads {said!r}")
    page.click("#removeCancel")
    wait_fn(page, "lifecycle: Cancel returns to the device", "() => !!document.getElementById('iLabel')")
    if len(doc()["items"]) != 4:
        bad.append("lifecycle: Cancel removed the device")
    # Keep: the device goes, its cable stays, loose, and stays listed.
    page.click("#iRemove")
    wait_sel(page, "lifecycle: the remove panel again", "#removeKeepCables")
    page.click("#removeKeepCables")
    wait_fn(page, "lifecycle: demarc (U14) removed", "() => window.__rack.doc().racks[0].items.length === 3")
    if [c["id"] for c in doc()["cables"]] != ["c1", "c2", "c3"]:
        bad.append(f"lifecycle: keeping the cables left {[c['id'] for c in doc()['cables']]}")
    wait_fn(page, "lifecycle: c2's far end is loose", reason_is("i3|front|port-2-1", "the device was removed"))
    wait_sel(page, "lifecycle: the list after the remove", '#cableList li[data-cable-item="c2"] [data-loose="b"]')
    row = page.text_content('#cableList [data-cable-row="c2"]') or ""
    line = page.text_content('#cableList li[data-cable-item="c2"] [data-loose="b"]') or ""
    if row != "leaf-1 (U15) mgmt-eth → a removed device's port-2-1" or line != "Loose end B: the device was removed.":
        bad.append(f"lifecycle: c2 is listed as {row!r} with {line!r}")
    wait_sel(page, "lifecycle: c2 hangs loose on the front",
             'svg[data-pane="front"] [data-cables] [data-cable-id="c2"][data-loose-lead="to"]')
    # Delete: the device and its cable both go.
    select_item(page, "rear", "i4")
    page.click("#iRemove")
    wait_sel(page, "lifecycle: the remove panel for the other demarc", "#removeWithCables")
    page.click("#removeWithCables")
    wait_fn(page, "lifecycle: demarc (U20) removed", "() => window.__rack.doc().racks[0].items.length === 2")
    if [c["id"] for c in doc()["cables"]] != ["c1", "c2"]:
        bad.append(f"lifecycle: deleting its cables left {[c['id'] for c in doc()['cables']]}")

    # A SHRINK that trims a device keeps its cables as loose ends, and Undo brings it all back.
    open_cabled(page, base)
    page.click("#frameBtn")
    page.fill("#fHeight", "3")
    page.dispatch_event("#fHeight", "change")
    wait_fn(page, "lifecycle: shrunk to 3U", "() => window.__rack.doc().racks[0].frame.heightRU === 3")
    if [i["id"] for i in doc()["items"]] != ["i2", "i3", "i4"] or len(doc()["cables"]) != 3:
        bad.append(f"lifecycle: after the shrink the rack holds {[i['id'] for i in doc()['items']]} and {len(doc()['cables'])} cables")
    wait_sel(page, "lifecycle: the shrink notice", ".rk-side .rk-notice")
    note = page.text_content(".rk-side .rk-notice") or ""
    if "core-1" not in note or "1 cable is kept as a loose end." not in note:
        bad.append(f"lifecycle: the shrink notice reads {note!r}")
    wait_fn(page, "lifecycle: c1's far end is loose after the shrink",
            reason_is("i1|front|slot-2/module/p0", "the device was removed"))
    page.click("#undoShrink")
    wait_fn(page, "lifecycle: Undo restores the device", "() => window.__rack.doc().racks[0].items.length === 4")
    wait_fn(page, "lifecycle: c1 lands again after Undo", reason_is("i1|front|slot-2/module/p0", None))

    # A FILE whose cable names a port the slot's part no longer has: the loader
    # keeps the cable, and the reason names the part.
    changed = json.loads(json.dumps(CABLE_FIXTURE))
    changed["id"] = "doc-cable-fixture-changed"
    changed["racks"][0]["name"] = "Cable test, card changed"
    changed["racks"][0]["items"][0]["swaps"] = {}
    try:
        open_cabled(page, base, changed)
    except RuntimeError as e:
        # The panes wait failed; say what the loader did first.
        got = [c["id"] for c in doc()["cables"]]
        return bad + [f"lifecycle: opening the changed file: {e}; the loader kept cables {got}, expected ['c1', 'c2', 'c3']"]
    if [c["id"] for c in doc()["cables"]] != ["c1", "c2", "c3"]:
        bad.append(f"lifecycle: the loader dropped or renamed a cable ({[c['id'] for c in doc()['cables']]})")
    try:
        wait_fn(page, "lifecycle: a port its card no longer has",
                reason_is("i1|front|slot-2/module/p0", "slot-2 holds A9K Slot Cover, which has no port p0"))
    except RuntimeError as e:
        bad.append(f"{e} (it says {page.evaluate(REASONS_JS).get('i1|front|slot-2/module/p0')!r})")
    return bad


@extra("rack.html: Undo after deleting a cable and after removing a cabled device, with its cables or without")
def check_rack_cable_undo(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("dialog", lambda d: (bad.append(f"undo: a browser dialog opened ({d.message!r})"), d.dismiss()))
    doc = lambda: page.evaluate("() => window.__rack.doc().racks[0]")
    note = lambda: page.text_content(".rk-side .rk-notice") or ""
    # The panel redraws after the document changes, so every read of it waits
    # for what it expects: the exact notice text, or the button's absence.
    def note_is(label, text):
        try:
            wait_fn(page, label, f"() => (document.querySelector('.rk-side .rk-notice')?.textContent || '') === {json.dumps(text)}")
        except RuntimeError:
            bad.append(f"undo: {label}: the notice reads {note()!r}, expected {text!r}")
    def undo_gone(label):
        try:
            wait_fn(page, label, "() => !document.getElementById('undoShrink')")
        except RuntimeError:
            bad.append(f"undo: {label}")
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"undo: {e}"]
    whole = doc()
    if page.query_selector("#undoShrink"):
        bad.append("undo: Undo is offered before anything changed")

    # Delete a cable from the list, then Undo: that exact cable is back, plug and all.
    page.click('#cableList [data-cable-row="c1"]')
    page.click("#cableDelete")
    wait_fn(page, "undo: c1 deleted", "() => window.__rack.doc().racks[0].cables.length === 2")
    note_is("the delete notice", "Deleted cable A1.")
    wait_sel(page, "undo: Undo after a delete", "#undoShrink")
    page.click("#undoShrink")
    wait_fn(page, "undo: c1 is back", "() => window.__rack.doc().racks[0].cables.length === 3")
    if doc() != whole:
        bad.append("undo: the rack after Undo is not the rack before the delete")
    wait_fn(page, "undo: c1's plug is back", "() => window.__rack.cableFacts().seats.i2['port-1-occupant/tx'] === 'generic/lc-plug@2'")
    undo_gone("Undo is still offered after it was used")

    # Remove a cabled device with its cables, then Undo.
    select_item(page, "rear", "i3")
    page.click("#iRemove")
    wait_sel(page, "undo: the remove panel", "#removeWithCables")
    page.click("#removeWithCables")
    wait_fn(page, "undo: demarc and its cable gone",
            "() => window.__rack.doc().racks[0].items.length === 3 && window.__rack.doc().racks[0].cables.length === 2")
    note_is("the remove notice", "Removed demarc and its 1 cable.")
    wait_sel(page, "undo: Undo after Remove and delete", "#undoShrink")
    page.click("#undoShrink")
    wait_fn(page, "undo: demarc is back", "() => window.__rack.doc().racks[0].items.length === 4")
    if doc() != whole:
        bad.append("undo: Undo after Remove and delete did not restore the rack")
    wait_fn(page, "undo: demarc's plug is back", "() => window.__rack.cableFacts().seats.i3['port-2-1'] === 'generic/rj45-plug@1'")

    # Remove it keeping the cables, then Undo.
    select_item(page, "rear", "i3")
    page.click("#iRemove")
    wait_sel(page, "undo: the remove panel again", "#removeKeepCables")
    page.click("#removeKeepCables")
    wait_fn(page, "undo: demarc removed", "() => window.__rack.doc().racks[0].items.length === 3")
    note_is("the keep notice", "Removed demarc. Its 1 cable is a loose end.")
    wait_sel(page, "undo: Undo after Remove and keep", "#undoShrink")
    page.click("#undoShrink")
    wait_fn(page, "undo: demarc is back again", "() => window.__rack.doc().racks[0].items.length === 4")
    if doc() != whole:
        bad.append("undo: Undo after Remove and keep did not restore the rack")

    # The remove panel acts on the rack as it is when the button is clicked,
    # not as it was when the panel was built: the click lands before the
    # redraw replaces the old buttons.
    stale = """(which) => {
      const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack(which === 'renamed' ? {...r, name: 'Renamed'}
        : {...r, name: 'Gone', items: r.items.filter(i => i.id !== 'i3'),
           cables: r.cables.filter(c => c.a.item !== 'i3' && c.b.item !== 'i3')});
      document.getElementById('removeKeepCables').click();
    }"""
    select_item(page, "rear", "i3")
    page.click("#iRemove")
    wait_sel(page, "undo: the remove panel for the stale click", "#removeKeepCables")
    page.evaluate(stale, "renamed")
    wait_fn(page, "undo: demarc removed over the changed rack", "() => window.__rack.doc().racks[0].items.length === 3")
    if doc()["name"] != "Renamed" or len(doc()["cables"]) != 3:
        bad.append(f"undo: a stale remove click wrote the old rack back (name {doc()['name']!r}, {len(doc()['cables'])} cables)")
    page.evaluate("w => window.__rack.replaceRack(w)", whole)
    wait_fn(page, "undo: the rack is whole again", "() => window.__rack.doc().racks[0].items.length === 4")
    select_item(page, "rear", "i3")
    page.click("#iRemove")
    wait_sel(page, "undo: the remove panel for the gone device", "#removeKeepCables")
    page.evaluate(stale, "gone")
    page.wait_for_timeout(500)
    if doc()["name"] != "Gone" or len(doc()["items"]) != 3 or len(doc()["cables"]) != 2:
        bad.append(f"undo: a remove click for a device already gone changed the rack ({doc()['name']!r}, "
                   f"{len(doc()['items'])} items, {len(doc()['cables'])} cables)")
    page.evaluate("w => window.__rack.replaceRack(w)", whole)
    wait_fn(page, "undo: the rack is whole once more", "() => window.__rack.doc().racks[0].items.length === 4")

    # Esc in the remove panel does what Cancel does: back to the device.
    select_item(page, "rear", "i3")
    page.click("#iRemove")
    wait_sel(page, "undo: the remove panel for Esc", "#removeWithCables")
    page.evaluate("() => document.activeElement?.blur()")
    page.keyboard.press("Escape")
    try:
        wait_sel(page, "undo: Esc in the remove panel returns to the device", "#iLabel")
    except RuntimeError as e:
        bad.append(str(e))
    if doc() != whole:
        bad.append("undo: Esc in the remove panel changed the rack")

    # An earlier notice from the same action is not lost to the Undo notice.
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.addNotice('Earlier.');
      window.__rack.replaceRack({...r, cables: r.cables.slice(1)}, {text: 'Later.'}); }""")
    note_is("an earlier notice is kept", "Earlier. Later.")
    page.evaluate("w => window.__rack.replaceRack(w)", whole)
    wait_fn(page, "undo: the rack is whole for the Undo test", "() => window.__rack.doc().racks[0].cables.length === 3")

    # Every edit is a step now: a later change does not retire Undo, it is what
    # Undo now describes. (Before every edit had an Undo, this checked that the
    # one pending Undo was retired by the next change.)
    page.evaluate("() => document.activeElement?.blur()")
    page.keyboard.press("Escape")               # the device is still selected: back to the list
    wait_sel(page, "undo: the cable list", '#cableList [data-cable-row="c2"]')
    page.click('#cableList [data-cable-row="c2"]')
    page.click("#cableDelete")
    wait_fn(page, "undo: c2 deleted", "() => window.__rack.doc().racks[0].cables.length === 2")
    wait_sel(page, "undo: Undo after the last delete", "#undoShrink")
    select_item(page, "front", "i2")
    page.keyboard.press("ArrowUp")
    wait_fn(page, "undo: leaf-1 moved", "() => window.__rack.doc().racks[0].items[1].ru === 15")
    try:
        wait_fn(page, "undo: Undo describes the later change",
                "() => (document.getElementById('undoWhat')?.textContent || '').startsWith('Moved leaf-1 ')")
    except RuntimeError:
        bad.append(f"undo: after a later change, Undo describes {page.text_content('#undoWhat') if page.query_selector('#undoWhat') else None!r}")
    return bad


@extra("rack.html: Undo and Redo walk back and forth through several edits, by button and by keyboard; a new edit clears Redo; DCIM settings survive Undo")
def check_rack_history(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    # New rack is async (it saves the old one first): wait for the new document, not just any empty rack.
    was = page.evaluate("() => window.__rack.doc().id")
    page.click("#libMenu > summary"); page.click("#libItems button:has-text('New rack')")
    wait_fn(page, "history: empty rack", f"() => window.__rack.doc().id !== {json.dumps(was)} && window.__rack.doc().racks[0].items.length === 0 && !window.__rack.history().canUndo")
    items = lambda: page.evaluate("() => window.__rack.doc().racks[0].items.map(i => [i.ref, i.ru, i.face])")
    pick(page, "front", 10, "R740", "r740xd")
    wait_fn(page, "history: placed", "() => window.__rack.doc().racks[0].items.length === 1")
    page.evaluate("() => window.__rack.apply({op: 'move', id: 'i1', ru: 20})")
    page.evaluate("() => window.__rack.apply({op: 'dcim', site: 'dc1'})")
    wait_sel(page, "history: Undo offered", "#undoShrink")
    what = page.text_content("#undoWhat") or ""
    if not what.startswith("Moved "):
        bad.append(f"history: Undo describes {what!r}, expected the move")
    page.click("#undoShrink")
    wait_fn(page, "history: the move undone", "() => window.__rack.doc().racks[0].items[0].ru === 10")
    if page.evaluate("() => window.__rack.doc().racks[0].dcim") != {"site": "dc1"}:
        bad.append("history: Undo took the DCIM settings back")
    wait_sel(page, "history: Redo offered", "#redoStep")
    page.keyboard.press("Meta+Shift+z" if sys.platform == "darwin" else "Control+Shift+z")
    wait_fn(page, "history: redone by keyboard", "() => window.__rack.doc().racks[0].items[0].ru === 20")
    page.keyboard.press("Meta+z" if sys.platform == "darwin" else "Control+z")
    page.keyboard.press("Meta+z" if sys.platform == "darwin" else "Control+z")
    wait_fn(page, "history: back to empty", "() => window.__rack.doc().racks[0].items.length === 0")
    try:
        wait_fn(page, "history: Undo gone with nothing left to undo", "() => !document.getElementById('undoShrink')")
    except RuntimeError:
        bad.append("history: Undo is still offered with nothing left to undo")
    page.evaluate("() => window.__rack.apply({op: 'rename', name: 'Fresh'})")
    wait_fn(page, "history: a new edit", "() => window.__rack.doc().racks[0].name === 'Fresh'")
    if page.evaluate("() => window.__rack.history().canRedo"):
        bad.append("history: a new edit left Redo offered")
    # A shrink, undone: every position comes back.
    page.evaluate("""() => window.__rack.apply([{op: 'place', ref: 'as7726-32x', face: 'front', ru: 40},
                                              {op: 'place', ref: 'as7726-32x', face: 'front', ru: 1}])""")
    before = items()
    page.evaluate("() => window.__rack.apply({op: 'frame', heightRU: 2})")
    wait_fn(page, "history: shrunk", "() => window.__rack.doc().racks[0].frame.heightRU === 2")
    wait_sel(page, "history: Undo after the shrink", "#undoShrink")
    page.click("#undoShrink")
    wait_fn(page, "history: unshrunk", "() => window.__rack.doc().racks[0].frame.heightRU === 42")
    if items() != before:
        bad.append(f"history: Undo after a shrink left {items()}, expected {before}")
    # A cable added between two placed devices is a step: Undo takes it back, Redo runs it again.
    ids = page.evaluate("() => window.__rack.doc().racks[0].items.map(i => i.id)")
    ends = []
    for i in ids[:2]:
        ports = page.evaluate(f"() => window.__rack.query.freePorts({json.dumps(i)})") or []
        if not ports:
            bad.append(f"history: freePorts({i!r}) found no port to cable")
            return bad
        ends.append({"item": i, "path": ports[0]["path"], "view": ports[0]["view"]})
    res = page.evaluate("([a, b]) => window.__rack.apply({op: 'cable.add', a, b})", ends)
    if res.get("error"):
        bad.append(f"history: cable.add refused: {res['error']}")
        return bad
    wait_fn(page, "history: cable added", "() => window.__rack.doc().racks[0].cables.length === 1")
    wait_fn(page, "history: Undo describes the cable",
            "() => (document.getElementById('undoWhat')?.textContent || '').startsWith('Added cable ')")
    page.click("#undoShrink")
    wait_fn(page, "history: the cable undone", "() => window.__rack.doc().racks[0].cables.length === 0")
    if len(items()) != len(ids):
        bad.append(f"history: undoing the cable changed the devices: {items()}")
    wait_sel(page, "history: Redo after undoing the cable", "#redoStep")
    page.click("#redoStep")
    wait_fn(page, "history: the cable redone", "() => window.__rack.doc().racks[0].cables.length === 1")
    # Two steps with one summary, the second undone: the notice reads "Undid: <summary>",
    # which holds the summary Undo now takes back, but Undo is described by that step,
    # not by the notice.
    page.evaluate("() => window.__rack.apply({op: 'place', ref: 'as7726-32x', face: 'front', ru: 30, label: 'twin'})")
    wait_fn(page, "history: twin placed", "() => window.__rack.doc().racks[0].items.some(i => i.label === 'twin')")
    tid = page.evaluate("() => window.__rack.doc().racks[0].items.find(i => i.label === 'twin').id")
    page.evaluate(f"() => window.__rack.apply({{op: 'patch', id: {json.dumps(tid)}, turned: true}})")
    page.evaluate(f"() => window.__rack.apply({{op: 'patch', id: {json.dumps(tid)}, turned: false}})")
    wait_fn(page, "history: two same-summary steps",
            f"() => window.__rack.doc().racks[0].items.find(i => i.id === {json.dumps(tid)}).turned === false")
    wait_sel(page, "history: Undo after two same-summary steps", "#undoShrink")
    page.click("#undoShrink")
    wait_fn(page, "history: the second step undone",
            f"() => window.__rack.doc().racks[0].items.find(i => i.id === {json.dumps(tid)}).turned === true")
    try:
        wait_fn(page, "history: Undo described by its step, not by the Undid notice",
                "() => document.getElementById('undoWhat')?.textContent === 'Changed twin.'")
    except RuntimeError:
        what = page.text_content("#undoWhat") if page.query_selector("#undoWhat") else None
        bad.append(f"history: after an Undo of a repeated step, Undo describes {what!r}, expected 'Changed twin.'")
    return bad


@extra("rack.html: __rack.apply refuses a bad batch whole, shows why, and the queries answer")
def check_rack_commands(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    # New rack is async (it saves the old one first): wait for the new document, not just any empty rack.
    was = page.evaluate("() => window.__rack.doc().id")
    page.click("#libMenu > summary"); page.click("#libItems button:has-text('New rack')")
    wait_fn(page, "commands: empty rack", f"() => window.__rack.doc().id !== {json.dumps(was)} && window.__rack.doc().racks[0].items.length === 0")
    res = page.evaluate("""() => window.__rack.apply([{op: 'place', ref: 'as7726-32x', face: 'front', ru: 10},
                                                    {op: 'place', ref: 'as7726-32x', face: 'front', ru: 10}])""")
    if res.get("index") != 1 or "Taken by" not in (res.get("error") or ""):
        bad.append(f"commands: the batch answered {res}")
    if page.evaluate("() => window.__rack.doc().racks[0].items.length") != 0:
        bad.append("commands: a refused batch left items in the rack")
    try:
        wait_fn(page, "commands: the refusal is shown",
                "() => (document.querySelector('.rk-side .rk-notice')?.textContent || '').includes('Taken by')")
    except RuntimeError:
        bad.append("commands: the page did not show why the batch was refused")
    page.evaluate("() => window.__rack.apply({op: 'place', ref: 'as7726-32x', face: 'front', ru: 10, as: 'leaf'})")
    text = page.evaluate("() => window.__rack.query.describe()")
    if "i1 AS7726-32X U10 front" not in text:
        bad.append(f"commands: describe() reads {text!r}")
    ports = page.evaluate("() => window.__rack.query.freePorts('i1')")
    if not isinstance(ports, list) or not ports or not all(p.get("path") and p.get("view") for p in ports):
        bad.append(f"commands: freePorts('i1') answered {str(ports)[:200]}")
    return bad


# A stand-in for the browser's WebMCP: records what the page registers, so the
# tools can be called as an agent would, with no relay and no flag.
STAND_IN_MODEL_CONTEXT = """
window.__tools = {};
const mc = {registerTool(t, o) {
  window.__tools[t.name] = t;
  o?.signal?.addEventListener('abort', () => delete window.__tools[t.name]);
  return Promise.resolve();
}};
Object.defineProperty(Document.prototype, 'modelContext', {get: () => mc, configurable: true});
"""
RELAY_FRAME = "iframe[data-webmcp-relay]"
AGENT_TOOLS = ["check_fit", "describe_rack", "edit_rack", "export_rack", "find_devices", "inspect", "list_free_ports", "new_rack", "redo", "undo"]


def agent_call(page, name, args):
    return page.evaluate("([n, a]) => window.__tools[n].execute(a)", [name, args])


@extra("rack.html: agent tools - registered on load, an agent's edit shown and undone, a dry run, an export, a busy export, a removed panel")
def check_rack_agent_tools(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    mcpb = []
    page.on("request", lambda r: mcpb.append(r.url) if "/vendor/mcp-b/" in r.url else None)
    page.add_init_script(STAND_IN_MODEL_CONTEXT)
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    was = page.evaluate("() => window.__rack.doc().id")
    page.click("#libMenu > summary"); page.click("#libItems button:has-text('New rack')")
    wait_fn(page, "agent: empty rack", f"() => window.__rack.doc().id !== {json.dumps(was)} && window.__rack.doc().racks[0].items.length === 0")
    wait_fn(page, "agent: tools registered", f"() => Object.keys(window.__tools).length === {len(AGENT_TOOLS)}")
    if sorted(page.evaluate("() => Object.keys(window.__tools)")) != AGENT_TOOLS:
        bad.append(f"agent: registered {page.evaluate('() => Object.keys(window.__tools)')}")
    items = lambda: page.evaluate("() => window.__rack.doc().racks[0].items.length")
    # An edit, as an agent sends it
    res = agent_call(page, "edit_rack", {"commands": [
        {"op": "place", "ref": "as7726-32x", "face": "front", "ru": 40, "as": "a"},
        {"op": "place", "ref": "as7726-32x", "face": "front", "ru": 38, "as": "b"}]})
    if res.get("isError") or "Placed" not in res["content"][0]["text"]:
        bad.append(f"agent: edit_rack answered {res}")
    try:
        wait_fn(page, "agent: the notice names the assistant",
                "() => (document.querySelector('.rk-side .rk-notice')?.textContent || '').includes('Your assistant: Placed')")
    except RuntimeError:
        bad.append("agent: no 'Your assistant:' notice after an agent edit")
    # The notice is Undo's description: no second line repeats the summary.
    if page.evaluate("() => document.querySelectorAll('.rk-side .rk-undo-what').length") != 0 or \
            "Your assistant:" not in (page.text_content("#undoWhat") or ""):
        bad.append("agent: the side panel repeats the summary in a separate undo line")
    try:
        wait_fn(page, "agent: highlighted", "() => document.querySelectorAll('svg .rk-agent-touched').length >= 2")
        wait_fn(page, "agent: highlight fades", "() => !document.querySelector('.rk-agent-touched')", timeout=8000)
    except RuntimeError as e:
        bad.append(f"agent: highlight - {e}")
    # Undo by the page's own button, then redo by the agent
    page.click("#undoShrink")
    wait_fn(page, "agent: undone by button", "() => window.__rack.doc().racks[0].items.length === 0")
    if agent_call(page, "redo", {})["content"][0]["text"].split(":")[0] != "Redid":
        bad.append("agent: redo did not say Redid")
    wait_fn(page, "agent: redone", "() => window.__rack.doc().racks[0].items.length === 2")
    # A dry run changes nothing
    dry = agent_call(page, "edit_rack", {"commands": [{"op": "remove", "id": "i1", "cables": "keep"}], "dry_run": True})
    if "Would:" not in dry["content"][0]["text"] or items() != 2:
        bad.append(f"agent: dry run answered {dry} with {items()} items")
    # The page's own command is refused
    if not agent_call(page, "edit_rack", {"commands": [{"op": "lengths.routed"}]}).get("isError"):
        bad.append("agent: lengths.routed was accepted")
    # describe_rack sees the edit
    if "i1" not in agent_call(page, "describe_rack", {})["content"][0]["text"]:
        bad.append("agent: describe_rack does not list i1")
    # An export arrives as a download, named as the tool said
    page.evaluate("() => window.__rack.apply({op: 'dcim', site: 'dc1', role: 'leaf'})")
    with page.expect_download(timeout=READY_MS) as dl:
        out = agent_call(page, "export_rack", {"kind": "netbox import"})
    said = out["content"][0]["text"]
    if out.get("isError") or dl.value.suggested_filename not in said:
        bad.append(f"agent: export said {said!r}, downloaded {dl.value.suggested_filename!r}")
    # Two exports at once: the second is told to wait, not left hanging
    both = page.evaluate("""async () => {
        const t = window.__tools.export_rack;
        const [a, b] = await Promise.all([t.execute({kind: 'netbox import'}), t.execute({kind: 'bill of materials'})]);
        return [a, b]; }""")
    if not any(r.get("isError") and "still running" in r["content"][0]["text"] for r in both):
        bad.append(f"agent: two exports at once answered {both}")
    # The user has i1's panel open when the agent removes it
    page.click('svg [data-item-id="i1"]')
    wait_fn(page, "agent: i1's panel open", "() => (document.querySelector('.rk-side')?.textContent || '').includes('AS7726-32X')")
    agent_call(page, "edit_rack", {"commands": [{"op": "remove", "id": "i1", "cables": "remove"}]})
    wait_fn(page, "agent: i1 gone", "() => window.__rack.doc().racks[0].items.length === 1")
    page.wait_for_timeout(300)
    if page.evaluate("() => !!document.querySelector('.rk-side [data-item-id=\"i1\"], .rk-side #iRemove')"):
        bad.append("agent: the side panel still shows the removed device")
    if mcpb:
        bad.append(f"agent: MCP-B loaded with the switch off: {mcpb[:2]}")
    return bad


def relay_connect_asserts(page):
    """The embed never scans on its own; Connect asks the relay frame to (no real relay in CI)."""
    bad = []
    if page.evaluate("() => document.querySelector('script[src*=\"vendor/mcp-b/embed.js\"]')?.getAttribute('data-auto-connect')") != "false":
        bad.append("relay: the embed script does not carry data-auto-connect=false")
    btn = "#agentSlot button:text-is('Connect')"
    if not page.is_visible(btn):
        bad.append("relay: no Connect button while the switch is on")
    status = lambda: page.text_content("#agentSlot [role=status]") or ""
    try:
        wait_fn(page, "relay: on", "() => document.querySelector('#agentSlot [role=status]').textContent.startsWith('On.')")
    except RuntimeError:
        pass
    if status() != "On. Start the relay on your computer first, then press Connect.":
        bad.append(f"relay: the status after switch-on is {status()!r}")
    # Record what the frame is sent.
    page.evaluate(f"""() => {{
      const w = document.querySelector({json.dumps(RELAY_FRAME)}).contentWindow;
      w.__got = []; w.addEventListener('message', e => w.__got.push(e.data));
    }}""")
    page.click(btn)
    try:
        wait_fn(page, "relay: connect posted", f"() => (document.querySelector({json.dumps(RELAY_FRAME)}).contentWindow.__got || []).some(m => m && m.type === 'webmcp.connect')")
    except RuntimeError:
        bad.append("relay: Connect did not post webmcp.connect to the relay frame")
    # What the widget says, posted from the frame's own window.
    from_frame = lambda msg: page.evaluate(f"""() => {{
      const w = document.querySelector({json.dumps(RELAY_FRAME)}).contentWindow;
      new w.Function("parent.postMessage(" + {json.dumps(json.dumps(msg))} + ", '*')")();
    }}""")
    from_frame({"type": "webmcp.tools.list.request", "requestId": "x"})
    try:
        wait_fn(page, "relay: found", "() => document.querySelector('#agentSlot [role=status]').textContent === 'Found your relay.'")
    except RuntimeError:
        bad.append(f"relay: a tools list request did not say 'Found your relay.' (status {status()!r})")
    from_frame({"type": "webmcp.relay.rejected"})
    try:
        wait_fn(page, "relay: rejected", "() => document.querySelector('#agentSlot [role=status]').textContent === `Your relay refused this page. Start it with --widget-origin ${location.origin}.`")
    except RuntimeError:
        bad.append(f"relay: a rejection did not overwrite the status (status {status()!r})")
    return bad


# The stand-in again, with what an agent in the page calls: getTools() and
# executeTool(tool, args) - the tool object first, as Chromium's WebMCP takes it.
# Kept apart from STAND_IN_MODEL_CONTEXT: a model context with executeTool reads
# as the MCP-B polyfill to the relay switch (site/agent/relay.js).
STAND_IN_WITH_EXECUTE = STAND_IN_MODEL_CONTEXT + """
mc.getTools = async () => Object.values(window.__tools);
// As the MCP-B polyfill (vendor/mcp-b/global.js 5.1.0) and Chromium's testing
// call do: the arguments come as a JSON string, an object is refused, and the
// answer goes back as a JSON string. A caller that passes an object fails here
// as it fails in the real page.
mc.executeTool = async (t, input) => {
  let a;
  try { a = JSON.parse(input); } catch { a = null; }
  if (typeof input !== 'string' || !a || typeof a !== 'object')
    throw new DOMException('Failed to parse input arguments', 'UnknownError');
  return JSON.stringify(await t.execute(a));
};
"""


def agent_exec(page, name, args):
    """A tool called as the page hint says: found in getTools(), run with
    executeTool(tool, JSON.stringify(args)), its JSON string answer parsed."""
    return page.evaluate("""async ([n, a]) => {
      const mc = document.modelContext ?? navigator.modelContext;
      const t = (await mc.getTools()).find(t => t.name === n);
      return JSON.parse(await mc.executeTool(t, JSON.stringify(a)));
    }""", [name, args])


# THE PAGE HINT'S SNIPPET, RUN AS WRITTEN: #webmcp-hint's howTo, its last
# expression returned. Answers [text, error].
RUN_HOW_TO = """async () => {
  const howTo = JSON.parse(document.getElementById('webmcp-hint').textContent).howTo;
  const cut = howTo.lastIndexOf('; ');
  const body = `${howTo.slice(0, cut + 2)}return ${howTo.slice(cut + 2)};`;
  try { return [await new (Object.getPrototypeOf(async () => {}).constructor)(body)(), null]; }
  catch (e) { return [null, String(e)]; }
}"""


def inspect_all(page, args):
    """Every page of an inspect answer, as an agent reads it: each page's first
    line names the next one ({...}) until "That is the end."."""
    out = []
    for _ in range(30):
        text = agent_exec(page, "inspect", args)["content"][0]["text"]
        out.append(text)
        m = re.search(r"Next: (\{.*?\})\.$", text.split("\n")[0])
        if not m:
            break
        args = json.loads(m.group(1))
    return "\n".join(out)


@extra("rack.html: a latch colour set in the Explorer lens reaches 2D, 3D, the saved rack and a reload (#206)")
def check_rack_lens_latch_colour(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    open_new_rack(page, "latch206")
    out = page.evaluate("""() => window.__rack.apply([{op: 'place', ref: 'as7726-32x', face: 'front', ru: 20, as: 'sw'},
      {op: 'fit', id: '@sw', path: 'port-1', ref: 'generic/qsfp-lc@2'}]).error ?? null""")
    if out:
        return [f"latch206: fitting an optic answered {out}"]
    latch2d = "() => [...document.querySelectorAll('#panes svg [data-fill-from=\"latch-color\"]')].map(n => n.getAttribute('fill'))"
    page.wait_for_selector('svg[data-pane="front"] [data-device-ref="as7726-32x"] [data-ref^="generic/qsfp-lc@2"]', timeout=READY_MS)
    page.click('svg[data-pane="front"] [data-device-ref="as7726-32x"]')
    page.click("#iExplore")
    page.wait_for_selector(".rk-lens iframe", timeout=READY_MS)
    page.wait_for_function("() => !!document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed", timeout=READY_MS)
    page.evaluate("async () => { await document.querySelector('.rk-lens iframe').contentWindow.portrayalEmbed.ready; }")
    lens = page.frame_locator(".rk-lens iframe")
    lens.locator('.nm:text-matches("^port-1 —")').click()
    pick_colour = lens.locator(".optic-fields input[type=color]")
    pick_colour.wait_for(timeout=READY_MS)
    pick_colour.evaluate("i => { i.value = '#c22f2f'; i.dispatchEvent(new Event('input', {bubbles: true})); }")
    page.wait_for_function("() => document.querySelector('.rk-lens iframe')?.contentWindow?.portrayalEmbed?.settled === true", timeout=READY_MS)
    page.click(".rk-lens-done")
    try:
        wait_fn(page, "latch206: the rack holds the colour",
                "() => window.__rack.doc().racks[0].items[0].fields?.['port-1-occupant']?.['latch-color'] === '#c22f2f'")
        wait_fn(page, "latch206: 2D shows it",
                f"() => {{ const f = ({latch2d})(); return f.length > 0 && f.every(x => x === '#c22f2f'); }}")
    except RuntimeError as e:
        bad.append(str(e))
    if webgl_trouble(page):
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "latch206: the scene")
    face = page.evaluate("""async () => { const s = window.__rack.scene(); const t = await s.faceText(0, 'front');
      const d = new DOMParser().parseFromString(t, 'image/svg+xml');
      return [...d.querySelectorAll('[data-fill-from="latch-color"]')].map(n => n.getAttribute('fill')); }""")
    if not face or any(f != "#c22f2f" for f in face):
        bad.append(f"latch206: the 3D face still draws the latch {sorted(set(face or []))}")
    # saved with the rack: a reload brings the colour back, in 2D and in 3D
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    kept = page.evaluate("() => window.__rack.doc().racks[0].items[0]?.fields ?? null")
    if (kept or {}).get("port-1-occupant", {}).get("latch-color") != "#c22f2f":
        bad.append(f"latch206: after a reload the rack holds {kept}")
    return bad


