@extra("rack.html: agent tools 2 - the page hint, new_rack, an optic fitted and its latch painted, a cassette swapped and its cable re-pointed, cables removed by selector")
def check_rack_agent_tools_2(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    said = lambda r: r["content"][0]["text"]
    doc = lambda expr: page.evaluate(f"() => {{ const r = window.__rack.doc().racks[0]; return {expr}; }}")
    page.add_init_script(STAND_IN_WITH_EXECUTE)
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    wait_fn(page, "agent2: tools registered", f"() => Object.keys(window.__tools).length === {len(AGENT_TOOLS)}")
    # The page hint lists exactly what was registered
    hint = page.evaluate("() => JSON.parse(document.getElementById('webmcp-hint').textContent)")
    if not hint.get("webmcp") or sorted(hint.get("tools", [])) != AGENT_TOOLS:
        bad.append(f"agent2: the page hint says {hint}")
    hint_p = page.text_content("#webmcp-hint-text") or ""
    if "executeTool" not in hint_p or f"The tools are: {', '.join(page.evaluate('() => Object.keys(window.__tools)'))}." not in hint_p \
            or not hint.get("registered"):
        bad.append(f"agent2: the hint paragraph does not name the registered tools and how to call them: {hint_p!r}, {hint}")
    text, err = page.evaluate(RUN_HOW_TO)
    if err or not re.match(r".+ \(r\d+\): \d+ items?, \d+ cables?\.", text or ""):
        bad.append(f"agent2: the hint's own snippet answered {text!r}, {err}")
    obj = page.evaluate("""async () => { const mc = document.modelContext;
      const t = (await mc.getTools()).find(t => t.name === 'describe_rack');
      try { await mc.executeTool(t, {}); return 'took an object'; } catch (e) { return String(e); } }""")
    if "Failed to parse input arguments" not in obj:
        bad.append(f"agent2: the stand-in took an object argument: {obj}")
    first = page.evaluate("() => [document.body.firstElementChild?.id, document.body.getAttribute('aria-describedby')]")
    if first != ["webmcp-hint-text", "webmcp-hint-text"]:
        bad.append(f"agent2: the hint is not the body's first element and its description: {first}")
    # new_rack: the old rack stays in the library, the new one is open
    old = page.evaluate("() => ({id: window.__rack.doc().id, name: window.__rack.doc().racks[0].name})")
    out = agent_exec(page, "new_rack", {"name": "Agent rack", "height": 24})
    if out.get("isError") or "Opened Agent rack" not in said(out) or "is in the library" not in said(out):
        bad.append(f"agent2: new_rack answered {out}")
    now = page.evaluate("() => { const d = window.__rack.doc(); const r = d.racks[0]; return [d.id, r.name, r.frame.heightRU, r.items.length]; }")
    if now[0] == old["id"] or now[1:] != ["Agent rack", 24, 0]:
        bad.append(f"agent2: after new_rack the open rack is {now}")
    page.click("#libMenu > summary")
    try:
        wait_fn(page, "agent2: the old rack is in the library",
                f"() => [...document.querySelectorAll('#libItems button')].some(b => b.textContent === {json.dumps(old['name'])})")
    except RuntimeError as e:
        bad.append(str(e))
    page.click("#libMenu > summary")
    # An optic fitted, then its latch color set: the drawing shows the color
    fitted = agent_exec(page, "edit_rack", {"commands": [
        {"op": "place", "ref": "as7726-32x", "face": "front", "ru": 20, "as": "sw"},
        {"op": "fit", "id": "@sw", "path": "port-1", "ref": "generic/qsfp-lc@2"}]})
    if fitted.get("isError"):
        bad.append(f"agent2: fitting an optic answered {fitted}")
        return bad
    # A part the cage does not take is refused, with what it takes, and nothing changes
    wrong = agent_exec(page, "edit_rack", {"commands": [{"op": "fit", "id": "i1", "path": "port-2", "ref": "fs/fhd-fap6scd-os2@1"}]})
    if not wrong.get("isError") or "does not take fs/fhd-fap6scd-os2@1" not in said(wrong) \
            or doc("r.items[0].swaps['port-2'] ?? null") is not None:
        bad.append(f"agent2: a wrong part in a cage answered {wrong}")
    look = inspect_all(page, {"id": "i1"})
    if "holds generic/qsfp-lc@2" not in look:
        bad.append(f"agent2: inspect does not show the optic: {look[:300]!r}")
    latch = next((l.split(":")[0] for l in look.splitlines() if "latch-color =" in l), None)
    if not latch or ".." in latch:
        bad.append(f"agent2: inspect names no single latch-color field for port-1: {look[:300]!r}")
        return bad
    colored = agent_exec(page, "edit_rack", {"commands": [
        {"op": "field", "id": "i1", "path": latch, "key": "latch-color", "value": "#c22f2f"}]})
    if colored.get("isError"):
        bad.append(f"agent2: setting the latch color answered {colored}")
    try:
        wait_fn(page, "agent2: the latch is painted",
                "() => [...document.querySelectorAll('#panes svg [data-fill-from=\"latch-color\"]')].some(n => n.getAttribute('fill') === '#c22f2f')")
    except RuntimeError as e:
        bad.append(str(e))
    # A cassette swapped: the orphaned cable is said, then re-pointed with cable.update {b}
    agent_exec(page, "edit_rack", {"commands": [{"op": "place", "ref": "fhd-1ufce", "cfg": "panels", "face": "front", "ru": 18}]})
    end = lambda item, p: {"item": item, "path": p["path"], "view": p["view"]}
    sw = page.evaluate("() => window.__rack.query.freePorts('i1')")
    bay = [p for p in page.evaluate("() => window.__rack.query.freePorts('i2')") if p["path"].startswith("bay-1/")]
    if len(sw) < 2 or len(bay) < 7:
        bad.append(f"agent2: not enough free ports to cable (switch {len(sw)}, bay-1 {len(bay)})")
        return bad
    agent_exec(page, "edit_rack", {"commands": [{"op": "cable.add", "a": end("i1", sw[0]), "b": end("i2", bay[-1])}]})
    swap = agent_exec(page, "edit_rack", {"commands": [{"op": "fit", "id": "i2", "path": "bay-1", "ref": "fs/fhd-fap6scd-os2@1"}]})
    if swap.get("isError") or not ("c1" in said(swap) or bay[-1]["path"] in said(swap)):
        bad.append(f"agent2: the cassette swap did not say what it orphaned: {said(swap)!r}")
    fresh = [p for p in page.evaluate("() => window.__rack.query.freePorts('i2')") if p["path"].startswith("bay-1/")]
    if not fresh:
        bad.append("agent2: the new cassette has no free ports")
        return bad
    repointed = agent_exec(page, "edit_rack", {"commands": [{"op": "cable.update", "id": "c1", "b": end("i2", fresh[0])}]})
    if repointed.get("isError") or doc("r.cables.find(c => c.id === 'c1')?.b.path") != fresh[0]["path"]:
        bad.append(f"agent2: re-pointing c1 answered {repointed}")
    # A hand route through a waypoint the rack lacks is refused, with what exists
    route_before = doc("JSON.stringify(r.cables.find(c => c.id === 'c1')?.route ?? null)")
    for way, want in [({"item": "i1", "via": "guide-9"}, "has no"), ({"lane": "middle", "ru": 20}, "no gutter called middle")]:
        routed = agent_exec(page, "edit_rack", {"commands": [{"op": "cable.route", "id": "c1", "route": [way]}]})
        if not routed.get("isError") or want not in said(routed):
            bad.append(f"agent2: a route through {way} answered {routed}")
    if doc("JSON.stringify(r.cables.find(c => c.id === 'c1')?.route ?? null)") != route_before \
            or doc("r.cables.find(c => c.id === 'c1')?.routeEdited === true"):
        bad.append("agent2: a refused route still changed c1")
    # The cables on a device, removed by selector
    agent_exec(page, "edit_rack", {"commands": [{"op": "cable.add", "a": end("i1", sw[1]), "b": end("i2", fresh[1])}]})
    removed = agent_exec(page, "edit_rack", {"commands": [{"op": "cable.remove", "select": {"item": "i1"}}]})
    if removed.get("isError") or not said(removed).startswith("Removed: c1, c2.") or doc("r.cables.length") != 0:
        bad.append(f"agent2: removing by selector answered {removed}, {doc('r.cables.length')} cables left")
    return bad


@extra("rack.html: Connect your AI - nothing loads until it is on, it remembers, it turns off, and it fits at 375px")
def check_rack_agent_relay(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    mcpb = []
    page.on("request", lambda r: mcpb.append(r.url) if "/vendor/mcp-b/" in r.url else None)
    page.set_viewport_size({"width": 375, "height": 800})
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.evaluate("() => { try { localStorage.removeItem('portrayal.agent.relay'); } catch {} }")
    if mcpb:
        bad.append(f"relay: loaded before it was switched on: {mcpb[:2]}")
    box = page.locator("#agentMenu > summary").bounding_box()
    if not box or box["x"] + box["width"] > 375:
        bad.append(f"relay: the Connect your AI button is off screen at 375px: {box}")
    page.click("#agentMenu > summary")
    panel = page.text_content("#agentSlot") or ""
    origin = page.evaluate("() => location.origin")
    for want in [f"--widget-origin {origin}", "Your AI runs on your computer and talks to this page directly.",
                 "Export this rack for NetBox."]:
        if want not in panel:
            bad.append(f"relay: the panel does not say {want!r}")
    hint = page.evaluate("() => JSON.parse(document.getElementById('webmcp-hint').textContent)")
    if hint.get("registered") or hint.get("tools") or "Connect your AI" not in (page.text_content("#webmcp-hint-text") or ""):
        bad.append(f"relay: with nothing registered the page hint says {hint}")
    page.check("#agentRelay")
    try:
        wait_fn(page, "relay: the hint names the tools once the switch registers them",
                f"() => JSON.parse(document.getElementById('webmcp-hint').textContent).tools.length === {len(AGENT_TOOLS)}")
    except RuntimeError as e:
        bad.append(str(e))
    else:
        # The hint's snippet, as written, against the REAL vendored polyfill
        # (vendor/mcp-b/global.js) that the switch loaded: a parseable answer.
        text, err = page.evaluate(RUN_HOW_TO)
        if err or not re.match(r".+ \(r\d+\): \d+ items?, \d+ cables?\.", text or ""):
            bad.append(f"relay: the page hint's snippet, run against the polyfill, answered {text!r}, {err}")
        # and the call the hint used to give, an object argument, is the one the polyfill refuses
        obj = page.evaluate("""async () => { const mc = document.modelContext;
          const t = (await mc.getTools()).find(t => t.name === 'describe_rack');
          try { await mc.executeTool(t, {}); return 'took an object'; } catch (e) { return String(e); } }""")
        if "Failed to parse input arguments" not in obj:
            bad.append(f"relay: the polyfill's executeTool took an object, so the hint's JSON-string advice needs another look: {obj}")
    try:
        wait_fn(page, "relay: embed loaded", "() => !!document.querySelector('script[src*=\"vendor/mcp-b/\"]')")
    except RuntimeError:
        bad.append("relay: switching on loaded nothing from vendor/mcp-b/")
    try:
        wait_fn(page, "relay: frame built", f"() => !!document.querySelector({json.dumps(RELAY_FRAME)})")
    except RuntimeError:
        bad.append("relay: switching on never built the relay frame")
    else:
        bad += relay_connect_asserts(page)
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    try:
        wait_fn(page, "relay: remembered after reload", "() => !!document.querySelector('script[src*=\"vendor/mcp-b/\"]')")
    except RuntimeError:
        bad.append("relay: the switch was not remembered")
    try:
        wait_fn(page, "relay: frame built after reload", f"() => !!document.querySelector({json.dumps(RELAY_FRAME)})")
    except RuntimeError:
        bad.append("relay: the remembered switch never built the relay frame")
    page.click("#agentMenu > summary")
    page.uncheck("#agentRelay")
    try:
        wait_fn(page, "relay: the relay frame removed", f"() => !document.querySelector({json.dumps(RELAY_FRAME)})")
    except RuntimeError:
        bad.append("relay: switching off left the relay frame in the page")
    if page.is_visible("#agentSlot button:text-is('Connect')"):
        bad.append("relay: the Connect button shows while the switch is off")
    if page.evaluate("() => { try { return localStorage.getItem('portrayal.agent.relay'); } catch { return null; } }") != "off":
        bad.append("relay: switching off was not remembered")
    # On, then straight off: nothing may come up behind the switch.
    page.check("#agentRelay")
    page.uncheck("#agentRelay")
    page.wait_for_timeout(1500)
    if page.evaluate(f"() => !!document.querySelector({json.dumps(RELAY_FRAME)})"):
        bad.append("relay: a quick on-then-off left the relay frame in the page")
    if (page.text_content("#agentSlot [role=status]") or "").startswith("On."):
        bad.append("relay: a quick on-then-off says On.")
    return bad


@extra("rack.html: when the cables' faces cannot be read, the rack still draws, no end is marked loose, and the panel says so; the answers are frozen")
def check_rack_cable_facts_fallback(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cable facts: {e}"]
    notice = lambda: (page.text_content(".rk-side .rk-notice") or "") if page.query_selector(".rk-side .rk-notice") else ""
    redraw = lambda: page.evaluate("() => window.__rack.replaceRack(window.__rack.doc().racks[0])")
    loose = lambda: page.eval_on_selector_all(
        '[data-loose], svg[data-pane] [data-cable-tags] .not-connected', "els => els.length")

    # The normal answer: c3's A end is an empty cage, and says so.
    wait_fn(page, "cable facts: a loose end is read",
            "() => Object.values(window.__rack.cableFacts().reasons).some(r => r)")
    if not loose() or notice():
        bad.append(f"cable facts: normally {loose()} loose marks and the notice {notice()!r}")

    # Reading fails: the cables stay drawn as they were, none is marked loose,
    # and the panel says why. A redraw that fails again keeps saying it.
    page.evaluate("() => window.__rack.failCableFacts(true)")
    redraw()
    wait_fn(page, "cable facts: the notice",
            "() => (document.querySelector('.rk-side .rk-notice')?.textContent || '').includes('could not be checked')")
    if notice() != "Cable ends could not be checked, so loose ends are not marked.":
        bad.append(f"cable facts: the notice reads {notice()!r}")
    if loose():
        bad.append(f"cable facts: {loose()} ends are still marked loose though none was checked")
    facts = page.evaluate("() => window.__rack.cableFacts()")
    if facts["seats"] or any(facts["reasons"].values()):
        bad.append(f"cable facts: the fallback carries seats or reasons ({facts})")
    if not page.query_selector('svg[data-pane="front"] [data-cables] [data-cable-id="c1"]'):
        bad.append("cable facts: the cables are not drawn when their faces cannot be read")

    # It recovers by itself on the next redraw.
    page.evaluate("() => window.__rack.failCableFacts(false)")
    redraw()
    wait_fn(page, "cable facts: the notice goes", "() => !document.querySelector('.rk-side .rk-notice')")
    wait_fn(page, "cable facts: loose ends are marked again",
            "() => !!document.querySelector('[data-loose]')")

    # Every answer is frozen: shared by the memo, the page and the probe.
    frozen = page.evaluate("""async () => {
      const {cableFacts, UNCHECKED} = await import('/site/rack/cable-plugs.js');
      const none = await cableFacts({items: [], cables: []});
      const real = await cableFacts(window.__rack.doc().racks[0]);
      return [none, UNCHECKED, real].map(f => [Object.isFrozen(f), Object.isFrozen(f.seats)]);
    }""")
    if frozen != [[True, True]] * 3:
        bad.append(f"cable facts: frozen (answer, seats) for no cables, the fallback, a real answer: {frozen}")
    return bad


CABLES_3D = "Cables are added in 2D. Switch to 2D to add one."


@extra("rack.html: in 3D the cables are drawn and Cable mode is off with a sentence saying where cables are added; the list still selects, edits and deletes; an edit to a cable's ends or media rebuilds the scene, an edit to its label does not")
def check_rack_cables_3d(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cables 3D: {e}"]
    cables = lambda: page.evaluate("() => window.__rack.doc().racks[0].cables")

    # The sheet carries the cables now (check_rack_export_sheet_cables): what
    # stays out of it is the screen's - a picked end's outline - and the old note.
    sheet = pathlib.Path(export_file(page, "sheet-svg").path()).read_text(encoding="utf-8")
    for bit in ("rk-end-pick", "not in this export yet"):
        if bit in sheet:
            bad.append(f"cables 3D: the sheet carries {bit!r}")
    # The BOM carries the cables now (check_rack_export_bom_cables), so it does not say they are left out.
    bom = pathlib.Path(export_file(page, "bom").path()).read_text(encoding="utf-8")
    if "not in this export yet" in bom:
        bad.append("cables 3D: the BOM still says cables are not in it")

    no_webgl = webgl_trouble(page)
    page.click("#cableBtn")
    wait_fn(page, "cables 3D: Cable mode on in 2D",
            "() => document.getElementById('cableBtn').getAttribute('aria-pressed') === 'true'")
    page.click('#mode [data-mode="3d"]')
    btn = page.eval_on_selector("#cableBtn", "b => ({disabled: b.disabled, pressed: b.getAttribute('aria-pressed'), title: b.title})")
    if btn != {"disabled": True, "pressed": "false", "title": CABLES_3D}:
        bad.append(f"cables 3D: in 3D the Cable button is {btn}")
    try:
        wait_sel(page, "cables 3D: the sentence", "#cable3dNote")
    except RuntimeError as e:
        return bad + [str(e)]
    if (page.text_content("#cable3dNote") or "") != CABLES_3D:
        bad.append(f"cables 3D: the note reads {page.text_content('#cable3dNote')!r}")

    # The list still works: select, edit, delete.
    pressed = lambda cid: (f"""() => document.querySelector('#cableList [data-cable-row="{cid}"]')"""
                           f"""?.getAttribute('aria-pressed') === 'true'""")
    groups = lambda: page.evaluate(
        "() => (window.__rack.scene().three.scene.getObjectByName('patch-cables')?.children || []).map(g => g.name)")

    def rebuilt(label, old):
        # A new scene object, built: the old one was disposed by the rebuild.
        try:
            page.wait_for_function("s => { const n = window.__rack.scene(); return !!n && n !== s; }",
                                   arg=old, timeout=READY_3D_MS)
        except Exception as e:
            raise RuntimeError(f"{label}: {str(e).splitlines()[0]}") from e
        settle_scene(page, label)
        old.dispose()
        return page.evaluate_handle("() => window.__rack.scene()")

    scene = None
    if not no_webgl:
        wait_fn(page, "cables 3D: the scene", "() => !!window.__rack.scene()", timeout=READY_3D_MS)
        settle_scene(page, "cables 3D: the scene")
        scene = page.evaluate_handle("() => window.__rack.scene()")
        if groups() != ["cable-c1", "cable-c2", "cable-c3"]:
            bad.append(f"cables 3D: the scene's cables are {groups()}")
    page.click('#cableList [data-cable-row="c1"]')
    wait_fn(page, "cables 3D: a row selects", pressed("c1"))
    page.click("#cableEdit")
    wait_sel(page, "cables 3D: the edit form", "#cableForm")
    page.fill("#cLabel", "B9")
    page.click("#cSave")
    wait_fn(page, "cables 3D: the edit saved", "() => window.__rack.doc().racks[0].cables[0].label === 'B9'")
    try:
        if scene:
            # A label is nothing the scene draws: the scene is kept, and is still good for an export.
            page.wait_for_timeout(800)          # past the 300 ms a rebuild would wait
            if not page.evaluate("s => window.__rack.scene() === s", scene):
                bad.append("cables 3D: editing a cable's label rebuilt the 3D scene")
            glb = export_file(page, "glb", timeout=READY_3D_MS)
            if not export_status(page).startswith("Downloaded") or pathlib.Path(glb.path()).stat().st_size < 100:
                bad.append("cables 3D: no GLB after a label edit")
            if not page.evaluate("s => window.__rack.scene() === s", scene):
                bad.append("cables 3D: exporting after a label edit rebuilt the 3D scene")

            # A cable's media is its color: the scene is rebuilt.
            colors = page.evaluate("async () => (await import('/site/rack/cables.js')).COLORS")
            page.click('#cableList [data-cable-row="c2"]')
            wait_fn(page, "cables 3D: row c2 selects", pressed("c2"))
            page.click("#cableEdit")
            wait_sel(page, "cables 3D: c2's edit form", "#cableForm")
            page.select_option("#cMedia", "dac")
            page.click("#cSave")
            scene = rebuilt("cables 3D: the rebuild after a media change", scene)
            got = {t["id"]: t["color"] for t in page.evaluate(CABLES_3D_JS)["tubes"]}
            if got.get("c2") != colors["dac"]:
                bad.append(f"cables 3D: after its media changed to DAC, c2 is {got.get('c2')}, expected {colors['dac']}")

        page.click('#cableList [data-cable-row="c3"]')
        wait_fn(page, "cables 3D: row c3 selects", pressed("c3"))
        page.click("#cableDelete")
        wait_fn(page, "cables 3D: the delete", "() => window.__rack.doc().racks[0].cables.length === 2")
        if scene:
            # A cable fewer is a tube fewer: the scene is rebuilt, and the GLB follows it.
            scene = rebuilt("cables 3D: the rebuild after a delete", scene)
            if groups() != ["cable-c1", "cable-c2"]:
                bad.append(f"cables 3D: after deleting c3 the scene's cables are {groups()}")
            glb = pathlib.Path(export_file(page, "glb", timeout=READY_3D_MS).path()).read_bytes()
            if b'"cable-c1"' not in glb or b'"cable-c3"' in glb:
                bad.append("cables 3D: the GLB exported after a cable delete does not match the rack")
            scene.dispose()
        else:
            print("[check_rack_cables_3d] WebGL unavailable - the rebuild steps were not exercised")
    except RuntimeError as e:
        return bad + [str(e)]

    # Back in 2D: the button works again and what is left is drawn.
    page.click('#mode [data-mode="2d"]')
    wait_sel(page, "cables 3D: cables back in 2D", 'svg[data-pane="front"] [data-cables] [data-cable-id="c1"]')
    if page.query_selector("#cable3dNote") or page.eval_on_selector("#cableBtn", "b => b.disabled || !!b.title"):
        bad.append("cables 3D: back in 2D the note is still shown or the button is still off")
    if page.query_selector('svg[data-pane="rear"] [data-cable-id="c3"]') or len(cables()) != 2:
        bad.append("cables 3D: the cable deleted in 3D is still drawn in 2D")

    # With no cable left, the empty state tells the truth of the mode it is in:
    # in 3D there is no Cable mode to use, so it says only that there are none.
    page.click('#mode [data-mode="3d"]')
    for cid in [c["id"] for c in cables()]:
        wait_sel(page, f"cables 3D: row {cid}", f'#cableList [data-cable-row="{cid}"]')
        page.click(f'#cableList [data-cable-row="{cid}"]')
        wait_fn(page, f"cables 3D: row {cid} selects", pressed(cid))
        page.click("#cableDelete")
        wait_fn(page, f"cables 3D: {cid} deleted",
                f"() => !window.__rack.doc().racks[0].cables.some(c => c.id === '{cid}')")
    wait_sel(page, "cables 3D: the empty state", "#cableEmpty")
    if (page.text_content("#cableEmpty") or "") != "No cables yet.":
        bad.append(f"cables 3D: in 3D the empty state reads {page.text_content('#cableEmpty')!r}")
    page.click('#mode [data-mode="2d"]')
    wait_fn(page, "cables 3D: the 2D empty state",
            "() => document.getElementById('cableEmpty')?.textContent.includes('Use Cable mode')")
    if (page.text_content("#cableEmpty") or "") != "No cables yet. Use Cable mode and click a port at each end.":
        bad.append(f"cables 3D: in 2D the empty state reads {page.text_content('#cableEmpty')!r}")
    return bad


def cable_fixture(doc_id, name, edit):
    f = json.loads(json.dumps(CABLE_FIXTURE))
    f["id"] = doc_id
    f["racks"][0]["name"] = name
    edit(f["racks"][0])
    return f


@extra("rack.html: a kept cable never re-attaches - a removed device's id is not handed to the next device placed")
def check_rack_cable_id_reuse(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("dialog", lambda d: (bad.append(f"id reuse: a browser dialog opened ({d.message!r})"), d.dismiss()))
    # c2 runs to the device with the HIGHEST id (i4), so its id is the next one a naive count hands out.
    def edit(rack):
        rack["cables"][1]["b"]["item"] = "i4"
        rack["cables"][2]["b"]["item"] = "i3"
    try:
        open_cabled(page, base, cable_fixture("doc-cable-id-reuse", "Cable ids", edit))
    except RuntimeError as e:
        return bad + [f"id reuse: {e}"]
    doc = lambda: page.evaluate("() => window.__rack.doc().racks[0]")
    reason = lambda: page.evaluate("() => window.__rack.cableFacts().reasons['i4|front|port-2-1']")
    select_item(page, "rear", "i4")
    page.click("#iRemove")
    wait_sel(page, "id reuse: the remove panel", "#removeKeepCables")
    page.click("#removeKeepCables")
    wait_fn(page, "id reuse: demarc (U20) removed", "() => window.__rack.doc().racks[0].items.length === 3")
    wait_fn(page, "id reuse: c2's far end is loose",
            "() => window.__rack.cableFacts().reasons['i4|front|port-2-1'] === 'the device was removed'")
    # Place another device where the removed one stood.
    pick(page, "rear", 20, "TM-280", "tm-280", dispatch=True)
    wait_fn(page, "id reuse: a device placed", "() => window.__rack.doc().racks[0].items.length === 4")
    new = doc()["items"][-1]
    if new["id"] == "i4":
        bad.append("id reuse: the new device was given i4, the id the kept cable still names")
    wait_fn(page, "id reuse: the new device is drawn",
            f"""() => !!document.querySelector('svg[data-pane="rear"] [data-item-id="{new["id"]}"][data-panel]')""")
    # Past the redraw that would land it: read what the newest drawing says.
    page.evaluate("() => document.activeElement?.blur()")
    page.keyboard.press("Escape")
    wait_sel(page, "id reuse: the cable list", '#cableList [data-cable-row="c2"]')
    if reason() != "the device was removed":
        bad.append(f"id reuse: after placing a new device, c2's far end reads {reason()!r}")
    line = page.text_content('#cableList li[data-cable-item="c2"] [data-loose="b"]') if page.query_selector(
        '#cableList li[data-cable-item="c2"] [data-loose="b"]') else None
    if line != "Loose end B: the device was removed.":
        bad.append(f"id reuse: the list says {line!r} of c2's far end")
    if page.query_selector('svg[data-pane="rear"] [data-cable-id="c2"]'):
        bad.append("id reuse: c2 is drawn on the rear pane, landing on the new device")
    if page.get_attribute('svg[data-pane="front"] [data-cables] [data-cable-id="c2"]', "data-loose-lead") != "to":
        bad.append("id reuse: c2 is not an unplugged lead on the front pane")
    if page.evaluate(PLUGS_JS, ["rear", new["id"]]) != {"lc": 0, "rj45": 0}:
        bad.append("id reuse: the new device was drawn with a plug for a cable that is not its own")
    return bad


# A 42U RACK WHOSE CABLES REACH BELOW IT: one from the top U to the bottom U
# in the front pane (its sag grows with its length), and an unplugged lead
# from a U1 device in the rear pane, whose tag hangs below the rack.
ROOM_FIXTURE = {
    "format": "portrayal-rack", "version": 1, "id": "doc-cable-room",
    "racks": [{
        "id": "r1", "name": "Cable room",
        "frame": {"kind": "four-post", "heightRU": 42, "numbering": "bottom-up",
                  "holes": {"style": "square", "thread": None},
                  "railDepth": 740, "usableDepth": 1000, "ref": None},
        "items": [
            {"id": "i1", "ref": "as7726-32x", "cfg": "ac-f2b", "label": "top", "ru": 42, "face": "front",
             "turned": False, "swaps": {}, "fields": {}},
            {"id": "i2", "ref": "as7726-32x", "cfg": "ac-f2b", "label": "bottom", "ru": 1, "face": "front",
             "turned": False, "swaps": {}, "fields": {}},
            {"id": "i3", "ref": "tm-280", "cfg": "base", "label": "low demarc", "ru": 1, "face": "rear",
             "turned": False, "swaps": {}, "fields": {}},
        ],
        "zeroU": [],
        "cables": [
            {"id": "c1", "a": {"item": "i1", "path": "mgmt-eth", "view": "front"},
             "b": {"item": "i2", "path": "mgmt-eth", "view": "front"},
             "media": "cat6a", "purpose": "management", "label": "", "route": []},
            {"id": "c2", "a": {"item": "i3", "path": "port-2-1", "view": "front"},
             "b": {"item": "i9", "path": "port-1", "view": "front"},
             "media": "cat6a", "purpose": "management", "label": "", "route": []},
        ]}]}

# Every stroke, plug and tag of each pane's cable layers that reaches outside
# the pane's viewBox - what the pane would clip.
CLIPPED_JS = """() => Object.fromEntries(['front', 'rear'].map(p => {
  const svg = document.querySelector(`svg[data-pane="${p}"]`);
  const vb = svg.getAttribute('viewBox').split(/\\s+/).map(Number);
  const nodes = [...svg.querySelectorAll('[data-cables] path, [data-cables] rect, [data-cable-tags] rect, [data-cable-tags] text')];
  const out = nodes.map(n => [n, n.getBBox()]).filter(([, b]) =>
    b.x < vb[0] - 0.01 || b.y < vb[1] - 0.01 || b.x + b.width > vb[0] + vb[2] + 0.01 || b.y + b.height > vb[1] + vb[3] + 0.01)
    .map(([n, b]) => `${n.closest('[data-cable-id]')?.dataset.cableId} ${n.tagName} to y ${Math.round(b.y + b.height)} of ${Math.round(vb[1] + vb[3])}`);
  return [p, {vb, nodes: nodes.length, tags: svg.querySelectorAll('[data-cable-tags] rect').length, out}];
}))"""


@extra("rack.html: a long cable's loop and a bottom lead's tag are never cut off - the panes grow downward together, and Fit still fits")
def check_rack_cables_room(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base, ROOM_FIXTURE)
    except RuntimeError as e:
        return bad + [f"cable room: {e}"]
    near = lambda a, b, tol=0.6: abs(a - b) <= tol
    got = page.evaluate(CLIPPED_JS)
    if got["front"]["nodes"] < 2 or got["rear"]["tags"] != 1:
        return bad + [f"cable room: the fixture did not draw its cables ({got}); the check proves nothing"]
    for p in ("front", "rear"):
        if got[p]["out"]:
            bad.append(f"cable room: the {p} pane cuts off {got[p]['out']}")
    f, r = got["front"]["vb"], got["rear"]["vb"]
    if not (near(f[1], r[1], 0.01) and near(f[3], r[3], 0.01)):
        bad.append(f"cable room: the panes' viewBoxes differ in origin or height ({f} / {r})")
    panes = page.evaluate(PANES_JS)
    front, rear = panes["front"], panes["rear"]
    if not (near(front["u1"]["h"], rear["u1"]["h"], 0.3) and near(front["u1"]["top"], rear["u1"]["top"], 1)):
        bad.append(f"cable room: U1 is not level across the panes ({front['u1']} / {rear['u1']})")
    if not (near(front["box"]["w"], rear["box"]["w"]) and near(front["box"]["h"], rear["box"]["h"])):
        bad.append(f"cable room: the panes differ in size ({front['box']} / {rear['box']})")
    # The base box is still the box before any widening: the plain 42U rack.
    base_h = float((front["baseBox"] or "0 0 0 0").split()[3])
    if not (base_h > 0 and f[3] > base_h + 40 and front["baseBox"].split()[3] == rear["baseBox"].split()[3]):
        bad.append(f"cable room: base boxes {front['baseBox']} / {rear['baseBox']} under viewBox height {f[3]}")
    # Fit fits the height and the width of the taller panes.
    fit = page.evaluate("""() => { const p = document.getElementById('panes');
      const cols = [...p.children].map(c => c.getBoundingClientRect());
      const svgs = ['front', 'rear'].map(n => document.querySelector(`svg[data-pane="${n}"]`).getBoundingClientRect());
      return {label: document.getElementById('zoomLevel').textContent, panes: p.getBoundingClientRect().height,
              scrollX: p.scrollWidth - p.clientWidth, scrollY: p.scrollHeight - p.clientHeight,
              h: svgs.map(r => r.height), over: svgs.map((r, i) => r.right - cols[i].right)}; }""")
    if (fit["label"] != "Fit" or any(h > fit["panes"] + 1 for h in fit["h"]) or fit["scrollX"] > 1
            or fit["scrollY"] > 1 or any(o > 1 for o in fit["over"])):
        bad.append(f"cable room: Fit does not fit the grown panes ({fit})")
    # A zoom step and back to Fit: still nothing cut off.
    page.click("#zoomIn")
    page.click("#zoomFit")
    again = page.evaluate(CLIPPED_JS)
    if again["front"]["out"] or again["rear"]["out"] or again["front"]["vb"] != f:
        bad.append(f"cable room: after a zoom and Fit the panes are {again}")
    # A rack with no cables is untouched.
    open_fixture(page, base)
    plain = page.evaluate(PANES_JS)
    if plain["front"]["baseBox"] or plain["front"]["layers"] or not near(plain["front"]["vb"][3], plain["rear"]["vb"][3], 0.01):
        bad.append(f"cable room: a rack with no cables was widened ({plain['front']['vb']}, base {plain['front']['baseBox']})")
    return bad


@extra("rack.html: a length keeps the unit its file wrote - listed as written, kept by an edit that leaves it alone; clearing it saves none; only a new value needs m or ft")
def check_rack_cable_length_units(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    def edit(rack):
        rack["cables"][1]["length"] = {"value": 3, "unit": "yd"}
        rack["cables"][2]["length"] = {"value": "long", "unit": "m"}
    try:
        open_cabled(page, base, cable_fixture("doc-cable-units", "Cable units", edit))
    except RuntimeError as e:
        return bad + [f"length units: {e}"]
    cable = lambda cid: page.evaluate("id => window.__rack.doc().racks[0].cables.find(c => c.id === id)", cid)
    meta = lambda cid: (page.text_content(f'#cableList li[data-cable-item="{cid}"] .rk-cable-meta') or "")
    wait_sel(page, "length units: the list", '#cableList [data-cable-row="c2"]')
    if cable("c2").get("length") != {"value": 3, "unit": "yd", "source": "entered"}:
        bad.append(f"length units: the loader made c2's length {cable('c2').get('length')}")
    if "3 yd" not in meta("c2"):
        bad.append(f"length units: the list says {meta('c2')!r} of a 3 yd cable")
    # A length the loader cannot use is kept as written, beside the cable, and shown nowhere as a number.
    c3 = cable("c3")
    if "length" in c3 or c3.get("lengthAsWritten") != {"value": "long", "unit": "m"}:
        bad.append(f"length units: c3 loaded as {c3}")
    if "long" in meta("c3") or "NaN" in meta("c3"):
        bad.append(f"length units: the list prints c3's unusable length ({meta('c3')!r})")

    def open_form():
        # A saved cable is left selected, and a second click on its row would let it go.
        wait_fn(page, "length units: no form open", "() => !document.getElementById('cableForm')")
        wait_sel(page, "length units: c2's row", '#cableList [data-cable-row="c2"]')
        if page.get_attribute('#cableList [data-cable-row="c2"]', "aria-pressed") != "true":
            page.click('#cableList [data-cable-row="c2"]')
        wait_sel(page, "length units: Edit", "#cableEdit")
        page.click("#cableEdit")
        wait_sel(page, "length units: the form", "#cableForm")
    # An edit that leaves the length alone keeps it, unit and all.
    open_form()
    if page.input_value("#cLength") != "3" or page.input_value("#cUnit") != "yd":
        bad.append(f"length units: the form shows {page.input_value('#cLength')!r} {page.input_value('#cUnit')!r}")
    page.fill("#cLabel", "M7")
    page.click("#cSave")
    wait_fn(page, "length units: the label saved", "() => window.__rack.doc().racks[0].cables[1].label === 'M7'")
    if cable("c2").get("length") != {"value": 3, "unit": "yd", "source": "entered"}:
        bad.append(f"length units: an edit that left the length alone made it {cable('c2').get('length')}")
    wait_sel(page, "length units: the list again", '#cableList li[data-cable-item="c2"] .rk-cable-meta')
    if "3 yd" not in meta("c2"):
        bad.append(f"length units: after the edit the list says {meta('c2')!r}")
    # A NEW value on the unknown unit is refused, with the sentence.
    open_form()
    page.fill("#cLength", "5")
    page.click("#cSave")
    # WRITTEN, NOT JUST ASKED FOR: the refusal is the save handler's, so wait
    # for it rather than for 200 ms - on a loaded runner the sentence below
    # would read None and end the check, which is not what went wrong. Any
    # text will do; which text it is, is exactly what is asserted next, and if
    # none ever comes the assertion below says so.
    try:
        page.wait_for_function("() => !!document.querySelector('#cError')?.textContent", timeout=5000)
    except Exception:
        pass
    err = lambda: page.text_content("#cError") if page.query_selector("#cError") else None
    if err() != "Choose m or ft for the new length.":
        return bad + [f"length units: a new value in yd gave {err()!r}, and c2's length is {cable('c2').get('length')}"]
    # Clearing the length, the unknown unit still selected, saves no length.
    page.fill("#cLength", "")
    page.click("#cSave")
    try:
        wait_fn(page, "length units: clearing the length saves", "() => !document.getElementById('cableForm')", timeout=5000)
    except RuntimeError:
        bad.append(f"length units: clearing a yd length was refused ({err()!r})")
    # Cleared means no ENTERED length: the page then fills in the routed one (spec 8), which is not the user's.
    if cable("c2").get("length", {}).get("source") not in (None, "routed"):
        bad.append(f"length units: after clearing it c2's length is {cable('c2').get('length')}")

    # A LENGTH KEPT AS WRITTEN (c3's {value: 'long'}): an edit that leaves the
    # length alone keeps it exactly; a length typed replaces it; so does clearing.
    def edit_c3(fill, label):
        wait_fn(page, "length units: no form open for c3", "() => !document.getElementById('cableForm')")
        wait_sel(page, "length units: c3's row", '#cableList [data-cable-row="c3"]')
        if page.get_attribute('#cableList [data-cable-row="c3"]', "aria-pressed") != "true":
            page.click('#cableList [data-cable-row="c3"]')
        wait_fn(page, "length units: c3 selected",
                """() => document.querySelector('#cableList [data-cable-row="c3"]')?.getAttribute('aria-pressed') === 'true'
                   && !!document.getElementById('cableEdit')""")
        page.click("#cableEdit")
        wait_sel(page, "length units: c3's form", "#cableForm")
        page.fill("#cLabel", label)
        if fill is not None:
            page.fill("#cLength", fill)
        page.click("#cSave")
        wait_fn(page, f"length units: c3 saved as {label}",
                f"() => window.__rack.doc().racks[0].cables[2].label === {json.dumps(label)}")
    edit_c3(None, "L1")
    c3 = cable("c3")
    if c3.get("lengthAsWritten") != {"value": "long", "unit": "m"} or "length" in c3:
        bad.append(f"length units: an edit of the label alone left c3 as {c3}")
    edit_c3("4", "L2")
    c3 = cable("c3")
    if c3.get("length") != {"value": 4, "unit": "m", "source": "entered"} or "lengthAsWritten" in c3:
        bad.append(f"length units: after a length was typed c3 is {c3}")
    # The clear case: put the kept-as-written length back, open the form, type and clear.
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, cables: r.cables.map(c => {
        if (c.id !== 'c3') return c;
        const {length, ...rest} = c;
        return {...rest, lengthAsWritten: {value: 'long', unit: 'm'}}; })}); }""")
    wait_fn(page, "length units: c3 kept as written again",
            "() => !!window.__rack.doc().racks[0].cables[2].lengthAsWritten && !window.__rack.doc().racks[0].cables[2].length")
    page.wait_for_timeout(300)
    wait_fn(page, "length units: c3 selected", "() => !!document.getElementById('cableEdit')")
    page.click("#cableEdit")
    wait_sel(page, "length units: c3's form to clear", "#cableForm")
    page.fill("#cLabel", "L3")
    page.fill("#cLength", "7")
    page.fill("#cLength", "")
    page.select_option("#cUnit", "ft")
    page.click("#cSave")
    wait_fn(page, "length units: c3 saved as L3", "() => window.__rack.doc().racks[0].cables[2].label === 'L3'")
    c3 = cable("c3")
    if c3.get("length", {}).get("source") == "entered" or "lengthAsWritten" in c3:
        bad.append(f"length units: after the length was cleared c3 is {c3}")
    return bad


@extra("rack.html: a control of a panel built for an earlier rack acts on the rack as it is now - Remove, the inspector's fields, the frame's name, Place")
def check_rack_stale_handlers(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("dialog", lambda d: d.accept())
    doc = lambda: page.evaluate("() => window.__rack.doc().racks[0]")
    open_fixture(page, base)
    whole = doc()
    restore = lambda: (page.evaluate("w => window.__rack.replaceRack(w)", whole),
                       wait_fn(page, "stale: the rack is whole again",
                               "() => window.__rack.doc().racks[0].items.length === 4 && window.__rack.doc().racks[0].name === 'Export test'"),
                       wait_fn(page, "stale: all four drawn again",
                               """() => document.querySelectorAll('svg[data-pane="rear"] [data-item-id][data-panel]').length >= 4"""))
    # Each step changes the rack and uses the OLD panel's control in one page
    # task: the redraw that would replace the panel has not run yet.
    # 1. Remove, over a renamed rack: the device goes, the new name stays.
    select_item(page, "rear", "i3")
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, name: 'Renamed'});
      document.getElementById('iRemove').click(); }""")
    wait_fn(page, "stale: demarc removed", "() => window.__rack.doc().racks[0].items.length === 3")
    if doc()["name"] != "Renamed":
        bad.append(f"stale: Remove wrote the rack it was built for back (name {doc()['name']!r})")
    restore()
    # 2. Remove, for a device already gone: nothing changes, and a pending Undo stands.
    select_item(page, "rear", "i3")
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, items: r.items.filter(i => i.id !== 'i3')}, {text: 'Dropped demarc.'});
      document.getElementById('iRemove').click(); }""")
    page.wait_for_timeout(400)
    if len(doc()["items"]) != 3 or not page.query_selector("#undoShrink"):
        bad.append(f"stale: Remove for a device already gone left {len(doc()['items'])} items, "
                   f"Undo {'offered' if page.query_selector('#undoShrink') else 'retired'}")
    restore()
    # 3. An inspector field, for a device already gone: no error, no commit (Undo stands).
    for field, js in (("the label", "const f = document.getElementById('iLabel'); f.value = 'zz';"),
                      ("the configuration", "const f = document.getElementById('iCfg'); f.value = f.options[f.options.length - 1].value;"),
                      ("the turned box", "const f = document.getElementById('iTurned'); f.checked = true;")):
        select_item(page, "front", "i2")
        page.evaluate("""() => { const r = window.__rack.doc().racks[0];
          window.__rack.replaceRack({...r, items: r.items.filter(i => i.id !== 'i2')}, {text: 'Dropped leaf-1.'});
          %s f.dispatchEvent(new Event('change', {bubbles: true})); }""" % js)
        page.wait_for_timeout(400)
        if len(doc()["items"]) != 3 or not page.query_selector("#undoShrink"):
            bad.append(f"stale: {field} of a device already gone left {len(doc()['items'])} items, "
                       f"Undo {'offered' if page.query_selector('#undoShrink') else 'retired'}")
        restore()
    # 4. An inspector field over a changed rack: the change lands on the rack as it is now.
    select_item(page, "front", "i2")
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, name: 'Renamed'});
      const f = document.getElementById('iLabel'); f.value = 'leaf-9';
      f.dispatchEvent(new Event('change', {bubbles: true})); }""")
    wait_fn(page, "stale: the label saved", "() => window.__rack.doc().racks[0].items[1].label === 'leaf-9'")
    if doc()["name"] != "Renamed":
        bad.append(f"stale: an inspector field wrote the old rack back (name {doc()['name']!r})")
    restore()
    # 5. The frame form's name, over a rack that lost a device: the device stays gone.
    page.click("#frameBtn")
    wait_sel(page, "stale: the frame form", "#fName")
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, items: r.items.filter(i => i.id !== 'i4')});
      const f = document.getElementById('fName'); f.value = 'Lab';
      f.dispatchEvent(new Event('change', {bubbles: true})); }""")
    wait_fn(page, "stale: the name saved", "() => window.__rack.doc().racks[0].name === 'Lab'")
    if len(doc()["items"]) != 3:
        bad.append(f"stale: the frame form's name brought a removed device back ({len(doc()['items'])} items)")
    page.click("#frameBtn")
    restore()
    # 6. Place, into a U the rack has since filled: refused with the reason, nothing placed.
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, items: r.items.filter(i => i.id !== 'i4')}); }""")
    wait_fn(page, "stale: U20 is free", """() => !document.querySelector('svg[data-pane="rear"] [data-item-id="i4"]')""")
    page.dispatch_event('svg[data-pane="rear"] rect.rk-u[data-u="20"]', "click")
    wait_sel(page, "stale: the picker", "#catQuery")
    page.fill("#catQuery", "TM-280")
    page.select_option("#catDevice", "tm-280")
    page.evaluate("""w => { window.__rack.replaceRack(w); document.getElementById('catPlace').click(); }""", whole)
    page.wait_for_timeout(400)
    if len(doc()["items"]) != 4:
        bad.append(f"stale: Place put a device into a U that was no longer free ({len(doc()['items'])} items)")
    return bad


@extra("rack.html: in 3D, a device edit then a cable's label edit inside the rebuild's wait - the GLB exported next carries the new device")
def check_rack_export_after_cable_edit(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"export after a cable edit: {e}"]
    if webgl_trouble(page):
        print("[check_rack_export_after_cable_edit] WebGL unavailable - not exercised")
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "export after a cable edit: the scene")
    page.click("#exportMenu > summary")
    page.wait_for_selector('#exportItems [data-export="glb"]', timeout=READY_MS)
    # One page task: a device is added (its rebuild waits 300 ms), a cable's
    # label is changed (a commit the scene reads nothing of, which re-points a
    # CURRENT scene and must leave this stale one stale), and the export is
    # asked for.
    downloads = []
    page.on("download", lambda d: downloads.append(d))
    page.evaluate("""() => {
      const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, items: [...r.items, {id: 'i5', ref: 'tm-280', cfg: 'base', label: 'late',
        ru: 22, face: 'front', turned: false, swaps: {}, fields: {}}]});
      const r2 = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r2, cables: r2.cables.map((c, k) => (k ? c : {...c, label: 'renamed'}))});
      document.querySelector('#exportItems [data-export="glb"]').click(); }""")
    # The status settles whether or not a file comes, so a refused export is
    # reported at once and not by waiting out a download that never starts.
    status = export_status(page)
    if not status.startswith("Downloaded"):
        return bad + [f"export after a cable edit: no GLB; the status reads {status!r}"]
    for _ in range(50):
        if downloads:
            break
        page.wait_for_timeout(100)
    if not downloads:
        return bad + ["export after a cable edit: the status says Downloaded and no file came"]
    glb = pathlib.Path(downloads[0].path()).read_bytes()
    missing = [i for i in ("i1", "i2", "i3", "i4", "i5") if f'"device-{i}"'.encode() not in glb]
    if missing:
        bad.append(f"export after a cable edit: the GLB has no node for {missing} - it was made from the scene before the device edit")
    page.click('#mode [data-mode="2d"]')
    return bad


@extra("rack.html: cabling's small print - a tag never discards a new cable's form, a gone cable's form falls back to the list, focus follows a delete and the remove panel, Undo says what it undoes, counts read right")
def check_rack_cable_polish(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("dialog", lambda d: (bad.append(f"polish: a browser dialog opened ({d.message!r})"), d.dismiss()))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"polish: {e}"]
    doc = lambda: page.evaluate("() => window.__rack.doc().racks[0]")
    whole = doc()
    active = lambda: page.evaluate("() => document.activeElement?.id || ''")
    def focus_is(label, want):
        try:
            wait_fn(page, label, f"() => document.activeElement?.id === {json.dumps(want)}", timeout=5000)
        except RuntimeError:
            bad.append(f"polish: {label}: focus is on {active()!r}, expected {want!r}")
    note = lambda: (page.text_content(".rk-side .rk-notice") or "") if page.query_selector(".rk-side .rk-notice") else ""

    # M1. A tag clicked (or keyed) while a NEW cable's form is open leaves the form alone.
    page.click("#cableBtn")
    page.click(port_sel("front", "i2", "port-3"))
    wait_sel(page, "polish: A picked", 'svg[data-pane="front"] .rk-end-pick')
    page.click(port_sel("front", "i2", "port-4"))
    wait_sel(page, "polish: the new cable's form", "#cableForm")
    page.fill("#cLabel", "typed")
    tag = 'svg[data-pane="front"] [data-cable-tags] [data-cable-id="c2"]'
    page.dispatch_event(tag, "click")
    page.focus(tag)
    page.keyboard.press("Enter")
    page.wait_for_timeout(400)
    if not page.query_selector("#cableForm") or page.input_value("#cLabel") != "typed":
        bad.append("polish: a tag click discarded the new cable's form")
    else:
        page.click("#cCancel")
    page.evaluate("() => document.activeElement?.blur()")
    page.keyboard.press("Escape")
    wait_fn(page, "polish: Cable mode off",
            "() => document.getElementById('cableBtn').getAttribute('aria-pressed') === 'false'")
    # With no form open a tag still selects its cable.
    page.dispatch_event(tag, "click")
    wait_fn(page, "polish: a tag still selects",
            """() => document.querySelector('#cableList [data-cable-row="c2"]')?.getAttribute('aria-pressed') === 'true'""")

    # M2. An edit form whose cable is gone falls back to the list, not the bare summary.
    page.click("#cableEdit")
    wait_sel(page, "polish: the edit form", "#cableForm")
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, cables: r.cables.filter(c => c.id !== 'c2')}); }""")
    wait_fn(page, "polish: the form of a cable that is gone closes", "() => !document.getElementById('cableForm')")
    if not page.query_selector("#cableList"):
        bad.append("polish: after its cable went, the form's panel has no cable list")
    page.evaluate("w => window.__rack.replaceRack(w)", whole)
    wait_sel(page, "polish: c2 back", '#cableList [data-cable-row="c2"]')

    # M3 + M4. Delete: focus goes to Undo, which says what it would undo - and keeps saying it.
    page.click('#cableList [data-cable-row="c1"]')
    wait_sel(page, "polish: Delete", "#cableDelete")
    page.click("#cableDelete")
    wait_fn(page, "polish: c1 deleted", "() => window.__rack.doc().racks[0].cables.length === 2")
    focus_is("after a delete", "undoShrink")
    said = lambda: page.evaluate("""() => { const b = document.getElementById('undoShrink');
      const d = b && document.getElementById(b.getAttribute('aria-describedby') || '');
      return b ? {text: b.textContent, what: d ? d.textContent : null,
                  whats: document.querySelectorAll('#undoWhat').length} : null; }""")
    if said() != {"text": "Undo", "what": "Deleted cable A1.", "whats": 1}:
        bad.append(f"polish: right after a delete, Undo is {said()}")
    select_item(page, "front", "i2")           # the one-shot notice is gone; the button is not
    if note():
        bad.append(f"polish: the one-shot notice is still shown ({note()!r})")
    if said() != {"text": "Undo", "what": "Deleted cable A1.", "whats": 1}:
        bad.append(f"polish: after selecting something else, Undo is {said()} - it no longer says what it undoes")
    page.click("#undoShrink")
    wait_fn(page, "polish: c1 is back", "() => window.__rack.doc().racks[0].cables.length === 3")
    # The rack was put back with replaceRack above, which is a step of its own
    # (every change is one now): Undo stays, and its sentence goes with it,
    # describing that earlier step instead of the delete just undone.
    wait_fn(page, "polish: Undo and its sentence go together",
            """() => { const b = document.getElementById('undoShrink');
                       const d = b && document.getElementById(b.getAttribute('aria-describedby') || '');
                       return !!d && d.id === 'undoWhat' && d.textContent === 'Changed the rack.'
                              && document.querySelectorAll('#undoWhat').length === 1; }""")

    # M3. The remove panel takes the keyboard at its first button; Cancel and Esc hand it back to Remove.
    select_item(page, "rear", "i3")
    page.click("#iRemove")
    wait_sel(page, "polish: the remove panel", "#removePanel")
    focus_is("the remove panel opens", "removeWithCables")
    page.click("#removeCancel")
    wait_sel(page, "polish: back on the device", "#iLabel")
    focus_is("after Cancel", "iRemove")
    page.click("#iRemove")
    wait_sel(page, "polish: the remove panel again", "#removePanel")
    focus_is("the remove panel opens again", "removeWithCables")
    page.keyboard.press("Escape")
    wait_sel(page, "polish: Esc goes back to the device", "#iLabel")
    focus_is("after Esc", "iRemove")

    # M5. "and its 0 cables" is never said: the count is the one at the click.
    page.click("#iRemove")
    wait_sel(page, "polish: the remove panel for the count", "#removeWithCables")
    for btn, want in (("removeWithCables", "Removed demarc."), ("removeKeepCables", "Removed demarc.")):
        page.evaluate("""(btn) => { const r = window.__rack.doc().racks[0];
          window.__rack.replaceRack({...r, cables: r.cables.filter(c => c.a.item !== 'i3' && c.b.item !== 'i3')});
          document.getElementById(btn).click(); }""", btn)
        wait_fn(page, "polish: demarc removed", "() => window.__rack.doc().racks[0].items.length === 3")
        try:
            wait_fn(page, f"polish: the notice after {btn}",
                    f"() => (document.querySelector('.rk-side .rk-notice')?.textContent || '') === {json.dumps(want)}", timeout=5000)
        except RuntimeError:
            bad.append(f"polish: {btn} with no cable left says {note()!r}, expected {want!r}")
        focus_is(f"after {btn}", "undoShrink")
        page.evaluate("w => window.__rack.replaceRack(w)", whole)
        wait_fn(page, "polish: the rack is whole", "() => window.__rack.doc().racks[0].items.length === 4")
        if btn == "removeWithCables":
            select_item(page, "rear", "i3")
            page.click("#iRemove")
            wait_sel(page, "polish: the remove panel once more", "#removeKeepCables")
    # ... and one cable is "1 of 1 cable matches."
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, cables: r.cables.slice(0, 1)}); }""")
    page.evaluate("() => document.activeElement?.blur()")
    page.keyboard.press("Escape")
    count = "() => document.querySelector('#cableList [data-filter-count]')?.textContent"
    try:
        wait_fn(page, "polish: the count of one", f"() => ({count})() === '1 of 1 cable matches.'", timeout=5000)
    except RuntimeError:
        bad.append(f"polish: with one cable the count reads {page.evaluate(count)!r}")

    # M7. A sentence the notice already holds is not added again.
    page.evaluate("""() => { window.__rack.addNotice('Once.'); window.__rack.addNotice('Once.');
      window.__rack.addNotice('Twice.'); window.__rack.addNotice('Once.');
      window.__rack.replaceRack(window.__rack.doc().racks[0]); }""")
    wait_sel(page, "polish: the notice", ".rk-side .rk-notice")
    if note() != "Once. Twice.":
        bad.append(f"polish: a repeated sentence gave the notice {note()!r}")
    return bad


# A CITATION SAYS WHAT ITS SOURCE SAID. A provenance entry has been an object,
# `{confidence, note}`, since Portrayal #167, and the About panel printed it as
# a string: "chassis: [object Object]" under Dimensions, and the same under
# every other cited fact on almost every device (roc-ops/portrayal-site#87).
# The expected lines are built from the device's own configs.json, so a sync
# that rewords a note changes both sides. The R660 has only leftover entries
# apart from its chassis; the AGR110 has entries cited under its attrs too.
@extra("Explorer: the About panel prints a provenance entry's confidence and note, never [object Object]")
def check_about_provenance(page, base):
    bad = []
    for device in ["r660", "agr110"]:
        page.goto(f"{base}/explorer.html?device={device}", wait_until="load")
        wait_sel(page, f"{device}: the chassis row", '#tree .node[data-path="chassis"]')
        page.click('#tree .node[data-path="chassis"]')
        wait_sel(page, f"{device}: the About panel", "#inspect .prov")
        r = page.evaluate("""async device => {
          const meta = await (await fetch(`assets/dist/${device}.configs.json`)).json();
          const box = document.querySelector('#inspect');
          return {prov: meta.provenance || {}, text: box.textContent,
                  head: box.querySelector('h2')?.textContent,
                  lines: [...box.querySelectorAll('.prov')].map(e => e.textContent)};
        }""", device)
        if r["head"] != "About":
            bad.append(f"{device}: the inspector is headed {r['head']!r}, not About")
            continue
        if "[object Object]" in r["text"]:
            n = r["text"].count("[object Object]")
            bad.append(f"{device}: the About panel prints [object Object] {n} time(s)")
        entries = {k: v for k, v in r["prov"].items() if v}
        if len(entries) < 10 or not isinstance(entries.get("chassis"), dict):
            bad.append(f"{device}: expected ten or more provenance entries and an object for"
                       f" chassis, found {len(entries)} - the check needs another device")
            continue
        wrong = []
        for k, v in entries.items():
            said = v if isinstance(v, str) else " ".join(
                filter(None, [v.get("confidence") and f"[{v['confidence']}]", v.get("note")]))
            if f"{k}: {said}" not in r["lines"]:
                got = next((l for l in r["lines"] if l.startswith(f"{k}: ")), None)
                wrong.append(f"{device}: the {k} citation reads {got and got[:60]!r},"
                             f" expected {(k + ': ' + said)[:60]!r}")
        # one broken helper breaks every line alike; three say it as well as thirty
        bad += wrong[:3] + ([f"{device}: ... and {len(wrong) - 3} more citations"] if len(wrong) > 3 else [])
        if len(r["lines"]) != len(entries):
            bad.append(f"{device}: {len(r['lines'])} citations printed for {len(entries)} provenance entries")
        # the chassis citation belongs under Dimensions, bracketed confidence first
        chassis = entries["chassis"]
        first = next((l for l in r["lines"] if l.startswith("chassis: ")), "")
        if chassis.get("confidence") and not first.startswith(f"chassis: [{chassis['confidence']}] "):
            bad.append(f"{device}: the chassis citation does not lead with its confidence: {first[:60]!r}")
    return bad


@extra("rack.html: Export - the cable schedule lists each cable with its ends, media, length and status, named as the device import names them")
def check_rack_export_cable_schedule(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cable schedule: {e}"]
    dl = export_file(page, "cables")
    status = export_status(page)
    if dl.suggested_filename != "Cable-test-cables.csv":
        bad.append(f"cable schedule: named {dl.suggested_filename!r}")
    cols, rows, text = read_csv(dl)
    if cols != ["id", "cable", "a_device", "a_u", "a_port", "b_device", "b_u", "b_port", "media", "purpose",
                "length", "length_unit", "route", "bundle", "length_source", "status", "notes",
                # rack file version 4 (kit 0.22.0): three columns appended after the last, so none read by position moves
                "spare", "stored", "straps"]:
        bad.append(f"cable schedule: columns {cols}")
    # THE THREE NEW CELLS ARE THE KIT'S: each cable's spare (slack.js slackOf, by the page's route context) to
    # the centimetre, where it is stored in the kit's words, and no strap for a cable tied nowhere. A cable with
    # a loose end has none. And the one line that totals the spare.
    kit = page.evaluate("""async () => {
      const S = await import('/vendor/rack/slack.js'), rack = window.__rack.doc().racks[0], ctx = window.__rack.routeContext();
      const out = {line: S.spareLine(rack, ctx), cells: {}};
      for (const c of rack.cables) { const s = S.slackOf(rack, c, ctx);
        out.cells[c.id] = s ? {spare: String(Math.round(s.spare.spare_m * 100) / 100), stored: S.storedText(rack, c, s)} : null; }
      return out;
    }""")
    for r in rows:
        k = kit["cells"].get(r["id"]) if r.get("status") == "connected" else {"spare": "", "stored": ""}
        if not k or (r.get("spare"), r.get("stored"), r.get("straps")) != (k["spare"], k["stored"], ""):
            bad.append(f"cable schedule: {r['id']} says spare {r.get('spare')!r}, stored {r.get('stored')!r}, straps {r.get('straps')!r}; the kit gives {k}")
        if r.get("status") == "connected" and not (float(r["spare"] or 0) > 0 and r["stored"].endswith(" at the ends")):
            bad.append(f"cable schedule: {r['id']} is connected and says no spare: {r}")
    # THE PAGE AND THE FILE SAY ONE FIGURE: each connected cable's row in the list ends with the schedule's spare.
    listed = page.evaluate("() => Object.fromEntries([...document.querySelectorAll('#cableList li[data-cable-item]')].map(li => [li.dataset.cableItem, li.querySelector('.rk-cable-meta')?.textContent ?? '']))")
    for r in rows:
        if r.get("status") == "connected" and not listed.get(r["id"], "").endswith(f", {r['spare']} m spare"):
            bad.append(f"cable schedule: {r['id']}'s spare is {r['spare']} m in the file, and its row in the list reads {listed.get(r['id'])!r}")
    rows = [{k: v for k, v in r.items() if k not in ("spare", "stored", "straps")} for r in rows]
    want = [
        {"id": "c1", "cable": "A1", "a_device": "leaf-1", "a_u": "14", "a_port": "port-1", "b_device": "core-1", "b_u": "2",
         "b_port": "slot-2/module/p0", "media": "OS2 single-mode fiber", "purpose": "uplink", "length": "2",
         "length_unit": "m", "route": "left-front U14-U2", "bundle": "", "length_source": "entered", "status": "connected", "notes": ""},
        {"id": "c2", "cable": "c2", "a_device": "leaf-1", "a_u": "14", "a_port": "mgmt-eth", "b_device": "demarc-i3", "b_u": "14",
         # c2 measures 1.503 m on kit 0.15.0 (each RJ45 plug's reach and its hang), 3 mm over the 1.5 m break
         "b_port": "port-2-1", "media": "Cat 6A copper", "purpose": "management", "length": "2", "length_unit": "m",
         "route": "right-front U14 > right-rear U14", "bundle": "", "length_source": "routed", "status": "connected", "notes": ""},
        {"id": "c3", "cable": "c3", "a_device": "leaf-1", "a_u": "14", "a_port": "port-2", "b_device": "demarc-i4", "b_u": "20",
         "b_port": "port-2-1", "media": "OS2 single-mode fiber", "purpose": "uplink", "length": "2", "length_unit": "m",
         "route": "left-front U14-U20 > left-rear U20", "bundle": "", "length_source": "routed", "status": "loose end",
         "notes": "End A is not connected: port-2 holds no optic. "
                  "OS2 single-mode fiber does not suit end B, which is copper."}]
    if rows != want:
        bad.append(f"cable schedule: rows {rows}")
    notes = [l for l in text.partition("\r\nNotes\r\n")[2].split("\r\n") if l]
    if notes != ["\"Devices that share a label are named as the device import names them: demarc-i3, demarc-i4.\"", kit["line"]] \
            or not re.fullmatch(r"Spare: [\d.]+ m; \d+ cords? not placed\.", kit["line"]):
        bad.append(f"cable schedule: the notes section reads {notes}; the kit's spare line is {kit['line']!r}")
    # Two notes in the notes section (the second the kit's spare line, since 0.22.0) and one row with notes: three in the file.
    if status != notes_status(3):
        bad.append(f"cable schedule: the status reads {status!r}")
    if "not in this export yet" in text:
        bad.append("cable schedule: it says cables are not in this export")
    # The device import names the same two devices the same way.
    names = {r["name"] for r in device_rows(page)}
    if not {"demarc-i3", "demarc-i4", "leaf-1", "core-1"} <= names:
        bad.append(f"cable schedule: the device import names {sorted(names)}, and the schedule's are not among them")

    # A label that opens as a formula is guarded; a length kept as written is in the notes, not the number.
    odd = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      const r = window.__rack.doc().racks[0];
      const cables = [{...r.cables[0], label: '=SUM(A1)', length: undefined, lengthAsWritten: {value: 'about 3', unit: 'm'}}];
      return {sched: (await X.cableScheduleCsv({...r, cables}, of)).data, bom: (await X.bomCsv({...r, cables}, of)).data};
    }""")
    # The BOM lists that cable as "length not set", and says what the file wrote, in the schedule's words.
    if 'Cable =SUM(A1): Length as written in the file: {""value"":""about 3"",""unit"":""m""}.' not in odd["bom"]:
        bad.append(f"cable schedule: the BOM does not say a length was kept as written: {odd['bom'].partition('Notes')[2]!r}")
    odd = odd["sched"]
    line = odd.split("\r\n")[1]
    if not line.startswith("c1,'=SUM(A1),leaf-1,14,port-1,core-1,2,slot-2/module/p0,OS2 single-mode fiber,uplink,,,left-front U14-U2,,,connected,"):
        bad.append(f"cable schedule: a formula-like label or a length as written is wrong: {line!r}")
    if 'Length as written in the file: {""value"":""about 3"",""unit"":""m""}.' not in line:
        bad.append(f"cable schedule: the length as written is not quoted in the notes: {line!r}")

    # No cables: the header alone, and a note saying so.
    open_fixture(page, base)
    dl = export_file(page, "cables")
    status = export_status(page)
    cols, rows, text = read_csv(dl)
    if dl.suggested_filename != "Export-test-cables.csv" or rows or not cols or cols[:2] != ["id", "cable"]:
        bad.append(f"cable schedule, no cables: {dl.suggested_filename!r} with rows {rows}")
    if "This rack has no cables, so there is nothing to list." not in text.partition("\r\nNotes\r\n")[2]:
        bad.append(f"cable schedule, no cables: the notes do not say so: {text!r}")
    if status != notes_status(1):
        bad.append(f"cable schedule, no cables: the status reads {status!r}")
    return bad


@extra("rack.html: Export - the schedule's U is the device import's position, and the cable exports survive their own failures")
def check_rack_export_cable_failures(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"cable export failures: {e}"]

    # Fix round 1: the schedule's U is the device import's position, whatever the numbering.
    for numbering in ("top-down", "bottom-up"):
        got = page.evaluate("""async numbering => {
          const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
          const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
          const r = window.__rack.doc().racks[0];
          const rack = {...r, frame: {...r.frame, numbering}};
          return {sched: (await X.cableScheduleCsv(rack, of)).data, dev: (await X.dcimKit(rack, of, 'nautobot')).files['1-devices.csv']};
        }""", numbering)
        sched = list(csv.DictReader(io.StringIO(got["sched"].partition("\r\n\r\nNotes")[0])))
        # (a device Nautobot's file leaves unpositioned says its unit in its comment: nautobot_u)
        dev = {r["name"]: nautobot_u(r) for r in csv.DictReader(io.StringIO(got["dev"]))}
        seen = 0
        for row in sched:
            for side in ("a", "b"):
                if row[f"{side}_device"]:
                    seen += 1
                    if row[f"{side}_u"] != dev.get(row[f"{side}_device"]):
                        bad.append(f"cable schedule ({numbering}): {row[side + '_device']} is at U{row[side + '_u']}, the device import says {dev.get(row[side + '_device'])}")
        if not seen:
            bad.append(f"cable schedule ({numbering}): no device read, nothing compared")

    # The exports' own read of the cables' faces fails: each export still comes, and says what it could not do.
    page.evaluate("window.__rack.failExport({facts: true})")
    dl = export_file(page, "cables")
    status = export_status(page)
    _, rows, text = read_csv(dl)
    if [r["status"] for r in rows] != ["not checked"] * 3 or "Cable ends could not be checked" not in text or "didn't work" in status:
        bad.append(f"cable schedule, facts failing: {[r['status'] for r in rows]}, status {status!r}")
    _, rows, text = read_csv(export_file(page, "bom"))
    status = export_status(page)
    if "Cable ends could not be read, so the cable lines do not state their connectors." not in text \
            or [r["section"] for r in rows].count("Cables") == 0 or "didn't work" in status:
        bad.append(f"BOM, facts failing: status {status!r}, notes {text.partition(chr(13) + chr(10) + 'Notes')[2]!r}")
    for kind, note in (("sheet-svg", "Cable ends could not be checked, so loose ends are not marked."),
                       ("drawio", "3 cables are not drawn because their ends could not be checked.")):
        text = pathlib.Path(export_file(page, kind).path()).read_text(encoding="utf-8")
        status = export_status(page)
        try:
            root = ET.fromstring(text.encode("utf-8"))
        except ET.ParseError as e:
            bad.append(f"{kind}, facts failing: not well-formed ({e})")
            continue
        if note not in text or "didn't work" in status:
            bad.append(f"{kind}, facts failing: no unchecked note, or status {status!r}")
        # An edge that may run to an empty cage is a false statement: with the ends unchecked, none is drawn.
        if kind == "drawio" and (drawio_page(text)["edges"] or len(drawio_page(text)["cabinets"]) != 2):
            bad.append("drawio, facts failing: an edge is drawn, or a cabinet is missing")
    # Resetting the probe with nothing, or with null, is "nothing fails": no export throws on it.
    for reset in ("window.__rack.failExport(null)", "window.__rack.failExport()"):
        page.evaluate("window.__rack.failExport({facts: true})")
        page.evaluate(reset)
        _, rows, _ = read_csv(export_file(page, "cables"))
        status = export_status(page)
        if [r["status"] for r in rows] != ["connected", "connected", "loose end"] or "didn't work" in status:
            bad.append(f"{reset}: the schedule reads {[r['status'] for r in rows]}, status {status!r}")
    page.evaluate("window.__rack.failExport({})")

    # One pane's cables fail to draw: the sheet comes without them, the other face keeps its own, and it says so.
    export_file(page, "sheet-svg")
    n0 = int(re.search(r"with (\d+) note", export_status(page)).group(1))
    page.evaluate("window.__rack.failExport({pane: 'front'})")
    text = pathlib.Path(export_file(page, "sheet-svg").path()).read_text(encoding="utf-8")
    status = export_status(page)
    note = "The cables could not be drawn on the front face of this sheet; tags on the other face may point at runs that are not drawn."
    if note not in text or "didn't work" in status or status != notes_status(n0 + 1):
        bad.append(f"sheet, front cables failing: status {status!r}")
    try:
        root = ET.fromstring(text.encode("utf-8"))
    except ET.ParseError as e:
        return bad + [f"sheet, front cables failing: not well-formed ({e})"]
    ns = "{http://www.w3.org/2000/svg}"
    panes = {p.get("data-pane"): p for p in root.iter(f"{ns}svg") if p.get("data-pane")}
    layer = lambda p: len([g for g in p.iter(f"{ns}g") if g.get("data-cable-id")])
    if layer(panes["front"]) or not layer(panes["rear"]):
        bad.append(f"sheet, front cables failing: front has {layer(panes['front'])} cable groups, rear {layer(panes['rear'])}")
    if "data-base-box" in text:
        bad.append("sheet, front cables failing: a data-base-box is left in the file")
    # A screen concern: the cable layers carry none in the file (the elevation's own, which the pin holds, stay).
    pe = [g.get("data-cable-id") for lay in root.iter(f"{ns}g") if lay.get("data-cables") is not None or lay.get("data-cable-tags") is not None
          for g in lay.iter() if g.get("pointer-events")]
    if pe:
        bad.append(f"sheet, front cables failing: pointer-events on cable groups {pe}")
    page.evaluate("window.__rack.failExport({})")

    # The GLB's notes describe the SCENE that is exported: a scene built with its
    # cable ends checked keeps the facts it was built from, so its GLB carries the
    # checked notes even while the export's own reading of the faces would fail.
    # (Before the final fix wave the GLB re-read the faces itself, and this case
    # asserted the unchecked note - a note about a reading the model was not built from.)
    try:
        if webgl_trouble(page):
            print("[check_rack_export_cable_failures] WebGL unavailable - GLB not exercised")
            return bad
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, "GLB, facts failing: the scene")
        page.evaluate("window.__rack.failExport({facts: true})")
        dl = export_file(page, "glb", timeout=READY_3D_MS)
        glb = pathlib.Path(dl.path()).read_bytes()
        status = export_status(page)
        if glb[:4] != b"glTF":
            bad.append(f"GLB, facts failing: {dl.suggested_filename!r} is not a GLB")
        doc = json.loads(glb[20:20 + int.from_bytes(glb[12:16], "little")].decode("utf-8"))
        notes = doc["scenes"][0].get("extras", {}).get("portrayal", {}).get("notes", [])
        if page.evaluate("() => window.__rack.scene().rackCables.checked") is not True:
            bad.append("GLB, facts failing: the scene itself was not built checked, so nothing is shown")
        if notes != ["Cable c3: end A, leaf-1 (U14) port-2, is not connected (port-2 holds no optic).",
                     "Cable c3: OS2 single-mode fiber does not suit end B, which is copper."] or "didn't work" in status:
            bad.append(f"GLB, facts failing: a checked scene's notes are {notes}, status {status!r}")
    finally:
        page.evaluate("window.__rack.failExport({})")
    return bad


@extra("rack.html: Export - draw.io gives devices whose ids slug alike cells of their own, and words a device with no drawing by the side it is on")
def check_rack_export_drawio_ids(page, base):
    from collections import Counter
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"draw.io ids: {e}"]
    out = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      const r = window.__rack.doc().racks[0];
      const [leaf, , d3, d4] = [r.items[1], r.items[0], r.items[2], r.items[3]];
      const end = (item, path) => ({item, path, view: 'front'});
      const cab = (id, a, b) => ({id, a, b, media: 'cat6a', purpose: 'management', label: id, route: []});
      // Two items whose ids slug alike, each cabled to its own demarc.
      const alike = {...r, items: [{...leaf, id: 'a b', label: 'x1', ru: 8}, {...leaf, id: 'a-b', label: 'x2', ru: 10}, d3, d4],
        cables: [cab('k1', end('a b', 'mgmt-eth'), end(d3.id, 'port-2-1')), cab('k2', end('a-b', 'mgmt-eth'), end(d4.id, 'port-2-1'))]};
      // A device with no drawing at all (an unknown configuration): a dashed box on each side.
      const bare = {...r, cables: [], items: [{...leaf, id: 'q', cfg: 'no-such-config', swaps: {}, ru: 5}]};
      const hostile = {...alike, cables: alike.cables.map((c, i) => ({...c, media: ['__proto__', 'constructor'][i]}))};
      return {hostile: (await X.drawioFile(hostile, of)).data, alike: (await X.drawioFile(alike, of)).data, bare: (await X.drawioFile(bare, of)).data};
    }""")
    try:
        d = drawio_page(out["alike"])
    except ET.ParseError as e:
        return bad + [f"draw.io ids: not well-formed ({e})"]
    dup = [i for i, c in Counter(d["ids"]).items() if c > 1]
    if dup:
        bad.append(f"draw.io ids: duplicate cell ids {dup[:5]}")
    tree = ET.fromstring(out["alike"])
    owner = {m.get("id"): m.get("value") for m in tree.iter("mxCell")}
    parent = {o.get("id"): o.find("mxCell").get("parent") for o in tree.iter("object")}
    ends = {e.get("portrayal-cable"): (e.find("mxCell").get("source"), e.find("mxCell").get("target")) for e in d["edges"]}
    if sorted(ends) != ["k1", "k2"] or any(i not in parent for e in ends.values() for i in e):
        bad.append(f"draw.io ids: edges {ends}")
    elif [owner[parent[ends[k][0]]] for k in ("k1", "k2")] != ["x1", "x2"]:
        # Each cable's port cell sits in its own device's group, whatever the ids slug to.
        bad.append(f"draw.io ids: the two cables are not bound to their own devices' port cells: {ends}")
    notes = out["alike"].partition("-->")[0] if "<!--" in out["alike"] else ""
    if "a-b-2" in notes or "@rear" in notes or "a-b-3" in notes:
        bad.append("draw.io ids: an alias is in the notes a person reads")

    colors = page.evaluate("async () => (await import('/site/rack/cables.js')).COLORS")
    strokes = [o.find("mxCell").get("style").rsplit("strokeColor=", 1)[1] for o in ET.fromstring(out["hostile"]).iter("object") if o.get("portrayal-cable")]
    if strokes != [f"{colors['unset']};"] * 2 or "[object" in out["hostile"] or "function" in out["hostile"].lower().replace("functions", ""):
        bad.append(f"draw.io ids: a media named __proto__ or constructor is styled {strokes}")

    def nones(text):
        return {(o.get("id"), o.get("value"), o.get("parent")) for o in ET.fromstring(text).iter("mxCell")
                if (o.get("id") or "").endswith("-none")}
    if nones(out["bare"]) != {("q-g0r0-front-none", "no front drawing", "g0r0-front"),
                              ("q-rear-g0r1-front-none", "no rear drawing", "g0r1-front")}:
        bad.append(f"draw.io ids: the dashed boxes read {nones(out['bare'])}")
    return bad


@extra("rack.html: Export - the BOM lists cables by media, length and connector, never a plug, and no longer says cables are left out")
def check_rack_export_bom_cables(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"BOM cables: {e}"]
    cols, rows, text = read_csv(export_file(page, "bom"))
    status = export_status(page)
    cables = [(r["qty"], r["manufacturer"], r["model"], r["description"], r["ref"]) for r in rows if r["section"] == "Cables"]
    # c2 and c3 have no entered length, so the page measures one along their routes and the BOM marks it.
    # (c2, front to rear, measures 1.503 m on kit 0.15.0, 3 mm over the 1.5 m
    # stock break: each RJ45 plug's reach and the free spans' hang, portrayal-site#166)
    want = [("1", "", "Cat 6A copper", "2 m (routed); copper at both ends", ""),
            ("1", "", "OS2 single-mode fiber", "2 m (routed); copper at one end", ""),
            ("1", "", "OS2 single-mode fiber", "2 m; fiber at both ends", "")]
    if cables != want:
        bad.append(f"BOM cables: the Cables section is {cables}")
    if [r["section"] for r in rows][-3:] != ["Cables"] * 3:
        bad.append(f"BOM cables: the cables are not the last section: {[r['section'] for r in rows]}")
    if any(r["section"] == "Plugs" or "plug" in r["ref"] for r in rows):
        bad.append("BOM cables: a derived plug is listed as a part")
    notes = text.partition("\r\nNotes\r\n")[2]
    if "not in this export yet" in notes:
        bad.append(f"BOM cables: the notes still say cables are left out: {notes!r}")
    n = len([l for l in notes.split("\r\n") if l])
    if status != notes_status(n):
        bad.append(f"BOM cables: {n} notes in the file, but the status reads {status!r}")

    # A rack with no cables has no Cables section, and its BOM is what it was.
    open_fixture(page, base)
    _, rows, text = read_csv(export_file(page, "bom"))
    if any(r["section"] == "Cables" for r in rows) or "cable" in text.partition("\r\nNotes\r\n")[2].lower():
        bad.append("BOM cables: a rack with no cables has a Cables row or a cable note")
    # Zero-U items are still said to be left out; only the cable line is retired.
    kept = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      const r = window.__rack.doc().racks[0];
      return (await X.bomCsv({...r, zeroU: [{}]}, of)).notes;
    }""")
    if "1 zero-U item is not in this export yet." not in kept:
        bad.append(f"BOM cables: the zero-U note is gone: {kept}")
    return bad


# THE SHEET AS PHASE 1B BUILT IT, kept here as the reference a rack with no
# cables is pinned to: the same faces, title block and notes, laid out by the
# arithmetic exports.js had before cables. For each set of faces it returns
# whether today's sheetSvg gives the same bytes, and where they first differ.
SHEET_1B_JS = """async ([y, m, d]) => {
  const X = await import('/site/rack/exports.js'), E = await import('/site/rack/elevation.js'),
        D = await import('/vendor/rack/export-data.js'), F = await import('/vendor/rack/fit.js'),
        R = await import('/vendor/rack/rails.js'), C = await import('/vendor/rack/catalog.js'),
        V = await import('/site/svg-export.js'), U = await import('/site/rack/dom.js'),
        L = await import('/vendor/rack/model.js');
  const chassisOf = (await C.loadCatalog('/assets/dist/')).chassisOf;
  const rack = window.__rack.doc().racks[0], date = new Date(y, m, d);
  const FACE_W = R.OPENING + R.RAIL_W * 2 + 12, M = 24, GAP = 48, HEAD = 28, LINE = 16, NOTE_LINE = 13;
  const INK = '#1D2125', MUTED = '#5B636B', PAPER = '#FFFFFF', RULE = '#B9BFC6';
  const text = (x, y, s, {size = 11, weight = 400, fill = INK, mono = false} = {}) => {
    const t = U.svgEl('text', {x, y, 'font-size': size, 'font-weight': weight, fill,
      'font-family': mono ? 'IBM Plex Mono, ui-monospace, monospace' : 'Archivo, system-ui, sans-serif'});
    t.textContent = s;
    return t;
  };
  async function before(faces) {
    const items = F.itemsWithU(rack, chassisOf);
    const notes = [...D.rackNotes(rack, {cables: false}), ...D.mountNotes(items, chassisOf, rack.frame)];
    for (const it of items) for (const pane of faces) {
      const panel = E.panelFor(it, pane);
      notes.push(...D.faceNotes({label: it.label, u: L.uLabel(rack.frame, it.ru), pane, panel,
                                 face: await X.faceOf(it, panel)}));
    }
    const all = D.uniq(notes);
    const panes = await Promise.all(faces.map(view =>
      E.drawElevation({items, frame: rack.frame, view, ears: true, metal: true, paper: true})));
    const faceH = rack.frame.heightRU * R.RU + 30;
    const width = M * 2 + faces.length * FACE_W + (faces.length - 1) * GAP;
    const chars = Math.floor((width - M * 2 - 24) / 6.2);
    const noteLines = all.flatMap(n => D.wrapText(n, chars - 2).map((l, i) => (i ? `  ${l}` : `• ${l}`)));
    const sheet = U.svgEl('svg', {xmlns: 'http://www.w3.org/2000/svg'});
    const paper = U.svgEl('rect', {x: 0, y: 0, fill: PAPER});
    sheet.append(paper);
    panes.forEach((pane, i) => {
      const x = M + i * (FACE_W + GAP);
      sheet.append(text(x, M + 16, faces[i] === 'front' ? 'Front' : 'Rear', {size: 14, weight: 600}));
      pane.setAttribute('x', x.toFixed(2));
      pane.setAttribute('y', String(M + HEAD));
      pane.setAttribute('width', FACE_W.toFixed(2));
      pane.setAttribute('height', faceH.toFixed(2));
      sheet.append(pane);
    });
    const blockY = M + HEAD + faceH + 24;
    const box = U.svgEl('rect', {x: M, y: blockY, width: (width - 2 * M).toFixed(2), fill: 'none', stroke: RULE});
    sheet.append(box);
    let yy = blockY + 22;
    // the Rack Builder's own name for itself: the kit's default since #895 upstream is 'Portrayal'
    D.titleLines(rack, date, {source: 'the Portrayal Rack Builder'}).forEach((line, i) => {
      sheet.append(text(M + 12, yy, line, i ? {fill: MUTED} : {size: 14, weight: 600}));
      yy += LINE;
    });
    if (noteLines.length) {
      yy += 6;
      sheet.append(text(M + 12, yy, 'Notes', {weight: 600}));
      for (const l of noteLines) { yy += NOTE_LINE; sheet.append(text(M + 12, yy, l, {size: 10, fill: MUTED, mono: true})); }
    }
    const blockH = yy - blockY + 12;
    box.setAttribute('height', blockH.toFixed(2));
    const height = blockY + blockH + M;
    for (const [k, v] of [['width', width], ['height', height]]) {
      sheet.setAttribute(k, v.toFixed(2));
      paper.setAttribute(k, v.toFixed(2));
    }
    sheet.setAttribute('viewBox', `0 0 ${width.toFixed(2)} ${height.toFixed(2)}`);
    const host = document.createElement('div');
    host.style.cssText = 'position:fixed;left:0;top:0;width:800px;visibility:hidden;pointer-events:none';
    document.body.append(host);
    try { host.append(sheet); return V.standalone(sheet); }
    finally { host.remove(); }
  }
  const out = {};
  for (const faces of [['front', 'rear'], ['front'], ['rear']]) {
    const was = await before(faces), now = (await X.sheetSvg(rack, chassisOf, {faces, date})).data;
    let at = 0;
    while (at < was.length && was[at] === now[at]) at++;
    out[faces.join('+')] = {same: was === now, bytes: was.length,
                            ...(was === now ? {} : {was: was.slice(Math.max(0, at - 60), at + 120),
                                                    now: now.slice(Math.max(0, at - 60), at + 120)})};
  }
  return out;
}"""


@extra("rack.html: Export - a rack with no cables gets the sheet it got before cables, byte for byte")
def check_rack_export_sheet_pinned(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    notes_fixture = json.loads(json.dumps(EXPORT_FIXTURE))
    notes_fixture["id"] = "doc-export-pin"
    notes_fixture["racks"][0]["name"] = "Export pin"
    notes_fixture["racks"][0]["zeroU"] = [{"id": "z1"}]
    notes_fixture["racks"][0]["items"].append(
        {"id": "i5", "ref": "no-such-device", "cfg": "base", "label": "mystery", "ru": 22, "face": "front",
         "turned": False, "swaps": {}, "fields": {}})
    # A desktop device: the sheet's notes must say it is not rack-mount, and the pin must hold that line too.
    notes_fixture["racks"][0]["items"].append(
        {"id": "i6", "ref": "hlx-tgv", "cfg": "base", "label": "desk", "ru": 8, "face": "front",
         "turned": False, "swaps": {}, "fields": {}})
    for name, fixture in (("the export fixture", EXPORT_FIXTURE), ("a rack with notes", notes_fixture),
                          ("an empty rack", EMPTY_FIXTURE)):
        open_fixture(page, base, fixture)
        got = page.evaluate(SHEET_1B_JS, [2026, 0, 2])
        for faces, r in got.items():
            if r["bytes"] < 2000:
                bad.append(f"sheet pin ({name}, {faces}): the reference sheet is only {r['bytes']} bytes")
            if not r["same"]:
                bad.append(f"sheet pin ({name}, {faces}): the sheet changed for a rack with no cables: "
                           f"was {r['was']!r}, now {r['now']!r}")
    return bad


# An exported sheet, measured: parsed, attached where it can be laid out, and
# each nested pane read - its box on the sheet, its viewBox, and every stroke,
# plug outline and tag of its cable layers that reaches outside that viewBox
# (a nested <svg> clips what is past its box). Also where the title block starts.
SHEET_PANES_JS = """(text) => {
  const host = document.createElement('div');
  host.style.cssText = 'position:fixed;left:0;top:0;visibility:hidden;pointer-events:none';
  host.innerHTML = text.replace(/^<\\?xml[^>]*>\\s*/, '');
  document.body.append(host);
  try {
    const sheet = host.querySelector('svg');
    const num = (n, k) => parseFloat(n.getAttribute(k));
    const panes = [...sheet.querySelectorAll(':scope > svg[data-pane]')].map(svg => {
      const vb = svg.getAttribute('viewBox').split(/\\s+/).map(Number);
      const nodes = [...svg.querySelectorAll('[data-cables] path, [data-cables] rect, [data-cable-tags] rect, [data-cable-tags] text')];
      const out = nodes.map(n => [n, n.getBBox()]).filter(([, b]) =>
        b.x < vb[0] - 0.01 || b.y < vb[1] - 0.01 || b.x + b.width > vb[0] + vb[2] + 0.01 || b.y + b.height > vb[1] + vb[3] + 0.01)
        .map(([n, b]) => `${n.closest('[data-cable-id]')?.dataset.cableId} ${n.tagName} to y ${Math.round(b.y + b.height)} of ${Math.round(vb[1] + vb[3])}`);
      return {pane: svg.dataset.pane, x: num(svg, 'x'), y: num(svg, 'y'), w: num(svg, 'width'), h: num(svg, 'height'),
              vb, nodes: nodes.length, out,
              // Routed cables: a path whose box ends in a gutter band (26-66 mm outside either rail).
              gutter: [...svg.querySelectorAll('[data-cables] path')].map(n => [n, n.getBBox()])
                .filter(([, b]) => (b.x <= -26 && b.x >= -66) || (b.x + b.width >= 476.85 && b.x + b.width <= 516.85))
                .map(([n]) => n.closest('[data-cable-id]')?.dataset.cableId)};
    });
    const block = [...sheet.querySelectorAll(':scope > rect')].find(r => r.getAttribute('fill') === 'none');
    return {width: num(sheet, 'width'), height: num(sheet, 'height'), blockY: num(block, 'y'), panes};
  } finally { host.remove(); }
}"""


@extra("rack.html: Export - the sheet draws the cables as the page does: plugs, tags that survive on paper, loose leads, and notes; one face carries its own")
def check_rack_export_sheet_cables(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"sheet cables: {e}"]
    ns = "{http://www.w3.org/2000/svg}"

    def cables_of(text):
        # {pane: {"cables": [ids, in file order], "tags": {id: text}}}
        root = ET.fromstring(text.encode("utf-8"))
        out = {}
        for pane in root.findall(f"{ns}svg"):
            layer = next((g for g in pane.findall(f"{ns}g") if g.get("data-cables")), None)
            tags = next((g for g in pane.findall(f"{ns}g") if g.get("data-cable-tags")), None)
            out[pane.get("data-pane")] = {
                "cables": sorted(g.get("data-cable-id") for g in (layer if layer is not None else [])),
                "tags": {g.get("data-cable-id"): g.find(f"{ns}text").text for g in (tags if tags is not None else [])},
                "tag_nodes": list(tags) if tags is not None else []}
        return out

    dl = export_file(page, "sheet-svg")
    status = export_status(page)
    text = pathlib.Path(dl.path()).read_text(encoding="utf-8")
    if dl.suggested_filename != "Cable-test-sheet.svg":
        bad.append(f"sheet cables: named {dl.suggested_filename!r}")
    got = cables_of(text)
    want = {"front": (["c1", "c2"], {"c2": "→ demarc port 2 1"}),
            "rear": (["c2", "c3"], {"c2": "→ leaf-1 mgmt eth", "c3": "✕ not connected"})}
    for pane, (ids, tags) in want.items():
        g = got.get(pane, {"cables": None, "tags": None})
        if g["cables"] != ids or g["tags"] != tags:
            bad.append(f"sheet cables: the {pane} pane draws {g['cables']} with tags {g['tags']}, expected {ids} and {tags}")
    # The derived plugs are drawn (an LC plug in each bore of both optics, an RJ45 plug in each jack).
    for ref, n in (("generic/lc-plug@2", 4), ("generic/rj45-plug@1", 3)):
        if text.count(f'data-ref="{ref}') != n:
            bad.append(f"sheet cables: {text.count(f'data-ref="{ref}')} {ref} drawn, expected {n}")
    # A tag is drawing, not a control: fixed ink of its own, nothing of the screen's.
    for pane in got.values():
        for tag in pane["tag_nodes"]:
            rect, label = tag.find(f"{ns}rect"), tag.find(f"{ns}text")
            if (rect.get("fill"), label.get("fill"), label.get("font-size")) != ("#FFFFFF", "#1D2125", "11") \
                    or not rect.get("stroke") or any(tag.get(k) for k in ("class", "tabindex", "role", "style")):
                bad.append(f"sheet cables: a tag is not fixed ink on paper: {ET.tostring(tag, encoding='unicode')[:200]}")
    loose = [t for p in got.values() for t in p["tag_nodes"] if t.get("data-not-connected")]
    if len(loose) != 1 or loose[0].find(f"{ns}rect").get("stroke-dasharray") != "3 2":
        bad.append("sheet cables: the not-connected tag is not dashed, or there is not exactly one")
    for ui_bit in ("tabindex", "data-pt-ui", 'class="cable-tag', 'role="button"', "var(--pt-", "rk-end-pick",
                   "data-base-box", "cable-focus", 'class="on"'):
        if ui_bit in text:
            bad.append(f"sheet cables: screen UI in the file ({ui_bit})")
    for note in ("Cable c3: end A, leaf-1 (U14) port-2, is not connected (port-2 holds no", "does not suit end B, which is copper."):
        if note not in text:
            bad.append(f"sheet cables: the notes block lacks {note!r}")
    if "not in this export yet" in text:
        bad.append("sheet cables: the sheet still says cables are not in it")
    if status != notes_status(2):
        bad.append(f"sheet cables: two notes in the file, but the status reads {status!r}")
    m = page.evaluate(SHEET_PANES_JS, text)
    # 24 + (514.85 + 68 + 520) + 48 + (514.85 + 68 + 520) + 24: the lane gutters (40 mm each side instead of 6) and,
    # the cables being routed, a column on both sides of each pane.
    if abs(m["width"] - 2301.70) > 0.01 or [p["w"] for p in m["panes"]] != [1102.85, 1102.85]:
        bad.append(f"sheet cables: the sheet is {m['width']} wide with panes {[p['w'] for p in m['panes']]}")
    # The page routes these cables, so the sheet draws the routed paths: some path reaches a gutter on each face.
    for p in m["panes"]:
        if not p["gutter"]:
            bad.append(f"sheet cables: the {p['pane']} pane has no routed path reaching its gutter")
    for p in m["panes"]:
        if p["out"] or not p["nodes"]:
            bad.append(f"sheet cables: the {p['pane']} pane clips {p['out']} (of {p['nodes']} nodes)")
        if abs(p["h"] - p["vb"][3]) > 0.01 or p["y"] + p["h"] > m["blockY"]:
            bad.append(f"sheet cables: the {p['pane']} pane is {p['h']} tall for a viewBox of {p['vb'][3]}, title block at {m['blockY']}")

    # One face alone carries that face's cables and tags.
    front = pathlib.Path(export_file(page, "front-svg").path()).read_text(encoding="utf-8")
    rear = pathlib.Path(export_file(page, "rear-svg").path()).read_text(encoding="utf-8")
    for name, t, pane in (("front", front, "front"), ("rear", rear, "rear")):
        g = cables_of(t)
        ids, tags = want[pane]
        if list(g) != [pane] or g[pane]["cables"] != ids or g[pane]["tags"] != tags:
            bad.append(f"sheet cables, {name} only: draws {[(k, v['cables'], v['tags']) for k, v in g.items()]}")
        mm = page.evaluate(SHEET_PANES_JS, t)
        if abs(mm["width"] - 1150.85) > 0.01 or mm["panes"][0]["out"]:
            bad.append(f"sheet cables, {name} only: {mm['width']} wide, clipping {mm['panes'][0]['out']}")

    # A cross-face cable's tag on a single face still names the far end.
    if cables_of(front)["front"]["tags"].get("c2") != "→ demarc port 2 1" or cables_of(rear)["rear"]["tags"].get("c2") != "→ leaf-1 mgmt eth":
        bad.append("sheet cables, one face: the cross-face cable's tag does not name its far end")
    # c3 hangs as a lead in the rear pane only, c1 runs in the front pane only: the other face's sheet says so.
    for name, t, note in (("front", front, "1 cable is on the rear face only and is not on this sheet."),
                          ("rear", rear, "1 cable is on the front face only and is not on this sheet.")):
        if note not in t:
            bad.append(f"sheet cables, {name} only: it does not say {note!r}")
    if "face only and" in text:
        bad.append("sheet cables: the two-face sheet says a cable is on one face only")

    # The PNG is that sheet at 2x.
    png = pathlib.Path(export_file(page, "sheet-png").path()).read_bytes()
    w = int.from_bytes(png[16:20], "big") if png[:8] == b"\x89PNG\r\n\x1a\n" else 0
    if w not in (4603, 4604):
        bad.append(f"sheet cables: the PNG is {w} px wide, expected the 2301.70 mm sheet at 2x")

    # The same ink in light and dark, cables and tags included.
    seen = {}
    for scheme in ("light", "dark"):
        page.emulate_media(color_scheme=scheme)
        seen[scheme] = page.evaluate("""async () => {
          const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
          const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
          return (await X.sheetSvg(window.__rack.doc().racks[0], of, {date: new Date(2026, 0, 2)})).data;
        }""")
    if seen["light"] != seen["dark"]:
        bad.append("sheet cables: the cabled sheet differs between light and dark")
    page.emulate_media(color_scheme="light")

    # A 42U rack cabled top to bottom, with a loose lead from its lowest device:
    # the panes grow together to hold the loop and the lead, and nothing is cut off.
    open_cabled(page, base, ROOM_FIXTURE)
    text = pathlib.Path(export_file(page, "sheet-svg").path()).read_text(encoding="utf-8")
    m = page.evaluate(SHEET_PANES_JS, text)
    base_h = 42 * 44.45 + 30
    hs = [p["h"] for p in m["panes"]]
    if len(hs) != 2 or hs[0] != hs[1] or hs[0] <= base_h + 40:
        bad.append(f"sheet cables, 42U: the panes are {hs} tall, expected one height past {base_h + 40}")
    for p in m["panes"]:
        if p["out"] or not p["nodes"]:
            bad.append(f"sheet cables, 42U: the {p['pane']} pane clips {p['out']} (of {p['nodes']} nodes)")
        if p["y"] + p["h"] > m["blockY"]:
            bad.append(f"sheet cables, 42U: the {p['pane']} pane runs into the title block")
    if "Cable c2: end B, a removed device's port-1, is not connected (the device was removed)." not in text:
        bad.append("sheet cables, 42U: the note for the cable to a removed device is missing")

    # A cable neither of whose ends lands has no lead to draw: the sheet says it
    # "is not drawn", as the GLB and draw.io do, on every sheet.
    def edit(rack):
        rack["cables"].append({"id": "c6", "a": {"item": "i2", "path": "port-3", "view": "front"},
                               "b": {"item": "i2", "path": "port-4", "view": "front"},
                               "media": "os2", "purpose": "uplink", "label": "", "route": []})
    open_cabled(page, base, cable_fixture("doc-sheet-undrawn", "Undrawn", edit))
    want = ("Cable c6 is not drawn: end A, leaf-1 (U14) port-3, is not connected (port-3 holds no optic); "
            "end B, leaf-1 (U14) port-4, is not connected (port-4 holds no optic).")
    for kind in ("sheet-svg", "front-svg", "rear-svg"):
        t = pathlib.Path(export_file(page, kind).path()).read_text(encoding="utf-8")
        # The notes block wraps: compare with the whitespace between its lines taken out.
        flat = re.sub(r"\s+", " ", " ".join(n.text or "" for n in ET.fromstring(t.encode("utf-8")).iter(f"{ns}text")))
        flat = flat.replace("• ", "")
        if want not in flat:
            bad.append(f"sheet cables, {kind}: a cable that lands nowhere is not called undrawn: {[l for l in flat.split('Cable ') if l.startswith('c6')]}")
        if any("c6" in p["cables"] or "c6" in p["tags"] for p in cables_of(t).values()):
            bad.append(f"sheet cables, {kind}: the cable that lands nowhere has a group on the sheet")
    return bad


@extra("rack.html: Export - draw.io draws each landed cable as an edge between port cells, across the two cabinets, in the page's colors; a loose end is a note")
def check_rack_export_drawio_cables(page, base):
    from collections import Counter
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"draw.io cables: {e}"]
    dl = export_file(page, "drawio")
    status = export_status(page)
    text = pathlib.Path(dl.path()).read_text(encoding="utf-8")
    try:
        d = drawio_page(text)
    except ET.ParseError as e:
        return bad + [f"draw.io cables: not well-formed XML ({e})"]
    if d["names"] != ["Cable test"] or sorted(d["cabinets"]) != ["g0r0-front", "g0r1-front"]:
        return bad + [f"draw.io cables: pages {d['names']}, cabinets {sorted(d['cabinets'])}"]
    dup = [i for i, c in Counter(d["ids"]).items() if c > 1]
    if dup:
        bad.append(f"draw.io cables: duplicate cell ids {dup[:5]}")
    colors = page.evaluate("async () => (await import('/site/rack/cables.js')).COLORS")
    style = "edgeStyle=orthogonalEdgeStyle;rounded=1;endArrow=none;startArrow=none;strokeWidth=2;fontSize=8;" \
            "labelBackgroundColor=#FFFFFF;fontColor=#15171a;strokeColor={};"
    got = {o.get("id"): {"label": o.get("label"), "cable": o.get("portrayal-cable"), "media": o.get("portrayal-media"),
                         "purpose": o.get("portrayal-purpose"), "length": o.get("portrayal-length"),
                         "source": o.find("mxCell").get("source"), "target": o.find("mxCell").get("target"),
                         "style": o.find("mxCell").get("style")} for o in d["edges"]}
    # THE LABEL STATES THE SPARE AFTER THE LENGTH (kit 0.22.0: "2 m, 1.01 m spare"); the length attribute stays
    # the length. The spare is the kit's (route.js spareOf, by the page's route context), to the centimetre.
    sp = page.evaluate("""async () => {
      const R = await import('/vendor/rack/route.js'), rack = window.__rack.doc().racks[0], ctx = window.__rack.routeContext();
      return Object.fromEntries(rack.cables.map(c => { const s = R.spareOf(rack, c, ctx); return [c.id, s ? `${Math.round(s.spare_m * 100) / 100} m` : null]; }));
    }""")
    if not all(sp.get(c) and re.fullmatch(r"0?[\d.]+ m", sp[c]) for c in ("c1", "c2")):
        return bad + [f"draw.io cables: the kit gives no spare for c1 and c2: {sp}"]
    want = {
        # Both ends in the front cabinet: a seated card's port is a cell like any other.
        "cable-c1": {"label": f"A1 · 2 m, {sp['c1']} spare", "cable": "c1", "media": "os2", "purpose": "uplink", "length": "2 m",
                     "source": "i2-g0r0-front-port-1", "target": "i1-g0r0-front-slot-2--module--p0",
                     "style": style.format(colors["os2"])},
        # Front cabinet to rear cabinet, one edge: the demarc's front panel is what the rear shows.
        # c2 measures 1.503 m on kit 0.15.0, 3 mm over the 1.5 m break (portrayal-site#166)
        "cable-c2": {"label": f"2 m, {sp['c2']} spare", "cable": "c2", "media": "cat6a", "purpose": "management", "length": "2 m",
                     "source": "i2-g0r0-front-mgmt-eth", "target": "i3-rear-g0r1-front-port-2-1",
                     "style": style.format(colors["cat6a"])}}
    if got != want:
        bad.append(f"draw.io cables: the edges are {got}")
    for e in got.values():
        for end in (e["source"], e["target"]):
            if end not in d["ids"]:
                bad.append(f"draw.io cables: an edge ends at {end!r}, which is no cell in the file")
    notes = text.partition("-->")[0]
    for note in ("Cable c3 is not drawn: end A, leaf-1 (U14) port-2, is not connected (port-2 holds no optic).",
                 "Cable c3: OS2 single-mode fiber does not suit end B, which is copper."):
        if note not in notes:
            bad.append(f"draw.io cables: the notes lack {note!r}")
    for bit in ("not in this export yet", "@rear", "names no mounted device", "is not a port in"):
        if bit in notes:
            bad.append(f"draw.io cables: the notes a person reads carry {bit!r}")
    if "Cable routes are not drawn in draw.io; the cables run straight between their ports there." not in notes:
        bad.append("draw.io cables: the notes do not say routes are not drawn")
    n = len([l for l in notes.splitlines() if l.startswith("- ")])
    if n != 5 or status != notes_status(n):
        bad.append(f"draw.io cables: {n} notes in the file, and the status reads {status!r}")

    # An end whose device is hidden in the cabinet that would show it: leaf-1
    # turned shows its ports to the rear, where the demarc at U14 covers it.
    # And a cable with no media takes the neutral color.
    odd = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
      const r = window.__rack.doc().racks[0];
      const hidden = await X.drawioFile({...r, items: r.items.map(i => (i.id === 'i2' ? {...i, turned: true} : i))}, of);
      const plain = await X.drawioFile({...r, cables: [{...r.cables[1], media: '', label: '<b>&"'}]}, of);
      const edge = new DOMParser().parseFromString(plain.data, 'application/xml').querySelector('object[portrayal-cable]');
      return {hidden: hidden.notes, hiddenEdges: (hidden.data.match(/portrayal-cable=/g) || []).length,
              style: edge?.querySelector('mxCell').getAttribute('style') || '', label: edge?.getAttribute('label'),
              media: edge?.getAttribute('portrayal-media')};
    }""")
    if "Cable A1 is not drawn: end A, leaf-1 (U14) port-1, is hidden behind demarc in the rear cabinet." not in odd["hidden"] \
            or odd["hiddenEdges"] != 0:
        bad.append(f"draw.io cables: a cable to a hidden device: {odd['hiddenEdges']} edges, notes {odd['hidden']}")
    if not odd["style"].endswith(f"strokeColor={colors['unset']};") or odd["media"] is not None:
        bad.append(f"draw.io cables: a cable with no media is styled {odd['style'][-30:]!r}, media {odd['media']!r}")
    if not re.fullmatch(r'<b>&" · 2 m, [\d.]+ m spare', odd["label"] or ""):
        bad.append(f"draw.io cables: a cable's label is not its own text: {odd['label']!r}")
    return bad


# What the 3D scene holds of the rack's cables: each tube's cable id, group
# name, color, the sides that did not land, and which device (by its place in
# rack.items) each drawn end is nearest - so two devices of one model are told
# apart. Plus the cable groups in the scene graph and each mount's overrides.
CABLES_3D_JS = """() => {
  const s = window.__rack.scene(), rc = s.rackCables;
  if (!rc || rc.failed) return {rc: rc ? 'failed' : null, groups: [], overrides: s.resolved().stack.map(e => e.overrides)};
  const boxes = s.deviceBoxes();
  const nearest = p => boxes.map((b, k) => [b.box.distanceToPoint(p), k]).sort((a, b) => a[0] - b[0])[0];
  const group = s.three.scene.getObjectByName('patch-cables');
  return {
    rc: 'drawn', checked: rc.checked,
    groups: group ? group.children.map(g => g.name) : [],
    tubes: rc.tubes.map(t => ({
      id: t.link.id, loose: t.loose, dangling: !!t.dangling, name: t.mesh ? t.mesh.name : null,
      color: t.mesh ? '#' + t.mesh.children[0].material.color.getHexString() : null,
      // An unplugged lead has one end on a device; its other end hangs free.
      ends: (t.dangling ? t.points.slice(0, 1) : t.points.length ? [t.points[0], t.points.at(-1)] : [])
        .map(p => { const [d, k] = nearest(p); return {item: k, mm: Math.round(d)}; })})),
    anchors: rc.anchors.map(a => `${a.i}:${a.side}:${a.anchor.path}`),
    overrides: s.resolved().stack.map(e => e.overrides)};
}"""


@extra("rack.html: 3D hangs the rack's cables as tubes between the right devices, with their plugs seated; a loose end dangles; a rack with no cables is untouched")
def check_rack_cables_3d_scene(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    # The cable fixture, and a fourth cable to a port that takes no plug (the
    # switch's USB port): in 2D it ends at the port's center, and so it must in 3D.
    fixture = cable_fixture("doc-cable-3d", "Cable 3D", lambda r: r["cables"].append(
        {"id": "c4", "a": {"item": "i2", "path": "usb", "view": "front"},
         "b": {"item": "i3", "path": "port-2-2", "view": "front"}, "media": "", "purpose": "", "label": "", "route": []}))
    try:
        open_cabled(page, base, fixture)
    except RuntimeError as e:
        return bad + [f"3D cables: {e}"]
    if webgl_trouble(page):
        print("[check_rack_cables_3d_scene] WebGL unavailable - not exercised")
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D cables: the scene")
    got = page.evaluate(CABLES_3D_JS)
    if got["rc"] != "drawn" or not got.get("checked"):
        return bad + [f"3D cables: the scene's cables are {got['rc']!r}"]
    colors = page.evaluate("async () => (await import('/site/rack/cables.js')).COLORS")
    if got["groups"] != ["cable-c1", "cable-c2", "cable-c3", "cable-c4"]:
        bad.append(f"3D cables: the scene's cable groups are {got['groups']}")
    tubes = {t["id"]: t for t in got["tubes"]}
    # rack.items order: 0 core-1, 1 leaf-1, 2 demarc at U14, 3 demarc at U20.
    want = {"c1": ([], False, colors["os2"], [1, 0]),          # leaf-1 to core-1
            "c2": ([], False, colors["cat6a"], [1, 2]),        # leaf-1 to the demarc at U14, not its twin
            "c3": (["from"], True, colors["os2"], [3]),        # the empty cage is loose: a lead hangs from the demarc at U20
            "c4": ([], False, colors["unset"], [1, 2])}        # no plug at the USB port, and it still lands
    for cid, (loose, dangling, color, items) in want.items():
        t = tubes.get(cid)
        if not t:
            bad.append(f"3D cables: no tube for {cid}")
            continue
        if (t["loose"], t["dangling"], t["color"], t["name"]) != (loose, dangling, color, f"cable-{cid}"):
            bad.append(f"3D cables: {cid} is {t}")
        if [e["item"] for e in t["ends"]] != items or any(e["mm"] > 120 for e in t["ends"]):
            bad.append(f"3D cables: {cid} runs between items {t['ends']}, expected {items}")
    # Each landed end is on a seated connector: an LC plug in each bore of an optic, an RJ45 plug in a jack.
    # An end with no connector seated is anchored on the port itself.
    for a in ("0:from:port-1-occupant/tx-occupant", "0:to:slot-2/module/p0-occupant/rx-occupant",
              "1:from:mgmt-eth-occupant", "1:to:port-2-1-occupant", "2:to:port-2-1-occupant",
              "3:from:usb", "3:to:port-2-2-occupant"):
        if a not in got["anchors"]:
            bad.append(f"3D cables: no anchor {a} among {got['anchors']}")
    if any(a.startswith("2:from:") for a in got["anchors"]):
        bad.append("3D cables: the empty cage's end was anchored")
    # The plugs are in the scene's overrides, over the items' own swaps, and not in the document.
    if got["overrides"][2] != {"port-2-1": "generic/rj45-plug@1", "port-2-2": "generic/rj45-plug@1"} or \
            got["overrides"][1].get("port-1") != "generic/qsfp-lc@2" or \
            got["overrides"][1].get("port-1-occupant/tx") != "generic/lc-plug@2":
        bad.append(f"3D cables: the mounts' overrides are {got['overrides']}")
    swaps = page.evaluate("() => window.__rack.doc().racks[0].items.map(i => i.swaps)")
    if swaps != [i["swaps"] for i in CABLE_FIXTURE["racks"][0]["items"]]:
        bad.append(f"3D cables: plugs were written into item.swaps: {swaps}")

    # No cables: nothing is added to the scene, and the mounts' overrides are the items' swaps.
    page.click('#mode [data-mode="2d"]')
    open_fixture(page, base)
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D cables: the scene of a rack with no cables")
    got = page.evaluate(CABLES_3D_JS)
    if got["rc"] is not None or got["groups"] or \
            got["overrides"] != [i["swaps"] for i in EXPORT_FIXTURE["racks"][0]["items"]]:
        bad.append(f"3D cables: a rack with no cables has {got}")
    if page.evaluate("() => !!window.__rack.scene().three.scene.getObjectByName('patch-cables')"):
        bad.append("3D cables: a rack with no cables has a cable group in its scene")
    page.click('#mode [data-mode="2d"]')
    return bad


@extra("rack.html: Export - the GLB and USDZ carry the cables the scene holds, each named for its cable; the GLB's notes list loose ends and mismatches")
def check_rack_export_3d_cables(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"3D export cables: {e}"]

    # The notes, with scenes that export nothing: only what modelFile says is under test.
    got = page.evaluate("""async () => {
      const X = await import('/site/rack/exports.js'), E = await import('/vendor/rack/export-data.js');
      const r = window.__rack.doc().racks[0];
      const scene = hung => ({running: () => false, complete: async () => {}, three: {scene: {userData: {}}},
                              toGLB: async () => new Uint8Array(4), toUSDZ: async () => new Uint8Array(4), rackCables: hung});
      const link = id => ({id});
      // As the scene hangs this rack: c1 and c2 land, c3 dangles from its B end.
      const hung = {tubes: [{link: link('c1'), loose: [], mesh: {}}, {link: link('c2'), loose: [], mesh: {}},
                            {link: link('c3'), loose: ['from'], mesh: {}}]};
      // The scene could not place c1's B end, and neither end of c2.
      const lost = {tubes: [{link: link('c1'), loose: ['to'], mesh: {}}, {link: link('c2'), loose: ['from', 'to'], mesh: null},
                            {link: link('c3'), loose: ['from'], mesh: {}}]};
      const out = {};
      // The scene was built without its faces (checked: false): no plugs, no loose ends marked.
      const unchecked = {...hung, checked: false};
      // c3 hangs from neither end: absent from the model.
      const gone = {tubes: [hung.tubes[0], hung.tubes[1], {link: link('c3'), loose: ['from', 'to'], mesh: null}]};
      for (const [k, s] of [['hung', scene(hung)], ['lost', scene(lost)], ['unchecked', scene(unchecked)], ['gone', scene(gone)], ['none', scene(null)], ['failed', scene({failed: true})]])
        out[k] = (await X.modelFile(s, r, 'glb')).notes;
      const usdz = await X.modelFile(scene(hung), r, 'usdz');
      out.usdz = {notes: usdz.notes, left: usdz.left, status: E.exportStatus(usdz)};
      out.plain = (await X.modelFile(scene(null), {...r, cables: []}, 'glb')).notes;
      return out;
    }""")
    loose = "Cable c3: end A, leaf-1 (U14) port-2, is not connected (port-2 holds no optic)."
    mism = "Cable c3: OS2 single-mode fiber does not suit end B, which is copper."
    if got["hung"] != [loose, mism]:
        bad.append(f"3D export cables: the notes are {got['hung']}")
    for want in ("Cable A1: end B, core-1 (U2) slot-2/module/p0, could not be placed in the 3D model, so the cable hangs loose there.",
                 "Cable c2: end A, leaf-1 (U14) mgmt-eth, and end B, demarc (U14) port-2-1, could not be placed in the 3D model, "
                 "so the cable is not drawn there."):
        if want not in got["lost"]:
            bad.append(f"3D export cables: an end the scene could not place is not noted ({want!r}): {got['lost']}")
    if len(got["lost"]) != 4:
        bad.append(f"3D export cables: a loose end the page already explains is noted twice: {got['lost']}")
    unchecked_note = "Cable ends could not be checked, so loose ends are not marked."
    if unchecked_note not in got["unchecked"] or any("is not connected" in n for n in got["unchecked"]):
        bad.append(f"3D export cables: a scene built unchecked says {got['unchecked']}")
    want = "Cable c3 is not drawn: end A, leaf-1 (U14) port-2, is not connected (port-2 holds no optic)."
    if want not in got["gone"] or loose in got["gone"]:
        bad.append(f"3D export cables: a cable absent from the model does not say so: {got['gone']}")
    for k in ("none", "failed"):
        if got[k] != ["The cables could not be drawn in the 3D model."]:
            bad.append(f"3D export cables: a scene with no cables hung ({k}) says {got[k]}")
    if got["plain"]:
        bad.append(f"3D export cables: a rack with no cables has notes {got['plain']}")
    if got["usdz"]["notes"] or got["usdz"]["left"] != [loose, mism] or \
            got["usdz"]["status"] != "Downloaded. USDZ carries no notes; the GLB does.":
        bad.append(f"3D export cables: the USDZ's notes are {got['usdz']}")
    if any("not in this export yet" in n for k in ("hung", "lost", "none", "failed") for n in got[k]):
        bad.append("3D export cables: the model still says cables are not in it")

    if webgl_trouble(page):
        print("[check_rack_export_3d_cables] WebGL unavailable - the files were not exercised")
        return bad
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D export cables: the scene")
    dl = export_file(page, "glb", timeout=READY_3D_MS)
    status = export_status(page)
    glb = pathlib.Path(dl.path()).read_bytes()
    if dl.suggested_filename != "Cable-test.glb" or glb[:4] != b"glTF":
        return bad + [f"3D export cables: {dl.suggested_filename!r} is not a GLB"]
    # A GLB is a JSON chunk, then a binary one: the node names and the scene's extras are in the JSON.
    doc = json.loads(glb[20:20 + int.from_bytes(glb[12:16], "little")].decode("utf-8"))
    names = [n.get("name") for n in doc["nodes"]]
    for want in ("patch-cables", "cable-c1", "cable-c2", "cable-c3", "device-i1", "device-i4"):
        if names.count(want) != 1:
            bad.append(f"3D export cables: the GLB has {names.count(want)} nodes named {want!r}")
    notes = doc["scenes"][0].get("extras", {}).get("portrayal", {}).get("notes", [])
    if notes != [loose, mism]:
        bad.append(f"3D export cables: the GLB's notes are {notes}")
    if status != notes_status(2):
        bad.append(f"3D export cables: the GLB's status reads {status!r}")
    # The cables are geometry in the GLB: each cable group has mesh children.
    by_name = {n.get("name"): n for n in doc["nodes"]}
    for cid in ("c1", "c2", "c3"):
        kids = by_name.get(f"cable-{cid}", {}).get("children", [])
        if not kids or any("mesh" not in doc["nodes"][k] for k in kids):
            bad.append(f"3D export cables: cable-{cid} has no tube in the GLB")

    dl = export_file(page, "usdz", timeout=READY_3D_MS)
    status = export_status(page)
    usdz = pathlib.Path(dl.path()).read_bytes()
    if dl.suggested_filename != "Cable-test.usdz" or usdz[:2] != b"PK":
        bad.append(f"3D export cables: {dl.suggested_filename!r} is not a USDZ")
    if status != "Downloaded. USDZ carries no notes; the GLB does.":
        bad.append(f"3D export cables: the USDZ's status reads {status!r}")
    page.click('#mode [data-mode="2d"]')

    # The scene's own read of the faces fails (the page's does not): 3D says so
    # once, and the GLB's notes say the ends were not checked, with no
    # "not connected" finding the model would contradict.
    page.evaluate("() => window.__rack.failSceneFacts(true)")
    page.click('#mode [data-mode="3d"]')
    settle_scene(page, "3D export cables: the unchecked scene")
    wait_fn(page, "3D export cables: the 3D notice",
            "() => (document.querySelector('.rk-side .rk-notice')?.textContent || '').includes('could not be checked')")
    if page.evaluate("() => window.__rack.scene().rackCables.checked") is not False:
        bad.append("3D export cables: a scene whose read failed is called checked")
    dl = export_file(page, "glb", timeout=READY_3D_MS)
    glb = pathlib.Path(dl.path()).read_bytes()
    doc = json.loads(glb[20:20 + int.from_bytes(glb[12:16], "little")].decode("utf-8"))
    notes = doc["scenes"][0].get("extras", {}).get("portrayal", {}).get("notes", [])
    if unchecked_note not in notes or any("is not connected" in n for n in notes):
        bad.append(f"3D export cables: the GLB of an unchecked scene has notes {notes}")
    # A second build is unchecked too, and does not say it again.
    old = page.evaluate_handle("() => window.__rack.scene()")
    page.evaluate("() => { const r = window.__rack.doc().racks[0]; window.__rack.replaceRack({...r, cables: r.cables.map((c, k) => (k ? c : {...c, media: 'om4'}))}); }")
    page.wait_for_function("s => { const n = window.__rack.scene(); return !!n && n !== s; }", arg=old, timeout=READY_3D_MS)
    settle_scene(page, "3D export cables: the rebuilt scene")
    # The rebuild says neither the unchecked notice again nor a bend flag (the
    # scene's to keep, portrayal-site#164), and every flag it keeps is true
    # (bend_flags_true).
    again = page.evaluate("() => document.querySelector('.rk-side .rk-notice')?.textContent || ''")
    if "could not be checked" in again:
        bad.append(f"3D export cables: the unchecked notice is shown again on a rebuild: {again!r}")
    if BEND_FLAG_RE.search(again):
        bad.append(f"3D export cables: the rebuild's notice says a bend flag: {again!r}")
    bad += [f"3D export cables: {b}" for b in bend_flags_true(page)]
    page.evaluate("() => window.__rack.failSceneFacts(false)")
    page.click('#mode [data-mode="2d"]')
    return bad


# A TOP-DOWN RACK WITH A TALL DEVICE: core-1 is 10U from stored U2, so on a
# 24U frame counted from the top it covers U14-U23. Its position - the U every
# file and the page name it with - is 14. c4 runs from an empty cage on its
# card to an empty cage on leaf-1, so every drawn export has a note naming it.
def one_u_fixture():
    def edit(rack):
        rack["frame"]["numbering"] = "top-down"
        rack["cables"].append({"id": "c4", "a": {"item": "i1", "path": "slot-2/module/p1", "view": "front"},
                               "b": {"item": "i2", "path": "port-3", "view": "front"},
                               "media": "os2", "purpose": "uplink", "label": "", "route": []})
    return cable_fixture("doc-one-u", "One U", edit)


# modelFile's notes for a rack, from a scene that exports nothing: every cable hung, none lost.
STUB_GLB_NOTES_JS = """async () => {
  const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
  const of = (await C.loadCatalog('/assets/dist/')).chassisOf;
  const r = window.__rack.doc().racks[0];
  const scene = {running: () => false, complete: async () => {}, three: {scene: {userData: {}}},
                 toGLB: async () => new Uint8Array(4), toUSDZ: async () => new Uint8Array(4),
                 rackCables: {tubes: r.cables.map(c => ({link: {id: c.id}, loose: [], mesh: {}}))}};
  return (await X.modelFile(scene, r, 'glb', of)).notes;
}"""


@extra("rack.html: one U per device - on a top-down frame a tall device has the same U in the sheet, draw.io, the GLB's notes, the schedule, the device import and the page")
def check_rack_one_u(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base, one_u_fixture())
    except RuntimeError as e:
        return bad + [f"one U: {e}"]
    # The device import's position is the reference: a DCIM's own word for it.
    pos = {r["name"]: nautobot_u(r) for r in device_rows(page)}
    if pos.get("core-1") != "14" or pos.get("leaf-1") != "11":
        return bad + [f"one U: the device import's positions are {pos}"]
    end = "core-1 (U14) slot-2/module/p1"
    old = "core-1 (U23)"

    _, rows, _ = read_csv(export_file(page, "cables"))
    us = {(r[f"{s}_device"], r[f"{s}_u"]) for r in rows for s in ("a", "b") if r[f"{s}_device"]}
    wrong = sorted((d, u) for d, u in us if pos.get(d) != u)
    if wrong or ("core-1", "14") not in us:
        bad.append(f"one U: the schedule's a_u/b_u differ from the device import's positions: {wrong or sorted(us)}")

    for kind in ("sheet-svg", "drawio"):
        text = html.unescape(pathlib.Path(export_file(page, kind).path()).read_text(encoding="utf-8"))
        if end not in text or old in text:
            bad.append(f"one U: the {kind} notes do not name core-1 at U14 ({'U23 is in the file' if old in text else 'no such note'})")
        if kind == "sheet-svg" and "leaf-1 (U11) port-1 → core-1 (U14) slot-2/module/p0" not in text:
            bad.append("one U: the sheet's title for c1 does not name both ends by position")
    notes = page.evaluate(STUB_GLB_NOTES_JS)
    if not any(end in n for n in notes) or any(old in n for n in notes):
        bad.append(f"one U: the GLB's notes are {notes}")

    # The page: the cable list's rows, the cable form's ends, a refusal, the inspector.
    row = page.inner_text("#cableRow-c4")
    if not row.startswith(f"{end} → leaf-1 (U11) port-3"):
        bad.append(f"one U: the cable list's row for c4 reads {row!r}")
    row = page.inner_text("#cableRow-c1")
    if row != "leaf-1 (U11) port-1 → core-1 (U14) slot-2/module/p0":
        bad.append(f"one U: the cable list's row for c1 reads {row!r}")
    page.click("#cableRow-c4")
    wait_sel(page, "one U: the selected row's Edit", "#cableEdit")
    page.click("#cableEdit")
    wait_fn(page, "one U: the cable form", "() => !!document.querySelector('#side form, #cableForm')")
    form = page.inner_text("#side")
    if end not in form or old in form:
        bad.append(f"one U: the cable form names its ends {form[:200]!r}")
    page.keyboard.press("Escape")
    select_item(page, "front", "i1")
    line = page.inner_text(".rk-inspector .rk-muted")
    if "· U14, front" not in line:
        bad.append(f"one U: the inspector reads {line!r}")
    return bad


@extra("rack.html: in 3D, a scene that could not check its cable ends says so once per rack - another rack's unchecked scene is announced too")
def check_rack_unchecked_3d_each_rack(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    try:
        open_cabled(page, base)
    except RuntimeError as e:
        return bad + [f"unchecked 3D: {e}"]
    if webgl_trouble(page):
        print("[check_rack_unchecked_3d_each_rack] WebGL unavailable - not exercised")
        return bad
    said = "() => (document.querySelector('.rk-side .rk-notice')?.textContent || '').includes('could not be checked')"
    page.evaluate("() => window.__rack.failSceneFacts(true)")
    try:
        page.click('#mode [data-mode="3d"]')
        settle_scene(page, "unchecked 3D: the first rack's scene")
        wait_fn(page, "unchecked 3D: the first rack's notice", said)
        # Another rack, opened while still in 3D: its scene is unchecked as well, and it has not been told.
        old = page.evaluate_handle("() => window.__rack.scene()")
        other = cable_fixture("doc-unchecked-other", "Other rack", lambda rack: None)
        page.set_input_files("#openFile", files=[{"name": "other.rack.json", "mimeType": "application/json",
                                                  "buffer": json.dumps(other).encode()}])
        page.wait_for_function("() => window.__rack.doc().racks[0].name === 'Other rack'", timeout=READY_MS)
        page.wait_for_function("s => { const n = window.__rack.scene(); return !!n && n !== s; }", arg=old, timeout=READY_3D_MS)
        settle_scene(page, "unchecked 3D: the second rack's scene")
        if page.evaluate("() => window.__rack.scene().rackCables.checked") is not False:
            bad.append("unchecked 3D: the second rack's scene is called checked")
        try:
            wait_fn(page, "unchecked 3D: the second rack's notice", said, timeout=5000)
        except RuntimeError:
            bad.append("unchecked 3D: the second rack's unchecked scene was not announced")
    finally:
        page.evaluate("() => window.__rack.failSceneFacts(false)")
    return bad



# ── portrayal-site#190: the cable list as a tree ─────────────────────────
# Two switches and a lacer, a switch at the rear, `n` cables up the front
# (c2 an OS2 cord on copper ports, so it carries a warning) and one more from
# the front to the rear, which has a tag on the front pane. c1 to c3 are
# bundled by the check.
TREE_FIXTURE = """async n => {
  const M = await import('/vendor/rack/model.js'), C = await import('/vendor/rack/catalog.js'), K = await import('/vendor/rack/cable-rules.js');
  const cat = (await C.loadCatalog('/assets/dist/')).devices;
  let r = M.newRack({name: 'Tree'});
  const sw = {ref: 'ws-c4948e', cfg: cat['ws-c4948e'].default};
  ({rack: r} = M.withItem(r, {...sw, ru: 20, face: 'front', label: 'sw-1'}));
  ({rack: r} = M.withItem(r, {ref: 'fhd-cmp5dr', cfg: cat['fhd-cmp5dr'].default, ru: 20, face: 'front', label: 'mgr-1', on: 'i1', unit: 1}));
  ({rack: r} = M.withItem(r, {...sw, ru: 30, face: 'front', label: 'sw-2'}));
  ({rack: r} = M.withItem(r, {...sw, ru: 26, face: 'rear', label: 'sw-rear'}));
  for (let k = 1; k <= n; k++)
    ({rack: r} = K.withCable(r, {a: {item: 'i1', path: `port-${k}`, view: 'front'}, b: {item: 'i3', path: `port-${k}`, view: 'front'}, media: k === 2 ? 'os2' : 'cat6a'}));
  ({rack: r} = K.withCable(r, {a: {item: 'i1', path: 'port-48', view: 'front'}, b: {item: 'i4', path: 'port-48', view: 'front'}, media: 'cat6a'}));
  return r;
}"""
# The tree as a reader of the page finds it: each row's place, what it says and whether it shows.
TREE_JS = """() => {
  const tree = document.querySelector('#cableList [role="tree"]');
  if (!tree) return null;
  const shows = n => !!n && n.getClientRects().length > 0;
  const row = li => ({id: li.id, key: li.dataset.treeKey ?? li.dataset.cableItem, level: li.getAttribute('aria-level'),
    expanded: li.getAttribute('aria-expanded'), selected: li.getAttribute('aria-selected'), tab: li.tabIndex, shows: shows(li),
    place: [li.getAttribute('aria-posinset'), li.getAttribute('aria-setsize')].join('/'),
    parent: li.parentElement.closest('[role="treeitem"]')?.id ?? null, group: li.parentElement.getAttribute('role'),
    name: (li.getAttribute('aria-labelledby') || '').split(' ').map(i => document.getElementById(i)?.textContent ?? '?').join(' | '),
    warned: li.querySelector(':scope > [data-member-warnings]')?.textContent ?? null,
    button: li.querySelector(':scope > [data-cable-row], :scope > [data-bundle-row]')?.tabIndex ?? null,
    twist: shows(li.querySelector(':scope > .rk-twist'))});
  const a = document.activeElement;
  return {rows: [...tree.querySelectorAll('[role="treeitem"]')].map(row), label: tree.getAttribute('aria-label'),
          at: a?.id || null, stops: [...document.querySelectorAll('#cableList [role="treeitem"], #cableList [data-cable-row], #cableList [data-bundle-row]')].filter(n => n.tabIndex === 0).map(n => n.id),
          pressed: [...document.querySelectorAll('#cableList [aria-pressed="true"]')].map(b => b.id), panel: !!document.getElementById('bundlePanel'),
          stored: localStorage.getItem('portrayal.rack.tree')};
}"""
STROKE_CLEAR_JS = """id => {
  const svg = document.querySelector('#paneFront > svg');
  const g = svg.querySelector(`[data-cables] [data-cable][data-cable-id="${id}"]`);
  // (a member's stroke outranks its bundle's band under the pointer: only other cables are in the way)
  const others = [...svg.querySelectorAll('[data-cables] [data-cable] path')].filter(p => !g.contains(p));
  for (const p of g.querySelectorAll('path')) {
    const L = p.getTotalLength();
    for (let f = 0.02; f < 0.98; f += 0.005) {
      const q = p.getPointAtLength(L * f), s = new DOMPoint(q.x, q.y).matrixTransform(p.getScreenCTM());
      if (others.some(o => o.isPointInStroke(new DOMPoint(s.x, s.y).matrixTransform(o.getScreenCTM().inverse())))) continue;
      if (document.elementFromPoint(s.x, s.y)?.closest('#paneFront')) return [s.x, s.y];
    }
  }
  return null;
}"""


# A point of a cable's stroke on the front pane that the page's own hover finds as that cable
# (cables that share a lane lie over one another: the one on top is the one hovered).
STROKE_OWN_JS = """async id => {
  const H = await import('/site/rack/hover.js');
  const svg = document.querySelector('#paneFront > svg'), g = svg.querySelector(`[data-cables] [data-cable][data-cable-id="${id}"]`);
  for (const p of g?.querySelectorAll('path') ?? []) {
    const L = p.getTotalLength();
    for (let f = 0.02; f < 0.98; f += 0.01) {
      const q = p.getPointAtLength(L * f), s = new DOMPoint(q.x, q.y).matrixTransform(p.getScreenCTM()), el = document.elementFromPoint(s.x, s.y);
      if (el?.closest('#paneFront') && H.hoverAt2d(svg, {clientX: s.x, clientY: s.y, target: el})?.id === id) return [s.x, s.y];
    }
  }
  return null;
}"""


def tree_rows(page):
    t = page.evaluate(TREE_JS)
    return t, {r["key"]: r for r in (t or {}).get("rows", [])}


@extra("rack.html: the cable list is a tree - each bundle a row that opens and closes over its members, the cables in no bundle a group of their own, closed to begin with past twenty cables and open under, remembered per rack in this browser and never in the rack; one Tab stop and the arrow keys; a closed row keeps its name, count, size and how many members carry a warning; the disclosure mark toggles and the name pins; a cable pinned opens the row it is under, and one hovered on the stage only marks its row: a sweep over thirty cables moves nothing in the panel (#190)")
def check_rack_cable_tree(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    page.click('#mode [data-mode="2d"]')

    def load(n):
        page.evaluate("r => window.__rack.replaceRack(r)", page.evaluate(TREE_FIXTURE, n))
        wait_fn(page, f"tree: {n + 1} cables drawn", "n => document.querySelectorAll('#cableList [data-cable-item]').length === n && window.__rack.routesCurrent().current", arg=n + 1)
        if not page.evaluate("() => (window.__rack.doc().racks[0].bundles || []).length"):
            res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'uplinks'})")
            if res.get("error"):
                raise RuntimeError(f"the bundle was not made: {res['error']}")
        wait_fn(page, "tree: the bundle's row", "() => document.querySelector('#cableList [data-bundle-row=\"b1\"]') && window.__rack.routesCurrent().current"
                                               " && document.querySelector('#paneFront [data-bundle-id=\"b1\"]')")
        page.wait_for_timeout(300)

    # PAST TWENTY CABLES every row that opens starts closed: 30 cables, three of them in b1.
    try:
        load(29)
    except RuntimeError as e:
        return bad + [f"fixture: {e}"]
    t, rows = tree_rows(page)
    if not t or t["label"] != "Cables":
        return bad + [f"tree: the list is not a labelled role=tree: {t and t['label']!r}"]
    tops = [r for r in t["rows"] if r["level"] == "1"]
    if [r["key"] for r in tops] != ["b1", "~none"] or any(r["expanded"] != "false" for r in tops):
        bad.append(f"30 cables: the rows at the top are {[(r['key'], r['expanded']) for r in tops]}, expected b1 and the unbundled group, both closed")
    members = [r for r in t["rows"] if r["level"] == "2"]
    if len(members) != 30 or any(r["shows"] for r in members) or any(r["group"] != "group" for r in members):
        bad.append(f"30 cables: {sum(r['shows'] for r in members)} of {len(members)} member rows show under closed rows, in {sorted({r['group'] for r in members})}")
    if {r["parent"] for r in members if r["key"] in ("c1", "c2", "c3")} != {"bundleItem-b1"} or {r["parent"] for r in members if r["key"] not in ("c1", "c2", "c3")} != {"cableGroup-none"}:
        bad.append("30 cables: b1's members are not under its row, or the rest are not under the unbundled group")
    # A CLOSED ROW still says its name, how many cables, its size, and how many carry a warning.
    b1, none = rows.get("b1", {}), rows.get("~none", {})
    if not re.search(r"^uplinks \| 3 cables \(c1-c3\), about \d+ mm", b1.get("name", "")):
        bad.append(f"closed: b1's row reads {b1.get('name')!r}, expected its name, its count and its size")
    if b1.get("warned") != "1 cable with a warning":
        bad.append(f"closed: b1's row says {b1.get('warned')!r} of its members' warnings; c2 is an OS2 cord on copper ports")
    if none.get("name") != "Not bundled | 27 cables" or none.get("warned") is not None:
        bad.append(f"closed: the unbundled group reads {none.get('name')!r} with {none.get('warned')!r}")
    if not (b1.get("twist") and none.get("twist")):
        bad.append("closed: a row that opens shows no disclosure mark")
    if t["stored"] is not None:
        bad.append(f"closed: rows nobody touched were stored: {t['stored']}")
    doc0 = page.evaluate("() => JSON.stringify(window.__rack.doc())")
    # A SWEEP OF THE POINTER OVER THE WHOLE RACK moves nothing in the panel: every cable hovered in turn, the
    # panel scrolled down first so a move would show, and its scroll position and height read after each.
    panel = "() => { const s = document.getElementById('side'); return [Math.round(s.scrollTop), s.scrollHeight, Math.round(document.querySelector('#cableList').getBoundingClientRect().height)]; }"
    page.set_viewport_size({"width": 1600, "height": 520})     # short, so the panel has somewhere to scroll to
    page.wait_for_timeout(400)
    for _ in range(8):                                          # and zoomed in on sw-1, where every cable has a stretch of its own
        page.click("#zoomIn")
    page.evaluate("() => document.querySelector('#paneFront [data-item-id=\"i1\"]').scrollIntoView({block: 'center', inline: 'center'})")
    page.wait_for_timeout(400)
    page.evaluate("() => { const s = document.getElementById('side'); s.scrollTop = 40; }")
    was, moved, hovered = page.evaluate(panel), [], 0
    if was[0] != 40:
        bad.append(f"sweep: the panel could not be scrolled ({was}), so a move would not have shown")
    for k in range(1, 31):
        pt = page.evaluate(STROKE_OWN_JS, f"c{k}")
        if not pt:
            continue
        page.mouse.move(pt[0], pt[1])
        page.wait_for_timeout(160)
        lit = page.evaluate("() => document.querySelectorAll('#panes [data-cables] [data-cable].hot').length")
        hovered += 1 if lit else 0
        now = page.evaluate(panel)
        if now != was:
            moved.append((f"c{k}", now))
    park_mouse(page)
    # (a cord from a lower port lies under its upper neighbour's for its whole length: about a third cannot be hovered at all.
    # On kit 0.22.0, which lays a cord from whichever end gives the better lay, 19 of the 30 have a stretch of their own
    # here, where 20 or more had: the bound, which only holds that a sweep was measured, is 18.)
    if hovered < 18:
        bad.append(f"sweep: only {hovered} of 30 cables were hovered on the stage, so a sweep was not what was measured")
    if moved or tree_rows(page)[1]["b1"]["expanded"] != "false":
        bad.append(f"sweep: hovering {hovered} cables moved the panel from {was} {len(moved)} times (scroll, scroll height, list height): {moved[:4]}")
    print(f"[check_rack_cable_tree] a sweep over {hovered} cables: the panel stayed at scroll {was[0]}, height {was[2]} px")
    page.set_viewport_size({"width": 1600, "height": 1000})
    page.click("#zoomFit")
    page.wait_for_timeout(400)

    # UNDER TWENTY they start open: the same rack with four cables up the front.
    try:
        load(3)
    except RuntimeError as e:
        return bad + [f"fixture: {e}"]
    t, rows = tree_rows(page)
    if [(r["key"], r["expanded"]) for r in t["rows"] if r["level"] == "1"] != [("b1", "true"), ("~none", "true")]:
        bad.append(f"4 cables: the rows at the top are {[(r['key'], r['expanded']) for r in t['rows'] if r['level'] == '1']}, expected both open")
    if [r["key"] for r in t["rows"]] != ["b1", "c1", "c2", "c3", "~none", "c4"] or not all(r["shows"] for r in t["rows"]):
        bad.append(f"4 cables: the rows are {[(r['key'], r['shows']) for r in t['rows']]}")
    # EACH ROW SAYS WHERE IT IS among its siblings: 1 and 2 of 2 at the top, 1 to 3 of 3 under b1, 1 of 1 under the group.
    if [r["place"] for r in t["rows"]] != ["1/2", "1/3", "2/3", "3/3", "2/2", "1/1"]:
        bad.append(f"4 cables: the rows' places among their siblings (aria-posinset / aria-setsize) are {[r['place'] for r in t['rows']]}")
    # ONE TAB STOP: one row holds it, and no row's own button is a stop.
    if len(t["stops"]) != 1 or any(r["button"] not in (-1, None) for r in t["rows"]):
        bad.append(f"keyboard: the list's Tab stops are {t['stops']}; expected one row")
    page.focus("#bundleItem-b1")
    page.keyboard.press("Tab")
    after = page.evaluate("() => { const a = document.activeElement; return [a?.id ?? null, !!a?.closest('[role=\"treeitem\"]')]; }")
    if after[1]:
        bad.append(f"keyboard: Tab from a row went to another row ({after[0]}), not out of the list")

    def press(key, want_at=None, label=""):
        page.keyboard.press(key)
        page.wait_for_timeout(120)
        tt, rr = tree_rows(page)
        if want_at and tt["at"] != want_at:
            bad.append(f"keyboard: {label or key} left focus on {tt['at']!r}, expected {want_at!r}")
        return tt, rr

    # THE ARROWS. Left closes b1 (its members no longer show), Right opens it, Right again steps in.
    page.focus("#bundleItem-b1")
    t, rows = press("ArrowLeft", "bundleItem-b1", "Left on open b1")
    if rows["b1"]["expanded"] != "false" or any(rows[c]["shows"] for c in ("c1", "c2", "c3")) or not rows["c4"]["shows"]:
        bad.append(f"keyboard: Left on b1 left it {rows['b1']['expanded']} with members showing {[rows[c]['shows'] for c in ('c1', 'c2', 'c3')]}")
    if json.loads(t["stored"] or "[]")[:1] != [[page.evaluate("() => window.__rack.doc().id"), {"b1": False}]]:
        bad.append(f"remembered: closing b1 stored {t['stored']!r}, expected this rack document with b1 closed")
    t, rows = press("ArrowDown", "cableGroup-none", "Down from closed b1")
    t, rows = press("ArrowUp", "bundleItem-b1", "Up from the unbundled group")
    t, rows = press("ArrowRight", "bundleItem-b1", "Right on closed b1")
    if rows["b1"]["expanded"] != "true" or not rows["c1"]["shows"]:
        bad.append("keyboard: Right on closed b1 did not open it")
    press("ArrowRight", "cableItem-c1", "Right on open b1")
    press("ArrowDown", "cableItem-c2", "Down from c1")
    press("ArrowUp", "cableItem-c1", "Up from c2")
    press("End", "cableItem-c4", "End")
    press("ArrowLeft", "cableGroup-none", "Left on c4")
    press("Home", "bundleItem-b1", "Home")
    t, rows = press("ArrowDown", "cableItem-c1", "Down from open b1")
    if len(t["stops"]) != 1 or t["stops"][0] != "cableItem-c1":
        bad.append(f"keyboard: the Tab stop did not follow focus to c1: {t['stops']}")
    # ENTER AND SPACE do what a click on the row does: pin the cable, then let it go.
    page.keyboard.press("Enter")
    wait_fn(page, "tree: Enter pins c1", "() => document.querySelector('#cableRow-c1')?.getAttribute('aria-pressed') === 'true' && document.getElementById('cableEdit')")
    t, rows = tree_rows(page)
    if t["at"] != "cableItem-c1" or rows["c1"]["selected"] != "true":
        bad.append(f"keyboard: after Enter focus is on {t['at']!r} and c1's row is selected={rows['c1']['selected']}")
    page.keyboard.press(" ")
    wait_fn(page, "tree: Space lets c1 go", "() => document.querySelector('#cableRow-c1')?.getAttribute('aria-pressed') === 'false'")
    if page.evaluate("() => document.activeElement?.id") != "cableItem-c1":
        bad.append("keyboard: Space on c1's row lost focus")

    # THE DISCLOSURE MARK IS ITS OWN TARGET: it closes and opens, and pins nothing.
    page.click("#bundleItem-b1 > .rk-twist")
    t, rows = tree_rows(page)
    if rows["b1"]["expanded"] != "false" or t["pressed"] or t["panel"]:
        bad.append(f"mark: a click on b1's mark left it {rows['b1']['expanded']}, pressed {t['pressed']}, bundle panel {t['panel']}")
    if t["at"] != "bundleItem-b1":
        bad.append(f"mark: closing b1 over the focused c1 left focus on {t['at']!r}, not on b1's row")
    # ENTER ON A BUNDLE'S ROW opens its panel and the keyboard goes with it, never to the page's body;
    # Done brings it back to the bundle's row.
    page.focus("#bundleItem-b1")
    page.keyboard.press("Enter")
    wait_fn(page, "tree: Enter opens b1's panel", "() => document.getElementById('bundlePanel')")
    at = page.evaluate("() => [document.activeElement?.id || document.activeElement?.tagName, !!document.activeElement?.closest('#bundlePanel')]")
    if not at[1]:
        bad.append(f"keyboard: after Enter on b1's row focus is on {at[0]!r}, not in the bundle's panel")
    page.click("#bDone")
    wait_fn(page, "tree: the list after Done", "() => document.querySelector('#cableList [role=\"tree\"]')")
    if page.evaluate("() => document.activeElement?.id") != "bundleItem-b1":
        bad.append(f"keyboard: after Done focus is on {page.evaluate('() => document.activeElement?.id || document.activeElement?.tagName')!r}, not back on b1's row")
    # THE NAME PINS THE BUNDLE, as it did, and toggles nothing: b1 is still closed when its panel is put away.
    page.click('#cableList [data-bundle-row="b1"]')
    wait_fn(page, "tree: b1's panel", "() => document.getElementById('bundlePanel') && document.querySelector('#paneFront [data-bundle-id=\"b1\"].on')")
    page.click("#bDone")
    wait_fn(page, "tree: the list again", "() => document.querySelector('#cableList [role=\"tree\"]')")
    t, rows = tree_rows(page)
    if rows["b1"]["expanded"] != "false":
        bad.append("name: pinning b1 by its name opened its row")
    # ...and it is still closed after a reload: remembered in this browser, for this rack.
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    wait_fn(page, "tree: the list after a reload", "() => document.querySelector('#cableList [data-bundle-row=\"b1\"]') && window.__rack.routesCurrent().current"
                                                " && document.querySelectorAll('#paneFront svg [data-cables] [data-cable-id][data-cable]').length >= 4")
    page.wait_for_timeout(300)
    t, rows = tree_rows(page)
    if rows["b1"]["expanded"] != "false" or rows["~none"]["expanded"] != "true":
        bad.append(f"remembered: after a reload b1 is {rows['b1']['expanded']} and the unbundled group {rows['~none']['expanded']}; expected closed and open")

    # A CABLE HOVERED ON THE STAGE MARKS ITS ROW AND MOVES NOTHING: b1 is closed, so its row stands for c1;
    # it is not opened, the panel does not scroll, and nothing is stored.
    stored = t["stored"]
    panel = "() => { const s = document.getElementById('side'); return [s.scrollTop, s.scrollHeight, document.querySelector('#cableList').getBoundingClientRect().height]; }"
    marks = "() => [...document.querySelectorAll('#cableList [data-hover-mark]')].map(li => li.id)"
    pt = page.evaluate(STROKE_CLEAR_JS, "c1")
    if not pt:
        bad.append("mark: found no point on c1's stroke clear of the others")
    else:
        was = page.evaluate(panel)
        page.mouse.move(pt[0], pt[1])
        page.wait_for_timeout(350)
        t, rows = tree_rows(page)
        if page.evaluate(marks) != ["bundleItem-b1"] or rows["b1"]["expanded"] != "false" or rows["c1"]["shows"]:
            bad.append(f"mark: with c1 under the pointer the marked rows are {page.evaluate(marks)} and b1 is {rows['b1']['expanded']}; expected b1's closed row marked and still closed")
        if t["stored"] != stored or page.evaluate(panel) != was:
            bad.append(f"mark: a hover moved the panel or was remembered: {was} to {page.evaluate(panel)}, stored {t['stored']}")
        park_mouse(page)
        if page.evaluate(marks):
            bad.append(f"mark: rows are still marked with the pointer off the stage: {page.evaluate(marks)}")
        # with b1 open, the member's own row is the one marked
        page.click("#bundleItem-b1 > .rk-twist")
        page.mouse.move(pt[0], pt[1])
        page.wait_for_timeout(350)
        if page.evaluate(marks) != ["cableItem-c1"]:
            bad.append(f"mark: with b1 open and c1 under the pointer the marked rows are {page.evaluate(marks)}")
        park_mouse(page)
        page.click("#bundleItem-b1 > .rk-twist")
    # A CABLE PINNED FROM THE STAGE (its tag) opens the row it is under, and that is remembered.
    page.click("#cableGroup-none > .rk-twist")
    if tree_rows(page)[1]["~none"]["expanded"] != "false":
        bad.append("pin: the unbundled group did not close")
    page.click('svg[data-pane="front"] [data-cable-tags] [data-cable-tag][data-cable-id="c4"]')
    wait_fn(page, "tree: the tag pins c4", "() => document.querySelector('#cableRow-c4')?.getAttribute('aria-pressed') === 'true'")
    t, rows = tree_rows(page)
    if rows["~none"]["expanded"] != "true" or not rows["c4"]["shows"]:
        bad.append(f"pin: with c4 pinned from its tag the unbundled group is {rows['~none']['expanded']} and c4's row shows {rows['c4']['shows']}")
    inview = page.evaluate("() => { const r = document.getElementById('cableItem-c4').getBoundingClientRect(), s = document.getElementById('side').getBoundingClientRect(); return r.top >= s.top - 1 && r.bottom <= s.bottom + 1; }")
    if not inview:
        bad.append("pin: c4's row is not in view in the side panel")
    if json.loads(t["stored"] or "[]")[0][1].get("~none") is not True:
        bad.append(f"pin: the row a pin opened was not remembered: {t['stored']}")
    page.keyboard.press("Escape")
    wait_fn(page, "tree: Esc lets c4 go", "() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
    # NOTHING OF THIS IS IN THE RACK: the document is what it was but for the cables the check itself changed.
    doc = page.evaluate("() => JSON.stringify(window.__rack.doc())")
    if "tree" in doc or "expanded" in doc or '"open"' in doc or "tree" in doc0:
        bad.append("rack: the rack document names the list's rows")
    return bad



# ── portrayal-site#190: covers on, see-through or off ────────────────────
# The covers of the duct on the front pane: the copy laid over the cables, the
# cover under them, a point on the bundle's run up the lane inside the duct
# (page pixels) and a point on the cover clear of every cable.
COVERS_2D_JS = """() => {
  const svg = document.querySelector('#paneFront > svg'), z = svg.querySelector('[data-zerou-id="z1"]');
  const copies = [...svg.querySelectorAll('[data-in-front] [data-front="cover"]')], own = [...z.querySelectorAll('[data-group="cover"]')];
  const css = n => { const c = getComputedStyle(n); return [Math.round(+c.opacity * 100) / 100, c.visibility]; };
  const box = z.getBoundingClientRect();
  // the lane run: a point of c2's stroke inside the duct, at the middle of its height there
  const pts = [];
  for (const p of svg.querySelectorAll('[data-cables] [data-cable][data-cable-id="c2"] path')) {
    const L = p.getTotalLength(), m = p.getScreenCTM();
    for (let t = 0; t <= L; t += 1) { const q = p.getPointAtLength(t), w = new DOMPoint(q.x, q.y).matrixTransform(m);
      if (w.x > box.left && w.x < box.right) pts.push([w.x, w.y]); }
  }
  pts.sort((a, b) => a[1] - b[1]);
  const lane = pts.length ? pts[Math.floor(pts.length / 2)] : null;
  return {state: document.getElementById('panes').dataset.covers, pressed: [...document.querySelectorAll('#covers [aria-pressed="true"]')].map(b => b.dataset.coversSet),
          buttons: [...document.querySelectorAll('#covers [data-covers-set]')].map(b => [b.dataset.coversSet, b.getAttribute('aria-label')]),
          copies: copies.map(css), own: own.map(css), lane, clear: lane ? [box.left + box.width * 0.82, lane[1]] : null,
          // the rack-mounted duct's cover: the page's own copy over the cables, the cover in its drawing, and its middle on the page
          duct: (() => { const g = svg.querySelector('[data-item-id="i4"]'), r = g?.getBoundingClientRect();
            return {copies: [...svg.querySelectorAll(':scope > [data-covers-front] [data-front="cover"][data-front-of="i4"]')].map(css),
                    own: [...(g?.querySelectorAll('[data-group="cover"]') ?? [])].map(css), at: r ? [r.left + r.width / 2, r.top + r.height / 2] : null,
                    selected: !!g?.classList.contains('rk-selected'), layers: svg.querySelectorAll(':scope > [data-covers-front]').length}; })(),
          // the power panel's thumbscrews, which its drawing puts in a group called `cover`: as they are painted, and any copy laid for them
          screws: (() => { const g = svg.querySelector('[data-item-id="i5"]'); return {own: [...(g?.querySelectorAll('[data-group="cover"]') ?? [])].map(n => [n.dataset.path, n.dataset.class, ...css(n)]),
            copies: svg.querySelectorAll('[data-front-of="i5"]').length}; })(),
          stored: localStorage.getItem('portrayal.rack.covers'), search: location.search, selected: z.classList.contains('rk-selected'),
          hot: [...svg.querySelectorAll('[data-cables] [data-cable].hot')].map(n => n.dataset.cableId)};
}"""
# The covers in the scene: how many meshes, whether they show, their materials' see-through state, and
# where the bundle's run inside the duct is on the page, with the camera put straight in front of it.
COVERS_3D_JS = """aim => {
  const s = window.__rack.scene(), T = s.three, ms = s.coverMeshes ?? [];
  const mats = ms.flatMap(o => [].concat(o.material));
  // the run's own point on the page, read where the camera is now (it eases after it is put somewhere)
  const tube = s.rackCables.tubes.find(t => t.link.id === 'c2'), g = T.scene.getObjectByName('device-z1');
  const box = new T.THREE.Box3().setFromObject(g), inside = tube.points.filter(q => q.x > box.min.x && q.x < box.max.x);
  // (the middle of its straight run up the lane: between its highest point in the duct and the lowest at that x)
  const top = inside.reduce((m, q) => (q.y > m.y ? q : m)), foot = inside.filter(q => Math.abs(q.x - top.x) < 1 && Math.abs(q.z - top.z) < 1).reduce((m, q) => (q.y < m.y ? q : m));
  const p = top.clone().add(foot).multiplyScalar(0.5);
  if (aim) { T.controls.target.copy(p); T.camera.position.set(p.x, p.y, p.z + 600); T.controls.update(); }
  T.camera.updateMatrixWorld();
  T.camera.matrixWorldInverse.copy(T.camera.matrixWorld).invert();
  const v = p.clone().project(T.camera), r = T.renderer.domElement.getBoundingClientRect();
  const at = [r.left + (v.x + 1) / 2 * r.width, r.top + (1 - v.y) / 2 * r.height];
  const under = name => { const g = T.scene.getObjectByName(name); return ms.filter(o => { for (let n = o; n; n = n.parent) if (n === g) return true; return false; }); };
  // the power panel's thumbscrews in the scene: every mesh of them, whether it shows, and its materials' own values
  const screws = []; T.scene.getObjectByName('device-i5')?.traverse(o => { if (o.isMesh && /^thumbscrew-/.test(o.userData.portrayalPath ?? ''))
    screws.push([o.userData.portrayalPath, o.visible, ms.includes(o), ...[].concat(o.material).map(m => [m.transparent, Math.round(m.opacity * 100) / 100, m.depthWrite].join('/'))].join(' ')); });
  return {n: ms.length, shown: ms.filter(o => o.visible).length, setting: s.covers, screws: screws.sort(), panel: under('device-i5').length, duct: under('device-i4').length, ductShown: under('device-i4').filter(o => o.visible).length,
          mats: [...new Set(mats.map(m => [m.transparent, Math.round(m.opacity * 100) / 100, m.depthWrite, m.alphaToCoverage, m.alphaTest].join('/')))].sort(),
          others: (() => { let n = 0; T.scene.getObjectByName('device-z1').traverse(o => { if (o.isMesh && !ms.includes(o) && o.visible) n++; }); return n; })(), at};
}"""
# A MODEL FILE, AS WHAT IT HOLDS. Two GLBs of one scene are not the same bytes:
# the exporter encodes its textures side by side and writes them in the order
# they finish. So a file is compared by what is in it, in an order of its own:
# every image's digest; every material with each texture it names put down as
# that image's digest; and every node with its name, its place, and its mesh as
# those materials and the size and bounds of its geometry. A USDZ is a zip of
# stored entries: its size and its entries' sizes.
MODEL_HASH_JS = """async kind => {
  const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
  const out = await X.modelFile(window.__rack.scene(), window.__rack.doc().racks[0], kind, (await C.loadCatalog('/assets/dist/')).chassisOf);
  const buf = out.data instanceof ArrayBuffer ? out.data : await new Response(out.data).arrayBuffer();
  const hex = b => [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
  const sha = async b => hex(await crypto.subtle.digest('SHA-256', b)), text = v => new TextEncoder().encode(JSON.stringify(v));
  const dv = new DataView(buf);
  if (kind !== 'glb') {
    const sizes = [];
    for (let i = 0; i + 30 < buf.byteLength;) {
      if (dv.getUint32(i, true) !== 0x04034b50) break;
      const size = dv.getUint32(i + 18, true);
      sizes.push(size);
      i += 30 + dv.getUint16(i + 26, true) + dv.getUint16(i + 28, true) + size;
    }
    return {bytes: buf.byteLength, entries: sizes.length, sizes: await sha(text(sizes.sort((a, b) => a - b)))};
  }
  const len = dv.getUint32(12, true), j = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 20, len)));
  const imgs = await Promise.all((j.images || []).map(i => { const v = j.bufferViews[i.bufferView]; return sha(new Uint8Array(buf, 20 + len + 8 + (v.byteOffset || 0), v.byteLength)); }));
  const tex = v => (v && typeof v === 'object' ? (Array.isArray(v) ? v.map(tex) : Object.fromEntries(Object.entries(v).map(([k, x]) =>
    [k, x && typeof x === 'object' && typeof x.index === 'number' && /Texture$/i.test(k) ? {...x, index: imgs[j.textures[x.index].source]} : tex(x)]))) : v);
  const mats = (j.materials || []).map(m => JSON.stringify(tex(m)));
  const acc = i => { const a = j.accessors[i]; return [a.count, a.type, a.componentType, a.min, a.max]; };
  const nodes = j.nodes.map(n => JSON.stringify([n.name ?? '', n.extras ?? null, n.translation, n.rotation, n.scale, n.matrix, (n.children || []).length,
    n.mesh == null ? null : j.meshes[n.mesh].primitives.map(p => [mats[p.material] ?? null, p.mode, p.indices == null ? null : acc(p.indices),
      Object.entries(p.attributes).sort().map(([k, i]) => [k, acc(i)])])]));
  return {bytes: buf.byteLength, nodes: j.nodes.length, materials: mats.length, images: imgs.length,
          nodesHash: await sha(text([...nodes].sort())), materialsHash: await sha(text([...mats].sort())), imagesHash: await sha(text([...imgs].sort())),
          hidden: j.nodes.filter(n => /cover/.test(n.name || '')).length,
          faded: (j.materials || []).filter(m => { const a = m.pbrMetallicRoughness?.baseColorFactor?.[3]; return a != null && a < 0.99; }).length};
}"""
SHEET_HASH_JS = """async () => {
  const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
  const text = (await X.sheetSvg(window.__rack.doc().racks[0], (await C.loadCatalog('/assets/dist/')).chassisOf, {date: new Date(2026, 0, 2)})).data;
  const h = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return {hash: [...new Uint8Array(h)].map(x => x.toString(16).padStart(2, '0')).join(''), covers: (text.match(/data-front="cover"/g) || []).length, opacity: /data-front="cover"[^>]*opacity="0.34"/.test(text)};
}"""


def colour_gap(a, b):
    return max(abs(x - y) for x, y in zip(a, b))


@extra("rack.html: covers on, see-through or off - one control for the panes (both pairs) and the scene, for a vertical manager's covers and a rack-mounted duct's alike and never for the thumbscrews a power panel keeps in a group of that name, see-through to begin with and remembered in the browser, never in the rack or the URL; on hides the run inside a vertical manager, see-through shows it through the cover, off draws no cover; the manager is still selected by a click and the cable inside still hovered; and the sheet, the GLB and the USDZ are the same files whatever it says (#190)")
def check_rack_covers(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_front_fixture(page, base, PACK_FIXTURE)
    # and a rack-mounted finger duct with a cover of its own (i4): every part the library marks a cover on
    res = page.evaluate("() => window.__rack.apply({op: 'place', ref: 'cmh-dfd1u', cfg: 'base', face: 'front', ru: 25, label: 'duct-h'})")
    if res.get("error") or res.get("created", {}).get("ids") != ["i4"]:
        return bad + [f"fixture: the horizontal duct was not placed as i4: {res}"]
    wait_fn(page, "covers: the horizontal duct", "() => document.querySelector('#paneFront [data-item-id=\"i4\"]') && window.__rack.routesCurrent().current")
    # and a power panel (i5) whose two thumbscrews are in a group the library calls `cover`: fasteners, not covers
    res = page.evaluate("() => window.__rack.apply({op: 'place', ref: '300cb08', cfg: 'base', face: 'front', ru: 10, label: 'panel'})")
    if res.get("error") or res.get("created", {}).get("ids") != ["i5"]:
        return bad + [f"fixture: the power panel was not placed as i5: {res}"]
    wait_fn(page, "covers: the power panel", "() => document.querySelector('#paneFront [data-item-id=\"i5\"]') && window.__rack.routesCurrent().current")
    res = page.evaluate("() => window.__rack.bundleCommand({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'pack'})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneFront [data-strap=\"b1\"]') && window.__rack.routesCurrent().current", timeout=READY_MS)
    page.click("#zoomFit")
    page.wait_for_timeout(400)
    park_mouse(page)
    st = page.evaluate(COVERS_2D_JS)
    screws0 = st["screws"]["own"]
    if sorted(x[:2] for x in screws0) != [["thumbscrew-left", "screw"], ["thumbscrew-right", "screw"]]:
        return bad + [f"fixture: the power panel's cover group holds {screws0}, expected its two thumbscrews"]
    if not st["duct"]["copies"] or not st["duct"]["own"] or st["duct"]["layers"] != 1:
        return bad + [f"fixture: the horizontal duct has {len(st['duct']['copies'])} cover copies over the cables and {len(st['duct']['own'])} covers in its drawing, in {st['duct']['layers']} layers"]
    # THE CONTROL: three settings, see-through to begin with, nothing stored until the reader picks.
    if [b[0] for b in st["buttons"]] != ["on", "see", "off"] or not all(b[1] and b[1].startswith("Covers ") for b in st["buttons"]):
        bad.append(f"control: its buttons are {st['buttons']}")
    if (st["state"], st["pressed"], st["stored"]) != ("see", ["see"], None):
        bad.append(f"control: to begin with the panes are {st['state']!r}, pressed {st['pressed']}, stored {st['stored']!r}; expected see-through and nothing stored")
    if not st["copies"] or not st["own"] or not st["lane"]:
        return bad + [f"fixture: the front pane has {len(st['copies'])} cover copies, {len(st['own'])} covers and lane point {st['lane']}"]
    doc0, sheet0 = page.evaluate("() => JSON.stringify(window.__rack.doc())"), page.evaluate(SHEET_HASH_JS)
    if sheet0["covers"] != 2:
        bad.append(f"sheet: the sheet has {sheet0['covers']} cover copies; the vertical manager's two are the drawing's, and the horizontal duct's is the page's alone")
    if not sheet0["covers"] or not sheet0["opacity"]:
        bad.append(f"sheet: the sheet has {sheet0['covers']} cover copies (see-through: {sheet0['opacity']}), so it could not show a change")
    want2d = {"on": ([1, "visible"], [1, "visible"]), "see": ([0.34, "visible"], [1, "visible"]), "off": ([0.34, "hidden"], [1, "hidden"])}
    seen = {}
    for state in ("on", "off", "see"):
        page.click(f'#covers [data-covers-set="{state}"]')
        page.wait_for_timeout(250)
        st = page.evaluate(COVERS_2D_JS)
        copy, own = want2d[state]
        if (st["state"], st["pressed"], st["stored"]) != (state, [state], state):
            bad.append(f"2D {state}: the panes are {st['state']!r}, pressed {st['pressed']}, stored {st['stored']!r}")
        if any(c != copy for c in st["copies"]) or any(c != own for c in st["own"]):
            bad.append(f"2D {state}: the copies over the cables are {st['copies']} and the covers under them {st['own']}; expected {copy} and {own}")
        d = st["duct"]
        if any(c != copy for c in d["copies"]) or any(c != own for c in d["own"]) or not d["copies"]:
            bad.append(f"2D {state}: the horizontal duct's copies over the cables are {d['copies']} and its covers {d['own']}; expected {copy} and {own}")
        # THE THUMBSCREWS ARE NOT A COVER: painted as they were, with no copy laid for them, whatever the setting
        if st["screws"]["own"] != screws0 or any(x[2:] != [1, "visible"] for x in st["screws"]["own"]) or st["screws"]["copies"]:
            bad.append(f"2D {state}: the power panel's thumbscrews are {st['screws']['own']} with {st['screws']['copies']} copies laid; expected them untouched")
        # the horizontal duct is still selected by a click on it
        page.mouse.click(*d["at"])
        try:
            wait_fn(page, f"2D {state}: a click on the horizontal duct selects it", "() => document.querySelector('#paneFront [data-item-id=\"i4\"].rk-selected')", timeout=8000)
        except RuntimeError as e:
            bad.append(str(e))
        page.keyboard.press("Escape")
        wait_fn(page, f"2D {state}: the horizontal duct put down", "() => !document.querySelector('#paneFront [data-item-id=\"i4\"].rk-selected')")
        park_mouse(page)
        if st["search"] != "?probe=1":
            bad.append(f"2D {state}: the setting reached the URL: {st['search']!r}")
        # on the composited page: the run inside the duct, and the cover beside it
        w, h, px = png_pixels(page.screenshot())
        seen[state] = (px(*st["lane"]), px(*st["clear"]))
        # THE CABLE INSIDE IS STILL HOVERED, whatever stands in front of it...
        page.mouse.move(*st["lane"])
        page.wait_for_timeout(350)
        hot = page.evaluate(COVERS_2D_JS)["hot"]
        if not hot or not set(hot) <= {"c1", "c2", "c3"}:
            bad.append(f"2D {state}: the pointer on the run inside the duct lit {hot}, expected a member of the bundle")
        park_mouse(page)
        # ...AND THE MANAGER IS STILL SELECTED by a click on it, cover or no cover.
        page.mouse.click(*st["clear"])
        try:
            wait_fn(page, f"2D {state}: a click on the duct selects it", "() => document.querySelector('#paneFront [data-zerou-id=\"z1\"].rk-selected') && document.getElementById('zRemove')", timeout=8000)
        except RuntimeError as e:
            bad.append(str(e))
        page.keyboard.press("Escape")
        wait_fn(page, f"2D {state}: the duct put down", "() => !document.querySelector('#paneFront [data-zerou-id=\"z1\"].rk-selected')")
        park_mouse(page)
        sheet = page.evaluate(SHEET_HASH_JS)
        if sheet != sheet0:
            bad.append(f"sheet {state}: the sheet is not the file it was with the covers see-through: {sheet} against {sheet0}")
    # ON hides the run; OFF shows it at its own colour and no cover beside it; SEE-THROUGH is between the two.
    lane = {k: v[0] for k, v in seen.items()}
    clear = {k: v[1] for k, v in seen.items()}
    if colour_gap(lane["on"], clear["on"]) > 12:
        bad.append(f"2D on: the run inside the duct still shows through the cover: {lane['on']} beside {clear['on']}")
    if colour_gap(lane["off"], lane["on"]) < 60 or colour_gap(clear["off"], clear["on"]) < 4:
        bad.append(f"2D off: the run is {lane['off']} (on: {lane['on']}) and the duct beside it {clear['off']} (on: {clear['on']}); expected the cable's own colour and no cover")
    if not (colour_gap(lane["see"], lane["on"]) > 25 and colour_gap(lane["see"], lane["off"]) > 25):
        bad.append(f"2D see-through: the run is {lane['see']}, expected between on {lane['on']} and off {lane['off']}")
    print(f"[check_rack_covers] 2D, the run inside the duct: on {lane['on']}, see-through {lane['see']}, off {lane['off']}")
    # FROM THE SIDE the cover is the strip the drawing marks: there with on and see-through, gone with off.
    to_sides(page, cables=4)
    side = "sel => [...document.querySelectorAll(`#panes svg[data-side] ${sel} [data-kind=\"cover\"]`)].map(n => getComputedStyle(n).visibility)"
    for state, want in (("off", "hidden"), ("on", "visible"), ("see", "visible")):
        page.click(f'#covers [data-covers-set="{state}"]')
        for what, sel in (("the vertical manager's", "[data-zerou-id]"), ("the horizontal duct's", '[data-item-id="i4"]')):
            got = page.evaluate(side, sel)
            if not got or set(got) != {want}:
                bad.append(f"sides {state}: {what} cover strips are {sorted(set(got))} ({len(got)} of them), expected {want}")
    to_faces(page)
    # REMEMBERED IN THE BROWSER, not in the rack: off, a reload, and it is still off.
    page.click('#covers [data-covers-set="off"]')
    if page.evaluate("() => JSON.stringify(window.__rack.doc())") != doc0:
        bad.append("rack: the setting changed the rack document")
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    wait_fn(page, "covers: the panes after a reload", "() => document.querySelector('#paneFront [data-in-front] [data-front=\"cover\"]') && window.__rack.routesCurrent().current")
    st = page.evaluate(COVERS_2D_JS)
    if (st["state"], st["pressed"]) != ("off", ["off"]) or any(c[1] != "hidden" for c in st["copies"] + st["own"]):
        bad.append(f"remembered: after a reload the panes are {st['state']!r}, pressed {st['pressed']}, covers {st['copies']} {st['own']}")

    # 3D. A scene built with the covers off never shows one; the control then restyles it in place.
    if webgl_trouble(page):
        print("[check_rack_covers] WebGL unavailable - 3D not exercised")
        return bad
    page.click('#mode [data-mode="3d"]')
    try:
        settle_scene(page, "covers: the 3D scene", tubes=True)
    except RuntimeError as e:
        return bad + [str(e)]
    scene = page.evaluate_handle("() => window.__rack.scene()")
    st = page.evaluate(COVERS_3D_JS, True)
    if not st["duct"]:
        bad.append(f"3D: none of the {st['n']} cover meshes is the horizontal duct's")
    screws3 = st["screws"]
    if len(screws3) < 2 or st["panel"] or any(" true false " not in f" {x} " for x in screws3):
        bad.append(f"3D: the power panel's thumbscrews are {screws3} and {st['panel']} of its meshes are taken as covers; expected its screws shown and none taken")
    if st["n"] < 2 or st["shown"] or st["setting"] != "off" or st["others"] < 10:
        bad.append(f"3D off: {st['shown']} of {st['n']} cover meshes show in a scene built with the covers off (setting {st['setting']!r}, {st['others']} other meshes of the duct show)")
    page.wait_for_timeout(1500)
    shots, built = {}, None
    for state in ("off", "on", "see", "on", "off", "see"):
        page.click(f'#covers [data-covers-set="{state}"]')
        page.wait_for_timeout(700)
        st3 = page.evaluate(COVERS_3D_JS, False)
        if state == "on":
            # as built, and the same again after a see-through spell
            if built is not None and st3["mats"] != built:
                bad.append(f"3D on: after see-through the covers' materials are {st3['mats']}, not as they were built {built}")
            built = st3["mats"]
            if st3["shown"] != st3["n"] or any(m.split("/")[1] != "1" or m.split("/")[2] != "true" for m in st3["mats"]):
                bad.append(f"3D on: {st3['shown']} of {st3['n']} cover meshes show, materials {st3['mats']}; expected every one at full strength and writing depth")
        elif state == "see":
            if st3["shown"] != st3["n"] or not all(m.startswith("true/0.3/false/false/") for m in st3["mats"]) or len(st3["mats"]) < 1:
                bad.append(f"3D see-through: {st3['shown']} of {st3['n']} cover meshes show, materials {st3['mats']}; expected every one blended at 0.3 and writing no depth")
        elif st3["shown"]:
            bad.append(f"3D off: {st3['shown']} of {st3['n']} cover meshes show")
        if st3["screws"] != screws3 or st3["panel"]:
            bad.append(f"3D {state}: the power panel's thumbscrews changed with the setting: {st3['screws']} (built {screws3}), {st3['panel']} taken as covers")
        if (st3["ductShown"] > 0) != (state != "off"):
            bad.append(f"3D {state}: {st3['ductShown']} of the horizontal duct's {st3['duct']} cover meshes show")
        if st3["others"] != st["others"]:
            bad.append(f"3D {state}: {st3['others']} other meshes of the duct show, {st['others']} before: the setting touched more than the covers")
        w, h, px = png_pixels(page.screenshot())
        shots[state] = px(*st3["at"])
        hov = page.evaluate("""async at => { const H = await import('/site/rack/hover.js'); return H.hoverAt3d(window.__rack.scene(), {clientX: at[0], clientY: at[1]}); }""", st3["at"])
        if not hov or hov.get("id") not in ("c1", "c2", "c3", "c4", "b1"):
            bad.append(f"3D {state}: the pointer on the run inside the duct finds {hov}, expected a cable that runs there or their bundle")
        for kind in ("glb", "usdz"):
            got = page.evaluate(MODEL_HASH_JS, kind)
            shots.setdefault(kind, {})[state] = got
        after = page.evaluate(COVERS_3D_JS, False)
        if (after["shown"], after["mats"]) != (st3["shown"], st3["mats"]):
            bad.append(f"3D {state}: after a download the covers are not as the setting has them ({after['shown']} show, {after['mats']})")
    if colour_gap(shots["on"], shots["off"]) < 60 or not (colour_gap(shots["see"], shots["on"]) > 20 and colour_gap(shots["see"], shots["off"]) > 8):
        bad.append(f"3D: on the page the run inside the duct is {shots['on']} with the covers on, {shots['see']} see-through and {shots['off']} off")
    print(f"[check_rack_covers] 3D, the run inside the duct: on {shots['on']}, see-through {shots['see']}, off {shots['off']}")
    for kind in ("glb", "usdz"):
        files = shots[kind]
        if len({json.dumps(v, sort_keys=True) for v in files.values()}) != 1:
            bad.append(f"{kind.upper()}: the file differs with the covers setting: {files}")
    glb = shots["glb"]["on"]
    if glb.get("faded") or glb["nodes"] < 20:
        bad.append(f"GLB: {glb['faded']} see-through materials in a file of {glb['nodes']} nodes; a cover in a file is as it was built")
    if page.evaluate("s => window.__rack.scene() !== s", scene):
        bad.append("3D: the scene was rebuilt for a covers setting")
    print(f"[check_rack_covers] GLB {glb['bytes']} bytes, {glb['nodes']} nodes, {glb['materials']} materials, {glb['images']} images (nodes {glb['nodesHash'][:12]}, materials {glb['materialsHash'][:12]}, images {glb['imagesHash'][:12]}): the same on, see-through and off; USDZ {shots['usdz']['on']['bytes']} bytes, {shots['usdz']['on']['entries']} entries, the same")
    return bad



# ── portrayal-site#190: nothing floats while the 3D scene loads ──────────
# One sample a frame of the scene as it is being built: is the duct there, where,
# how many of its meshes would be drawn (and whether one is its stand-in box),
# and how many cable tubes and strap bands would be.
LOADING_SAMPLER_JS = """() => {
  window.__frames = []; window.__sampling = true;
  const t0 = performance.now();
  const drawn = o => { for (let n = o; n; n = n.parent) if (!n.visible) return false; return [].concat(o.material).some(m => m && m.visible !== false); };
  const tick = () => {
    const s = window.__rack.loadingScene(), T = s?.three?.scene;
    if (T) {
      const g = T.getObjectByName('device-z1'), pc = T.getObjectByName('patch-cables'), cb = T.getObjectByName('cable-bundles');
      const next = !!T.getObjectByName('device-z2');
      let body = 0, standIn = 0, tubes = 0, straps = 0;
      g?.traverse(o => { if (o.isMesh && drawn(o)) { body++; if (o.userData.standIn) standIn++; } });
      pc?.traverse(o => { if (o.isMesh && drawn(o)) tubes++; });
      cb?.traverse(o => { if (o.isMesh && o.userData.strap && drawn(o)) straps++; });
      window.__frames.push({t: Math.round(performance.now() - t0), device: !!g, next, x: g ? Math.round(g.position.x * 10) / 10 : null, body, standIn, tubes, straps});
    }
    if (window.__sampling) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}"""
STRAPS_WITH_CABLES_JS = """() => [...document.querySelectorAll('#panes svg[data-pane]')].map(s => ({pane: s.dataset.pane,
  straps: [...s.querySelectorAll('[data-strap]')].map(g => (g.dataset.members || '').split(' ').filter(id => s.querySelector(`[data-cables] [data-cable][data-cable-id="${id}"] path`)).length),
  trunks: s.querySelectorAll('[data-bundle-trunk]').length}))"""


@extra("rack.html: nothing floats while the 3D scene loads - no frame has a cable or a strap without the vertical manager's body (a plain box of its size until its detail arrives), the box stands beside its rail from the first frame it is in, through the wait for a later part's held-back files, and is gone once the scene is complete; and a part whose files do not load stays a box marked as not coming, with the page saying so, once, for as long as it is one (#190)")
def check_rack_3d_loading(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1400, "height": 900})
    # the files of the part built LAST come late, each held for a moment: the vertical manager (z1) is mounted
    # before it, and stands through the whole wait
    held = []
    def late(route):
        held.append(route.request.url.rsplit("/", 1)[-1])
        time.sleep(0.4)
        route.continue_()
    open_front_fixture(page, base, PACK_FIXTURE)
    # a second part beside the rack, at the other rail, of another kind (a PDU), built after the manager
    page.evaluate("""() => { const r = window.__rack.doc().racks[0];
      window.__rack.replaceRack({...r, zeroU: [...r.zeroU, {id: 'z2', ref: 'evmi2130x', cfg: 'base', label: 'pdu-1', at: 'right-front', offsetMm: 0}]}); }""")
    wait_fn(page, "loading: the second part", "() => document.querySelector('#paneFront [data-zerou-id=\"z2\"]') && window.__rack.routesCurrent().current")
    res = page.evaluate("() => window.__rack.apply({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'pack'})")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => document.querySelector('#paneFront [data-strap=\"b1\"]') && window.__rack.routesCurrent().current", timeout=READY_MS)
    # 2D: every strap on a pane has a member of its bundle drawn on that pane.
    two = page.evaluate(STRAPS_WITH_CABLES_JS)
    if not any(p["straps"] for p in two) or any(n == 0 for p in two for n in p["straps"]):
        bad.append(f"2D: straps and the members drawn with them, per pane: {two}; expected straps, each with a member drawn")
    if webgl_trouble(page):
        print("[check_rack_3d_loading] WebGL unavailable - not exercised")
        return bad
    page.route("**/assets/dist/evmi2130x*", late)
    page.evaluate(LOADING_SAMPLER_JS)
    t0 = time.time()
    page.click('#mode [data-mode="3d"]')
    try:
        settle_scene(page, "loading: the 3D scene", tubes=True)
    except RuntimeError as e:
        return bad + [str(e)]
    page.wait_for_timeout(300)
    frames = page.evaluate("() => { window.__sampling = false; return window.__frames; }")
    page.unroute("**/assets/dist/evmi2130x*")
    if not held:
        bad.append("loading: none of the last part's files was asked for while the scene loaded, so nothing was held back")
    with_cables = [f for f in frames if f["tubes"] or f["straps"]]
    if len(frames) < 10 or not with_cables or not any(f["straps"] for f in frames):
        return bad + [f"loading: {len(frames)} frames sampled, {len(with_cables)} with cables, {sum(1 for f in frames if f['straps'])} with straps: the load was not measured"]
    final = frames[-1]
    # NO FRAME HAS A CABLE OR A STRAP WITHOUT THE MANAGER'S BODY...
    bare = [f for f in with_cables if not f["body"]]
    if bare:
        bad.append(f"loading: {len(bare)} of {len(with_cables)} frames with cables have no body for the vertical manager, the first at {bare[0]['t']} ms: {bare[0]}")
    # ...AND THE BODY IS WHERE THE MANAGER STANDS from its first frame, never at the middle of the rack.
    # (measured over the frames it stands in while the part after it is still waiting for its files: a long window)
    alone = [f for f in frames if f["device"] and f["body"] and not f["next"]]
    if len(alone) < 5:
        bad.append(f"loading: the manager stood in only {len(alone)} frames before the part after it was mounted, so where it stood then was not measured")
    astray = [f for f in frames if f["device"] and f["body"] and abs(f["x"] - final["x"]) > 0.5]
    if astray or abs(final["x"]) < 200:
        bad.append(f"loading: the manager's body is drawn at x {sorted({f['x'] for f in astray})} in {len(astray)} frames before it stands at {final['x']}")
    # a strap goes on with its cables or after them, never before
    if any(f["straps"] and not f["tubes"] for f in frames):
        bad.append("loading: a frame has straps and no cable")
    boxed = [f for f in frames if f["standIn"]]
    if not boxed:
        bad.append("loading: the manager never stood as a plain box, so the frames before its detail were not what was measured")
    if final["standIn"] or final["body"] < 50:
        bad.append(f"loading: the settled scene has {final['standIn']} stand-in boxes and {final['body']} meshes of the manager")
    left = page.evaluate("""() => { const out = []; window.__rack.scene().three.scene.traverse(o => {
      if (o.userData?.standIn || /^standin/.test(o.name || '')) out.push(o.name || 'a stand-in');
      // a sheet part's own box is not drawn once its detail stands: every material of it is hidden again
      if (o.isMesh && o.parent?.name === 'device-z1' && o.geometry.type === 'BoxGeometry' && o.geometry.parameters.height > 1800 && [].concat(o.material).some(m => m.visible)) out.push('the box of device-z1'); });
      return out; }""")
    if left:
        bad.append(f"loading: stand-in boxes are still in the settled scene (a download would carry them): {left}")
    first_body = next((f["t"] for f in frames if f["body"]), None)
    first_cable, first_detail = with_cables[0]["t"], next((f["t"] for f in frames if f["body"] and not f["standIn"]), None)
    print(f"[check_rack_3d_loading] {len(frames)} frames in {time.time() - t0:.1f} s, {len(held)} of the last part's files held, the manager alone in {len(alone)} frames; its box from {first_body} ms, cables from {first_cable} ms, "
          f"its detail from {first_detail} ms; {len(boxed)} frames with the box, {sum(1 for f in with_cables if f['standIn'])} of them with cables")
    # A PART WHOSE FILES DO NOT LOAD stays a box, marked as one that is not coming, and the page says so, once.
    # (on a page loaded afresh: a drawing this page has read once is not asked for again)
    page.click('#mode [data-mode="2d"]')
    page.evaluate("() => window.__rack.flush()")
    page.reload(wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    wait_fn(page, "failed: the panes again", "() => document.querySelector('#paneFront svg [data-cables] [data-cable-id]') && window.__rack.routesCurrent().current")
    page.route("**/assets/dist/cmv-sfd42u9w*", lambda route: route.abort())
    said = "() => (document.getElementById('side').textContent.match(/duct-1 could not be drawn in detail\\./g) || []).length"
    failed = """() => { const g = window.__rack.scene()?.three.scene.getObjectByName('device-z1'), b = g?.children[0];
      return !!b && b.userData.standIn === 'failed' && [].concat(b.material).some(m => m.visible); }"""
    try:
        page.click('#mode [data-mode="3d"]')
        wait_fn(page, "failed: the manager's box marked as not coming", failed, timeout=READY_3D_MS)
        wait_fn(page, "failed: the page says the manager could not be drawn in detail", f"() => ({said})() === 1", timeout=15000)
        st = page.evaluate("""() => { const T = window.__rack.scene().three.scene; let tubes = 0; T.getObjectByName('patch-cables')?.traverse(o => { if (o.isMesh) tubes++; }); return {tubes}; }""")
        if not st["tubes"]:
            bad.append("failed: the cables were not hung in a scene whose manager could not be drawn in detail")
        # IT STAYS SAID WHILE THE PART IS STILL A BOX: through a redraw of the side panel (a cable pinned and let go)...
        page.click('#cableList [data-cable-row="c4"]')
        wait_fn(page, "failed: c4 pinned", "() => document.querySelector('#cableRow-c4')?.getAttribute('aria-pressed') === 'true'")
        page.click('#cableList [data-cable-row="c4"]')
        wait_fn(page, "failed: c4 let go", "() => !document.querySelector('#cableList [aria-pressed=\"true\"]')")
        if page.evaluate(said) != 1:
            bad.append(f"failed: after a redraw of the panel the page says it {page.evaluate(said)} times, expected once")
        # ...and on a second build of the scene, where the part fails again: said, and said once
        old = page.evaluate_handle("() => window.__rack.scene()")
        page.click('#mode [data-mode="2d"]')
        wait_fn(page, "failed: 2D says nothing of it", f"() => ({said})() === 0")
        page.click('#mode [data-mode="3d"]')
        page.wait_for_function("s => { const n = window.__rack.scene(); return !!n && n !== s; }", arg=old, timeout=READY_3D_MS)
        wait_fn(page, "failed: the second scene's box marked as not coming", failed, timeout=READY_3D_MS)
        wait_fn(page, "failed: the second scene says it too", f"() => ({said})() >= 1", timeout=15000)
        page.wait_for_timeout(600)
        if page.evaluate(said) != 1:
            bad.append(f"failed: on a second build the page says it {page.evaluate(said)} times, expected once")
    except RuntimeError as e:
        bad.append(str(e))
    finally:
        page.unroute("**/assets/dist/cmv-sfd42u9w*")
    return bad



# ── portrayal-site#190: a strap's size on a pane ─────────────────────────
# Every strap of b1 on the front pane, measured off the drawing itself: its
# bar at scale and its least bar (pane mm), which way it lies, and the pack it
# is across - each member's own stroke where it crosses the strap's line, so
# how wide the members are there square across the run, and which way they run.
STRAP_SIZE_JS = """() => {
  const svg = document.querySelector('#paneFront > svg'), vb = svg.viewBox.baseVal, scale = svg.getBoundingClientRect().width / vb.width;
  const strokes = {};
  for (const g of svg.querySelectorAll('[data-cables] [data-cable][data-cable-id]')) {
    const p = g.querySelector('path:last-of-type'), L = p.getTotalLength(), pts = [];
    for (let t = 0; t <= L; t += 0.25) { const q = p.getPointAtLength(t); pts.push([q.x, q.y]); }
    strokes[g.dataset.cableId] = pts;
  }
  const ends = l => ['x1', 'y1', 'x2', 'y2'].map(k => +l.getAttribute(k));
  return {scale, straps: [...svg.querySelectorAll('[data-strap="b1"]')].map(g => {
    const core = g.querySelector('line[data-strap-part="core"]:not([data-strap-least])'), least = g.querySelector('line[data-strap-part="core"][data-strap-least]');
    const rim = g.querySelector('line[data-strap-part="rim"][data-strap-least]');
    const [x1, y1, x2, y2] = ends(core), len = Math.hypot(x2 - x1, y2 - y1), n = [(x2 - x1) / len, (y2 - y1) / len], d = [-n[1], n[0]], c = [(x1 + x2) / 2, (y1 + y2) / 2];
    const across = [], runs = [];
    for (const id of g.dataset.members.split(' ')) {
      const pts = strokes[id] ?? [];
      let best = null;
      pts.forEach((q, k) => { const along = (q[0] - c[0]) * d[0] + (q[1] - c[1]) * d[1], a = (q[0] - c[0]) * n[0] + (q[1] - c[1]) * n[1];
        if (Math.abs(a) < 40 && (best == null || Math.abs(along) < Math.abs(best.along))) best = {along, a, k}; });
      if (!best || Math.abs(best.along) > 0.3) continue;
      across.push(best.a);
      const p0 = pts[Math.max(0, best.k - 8)], p1 = pts[Math.min(pts.length - 1, best.k + 8)], r = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]) || 1;
      runs.push(Math.abs(((p1[0] - p0[0]) * n[0] + (p1[1] - p0[1]) * n[1]) / r));
    }
    const l2 = ends(least), r2 = ends(rim), lenOf = e => Math.hypot(e[2] - e[0], e[3] - e[1]);
    return {len, least: lenOf(l2), rim: lenOf(r2), rimTrue: lenOf(ends(g.querySelector('line[data-strap-part="rim"]:not([data-strap-least])'))), slant: Math.round(Math.atan2(Math.abs(n[0]), Math.abs(n[1])) * 180 / Math.PI), at: (() => { const m = core.getScreenCTM(), q = new DOMPoint(c[0], c[1]).matrixTransform(m); return [q.x, q.y]; })(),
            riders: across.length, pack: across.length ? Math.max(...across) - Math.min(...across) + 3 : null, mid: across.length ? (Math.max(...across) + Math.min(...across)) / 2 : null,
            skew: runs.length ? Math.max(...runs) : null, noted: g.dataset.strapPack == null ? null : +g.dataset.strapPack, diameter: +g.dataset.pack,
            cap: least.getAttribute('stroke-linecap'), thick: [core, least].map(l => [+l.getAttribute('stroke-width'), l.getAttribute('vector-effect')])};
  })};
}"""


# Every WebGL context the page makes, whether it was a probe (never in the
# document) or a renderer's, and each one lost or restored; and each
# loseContext call, with whether its context was already lost (which the browser
# reports as "loseContext: context lost").
GL_COUNTER_JS = """(() => {
  const M = window.__gl = {made: [], lost: [], restored: [], lose: []};
  const get = HTMLCanvasElement.prototype.getContext;
  HTMLCanvasElement.prototype.getContext = function (kind, ...rest) {
    const known = this.__glId != null, c = get.call(this, kind, ...rest);
    if (c && /webgl/.test(kind) && !known) {
      const id = this.__glId = M.made.length, rec = {id, attached: null};
      M.made.push(rec);
      setTimeout(() => { rec.attached = this.isConnected; });
      this.addEventListener('webglcontextlost', () => M.lost.push(id));
      this.addEventListener('webglcontextrestored', () => M.restored.push(id));
    }
    return c;
  };
  for (const P of [WebGLRenderingContext.prototype, WebGL2RenderingContext.prototype]) {
    const ext = P.getExtension;
    P.getExtension = function (name) {
      const x = ext.call(this, name);
      if (x && name === 'WEBGL_lose_context' && !x.__counted) {
        const gl = this, lose = x.loseContext.bind(x);
        x.loseContext = () => { M.lose.push({id: gl.canvas.__glId ?? null, already: gl.isContextLost()}); return lose(); };
        x.__counted = true;
      }
      return x;
    };
  }
})();"""
# The scene's textures and the device materials it shares: how many textures, the longest side of any, and for
# each plain model mounted more than once whether every mount draws with one set of body materials.
SCENE_SHARING_JS = """() => {
  const s = window.__rack.scene(), seen = new Set(), bodies = new Map();
  let longest = 0;
  s.three.scene.traverse(o => {
    for (const m of [].concat(o.material || [])) for (const k of ['map', 'alphaMap']) {
      const t = m?.[k]; if (!t || seen.has(t)) continue;
      seen.add(t); longest = Math.max(longest, t.image?.width ?? 0, t.image?.height ?? 0);
    }
  });
  const r0 = window.__rack.doc().racks[0], ref = new Map([...r0.items, ...(r0.zeroU ?? [])].map(i => [i.id, i.ref]));
  for (const g of s.three.scene.children) {
    if (!g.name?.startsWith('device-')) continue;
    const r = ref.get(g.name.slice(7)); if (!r) continue;
    (bodies.get(r) ?? bodies.set(r, new Set()).get(r)).add(g.children[0]?.material);
  }
  return {textures: seen.size, longest, gl: s.three.renderer.info.memory.textures,
          sets: Object.fromEntries([...bodies].map(([r, m]) => [r, m.size]))};
}"""


@extra("rack.html: a large rack is built in 3D once, with one renderer, no context lost and no page error; its plain parts share their materials and no face texture is over 4096 px; picking a bundle or a cable type keeps the scene and makes no context; and a lost context stops the scene, says so, and builds it again once when the context comes back, never deleting into the new one (S-0043)")
def check_rack_3d_large_once(page, base):
    bad, said = [], []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.on("console", lambda m: said.append(m.text))
    page.add_init_script(GL_COUNTER_JS)
    page.set_viewport_size({"width": 1400, "height": 900})
    fixture = ring_rack_fixture()
    page.goto(f"{base}/rack.html?probe=1", wait_until="load")
    page.wait_for_function("() => window.__rack && window.__rack.ready", timeout=READY_MS)
    page.evaluate("() => window.__rack.ready")
    if webgl_trouble(page):
        print("[check_rack_3d_large_once] WebGL unavailable - not exercised")
        return bad
    page.click('#mode [data-mode="2d"]')
    page.set_input_files("#openFile", files=[{"name": "ring.rack.json", "mimeType": "application/json", "buffer": json.dumps(fixture).encode()}])
    wait_fn(page, "large: opened and drawn with its routes",
            "() => window.__rack.doc().racks[0].name === 'Ring rack' && window.__rack.routesCurrent().current", timeout=300000)
    page.evaluate("() => { const M = window.__gl; M.made.length = 0; M.lost.length = 0; M.restored.length = 0; M.lose.length = 0; }")
    t0 = time.time()
    page.click('#mode [data-mode="3d"]')
    try:
        settle_scene(page, "large: the 3D scene", tubes=True)
    except RuntimeError as e:
        return bad + [str(e)]
    took = time.time() - t0
    gl = page.evaluate("() => JSON.parse(JSON.stringify(window.__gl))")
    renderers = [c for c in gl["made"] if c["attached"]]
    if len(renderers) != 1:
        bad.append(f"large: {len(renderers)} renderers made while the scene loaded, expected one (contexts: {gl['made']})")
    probes_lost = [c["id"] for c in gl["made"] if not c["attached"]]
    if sorted(gl["lost"]) != sorted(probes_lost) or gl["restored"] or any(x["already"] for x in gl["lose"]):
        bad.append(f"large: contexts lost {gl['lost']} (only the probes {probes_lost} should be), restored {gl['restored']}, loseContext calls {gl['lose']}")
    share = page.evaluate(SCENE_SHARING_JS)
    if share["longest"] > 4096:
        bad.append(f"large: a face texture {share['longest']} px long, over 4096")
    # (each of these is mounted more than once in the fixture, with nothing done to it)
    for ref in ("fhd-cmp5dr", "cmv-sfd42u9w", "pdumv20hvnetlx"):
        if share["sets"].get(ref) != 1:
            bad.append(f"large: the plain {ref} mounts draw with {share['sets'].get(ref)} sets of body materials, expected one shared set")
    print(f"[check_rack_3d_large_once] built in {took:.1f} s with {len(renderers)} renderer, {len(gl['made'])} contexts in all; "
          f"{share['textures']} textures in the scene ({share['gl']} on the GPU), the longest {share['longest']} px; material sets {share['sets']}")
    # A BUNDLE, THEN A CABLE TYPE, picked and put down twice: the scene stays, no context is made.
    scene_was = page.evaluate("() => { window.__was = window.__rack.scene(); return window.__gl.made.length; }")
    idle = "() => window.__rack.idle()"
    # (each control clicked as a reader's click reaches it; where it sits in a long side panel is not what is checked)
    def press(sel):
        wait_fn(page, f"large: {sel} to press", "s => document.querySelector(s)", arg=sel)
        page.evaluate("s => document.querySelector(s).click()", sel)
    rows = page.evaluate("() => [...document.querySelectorAll('[data-bundle-row]')].map(b => b.dataset.bundleRow)")
    if len(rows) < 2:
        return bad + [f"large: the side panel in 3D lists {len(rows)} bundles ({rows}); expected the fixture's four"]
    for turn in range(2):
        press(f'[data-bundle-row="{rows[0] if turn == 0 else rows[-1]}"]')
        wait_fn(page, "large: the bundle's panel", "() => document.querySelector('#bDone')")
        wait_fn(page, "large: idle after the bundle", idle)
        press("#bDone")
        wait_fn(page, "large: the list again", "() => document.querySelector('[data-filter-row] button')")
        press('[data-filter-row] button')
        wait_fn(page, "large: idle after the filter", idle)
        press('[data-filter-row] button[aria-pressed="true"]')
        wait_fn(page, "large: idle after the filter is off", idle)
    page.wait_for_timeout(800)   # past the page's 300 ms rebuild debounce
    after = page.evaluate("() => ({same: window.__rack.scene() === window.__was, made: window.__gl.made.length})")
    if not after["same"] or after["made"] != scene_was:
        bad.append(f"large: picking a bundle and a cable type rebuilt the scene ({not after['same']}) or made {after['made'] - scene_was} contexts")
    # A LOST CONTEXT: the loop stops, the stage says so; the context back, the scene is built again, once.
    said.clear()
    page.evaluate("() => { window.__lostExt = window.__rack.scene().three.renderer.getContext().getExtension('WEBGL_lose_context'); window.__lostExt.loseContext(); }")
    wait_fn(page, "lost: the notice", "() => document.querySelector('#lost3d #lost3dRebuild')")
    lost = page.evaluate("() => ({running: window.__rack.scene().running(), lost: window.__rack.scene().contextLost()})")
    if lost["running"] or not lost["lost"]:
        bad.append(f"lost: the scene after its context was lost: {lost}; expected stopped and lost")
    page.evaluate("() => { window.__was = window.__rack.scene(); window.__lostExt.restoreContext(); }")
    try:
        settle_scene(page, "lost: the scene built again", tubes=True)
    except RuntimeError as e:
        return bad + [str(e)]
    again = page.evaluate("() => ({fresh: window.__rack.scene() !== window.__was, notice: !!document.querySelector('#lost3d')})")
    if not again["fresh"] or again["notice"]:
        bad.append(f"lost: after the context came back: {again}; expected a new scene and the notice gone")
    # ...and only once: lost again, it waits for the button.
    page.evaluate("() => { const x = window.__rack.scene().three.renderer.getContext().getExtension('WEBGL_lose_context'); window.__was = window.__rack.scene(); x.loseContext(); setTimeout(() => x.restoreContext(), 300); }")
    wait_fn(page, "lost again: the notice", "() => document.querySelector('#lost3d #lost3dRebuild')")
    page.wait_for_timeout(1500)
    if page.evaluate("() => window.__rack.scene() !== window.__was || !document.querySelector('#lost3d')"):
        bad.append("lost again: the scene was built again by itself a second time; expected the notice and its button to stay")
    # ...and the button builds it, also from a context the browser has not given back: the lost one is let go quietly.
    page.evaluate("() => { const x = window.__rack.scene().three.renderer.getContext().getExtension('WEBGL_lose_context'); window.__was = window.__rack.scene(); x.loseContext(); }")
    wait_fn(page, "lost, no restore: the notice", "() => document.querySelector('#lost3d #lost3dRebuild')")
    press("#lost3dRebuild")
    try:
        settle_scene(page, "lost, no restore: the scene built from the button", tubes=True)
    except RuntimeError as e:
        return bad + [str(e)]
    if page.evaluate("() => window.__rack.scene() === window.__was || !!document.querySelector('#lost3d')"):
        bad.append("lost, no restore: the button did not build a new scene, or the notice stayed")
    noisy = [t for t in said if "does not belong to this context" in t or "loseContext: context lost" in t or "reading 'trim'" in t]
    if noisy:
        bad.append(f"lost: the console said {len(noisy)} GL errors, the first: {noisy[0]}")
    return bad


@extra("rack.html: a strap is as long as its pack is wide where it sits - the members there, square across the run, and a small margin, on a diagonal stretch as on a straight one; it lies square across its run; at Fit on a 42U rack it is never under the least size along the run, and across it only up to twice its pack; at 300% it is its true size; and the sheet's straps are the ones they were (#190)")
def check_rack_strap_size(page, base):
    bad = []
    page.on("pageerror", lambda e: bad.append(f"uncaught: {e}"))
    page.set_viewport_size({"width": 1600, "height": 1000})
    open_front_fixture(page, base, PACK_FIXTURE)
    # A trunk with a slanted stretch, as a lacer's ring to a lane a few units up is: out of mgr-1's first ring,
    # onto the left lane at U23, up it to U28. A strap every 2 in puts several on the slant and several on the lane.
    res = page.evaluate("""() => window.__rack.bundleCommand({op: 'bundle.create', cables: ['c1', 'c2', 'c3'], label: 'pack',
      route: [{item: 'i2', via: 'guide-1'}, {lane: 'left-front', ru: 23}, {lane: 'left-front', ru: 28}], straps: {every: {value: 2, unit: 'in'}}})""")
    if res.get("error"):
        return bad + [f"create: refused: {res['error']}"]
    page.wait_for_function("() => document.querySelectorAll('#paneFront [data-strap=\"b1\"]').length >= 6 && window.__rack.routesCurrent().current", timeout=READY_MS)
    page.wait_for_timeout(400)
    page.click('#covers [data-covers-set="off"]')      # the lane is inside a duct: its cover would tint the straps on the page
    page.click("#zoomFit")
    page.wait_for_timeout(500)
    park_mouse(page)
    fit = page.evaluate(STRAP_SIZE_JS)
    measured = [s for s in fit["straps"] if s["riders"] >= 2]
    slanted = [s for s in measured if 10 <= s["slant"] <= 80]
    if len(measured) < 4 or not slanted or not [s for s in measured if s["slant"] > 80 or s["slant"] < 10]:
        return bad + [f"fixture: {len(fit['straps'])} straps, {len(measured)} with two or more members measured across them, {len(slanted)} of those on a slant: straight and slanted stretches were not both measured"]
    if fit["scale"] * 10 >= 6:
        bad.append(f"fixture: at Fit a 10 mm strap is {fit['scale'] * 10:.1f} px, so the least size was not what was measured")
    worst = 0
    for s in measured:
        where = f"strap at {s['slant']} degrees, {s['riders']} members"
        # ACROSS THE PACK: the members there, measured on their own strokes, and 2 mm each side.
        # (S-0040: 1 mm each side on the page, strap-size.js PAGE_STRAP, not the 2 mm of the paper)
        if not (s["pack"] + 2 - 1.2 <= s["len"] <= s["pack"] + 2 + 1.2):
            bad.append(f"{where}: its bar is {s['len']:.1f} mm for a pack {s['pack']:.1f} mm wide there (the bundle's diameter is {s['diameter']}); expected the pack and 1 mm each side")
        if abs(s["mid"]) > 1.2:
            bad.append(f"{where}: its bar is {s['mid']:.1f} mm off the middle of its pack")
        # SQUARE ACROSS THE RUN: the members' own strokes cross it at a right angle (within 15 degrees).
        if s["skew"] > 0.26:
            bad.append(f"{where}: it is not square across its run (its members run {math.degrees(math.asin(min(1, s['skew']))):.0f} degrees off square)")
        # THE LEAST SIZE, across: up to the least pixels, and never past twice the pack.
        pack = s["noted"]
        if pack is None or abs(pack - s["pack"]) > 1.2:
            bad.append(f"{where}: the page noted a pack of {pack} mm, measured {s['pack']:.1f}")
            continue
        # (the whole bar, its rim included: 2.0 packs at the most, unless the pack and its margins are more)
        # (S-0040: on the page the least is 5 px, a bar is 1.5 packs at the most, and the rim adds a pixel)
        px1, most_mm = 1 / fit["scale"], max(s["len"], 1.5 * pack)
        want = max(s["len"], min(5 * px1, 1.5 * pack - px1))
        if abs(s["least"] - want) > 0.05 or s["cap"] != "butt":
            bad.append(f"{where}: at Fit its least bar is {s['least']:.1f} mm ({s['least'] * fit['scale']:.1f} px, cap {s['cap']}) for a {pack:.1f} mm pack; expected {want:.1f} mm")
        if max(s["rim"], s["rimTrue"], s["least"]) > most_mm + 0.05:
            bad.append(f"{where}: with its rim the bar is {max(s['rim'], s['rimTrue']):.1f} mm, {max(s['rim'], s['rimTrue']) / pack:.2f} times its {pack:.1f} mm pack; expected no more than {most_mm / pack:.2f}")
        if abs(s["rim"] - min(s["least"] + px1, most_mm)) > 0.05 or abs(s["rimTrue"] - min(s["len"] + px1, most_mm)) > 0.05:
            bad.append(f"{where}: its rims are {s['rimTrue']:.1f} and {s['rim']:.1f} mm long round bars of {s['len']:.1f} and {s['least']:.1f}; expected a pixel past each end where twice the pack leaves room")
        worst = max(worst, max(s["rim"], s["rimTrue"]) / pack)
        # ALONG THE RUN: 10 mm at scale, and the least bar's own non-scaling 7 px.
        if s["thick"] != [[6, None], [5, "non-scaling-stroke"]]:
            bad.append(f"{where}: along the run its bars are {s['thick']}; expected 6 mm at scale (0.6 of 10) and 5 px at the least")
    # on the composited page at Fit, a strap on the straight run is its own colour for the least size along the run
    # and for no more than twice its pack (and the rim) across it
    up = max((s for s in measured if s["slant"] > 80 or s["slant"] < 10), key=lambda s: s["riders"])
    core = rgb_of(page.evaluate("() => getComputedStyle(document.querySelector('#paneFront [data-strap=\"b1\"] line[data-strap-part=\"core\"]')).stroke"))
    w, h, px = png_pixels(page.screenshot())
    ext = strap_extent(px, w, h, up["at"], core)
    along, across_px = (ext[1], ext[0]) if up["slant"] > 45 else (ext[0], ext[1])
    most = max(up["len"], 1.5 * up["noted"]) * fit["scale"] + 1
    if along < 4 or across_px > most:
        bad.append(f"at Fit: a strap on the straight run is {along} px along the run and {across_px} px across it on the page; expected 4 or more along, and no more than {most:.1f} across")
    print(f"[check_rack_strap_size] at Fit ({fit['scale']:.2f} px a mm): {len(measured)} straps measured, {len(slanted)} on a slant; bars {sorted({round(s['len'], 1) for s in measured})} mm for packs "
          f"{sorted({round(s['pack'], 1) for s in measured})} mm (diameter {measured[0]['diameter']}); on the page {along} px along the run, {across_px} across; the longest bar, rim included, is {worst:.2f} packs")
    # AT 300% a strap is its true size: the least bar is no longer than the bar at scale.
    for _ in range(40):
        label = page.inner_text("#zoomLevel")
        if label != "Fit" and int(label.rstrip("%")) >= 300:
            break
        page.click("#zoomIn")
        page.wait_for_timeout(80)
    page.wait_for_timeout(300)
    big = page.evaluate(STRAP_SIZE_JS)
    if big["scale"] < 2.5 * fit["scale"]:
        bad.append(f"300%: the pane is at {big['scale']:.2f} px a mm, {big['scale'] / fit['scale']:.1f} times Fit")
    for s, was in zip(big["straps"], fit["straps"]):
        if abs(s["len"] - was["len"]) > 0.01:
            bad.append(f"300%: a strap's bar at scale changed with the zoom: {was['len']:.2f} to {s['len']:.2f} mm")
        if s["least"] > s["len"] + 0.01 and s["least"] * big["scale"] > 7.01:
            bad.append(f"300%: a strap's least bar is {s['least'] * big['scale']:.1f} px, past its true {s['len'] * big['scale']:.1f} px and the least size")
    # THE SHEET'S STRAPS ARE THE ONES THEY WERE: each as long as its bundle's diameter there and 4 mm, and nothing of the page's.
    sheet = page.evaluate("""async () => { const X = await import('/site/rack/exports.js'), C = await import('/vendor/rack/catalog.js');
      return (await X.sheetSvg(window.__rack.doc().racks[0], (await C.loadCatalog('/assets/dist/')).chassisOf, {faces: ['front']})).data; }""")
    ns = "{http://www.w3.org/2000/svg}"
    bars = [g for g in ET.fromstring(sheet.encode("utf-8")).iter(f"{ns}g") if g.get("data-strap") == "b1"]
    odd = []
    for g in bars:
        for l in g:
            ln = math.hypot(float(l.get("x2")) - float(l.get("x1")), float(l.get("y2")) - float(l.get("y1")))
            if abs(ln - (float(g.get("data-pack")) + 4)) > 0.01 or (l.get("data-strap-least") is not None and l.get("stroke-linecap") != "square"):
                odd.append(round(ln, 2))
    if len(bars) != len(fit["straps"]) or odd or "data-strap-pack" in sheet:
        bad.append(f"sheet: {len(bars)} straps for the pane's {len(fit['straps'])}, {len(odd)} lines not their diameter and 4 mm ({odd[:4]}), page's note in the file: {'data-strap-pack' in sheet}")
    return bad


# THE SHARDS. On CI's two CPUs the whole pass had grown to twenty minutes, most
# of it software-rendered 3D, and no check waits on another: each opens its own
# page. So CI runs it as n jobs side by side, `--shard i/n`, and this is how
# the work is dealt out.
#
# A UNIT is one thing main() does, named: a page of PAGES, one of the blocks
# hand-wired into main() (FIXED_UNITS), a registered @extra by its function
# name, or the marks harness. units() is built from the same lists main() walks,
# so a page or an @extra added to this file is in a shard without anyone
# remembering to put it there.
#
# NO UNIT CAN BE SILENTLY SKIPPED, and three things hold that:
#   - shard_plan() deals out units(), all of them, each to exactly one shard;
#     check-contract.py asserts that for every n it might be asked for, and
#     that the workflow's matrix asks for every shard of the n it names.
#   - want() refuses a name that is not a unit, so a guard in main() cannot
#     quietly be False in every shard.
#   - a block added to main() with no want() around it runs in EVERY shard:
#     wasteful, and never skipped.
